static id<MTLDevice> g_dev;
// g_comp4: the host's one MTL4Compiler, made in mtl_init before any pipeline (mtl_comp4): every pipeline is built through it, the host's own (host_cps, host_rps), MetalFX's
// scalers and the game's (pso_build, cps_new, mtk_build); there is no MTLDevice pipeline path. Made only when it is nil, so a test can put a compiler of its own in first
// (t_pso_pending's fake one). The archive's captures go through the current flush period's own compiler (ArchEpoch)
static id<MTL4Compiler> g_comp4;
id<MTL4Compiler> mtl_comp4(void) {
    static os_unfair_lock lk = OS_UNFAIR_LOCK_INIT;
    id<MTL4Compiler> c = g_comp4;
    if (c || !g_dev) return c;
    os_unfair_lock_lock(&lk);   // a test that sets g_dev itself and skips mtl_init makes it at its first use, on whichever thread that is
    if (!g_comp4) {
        NSError *ce = nil; g_comp4 = [g_dev newCompilerWithDescriptor:[MTL4CompilerDescriptor new] error:&ce];
        if (!g_comp4) MLOG("[RED] the Metal device %s made no Metal 4 compiler: %s", g_dev.name.UTF8String, ce ? ce.localizedDescription.UTF8String : "no error given");
    }
    c = g_comp4;
    os_unfair_lock_unlock(&lk);
    return c;
}
// The shaders the host writes itself (built-in kernels, clears, copies, index conversions, geometry packing, the present, the diagnostics DM_NVN_HILITE, DM_NVN_MAGSCAN and
// DM_NVN_TEXDUMP: dm/gfx/msl), compiled when the host is built and loaded by name (host_msl_lib), so none is compiled at run time
static id<MTLLibrary> host_lib(const char *name, NSError **e) { return host_msl_lib(g_dev, name, e); }
// The host's own pipelines, whole through g_comp4 (host_msl_cps / host_msl_rps: no archive, no base; fs nil: the empty fragment function)
// Every compile that is not an archive capture reports the compiler service's death (arch_died) on its way out, even when its caller ignores the error (upstream NXNative
// 9bd8bb386): the service takes every compile it held down, the current flush period's captures among them, so that period must not be written. Archive lookups do not compile
static void arch_died(NSError *e);
static id compile_done(id result, NSError *error, NSError **out) {
    if (!result) { arch_died(error); if (out) *out = error; }
    return result;
}
static id<MTLRenderPipelineState> plain_rps(id<MTL4Compiler> c, MTL4PipelineDescriptor *d, NSError **out) {
    NSError *e = nil; id ps = [c newRenderPipelineStateWithDescriptor:d compilerTaskOptions:nil error:&e]; return compile_done(ps, e, out);
}
static id<MTLComputePipelineState> plain_cps(id<MTL4Compiler> c, MTL4ComputePipelineDescriptor *d, NSError **out) {
    NSError *e = nil; id ps = [c newComputePipelineStateWithDescriptor:d compilerTaskOptions:nil error:&e]; return compile_done(ps, e, out);
}
static id<MTLRenderPipelineState> plain_spec(id<MTL4Compiler> c, MTL4RenderPipelineDescriptor *d, id<MTLRenderPipelineState> base, NSError **out) {
    NSError *e = nil; id ps = [c newRenderPipelineStateBySpecializationWithDescriptor:d pipeline:base error:&e]; return compile_done(ps, e, out);
}
static id<MTLComputePipelineState> host_cps(id<MTLLibrary> lib, NSString *name, MTLFunctionConstantValues *cv, NSError **out) {
    NSError *e = nil; id ps = host_msl_cps(mtl_comp4(), lib, name, cv, &e); return compile_done(ps, e, out);
}
static id<MTLRenderPipelineState> host_rps(id<MTLLibrary> lib, NSString *vs, NSString *fs, int ncol, const MTLPixelFormat *cf, const MTLColorWriteMask *wm, NSUInteger samples, NSError **out) {
    NSError *e = nil; id ps = host_msl_rps(mtl_comp4(), lib, vs, fs, ncol, cf, wm, samples, &e); return compile_done(ps, e, out);
}
static NSMutableArray *g_l3_gpu_leaks;
static int g_nvn_deswz_gpu;
static id<MTL4CommandQueue> g_q4;
static dispatch_queue_t g_feedback_q;
// The GPU's busy time, for the power line's GPU ms/s (hle_nvn.c power_line): every command buffer committed to the Metal 4 queue adds its GPU start-to-end interval, overlaps
// counted once (nvn_gpu_diag.h gd_busy_add). iOS leaves task_power_info's gpu_energy.task_gpu_utilisation at 0 for an app, so before this every iPhone power line read
// 'GPU 0.0 ms/s'. Added to by the feedback handlers alone, which all run on g_feedback_q, a serial queue: the one writer gd_busy needs. The submit thread does nothing more for
// it, but for giving the command buffer of the game's work that had no handler one: the indirect-count wait's (mdi_wait). Counted: the game's submissions and their
// segments, the indirect-count waits (mdi_wait), upload batches, one-off command buffers (readbacks, screenshots, drains), the display presents and offscreen presents. Not counted: the present snapshot copy (one texture copy a frame while present snapshots are on, DM_PRESENT_SNAP or Frame buffering, committed with no handler),
// and the iOS render server's own GPU work (UIKit over the layer), which is another process's. A command buffer's interval includes its waits at queue barriers, so this is an
// upper bound of the GPU's work while it ran; the timing line's GPU (mtl_gpu_ms) is another measure, per frame, of the game's command buffers alone and summed, not merged
static gd_busy g_gpu_busy;
// Seconds on the CACurrentMediaTime base; g_feedback_q only. An interval ending after the handler runs (beyond a second) or longer than a minute is a bad time, not GPU work, and
// is left out (gd_busy_add_checked): counted, its end would hide every later interval for the rest of the run
// Valid completed GPU interval from Metal feedback: finite, positive, ordered, and already elapsed on Metal's clock.
// Missing start times (0, Big Brain Academy) or faulted command buffers (unwritten UINT64_MAX tick sentinel ≈ 6.15e9 s
// on Apple Silicon's 125/3 timebase) would otherwise poison frame/upload durations, spans, mtl_gpu_done, and integer casts.
static inline int gpu_time_valid(double g0, double g1) {
    return isfinite(g0) && isfinite(g1) && g0 > 0 && g1 > g0 && g1 <= CACurrentMediaTime();
}
static inline void gpu_busy_note(double g0, double g1) { if (gpu_time_valid(g0, g1)) gd_busy_add_checked(&g_gpu_busy, (uint64_t)(g0 * 1e9), (uint64_t)(g1 * 1e9), (uint64_t)(CACurrentMediaTime() * 1e9)); }
uint64_t mtl_gpu_busy_ns(void) { return gd_busy_ns(&g_gpu_busy); }   // the Metal 4 queue's GPU busy time so far, in ns (hle_nvn.c power_line, any thread)
static _Atomic uint32_t g_present_qos;
#define ALLOC_MAX 8
// The most submissions committed and not yet completed: mtl_sub_commit waits for the GPU before it commits past them (the post ring, POST_RING). It sizes what is held per
// submission in flight (POST_RING, VIS_RING). Upstream sizes it from the allocator bound, ALLOC_MAX * ALLOC_SHARE (512); here the post ring's wait keeps 128
enum { SUB_FLIGHT_MAX = 128 };
static id<MTL4CommandAllocator> g_alloc4[ALLOC_MAX]; static int g_alloc_n, g_alloc_cur;   // Command allocator pool of the main submission: at start pick one the GPU has finished with, create a new one if there is none (wait only at the cap)
// Upload batch slots (adapted from MacNativeGames 6ecb27c1 (MIT)): each upload batch takes the next slot in rotation, and up_begin waits until that slot's previous batch has come
// back. With 3 slots the submit thread can be at most 3 batches ahead of the GPU; a game that makes many new textures a frame, in several batches, then waits for a slot while the
// GPU idles (MacNativeGames measured Breath of the Wild 1.9.0 at about 6 ms a frame of such waits with 3, 0.0-0.2 ms with 8). g_up_nslots of UP_SLOTS_MAX rotate, decided once in
// mtl_init before any batch (up_slots_pick: DM_NVN_UP_SLOTS, else the profile's upload_slots, else 3) and fixed for the run, as up_seq_back maps a batch number to its slot by it.
// The waits show in DM_NVN_WAITS=1's [waits] line as 'upload slot'
#define UP_SLOTS_MAX 8
enum { UP_SLOTS_MIN = 3 };
static id<MTL4CommandAllocator> g_up_alloc4[UP_SLOTS_MAX]; static unsigned g_up_nslots = UP_SLOTS_MIN;
// The slot count from the profile's value and DM_NVN_UP_SLOTS (env, NULL when unset): a whole number there wins, held to UP_SLOTS_MIN..UP_SLOTS_MAX; unset, empty or not a number,
// the profile's. *why says which, for the start line
static unsigned up_slots_pick(const char *env, long profile, const char **why) {
    long v = profile; *why = profile == UP_SLOTS_MIN ? "the default" : "game profile upload_slots";
    if (env && *env) { char *end; long e = strtol(env, &end, 10);
        if (end != env && !*end) { v = e; *why = e < UP_SLOTS_MIN || e > UP_SLOTS_MAX ? "DM_NVN_UP_SLOTS, held to 3 to 8" : "DM_NVN_UP_SLOTS"; }
        else *why = profile == UP_SLOTS_MIN ? "DM_NVN_UP_SLOTS is not a number, so the default" : "DM_NVN_UP_SLOTS is not a number, so game profile upload_slots"; }
    return (unsigned)(v < UP_SLOTS_MIN ? UP_SLOTS_MIN : v > UP_SLOTS_MAX ? UP_SLOTS_MAX : v);
}
