// DM_NVN_ALLOCPROF=2: command memory. Each main submission takes a fresh command allocator (an allocator keeps its high-water size across resets), so its size is what that submission
// encoded; its growth (in chunks of about 2 MB) is charged to the replayed operation that caused it
static uint64_t g_cm_op[64], g_cm_opn[64], g_cm_sub_n, g_cm_sub_sum, g_cm_sub_max, g_cm_last;
static int allocprof_level(void) { if (g_allocprof < 0) { const char *e = getenv("DM_NVN_ALLOCPROF"); g_allocprof = e ? (atoi(e) > 1 ? 2 : 1) : 0; } return g_allocprof; }
// Diagnostic only: inclusive wall/CPU time on the replay thread. No GPU waits
// are added, and no clocks are read when DM_NVN_CPUPROF is absent or zero.
typedef struct { uint64_t wall, cpu; } cp_stamp;
// Shared by the threads that encode (the replay thread, and the encode thread with DM_NVN_ENC_THREAD): the report runs on whichever thread reaches it first, and with per-thread
// counters it printed its heading alone (Ocarina's and Bananza's developer runs of 2026-11-18). Each phase's CPU time is the thread's own
static _Atomic uint64_t g_cp_wall[8], g_cp_cpu[8], g_cp_calls[8], g_cp_last;
static _Atomic uint64_t g_cp_geo_waited, g_cp_geo_safe;
static int cp_on(void) { static _Thread_local int on = -1; if (on < 0) { const char *e = getenv("DM_NVN_CPUPROF"); on = e && atoi(e); } return on; }
static cp_stamp cp_begin(void) {
    if (!cp_on()) return (cp_stamp){0};
    return (cp_stamp){clock_gettime_nsec_np(CLOCK_MONOTONIC_RAW), clock_gettime_nsec_np(CLOCK_THREAD_CPUTIME_ID)};
}
static void cp_end(int phase, cp_stamp start) {
    if (!start.wall) return;
    atomic_fetch_add_explicit(&g_cp_cpu[phase], clock_gettime_nsec_np(CLOCK_THREAD_CPUTIME_ID) - start.cpu, memory_order_relaxed);
    atomic_fetch_add_explicit(&g_cp_wall[phase], clock_gettime_nsec_np(CLOCK_MONOTONIC_RAW) - start.wall, memory_order_relaxed);
    atomic_fetch_add_explicit(&g_cp_calls[phase], 1, memory_order_relaxed);
}
static void cp_report(void) {
    if (!cp_on()) return;
    uint64_t now = clock_gettime_nsec_np(CLOCK_MONOTONIC_RAW), last = atomic_load_explicit(&g_cp_last, memory_order_relaxed);
    if (!last) { atomic_compare_exchange_strong(&g_cp_last, &last, now); return; }
    if (now - last < 5000000000ull || !atomic_compare_exchange_strong(&g_cp_last, &last, now)) return;   // one thread reports each window
    static const char *names[] = {"pass_end", "pass_begin", "pipeline", "arguments", "texture", "draw", "geometry", "index"};
    char line[1000] = {0}; size_t at = 0;
    for (int i = 0; i < 8; i++) {   // taken and zeroed together: the other thread's phases go on adding
        uint64_t n = atomic_exchange_explicit(&g_cp_calls[i], 0, memory_order_relaxed), c = atomic_exchange_explicit(&g_cp_cpu[i], 0, memory_order_relaxed), w = atomic_exchange_explicit(&g_cp_wall[i], 0, memory_order_relaxed);
        if (n && at < sizeof line) at += snprintf(line + at, sizeof line - at, " %s %llu calls %.2f/%.2f ms CPU/wall;", names[i], (unsigned long long)n, c / 1e6, w / 1e6); }
    MLOG("[cpuprof] inclusive phases over %.2f s (nested phases overlap):%s", (now - last) / 1e9, line);
    uint64_t gw = atomic_exchange_explicit(&g_cp_geo_waited, 0, memory_order_relaxed), gs = atomic_exchange_explicit(&g_cp_geo_safe, 0, memory_order_relaxed);
    if (gw || gs) MLOG("[cpuprof] geometry CPU reads: waited %llu / proven safe %llu", (unsigned long long)gw, (unsigned long long)gs);
}
#define AP_B uint64_t _ap0 = g_allocprof > 0 ? g_dev.currentAllocatedSize : 0; cp_stamp _cp0 = cp_begin()
#define AP_E(i) do { if (g_allocprof > 0) { uint64_t _n = g_dev.currentAllocatedSize; if (_n > _ap0) g_ap_fn[i] += _n - _ap0; } cp_end(i, _cp0); } while (0)   // Per-frame arenas created so far (4 MiB each; for the memory report)
static _Atomic int g_last_commit_error;
static _Atomic int g_up_pending;

// macOS revokes a process's GPU access after GPU hangs or faults it caused: from then on every command buffer comes back MTL4CommandQueueErrorAccessRevoked ("Ignored (for causing
// prior/excessive GPU errors)", kIOGPUCommandBufferCallbackErrorSubmissionsIgnored) without running, the GPU signals no fence again and nothing is drawn; the game in #1326 ran about
// 70 s like that before it aborted, and in full screen WindowServer froze. The first one stops the game: presents stop, the front end closes the game, and the shared event a game's
// SyncWait waits on (for up to an hour, mtl_wait_at) is raised from the CPU to each fence whose feedback has come back. The feedback still comes, promptly, so g_done moves as
// before and no command allocator is reset before Metal has handed its command buffer back. A hang or a fault alone is not enough: the GPU recovers from those, and a command buffer
// discarded as the victim of another's error comes back with a timeout too while the game goes on, as it did in #1326's second run
static _Atomic int g_gpu_lost;
// Why the GPU was taken as lost (g_gpu_lost, set once): GL_REVOKED, the access macOS revoked (gpu_lost_check: the queue still reports every command buffer back, so the waits end
// at their feedback as before); GL_HANG, work waiting and no GPU work finished for DM_GPU_LOST_S seconds (gpu_watch, below). From GL_HANG on the GPU is gone (gpu_gone): nothing
// more is committed to it (Q4_COMMIT_TIMED and the present's own commits skip theirs, counted in g_gone_skips), and every CPU wait on its completion gives way instead of waiting
// for feedback that will not come, so the front end's save and exit (front_gpu_lost) are not held by a wait of the game's or the host's
// GL_OOM: a command buffer came back out of GPU memory (gpu_lost_check; ported from S2Arm 966e78cae, Apache-2.0): stopped as the hang, and the residency set emptied at once
enum { GL_NONE, GL_REVOKED, GL_HANG, GL_OOM };
static inline int gpu_gone(void) { return atomic_load_explicit(&g_gpu_lost, memory_order_acquire) >= GL_HANG; }
static _Atomic uint64_t g_gone_skips;   // command buffers not committed because the GPU is gone (the tests read it)
static inline void gpu_gone_skip(void) { atomic_fetch_add_explicit(&g_gone_skips, 1, memory_order_relaxed); }
int mtl_gpu_lost_why(void) { return atomic_load(&g_gpu_lost); }   // front.h: 0 not lost, 1 access revoked, 2 no GPU work finished (a hang), 3 GPU memory full
int mtl_gpu_gone(void) { return gpu_gone(); }
void front_gpu_lost(void);
__attribute__((weak)) void front_gpu_lost(void) {   // the Mac front end leaves full screen, says why and quits; the iPhone's saves and quits (front_ios.m)
    if (atomic_load(&g_gpu_lost) == GL_REVOKED) MDIE("GPU access revoked: macOS runs none of this process's GPU work any more");
    if (atomic_load(&g_gpu_lost) == GL_OOM) MDIE("GPU lost: a command buffer came back out of GPU memory");
    MDIE("GPU lost: no GPU work finished for DM_GPU_LOST_S seconds with work waiting");
}
// g_ev is raised from the CPU here and in gpu_gone_release, under the one lock, so neither lowers what the other set
static os_unfair_lock g_ev_lk = OS_UNFAIR_LOCK_INIT;
// Keep g_ev at least at g_done (ported from NXNative 4fdfd4793): a command buffer that fails with a recoverable error (page fault, hang or timeout, innocent victim, a rejected
// submission) or with the access revoked can complete through its feedback handler without running rec_signal(g_ev, fence), and a fast-wake SyncWait on g_ev (mtl_wait_at) would
// sleep until its limit. post_complete raises it at each feedback; normal frames find it already there and write nothing
static void fence_ev_raise(uint64_t f) {
    if (!g_ev || g_ev.signaledValue >= f) return;
    os_unfair_lock_lock(&g_ev_lk);
    if (g_ev && g_ev.signaledValue < f) g_ev.signaledValue = f;
    os_unfair_lock_unlock(&g_ev_lk);
}
// Metal 4 reports a commit's error as MTL4CommandQueueErrorTimeout with no text, and the command buffer's own error underneath (NSUnderlyingErrorKey, NSMultipleUnderlyingErrorsKey):
// every command buffer error in both #1326 logs has that shape. Only this domain counts: an innocent victim's IOGPU error underneath has code 5 too
static int gpu_err_has(NSError *e, NSInteger code, int depth) {
    if (!e || depth > 3) return 0;
    if (e.code == code && [e.domain isEqualToString:MTL4CommandQueueErrorDomain]) return 1;
    for (NSError *u in e.underlyingErrors) if (gpu_err_has(u, code, depth + 1)) return 1;
    return 0;
}
// GPU memory full (ported from S2Arm 966e78cae, Apache-2.0): a command buffer that comes back out of GPU memory, kIOGPUCommandBufferCallbackErrorOutOfMemory by name ("Insufficient
// Memory (00000008:kIOGPUCommandBufferCallbackErrorOutOfMemory)") or by code alone (MTL4CommandQueueErrorOutOfMemory, Metal 3's MTLCommandBufferErrorOutOfMemory), was logged and the
// submissions went on, each filling the memory further: S2Arm's #327 (iPhone 15 Pro Max) had the zero-copy pools 3,669 MB resident and 5,127 MB allocated on the GPU, 49 more such
// errors after the first, the picture stopped and the whole phone froze until a hard restart. It now stops the game as the hang does (gpu_lost_take GL_OOM), and the residency set,
// wired memory the whole phone shares on iOS, is emptied at once (res_drop_all), not at the process's end. A code alone does not count for an innocent victim's error
static int gpu_err_text(NSError *e, NSString *what, int depth) {   // what is in the description of e or of an error under it
    if (!e || depth > 3) return 0;
    if ([e.localizedDescription containsString:what] || [e.userInfo[NSLocalizedDescriptionKey] containsString:what]) return 1;
    for (NSError *u in e.underlyingErrors) if (gpu_err_text(u, what, depth + 1)) return 1;
    return 0;
}
static int gpu_err_oom_code(NSError *e, int depth) {
    if (!e || depth > 3) return 0;
    if ((e.code == MTL4CommandQueueErrorOutOfMemory && [e.domain isEqualToString:MTL4CommandQueueErrorDomain]) || (e.code == MTLCommandBufferErrorOutOfMemory && [e.domain isEqualToString:MTLCommandBufferErrorDomain])) return 1;
    for (NSError *u in e.underlyingErrors) if (gpu_err_oom_code(u, depth + 1)) return 1;
    return 0;
}
static int gpu_err_oom(NSError *e) { return gpu_err_text(e, @"CallbackErrorOutOfMemory", 0) || (gpu_err_oom_code(e, 0) && !gpu_err_text(e, @"InnocentVictim", 0)); }
static void gpu_lost_take(int why, const char *what);
static void gpu_lost_check(NSError *e, const char *where) {
    if (e && !atomic_load(&g_gpu_lost) && gpu_err_oom(e)) {
        char what[160]; snprintf(what, sizeof what, "the %s command buffer came back out of GPU memory", where);
        gpu_lost_take(GL_OOM, what); return;
    }
    int none = GL_NONE;
    if (!e || atomic_load(&g_gpu_lost) || !gpu_err_has(e, MTL4CommandQueueErrorAccessRevoked, 0) || !atomic_compare_exchange_strong(&g_gpu_lost, &none, GL_REVOKED)) return;
    MLOG("[RED] GPU access revoked: the %s command buffer was ignored (fences back %llu of %llu); macOS runs none of this process's GPU work any more, so the game stops", where,
         (unsigned long long)atomic_load(&g_done), (unsigned long long)atomic_load(&g_fence));
    front_gpu_lost();   // post_complete raises g_ev at each feedback from here on (fence_ev_raise)
}
// DM_TEST_GPU_LOST=n (for testing): from the n-th submission on, imitate the revoked access without faulting the GPU: each submission's feedback reports it, in the shape the #1326
// logs show, and the GPU's signal of its fence is left out (its work still runs)
static int gpu_lost_test(void) {
    static int at = -2, n; if (at == -2) { const char *e = getenv("DM_TEST_GPU_LOST"); at = e ? atoi(e) : -1; }
    return at > 0 && ++n >= at;
}
static NSError *gpu_lost_test_error(void) {
    NSError *revoked = [NSError errorWithDomain:MTL4CommandQueueErrorDomain code:MTL4CommandQueueErrorAccessRevoked userInfo:@{NSLocalizedDescriptionKey: @"DM_TEST_GPU_LOST: Ignored (for causing prior/excessive GPU errors)",
                                                                                                                             NSUnderlyingErrorKey: [NSError errorWithDomain:@"IOGPUCommandQueueErrorDomain" code:4 userInfo:nil]}];
    return [NSError errorWithDomain:MTL4CommandQueueErrorDomain code:MTL4CommandQueueErrorTimeout userInfo:@{NSUnderlyingErrorKey: revoked, NSMultipleUnderlyingErrorsKey: @[revoked]}];
}

static pthread_mutex_t g_res_mu = PTHREAD_MUTEX_INITIALIZER;   // Dedicated lock for the residency set: res_add is called on paths that hold g_mu (arena_new), so it cannot share g_mu
// ---------- What the freeze detector's dump reads (mtl_stall_dump; dm/host/stall.c, DM_STALL_LOG) ----------
// Ocarina of Time's test 3 froze once on an iPhone 18 Pro Max, 13 s after a save load as Link stepped into water: presents stopped, audio went on, and the log said nothing, no [RED]
// line and no crash. Every wait that could have held it was silent: a command buffer that never completes logs nothing, the game's SyncWait sleeps on the GPU event for up to an hour
// (mtl_wait_at), and rec_drain, rec_note_wait, ubc_wait, up_wait_zero and the present waits have no limit (they now say so once at 10 s, wait_say below, and wait on). The feedback handlers all run on the one serial queue
// g_feedback_q, and the upload batch's handler committed the residency set (res_commit, under g_res_commit_mu) every time, so one long commit held back every completion, and g_done with
// it, again with no line (no handler commits now: res_commit_async; a slow commit or lock wait says so, q4_commit_slow below). The detector's dump therefore needs, without taking any lock those paths can hold: who holds the two residency locks and since when, which feedback handler
// runs and when the queue last ran one, which waits are in progress, and what the encode thread is doing. Everything below is a few relaxed atomic stores; the clock is
// mach_absolute_time (no system call), read only where a lock is taken or a wait blocks, never per draw.
//
// Who holds a lock: the holder's mach thread (as svc_thread_dump names host threads), the site that took it (file:line) and since when (mach ticks), stored after each take and cleared
// before each release. The dump reads these, never the lock, so a dump during a freeze cannot wait on the lock that froze it. A take whose note is not stored yet shows the previous holder
#define LOCK_STR_(x) #x
#define LOCK_STR(x) LOCK_STR_(x)
#define LOCK_SITE __FILE_NAME__ ":" LOCK_STR(__LINE__)
typedef struct { _Atomic uint32_t th; _Atomic(const char *) site; _Atomic uint64_t at; } lock_note;
static lock_note g_res_commit_note, g_res_note;
static inline void lock_note_take(lock_note *n, const char *site) {
    atomic_store_explicit(&n->site, site, memory_order_relaxed); atomic_store_explicit(&n->at, mach_absolute_time(), memory_order_relaxed);
    atomic_store_explicit(&n->th, pthread_mach_thread_np(pthread_self()), memory_order_release);
}
static inline void lock_note_drop(lock_note *n) { atomic_store_explicit(&n->th, 0, memory_order_release); }
// The long-frame line's split of the replay's time (nvn_lft.h, which says what each part times): ns, count and the part inside a texture upload, on the replay thread only
static _Atomic uint64_t g_lft_ns[LFT_N], g_lft_n[LFT_N], g_lft_up[LFT_N];
static __thread int t_lft_up;   // inside pkg_upload
static int on_sub_thread(void);
static inline uint64_t lft_begin(void) { return on_sub_thread() ? clock_gettime_nsec_np(CLOCK_UPTIME_RAW) : 0; }
// Page-ins by part of the replay's work (nvn_lft.h PF_*): t_pf_sec is the part running on this thread while a replayed node's scope runs (-1 outside one); each change reads the
// process's page-in count and gives the difference to the part that ran. A part is entered with pf_enter (-> the part to go back to) and left with pf_leave
static _Atomic uint64_t g_pf[PF_N];
static __thread int t_pf_sec = -1; static __thread uint64_t t_pf_last;
static __thread int t_sop = -1; static __thread uint64_t t_sop_t;   // DM_NVN_PF_PARTS: the replay's command under way and when it began (sop_tick)
static inline uint64_t pf_pageins(void) { task_events_info_data_t ev; mach_msg_type_number_t c = TASK_EVENTS_INFO_COUNT; return task_info(mach_task_self(), TASK_EVENTS_INFO, (task_info_t)&ev, &c) == KERN_SUCCESS ? (uint64_t)(uint32_t)ev.pageins : 0; }
// The 'other' part by step (DM_NVN_PF_PARTS): t_pfm is the step of the replay's command under way (a mark, pfm, at the top-level steps of draw_, dispatch and set_rt; PFM_CMD from
// each command's start until its first mark), and page-ins credited to PF_OTHER go to it too. A mark credits what came before it, so each step gets the page-ins between its mark and the
// next one, less those of named parts called within it
enum { PFM_CMD, PFM_D_START, PFM_D_MDX, PFM_D_IMG, PFM_D_UBD, PFM_D_IXC, PFM_D_ORDER, PFM_D_FB, PFM_D_HOIST, PFM_D_VBUF, PFM_D_RP, PFM_D_STATE, PFM_D_PULL, PFM_D_ARGS, PFM_D_TAIL, PFM_C_START, PFM_C_PSO, PFM_C_FILL, PFM_C_FLUSH, PFM_C_OWN, PFM_C_ARGS, PFM_C_ENC, PFM_RT, PFM_N };
static const char *const k_pfm_name[PFM_N] = {"the command (before its first step)", "draw: start (mesh flush, pass checks)", "draw: multi-draw records", "draw: images and buffer textures", "draw: inline uniform updates", "draw: index conversion and prescans", "draw: tests and order", "draw: feedback snapshots", "draw: hoists and plans", "draw: vertex streams", "draw: render pass begin", "draw: pipeline and state", "draw: pulled vertices", "draw: arguments and encoding", "draw: after the draw (notes, split draws)", "dispatch: start (indirect, program)", "dispatch: pipeline", "dispatch: buffer fills, uniform updates", "dispatch: pass end, images", "dispatch: encoder", "dispatch: buffer textures, arguments", "dispatch: ranges and encoding", "set_rt"};
static _Atomic uint64_t g_pfo[PFM_N];
static __thread int t_pfm = PFM_CMD;
static inline void pf_credit(void) { uint64_t p = pf_pageins(); if (p >= t_pf_last) { atomic_fetch_add_explicit(&g_pf[t_pf_sec], p - t_pf_last, memory_order_relaxed); if (t_pf_sec == PF_OTHER) atomic_fetch_add_explicit(&g_pfo[t_pfm], p - t_pf_last, memory_order_relaxed); } t_pf_last = p; }
// The replay thread's own waits by step: the page-in count is the whole process's (task_info), so 'other' also takes what other threads page in (the game's loads, the residency
// workers) while the replay is between named parts. A step's wall time less this thread's CPU time is time it was off the CPU: its own page-ins, lock waits and the like. A step here
// includes the named parts it calls
static _Atomic uint64_t g_pfw[PFM_N];
static __thread uint64_t t_pfw_wall, t_pfw_cpu;
static inline void pfw_tick(void) {
    uint64_t w = clock_gettime_nsec_np(CLOCK_UPTIME_RAW), c = clock_gettime_nsec_np(CLOCK_THREAD_CPUTIME_ID);
    if (t_pfw_wall && w > t_pfw_wall) { uint64_t dw = w - t_pfw_wall, dc = c > t_pfw_cpu ? c - t_pfw_cpu : 0; if (dw > dc) atomic_fetch_add_explicit(&g_pfw[t_pfm], dw - dc, memory_order_relaxed); }
    t_pfw_wall = w; t_pfw_cpu = c;
}
static inline void pfm(int m) { if (__builtin_expect(t_pf_sec >= 0, 0)) { if (t_pf_sec == PF_OTHER) pf_credit(); pfw_tick(); t_pfm = m; } }   // a step's mark: a load and a compare when DM_NVN_PF_PARTS is off
static inline int pf_enter(int s) { int prev = t_pf_sec; if (prev < 0 || prev == s) return -2; pf_credit(); t_pf_sec = s; return prev; }
static inline void pf_leave(int prev) { if (prev < 0) return; pf_credit(); t_pf_sec = prev; }
// DM_NVN_PF_PARTS=1 turns it on (a diagnostic, off by default): each change of part costs a task_info call (about 0.5 us on an M4 Max), and the uniform reads and the pool tables
// change it thousands of times a frame. Off, t_pf_sec stays -1 and pf_enter is a load and a compare
static int g_pf_on = -1;
static int pf_on(void) { if (g_pf_on < 0) { const char *e = getenv("DM_NVN_PF_PARTS"); g_pf_on = e && atoi(e) > 0; if (g_pf_on) MLOG("DM_NVN_PF_PARTS=1: long-frame lines give the replay's page-ins by part of its work (a task_info call at each change of part)"); } return g_pf_on; }
void mtl_pf_scope(int on) { if (!pf_on()) return; t_sop = -1; if (on) { t_pf_last = pf_pageins(); t_pf_sec = PF_OTHER; t_pfw_wall = 0; t_pfm = PFM_CMD; pfw_tick(); } else if (t_pf_sec >= 0) { pf_credit(); pfw_tick(); t_pf_sec = -1; } }
// DM_NVN_PF_PARTS=1 also times the replay's commands (mtl_exec): one clock read a command, and a command that took SOP_NS or more is counted to its type (its time, how many). A
// page-in stall shows as a slow command, so the long-frame line names the command types the replay waited in, inside the page-ins' 'other' part. A sub-list's call, a jump and an
// end are not counted (the commands they lead to are), nor the time a game submit took the lock between two commands (nq_sub_yield)
enum { SOP_N = 64, SOP_NS = 200000 };
static _Atomic uint64_t g_sop_ns[SOP_N], g_sop_n[SOP_N];
static const char *const k_sop_name[] = {"end", "jump", "begin", "call", "signal_event", "report_counter", "copy_b2b", "update_ub", "set_rt", "clear_color", "clear_ds", "viewports", "scissor", "depth_range", "bind_program", "bind_state", "bind_vattr", "bind_vstream", "bind_vbuf", "bind_ubo", "bind_ssbo", "bind_tex", "bind_samp", "stencil", "poly_offset", "draw", "draw_idx", "dispatch", "barrier", "set_tex_pool", "set_samp_pool", "copy_b2t", "copy_stride", "blend_color", "copy_t2b", "bind_img", "copy_t2t", "reset_counter", "clear_tex", "clear_buf", "depth_clamp", "render_cond", "fence_sync", "tf_bind", "tf_state", "rast_discard", "vp_swizzle", "bind_tex1", "prim_restart", "bind_ubo_small", "bind_vbuf1", "draw_tex", "alpha_ref", "push_const", "dlss", "multi_draw", "wait_event", "wait_sync", "depth_bounds"};
static inline void sop_tick(uint32_t op) {   // the replay thread, at each command while a scope is tracked
    pfm(PFM_CMD);   // the 'other' page-ins so far go to the last command's step
    uint64_t now = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    if (t_sop >= 0) { uint64_t d = now - t_sop_t; if (d >= SOP_NS) { atomic_fetch_add_explicit(&g_sop_ns[t_sop], d, memory_order_relaxed); atomic_fetch_add_explicit(&g_sop_n[t_sop], 1, memory_order_relaxed); } }
    t_sop = (op == OP_END || op == OP_JUMP || op == OP_CALL || op >= SOP_N) ? -1 : (int)op; t_sop_t = now;
}
// The slow commands since the last call, the largest first (up to 5), into out: "; slow commands: draw_idx 3 / 120.4 ms, ..." or ""; resets them
int mtl_sop_text(char *out, size_t n) {
    uint64_t ns[SOP_N], c[SOP_N]; int o = 0; if (!n) return 0; out[0] = 0;
    for (int k = 0; k < SOP_N; k++) { ns[k] = atomic_exchange_explicit(&g_sop_ns[k], 0, memory_order_relaxed); c[k] = atomic_exchange_explicit(&g_sop_n[k], 0, memory_order_relaxed); }
    for (int i = 0; i < 5; i++) { int b = -1; for (int k = 0; k < SOP_N; k++) if (c[k] && (b < 0 || ns[k] > ns[b])) b = k;
        if (b < 0) break;
        o += snprintf(out + o, n - (size_t)o, "%s %s %llu / %.1f ms", i ? "," : "; slow commands (DM_NVN_PF_PARTS):", b < (int)(sizeof k_sop_name / sizeof *k_sop_name) ? k_sop_name[b] : "op", (unsigned long long)c[b], ns[b] / 1e6);
        if ((size_t)o >= n) { o = (int)n - 1; break; }
        c[b] = 0; }
    {   // the 'other' part by step, the largest first (up to 6)
        uint64_t v[PFM_N], all = 0; for (int k = 0; k < PFM_N; k++) all += v[k] = atomic_exchange_explicit(&g_pfo[k], 0, memory_order_relaxed);
        for (int i = 0; all && i < 6 && (size_t)o < n; i++) { int b = -1; for (int k = 0; k < PFM_N; k++) if (v[k] && (b < 0 || v[k] > v[b])) b = k;
            if (b < 0) break;
            o += snprintf(out + o, n - (size_t)o, "%s %s %llu", i ? "," : "; 'other' page-ins by step:", k_pfm_name[b], (unsigned long long)v[b]); v[b] = 0; }
        if ((size_t)o >= n) o = (int)n - 1; }
    {   // the replay thread's own waits by step (wall less its CPU), 1 ms or more, the largest first (up to 6)
        uint64_t v[PFM_N]; for (int k = 0; k < PFM_N; k++) v[k] = atomic_exchange_explicit(&g_pfw[k], 0, memory_order_relaxed);
        for (int i = 0; i < 6 && (size_t)o < n; i++) { int b = -1; for (int k = 0; k < PFM_N; k++) if (v[k] >= 1000000 && (b < 0 || v[k] > v[b])) b = k;
            if (b < 0) break;
            o += snprintf(out + o, n - (size_t)o, "%s %s %.1f ms", i ? "," : "; the replay's own waits by step (wall less its CPU):", k_pfm_name[b], v[b] / 1e6); v[b] = 0; }
        if ((size_t)o >= n) o = (int)n - 1; }
    return o;
}
void mtl_pf_take(uint64_t out[PF_N]) { for (int k = 0; k < PF_N; k++) out[k] = atomic_exchange_explicit(&g_pf[k], 0, memory_order_relaxed); }   // 0: not the replay thread, nothing timed
static inline void lft_add(int k, uint64_t ns) {
    atomic_fetch_add_explicit(&g_lft_ns[k], ns, memory_order_relaxed); atomic_fetch_add_explicit(&g_lft_n[k], 1, memory_order_relaxed);
    if (t_lft_up) atomic_fetch_add_explicit(&g_lft_up[k], ns, memory_order_relaxed);
}
static inline void lft_end(int k, uint64_t t0) { if (t0) lft_add(k, clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0); }
static inline void lft_lock(pthread_mutex_t *m) { if (!pthread_mutex_trylock(m)) return; uint64_t t0 = lft_begin(); pthread_mutex_lock(m); lft_end(LFT_LOCK, t0); }   // a wait the replay makes is timed
#define mu_lock() lft_lock(&g_mu)
#define smu_lock() lft_lock(&g_smu)
#define res_mu_lock() res_mu_lock_at(LOCK_SITE)
static inline void res_mu_lock_at(const char *site) { lft_lock(&g_res_mu); lock_note_take(&g_res_note, site); }
static inline void res_mu_unlock(void) { lock_note_drop(&g_res_note); pthread_mutex_unlock(&g_res_mu); }
static inline void res_commit_unlock(void) { lock_note_drop(&g_res_commit_note); pthread_mutex_unlock(&g_res_commit_mu); }
static double mach_s(uint64_t ticks) { static mach_timebase_info_data_t tb; if (!tb.denom) mach_timebase_info(&tb); return (double)ticks * tb.numer / tb.denom / 1e9; }
// The feedback queue's heartbeat: every commit feedback handler stamps its start and its end and names itself (they run one at a time on g_feedback_q), so a handler that never
// returns shows as "running: upload batch for 12.0 s", and a queue that has run nothing for a while as the age of the last handler's end with g_done behind g_fence
static _Atomic(const char *) g_fbq_what; static _Atomic uint64_t g_fbq_in, g_fbq_out, g_fbq_n;
static inline void fb_in(const char *what) { atomic_store_explicit(&g_fbq_in, mach_absolute_time(), memory_order_relaxed); atomic_store_explicit(&g_fbq_what, what, memory_order_release); }
static inline void fb_out(void) { atomic_store_explicit(&g_fbq_what, NULL, memory_order_relaxed); atomic_store_explicit(&g_fbq_out, mach_absolute_time(), memory_order_relaxed); atomic_fetch_add_explicit(&g_fbq_n, 1, memory_order_relaxed); }
// Waits in progress: per kind, the threads blocked in it now, and what the latest one waits for and since when. Set and cleared only once a wait blocks (the fast paths pay nothing)
enum { WN_EVENT, WN_DONE, WN_DRAIN, WN_NOTE, WN_UPZERO, WN_ONCE, WN_PALLOC, WN_PTICKET, WN_N };
static const char *const wn_name[WN_N] = {"SyncWait on the GPU event (fence)", "wait for a fence's feedback (fence)", "encode thread drain (submit thread)", "encode thread note (value)",
    "upload batches to complete (pending)", "one-off command buffer", "present allocator (ticket)", "present ticket (ticket)"};
static struct { _Atomic int n; _Atomic uint64_t what, at; } g_wn[WN_N];
static inline void wn_in(int k, uint64_t what) { atomic_store_explicit(&g_wn[k].what, what, memory_order_relaxed); atomic_store_explicit(&g_wn[k].at, mach_absolute_time(), memory_order_relaxed); atomic_fetch_add(&g_wn[k].n, 1); }
static inline void wn_out(int k) { atomic_fetch_sub(&g_wn[k].n, 1); }
// The 10 s mark: a wait with no limit that is still waiting after 10 s says so once, in a red line with its site, and then waits on exactly as before. Ocarina of Time's test 3 froze
// with nothing in the log; the game's SyncWait sleeps on the GPU event for up to an hour (mtl_wait_at's fast wake), and up_wait_zero, the present waits (present_now's allocator,
// mtl_present_wait), rec_drain, rec_note_wait and ubc_wait had no limit and no line, so whichever of them held the picture said nothing. The freeze detector (dm/host/stall.c)
// names the waits in progress once presents stop in focus; these lines say it in the wait itself, in the background too and whatever stopped. Nothing changes for a wait that ends
// before the mark: the clock is read once it blocks (CLOCK_UPTIME_RAW, the commpage, no system call), its sleeps are the same until the mark, and a wait past it wakes once there,
// says it and goes back to the very wait it was in. Each site says it at most WAIT_SAY_MAX times a run. The graphics tests shorten the mark (g_wait_say_ns) to drive the lines
static uint64_t g_wait_say_ns = 10000000000ull;
enum { WAIT_SAY_MAX = 4 };
typedef struct { uint64_t at; int told; } wait_mark;   // the mark (CLOCK_UPTIME_RAW ns), and whether this wait has said it (or has nothing to say: a limit before the mark)
static inline void wait_mark_set(wait_mark *m) { m->at = clock_gettime_nsec_np(CLOCK_UPTIME_RAW) + g_wait_say_ns; m->told = 0; }
static inline uint64_t wait_mark_left(const wait_mark *m) { uint64_t now = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); return now >= m->at ? 0 : m->at - now; }
// 1 once, the first time it is called at or past the mark: the caller says what it waits for
static inline int wait_mark_due(wait_mark *m) { if (m->told || wait_mark_left(m)) return 0; m->told = 1; return 1; }
// The suspend's limit (mtl_drain_by; hle_nvn.c dm_gfx_suspend, going to the background). Ocarina of Time's test 3 (baf45a97) froze once on an iPhone 18 Pro Max as Link stepped
// into water: presents stopped, audio went on, and when the owner closed it from the app switcher the log ended at "oe focus state -> 2/3" and "audio suspended". Going to the
// background, dm_gfx_suspend runs on the main thread (front_ios.m sceneDidEnterBackground) and waited with no limit for the graphics calls in progress, the present on the GPU
// (present_drop_for_suspend), the present queue, the snapshot copies, a one-off command buffer (once_wait, DISPATCH_TIME_FOREVER) and the last fence and upload batches
// (mtl_finish_gpu): with the GPU or the feedback queue stuck it never returned, so the pipeline archive's background task and the cloud save after it never started, and the
// relaunch came up black. The drain now runs with a deadline, a thread-local one so that no other caller of these waits changes: t_drain_by is set only on the thread that runs
// mtl_drain_by (CLOCK_UPTIME_RAW ns, 0: no limit, every other thread). The waits on that path end at it, their loops checking drain_over, and say which one it was; the snapshot
// copy's 10 s stop (snap_drain's MDIE) becomes that answer too, as a process stopped in the background is worse than one that says it did not drain
static __thread uint64_t t_drain_by;
static inline uint64_t drain_left(void) {   // what is left of the limit (ns); UINT64_MAX with none
    if (!t_drain_by) return UINT64_MAX;
    uint64_t now = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); return now >= t_drain_by ? 0 : t_drain_by - now;
}
// A GPU taken as lost (gpu_gone) ends these waits as the limit does: what they wait for will not come
static inline int drain_over(void) { return gpu_gone() || (t_drain_by && !drain_left()); }
// pthread_cond_wait that also wakes at the mark (a timed-out wake is a spurious one to the caller's loop, which checks wait_mark_due); after the mark, pthread_cond_wait itself.
// Under the suspend's limit (t_drain_by) it also wakes there, for the caller's loop to check drain_over
static void wait_mark_sleep(pthread_cond_t *cv, pthread_mutex_t *mu, const wait_mark *m) {
    uint64_t left = m->told ? UINT64_MAX : wait_mark_left(m), dl = drain_left();
    if (!left || !dl) return;
    if (dl < left) left = dl;
    if (gpu_gone() && left > 1000000ull) left = 1000000ull;   // the GPU taken as lost: the caller's loop looks again every millisecond (gone ends the GPU waits' loops, drain_over)
    if (left == UINT64_MAX) { pthread_cond_wait(cv, mu); return; }
    struct timespec ts = {(time_t)(left / 1000000000ull), (long)(left % 1000000000ull)};
    pthread_cond_timedwait_relative_np(cv, mu, &ts);
}
// pthread_cond_wait, or under the suspend's limit a wait that ends there (present_drop_for_suspend)
static void drain_cond_wait(pthread_cond_t *cv, pthread_mutex_t *mu) {
    uint64_t dl = drain_left(); if (gpu_gone() && dl > 1000000ull) dl = 1000000ull;   // as wait_mark_sleep
    if (dl == UINT64_MAX) { pthread_cond_wait(cv, mu); return; }
    if (!dl) return;
    struct timespec ts = {(time_t)(dl / 1000000000ull), (long)(dl % 1000000000ull)};
    pthread_cond_timedwait_relative_np(cv, mu, &ts);
}
// The line: "[RED] the host has waited 10 s for <what> at <site> (thread <name>): <state>", at most WAIT_SAY_MAX a site (*n, the site's own count). MLOG takes only the log's lock
__attribute__((format(printf, 4, 5))) static void wait_say(_Atomic int *n, const char *what, const char *site, const char *fmt, ...) {
    if (atomic_fetch_add_explicit(n, 1, memory_order_relaxed) >= WAIT_SAY_MAX) return;
    char state[512]; va_list ap; va_start(ap, fmt); vsnprintf(state, sizeof state, fmt, ap); va_end(ap);
    char th[64] = ""; pthread_getname_np(pthread_self(), th, sizeof th);
    MLOG("[RED] the host has waited %g s for %s at %s (thread %s): %s", g_wait_say_ns / 1e9, what, site, th[0] ? th : "unnamed", state);
}
// When the last present completed on the GPU (host now_ns), for the freeze detector: dm/host/stall.c defines it, the graphics tests' t_host_stubs.c a weak stand-in
extern _Atomic uint64_t dm_present_done_ns;
// The start's timeline (dm/host/hle_lifecycle.c): the prepare step's time before the first frame, and the first present that completed on the GPU. The graphics tests have no host
__attribute__((weak)) void dm_start_prepared(uint64_t ns) { (void)ns; }
__attribute__((weak)) void dm_start_first_frame(uint64_t at_ns) { (void)at_ns; }
// Time spent waiting for g_res_commit_mu (res_commit_lock: a try first, so an uncontended lock reads no clock), by the replay thread (on_sub_thread) and by every other thread together
// (the encode thread's queue commits, the upload batches' completion handlers, the deferred-release worker): the translation detail line (mtl_wait_stats)
static _Atomic uint64_t g_rcm_wait_ns[2], g_rcm_waits[2];   // [0] the replay thread, [1] the others
static int on_sub_thread(void);
// ---------- Slow residency and queue commits ----------
// Ocarina of Time's test 3 (baf45a97) froze once on an iPhone 18 Pro Max as Link stepped into water, presents stopped with audio running and nothing in the log. One of the paths the
// audits could not rule out: a [g_res commit] or a [g_q4 commit:] that takes seconds. Every taker of g_res_commit_mu waits behind it, and while the upload batch's feedback handler
// committed the residency set itself, so did g_feedback_q and every completion after it (g_done stopped). Nothing timed those calls: the residency set line every 300 frames sums the
// commits' time, and it never came. So each one is timed now (CLOCK_UPTIME_RAW, the commpage: no system call, a few ns) and one of 100 ms or more says so with what it was doing:
//   "[RED] slow residency commit: N ms (adds A, B MB; removes R, S MB) on thread T[, on the feedback queue] (#k)"   (res_commit: the queued add / remove calls and [g_res commit])
//   "[RED] slow queue commit: N ms at <site> on thread T[, on the feedback queue] (#k)"                             (the encode thread's RO_COMMIT / RO_COMMIT_REAL, once_commit, snap_take)
//   "[RED] slow wait for the residency commit lock: N ms at <site> on thread T; held by host thread H from <site> (#k)"   (res_commit_lock)
//   "[RED] slow residency prewire: N ms (F file ranges, M MB, changes #a-#b) on thread T, outside the residency commit lock (DM_NVN_RES_PREWIRE) (#k)"   (res_prewire: the page-in alone)
//   "[RED] slow wait for a residency prewire: N ms at <site> on thread T (it needed the changes below #s; ...) (#k)"   (res_commit_to: a commit that needed what a prewire wires)
// Each kind says its first 20, then every 100th (#k counts them all), so a run of slow commits cannot fill the log. A commit under the threshold costs two clock reads and a compare.
// The graphics tests lower g_slow_commit_ns to drive the lines
static uint64_t g_slow_commit_ns = 100000000ull;
static char g_fbq_key;   // g_feedback_q's specific (mtl_init): set only on the feedback queue's own blocks
static inline int on_feedback_q(void) { return dispatch_get_specific(&g_fbq_key) != NULL; }
static inline uint64_t slow_now(void) { return clock_gettime_nsec_np(CLOCK_UPTIME_RAW); }
static uint64_t slow_due(_Atomic uint64_t *n) { uint64_t k = atomic_fetch_add_explicit(n, 1, memory_order_relaxed) + 1; return k <= 20 || k % 100 == 0 ? k : 0; }   // → its number when due, else 0
static void slow_thread(char *th, size_t n) {
    th[0] = 0; pthread_getname_np(pthread_self(), th, n);
    if (!th[0]) snprintf(th, n, "%#x", pthread_mach_thread_np(pthread_self()));
}
// A [g_q4 commit:] that started at t0 (slow_now) and has just returned; site: whose
static void q4_commit_slow(uint64_t t0, const char *site) {
    uint64_t dt = slow_now() - t0; if (dt < g_slow_commit_ns) return;
    static _Atomic uint64_t n; uint64_t k = slow_due(&n); if (!k) return;
    char th[64]; slow_thread(th, sizeof th);
    MLOG("[RED] slow queue commit: %.1f ms at %s on thread %s%s (#%llu)", dt / 1e6, site, th, on_feedback_q() ? ", on the feedback queue" : "", (unsigned long long)k);
}
// With the GPU taken as lost (gpu_gone) the commit is skipped: nothing more is sent to it, and what waits for its completion gives way (drain_over, mtl_wait_at, once_wait)
static void (*g_q4_commit_hook)(const char *site);   // test hook (t_pool_unwire): runs just before each timed queue commit; the host never sets it
#define Q4_COMMIT_TIMED(site, ...) do { if (gpu_gone()) { gpu_gone_skip(); break; } uint64_t q4_t0_ = slow_now(); if (g_q4_commit_hook) g_q4_commit_hook(site); __VA_ARGS__; q4_commit_slow(q4_t0_, site); } while (0)
#define res_commit_lock() res_commit_lock_at(LOCK_SITE)
static void res_commit_lock_at(const char *site) {
    if (!pthread_mutex_trylock(&g_res_commit_mu)) { lock_note_take(&g_res_commit_note, site); return; }
    // The holder as the wait begins (its note; it may be gone by the time this thread has the lock), for a wait long enough to say
    uint32_t hth = atomic_load_explicit(&g_res_commit_note.th, memory_order_acquire); const char *hsite = atomic_load_explicit(&g_res_commit_note.site, memory_order_relaxed);
    uint64_t hat = atomic_load_explicit(&g_res_commit_note.at, memory_order_relaxed), at = mach_absolute_time();
    uint64_t t0 = now_ns(); pthread_mutex_lock(&g_res_commit_mu); int k = !on_sub_thread();
    lock_note_take(&g_res_commit_note, site);
    uint64_t dt = now_ns() - t0;
    atomic_fetch_add_explicit(&g_rcm_wait_ns[k], dt, memory_order_relaxed); atomic_fetch_add_explicit(&g_rcm_waits[k], 1, memory_order_relaxed);
    if (!k) lft_add(LFT_LOCK, dt);
    if (dt >= g_slow_commit_ns) {
        static _Atomic uint64_t n; uint64_t s = slow_due(&n);
        if (s) { char th[64]; slow_thread(th, sizeof th); char holder[160];
            if (hth) snprintf(holder, sizeof holder, "held by host thread %#x from %s (for %.1f ms as the wait began)", hth, hsite ? hsite : "?", hat && at >= hat ? mach_s(at - hat) * 1e3 : 0.0);
            else snprintf(holder, sizeof holder, "its holder had not noted itself as the wait began (last taken at %s)", hsite ? hsite : "?");
            MLOG("[RED] slow wait for the residency commit lock: %.1f ms at %s on thread %s%s; %s (#%llu)", dt / 1e6, site, th, on_feedback_q() ? ", on the feedback queue" : "", holder, (unsigned long long)s); }
    }
}
// Wait ledger (DM_NVN_WAITS=1): every place a thread of the host or the game waits on the CPU for the GPU or for the encode thread, counted per frame (calls, calls that blocked,
// the time they blocked) and logged every 300 frames with the frame's GPU idle. The game's own SyncWait is split by how far its fence is behind the newest one (0: the last submission)
enum { WS_SYNC, WS_SYNC_NEWEST, WS_SYNC_POLL, WS_ACQ, WS_FINISH, WS_ALLOC, WS_VIS, WS_MDI, WS_READTEX, WS_T2T, WS_DIAG, WS_SNAP, WS_UPZERO, WS_UPALLOC, WS_DRAIN, WS_UBC, WS_ONCE, WS_POST, WS_SNAPCOPY, WS_N };
static const char *const ws_name[WS_N] = {"SyncWait (game, older fence)", "SyncWait (game, newest fence)", "SyncWait polls", "SyncWait on an acquire sync", "QueueFinish", "allocator", "occlusion ring",
    "indirect-count multi-draw", "texture readback", "texture copy t2t", "diagnostics", "snapshot ring", "upload batches", "upload slot", "encode thread drain", "uniform copy worker", "one-off command buffer", "post ring", "snapshot copy"};
static _Atomic uint64_t g_ws_n[WS_N], g_ws_blk[WS_N], g_ws_ns[WS_N];
static int ws_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_WAITS"); v = e && atoi(e) > 0; } return v; }
static inline uint64_t ws_t0(void) { return clock_gettime_nsec_np(CLOCK_UPTIME_RAW); }
static inline void ws_put(int site, uint64_t t0, int blocked) {
    atomic_fetch_add_explicit(&g_ws_n[site], 1, memory_order_relaxed);
    if (blocked) { atomic_fetch_add_explicit(&g_ws_blk[site], 1, memory_order_relaxed); atomic_fetch_add_explicit(&g_ws_ns[site], ws_t0() - t0, memory_order_relaxed); }
}
// For the game's waits: when each fence's command buffer ended on the GPU and when its feedback handler ran (CACurrentMediaTime), so a wait that blocked tells its wake-up delay
static struct { _Atomic uint64_t fence, wfence; double gpu_end, fb, wake; _Atomic int done; } g_fend[64];
