    dispatch_once(&once, ^{ q = dispatch_queue_create("dm.nvn.file-advise", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_USER_INITIATED, 0)); });
