// drop: the texture was let go by a memory trim (fb_trim from mtl_trim_at) or a pressure pass of DM_NVN_RT_DEAD (tu_pass_at), so its heap is freed with it instead of waiting in the
// list the trim has just emptied, or that the low headroom keeps short
@interface NvRecycledHeap : NSObject { @public id<MTLHeap> heap; int drop; } @end
@implementation NvRecycledHeap
- (void)dealloc { if (drop) res_remove(heap); else rh_wait(heap); }
@end
typedef struct { uint64_t serial, wh; } fam_pool_ser;   // a family member's serial a pool table read, and its geometry (fam_track_pool_serial)
// A resolution family's heap (image_texture); drop: its family went whole in a pressure pass (alias_dead_locked); hint: the member the last pass found not dead, an address compared only (DM_NVN_RT_DEAD).
// compressed: its members keep lossless compression (DM_NVN_FAMILY_NOCOMPRESS not 1); valid_wh: the geometry (width << 32 | height) whose compressed blocks the heap holds now, 0 none (fam_set_valid);
// pool_sers: the members' serials the pool tables have read, under pool_lk, so a size switch notes only those (ser_note); a table by serial (fam_track_pool_serial)
@interface NvImageHeap : NSObject { @public id<MTLHeap> heap; int drop; void *hint; _Atomic uint64_t valid_wh; uint8_t compressed; os_unfair_lock pool_lk; fam_pool_ser *pool_sers; uint32_t npool_sers, cappool_sers; } @end
