// A placement heap of at least `size` bytes: the smallest waiting one up to half as large again, or a new one an eighth larger, at most RH_SLACK more (its exact size with the switch
// off), so a single large target does not keep tens of MB resident for reuse (Ocarina of Time's 296 MB shadow target had a 333 MB heap). nil if Metal makes none
enum { RH_SLACK = 4u << 20 };
static id<MTLHeap> rh_heap(uint64_t size, MTLStorageMode sm, MTLCPUCacheMode cm, MTLHazardTrackingMode hm, int *reused) {
    *reused = 0;
    if (!size) return nil;
    int on = sw_on(rh_mode());
    uint64_t top = size + size / 2;
    void *got = NULL; uint64_t got_size = 0; int got_vol = 0;
    if (on) {
        os_unfair_lock_lock(&g_rh_lk);
        unsigned best = g_rh_n;
        for (unsigned i = 0; i < g_rh_n; i++) {
            if (g_rh[i].size < size || g_rh[i].size > top || (best < g_rh_n && g_rh[i].size >= g_rh[best].size)) continue;
            id<MTLHeap> h = (__bridge id<MTLHeap>)g_rh[i].heap;
            if (h.storageMode != sm || h.cpuCacheMode != cm) continue;   // (a placed texture takes its heap's hazard tracking: a placement heap reports untracked, a descriptor default)
            best = i;
        }
        if (best < g_rh_n) { got = g_rh[best].heap; got_size = g_rh[best].size; got_vol = g_rh[best].vol; g_rh_bytes -= g_rh[best].size; g_rh[best] = g_rh[--g_rh_n]; }
        os_unfair_lock_unlock(&g_rh_lk);
    }
    if (got) {
        id<MTLHeap> h = CFBridgingRelease(got);
        // marked volatile while it waited: non-volatile again before its texture is made; one the system emptied leaves (as rh_trim's) and a new heap is made in its place
        if (got_vol && cv_back(h, got_size)) { res_remove(h); atomic_fetch_add(&g_rh_trimmed, 1); }
        else { *reused = 1; atomic_fetch_add(&g_rh_reused, 1); return h; }
    }
    MTLHeapDescriptor *hd = [MTLHeapDescriptor new]; hd.type = MTLHeapTypePlacement; hd.size = on ? size + MIN(size / 8, (uint64_t)RH_SLACK) : size;
    hd.storageMode = sm; hd.cpuCacheMode = cm; hd.hazardTrackingMode = hm;
    id<MTLHeap> h = [g_dev newHeapWithDescriptor:hd];
    if (h && on) atomic_fetch_add(&g_rh_made, 1);
    return h;
}
// A texture of this descriptor in recycled memory, at the start of its heap. nil when the switch is off or the descriptor cannot be placed. A heap taken from the list that the texture
// does not go into waits again; a new one goes
static id<MTLTexture> rh_place(MTLTextureDescriptor *d) {
    if (!sw_on(rh_mode()) || d.storageMode != MTLStorageModePrivate || d.textureType == MTLTextureTypeTextureBuffer) return nil;
    MTLSizeAndAlign need = [g_dev heapTextureSizeAndAlignWithDescriptor:d];
    int reused = 0; id<MTLHeap> heap = rh_heap(need.size, d.storageMode, d.cpuCacheMode, d.hazardTrackingMode, &reused);
    id<MTLTexture> mt = heap ? [heap newTextureWithDescriptor:d offset:0] : nil;
    if (!mt) { if (heap && reused) rh_wait(heap); return nil; }
    NvRecycledHeap *owner = [NvRecycledHeap new]; owner->heap = heap;
    objc_setAssociatedObject(mt, &g_rh_owner_key, owner, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    return mt;
}
// The memory a texture holds: its recycled heap's size when rh_place made it, else its own allocation. drop: its heap is freed with it, not kept for reuse (NvRecycledHeap)
static uint64_t rh_tex_bytes(id<MTLTexture> t, int drop) {
    NvRecycledHeap *o = t ? objc_getAssociatedObject(t, &g_rh_owner_key) : nil;
    if (o && drop) o->drop = 1;
    return o ? o->heap.size : t.allocatedSize;
}
// A shared texture in a GPU-only pool (tex_mtl_) that the GPU can render or write to, in recycled memory: the CPU never writes its storage, and the new texture is filled from what
// the host holds of it (tex_init_fill) or zeroed, as a new allocation is. NVN asks no flag of a render target (Mario Kart World's resized targets include some without COMPRESSIBLE),
// so the test is the Metal usage the host gives it: a texture of a block-compressed format, which is an asset the game copied in, keeps an allocation of its own and so its exact size
static int rh_fits(const tex_t *t, MTLTextureUsage usage) {
    return t->pool && (t->pool->flags & NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS) && (usage & (MTLTextureUsageRenderTarget | MTLTextureUsageShaderWrite))
        && !(t->d.flags & (NVN_TEXTURE_FLAGS_DISPLAY | NVN_TEXTURE_FLAGS_VIDEO_DECODE | NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_SPARSE | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET));
}
static id<MTLTexture> rh_texture(const tex_t *t, MTLTextureDescriptor *d) { return rh_fits(t, d.usage) ? rh_place(d) : nil; }
// Shared render targets another one drew over (DM_NVN_RT_DEAD, tu_pass; alias_dead_locked says why they go; after NXNative 8653238e, by hand onto this tree's in-file sharing table).
// A texture of the sharing table that the GPU alone writes (rh_fits, tex_mtl_) and that a pool walk reads as the dummy until a pass writes it (COMPRESSIBLE, pool_unwritten_target) has a
// record here, keyed by its address, with two stamps in g_tu_now's clock: its last use and its last write by the GPU. Uses: a lookup outside a pool walk (tex_mtl_: attachments,
// copies, clears, bindings by texture object), a binding of one of its texture IDs (tex_fast, tex_fast_rid, tex_by_id; each render pass encodes its bindings again, so a texture read
// every frame is stamped every frame), a handle table kept for a new pass (htab_gpu) and a read the shaders mark in a pool (folded by the pass). A pool walk resolves every ID of the
// pool, read or not, so it stamps nothing. Writes: attach, image bindings, copy and clear destinations, DLSS output (tu_wrote). The record goes at the pass after its texture left the
// sharing table; a texture made at a freed one's address drops it (alias_put) or resets it (tu_register). Records are made only while the switch is on (or ab), so with it off, the
// default, the stamps cost one store a binding and nothing else. Under g_tu_lk, a leaf lock
typedef struct { uint32_t use, wr, pass, kept; void *fam; } tu_rec;   // kept: the use the family rule last kept it at (alias_dead_locked; tu_rec_idle), 0 none; fam: a resolution family member's family heap (NvImageHeap), as a key only
static os_unfair_lock g_tu_lk = OS_UNFAIR_LOCK_INIT; static nvn_hmap g_tu = {.klen = sizeof(uintptr_t)};
static uint32_t g_tu_now = 1, g_tu_pass_no;   // deciseconds since the first submission, plus 1 (a stamp of 0 is none), set when a submission begins; the passes so far
static int g_pool_walk;   // a pool walk is resolving its IDs (pool_gpu, on the submit thread): not uses
// g_tu_gone: serials whose texture a pass released, until it is made again (the count of those made again) or the set is full; each one's value, from its low bit up: 1 for a
// pressure pass (tu_pass_at), so never NULL; when the pass released it (g_tu_now, 32 bits); the back-off's window then (g_tu_bo_ep, 31 bits). Under g_tu_lk, as are the counts
static nvn_hmap g_tu_gone = {.klen = 8};
_Static_assert(sizeof(uintptr_t) == 8, "g_tu_gone's values hold a time and a window");
static uint64_t g_tu_remade, g_tu_press_quick;   // made again in all; of them, released by a pressure pass and made again within TU_PRESS_REMADE_DS
// The back-off's window (tu_backoff): from a low spell's start or its last step to the next, each one a number (g_tu_bo_ep). g_tu_bo_q: the targets released at pressure in the
// window and made again within TU_PRESS_REMADE_DS, so one released before a step (or before the spell began) and made again after it counts in neither window: counted, 20 of an
// earlier window's made a second step "20 of 10 textures … made again". g_tu_spell_q: those of the low spell's own releases (g_tu_spell_ep: its first window)
static uint32_t g_tu_bo_ep, g_tu_spell_ep; static uint64_t g_tu_bo_q, g_tu_spell_q;
enum { TU_PRESS_REMADE_DS = 100 };   // 10 s
static int sw_mode(const char *name, int dflt); static inline int sw_on(int m);
static int tu_mode(void) { static int m = -1; if (m < 0) m = sw_mode("DM_NVN_RT_DEAD", 1); return m; }   // on by default, as NXNative has it: 0 off, ab alternates with the DM_AB phases
static tu_rec *tu_find(id o) {   // o's record, or its parent's for a view. Caller holds g_tu_lk
    for (id x = o; x; x = [x respondsToSelector:@selector(parentTexture)] ? ((id<MTLTexture>)x).parentTexture : nil) {
        uintptr_t k = (uintptr_t)(__bridge void *)x; tu_rec *r = nvn_hm_get(&g_tu, &k); if (r) return r; }
    return NULL;
}
static int g_ls_on; static void ls_touch(id o);   // DM_NVN_LS_STATS (a use of a texture with stores pending on it)
static void tu_stamp(id o, int wrote) {
    if (__builtin_expect(g_ls_on > 0, 0)) ls_touch(o);
    if (!o || !g_tu.n) return;   // (n read unlocked: a record made meanwhile is stamped at its next use)
    uint32_t now = g_tu_now;
