// ---------- Clears a texture already holds (DM_NVN_SAME_CLEAR) ----------
// Donkey Kong Bananza clears a 2880x1620 RGBA8 target and its D32S8 depth (ser 5 / 6) every frame and nothing else touches them: a clear-only pass of its own each frame, about
// 42 MB of stores and 0.25-0.35 ms of GPU time at full clock, ~1 ms at the clock iOS caps it to (NX18-X2.0 bananza-alldata-analysis.md, fix 1b). A clear-only pass (rp_begin_ex_
// with clear_only 1: lc_land, rp_flush) records what each attachment it clears whole now holds: the texture, the format it was cleared through and the value of each plane. A later
// clear-only pass that would write the same value through the same format into a texture whose record still holds leaves that attachment out (and opens no pass when none is left):
// the texture's memory already holds exactly those bytes, so whatever reads it afterwards (an attachment load, a sample, a copy, a present, a readback) reads what it would have
// read after the clear. The proof rests on writes alone, so no read path needs a hook: every GPU write into a game texture forgets its record first. The hooks are the generic ones
// (every attachment of a draw pass as attach() sets it, tu_wrote; every other render pass's attachments at its encoder, enc_r_begin / once_pass and the upload
// clears; every blit copy's destination, enc_b_copy_*), tu_wrote's other sites (image bindings, copy and clear destinations), and MetalFX's direct outputs (DLSS, NDVE); trims and the background purge forget every record, as the system may take a
// volatile texture's memory. Only textures no other write can reach take a record (sc_eligible): a CPU_NO_ACCESS pool's private 2D texture of one level and one layer, single-sampled,
// not over a buffer, not sparse or lazily backed, not block-compressed, and without the shader-write usage (a texture an image store could write is a new texture once it gets that usage,
// tex_upgrade). A record names its texture weakly, so a texture freed and another made at its address is not taken for it. The skipped attachment still gets the write stamp the
// pass would have given it (tu_stamp: the drawn-over render target rule keeps seeing it used). DM_NVN_SAME_CLEAR=0 opens every clear-only pass as before
// Clear triangles (DM_NVN_SAME_CLEAR_TRI): that Bananza pass was never clear-only. The game clears depth whole and stencil with a write mask of 0x1 (nvnCommandBufferClearDepthStencil),
// and a masked stencil clear was drawn as a triangle (clear_ds_tri) in a pass it opened at once, a draw pass (rp_begin) that no record came out of. Such a clear (no pass open, over the whole
// target, a target that can take a record) now waits as the other clears do (R.clear_sm, R.csm: the mask and the masked value; a newer one folds in, a full stencil clear pending or newer folds
// it into a load-action clear) and is drawn when its pass opens: right after the encoder begins, before anything else, the triangle clear_ds_tri drew (compare always, replace through the
// write mask, no depth write, the whole target as viewport and scissor, no blending: its result is (old & ~mask) | (value & mask) whatever the old content). A stencil record keeps which bits
// it knows (g_sc_sk; a load-action clear knows all 8): taken before attach() forgets it, the pass's triangle adds its mask's bits, and a clear-only pass whose triangle writes bits the record
// holds with those values leaves the stencil out like a held clear (sc_skip_held); with its colour and depth held too the pass is not opened. A pass a draw opens takes the triangle the
// same way and records nothing. DM_NVN_SAME_CLEAR_TRI=0 draws such a clear at once as before (fcdc1fd0)
enum { SC_MAX = 8, SC_COLOR = 1, SC_DEPTH = 2, SC_STENCIL = 4 };
static __weak id<MTLTexture> g_sc_tex[SC_MAX];   // the records: texture (root), the attachment's pixel format, which planes hold a known clear and their values. Under g_sc_lk
static MTLPixelFormat g_sc_pf[SC_MAX]; static uint8_t g_sc_have[SC_MAX]; static MTLClearColor g_sc_cc[SC_MAX]; static double g_sc_cd[SC_MAX]; static uint32_t g_sc_cs[SC_MAX];
static uint8_t g_sc_sk[SC_MAX];   // the stencil bits the record knows (g_sc_cs holds them; the others are 0 there)
static uint64_t g_sct_pass, g_sct_bytes;   // clear-only passes with a stencil triangle not opened, and the attachment loads and stores they would have made (DM_NVN_SAME_CLEAR_TRI)
void mtl_sct_stats(uint64_t *pass, uint64_t *bytes) { *pass = g_sct_pass; *bytes = g_sct_bytes; }
static _Atomic int g_nsc; static os_unfair_lock g_sc_lk = OS_UNFAIR_LOCK_INIT; static int g_sc_next;
static uint64_t g_sc_att, g_sc_pass, g_sc_bytes;
static uint64_t g_fb_dclr;   // depth / stencil clears and writes other than drawing into depth textures so far: a depth snapshot taken before one is not reused by a reading draw (fb_dsnap_live, DM_NVN_FB_DSNAP)   // attachments left out of clear-only passes, passes not opened at all, the stores those attachments would have made
void mtl_sc_stats(uint64_t *att, uint64_t *pass, uint64_t *bytes) { *att = g_sc_att; *pass = g_sc_pass; *bytes = g_sc_bytes; }
static int g_sc_on = -1;   // DM_NVN_SAME_CLEAR, read once (a unit test may set it)
static int sc_on(void) { if (g_sc_on < 0) { const char *e = getenv("DM_NVN_SAME_CLEAR"); g_sc_on = !(e && !strcmp(e, "0")); if (!g_sc_on) MLOG("DM_NVN_SAME_CLEAR=0: a clear-only pass opens even when its texture already holds the clear"); } return g_sc_on; }
static int g_sct_on = -1;   // DM_NVN_SAME_CLEAR_TRI, read once (a unit test may set it)
static int sct_on(void) { if (g_sct_on < 0) { const char *e = getenv("DM_NVN_SAME_CLEAR_TRI"); g_sct_on = !(e && !strcmp(e, "0")); if (!g_sct_on) MLOG("DM_NVN_SAME_CLEAR_TRI=0: a masked stencil clear is drawn at once in a pass of its own as before"); } return g_sct_on && sc_on(); }
static id<MTLTexture> sc_root(id<MTLTexture> in) { id<MTLTexture> t = in; while (t.parentTexture) t = t.parentTexture; return t; }
static void sc_forget(id<MTLTexture> in) {   // a GPU write into in (or a view of it) is about to be encoded
    if (!in || !atomic_load_explicit(&g_nsc, memory_order_relaxed)) return;
    id<MTLTexture> t = sc_root(in);
    os_unfair_lock_lock(&g_sc_lk);
    for (int i = 0; i < SC_MAX; i++) if (g_sc_have[i]) { id<MTLTexture> r = g_sc_tex[i]; if (!r || r == t) { g_sc_tex[i] = nil; g_sc_have[i] = 0; atomic_fetch_sub(&g_nsc, 1); } }
    os_unfair_lock_unlock(&g_sc_lk);
}
static void sc_forget_all(void) {
    if (!atomic_load_explicit(&g_nsc, memory_order_relaxed)) return;
    os_unfair_lock_lock(&g_sc_lk); for (int i = 0; i < SC_MAX; i++) { g_sc_tex[i] = nil; g_sc_have[i] = 0; } atomic_store(&g_nsc, 0); os_unfair_lock_unlock(&g_sc_lk);
}
static void sc_forget_pd(MTL4RenderPassDescriptor *d) {   // every attachment of a render pass about to begin (not the draw passes, whose attach() forgets each: a scan costs ~0.5 us a pass)
    if (!d || !atomic_load_explicit(&g_nsc, memory_order_relaxed)) return;
    for (int i = 0; i < 8; i++) { MTLRenderPassColorAttachmentDescriptor *c = d.colorAttachments[i]; if (c.texture) sc_forget(c.texture); if (c.resolveTexture) sc_forget(c.resolveTexture); }
    if (d.depthAttachment.texture) sc_forget(d.depthAttachment.texture);
    if (d.stencilAttachment.texture) sc_forget(d.stencilAttachment.texture);
}
// Whether root's record holds plane (SC_*) with this value through pixel format pf
static int sc_holds(id<MTLTexture> root, MTLPixelFormat pf, int plane, const MTLClearColor *cc, double cd, uint32_t cs) {
    if (!root || !atomic_load_explicit(&g_nsc, memory_order_relaxed)) return 0;
    int hit = 0;
    os_unfair_lock_lock(&g_sc_lk);
    for (int i = 0; i < SC_MAX && !hit; i++) if ((g_sc_have[i] & plane) && g_sc_pf[i] == pf) { id<MTLTexture> r = g_sc_tex[i]; if (r != root) continue;
        hit = plane == SC_COLOR ? !memcmp(&g_sc_cc[i], cc, sizeof *cc) : plane == SC_DEPTH ? !memcmp(&g_sc_cd[i], &cd, sizeof cd) : g_sc_sk[i] == 0xff && g_sc_cs[i] == (cs & 0xff); }
    os_unfair_lock_unlock(&g_sc_lk);
    return hit;
}
// The stencil bits root's record knows through pf (*known, 0 = none) and their values (*val)
static void sc_stencil_known(id<MTLTexture> root, MTLPixelFormat pf, uint8_t *known, uint32_t *val) {
    *known = 0; *val = 0;
    if (!root || !atomic_load_explicit(&g_nsc, memory_order_relaxed)) return;
    os_unfair_lock_lock(&g_sc_lk);
    for (int i = 0; i < SC_MAX; i++) if ((g_sc_have[i] & SC_STENCIL) && g_sc_pf[i] == pf) { id<MTLTexture> r = g_sc_tex[i]; if (r == root) { *known = g_sc_sk[i]; *val = g_sc_cs[i]; break; } }
    os_unfair_lock_unlock(&g_sc_lk);
}
// After a clear-only pass began: root's plane now holds this value (attach() forgot root's record before, tu_wrote)
static void sc_note_sk(id<MTLTexture> root, MTLPixelFormat pf, int plane, const MTLClearColor *cc, double cd, uint32_t cs, uint8_t sk);
static void sc_note(id<MTLTexture> root, MTLPixelFormat pf, int plane, const MTLClearColor *cc, double cd, uint32_t cs) { sc_note_sk(root, pf, plane, cc, cd, cs, 0xff); }
// As sc_note; for the stencil plane sk: the bits known (cs holds their values)
static void sc_note_sk(id<MTLTexture> root, MTLPixelFormat pf, int plane, const MTLClearColor *cc, double cd, uint32_t cs, uint8_t sk) {
    os_unfair_lock_lock(&g_sc_lk);
    int k = -1;
    for (int i = 0; i < SC_MAX && k < 0; i++) if (g_sc_have[i]) { id<MTLTexture> r = g_sc_tex[i]; if (r == root && g_sc_pf[i] == pf) k = i; }
    if (k < 0) { for (int i = 0; i < SC_MAX && k < 0; i++) if (!g_sc_have[i]) k = i;
        if (k < 0) { k = g_sc_next++ % SC_MAX; g_sc_have[k] = 0; atomic_fetch_sub(&g_nsc, 1); }
        g_sc_tex[k] = root; g_sc_pf[k] = pf; atomic_fetch_add(&g_nsc, 1); }
    g_sc_have[k] |= (uint8_t)plane;
    if (plane == SC_COLOR) g_sc_cc[k] = *cc; else if (plane == SC_DEPTH) g_sc_cd[k] = cd; else { g_sc_cs[k] = cs & sk; g_sc_sk[k] = sk; }
    os_unfair_lock_unlock(&g_sc_lk);
}
static void bg_pkg_gpu_wrote(id<MTLTexture> t);
static void tu_wrote(id o) { sc_forget((id<MTLTexture>)o); tu_stamp(o, 1); bg_pkg_gpu_wrote((id<MTLTexture>)o); }
static void tu_register(id<MTLTexture> t, uint64_t serial) {
    uintptr_t k = (uintptr_t)(__bridge void *)t; void *fam = (__bridge void *)objc_getAssociatedObject(t, &g_image_heap_owner_key);   // set when it was made (image_texture), never changed
    os_unfair_lock_lock(&g_tu_lk);
