    return sw_on(g_pw_mode);
}
// The prefix of a number-ordered array below seq (binary search)
#define SEQ_BELOW(arr, cnt, lim) ({ size_t lo_ = 0, hi_ = (cnt); while (lo_ < hi_) { size_t mid_ = (lo_ + hi_) / 2; if ((arr)[mid_].seq < (lim)) lo_ = mid_ + 1; else hi_ = mid_; } lo_; })
static fwire_t *fw_take(fwire_t *v, size_t *cnt, size_t k) {   // the first k of v (a copy), the rest moved down; caller holds g_res_mu
    if (!k) return NULL;
    fwire_t *o = realloc_or_die(NULL, k * sizeof *o, "the wired file ranges"); memcpy(o, v, k * sizeof *o);
    memmove(v, v + k, (*cnt - k) * sizeof *v); *cnt -= k; return o;
