static void fw_append(fwire_t **v, size_t *cnt, size_t *cap, const fwire_t *w, size_t k) {   // caller holds g_res_mu
    if (*cnt + k > *cap) { size_t c = *cap ? *cap : 64; while (c < *cnt + k) c *= 2; *v = realloc_or_die(*v, c * sizeof **v, "the wired file ranges"); *cap = c; }
    memcpy(*v + *cnt, w, k * sizeof *w); *cnt += k;
