    if ((g_nfwire && g_fwire[0].seq < want) || (g_pw_busy && g_pw_lo < want)) { res_mu_unlock(); res_commit_unlock(); return 0; }
    size_t n = SEQ_BELOW(g_res_q, g_res_qn, want), nfw = SEQ_BELOW(g_fwired, g_nfwired, want);
