}
// As before (DM_NVN_RES_PREWIRE=0): the whole queue, its file ranges wired under the lock. A prewire of the other phase (=ab) finishes first, and what it wired is given back here
static void res_commit_all(const char *site) {
    res_commit_lock_at(site);
    res_mu_lock();
    while (g_pw_busy) pthread_cond_wait(&g_pw_cv, &g_res_mu);
    uint64_t want = atomic_load_explicit(&g_res_seq, memory_order_relaxed);
    res_op *q = g_res_q; size_t n = g_res_qn; g_res_q = NULL; g_res_qn = g_res_qcap = 0;
    fwire_t *fw = g_fwire; size_t nfw = g_nfwire; g_fwire = NULL; g_nfwire = g_cfwire = 0;   // the file pages wired for exactly these changes
    fwire_t *fwd = g_fwired; size_t nfwd = g_nfwired; g_fwired = NULL; g_nfwired = g_cfwired = 0;
