// Applies and commits every change numbered below want (0: every change made before the call). A change another thread's commit took is in the set and released when this returns
// too: that commit holds g_res_commit_mu, and marks the changes done (g_res_done), only once it has committed them and dropped its queue references. Each change holds its allocation until it is committed, so a removed one stays alive until it has left the set. No feedback
// handler calls it (res_commit_async)
#define res_commit() res_commit_to(0, LOCK_SITE)
static void res_commit_to_(uint64_t want, const char *site);
static void res_commit_to(uint64_t want, const char *site) { int pf = pf_enter(PF_RES); res_commit_to_(want, site); pf_leave(pf); }   // page-ins by part (PF_RES)
static void res_commit_to_(uint64_t want, const char *site) { @autoreleasepool {
    if (!pw_on()) { res_commit_all(site); return; }
    if (!want) want = atomic_load_explicit(&g_res_seq, memory_order_relaxed);
    for (;;) {
        if (atomic_load_explicit(&g_res_done, memory_order_acquire) >= want) return;
        res_mu_lock();
