// GPU memory full (gpu_lost_take GL_OOM; ported from S2Arm 966e78cae, Apache-2.0): the residency set emptied and committed at once, the changes queued for it and the file ranges
// noted for them dropped, and its books emptied with it, so the memory it pinned (on iOS wired memory the whole phone shares) goes back now, not at the process's end. Nothing is
// committed to the GPU any more (gpu_gone), so no command buffer uses what left; res_commit drops what is queued later. On the residency commit worker (res_commit_async's
// queue), never on the feedback queue that saw the error. A hang does not empty it: what it holds stays for the dump
static dispatch_queue_t res_commit_q(void);
static void res_drop_all(void) { @autoreleasepool {
    res_commit_lock(); res_mu_lock();
    while (g_pw_busy) pthread_cond_wait(&g_pw_cv, &g_res_mu);   // a prewire under way (DM_NVN_RES_PREWIRE) holds ranges of the changes dropped here
    res_op *q = g_res_q; size_t n = g_res_qn; g_res_q = NULL; g_res_qn = g_res_qcap = 0;
    fwire_t *fw = g_fwire; g_fwire = NULL; g_nfwire = g_cfwire = 0;
    fwire_t *fwd = g_fwired; size_t nfwd = g_nfwired; g_fwired = NULL; g_nfwired = g_cfwired = 0;
    [g_res_objects removeAllObjects];
    atomic_store_explicit(&g_res_done, atomic_load_explicit(&g_res_seq, memory_order_relaxed), memory_order_release);   // the queued changes are dropped
    res_mu_unlock();
