    if (fwd) file_unwire(fwd, nfwd);
    res_commit_unlock();
    free(fw); for (size_t i = 0; i < n; i++) CFRelease(q[i].o); free(q);
    MLOG("[RED] GPU memory full: the residency set emptied at once: %lu allocations, %.0f MB given back (%zu queued changes dropped)", (unsigned long)k, b / 1048576.0, n);
} }
// The residency commit worker: a serial queue of its own (user-interactive, as g_feedback_q). Every Metal 4 commit feedback handler runs on the one serial queue g_feedback_q, and
// the upload batch's handler (the staging it retires) and the one-off command buffer's (what once_use made resident) committed the residency set there, under g_res_commit_mu:
// one long [g_res commit], or a wait for a long commit or queue commit on another thread, held back every completion behind it, g_done and the presents' with it, and said nothing
// (Ocarina of Time's test 3 froze once with nothing in the log; this was one of the paths the audits could not rule out). The handlers now only queue the removal (res_remove: a
// moment under g_res_mu, never g_res_commit_mu) and hand the commit here; after (may be nil) runs once it is done, on this queue. The rule that a removal is committed only once the
// GPU is done with what it removes holds as before: the handler queues it, so only after the GPU has finished that command buffer, and any commit after that takes it (this one,
// or another thread's first: the next submission's, an upload flush's, defer_kick's), as defer_drain's removals have always been taken. A removed allocation stays alive, held by
// its queued change, until that commit; the upload batch counts as pending until then (g_up_pending, which mtl_finish and the drain wait for), so what was true when the drain or
// nvnQueueFinish returned (the staging gone from the set and freed) still is
static dispatch_queue_t res_commit_q(void) {
    static dispatch_once_t once; static dispatch_queue_t q;
    dispatch_once(&once, ^{ q = dispatch_queue_create("dm.nvn.res-commit", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_USER_INTERACTIVE, 0)); });
    return q;
}
// The worker's state, for the freeze detector's dump and up_wait_zero's 10 s line (rcw_text): an upload batch whose staging's removal the worker has not committed yet stays pending
// (g_up_pending) with its feedback handler long done and its slot free, so without it those lines read "1 pending ... feedback handler none running", as if the GPU had never
// finished the batch, when the worker is waiting for the residency commit lock or is inside a long [g_res commit]. g_rcw_n: commits handed here and not finished; g_rcw_at: when
// the current one began (mach_absolute_time, 0 between them). Relaxed atomics, a few per handed-off commit (upload batches that retire staging, one-off command buffers)
static _Atomic int g_rcw_n; static _Atomic uint64_t g_rcw_at;
static void res_commit_async(dispatch_block_t after) {
    atomic_fetch_add_explicit(&g_rcw_n, 1, memory_order_relaxed);
    dispatch_async(res_commit_q(), ^{ @autoreleasepool {
        atomic_store_explicit(&g_rcw_at, mach_absolute_time(), memory_order_relaxed);
        res_commit(); if (after) after();
        atomic_store_explicit(&g_rcw_at, 0, memory_order_relaxed); atomic_fetch_sub_explicit(&g_rcw_n, 1, memory_order_relaxed);
    } });
}
static void rcw_text(char *out, size_t n, uint64_t now) {
    int k = atomic_load_explicit(&g_rcw_n, memory_order_relaxed); uint64_t at = atomic_load_explicit(&g_rcw_at, memory_order_relaxed);
    if (k <= 0) snprintf(out, n, "idle");
    else if (at && now >= at) snprintf(out, n, "%d commit%s queued, the current one for %.1f s", k, k == 1 ? "" : "s", mach_s(now - at));
    else snprintf(out, n, "%d commit%s queued, none begun", k, k == 1 ? "" : "s");
}
static int res_pending(void) { res_mu_lock(); int n = g_res_qn != 0; res_mu_unlock(); return n; }
// ---------- Residency commits off the replay thread (DM_NVN_RES_ASYNC) ----------
// Ocarina of Time's area loads on the iPhone 18 Pro Max (e2b4122f, NX18-X2.0 oot-alldata-analysis.md item 7) spent 142-300 ms of a load frame in residency commits on the replay
// thread: 15 to 117 commits, each taken on the spot where something joined the set (a pool's first lookup, the raw pool table's pools, each upload batch, each submission), one of
// 1,921 pools and 860 MB, a window of 1.6 GB of guest-file pages wired before their commits (an mlock that pages them in) and one commit of 405 ms; the replay waited out each one.
// What the rule needs is only that a resource is in the committed set before the GPU runs a command buffer that uses it, i.e. before that command buffer's queue commit. So with
// the encode thread (where the replay's queue commits are records the encode thread commits later) the replay hands its commits to the residency commit worker
// (res_commit_soon): it queues its changes as before, starts the worker on them if it is not already queued, and goes on translating. The worker takes every change queued by
// the time it starts, so a load's dozens of commits become a few, and their file wiring runs there too. The encode thread commits whatever is still queued, under
// g_res_commit_mu, just before each queue commit (rca_queue_guard): a change recorded before a command buffer is in the set by the time that command buffer is committed, as
// res_commit waits for a commit under way (the worker's) and then commits the rest itself. Without the encode thread only the pool lookups and the raw pool table hand off (the
// submission's own commit and the upload batch's still come right before their queue commits, on this thread, and wait for the worker's). A present, a one-off command buffer
// and every other thread's commit stay as they were (res_commit), and wait for the worker's commit under way as for any other.
// =0 commits on the spot again; =ab alternates with DM_AB. The residency line gives the commits by where they ran (g_rca_n)
static int g_rca_mode = -1;
static int rca_mode(void) {
    if (g_rca_mode < 0) { int m = sw_mode("DM_NVN_RES_ASYNC", 1); if (m != 1) MLOG("DM_NVN_RES_ASYNC=%d: the replay commits the residency set on the spot%s", m, m ? " in the other A/B phases" : ""); g_rca_mode = m; }
    return g_rca_mode;
}
static _Atomic int g_rca_kicked;      // a worker run is queued and has not started: a later hand-off needs none of its own
static _Atomic int g_pool_res_open;   // pool adds not committed yet (pool_res, below)
static _Atomic int g_pool_res_lazy;   // pool adds handed off (g_pool_res_open), closed by the worker run that commits them
static _Atomic uint64_t g_rca_soon, g_rca_kicks;   // hand-offs, worker runs started for them (the residency line)
static void rca_kick(void) {
    if (atomic_exchange(&g_rca_kicked, 1)) return;
    atomic_fetch_add_explicit(&g_rca_kicks, 1, memory_order_relaxed);
    atomic_fetch_add_explicit(&g_rcw_n, 1, memory_order_relaxed);
    dispatch_async(res_commit_q(), ^{ @autoreleasepool {
        atomic_store(&g_rca_kicked, 0);   // before the commit takes the queue: a hand-off after this point starts another run
        int k = atomic_exchange(&g_pool_res_lazy, 0);   // pool adds counted before the commit takes the queue were queued before it (pool_res_commit counts after res_add)
        atomic_store_explicit(&g_rcw_at, mach_absolute_time(), memory_order_relaxed);
        t_rca_role = 1; res_commit(); t_rca_role = 0;
        if (k) atomic_fetch_sub(&g_pool_res_open, k);
        atomic_store_explicit(&g_rcw_at, 0, memory_order_relaxed); atomic_fetch_sub_explicit(&g_rcw_n, 1, memory_order_relaxed);
    } });
}
// Commits what is queued (res_commit), or on the replay thread with DM_NVN_RES_ASYNC hands it to the worker and returns at once (1). queue: the caller's queue commit is a record
// of the encode thread (rec_on, encode thread started), which commits what is left before it; 0 for a hand-off whose GPU use goes through a later submission or upload batch.
// pool_added: pool adds this commit closes (g_pool_res_open)
static int res_commit_soon(int queue, int pool_added) {
    int m = rca_mode();
    if (!m || !sw_on(m) || !on_sub_thread() || (queue && !(rec_on() && g_rb_started))) {
        res_commit(); if (pool_added) atomic_fetch_sub(&g_pool_res_open, pool_added);
        return 0;
    }
    atomic_fetch_add_explicit(&g_rca_soon, 1, memory_order_relaxed);
    if (pool_added) atomic_fetch_add(&g_pool_res_lazy, pool_added);
    if (pool_added || res_pending()) rca_kick();
