}
// The encode thread, before each queue commit: what the replay handed off is in the set first (any change queued before the record was put). seq: the number the next change had
// when the record was put (res_seq_now; 0 not known: every change made so far), with the encode thread's own changes since (t_res_seq: a framework's encoding, RO_CB_BLOCK). With
// DM_NVN_RES_PREWIRE that is all it commits or waits for: changes the replay made after the record (the worker paging in the next frame's uploads) are not this command buffer's.
// =0: every change queued so far, and a worker commit under way is waited for, as before
static uint64_t res_seq_now(void) { return atomic_load_explicit(&g_res_seq, memory_order_relaxed); }
static void rca_queue_guard(uint64_t seq) {
    if (g_rca_mode <= 0) return;
    uint64_t want = 0;
    if (pw_on()) {
        atomic_fetch_add_explicit(&g_rg_n, 1, memory_order_relaxed);
        want = seq ? (seq > t_res_seq ? seq : t_res_seq) : res_seq_now();
        if (atomic_load_explicit(&g_res_done, memory_order_acquire) >= want) { atomic_fetch_add_explicit(&g_rg_skip, 1, memory_order_relaxed); return; }
    }
