}
void mtl_res_stats(char *out, size_t n) {
    res_commit_lock();   // the set's counts, which a commit changes
    unsigned long set_n = g_res ? (unsigned long)g_res.allocationCount : 0ul; double set_mb = g_res ? g_res.allocatedSize / 1048576.0 : 0;
    res_commit_unlock();
    res_mu_lock();
    uint64_t tn = 0, tb = 0; for (int k = 0; k < RS_SITES; k++) { tn += g_rs_site[k].n; tb += g_rs_site[k].bytes; }
    size_t o = snprintf(out, n, "commits %llu / %.1f ms", (unsigned long long)g_rs_commits, g_rs_commit_ns / 1e6);
    uint64_t soon = atomic_exchange(&g_rca_soon, 0), kicks = atomic_exchange(&g_rca_kicks, 0);
    if (o < n && (soon || g_rca_n[1] || g_rca_n[2]))   // DM_NVN_RES_ASYNC: where they ran, and the replay's hand-offs
        o += snprintf(out + o, n - o, " (on the replay thread %llu / %.1f ms, on the commit worker %llu / %.1f ms, before a queue commit %llu / %.1f ms; the replay handed off %llu, the worker ran %llu times for it)",
                      (unsigned long long)g_rca_n[0], g_rca_ns[0] / 1e6, (unsigned long long)g_rca_n[1], g_rca_ns[1] / 1e6, (unsigned long long)g_rca_n[2], g_rca_ns[2] / 1e6,
                      (unsigned long long)soon, (unsigned long long)kicks);
    memset(g_rca_n, 0, sizeof g_rca_n); memset(g_rca_ns, 0, sizeof g_rca_ns);
    { uint64_t rg = atomic_exchange(&g_rg_n, 0), rgs = atomic_exchange(&g_rg_skip, 0);   // DM_NVN_RES_PREWIRE: page-ins outside the lock, the waits for one, the guards that had nothing to wait for
      if (o < n && (g_rpw_n || g_rpw_waits || rg))
          o += snprintf(out + o, n - o, " (prewired outside the lock %llu, %.0f MB, %.1f ms; waits for a prewire %llu, %.1f ms, the longest %.1f ms; queue-commit guards %llu, %llu of them with their changes committed)",
                        (unsigned long long)g_rpw_n, g_rpw_bytes / 1048576.0, g_rpw_ns / 1e6, (unsigned long long)g_rpw_waits, g_rpw_wait_ns / 1e6, g_rpw_wait_max / 1e6, (unsigned long long)rg, (unsigned long long)rgs);
      g_rpw_n = g_rpw_bytes = g_rpw_ns = g_rpw_waits = g_rpw_wait_ns = g_rpw_wait_max = 0; }
    if (o < n) o += snprintf(out + o, n - o, ", added %llu, %.0f MB (", (unsigned long long)tn, tb / 1048576.0);
    for (int i = 0; i < 4 && o < n; i++) { int best = -1; for (int k = 0; k < RS_SITES; k++) if (g_rs_site[k].n && (best < 0 || g_rs_site[k].bytes > g_rs_site[best].bytes)) best = k;
        if (best < 0) break; o += snprintf(out + o, n - o, "%sline %d: %llu, %.0f MB", i ? ", " : "", g_rs_site[best].line, (unsigned long long)g_rs_site[best].n, g_rs_site[best].bytes / 1048576.0); g_rs_site[best].n = 0; }
    if (o < n) o += snprintf(out + o, n - o, "), removed %llu, %lu allocations in the set (%.0f MB)", (unsigned long long)g_rs_rm, set_n, set_mb);
    // How often a pass drew into a depth or compressed texture through a shadow, and whether the shadow cache kept up: in Luigi's Mansion 3 'made' was about 3 a frame before the cache was
    // keyed by format and size (bcrt_slot), each one a texture, a buffer and residency commits; a few in all, then none, once it was. Passes times 4 copies is what the shadows cost in copies
    uint64_t bp = atomic_exchange(&g_bcrt_passes, 0), bm = atomic_exchange(&g_bcrt_made, 0), bu = atomic_exchange(&g_bcrt_reused, 0), br = atomic_exchange(&g_bcrt_retired, 0);
    if (o < n && (bp || bm || br)) snprintf(out + o, n - o, "; render-target shadows: passes %llu, made %llu, reused %llu, retired %llu, %.1f MB kept", (unsigned long long)bp, (unsigned long long)bm,
                                           (unsigned long long)bu, (unsigned long long)br, atomic_load(&g_bcrt_bytes) / 1048576.0);
    memset(g_rs_site, 0, sizeof g_rs_site); g_rs_rm = g_rs_commits = g_rs_commit_ns = 0;
    res_mu_unlock();
}

@interface NvDeferredRelease : NSObject { @public id object; uint64_t fence; int keep_resident; } @end
@implementation NvDeferredRelease @end
static NSMutableArray<NvDeferredRelease *> *g_deferred;
static pthread_mutex_t g_deferred_mu = PTHREAD_MUTEX_INITIALIZER;
// Deferred release has two meanings that must be kept apart (the root of the GPU memory fault on the first frame on entering Travincal):
//   defer_obj_release = this object is retired: drop the reference after the submissions that used it complete, and remove it from the residency set once no serial entry holds it (g_retire_held);
//   defer_obj_unref   = only the reference I hold is no longer wanted, the object itself may still be in use (the view cache of a texture ID may hold the base texture itself): only drop the reference, leave the residency set alone.
// Previously only the former existed: when the view cache was invalidated, a texture that 'is still the current storage of some serial' was also removed from the residency set. Invalidation used to happen only when the base texture was really replaced, so it was never hit;
// after the transparency chain's in-place composite swapped the storage of two textures, each of the two live textures was removed once this way, and afterwards they are used as attachments and sampled every frame as usual - the GPU accesses non-resident memory.
static void defer_kick(void);
// Most objects wait for the next submission's fence. A caller that knows no submission still to come can reach the object passes an earlier one (mtl_pool_del); a fence the GPU has
// already passed is then drained at once (defer_kick), as no feedback handler is left to do it
static void defer_obj_at(id obj, int keep_resident, uint64_t fence) {
    if (!obj) return;
    NvDeferredRelease *d = [NvDeferredRelease new]; d->object = obj; d->fence = fence; d->keep_resident = keep_resident;
    pthread_mutex_lock(&g_deferred_mu);
    if (!g_deferred) g_deferred = [NSMutableArray array];
    [g_deferred addObject:d];
    pthread_mutex_unlock(&g_deferred_mu);
    // After the entry is in: a feedback handler stores g_done before it drains, so either its drain finds the entry or this load sees its fence
    if (fence <= atomic_load(&g_done)) defer_kick();
}
static void defer_obj_release(id obj) { defer_obj_at(obj, 0, g_fence + 1); }
static void defer_obj_unref(id obj) { defer_obj_at(obj, 1, g_fence + 1); }
static pthread_mutex_t g_smu; static int entry_holds(const void *o); static void retire_wait(id o);   // defined below (the serial table)
// Its own autorelease pool: mtl_sub_begin drains before it pushes the submission's pool, on the guest submit thread, whose implicit pool is never drained. The weak-table lookups and the residency-set removal
// autorelease the retired object, so whatever that thread drained (instead of the completion handler, which wins the race only when the CPU is idle) stayed alive for good: in Metroid Dread every
// re-upload of its map mask kept the old texture and its 32 MB upload staging block, and GPU memory grew by several GB within minutes under CPU load.
// → how many finished entries it handed back to the queue (g_smu busy)
static int defer_drain(void) { int back = 0; @autoreleasepool {
    NSMutableArray<NvDeferredRelease *> *ready = [NSMutableArray array];
    pthread_mutex_lock(&g_deferred_mu);
    // One pass that keeps the rest: removing each from the middle moved the whole tail, quadratic in the queue, which a scene load fills (PR 1444 saw minutes in memmove)
    uint64_t done = g_done; NSMutableArray<NvDeferredRelease *> *keep = nil;
    for (NvDeferredRelease *d in g_deferred) if (d->fence <= done) { [ready addObject:d]; }
    if (ready.count) { keep = [NSMutableArray arrayWithCapacity:g_deferred.count - ready.count]; for (NvDeferredRelease *d in g_deferred) if (d->fence > done) [keep addObject:d]; g_deferred = keep; }
    pthread_mutex_unlock(&g_deferred_mu);
    // A retired resource a serial entry still holds keeps its residency (g_retire_held). g_smu is only tried: this runs on the completion handler's thread too, which must not wait on
    // the submit thread's long holds; when it is busy, those entries wait for the next drain
    // Each entry is sorted once, here, into the resources that may leave the residency set and the rest. When g_smu is busy, the rest are drained now and the resources go back to
    // g_deferred: from then on they belong to whichever drain takes them next (the submit thread or a completion handler), which releases the object and clears d->object. So nothing
    // here may read an entry it has handed back: sorting them again after the hand-back sent conformsToProtocol: to an object another drain had just freed (a crash in
    // class_conformsToProtocol from a completion handler, ROMANCE OF THE THREE KINGDOMS XIV in its main menu)
    NSMutableArray<NvDeferredRelease *> *res_ready = nil, *rest = [NSMutableArray arrayWithCapacity:ready.count];
    for (NvDeferredRelease *d in ready) {
        if (!d->keep_resident && [d->object conformsToProtocol:@protocol(MTLResource)]) { if (!res_ready) res_ready = [NSMutableArray array]; [res_ready addObject:d]; }
        else [rest addObject:d];
    }
    if (res_ready && !pthread_mutex_trylock(&g_smu)) {
        for (NvDeferredRelease *d in res_ready) if (entry_holds((__bridge void *)d->object)) { retire_wait(d->object); d->keep_resident = 1; }
        pthread_mutex_unlock(&g_smu);
    } else if (res_ready) {
        ready = rest; back = (int)res_ready.count;
        pthread_mutex_lock(&g_deferred_mu); [g_deferred addObjectsFromArray:res_ready]; pthread_mutex_unlock(&g_deferred_mu);
    }
    for (NvDeferredRelease *d in ready) {
        id obj = d->object;
        if (g_res_check_on) { res_mu_lock(); NSArray *u = [g_res_last_use objectForKey:obj]; res_mu_unlock();
            CFIndex refs = CFGetRetainCount((__bridge CFTypeRef)obj);   // d, obj and the array's enumeration hold some; a released object has nobody else
            if (u && [u[0] unsignedLongLongValue] > d->fence && (!d->keep_resident || refs <= 3) && g_res_late++ < 40) {
                int is_tex = [obj conformsToProtocol:@protocol(MTLTexture)]; id<MTLTexture> t = is_tex ? obj : nil;
                MLOG("[RED] released too early #%llu: %s %p (%lux%lu format %lu) retired behind fence %llu, bound by shader %s in submission %llu; %s, references %ld", (unsigned long long)g_res_late, is_tex ? "texture" : "object", (__bridge void *)obj, (unsigned long)t.width, (unsigned long)t.height, (unsigned long)t.pixelFormat, (unsigned long long)d->fence, [u[1] UTF8String], [u[0] unsignedLongLongValue], d->keep_resident ? "reference dropped" : "out of the residency set", (long)refs); } }
        if (!d->keep_resident && [obj conformsToProtocol:@protocol(MTLResource)]) {
            res_mu_lock();
            int registered = [g_res_objects containsObject:obj];
            res_mu_unlock();
            if (registered) res_remove((id<MTLResource>)obj);
        }
        d->object = nil;
    }
} return back; }
// A drain off the submit thread for entries whose fence had passed when they were queued. Between submissions no feedback handler comes: Ocarina of Time out of focus waits in
// oe::PopNotificationMessage and submits nothing, while its streaming threads remade a run of about 10 MB of a virtual pool 70 times a second (vrun_set). Each old buffer waited for
// the next submission's fence, and GPU allocated went from 11 to 20 GB in 12 s, with 6.7 GB of swap in 20 s (PR #1392). Entries handed back while g_smu was busy are tried again 10 ms later.
// Each such drain, from its dispatch to the end of its residency commit, and each retry from the moment it is scheduled, is in one group (defer_kick_group): they run on a global
// queue, which nothing can wait for, and the commit that ends one drops the last reference to what it retires, on a utility thread, after the drain that queued it has returned (a
// feedback handler's, whose fence the submit thread may have seen pass already). A test that counts what is freed waits for the group (t_depth_lazy's settle)
static dispatch_group_t defer_kick_group(void) { static dispatch_once_t once; static dispatch_group_t g; dispatch_once(&once, ^{ g = dispatch_group_create(); }); return g; }
static void defer_kick(void) {
    static _Atomic int queued;
    if (atomic_exchange(&queued, 1)) return;
    dispatch_group_t g = defer_kick_group();
    dispatch_group_async(g, dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{ @autoreleasepool {
        atomic_store(&queued, 0);   // before the drain: an entry queued during it kicks again
        int back = defer_drain(); res_commit();
        if (back) { dispatch_group_enter(g); dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 10 * NSEC_PER_MSEC), dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{ defer_kick(); dispatch_group_leave(g); }); }
    } });
}
// What a drain takes out of the residency set leaves it, and is released, at the set's next commit, which the next submission makes. With none open none may come: the drain is
// committed off this thread then (a feedback handler's, or the submit thread closing its submission). Each side writes, then reads the other's state behind a full fence, so one of
// them sees what is left
static void defer_idle_commit(void) {
    atomic_thread_fence(memory_order_seq_cst);
    if (atomic_load(&g_sub_open)) return;
    if (res_pending()) defer_kick();
}

// A profile list of shader keys the host asks the next shader build for (bf_want.tsv, dual_want.tsv): each key appended once to the file the environment names. A shader's key is
// its 16 hex digits, with or without the route suffix (NvShader keys are "<key>_b"), as dmsh_build.py reads the list
typedef struct { const char *env; pthread_mutex_t mu; char **keys; size_t n, cap; int loaded; } want_list;
static void want_note(want_list *w, const char *key) {
    const char *path = getenv(w->env);
    if (!path || !key || strlen(key) < 16 || (key[16] && key[16] != '_')) return;
    for (int i = 0; i < 16; i++) if (!((key[i] >= '0' && key[i] <= '9') || (key[i] >= 'a' && key[i] <= 'f') || (key[i] >= 'A' && key[i] <= 'F'))) return;
    char k16[17]; memcpy(k16, key, 16); k16[16] = 0;
    pthread_mutex_lock(&w->mu);
    if (!w->loaded) {
        FILE *f = fopen(path, "r"); char line[64];
        if (f) { while (fgets(line, sizeof line, f)) { char *e = strpbrk(line, "\r\n"); if (e) *e = 0; if (strlen(line) != 16) continue;
                if (w->n == w->cap) { w->cap = w->cap ? w->cap * 2 : 64; w->keys = realloc_or_die(w->keys, w->cap * sizeof *w->keys, "the shader key list"); }
                w->keys[w->n++] = strdup(line); } fclose(f); }
        w->loaded = 1;
    }
    for (size_t i = 0; i < w->n; i++) if (!strcmp(w->keys[i], k16)) { pthread_mutex_unlock(&w->mu); return; }
    if (w->n == w->cap) { w->cap = w->cap ? w->cap * 2 : 64; w->keys = realloc_or_die(w->keys, w->cap * sizeof *w->keys, "the shader key list"); }
    w->keys[w->n++] = strdup(k16);
    FILE *f = fopen(path, "a"); if (f) { fprintf(f, "%s\n", k16); fclose(f); }
    pthread_mutex_unlock(&w->mu);
}
static want_list g_bf_want = {"DM_NVN_BF_WANT", PTHREAD_MUTEX_INITIALIZER}, g_dual_want = {"DM_NVN_DUAL_WANT", PTHREAD_MUTEX_INITIALIZER};
void bf_want_note(const char *key) { want_note(&g_bf_want, key); }

// ---------- Memory pools ----------
// How far a pool entry's buffer reaches (BIG_MIN): REACH_WHOLE a large pool's whole-pool buffer; REACH_END to its pool's end (an ordinary pool, or a chunk that reaches the end); REACH_SHORT a chunk
// that ends before its pool does, which answers only lookups that say how far they read
enum { REACH_WHOLE, REACH_END, REACH_SHORT };
typedef struct { uintptr_t lo, hi; uintptr_t base; __unsafe_unretained id<MTLBuffer> buf; uint64_t gpu; const void *key; int res; uint64_t born; uintptr_t end; int reach; uint32_t n_tex_reads, n_other;
                 unsigned up_seq; uint64_t up_ns; uint8_t ev, ev_n, sticky, ak; uint64_t ev_at, ev_hold; } pool_ent;   // res: already in the residency set (on demand, see pool_res); born: when it was added (ns); end: where the buffer ends, reach: how far that is (a large pool's chunk, see BIG_MIN); n_tex_reads / n_other: lookups by texture uploads / by anything else (mem_census).
// The upload-only unwire (DM_NVN_UNWIRE_UP, up_unwire_sweep): up_seq the highest upload batch that reads buf, up_ns when an upload last looked it up; ev: out of the residency set by the sweep,
// ev_n its quick re-adds, ev_at when it went, ev_hold no sweep before then, sticky never again; ak: how the game was given an address in it (AK_*, mtl_pool_addressed_k; census only)
static pool_ent *g_pools; static int g_npool, g_cap;
static int g_pidx_ok, g_plast = -1;   // whether the address→pool index is valid, the last hit (pool_find)
static int *g_pidx; static int g_pidx_cap;   // g_pools' indices sorted by start address (pool_held); only g_pools entries are in it, not the large pools of g_big
static void pidx_added(void); static void pidx_removing(int i);
static NSMutableArray *g_keep;                  // Holds the buffer references (pool_ent has non-owning pointers)
static uint64_t g_pool_adds;
static int g_pool_res_n;   // registered pools already in the residency set (for the memory readout; under g_mu)

#define C1_BANK_SIZE (4u << 20)
#define C1_DECL_SIZE (64u << 10)
static NSMutableArray *g_c1_banks;
static size_t g_c1_bank_off, g_c1_alloc_bytes, g_c1_data_bytes;
static uint64_t g_c1_count;
static NSMutableSet<NSString *> *g_c1_full;
static int g_c1_full_valid;
static NSDictionary<NSString *, NSString *> *g_cb_ext;   // cb_extent.tsv: shader key → "reg:bytes ..." (how far into each uniform slot the shader can read); nil when stale or missing
static os_unfair_lock g_c1_lock = OS_UNFAIR_LOCK_INIT;

@class NvOnce; static NvOnce *once_new(int order); static void once_use(NvOnce *o, id r); static id<MTL4ComputeCommandEncoder> once_copy(NvOnce *o);
static id<MTL4RenderCommandEncoder> once_pass(NvOnce *o, MTL4RenderPassDescriptor *rp); static void once_end(NvOnce *o, id<MTL4CommandEncoder> e); static int once_wait(NvOnce *o);   // one-off command buffers on the Metal 4 queue (below, at once_new)
// DM_UDC_SELFTEST=1 (diagnostic, checks DontCare behavior on a real A19 device): private-storage Depth32Float_Stencil8 / RGBA8 (1952x900) are first cleared to write known values,
// then Load + DontCare without drawing, read back and compared pixel by pixel, printing one result line
static void udc_selftest(void) {
    if (!getenv("DM_UDC_SELFTEST")) return;
    for (int depth = 1; depth >= 0; depth--) {
        NSUInteger w = 1952, h = 900;
        MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:depth ? MTLPixelFormatDepth32Float_Stencil8 : MTLPixelFormatRGBA8Unorm width:w height:h mipmapped:NO];
        td.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; td.storageMode = MTLStorageModePrivate;
        id<MTLTexture> t = [g_dev newTextureWithDescriptor:td];
        NvOnce *cb = once_new(1); once_use(cb, t);
        for (int pass = 0; pass < 2; pass++) {
            MTL4RenderPassDescriptor *rp = [MTL4RenderPassDescriptor new];
            MTLLoadAction la = pass ? MTLLoadActionLoad : MTLLoadActionClear; MTLStoreAction sa = pass ? MTLStoreActionDontCare : MTLStoreActionStore;
            if (depth) { rp.depthAttachment.texture = t; rp.depthAttachment.loadAction = la; rp.depthAttachment.storeAction = sa; rp.depthAttachment.clearDepth = 0.3125;
                         rp.stencilAttachment.texture = t; rp.stencilAttachment.loadAction = la; rp.stencilAttachment.storeAction = sa; rp.stencilAttachment.clearStencil = 0x5a; }
            else { rp.colorAttachments[0].texture = t; rp.colorAttachments[0].loadAction = la; rp.colorAttachments[0].storeAction = sa; rp.colorAttachments[0].clearColor = MTLClearColorMake(0.2, 0.4, 0.6, 0.8); }
            once_end(cb, once_pass(cb, rp));
        }
        id<MTLBuffer> out = [g_dev newBufferWithLength:w * h * 4 options:MTLResourceStorageModeShared]; once_use(cb, out);
        id<MTL4ComputeCommandEncoder> b = once_copy(cb);
        [b copyFromTexture:t sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, 1) toBuffer:out destinationOffset:0
            destinationBytesPerRow:w * 4 destinationBytesPerImage:w * h * 4 options:depth ? MTLBlitOptionDepthFromDepthStencil : MTLBlitOptionNone];
        once_end(cb, b); once_wait(cb);
        const uint32_t *px = out.contents; NSUInteger bad = 0; for (NSUInteger i = 0; i < w * h; i++) if (px[i] != px[0]) bad++;
        MLOG("UDC self-check %s %s %lux%lu first value %08x, values differing from it %lu / %lu", g_dev.name.UTF8String, depth ? "Depth32F_S8" : "RGBA8", (unsigned long)w, (unsigned long)h, px[0], (unsigned long)bad, (unsigned long)(w * h));
    }
}
static unsigned ghost_cap(void);
static int md_k(void);   // DM_NVN_MIP_DROP (the mip drop, below)
// DM_NVN_ARGS_STATS=1 (measurement only, off by default; read once at mtl_init): what makes argument blocks encode again and where encode_args_ spends its time, as
// "[args-stats]" lines each log window (mtl_args_stats_log, after hle_nvn.c's "argument blocks per frame"). Each binding generation change records its reason per stage
// (g_args_why: the hard ones, g_args_swhy: a new pass or program, g_args_uwhy: what moved the uniform slots); a full encode counts the reason its block could not be reused or
// patched (ast_fresh_why). Off, the reasons are still stored (a byte a stage) and each path tests the switch once; nothing is counted or timed
enum { AW_OTHER, AW_TEX, AW_SAMP, AW_SSBO, AW_IMG, AW_PUSH, AW_POOLBASE, AW_REG_TEX, AW_REG_POOL, AW_GWRITE, AW_SER, AW_QUEUE, AW_RESTORE, AW_FB, AW_HOST_CS, AW_HOST_DRAW,
       AW_DRAIN, AW_UPGRADE, AW_DISPATCH,                     // hard: the stage's bindings changed, or are not proven not to have (args_dirty_w, args_dirty_all_w)
       AW_PASS, AW_PROG,                                        // soft: a new render pass, a new program (args_dirty_soft_w)
       AW_FIRST, AW_NEWSUB, AW_XKIND, AW_NOX, AW_XMEM, AW_BINST, AW_PSNAP, AW_UBO, AW_CS, AW_REG_ID, AW_REG_UNCHK, AW_N };   // only a full encode's: see ast_fresh_why
static const char *const g_aw_name[AW_N] = {"other", "tex", "samp", "ssbo", "img", "push", "pool_base", "reg_tex", "reg_pool", "guest_write", "serial", "queue", "restore", "feedback",
    "host_compute", "host_draw", "drain", "upgrade", "dispatch", "pass", "program", "first", "new_sub", "never_kept", "not_kept", "mem_write", "base_inst", "pool_table", "ubo_unpatchable", "compute", "reg_id", "reg_unchecked"};
static int g_ast_on;   // DM_NVN_ARGS_STATS
static int g_push_dedup = 1;   // DM_NVN_PUSH_DEDUP (OP_PUSH_CONST in state_op)
// DM_NVN_ARGS_STATS: this thread's time (mach ticks) in texture lookups past the cached view (tex_by_id_ptr: a texture made or uploaded again, a view made, a packaged texture's pages
// checked), counted with the switch only. The encode split gives it a group of its own (AG_TEXSLOW) and the pool tables' patch path leaves it out of its own time: a lookup there was the
// texture's first since its registration, and its cost is the texture's, not the table's (the 'pool and handle tables' share of Ocarina of Time's full encodes, 2026-11-21)
static _Thread_local uint64_t tl_tex_slow, tl_tex_slow_n; static _Thread_local int tl_tex_in;
// The same lookups by how they ended (tex_by_id_ptr_ sets tl_ts_out, TS_*), and how a new view was had (TSM_*); tex_fit's type-compatible views by outcome (TF_*). Counted and timed with
// the switch only, under g_rmu (every caller holds it), and read by the log line as they stand (cumulative: the line takes differences)
enum { TS_HIT, TS_SPAN, TS_KEEP_EP, TS_KEEP_SPAN, TS_KEEP_NOSPAN, TS_REPL, TS_FIRST, TS_EMPTY, TS_N };
enum { TSM_BASE, TSM_VC, TSM_MADE, TSM_N };
enum { TF_HIT, TF_NEW, TF_VIEW, TF_TYPE, TF_KEPT2, TF_N };
static _Thread_local uint8_t tl_ts_out, tl_ts_made;
static int g_tex_alt2 = 1;   // DM_NVN_TEX_ALT2 (read at mtl_init): 0 = one type-compatible view per texture ID (tex_fit), as before
static int g_tex_seq = 1;   // DM_NVN_TEX_SEQ (read at mtl_init): 0 = a packaged texture ID's view is current only until the next guest write anywhere (the clock), as before; see tex_by_id
static struct { uint64_t n[TS_N], t[TS_N], mn[TSM_N], up, upt, fn[TF_N], ft[TF_N]; } g_tsl;
static int g_args_partial = 1;   // DM_NVN_ARGS_PARTIAL (read at mtl_init): 0 turns partial argument patches off (args_partial), and with them the wider uniform patch (args_pkind) and args_changed's history
static int g_pool_memo = 1;   // DM_NVN_POOL_MEMO (read at mtl_init): 0 sends every pool table lookup through pool_walk's search and checks, as before (pool_gpu)
static int g_args_drv = 1;   // DM_NVN_ARGS_DRV (read at mtl_init): 0 makes a c0 / c2 driver bank for each argument block that reads one, as before (drv_bank)
static int g_bl_on;   // DM_NVN_BINDLESS=1 (read at mtl_init; measuring only in stage 1, off by default): fragment slot tables kept and checked beside the slot path (bl_note)
static int g_pool_entry = 1;   // DM_NVN_POOL_ENTRY (read at mtl_init): 0 takes a pool table entry's checks in their old order, asking the texture its type (pool_entry)
static int g_args_regchk = 1;   // DM_NVN_ARGS_REGCHK (read at mtl_init): 0 makes every texture or sampler registration encode every argument block in full again, as before (args_sync_dirty)
static _Atomic uint64_t g_ast_reg_ts, g_ast_reg_pool;   // texture / sampler registrations and memory pools added or removed (reg_bump), counted with the switch only
static void ast_init(void);
static void gpu_watch_start(void);
static void unw_init(void);   // DM_NVN_UNWIRE_UP (up_unwire_sweep)
static int g_rop_f16_hw_rtz; static void rop_f16_probe(void);   // the 16-bit float colour probe (below, after once_new)
static void mtl_init_once(void) {
    if (g_dev) return;   // a test that made its own device (mtl_comp4)
    ghost_cap();   // the finalized-texture table's size and its start line (DM_NVN_GHOST, the profile's ghost_table)
    md_k();   // its start line, before any thread reads it
    const char *vbc = getenv("DM_NVN_VBUF_CACHE"); g_vbuf_cache = !(vbc && !strcmp(vbc, "0"));
    const char *ftc = getenv("DM_NVN_FT_CACHE"); g_ft_cache = !(ftc && !strcmp(ftc, "0"));
    const char *link = getenv("DM_PRESENT_LINK");
    g_dm_present_link = link ? atoi(link) : 1; if (g_dm_present_link < 0 || g_dm_present_link > 2) g_dm_present_link = 1; g_present_link_env = link != NULL;   // Default 1 (real-device same-process alternation: when load exceeds one display-link period, long frames 15% → 0 and frame intervals even out; no difference from 0 at a steady 60); DM_PRESENT_LINK=0 turns it off   // 1 = present on every tick of a 60 Hz display link; 2 = 120 Hz display link, the game presents a frame every other display-link tick (when behind, it can present on the next 8.33 ms display-link tick)
    const char *latency = getenv("DM_PRESENT_LATENCY");
    if (latency && atoi(latency) > 0) g_present_latency = atoi(latency);
    g_res_check_on = getenv("DM_RES_CHECK") != NULL;
    g_dev = MTLCreateSystemDefaultDevice();
    if (!g_dev) MDIE("no Metal device");
    if (!g_dev.hasUnifiedMemory) MDIE("needs a unified-memory device (zero-copy memory pools)");
    // Metal 4 is the only way the host draws: its command queue, residency set and MTL4Compiler. A GPU without it (a virtual Mac's paravirtualized GPU, such as GitHub's runners)
    // stops here with the reason; the front ends refuse it before the game starts (main.m front_ios_device_check, launcher.c dm_mac_metal4_missing), so this is the message of the
    // command-line dmhost and of any other route
    NSError *re = nil; const char *no4 = NULL;
    if (![g_dev supportsFamily:MTLGPUFamilyMetal4]) no4 = "no Metal 4 GPU family";
    else {
        MTLResidencySetDescriptor *rd = [MTLResidencySetDescriptor new];
        rd.initialCapacity = 4096;
        g_res = [g_dev newResidencySetWithDescriptor:rd error:&re];
        if (!g_res) no4 = "failed to create the MTLResidencySet";
    }
    if (!no4) {
        dispatch_queue_attr_t feedback_attr = dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_USER_INTERACTIVE, 0);
        g_feedback_q = dispatch_queue_create("dm.nvn.mtl4-feedback", feedback_attr);
        dispatch_queue_set_specific(g_feedback_q, &g_fbq_key, &g_fbq_key, NULL);   // on_feedback_q: the slow commit lines say whether they ran here
        MTL4CommandQueueDescriptor *q4d = [MTL4CommandQueueDescriptor new]; q4d.feedbackQueue = g_feedback_q;
        g_q4 = [g_dev newMTL4CommandQueueWithDescriptor:q4d error:&re];
        if (!g_q4) no4 = "failed to create the MTL4CommandQueue";
    }
    if (no4) {
        const char *why = re ? re.localizedDescription.UTF8String : "";
        MDIE("the Metal device %s has no Metal 4 (%s%s%s), the only way the host draws: it needs an iPhone 15 Pro or newer (A17 Pro chip or later), an iPad with an M1 chip or later, "
             "or a Mac with Apple silicon on macOS 27.2 or later; a virtual Mac's GPU has none", g_dev.name.UTF8String, no4, *why ? ": " : "", why);
    }
    // BC textures are created and uploaded as BC, with no decompression path (dm/gfx/tex/README.md); without BC the first one aborts in Metal's descriptor validation mid-game
    // (GitHub issue #704: an iPhone 15, A16). The iOS front end refuses such a device before the launcher (main.m); this stops every other route at the device, with the reason
    if (!g_dev.supportsBCTextureCompression) MDIE("the Metal device %s has no BC texture formats, which the games' textures use and the host does not decompress: an iPhone needs an A17 Pro or later, an iPad an M1 or later", g_dev.name.UTF8String);
    if (!mtl_comp4()) MDIE("the Metal device %s made no Metal 4 compiler, which the host's pipelines are built through", g_dev.name.UTF8String);   // before any host library or pipeline
    [g_q4 addResidencySet:g_res];
    rca_mode();   // read once here, before the replay and the encode thread ask (DM_NVN_RES_ASYNC)
    pw_on();      // and DM_NVN_RES_PREWIRE's
    { void crash_set_wait_dump(void (*fn)(void)); void mtl_wait_state_dump(void); crash_set_wait_dump(mtl_wait_state_dump); }
    g_alloc_n = 3;
    for (int i = 0; i < 3; i++) {
        MTL4CommandAllocatorDescriptor *ad = [MTL4CommandAllocatorDescriptor new];
        ad.label = [NSString stringWithFormat:@"nvn-mtl allocator %d", i];
        NSError *ae = nil;
        g_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:ad error:&ae];
        if (!g_alloc4[i]) MDIE("failed to create MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
        MTL4CommandAllocatorDescriptor *pad = [MTL4CommandAllocatorDescriptor new];
        pad.label = [NSString stringWithFormat:@"nvn-mtl present allocator %d", i];
        g_present_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:pad error:&ae];
        if (!g_present_alloc4[i]) MDIE("failed to create present MTL4CommandAllocator[%d]: %s", i, ae.localizedDescription.UTF8String);
        g_present_cb[i] = [g_dev newCommandBuffer];
        if (!g_present_cb[i]) MDIE("failed to create present MTL4CommandBuffer[%d]", i);
    }
    { const char *why; g_up_nslots = up_slots_pick(getenv("DM_NVN_UP_SLOTS"), DM_GAME_UPLOAD_SLOTS, &why);
      MLOG("upload batches: %u slots in rotation (%s)", g_up_nslots, why); }
    for (unsigned i = 0; i < g_up_nslots; i++) {
        MTL4CommandAllocatorDescriptor *ad = [MTL4CommandAllocatorDescriptor new]; NSError *ae = nil;
        ad.label = [NSString stringWithFormat:@"nvn-mtl upload allocator %u", i];
        g_up_alloc4[i] = [g_dev newCommandAllocatorWithDescriptor:ad error:&ae];
        if (!g_up_alloc4[i]) MDIE("failed to create upload MTL4CommandAllocator[%u]: %s", i, ae.localizedDescription.UTF8String);
    }
    MTL4ArgumentTableDescriptor *atd = [MTL4ArgumentTableDescriptor new];
    atd.maxBufferBindCount = 31; atd.maxTextureBindCount = 1;
    NSError *ate = nil;
    g_vt = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_vt) MDIE("failed to create the vertex argument table: %s", ate.localizedDescription.UTF8String);
    g_vt_valid = 0;
    g_ft = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_ft) MDIE("failed to create the fragment argument table: %s", ate.localizedDescription.UTF8String);
    g_ft_valid = 0;
    g_ct = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_ct) MDIE("failed to create the compute argument table: %s", ate.localizedDescription.UTF8String);
    g_ot = rec_table([g_dev newArgumentTableWithDescriptor:atd error:&ate]); if (!g_ot) MDIE("failed to create the object argument table: %s", ate.localizedDescription.UTF8String);
    g_up_ct = [g_dev newArgumentTableWithDescriptor:atd error:&ate]; if (!g_up_ct) MDIE("failed to create the upload compute argument table: %s", ate.localizedDescription.UTF8String);
    MTL4ArgumentTableDescriptor *pad = [MTL4ArgumentTableDescriptor new];
    pad.maxTextureBindCount = 1; pad.maxSamplerStateBindCount = 1; pad.maxBufferBindCount = 1;
    g_present_args = [g_dev newArgumentTableWithDescriptor:pad error:&ate];
    if (!g_present_args) MDIE("failed to create the present argument table: %s", ate.localizedDescription.UTF8String);
    for (int i = 0; i < 3; i++) {
        g_present_uv[i] = [g_dev newBufferWithLength:sizeof(float) * PRESENT_UV_FLOATS options:MTLResourceStorageModeShared];
        if (!g_present_uv[i]) MDIE("failed to create present UV buffer[%d]", i);
        res_add(g_present_uv[i]);
    }
    g_ev = [g_dev newSharedEvent];
    g_keep = [NSMutableArray array];
    g_nvn_deswz_gpu = nvn_deswz_gpu_init(g_dev, g_comp4) == 0;
    dm_res_report_register(mtl_res_counts);
    if (!g_nvn_deswz_gpu) MLOG("[RED] GPU deswizzle init failed; swizzled textures fall back to the CPU");
    MLOG("Metal device %s", g_dev.name.UTF8String);
    { const char *e = getenv("DM_NVN_ARGS_STATS"); if (e && atoi(e) > 0) ast_init(); }
    { const char *e = getenv("DM_NVN_PUSH_DEDUP"); if (e && !strcmp(e, "0")) { g_push_dedup = 0; MLOG("DM_NVN_PUSH_DEDUP=0: push constants set to the bytes held already re-encode the argument blocks, as before"); } }
    { const char *e = getenv("DM_NVN_ARGS_PARTIAL"); if (e && !strcmp(e, "0")) { g_args_partial = 0; MLOG("DM_NVN_ARGS_PARTIAL=0: an argument block whose texture, sampler, storage or base instance changed is encoded in full, as before"); } }
    unw_init();   // DM_NVN_UNWIRE_UP
    { const char *e = getenv("DM_NVN_POOL_MEMO"); if (e && !strcmp(e, "0")) { g_pool_memo = 0; MLOG("DM_NVN_POOL_MEMO=0: every pool table lookup goes through the table search and its checks, as before"); } }
    { const char *e = getenv("DM_NVN_ARGS_DRV"); if (e && !strcmp(e, "0")) { g_args_drv = 0; MLOG("DM_NVN_ARGS_DRV=0: a c0 / c2 driver bank is made for each argument block that reads one, as before"); } }
    { const char *e = getenv("DM_NVN_BINDLESS"); if (e && atoi(e) > 0) { g_bl_on = 1; MLOG("DM_NVN_BINDLESS=1 (stage 1, measuring): fragment slot tables are built and checked against the slot path; shaders still read their slots. With DM_NVN_ARGS_STATS=1 a '[args-stats] slot tables' line counts what they would save"); } }
    { const char *e = getenv("DM_NVN_POOL_ENTRY"); if (e && !strcmp(e, "0")) { g_pool_entry = 0; MLOG("DM_NVN_POOL_ENTRY=0: a pool table entry takes its storage and budget checks before its texture type, and asks the texture its type, as before"); } }
    { const char *e = getenv("DM_NVN_TEX_ALT2"); if (e && !strcmp(e, "0")) { g_tex_alt2 = 0; MLOG("DM_NVN_TEX_ALT2=0: a texture ID keeps one type-compatible view, as before"); } }
    { const char *e = getenv("DM_NVN_TEX_SEQ"); if (e && !strcmp(e, "0")) { g_tex_seq = 0; MLOG("DM_NVN_TEX_SEQ=0: a packaged texture ID's view is checked again after any guest write, as before"); } }
    { const char *e = getenv("DM_NVN_ARGS_REGCHK"); if (e && !strcmp(e, "0")) { g_args_regchk = 0; MLOG("DM_NVN_ARGS_REGCHK=0: a texture or sampler registration encodes every argument block in full, as before"); } }
    rop_f16_probe();   // DM_NVN_ROP_F16 (rop_f16_need)
    udc_selftest();
    gpu_watch_start();   // DM_GPU_LOST_S (below)
}
// Pool registration and the shutdown drain can arrive together on a cold device (upstream 4f4bfb6a7: SIGTERM during NieR's start crashed in the ARC release of the
// feedback queue the other caller had made). Both wait for the whole initialization: a device alone is not enough, the callers need the queues and residency set too.
// Nothing mtl_init_once calls may call mtl_init (dispatch_once would wait on itself)
void mtl_init(void) {
    static dispatch_once_t once;
    dispatch_once(&once, ^{ mtl_init_once(); });
}

void dm_mtl_l3_tick(uint32_t tick) {
    static int leak = -1;
    if (leak < 0) leak = getenv("DM_TEST_LEAK_GPU") != NULL;
    if (leak && tick % 100 == 0) {
        if (!g_l3_gpu_leaks) g_l3_gpu_leaks = [NSMutableArray array];
        id<MTLBuffer> leak = [g_dev newBufferWithLength:1 << 20 options:MTLResourceStorageModeShared];
        if (leak) [g_l3_gpu_leaks addObject:leak];
    }
}

uint64_t dm_mtl_l3_sample(uint32_t tick) {
    (void)tick;
    return g_dev ? g_dev.currentAllocatedSize : 0;
}

// No-copy buffers of finalized pools (weak references, under g_mu): the memory report counts how many are still alive and their length -- a buffer that outlives its pool is still strongly referenced by something else (a texture built directly on the pool, etc.)
static NSHashTable *g_dead_pools;
// Address → pool cache per thread (mtl_addr / mtl_gpu_addr), valid while g_pool_gen is unchanged (every pool add / removal bumps it under g_mu), holding only pools already in the residency set.
// Every buffer binding of every draw used to take g_mu, which game threads creating pools and the GPU completion handler also take, and search the pool index. Two levels: a table direct-mapped
// by 4 KB page, then the last 8 pools found, which also fill the table. Breath of the Wild binds from more pools a frame than 8 entries alone could hold (about 2300 of its 21000 lookups a frame
// took the lock), and its uniform rings move to a new page every few draws (the table alone missed as often)
enum { PC_BITS = 10, PC_RECENT = 8 };
static _Alignas(128) _Atomic uint64_t g_pool_gen = 1;
static _Atomic uint64_t g_pool_drop_gen;   // g_pool_gen as of the last pool taken out (pool_take_out): a raw pool table built before it may name a buffer that is going (gmem_map)
typedef struct { uintptr_t lo, hi, base; __unsafe_unretained id<MTLBuffer> buf; uint64_t gpu; uintptr_t end; int reach; } pc_ent;
// A second table direct-mapped by 64 KB region, looked at first: a pool of megabytes is found from any page of a region already seen, where the page table needs each of its
// pages seen once and, with 1,024 slots, kept, so a game binding from thousands of pools kept falling through to g_mu and the pool index (pool_held;
// docs/reference/frame-rate.md, "Pool lookups by page missed with thousands of pools"). Pools that share a region take turns in its slot and are found in the page table as before
static __thread struct { uint64_t gen; unsigned next; pc_ent r[PC_RECENT], e[1u << PC_BITS], w[1u << PC_BITS]; } t_pc;   // an empty entry has hi 0
static inline unsigned pc_slot(uint64_t addr) { return (unsigned)(((addr >> 12) * 0x9E3779B97F4A7C15ull) >> (64 - PC_BITS)); }
static inline unsigned pc_slot_w(uint64_t addr) { return (unsigned)(((addr >> 16) * 0x9E3779B97F4A7C15ull) >> (64 - PC_BITS)); }
// A lookup of unknown length (1) may read on to its pool's end, so a chunk short of it does not answer one: big_lookup gives it the whole pool
static inline int pc_holds(const pc_ent *c, uint64_t addr, uint64_t len) { return len > 1 ? addr + len <= c->end : c->reach != REACH_SHORT; }
static inline const pc_ent *pc_get(uint64_t addr, uint64_t len) {
    if (t_pc.gen != atomic_load_explicit(&g_pool_gen, memory_order_acquire)) return NULL;
    pc_ent *w = &t_pc.w[pc_slot_w(addr)];
    if (addr >= w->lo && addr < w->hi && pc_holds(w, addr, len)) return w;
    pc_ent *c = &t_pc.e[pc_slot(addr)];
    if (addr >= c->lo && addr < c->hi && pc_holds(c, addr, len)) return c;
    for (unsigned k = 0; k < PC_RECENT; k++) { const pc_ent *x = &t_pc.r[k]; if (addr >= x->lo && addr < x->hi && pc_holds(x, addr, len)) { *c = *x; *w = *x; return c; } }
    return NULL;
}
static __thread int t_tex_upload_lookup;   // set around a texture upload's read of its storage (pool lookups counted apart, mem_census)
static void pc_put(int i, uint64_t addr) {   // caller holds g_mu, pool i is resident and holds addr; never for a texture upload's lookup (mtl_addr): every entry comes from a counted other use
    assert(!t_tex_upload_lookup);
    uint64_t gen = atomic_load_explicit(&g_pool_gen, memory_order_relaxed);
    if (t_pc.gen != gen) { memset(t_pc.r, 0, sizeof t_pc.r); memset(t_pc.e, 0, sizeof t_pc.e); memset(t_pc.w, 0, sizeof t_pc.w); t_pc.gen = gen; }
    pc_ent c = {g_pools[i].lo, g_pools[i].hi, g_pools[i].base, g_pools[i].buf, g_pools[i].gpu, g_pools[i].end, g_pools[i].reach};
    t_pc.e[pc_slot(addr)] = c; t_pc.w[pc_slot_w(addr)] = c; t_pc.r[t_pc.next++ % PC_RECENT] = c;
}
static _Alignas(128) _Atomic uint64_t g_reg_gen = 1;   // Change generation of memory pool / texture / sampler registration: one of the invalidation conditions for argument buffer reuse
// The changes behind g_reg_gen, by generation: a texture or sampler registration (under g_rmu) records the generation it made and its ID, so a pool table (pool_gpu) built at an earlier
// generation can take just those IDs again. One the ring has overwritten makes the table be built whole. A memory pool added or removed (mtl_pool_add / mtl_pool_del) records REG_POOL
// and no ID: it changes no registration, only which storage exists, so a table takes again only the IDs it found without storage. The IDs of a pool that Finalize removes are marked
// gone first (treg_gone), each with a note of its own. Ocarina of Time registers something between most of its draws, and its streamed textures map and unmap virtual pool runs
// (vrun_set) dozens of times a second: each of those walked its 33,025-entry texture table again. Pool changes come from threads that do not hold g_rmu, so a note is a sequence
// lock: its writer clears the generation, writes what changed and stores the generation last (release); a reader takes it only if the generation is the one asked for both before
// and after it reads what changed, so a note the ring overwrites meanwhile reads as overwritten
enum { REG_LOG = 4096, REG_POOL = 2 };
typedef struct { _Atomic uint64_t gen, what; } reg_note;   // what: the ID in the low 32 bits, above them 0 a texture ID, 1 a sampler ID, REG_POOL a memory pool added or removed (no ID)
static reg_note g_reg_log[REG_LOG];
static void reg_bump(int id_, int samp) {
    if (__builtin_expect(g_ast_on, 0)) atomic_fetch_add_explicit(samp == REG_POOL ? &g_ast_reg_pool : &g_ast_reg_ts, 1, memory_order_relaxed);   // before the generation: a reader that sees it moved sees this
    uint64_t g = atomic_fetch_add(&g_reg_gen, 1) + 1; reg_note *n = &g_reg_log[g % REG_LOG];
    atomic_store_explicit(&n->gen, 0, memory_order_relaxed); atomic_thread_fence(memory_order_release);
    atomic_store_explicit(&n->what, (uint64_t)(uint32_t)id_ | (uint64_t)samp << 32, memory_order_relaxed);
    atomic_store_explicit(&n->gen, g, memory_order_release);
}
static int reg_read(uint64_t g, int *id_, int *samp) {   // → 0 when note g is not in the ring (not written yet, or overwritten)
    reg_note *n = &g_reg_log[g % REG_LOG];
    if (atomic_load_explicit(&n->gen, memory_order_acquire) != g) return 0;
    uint64_t w = atomic_load_explicit(&n->what, memory_order_relaxed);
    atomic_thread_fence(memory_order_acquire);
    if (atomic_load_explicit(&n->gen, memory_order_relaxed) != g) return 0;
    *id_ = (int)(uint32_t)w; *samp = (int)(w >> 32); return 1;
}
// A shader's pointer is an address the driver gave out, or one worked out from it, and the driver gives addresses out by buffer, pool or texture (hle_nvn.c pool_mark_addressed). The raw table admits
// the pools so noted, and those reached by fixed pointers read before binding (gmem_discover). A pool with neither holds only textures, which Metal keeps in textures of its own, so the table leaves it
// out and nothing wires it for the table's sake. With the getter-only filter, Ocarina of Time: 172 pools of 3,721 MB of the 4,588 MB, its whole 2,432 MB
// graphics pool among them; with them in, the first scene passed 12 GB of Metal's 12.1 GB working set and took a 16 GB Mac into swap, and once into a kernel panic in IOGPUGroupMemory
static struct { uintptr_t lo, hi; } *g_addr; static int g_naddr, g_addr_cap;   // sorted, disjoint. Under g_mu
static int addr_first(uintptr_t lo) { int a = 0, b = g_naddr; while (a < b) { int m = (a + b) / 2; if (g_addr[m].hi <= lo) a = m + 1; else b = m; } return a; }   // the first range that ends after lo
static int addr_meets(uintptr_t lo, uintptr_t hi) { int i = addr_first(lo); return i < g_naddr && g_addr[i].lo < hi; }
static int pool_held(uint64_t addr, uint64_t len); static int pidx_pos(uintptr_t lo, int n); static void pidx_sort(void);
// How the address was given (mtl_pool_addressed_k), OR'd into the ak of each pool of g_pools the range meets: for the census only (mem_census, pool_res_classes), which tells the pools
// the raw table keeps resident by the call that put them in it. g_addr is the same whatever the kind
void mtl_pool_addressed_k(const void *mem, uint64_t size, int kind) {
    uintptr_t lo = (uintptr_t)mem, hi = lo + size, lo0 = lo, hi0 = hi;
    mu_lock();
    if (kind && g_npool) {   // the pools the range meets: the last one starting at or before lo, then on by start address (pools barely overlap: a large pool's chunks are not in g_pools' index walk here)
        pidx_sort();
        int p = pidx_pos(lo0, g_npool); if (p > 0) p--;
        for (int k = p; k < g_npool && g_pools[g_pidx[k]].lo < hi0; k++) { pool_ent *e = &g_pools[g_pidx[k]]; if (e->hi > lo0) e->ak |= (uint8_t)kind; }
    }
    int i = addr_first(lo);
    if (i == g_naddr || g_addr[i].lo > lo || g_addr[i].hi < hi) {
        if (i > 0 && g_addr[i - 1].hi == lo) i--;   // touching on the left
        int j = i;
        while (j < g_naddr && g_addr[j].lo <= hi) { lo = MIN(lo, g_addr[j].lo); hi = MAX(hi, g_addr[j].hi); j++; }
        if (i == j && g_naddr == g_addr_cap) { g_addr_cap = g_addr_cap ? g_addr_cap * 2 : 256; g_addr = realloc_or_die(g_addr, (size_t)g_addr_cap * sizeof *g_addr, "the addressed range table"); }
        if (j != i + 1) memmove(g_addr + i + 1, g_addr + j, (size_t)(g_naddr - j) * sizeof *g_addr);
        g_naddr += 1 - (j - i); g_addr[i].lo = lo; g_addr[i].hi = hi;
        atomic_fetch_add(&g_pool_gen, 1);   // the table rebuilds before the next draw that uses it
    }
    pthread_mutex_unlock(&g_mu);
}
void mtl_pool_addressed(const void *mem, uint64_t size) { mtl_pool_addressed_k(mem, size, 0); }
// A shader-code pool whose own address the game asked for (hle_nvn.c nvnMemoryPoolGetBufferAddress) stays out of g_addr, so the raw pool table (gmem_map) does not make it resident.
// Counted for the log only: once at the first, then every 50 pools (a pool asked for again on another thread may count twice)
static _Atomic uint64_t g_code_pools, g_code_bytes;
void mtl_pool_code_address(const void *mem, uint64_t size) {
    static __thread const void *last; if (!mem || !size || mem == last) return; last = mem;
    uint64_t n = atomic_fetch_add(&g_code_pools, 1) + 1, b = atomic_fetch_add(&g_code_bytes, size) + size;
    if (n == 1 || n % 50 == 0) MLOG("raw global memory: shader-code pools whose own address the game asks for stay out of the pool table, so nothing makes them resident for its sake: %llu pools, %llu MB so far",
                                    (unsigned long long)n, (unsigned long long)(b >> 20));
}
// ---------- The upload-only unwire (DM_NVN_UNWIRE_UP; up_unwire_sweep, below) ----------
// A pool in the residency set is wired whole: Metal pins a no-copy buffer's pages while the set holds it, so the kernel cannot drop its clean file pages under memory pressure and
// compresses dirty memory and evicts other file pages instead (Ocarina of Time on the iPhone 18 Pro Max: 3,800-4,350 of 4,400-4,800 pools resident, the process re-read 12.6 GB of
// guest-file pages by 120 s; NX18-X2.0 traces/oot-mst-1-findings.md). A pool that only texture uploads have read needs the set only while an upload batch that reads it runs: once
// that batch's feedback has come back, the sweep takes it out, and its pages are the kernel's to drop again. It comes back through the usual paths (pool_res, gmem_map_at) before
// any later GPU use: the lookups' residency rule (pool_res_commit, rca_queue_guard) is unchanged. Counts under g_mu
enum { UNW_RE_UPLOAD, UNW_RE_OTHER, UNW_RE_RAW, UNW_RE_N };   // why an unwired pool came back: an upload that could not read it through a batch buffer, another use, the raw pool table
static const uint64_t UNW_QUICK_NS = 10000000000ull, UNW_HOLD_MAX_NS = 120000000000ull;   // a re-add within 10 s of the unwire holds the pool back from the sweep 10 s, then 20, 40 ... up to 120 s
static int g_unw_mode = -1, g_unw_measure;   // DM_NVN_UNWIRE_UP (read once at mtl_init: unw_init): 0 off, 1 on, ab; m (g_unw_measure, the default: unset or empty) counts what would go and changes nothing
static uint64_t g_unw_skew;                  // test hook (t_pool_unwire): added to the sweep's clock; the host never sets it
static int g_unw_stress;                     // test hook (t_pool_unwire): a sweep at every submission, without the idle rule; the host never sets it
static int g_up_src_refuse;                  // test hook (t_pool_unwire): up_big_src makes no buffer, as when Metal refuses one; the host never sets it
static uint64_t g_unw_n, g_unw_b, g_unw_would_n, g_unw_would_b, g_unw_re[UNW_RE_N], g_unw_sticky, g_unw_src_n, g_unw_src_b, g_unw_sweeps, g_unw_sweep_ns;   // totals (the 10 s line)
static uint64_t g_unw_last_at;               // the last sweep (submit thread)
static uint64_t unw_now(void) { return clock_gettime_nsec_np(CLOCK_MONOTONIC) + g_unw_skew; }
static unsigned g_up_seq;   // the upload batches up_begin has opened (below)
static id<MTLBuffer> g_gmem_buf;   // the raw pool table (gmem_map_at, below); the sweep keeps every addressed pool, table or not
// Caller holds g_mu: pool i joins the set again after the sweep took it out. A re-add soon after the unwire holds the pool back from the next sweeps, twice as long each time, and the third makes it stay
static void pool_res_mark(int i, int cause) {
    pool_ent *p = &g_pools[i];
    if (!p->ev) return;
    p->ev = 0; g_unw_re[cause]++;
    uint64_t now = unw_now();
    if (now - p->ev_at < UNW_QUICK_NS) {
        uint64_t h = UNW_QUICK_NS << MIN(p->ev_n, 4); if (h > UNW_HOLD_MAX_NS) h = UNW_HOLD_MAX_NS;
        p->ev_hold = now + h;
        if (++p->ev_n >= 3 && !p->sticky) { p->sticky = 1; g_unw_sticky++; }
    }
}
// Caller holds g_mu: a lookup of pool i, counted by who made it (mem_census). An upload's notes the batch that reads the pool (up_seq: the sweep waits for it to come back) and when
static void pool_counted(int i) {
    pool_ent *p = &g_pools[i];
    if (t_tex_upload_lookup) { p->n_tex_reads++; p->up_seq = MAX(p->up_seq, g_up_seq); p->up_ns = unw_now(); }
    else p->n_other++;
}
// On-demand residency of memory pools: putting a zero-copy buffer into the residency set makes iOS read the whole pool into memory and pin it as wired, even a pool the game never uses
// (they measured on a 17 Pro Max a 512 MB render-target pool addressed 0 times in a run, with about 530 MB more device wired memory; a 4 GB A14 was ended by the system within seconds of launch because of it).
// So a pool is not put into the residency set when created; it is put in, and the residency set committed on the spot, the first time the GPU gets its address through mtl_addr / mtl_gpu_addr -- these are the only two ways the GPU gets pool addresses,
// and committing on the spot is earlier than any command buffer commit that uses it. CPU-side reads of pool contents through mtl_addr trigger it too (conservative, never misses). Caller holds g_mu.
// The commit itself is made after g_mu is let go (pool_res_commit): a residency commit that wires a pool of hundreds of MB takes 10-25 ms and more, and under g_mu every pool lookup
// on every thread (mtl_addr / mtl_gpu_addr past their per-thread cache, the pool table, the submit thread's own) waited for it. The pool is marked resident under g_mu before it is
// committed, so another thread's lookup can find it so in between; g_pool_res_open counts the adds not committed yet, and a lookup that sees one commits too (res_commit then waits
// for the commit under way, or takes the add itself), so no lookup returns a pool before it is in the committed set, as when the commit was made under g_mu. The replay thread's
// lookups are the exception with DM_NVN_RES_ASYNC (res_commit_soon): they hand the commit to the worker, and the queue commit of what uses the pool comes after it. → 1 when it added
static int pool_res(int i) {
    if (g_pools[i].res) return 0;
    pool_res_mark(i, t_tex_upload_lookup ? UNW_RE_UPLOAD : UNW_RE_OTHER);
    res_add(g_pools[i].buf); g_pools[i].res = 1; g_pool_res_n++; atomic_fetch_add(&g_pool_res_open, 1);
    return 1;
}
// After g_mu: commit this lookup's add (added), or one another thread's lookup made and has not committed yet. Nothing to commit costs one atomic load
static void pool_res_commit(int added) {
    if (!added && !atomic_load(&g_pool_res_open)) return;
    res_commit_soon(0, added);   // the replay hands it to the worker (DM_NVN_RES_ASYNC): its GPU use is committed later, after the commit (cb_commit, rca_queue_guard)
}
// A large pool in chunks. Metal wires a zero-copy buffer whole while it is in the residency set, so one buffer over a large pool pins all of it, whatever the GPU reads. Mario Kart World's 2,427 MB
// graphics pool: the GPU has touched 1,111 MB by the first race, 326 MB of it in the last 1,500 frames; on a 16 GB Mac the driver then spent half its time wiring and unwiring (3.2 s of a 6 s Metal System
// Trace) with 140 MB free, and frames took 100 ms and more every few frames. A pool of BIG_MIN or more therefore has no buffer of its own: a lookup gets a chunk, a zero-copy buffer over the BIG_S
// stride holding its address and on up to the end of what it asked (rounded up to the stride, plus a stride), made when first asked for. Only what lookups reach is wired. The chunks overlap, as adjacent
// pools' buffers do at shared pages; GPU addresses are not contiguous across them, so a lookup must say how far it reads. One that does not know (length 1: an indirect draw's index buffer, a storage
// buffer whose address the game keeps or pushes) may read on to the pool's end, and takes one buffer of the whole pool, as raw global memory does, whose pool table the shader walks by itself (big_full).
// A guess of 64 MB past the address made a chunk of 80 to 96 MB at each stride such a lookup started in, overlapping each other and each counted whole by Metal: Trails in the Sky 1st Chapter
// had 4,243 MB of shared buffers over its 1,507 MB pool and its command buffers failed out of memory on an M1 (issue #877). From 256 MB: Ocarina of Time's render
// targets live in virtual pools over one 305 MB physical pool, which the raw pool table no longer names (hle_nvn.c tex_bytes_elsewhere); one compute shader still binds a 200 KB
// storage buffer at an address in it every frame, and that lookup wired all 305 MB on the iPhone 17 (docs/reference/memory.md)
enum { BIG_MIN = 256u << 20, BIG_S = 16u << 20, BIG_MAX = 32 };
typedef struct { uintptr_t lo, hi, a, b; const void *mem; int *chunk, full; NSMutableArray *old; } big_pool;   // chunk: stride → g_pools index + 1; full: the whole pool's entry + 1; old: buffers a longer chunk replaced, alive with the pool
static big_pool g_big[BIG_MAX]; static int g_nbig;
static id<MTLBuffer> pool_buf(uintptr_t a, uintptr_t b);   // a pool's zero-copy buffer over [a, b), made over writable pages (below)
static int big_of(uint64_t addr) { for (int i = 0; i < g_nbig; i++) if (addr >= g_big[i].lo && addr < g_big[i].hi) return i; return -1; }
// A pool to put into the table: its zero-copy buffer is made first, outside g_mu (pool_new_prep; it may retry for seconds), and the entry goes in under g_mu (pool_new_put), so a change
// of several pools can be one step for every lookup (mtl_pool_replace)
typedef struct { const void *mem; uint64_t size; uintptr_t lo, hi, a, b; __strong id<MTLBuffer> buf; int none; } pool_new;   // buf nil: in chunks (a large pool); none: no buffer could be made (pool_buf_made), not registered
static int pool_chunks(void) { static int c = -1; if (c < 0) { const char *e = getenv("DM_NVN_POOL_CHUNKS"); c = !e || atoi(e); } return c; }
static int g_pool_refuse;   // unit tests (t_pool_chunks): 1 takes the zero-copy buffer as refused (no retries), 2 the remapped view's too
static id<MTLBuffer> pool_buf_made(const void *mem, uint64_t size, uintptr_t a, uintptr_t b) {
    int refuse = g_pool_refuse;
    id<MTLBuffer> buf = refuse ? nil : pool_buf(a, b);
    // Pokémon Legends: Z-A: twice on the Mac a small pool's buffer was refused although its pages were one read-write VM region, both times while another heavy job (a shader compile,
    // a second game instance) took the machine's memory; every run on an idle machine created all of them. Wiring the pages may fail under memory pressure: retry for up to about 2 s
    for (int t = 0; !buf && !refuse && t < 12; t++) {
        usleep(10000u << (t < 4 ? t : 4));
        buf = pool_buf(a, b);
        if (buf) MLOG("[RED] memory pool %p+%#llx: the zero-copy buffer was refused, created at retry %d", mem, (unsigned long long)size, t + 1);
    }
    if (!buf) {   // say what the pages looked like: every VM region over the range, with its protection (an unmapped page in the range is the usual cause)
        for (vm_address_t r = a; r < b; ) {
            vm_size_t rs = 0; vm_region_basic_info_data_64_t vi; mach_msg_type_number_t cnt = VM_REGION_BASIC_INFO_COUNT_64; mach_port_t obj = MACH_PORT_NULL;
            if (vm_region_64(mach_task_self(), &r, &rs, VM_REGION_BASIC_INFO_64, (vm_region_info_t)&vi, &cnt, &obj) != KERN_SUCCESS) { MLOG("[RED]   no VM region at or after %#llx", (unsigned long long)r); break; }
            MLOG("[RED]   VM region %#llx+%#llx protection %d (max %d)", (unsigned long long)r, (unsigned long long)rs, vi.protection, vi.max_protection);
            r += rs;
        }
        // Then the same pages are remapped at one new range (vm_remap, no copy: the CPU and the GPU still see one memory) and the buffer is made over that view, its protected pages
        // opened as for pool_buf, so the view is writable for the GPU. Its deallocator lets the view go. Failing that too, the pool is left unregistered: what uses it is skipped as
        // in no pool, with its red line, and the game goes on (S2Arm c898acfb: a 340 MB pool over four read-write VM regions refused 12 times on a Mac and an iPad aborted the session)
        vm_address_t v = 0; vm_prot_t cur, max; kern_return_t kr = KERN_FAILURE;
        nvn_dirty_open((void *)a, b - a);
        if (refuse < 2) kr = vm_remap(mach_task_self(), &v, (vm_size_t)(b - a), 0, VM_FLAGS_ANYWHERE, mach_task_self(), (vm_address_t)a, FALSE, &cur, &max, VM_INHERIT_NONE);
        if (kr == KERN_SUCCESS)
            buf = [g_dev newBufferWithBytesNoCopy:(void *)v length:b - a options:MTLResourceStorageModeShared deallocator:^(void *q, NSUInteger n) { vm_deallocate(mach_task_self(), (vm_address_t)q, n); }];
        nvn_dirty_close();
        if (buf) MLOG("[RED] memory pool %p+%#llx: the zero-copy buffer over %#lx..%#lx was refused; made over one remapped view of the same pages at %#lx", mem, (unsigned long long)size, (unsigned long)a, (unsigned long)b, (unsigned long)v);
        else {
            if (kr == KERN_SUCCESS) vm_deallocate(mach_task_self(), v, (vm_size_t)(b - a));
            MLOG("[RED] memory pool %p+%#llx: no zero-copy buffer over %#lx..%#lx, not even over a remapped view (vm_remap %d): the pool is not registered, what uses it is skipped as in no pool",
                 mem, (unsigned long long)size, (unsigned long)a, (unsigned long)b, kr);
        }
    }
    return buf;
}
static void pool_new_prep(pool_new *n, const void *mem, uint64_t size) {
    uintptr_t pg = (uintptr_t)getpagesize(), lo = (uintptr_t)mem, hi = lo + size;
    *n = (pool_new){mem, size, lo, hi, lo & ~(pg - 1), (hi + pg - 1) & ~(pg - 1), nil};
    if (size >= BIG_MIN && pool_chunks()) { mu_lock(); int room = g_nbig < BIG_MAX; pthread_mutex_unlock(&g_mu); if (room) return; }
    if (!(n->buf = pool_buf_made(mem, size, n->a, n->b))) n->none = 1;
}
static void pool_new_put(pool_new *n) {   // caller holds g_mu
    if (n->none) return;   // no buffer could be made: not registered (pool_buf_made)
    if (!n->buf && g_nbig == BIG_MAX && !(n->buf = pool_buf_made(n->mem, n->size, n->a, n->b))) return;   // the chunk table filled since pool_new_prep looked
    if (!n->buf) {
        int *ch = calloc(((n->b - n->a) >> 24) + 1, sizeof *ch); if (!ch) MDIE("pool chunk table");
        g_big[g_nbig++] = (big_pool){n->lo, n->hi, n->a, n->b, n->mem, ch, 0, [NSMutableArray array]};
        g_plast = -1; atomic_fetch_add(&g_pool_gen, 1); g_pool_adds++; atomic_fetch_add(&g_big_n, 1);   // g_big is not in the address index (g_pidx): it stays valid
        static int nl; if (nl++ < 8) MLOG("memory pool %p+%llu MB: in chunks, wired as far as lookups reach", n->mem, (unsigned long long)(n->size >> 20));
        return;
    }
    if (g_npool == g_cap) { g_cap = g_cap ? g_cap * 2 : 64; g_pools = realloc_or_die(g_pools, g_cap * sizeof *g_pools, "the memory pool table"); }
    g_plast = -1; atomic_fetch_add(&g_pool_gen, 1);   // the last hit and the per-thread caches are invalid (pool_find, pc_get); the address index takes the pool in place (pidx_added)
    g_pools[g_npool++] = (pool_ent){n->lo, n->hi, n->a, n->buf, n->buf.gpuAddress, n->mem, 0, clock_gettime_nsec_np(CLOCK_MONOTONIC), n->hi, REACH_END}; pidx_added();   // not in the residency set yet: put in the first time it is addressed (pool_res)
    g_pool_adds++;
    [g_keep addObject:n->buf];
}
static void pool_dying_take(uintptr_t lo, uintptr_t hi, uint64_t oldest, NSMutableArray<id<MTLBuffer>> *gone); static void pool_gone_release(NSMutableArray<id<MTLBuffer>> *gone);
void mtl_pool_add(const void *mem, uint64_t size) {
    mtl_init();   // the change is recorded once the pool can be found (reg_bump below): a reader that sees the new generation sees the pool
    pool_new n; pool_new_prep(&n, mem, size);
    @autoreleasepool {
    NSMutableArray<id<MTLBuffer>> *gone = [NSMutableArray array];
    mu_lock(); pool_dying_take((uintptr_t)mem, (uintptr_t)mem + size, 0, gone); pool_new_put(&n); if (gone.count) pool_gone_release(gone); pthread_mutex_unlock(&g_mu);   // a finalized pool over the same memory goes first
    }
    reg_bump(-1, REG_POOL);
}

static void big_moved(int i) {   // caller holds g_mu: entry i has a new index
    const pool_ent *e = &g_pools[i];
    for (int k = 0; k < g_nbig; k++) { big_pool *b = &g_big[k]; if (b->mem != e->key) continue;
        if (e->reach == REACH_WHOLE) b->full = i + 1; else b->chunk[(e->lo - b->a) >> 24] = i + 1;
        return; }
}
// The no-copy buffer goes through deferred release (out of the residency set and unreferenced after submitted commands complete). It used to be removed only from g_keep while the residency set still held a strong reference: after the pool was freed the buffer stayed alive wrapping that guest memory,
// and a new pool at the same address wrapped it again. Engage's title demo cycles scenes; GPU allocated grew to 5.4 GB and resident memory to 3.6 GB in 850 s.
// In an autorelease pool of its caller's: this runs on the guest thread that finalizes the pool, whose implicit pool never drains, and adding to the weak table g_dead_pools left the buffer
// autoreleased there, so every finalized pool buffer stayed alive for good (Ghost Trick: Phantom Detective, 125 buffers and 6.6 GB of GPU allocations 300 frames into the boot, 0 with the pool)
static void pool_take_out(const void *mem, NSMutableArray<id<MTLBuffer>> *gone) {   // caller holds g_mu
    int bg = -1; for (int k = 0; k < g_nbig; k++) if (g_big[k].mem == mem) bg = k;
    for (int i = 0; i < g_npool; i++)
        if (g_pools[i].key == mem) { id<MTLBuffer> b = g_pools[i].buf; [g_keep removeObject:b]; [gone addObject:b]; if (g_pools[i].res) g_pool_res_n--;
            if (!g_dead_pools) g_dead_pools = [NSHashTable weakObjectsHashTable];
            [g_dead_pools addObject:b]; pidx_removing(i); g_pools[i] = g_pools[--g_npool]; g_plast = -1; atomic_store(&g_pool_drop_gen, atomic_fetch_add(&g_pool_gen, 1) + 1);
            if (i < g_npool) big_moved(i);   // the entry moved into this place
            if (bg < 0) break;   // a large pool has an entry per chunk
            i--; }
    if (bg >= 0) {
        [gone addObjectsFromArray:g_big[bg].old];
        free(g_big[bg].chunk); g_big[bg] = g_big[--g_nbig]; g_plast = -1; atomic_store(&g_pool_drop_gen, atomic_fetch_add(&g_pool_gen, 1) + 1); atomic_fetch_sub(&g_big_n, 1);
    }
}
// Once out of the table and with g_pool_gen bumped, a buffer is reached only by what a submission already encoded: so with none open it waits for the last committed fence, not the
// next one, which a game that stops submitting never reaches (defer_kick). The open flag is read after the bump, and mtl_sub_begin sets it before its lookups, each side with a full
// fence: a submission either is seen open or sees the bump, and then neither the per-thread cache (pc_get, no lock) nor the table gives it this buffer.
// The open flag holds that submission's own fence and is read before g_fence: the commit clears it only after its ++g_fence, so a 0 read means the g_fence read after it counts that
// submission. As g_fence + (open ? 1 : 0), one expression, C left the order of the two reads open: g_fence read before a commit's ++g_fence and the flag after its clear gave the fence
// before that submission's, which may be done already, and defer_kick could free the buffer while the submission ran (PR #2328). A 0/1 flag read first is still one fence late when a
// commit lands between the reads, a fence a game that stops submitting never reaches. mtl_pool_replace retires through here too
static void pool_gone_release(NSMutableArray<id<MTLBuffer>> *gone) {   // caller holds g_mu
    atomic_thread_fence(memory_order_seq_cst);
    uint64_t open = atomic_load(&g_sub_open);
    if (g_pool_gone_between) g_pool_gone_between();
    uint64_t fence = open ? open : atomic_load(&g_fence);
    for (id<MTLBuffer> b in gone) defer_obj_at(b, 0, fence);
}
void mtl_pool_del(const void *mem) {
    reg_bump(-1, REG_POOL);
    @autoreleasepool {
    NSMutableArray<id<MTLBuffer>> *gone = [NSMutableArray array];
    mu_lock(); pool_take_out(mem, gone); pool_gone_release(gone); pthread_mutex_unlock(&g_mu);
    }
}
// A pool the game finalized is taken out in replay order (ported from S2Arm d9af7859, Apache-2.0): commands the game recorded before its nvnMemoryPoolFinalize and submitted after it,
// or submitted before it and not replayed yet, still name its addresses, and a pool already taken out left their vertices reading 0 and their index and storage buffers the dummy.
// So nvnMemoryPoolFinalize only notes it (mtl_pool_retire) with the queue's count of submissions then (hle_nvn.c nvn_queue_seq); it stays findable, its entries, chunks and index
// as they were, until every submission up to the first one submitted after the Finalize has been replayed: the replay asks at each submission it begins, with the oldest one not done
// (mtl_pool_reap). A new pool over any of its memory takes it out first (mtl_pool_add, mtl_pool_replace), as its zero-copy buffer may cover pages the game mapped again since.
// Its buffers then go through pool_gone_release as before. mtl_pool_del (a virtual pool's runs, whose mappings change in queue order anyway, and the tests) takes a pool out at once
typedef struct { const void *key; uintptr_t lo, hi; uint64_t after; } pool_dying;   // after: the queue's submissions when the game finalized it
static pool_dying *g_dying; static int g_ndying, g_dying_cap;   // under g_mu
// Caller holds g_mu: takes out every finalized pool overlapping [lo, hi), and with oldest set every one the replay is past (the oldest submission not done is past the first one after it)
static void pool_dying_take(uintptr_t lo, uintptr_t hi, uint64_t oldest, NSMutableArray<id<MTLBuffer>> *gone) {
    for (int i = 0; i < g_ndying; i++) {
        pool_dying *d = &g_dying[i];
        if (!((hi > lo && d->lo < hi && lo < d->hi) || (oldest && oldest > d->after + 1))) continue;
        pool_take_out(d->key, gone);
        g_dying[i--] = g_dying[--g_ndying];
    }
}
void mtl_pool_retire(const void *mem, uint64_t size, uint64_t after) {
    mu_lock();
    if (g_ndying == g_dying_cap) { g_dying_cap = g_dying_cap ? g_dying_cap * 2 : 64; g_dying = realloc_or_die(g_dying, (size_t)g_dying_cap * sizeof *g_dying, "the finalized pool list"); }
    g_dying[g_ndying++] = (pool_dying){mem, (uintptr_t)mem, (uintptr_t)mem + size, after};
    pthread_mutex_unlock(&g_mu);
}
void mtl_pool_reap(uint64_t oldest) {   // the replay, at each submission it begins: oldest is the queue's oldest submission not done (nvn_queue.inc nq_worker)
    if (!g_ndying) return;   // read without the lock: a pool finalized meanwhile waits for the next submission, which it must anyway
    int taken = 0;
    @autoreleasepool {
    NSMutableArray<id<MTLBuffer>> *gone = [NSMutableArray array];
    mu_lock(); int n0 = g_ndying; pool_dying_take(0, 0, oldest, gone); taken = n0 != g_ndying; if (gone.count) pool_gone_release(gone); pthread_mutex_unlock(&g_mu);
    }
    if (taken) reg_bump(-1, REG_POOL);
}
// Pools that take the place of others, in one step under g_mu: a lookup finds the old ones or the new ones, never neither. A sparse pool's mapped run is a pool of its own, replaced
// whenever a mapping joins it to its neighbours or an unmap splits it (hle_nvn.c vrun_set), on the game's thread while the replay looks addresses up on its own. Removed and then
// added, an address mapped all along was in no pool between the two: PRAGMATA's mesh shaders 765e6d9d2588ce70 and 5aab38bb5ba67ef7 read a buffer whose address the game pushes,
// 0x3000000 into a sparse pool whose one run kept growing (0x8c5e304000..0x8c7b1a4000, then on), and got a dummy buffer at frames 2971 and 4484, the frames the run was replaced in
void mtl_pool_replace(const void *const *del, int ndel, const void *const *add, const uint64_t *size, int nadd) {
    mtl_init();
    pool_new *n = nadd ? (pool_new *)calloc((size_t)nadd, sizeof *n) : NULL; if (nadd && !n) MDIE("pool replacement");
    for (int i = 0; i < nadd; i++) pool_new_prep(&n[i], add[i], size[i]);
    reg_bump(-1, REG_POOL);
    @autoreleasepool {
    NSMutableArray<id<MTLBuffer>> *gone = [NSMutableArray array];
    mu_lock();
    for (int i = 0; i < ndel; i++) pool_take_out(del[i], gone);
    for (int i = 0; i < nadd; i++) { pool_dying_take(n[i].lo, n[i].hi, 0, gone); pool_new_put(&n[i]); }
    pool_gone_release(gone);
    pthread_mutex_unlock(&g_mu);
    }
    for (int i = 0; i < nadd; i++) n[i].buf = nil;   // release the references before the memory goes (a strong member of a calloc'd array)
    free(n);
    reg_bump(-1, REG_POOL);
}

// Address → pool: the last hit first, then a binary search over indices sorted by start address, and a full linear scan only when that fails (pools overlapping).
// The Legend of Zelda: Breath of the Wild keeps about 1760 memory pools alive and every buffer binding of every draw looks one up; the old full scan took about 4% of the submit thread's samples (mtl_gpu_addr 222 / 6 s).
// The index is sorted the first time it is used and then follows each entry added or removed in place (pidx_added / pidx_removing): every registration or removal used to invalidate it,
// and a game that makes or frees a pool or two a frame among ~1,760 re-sorted all of them at the next lookup (the S2Arm project measured that qsort at 3.3% of its submit thread). When
// the index is not current or an entry is not where the order says, it is invalidated and the next lookup re-sorts it whole. Caller holds g_mu
static int pidx_cmp(const void *a, const void *b) { uintptr_t x = g_pools[*(const int *)a].lo, y = g_pools[*(const int *)b].lo; return x < y ? -1 : x > y; }
static void pidx_sort(void) {
    if (g_pidx_ok) return;
    if (g_pidx_cap < g_npool) { g_pidx_cap = g_npool * 2; g_pidx = realloc_or_die(g_pidx, (size_t)g_pidx_cap * sizeof *g_pidx, "the memory pool index"); }
    for (int i = 0; i < g_npool; i++) g_pidx[i] = i;
    qsort(g_pidx, (size_t)g_npool, sizeof *g_pidx, pidx_cmp); g_pidx_ok = 1;
}
static int pidx_pos(uintptr_t lo, int n) { int a = 0, b = n; while (a < b) { int m = (a + b) / 2; if (g_pools[g_pidx[m]].lo < lo) a = m + 1; else b = m; } return a; }   // the first of n index entries starting at lo or after
static int pidx_of(int pool, int n) {   // where entry pool is among the first n index entries, or -1
    int p = pidx_pos(g_pools[pool].lo, n);
    while (p < n && g_pidx[p] != pool && g_pools[g_pidx[p]].lo == g_pools[pool].lo) p++;
    return p < n && g_pidx[p] == pool ? p : -1;
}
static void pidx_added(void) {   // g_pools[g_npool - 1] is the new entry
    if (!g_pidx_ok) return;
    if (g_pidx_cap < g_npool) { int c = g_npool * 2; int *g = realloc(g_pidx, (size_t)c * sizeof *g_pidx); if (!g) { g_pidx_ok = 0; return; } g_pidx = g; g_pidx_cap = c; }
    int n = g_npool - 1, p = pidx_pos(g_pools[n].lo, n);
    memmove(g_pidx + p + 1, g_pidx + p, (size_t)(n - p) * sizeof *g_pidx); g_pidx[p] = n;
}
static void pidx_removing(int i) {   // before g_pools[i] = g_pools[--g_npool]: i's index entry goes, and the last entry's is renamed i
    if (!g_pidx_ok) return;
    int n = g_npool, last = n - 1, p = pidx_of(i, n);
    if (p < 0) { g_pidx_ok = 0; return; }
    memmove(g_pidx + p, g_pidx + p + 1, (size_t)(n - 1 - p) * sizeof *g_pidx);
    if (i != last) { int q = pidx_of(last, n - 1); if (q < 0) { g_pidx_ok = 0; return; } g_pidx[q] = i; }
}
static int big_new(big_pool *b, uintptr_t lo, uintptr_t hi, uintptr_t end, int reach) {   // caller holds g_mu: a new entry for [lo, end) of the pool, looked up for addresses in [lo, hi)
    id<MTLBuffer> buf = pool_buf(lo, end);
    if (!buf) { MLOG("[RED] memory pool %p: the zero-copy buffer over %#lx..%#lx was refused", b->mem, (unsigned long)lo, (unsigned long)end); return -1; }
    if (g_npool == g_cap) { g_cap = g_cap ? g_cap * 2 : 64; g_pools = realloc_or_die(g_pools, g_cap * sizeof *g_pools, "the memory pool table"); }
    atomic_fetch_add(&g_pool_gen, 1);
    g_pools[g_npool++] = (pool_ent){lo < b->lo ? b->lo : lo, hi > b->hi ? b->hi : hi, lo, buf, buf.gpuAddress, b->mem, 0, clock_gettime_nsec_np(CLOCK_MONOTONIC), end > b->hi ? b->hi : end, reach}; pidx_added();
    [g_keep addObject:buf];
    return g_npool - 1;
}
// The entry of a large pool for [addr, addr + len): the chunk of its stride, made or lengthened to reach as far as asked, or the whole pool for a lookup of unknown length; -1 past the pool's end.
// The chunks made before the whole pool's buffer stay, resident: what was encoded with them still reads through them
static int big_full(big_pool *b, const char *why) {
    int n = big_new(b, b->a, b->b, b->b, REACH_WHOLE);
    if (n < 0) return -1;
    b->full = n + 1;
    static int nl; if (nl++ < 16) { int c = 0; uint64_t mb = 0; for (int i = 0; i < g_npool; i++) if (i != n && g_pools[i].key == b->mem) { c++; mb += g_pools[i].buf.length; }
        for (id<MTLBuffer> o in b->old) { c++; mb += o.length; }
        MLOG("memory pool %p+%llu MB: one buffer of the whole pool (%s); the chunks made before it stay: %d, %llu MB", b->mem, (unsigned long long)((b->hi - b->lo) >> 20), why, c, (unsigned long long)(mb >> 20)); }
    return n;
}
static int big_lookup(big_pool *b, uint64_t addr, uint64_t len) {
    if (addr + len > b->hi) return -1;
    if (b->full) return b->full - 1;
    if (len <= 1) return big_full(b, "a lookup of unknown length");
    uintptr_t k = (addr - b->a) >> 24, lo = b->a + (k << 24);
    uintptr_t end = (addr + len + BIG_S - 1) & ~(uintptr_t)(BIG_S - 1); end += BIG_S; if (end > b->b || end < lo) end = b->b;
    int i = b->chunk[k] - 1;
    uintptr_t have = i >= 0 ? g_pools[i].end : 0;
    if (i >= 0 && (have >= b->hi || have >= addr + len)) return i;
    int n = big_new(b, lo, lo + BIG_S, end, end >= b->b ? REACH_END : REACH_SHORT); if (n < 0) return -1;
    if (i >= 0) {   // lengthened: what is encoded with the shorter chunk keeps it, resident, until the pool goes
        [b->old addObject:g_pools[i].buf]; [g_keep removeObject:g_pools[i].buf]; g_pools[n].res = 0; if (g_pools[i].res) g_pool_res_n--;
        if (g_pools[i].lo != g_pools[n].lo) g_pidx_ok = 0;   // the same stride starts at the same place; were it not, i's index entry would be out of order
        pidx_removing(n); g_pools[i] = g_pools[n]; g_npool--; n = i;
    }
    b->chunk[k] = n + 1;
    return n;
}
static int pool_held(uint64_t addr, uint64_t len) {   // the entry of g_pools holding [addr, addr + len), made by no lookup: an ordinary pool, or an existing chunk
    if (len > UINT64_MAX - addr) return -1;   // an overflowing exclusive end cannot lie in a pool, including the cached one (upstream f15d65850)
    if (g_plast >= 0 && g_plast < g_npool && addr >= g_pools[g_plast].lo && addr + len <= g_pools[g_plast].hi) return g_plast;
    pidx_sort();
    int lo = 0, hi = g_npool - 1, hit = -1;   // the last one whose start ≤ addr
    while (lo <= hi) { int m = (lo + hi) / 2; if (g_pools[g_pidx[m]].lo <= addr) { hit = m; lo = m + 1; } else hi = m - 1; }
    if (hit >= 0 && addr + len <= g_pools[g_pidx[hit]].hi) return g_plast = g_pidx[hit];
    for (int i = 0; i < g_npool; i++) if (addr >= g_pools[i].lo && addr + len <= g_pools[i].hi) return g_plast = i;
    return -1;
}
// The entry for a GPU use of [addr, addr + len): a large pool's chunk is made or lengthened to reach as far as asked (big_lookup)
static int pool_find(uint64_t addr, uint64_t len) {
    if (g_nbig) { int b = big_of(addr); if (b >= 0) return big_lookup(&g_big[b], addr, len); }
    return pool_held(addr, len);
}
// The entry that holds addr, or -1, making no buffer: a large pool answers with its stride's chunk if it has one. For questions no GPU use follows: through pool_find the pool walk's log
// asked about every texture's storage and made a chunk of 80 MB and more for each stride (then 64 MB past the address), or lengthened its chunk to that, 77 of them, 6.7 GB counted
// by Metal, in Ocarina of Time's first area load. Caller holds g_mu
static int pool_peek(uint64_t addr) {
    if (g_nbig) { int b = big_of(addr); if (b >= 0) { const big_pool *bp = &g_big[b]; return bp->full ? bp->full - 1 : bp->chunk[(addr - bp->a) >> 24] - 1; } }
    return pool_held(addr, 1);
}
// Whether [addr, addr + len) lies in a pool, with no side effect: mtl_addr makes the pool resident, for a GPU use to follow. A large pool is answered from its range, since its lookup
// (big_lookup) makes the chunk that holds the range. hle_nvn.c keys_hash asks this whether a shader's code is mapped: through mtl_addr every pool holding shader code went into the
// residency set, though the GPU never reads it (the shaders run translated): The Great Ace Attorney Chronicles' three chunks, about 5 MB
int mtl_addr_known(uint64_t addr, uint64_t len) {
    mu_lock(); int b = big_of(addr), ok = b >= 0 ? addr + len <= g_big[b].hi : pool_find(addr, len) >= 0; pthread_mutex_unlock(&g_mu);
    return ok;
}
int mtl_addr(uint64_t addr, uint64_t len, void **buf, uint64_t *off) {
    const pc_ent *c = t_tex_upload_lookup ? NULL : pc_get(addr, len);   // an upload's lookup is always counted (and never cached: pc_put), so an entry of t_pc means an other use was
    if (c) { *buf = (__bridge void *)c->buf; *off = addr - c->base; return 1; }
    int ok = 0;
    mu_lock();
    int i = pool_find(addr, len);
    if (i >= 0) pool_counted(i);
    int added = 0;
    if (i >= 0) { added = pool_res(i); if (!t_tex_upload_lookup) pc_put(i, addr); *buf = (__bridge void *)g_pools[i].buf; *off = addr - g_pools[i].base; ok = 1; }
    pthread_mutex_unlock(&g_mu);
    pool_res_commit(added);
    return ok;
}
int mtl_gpu_addr(uint64_t addr, uint64_t len, void **buf, uint64_t *off, uint64_t *gpu) {
    const pc_ent *c = t_tex_upload_lookup ? NULL : pc_get(addr, len);   // an upload's lookup is always counted (and never cached: pc_put), so an entry of t_pc means an other use was
    if (c) { *buf = (__bridge void *)c->buf; *off = addr - c->base; *gpu = c->gpu + *off; return 1; }
    int ok = 0;
    mu_lock();
    int i = pool_find(addr, len);
    if (i >= 0) pool_counted(i);
    int added = 0;
    if (i >= 0) { added = pool_res(i); if (!t_tex_upload_lookup) pc_put(i, addr); *buf = (__bridge void *)g_pools[i].buf; *off = addr - g_pools[i].base; *gpu = g_pools[i].gpu + *off; ok = 1; }
    pthread_mutex_unlock(&g_mu);
    pool_res_commit(added);
    return ok;
}

// ---------- Submission ----------
typedef struct { int kind; volatile uint32_t *val; uint32_t mode, v; uint64_t addr; uint32_t type; void *vis; uint32_t seg, vhi; } post_op;   // vis: the visibility slot table for kind 3 (DM_NVN_QUERY_POOL=0), else v..vhi its slots in the submission's arena; seg: the segment it was encoded in (sub_cut)
static uint32_t g_seg;   // Index of the segment being encoded in this submission (0 until the first sub_cut)
static uint64_t g_cbgen; static int gsb_held(const void *mem, uint64_t size);   // main command buffers committed; whether storage overlaps what the one being encoded writes on the GPU (gsb_store)
typedef struct seg_clk seg_clk; static seg_clk *g_sclk; static void seg_clk_put(seg_clk *c);   // Counter timestamps by segment (see gpu_ticks)
// ---------- Conditional rendering (profile render_cond) ----------
// SetRenderEnableConditional(mode, rec) enables rendering if the 64-bit counter of the report at rec equals (RENDER_IF_EQUAL) or differs from (RENDER_IF_NOT_EQUAL) the one at
// rec + 16, until the next SetRenderEnable(true). Tears of the Kingdom wraps nearly every ClearColor / ClearDepthStencil this way: rec is set to 1 from the CPU when the target
// needs a clear, each clear is followed by ReportCounter(TIMESTAMP_TOP, rec), and rec + 16 is never written. A timestamp report puts 0 in the counter field (the time goes in the
// second field), so after one clear the two compare equal and later conditional clears of that target are skipped. The host used to ignore the condition and write the time
// into both fields, so every clear ran: the first tile-lighting round, the half-resolution scene depth its light volumes test against and the light accumulation were cleared
// before the composite read them, and the 3D scene came out black.
// Metal has no predication, so the condition is evaluated here at replay, on the CPU, from the records in memory. A report in an earlier unfinished GPU prefix is not written yet
// (that happens when the GPU completes): a timestamp one counts with its known counter 0; a samples-passed result (an occlusion query, written from the visibility buffers) is
// unknown until its submission completes, and a condition on it keeps drawing (occlusion culling only saves work). Once it has landed the condition is evaluated from it, as the
// GPU would at that point in the queue: Ocarina of Time reports its queries a submission ahead of the conditional draws, so every one has landed by then (1.48 million
// conditions on its Kokiri Forest route, 42% false; the host drew them all, GPU p50 17.06 → 16.44 ms a frame on an M4 Pro). Inside a block evaluated false, draws and clears are dropped
static int g_rc_skip;   // logical queue state: a render-enable block evaluated false is active
// Latest command-ordered writer of each report counter. Completed reports are read
// from memory, so CPU rewrites remain visible. Unfinished queries stay unknown;
// timestamp counters and explicit writes can supply known bytes before completion.
// Address lookup is constant-time. The dirty list stamps only this prefix's writers,
// and the page index keeps unrelated buffer updates out of the report table.
typedef struct rc_report {
    uint64_t addr, fence, value, report_fence, gpu_epoch;
    uint8_t known, dirty, readable, reported, report_dirty, unreliable, gpu_domain, opaque_unreliable, opaque_later, conservative;
    struct rc_report *page_next, *dirty_next;
    struct rc_report *lo16, *hi16;   // the records at addr - 16 and addr + 16 once found (DM_NVN_QUERY_POOL): a record lives until rc_forget drops them all, so a found one stays valid
} rc_report;
static nvn_hmap g_rc_reports={.klen=8}, g_rc_pages={.klen=8};
static uint64_t *g_rc_page_order; static uint32_t g_rc_page_n, g_rc_page_cap;
static uint32_t rc_page_lower(uint64_t page) {
    uint32_t lo=0, hi=g_rc_page_n;
    while (lo<hi) { uint32_t mid=lo+(hi-lo)/2; if (g_rc_page_order[mid]<page) lo=mid+1; else hi=mid; }
    return lo;
}
static void rc_page_add(uint64_t page) {
    uint32_t at=rc_page_lower(page);
    if (g_rc_page_n==g_rc_page_cap) {
        uint32_t cap=g_rc_page_cap ? g_rc_page_cap*2 : 64;
        uint64_t *p=realloc(g_rc_page_order,(size_t)cap*sizeof *p);
        if (!p) MDIE("no memory for the report page index");
        g_rc_page_order=p; g_rc_page_cap=cap;
    }
    memmove(g_rc_page_order+at+1,g_rc_page_order+at,(g_rc_page_n-at)*sizeof *g_rc_page_order);
    g_rc_page_order[at]=page; g_rc_page_n++;
}
static rc_report *g_rc_dirty;
static uint64_t g_rc_gpu_epoch, g_rc_gpu_fence;
static int g_rc_gpu_dirty;
// Published after the CPU post effects land, before an event can wake a CPU writer.
// g_done is later than event publication and would briefly hide such a writer.
static _Atomic uint64_t g_rc_complete;
static rc_report *rc_find(uint64_t addr) { return nvn_hm_get(&g_rc_reports,&addr); }
static void rc_touch(rc_report *r) {
    r->fence=0; r->gpu_epoch=g_rc_gpu_epoch;
    if (!r->dirty) { r->dirty=1; r->dirty_next=g_rc_dirty; g_rc_dirty=r; }
}
static void rc_commit(uint64_t fence) {
    for (rc_report *r=g_rc_dirty,*next;r;r=next) {
        next=r->dirty_next; r->fence=fence; r->dirty=0; r->dirty_next=NULL;
        if (r->report_dirty) { r->report_fence=fence; r->report_dirty=0; }
    }
    g_rc_dirty=NULL;
    if (g_rc_gpu_dirty) { g_rc_gpu_fence=fence; g_rc_gpu_dirty=0; }
}
static void rc_forget(void) {
    g_rc_dirty=NULL; g_rc_gpu_epoch=g_rc_gpu_fence=0; g_rc_gpu_dirty=0;
    nvn_hm_clear(&g_rc_pages,NULL); nvn_hm_clear(&g_rc_reports,free);
    free(g_rc_page_order); g_rc_page_order=NULL; g_rc_page_n=g_rc_page_cap=0;
}
static rc_report *rc_ensure(uint64_t addr) {
    rc_report *r=rc_find(addr);
    if (!r) {
        r=calloc(1,sizeof *r); if (!r) MDIE("no memory for the report table");
        r->addr=addr; r->readable=1; r->gpu_epoch=g_rc_gpu_epoch; nvn_hm_put(&g_rc_reports,&addr,r);
        uint64_t page=addr>>12; r->page_next=nvn_hm_get(&g_rc_pages,&page);
        if (!r->page_next) rc_page_add(page);
        nvn_hm_put(&g_rc_pages,&page,r);
    }
    return r;
}
static void rc_query_operand(rc_report *r) {
    if (r->gpu_domain) return;
    r->gpu_domain=1;
    // An earlier opaque writer may have raced this timestamp before the address
    // first participated in a query comparison. Do not expose its CPU-post bytes.
    if (r->opaque_later) { r->known=0; r->opaque_later=0; }
    if (r->opaque_unreliable) r->unreliable=1;
}
static int qpool_on(void);
// The neighbour a condition compares with (+16) or a query's operand pair (-16 / +16), by pointer once found: each look-up was a hash probe, three a samples-passed report and two a
// condition, about 7,500 a frame in Ocarina of Time. Not cached while missing, so a record made later is found
static rc_report *rc_hi(rc_report *r) { if (!r->hi16 || !qpool_on()) r->hi16=rc_find(r->addr+16); return r->hi16; }
static rc_report *rc_ensure_lo(rc_report *r) { if (!r->lo16 || !qpool_on()) r->lo16=rc_ensure(r->addr-16); return r->lo16; }
static rc_report *rc_ensure_hi(rc_report *r) { if (!r->hi16 || !qpool_on()) r->hi16=rc_ensure(r->addr+16); return r->hi16; }
static void rc_note(uint64_t addr, int kind) {
    rc_report *r=rc_ensure(addr);
    r->conservative=kind==3;   // counter kinds the host does not implement; a samples-passed result is read once it has landed (rc_value)
    // A condition compares adjacent 16-byte records. Either operand can be the
    // query; track its unreported neighbor before later explicit buffer writers.
    // Existing entries keep their own report type, pending fence and known bytes.
    if (kind==2) { rc_query_operand(r); if (addr>=16) rc_query_operand(rc_ensure_lo(r)); rc_query_operand(rc_ensure_hi(r)); }
    // Only timestamp and samples-passed reports have implemented counter values.
    // Other counter kinds retain the conservative fallback after their placeholder lands.
    r->value=0; r->known=kind==1 ? 255 : 0; r->readable=kind!=3;
    r->reported=r->report_dirty=1; r->report_fence=0; r->unreliable=r->opaque_unreliable=r->opaque_later=0; rc_touch(r);
}
static int rc_gpu_unknown(rc_report *r, uint64_t done) {
    if (!r->gpu_domain || r->gpu_epoch==g_rc_gpu_epoch) return 0;
    // An unbounded shader writer may race a CPU-landed query. A fresh report or
    // explicit full write can establish that counter again. Unreported reference
    // words have no deferred CPU report, so they become readable after the writer.
    if (r->reported || g_rc_gpu_dirty || g_rc_gpu_fence>done) return 1;
    r->gpu_epoch=g_rc_gpu_epoch; return 0;
}
static int rc_value_of(rc_report *r, uint64_t addr, uint64_t *v) {   // 0 = unknown at encode time; r: addr's record, NULL when it has none
    uint64_t done=atomic_load_explicit(&g_rc_complete,memory_order_acquire);
    if (r) {
        if (r->conservative) return 0;
        if (rc_gpu_unknown(r,done)) return 0;
        if (r->dirty || r->fence>done) { *v=r->value; return r->known==255; }
        if (!r->readable || r->unreliable) return 0;
    }
    *v=*(const volatile uint64_t *)addr; return 1;
}
static int rc_value(uint64_t addr, uint64_t *v) { return rc_value_of(rc_find(addr),addr,v); }
// A condition's two counters (addr, addr + 16), each 0 = unknown: the second found from the first's record (rc_hi)
static int rc_values(uint64_t addr, uint64_t *x, uint64_t *y) {
    if (!qpool_on()) return rc_value(addr,x) & rc_value(addr+16,y);
    rc_report *r=rc_find(addr), *h=r ? rc_hi(r) : rc_find(addr+16);
    return rc_value_of(r,addr,x) & rc_value_of(h,addr+16,y);
}
// Counter records need not share a page with the buffer write. Include the previous
// seven bytes so even an unaligned eight-byte counter crossing a page is covered.
static rc_report *rc_containing(uint64_t addr) {
    uint64_t first=(addr>7 ? addr-7 : 0)>>12, last=addr>>12;
    for (uint64_t page=first;page<=last;page++)
        for (rc_report *r=nvn_hm_get(&g_rc_pages,&page);r;r=r->page_next)
            if (addr>=r->addr && addr-r->addr<8) return r;
    return NULL;
}
static uint8_t rc_source(uint64_t a, unsigned n, uint8_t *out, int *unreliable);
static void rc_overwrite(rc_report *r, uint64_t dst, uint64_t n, const void *data, unsigned period, uint64_t src, uint64_t done, int opaque) {
    uint64_t lo=MAX(dst,r->addr), hi=MIN(dst+n,r->addr+8);
    if (hi<=lo) return;
    if (opaque && !r->gpu_domain) {
        // Keep ordinary timestamp forwarding unchanged, but retain this history
        // in case a later query makes the address a comparison operand.
        if (r->reported) r->opaque_unreliable=r->opaque_later=1;
        return;
    }
    int report_pending=r->reported && (r->report_dirty || r->report_fence>done);
    if (r->opaque_later) { r->known=0; r->opaque_later=0; }
    if (r->opaque_unreliable) r->unreliable=1;
    if ((r->reported && r->gpu_epoch!=g_rc_gpu_epoch) || rc_gpu_unknown(r,done)) { r->known=0; if (r->reported) r->unreliable=1; }
    if (opaque) {
        if (report_pending) r->unreliable=1;
        r->known=0; rc_touch(r); return;
    }
    // The preceding writer has landed: keep unaffected bytes from the current CPU
    // value, including a legal CPU rewrite after that writer completed.
    if (!r->dirty && r->fence<=done) {
        if (r->readable && !r->unreliable && !rc_gpu_unknown(r,done)) { r->value=*(const volatile uint64_t *)r->addr; r->known=255; }
        else r->known=0;
    }
    int unreliable=report_pending;
    unsigned at=(unsigned)(lo-r->addr), bytes=(unsigned)(hi-lo);
    if (data) {
        for (unsigned b=0;b<bytes;b++) {
            uint64_t off=lo+b-dst;
            ((uint8_t *)&r->value)[at+b]=((const uint8_t *)data)[period ? off%period : off];
            r->known|=(uint8_t)(1u<<(at+b));
        }
    } else {
        uint8_t value[8], known=rc_source(src+lo-dst,bytes,value,&unreliable), mask=(uint8_t)(((1u<<bytes)-1)<<at);
        for (unsigned b=0;b<bytes;b++) if (known>>b&1) ((uint8_t *)&r->value)[at+b]=value[b];
        r->known=(r->known&~mask)|(known<<at);
    }
    if (r->known==255) r->readable=1;
    // Query reports still land on the CPU after GPU execution. A following GPU
    // overwrite/copy can therefore leave unreliable final bytes. Preserve the
    // existing conservative fallback for this unsupported ordering pattern;
    // pending command-known values remain valid, but completed memory is not used.
    if (unreliable) r->unreliable=1;
    else if (at==0 && bytes==8) r->unreliable=r->opaque_unreliable=r->opaque_later=0;
    rc_touch(r);
}
// A later explicit buffer write replaces the report's command-ordered knowledge,
// including partial writes. Its bytes stay live until that writer completes.
// This does not make CPU-landed query reports ordered GPU sources: arbitrary
// shader-produced predicates and GPU reads of an unfinished report remain unsupported.
static void rc_change(uint64_t dst, uint64_t n, const void *data, unsigned period, uint64_t src, int opaque) {
    if (!g_rc_reports.n || !n) return;
    uint64_t done=atomic_load_explicit(&g_rc_complete,memory_order_acquire);
    uint64_t first=(dst>7 ? dst-7 : 0)>>12, last=(dst+n-1)>>12;
    // Large writable bindings are common on every draw. Search the recorded page
    // addresses, then visit only intersecting pages; scanning every report made
    // unrelated storage buffers cost several milliseconds per frame.
    if (last-first>=8) {
        for (uint32_t i=rc_page_lower(first);i<g_rc_page_n && g_rc_page_order[i]<=last;i++)
            for (rc_report *r=nvn_hm_get(&g_rc_pages,&g_rc_page_order[i]);r;r=r->page_next) rc_overwrite(r,dst,n,data,period,src,done,opaque);
    } else {
        for (uint64_t page=first;page<=last;page++)
            for (rc_report *r=nvn_hm_get(&g_rc_pages,&page);r;r=r->page_next) rc_overwrite(r,dst,n,data,period,src,done,opaque);
    }
}
static void rc_write(uint64_t dst, uint64_t n, const void *data, unsigned period) { rc_change(dst,n,data,period,0,0); }
static void rc_copy(uint64_t src, uint64_t dst, uint64_t n) { if (src!=dst) rc_change(dst,n,NULL,0,src,0); }
static void rc_gpu_write(uint64_t dst, uint64_t n) {
    if (!n) { g_rc_gpu_epoch++; g_rc_gpu_dirty=1; }
    else rc_change(dst,n,NULL,0,0,1);
}
// ---------- Occlusion queries (NVN_COUNTER_TYPE_SAMPLES_PASSED) ----------
// NVN semantics: samples passed is a cumulative counter on the queue - ResetCounter zeroes it, every draw afterwards adds to it, and ReportCounter writes out the cumulative value at that moment (+ timestamp) when the GPU completes.
// Metal: every render pass attaches a visibility result buffer; draws during counting use counting mode, with a new slot per pass (no reliance on accumulation across passes). The counter is one running total
// (g_vis_acc), kept by post_run in submission order under g_post_mu: a report hands the slots since the previous report (retained) to its submission's completion, which adds them to the total and writes it out;
// the slots left at a submission's end are added at its completion too (VIS_FOLD), so a slot is read once, while its buffer is still this submission's (the ring hands it to a later one once the fence passes);
// a reset drops the slots before it and zeroes the total there (VIS_ZERO). After a report a new slot is used, so later draws are not counted into the reported value.
// Counting starts at the first reset or, for a game that never resets, at the first report: the GPU's counter runs from the queue's creation, so such a game reads end - begin of two reports around each query
// (Red Dead Redemption's character occlusion queries: counting used to start only at a reset, so every report was 0 and the bodies of characters a few metres away were dropped).
// (Previously always wrote 0: occlusion query = 'fully occluded', campfires / light sources got culled - the character select screen calls ResetCounter 21 times per frame)
typedef struct { void *buf; uint32_t slot; } vis_slot;
typedef struct { int n; vis_slot s[]; } vis_list;
#define VIS_SLOTS 8192
typedef struct { __strong id<MTLBuffer> buf; uint64_t fence; } vis_buf;
// One visibility buffer per submission in flight, as many as command allocators: with 4, Age of Calamity (about twelve submissions a frame) waited in mtl_sub_begin for the previous frame's GPU work; its first battle went from 18.0 to 16.9 ms a frame on the Mac
// The ring grows on demand (vis_take), each buffer kept resident and reused once its submission's fence passes. Since a frame's submissions share a command allocator, more
// counting submissions are in flight than allocators: with a ring of 8, a GPU running behind left none free and each such submission made a one-off buffer, added to the
// residency set and removed after it, two residency changes, each committed through the kernel's GPU driver, per submission (Ocarina of Time on an iPhone 17: about 9 a frame, upstream issue #2535).
// So the ring holds one for every submission that can be in flight, SUB_FLIGHT_MAX committed and the one being encoded, and never runs dry: it grows only to the most counting
// submissions in flight at once (129 x 64 KiB, about 8 MiB, at most)
enum { VIS_RING = SUB_FLIGHT_MAX + 1 };
static vis_buf g_vis_ring[VIS_RING]; static int g_vis_ring_n, g_vis_ring_i = -1;
static id<MTLBuffer> g_vis; static uint32_t g_vis_n;   // This submission's visibility buffer and number of slots used
static void vis_take(void);
// Whether b is this submission's ring buffer: g_vis is either that or an overflow buffer of its own, which is retired after it
static int vis_in_ring(id<MTLBuffer> b) { return g_vis_ring_i >= 0 && g_vis_ring[g_vis_ring_i].buf == b; }
static int g_vis_on, g_vis_counting, g_vis_cur = -1; static uint64_t g_vis_cur_pass;
static vis_slot *g_vs; static int g_nvs, g_vscap;      // Slots since the last report or reset, in this submission (DM_NVN_QUERY_POOL=0)
enum { VIS_REPORT, VIS_FOLD, VIS_ZERO };               // post_op mode for kind 3: add the slots and write the total / only add them / zero the total
static uint64_t g_vis_acc;                              // The counter's running total (post_run, under g_post_mu)
static uint64_t g_cnt_report[32], g_cnt_reset[32];       // Report / reset counts per counter type (diagnostics)
// Pooled query records (DM_NVN_QUERY_POOL, on by default). Ocarina of Time reports about 1,500 samples-passed queries a frame: each report took a malloc for its slot list and a
// CFRetain per slot (one more per slot when the slot was made, and a CFRelease for each at the report and at completion), all on the replay thread. Now a submission's slots go into
// one arena in the order they are made, a report hands its submission's completion the range of slots since the previous report or reset (post_op v / vhi), and each visibility buffer
// the slots name is retained once per submission (its buffers, in the order first used: an overflow buffer replaces the one before it, so a new one is always the last). At commit the
// arena goes to the submission's post ring record and that record's previous arena, read and emptied by its completion (post_run, under g_post_mu), comes back for the next submission:
// a slot's buffer is held until the completion that reads it has run, as before, and a steady frame allocates nothing. Slots dropped by a reset stay in the arena unread, as the old list
// dropped them. =0: a slot list allocated for each report, every slot retained, as before
typedef struct vis_arena { vis_slot *s; uint32_t n, cap; void **buf; uint32_t nbuf, bufcap; } vis_arena;
static vis_arena g_va; static uint32_t g_va_mark;       // the submission being encoded; the first of its slots since the last report or reset
static int g_qpool = -1;   // 1 pooled, 0 as before (a unit test may set it directly between submissions, with no slot or report pending)
static int qpool_on(void) { if (g_qpool < 0) { const char *e = getenv("DM_NVN_QUERY_POOL"); g_qpool = !(e && !strcmp(e, "0")); if (!g_qpool) MLOG("DM_NVN_QUERY_POOL=0: occlusion query slots listed and retained per report, and conditions found by hash, as before"); } return g_qpool; }
static void vis_add(id<MTLBuffer> b, uint32_t slot) {
    void *bp = (__bridge void *)b;
    if (!qpool_on()) {
        if (g_nvs == g_vscap) { g_vscap = g_vscap ? g_vscap * 2 : 64; g_vs = realloc_or_die(g_vs, g_vscap * sizeof *g_vs, "the visibility slots"); }
        g_vs[g_nvs++] = (vis_slot){(void *)CFBridgingRetain(b), slot}; return;
    }
    if (!g_va.nbuf || g_va.buf[g_va.nbuf - 1] != bp) {
        if (g_va.nbuf == g_va.bufcap) { g_va.bufcap = g_va.bufcap ? g_va.bufcap * 2 : 4; g_va.buf = realloc_or_die(g_va.buf, g_va.bufcap * sizeof *g_va.buf, "the visibility buffers held"); }
        g_va.buf[g_va.nbuf++] = (void *)CFBridgingRetain(b);
    }
    if (g_va.n == g_va.cap) { g_va.cap = g_va.cap ? g_va.cap * 2 : 256; g_va.s = realloc_or_die(g_va.s, g_va.cap * sizeof *g_va.s, "the visibility slots"); }
    g_va.s[g_va.n++] = (vis_slot){bp, slot};
}
static int vis_pending(void) { return qpool_on() ? g_va.n > g_va_mark : g_nvs > 0; }   // slots since the last report or reset
static void vis_clear(void) {
    if (qpool_on()) g_va_mark = g_va.n;
    else { for (int i = 0; i < g_nvs; i++) CFRelease(g_vs[i].buf); g_nvs = 0; }
    g_vis_cur = -1;
}
static vis_list *vis_snapshot(void) {
    vis_list *l = malloc(sizeof *l + g_nvs * sizeof(vis_slot)); l->n = g_nvs;
    for (int i = 0; i < g_nvs; i++) { l->s[i] = g_vs[i]; CFRetain(g_vs[i].buf); }
    return l;
}
// A kind 3 post op (VIS_REPORT / VIS_FOLD) carrying the slots since the last report or reset, then cleared
static post_op vis_op(uint32_t mode, uint64_t addr, uint32_t type) {
    post_op o = {3, NULL, mode, 0, addr, type, NULL};
    if (qpool_on()) { o.v = g_va_mark; o.vhi = g_va.n; } else o.vis = vis_snapshot();
    vis_clear(); return o;
}
// post_run: the samples of an op's slots (under g_post_mu); va: its submission's arena
static uint64_t vis_sum(const post_op *o, const vis_arena *va) {
    uint64_t sum = 0;
    if (o->vis) { vis_list *l = o->vis; for (int k = 0; k < l->n; k++) { sum += ((const uint64_t *)((__bridge id<MTLBuffer>)l->s[k].buf).contents)[l->s[k].slot]; CFRelease(l->s[k].buf); } free(l); return sum; }
    // contents is the same pointer for every slot of a buffer: asked once per run of slots in one buffer
    const void *cb = NULL; const uint64_t *c = NULL;
    for (uint32_t k = o->v; k < o->vhi; k++) { const vis_slot *s = &va->s[k]; if (s->buf != cb) { cb = s->buf; c = ((__bridge id<MTLBuffer>)s->buf).contents; } sum += c[s->slot]; }
    return sum;
}
static void vis_arena_done(vis_arena *va) { for (uint32_t i = 0; i < va->nbuf; i++) CFRelease(va->buf[i]); va->nbuf = 0; va->n = 0; }   // after its submission's completion read it
// Target ranges of buffer writes (copies / inline uniform updates) already encoded in this submission but not yet executed on the GPU: reading these addresses on the CPU side at encode time yields old values (uv_proof avoids them when reading uniforms)
// Inline updates keep where their data sits in the update ring (g_pend_upd: index + 1 into g_upd), so a bindless handle they wrote can be read as the GPU will see it (pend_read).
// The writes are indexed by 4 KB page (a chain per hash bucket, newest first); a write over more than PEND_SPAN pages goes to a short list that every lookup scans.
// The list grows as a submission needs it and keeps its size for the next (pend_room). It used to stop at a fixed count, and past it the submission counted as a write anywhere
// (g_pend_over), which gw_commit carries past the submission: every partly covered uniform shadow of later submissions was refused while it ran, so every draw that read one ended its
// pass. Monster Hunter Rise passed 256 writes in a submission, and Splatoon Raiders' third boss stage about 11,000 (7 uniform updates before each of about 1,550 ink-map queries; 2,800
// in its other fights): past 8,192 each query took a pass of its own on its 6400x6400 map, the GPU fell behind, the submissions kept running, and the stage stayed at 1-2 fps.
// A write anywhere is left for a list that cannot grow (no memory) and a full wide list
enum { PEND_HB_BITS = 13, PEND_HB = 1 << PEND_HB_BITS, PEND_SPAN = 8, PEND_WIDE = 256 };
static uint64_t *g_pend_lo, *g_pend_hi; static int g_npend, g_pend_over, g_pend_cap; static uint8_t *g_pend_kind; static uint32_t *g_pend_upd;   // kind: 1 inline update, 2 copy, 3 fill
static int32_t g_pend_head[PEND_HB]; static uint32_t g_pend_hgen[PEND_HB], g_pend_gen = 1;   // a bucket's chain is valid when its generation is this submission's
typedef struct { int32_t e, next; } pend_node;
static pend_node *g_pend_node; static int g_npnode, g_pnode_cap;
static int32_t g_pend_wide[PEND_WIDE]; static int g_nwide;
typedef struct { uint64_t lo; size_t off; __unsafe_unretained id<MTLBuffer> buf; } upd_ent;   // the ring block lives until this submission completes (mtl_sub_update)
static upd_ent *g_upd; static int g_nupd;   // one per entry at most: sized with the entries
static int *g_ubp_idx;   // every entry a lookup can meet (pend_since): at most one per node of the range's chains, plus the wide list
static int pend_grow(void **p, size_t n, size_t each) { void *q = realloc(*p, n * each); if (!q) return 0; *p = q; return 1; }
// Room for one more entry and nodes more nodes: 0 when memory runs out (the caller counts the write as one anywhere)
static int pend_room(int nodes) {
    if (g_npend == g_pend_cap) { if (g_pend_cap > INT_MAX / 2) return 0; int c = g_pend_cap ? g_pend_cap * 2 : 4096;
        if (!pend_grow((void **)&g_pend_lo, c, sizeof *g_pend_lo) || !pend_grow((void **)&g_pend_hi, c, sizeof *g_pend_hi) || !pend_grow((void **)&g_pend_kind, c, sizeof *g_pend_kind)
            || !pend_grow((void **)&g_pend_upd, c, sizeof *g_pend_upd) || !pend_grow((void **)&g_upd, c, sizeof *g_upd)) return 0;   // a grown array kept at its new size is only spare room
        g_pend_cap = c; }
    if (!g_pnode_cap || g_npnode + nodes > g_pnode_cap) { int c = g_pnode_cap ? g_pnode_cap : 8192; while (c < g_npnode + nodes) { if (c > INT_MAX / 2) return 0; c *= 2; }
        if (!pend_grow((void **)&g_pend_node, c, sizeof *g_pend_node) || !pend_grow((void **)&g_ubp_idx, (size_t)c + PEND_WIDE, sizeof *g_ubp_idx)) return 0;
        g_pnode_cap = c; }
    return 1;
}
// Other writes to guest memory in this submission, which the pend list does not hold: writable storage buffers bound to a shader, texture→buffer copies, counter reports (ubp_get).
// Kept by 4 KB page (Breath of the Wild's particle dispatches bind about ten storage buffers each, hundreds a frame): a set of pages tagged with the submission (g_pend_gen) and with what
// wrote them. A counter report does not count against this submission's shadows: the host writes reports on the CPU when the whole submission has completed, so no draw of it reads one
// (Fire Emblem Engage writes its query reports into the page of a uniform block); for later submissions it counts by its own 16 bytes while this one runs (hw_note, hw_live).
// A GPU write over more than SBW_WPAGES pages is kept as an interval instead (overlapping ones merge): a storage buffer bound with size 0 counts as the rest of its Metal buffer (sbw_len)
enum { SBW_N = 16384, SBW_WPAGES = 64, SBW_WN = 64 };
static struct { uint64_t page; uint32_t gen; uint8_t src; } g_sbwp[SBW_N]; static int g_nsbw, g_sbw_over;   // src: SBW_* bits; pages in the set this submission; over: a write could not be kept (set full, size not known)
static uint16_t g_sbw_list[SBW_N];   // the slots this submission took, in order (g_nsbw of them): the commit reads these instead of all SBW_N slots (gw_commit), about 30 times a frame
static uint64_t g_sbw_wlo[SBW_WN], g_sbw_whi[SBW_WN]; static int g_nsbw_w;   // the wide writes of this submission
static int sbw_slot(uint64_t pg, int add) {   // open addressing; −1 = not there (or no room to add)
    unsigned h = (unsigned)((pg * 0x9E3779B97F4A7C15ull) >> 50) & (SBW_N - 1);
    for (int i = 0; i < 64; i++, h = (h + 1) & (SBW_N - 1)) {
