        once_end(o, en);
        if (once_wait(o) != 1) { MLOG("[RED] 16-bit float colour probe: the GPU did not finish it; 16-bit float targets take the shader guard"); return; }
        uint16_t h[4] = {0};
        [rt getBytes:h bytesPerRow:8 fromRegion:MTLRegionMake2D(0, 0, 1, 1) mipmapLevel:0];
        g_rop_f16_hw_rtz = h[0] == 0x3c00u && h[1] == 0x03ffu && h[2] == 0x0000u && h[3] == 0x7bffu;
        MLOG("16-bit float colour probe: this GPU converts toward zero %s (stored %#x %#x %#x %#x)", g_rop_f16_hw_rtz ? "as NVIDIA's does: no shader guard" : "unlike NVIDIA's: DMSH_ROUND_F16 in the shaders",
             h[0], h[1], h[2], h[3]);
    }
}
static int once_wait(NvOnce *o) {
    dispatch_semaphore_t sem = dispatch_semaphore_create(0); __block int ok = 0;
    uint64_t w0 = ws_t0();
    o->waiter = 1;
    once_commit(o, ^(int k) { ok = k; dispatch_semaphore_signal(sem); });
    if (dispatch_semaphore_wait(sem, DISPATCH_TIME_NOW)) {
        wn_in(WN_ONCE, 0);
        long late;
        for (;;) {   // in slices of 100 ms, so that a GPU taken as lost (gpu_gone, drain_over) ends it too: its completion will not come
            uint64_t dl = drain_left(), sl = dl < 100000000ull ? dl : 100000000ull;
            late = dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, (int64_t)sl));
            if (!late || drain_over()) break;
        }
        wn_out(WN_ONCE);
        if (late) {
            if (__atomic_exchange_n(&o->settle, 1, __ATOMIC_ACQ_REL)) res_commit_async(nil);   // the completion came between the timeout and here: its removal is queued, uncommitted
            if (ws_on()) ws_put(WS_ONCE, w0, 1); return t_drain_by ? -1 : 0;   // the GPU gone, outside the suspend's limit: as a GPU error
        }
    }
    if (__atomic_load_n(&o->settle, __ATOMIC_ACQUIRE)) { if (t_drain_by) res_commit_async(nil); else res_commit(); }   // set only when the completion queued a removal
    if (ws_on()) ws_put(WS_ONCE, w0, 1);
    return ok;
}
// Wait until everything committed to the Metal 4 queue so far has completed on the GPU: an empty one-off command buffer, whose leading queue barrier puts it after all earlier work, placed
// as once_commit places it (on the submit thread behind the upload batch it flushes and what the encode thread was given, from another thread behind every block published so far).
// It ends on its commit feedback, not on a queue signal: when the queue runs none of this process's work (revoked GPU access, gpu_lost_check; a submission iOS refuses in the
// background) no signal ever comes, but the feedback does, with the error, as it does for the frames (mtl_finish_gpu waits on g_done). A queue signalEvent here hung dm_gfx_suspend
// on the iOS main thread (sceneDidEnterBackground: the watchdog, and save_sync_background after it never starts). 0: the suspend's limit came first (once_wait's -1)
static int once_drain(void) {
    NvOnce *o = once_new(1);
    once_end(o, once_copy(o));
    return once_wait(o) >= 0;
}
// ---------- The GPU probe (DM_GPU_PROBE) ----------
// A fixed GPU job timed every 2 s, for a GPU-clock signal in the log: the power lines give GPU time per second, which rises with more work and with a lower clock alike, so a
// slowdown such as Breath of the Wild's at about 40 fps after a fight could not be told apart. A probe is one dispatch of one SIMD group (32 threads) in a one-off command buffer
// of its own on the Metal 4 queue, unordered with the work before it (once_new(0)): a dependent chain of 2,048 fused multiply-adds (gpu_probe.metal), whose time is the chain's
// latency, so it follows the clock of the GPU core it runs on, not the number of cores or the memory. Its time is the command buffer's GPU end minus start. The game's work on the
// same core lengthens it, and a probe can wait for a core: the fastest probe of a window is the signal, its mean and slowest say how much the game's work got in the way.
// On an Apple M4 Max (t_gpu_probe, a scratch run with a load): about 130 µs with the GPU idle at its lowest clock, 28-55 µs fastest with the GPU kept busy (its clock up), mean
// 295 µs there (waits for a core). The power tick (hle_nvn.c power_tick, once a second while DM_POWER_DETAIL is on, its default) starts one every other second
// (mtl_gpu_probe_tick); the power line (every 300 frames: about 5 s at 60 fps, 10 s at 30) logs the window's probes (mtl_gpu_probe_line) with their ratio to the session's fastest:
// 1.00 at the fastest clock seen, 2.4-4.6 at the M4 Max's idle clock against its busy one. Its pipeline is made on a utility queue at the first tick, off the present thread.
// Later work does wait for it: the next encoder the host opens starts with a queue barrier (barrierAfterQueueStages:MTLStageAll, enc_r_begin_pass and the others), which on the
// Metal 4 queue covers the probe's command buffer too, so that encoder can wait up to one probe's time (about 130 µs idle, a mean of about 295 µs under load) once every 2 s.
// Cost: one probe every 2 s, under 130 µs of one GPU core each, at most that long a wait for the next encoder, and a few µs of the present thread's CPU per probe. DM_GPU_PROBE=0
// turns it off; DM_POWER_DETAIL=0 too, with the ticks. Logging only: nothing the game sees changes
static _Atomic int g_probe_state;   // 0 not made, 1 being made, 2 ready, -1 refused (logged once), -2 off
static _Atomic int g_probe_busy;    // a probe committed and not yet done
static os_unfair_lock g_probe_lk = OS_UNFAIR_LOCK_INIT;
static struct { uint64_t n, err, min, max, sum, best, total, last; } g_probe;   // under g_probe_lk: this window's probes (n, min, max, sum of ns; err: no GPU time), the session's fastest and count, the latest
static id<MTLComputePipelineState> g_probe_ps; static id<MTL4ArgumentTable> g_probe_at; static id<MTLBuffer> g_probe_buf;
static int gpu_probe_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("DM_GPU_PROBE"); on = !(e && *e == '0'); } return on; }
static void gpu_probe_make(void) {   // on a utility queue
    @autoreleasepool {
        NSError *e = nil; id<MTLLibrary> lib = host_lib("gpu_probe", &e);
        id<MTLComputePipelineState> ps = lib ? host_cps(lib, @"dm_gpu_probe", nil, &e) : nil;
        MTL4ArgumentTableDescriptor *ad = [MTL4ArgumentTableDescriptor new]; ad.maxBufferBindCount = 1;
        id<MTL4ArgumentTable> at = ps ? [g_dev newArgumentTableWithDescriptor:ad error:&e] : nil;
        id<MTLBuffer> b = at ? [g_dev newBufferWithLength:32 * sizeof(float) options:MTLResourceStorageModePrivate] : nil;
        if (!b) { MLOG("GPU probe: cannot make its pipeline (%s); no GPU probe this run", e ? e.localizedDescription.UTF8String : "no buffer"); atomic_store(&g_probe_state, -1); return; }
        b.label = @"GPU probe"; res_add(b); [at setAddress:b.gpuAddress atIndex:0];
        g_probe_ps = ps; g_probe_at = at; g_probe_buf = b;
        atomic_store_explicit(&g_probe_state, 2, memory_order_release);
