}
// Once a second from the power tick (on the presenting thread): the first call has the pipeline made, then every other call starts a probe unless one is still running
void mtl_gpu_probe_tick(void) {
    static unsigned tick;
    int st = atomic_load_explicit(&g_probe_state, memory_order_acquire);
    if (st == 0) { if (!gpu_probe_on()) { atomic_store(&g_probe_state, -2); return; }
        atomic_store(&g_probe_state, 1); dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{ gpu_probe_make(); }); return; }
    if (st != 2 || (tick++ & 1) || atomic_exchange(&g_probe_busy, 1)) return;
    NvOnce *o = once_new(0);
    id<MTL4ComputeCommandEncoder> ce = [o->cb computeCommandEncoder];
    [ce setComputePipelineState:g_probe_ps]; [ce setArgumentTable:g_probe_at];
    [ce dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
    [ce endEncoding];
    once_commit(o, ^(int ok) {   // on the feedback queue
        double sec = o->gpu1 - o->gpu0; uint64_t v = ok && o->gpu0 > 0 && sec > 0 && sec < 1 ? (uint64_t)(sec * 1e9) : 0;
        os_unfair_lock_lock(&g_probe_lk);
        if (v) { if (!g_probe.n || v < g_probe.min) g_probe.min = v; if (v > g_probe.max) g_probe.max = v; g_probe.sum += v; g_probe.n++; g_probe.total++; g_probe.last = v; if (!g_probe.best || v < g_probe.best) g_probe.best = v; }
        else g_probe.err++;
        os_unfair_lock_unlock(&g_probe_lk);
        atomic_store(&g_probe_busy, 0);
    });
}
// The power window's probes into out (0: none to say), and the next window started. On the thread that writes the power line
int mtl_gpu_probe_line(char *out, size_t n) {
    if (atomic_load_explicit(&g_probe_state, memory_order_acquire) != 2) return 0;
    os_unfair_lock_lock(&g_probe_lk);
    __typeof__(g_probe) w = g_probe; g_probe.n = g_probe.err = g_probe.min = g_probe.max = g_probe.sum = 0;
    os_unfair_lock_unlock(&g_probe_lk);
    if (w.n) snprintf(out, n, "fixed job fastest %.1f us of %llu (mean %.1f, slowest %.1f), %.2fx the session's fastest %.1f us (%llu probes)%s", w.min / 1e3, (unsigned long long)w.n,
                      w.sum / 1e3 / (double)w.n, w.max / 1e3, w.best ? (double)w.min / (double)w.best : 0, w.best / 1e3, (unsigned long long)w.total, w.err ? "; some without a GPU time" : "");
    else if (w.err) snprintf(out, n, "%llu probes without a GPU time", (unsigned long long)w.err);
    else if (atomic_load(&g_probe_busy)) snprintf(out, n, "the probe started in this window has not finished");
    else return 0;
    return 1;
}
// The latest probe against the session's fastest into *ratio, and the session's probe count (0: none yet). The frame-rate controller's probe lines (hle_fctl.c), on the game's thread
uint64_t mtl_gpu_probe_last(double *ratio) {
    if (atomic_load_explicit(&g_probe_state, memory_order_acquire) != 2) return 0;
    os_unfair_lock_lock(&g_probe_lk);
    const uint64_t last = g_probe.last, best = g_probe.best, n = g_probe.total;
    os_unfair_lock_unlock(&g_probe_lk);
    if (!n || !best) return 0;
    *ratio = (double)last / (double)best;
    return n;
}
