static int trim_frames_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("DM_NVN_TRIM_FRAMES"); on = !e || atoi(e); } return on; }
static uint64_t subs_for_frames(uint64_t frames) {
    if (!trim_frames_on()) return frames;
    const uint64_t f = atomic_load_explicit(&g_cur_frame, memory_order_relaxed), sub = g_sub_serial;
    const uint64_t per = f > 60 && sub > f ? (sub + f / 2) / f : 1;
