static _Atomic uint64_t g_trickle_n, g_trickle_bytes;   // res_trickle's pools and bytes (the [trickle] line)
static void res_trickle(void) {
    static int mb = -1; static uint64_t frame = UINT64_MAX, used, gen_done;
