static void lz_tick(uint64_t f);
static void ls_frame(uint64_t f);
void mtl_set_frame(uint64_t f) { atomic_store(&g_cur_frame, f); ls_frame(f); dm_tcore_sample(DM_TCORE_REPLAY, f); if (g_ub_n) ub_frame(f); if (ab_len()) ab_frame(f); gpu_capture_frame(f); dz_tick(f); lz_tick(f); }
// GPU timing registration: gpu_tag_begin(frame) before commit, gpu_tag_done(frame, GPU start, GPU end) on completion (seconds on the CACurrentMediaTime base).
// The Metal 4 main submission backfills in the feedback of mtl_sub_commit (when switching to Metal 4 all the call sites were lost and the GPU column of the timing line became empty)
static void gpu_tag_begin(uint64_t f) {
    unsigned k = f % GRING;
    if (atomic_load(&g_gpu[k].frame) != f) { atomic_store(&g_gpu[k].frame, f); atomic_store(&g_gpu[k].ns, 0); atomic_store(&g_gpu[k].pending, 0); atomic_store(&g_gpu[k].t0, UINT64_MAX); atomic_store(&g_gpu[k].t1, 0); }
    atomic_fetch_add(&g_gpu[k].pending, 1);
}
static void gpu_tag_done(uint64_t f, double g0, double g1) {
    unsigned k = f % GRING;
    if (atomic_load(&g_gpu[k].frame) != f) return;
    if (gpu_time_valid(g0, g1)) {   // no start time (0, Big Brain Academy's movie uploads), a faulted buffer's unwritten tick, or a time ahead of now adds nothing (upstream 99ae7c6fc)
        double d = g1 - g0;
        atomic_fetch_add(&g_gpu[k].ns, (uint64_t)(d * 1e9));
        uint64_t s0 = (uint64_t)(g0 * 1e9), s1 = (uint64_t)(g1 * 1e9), v;
        for (v = atomic_load(&g_gpu[k].t0); s0 < v && !atomic_compare_exchange_weak(&g_gpu[k].t0, &v, s0);) {}
        for (v = atomic_load(&g_gpu[k].t1); s1 > v && !atomic_compare_exchange_weak(&g_gpu[k].t1, &v, s1);) {}
    }
    atomic_fetch_sub(&g_gpu[k].pending, 1);
}
double mtl_gpu_ms(uint64_t f) {
    unsigned k = f % GRING;
    if (atomic_load(&g_gpu[k].frame) != f || atomic_load(&g_gpu[k].pending)) return -1;
    return atomic_load(&g_gpu[k].ns) / 1e6;
}
int mtl_gpu_span(uint64_t f, uint64_t *t0, uint64_t *t1) {
    unsigned k = f % GRING;
    if (atomic_load(&g_gpu[k].frame) != f || atomic_load(&g_gpu[k].pending)) return 0;
    *t0 = atomic_load(&g_gpu[k].t0); *t1 = atomic_load(&g_gpu[k].t1);
    return *t0 && *t0 != UINT64_MAX && *t1 >= *t0 && *t1 - *t0 <= 1000000000ull;   // none started, or a span over 1 s (a start or end that was never set): no span (nvn_power.h nvn_pd_span_add)
}
// The process's performance profile (NSProcessInfo hasPerformanceProfile:, Metal's MTLDeviceCertification.h) for the power detail (hle_nvn.c power_tick's first call, DM_POWER_DETAIL):
// one line, and one more on each NSProcessInfoPerformanceProfileDidChangeNotification, with whether the device is certified for the iPhone performance gaming tier. Logging only
static void perf_profile_line(const char *what) {
    NSProcessInfo *pi = NSProcessInfo.processInfo;
    LOG("[nvn] performance profile%s: default %s, sustained %s; device certified for iPhone performance gaming: %s", what, [pi hasPerformanceProfile:NSProcessPerformanceProfileDefault] ? "yes" : "no",
        [pi hasPerformanceProfile:NSProcessPerformanceProfileSustained] ? "yes" : "no", [pi isDeviceCertifiedFor:NSDeviceCertificationiPhonePerformanceGaming] ? "yes" : "no");
}
void mtl_perf_profile_watch(void) {
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        perf_profile_line("");
        [NSNotificationCenter.defaultCenter addObserverForName:NSProcessInfoPerformanceProfileDidChangeNotification object:nil queue:nil usingBlock:^(NSNotification *n) { (void)n; perf_profile_line(" changed"); }];
    });
}
