static void cbs_feedback(cbs_list *l, NSError *err, const char *where);
static void cbs_fly_report(uint64_t fence); static void cbs_fly_put(uint64_t fence, const cbs_list *l); static void ind_fly_put(const char *key, uint64_t ind, uint64_t off, void *buf);
static void lc_land(void); static void lc_take_rt(void); static int g_nlc;   // lazy clears (lc_push): land / take the waiting ones, and how many wait
// A submission's CPU-side writes at its end (events, samples-passed and counter reports): run once, by its feedback handler or, when a game's SyncWait wakes on the
// GPU's own signal of the fence first, by that waiter (DM_NVN_FAST_WAKE, on by default): the feedback handler comes 0.26 ms after the GPU end on an M2 Max
typedef struct { _Atomic uint64_t fence; _Atomic int claimed; int n; post_op *ops; seg_clk *sc; uint32_t seg_last; uint64_t t_commit, t_ready; vis_arena va; } post_rec;   // t_commit: guest ns when it was committed; t_ready: when it was ready to run (mtl_sub_ready, 0 = not known); va: its query slots (DM_NVN_QUERY_POOL)
enum { POST_RING = SUB_FLIGHT_MAX };
static post_rec g_postr[POST_RING];
static pthread_mutex_t g_post_mu = PTHREAD_MUTEX_INITIALIZER;
// A successful claim holds the lock until post_run finishes. Ownership alone
// cannot publish completion: another waiter must see the actual writes first.
static int post_claim(post_rec *r, uint64_t fence) {
    pthread_mutex_lock(&g_post_mu);
    if (r->fence != fence || r->claimed) { pthread_mutex_unlock(&g_post_mu); return 0; }
    return 1;
}
// A submission's place on the GPU timeline (see place_back), in fence order: post_complete runs the records up to a fence in order, each post_run under g_post_mu. Returns how far its
// first command buffer moves back. With no ready time (replay tools, tests), its first command buffer's feedback not arrived yet, or no GPU times, it stays where it is. Every submission,
// moved or not, sets the timeline's end to its own end as its reports read it, so no later report reads earlier than one of it. A submission completed by a SyncWait that woke on the
// GPU's signal before its feedback (post_early) is placed by the times post_complete estimates for it
static uint64_t g_line_fence, g_line_end;   // the last submission placed, and the timeline's end (guest ns)
static uint64_t sub_place(const post_rec *r, uint64_t c0, uint64_t c1) {
    uint64_t fence = atomic_load(&r->fence);
    if (ts_mode() != 1 || fence <= g_line_fence) return 0;
    uint64_t s = c0, gaps = 0, off = 0;   // its first command buffer's real GPU start, and the gaps between its command buffers
    if (r->sc && r->sc->ncm) { s = atomic_load(&r->sc->t[r->sc->cm[0]][0]); gaps = seg_idle_before(r->sc, c1, c0); }
    uint64_t end = c1 ? c1 : guest_ns();   // its end as its last report reads it unmoved (rep_ticks: with no GPU end, the time of the write)
    if (gaps < end) end -= gaps;
    if (r->t_ready && s && c1 >= s) { uint64_t at = g_line_end > r->t_ready ? g_line_end : r->t_ready; if (at < s) { off = s - at; end -= off; } }
    if (end > g_line_end) g_line_end = end;
    g_line_fence = fence;
    return off;
}
// The GPU time stretch (the heat ladder's resolution rungs and the GPU clock rescue in the Mario Kart World engine family, hle_nvn.c scale_set; nvn_heat.h nvn_heat_stretch_ts):
// the game's own dynamic resolution steers by the time between its counter reports, so every report of a submission is moved back from the submission's end (its last
// segment's GPU end, placed back as its own report would read it) by k times its distance, and never before the latest time written for the submissions before it (read
// once per submission, so its own reports keep the order of their times: a submission's ops are not in time order, a TIMESTAMP_TOP reads its segment's start after a
// BOTTOM read its end) unless the report's own time is earlier. The end stays, so a frame-rate controller that compares a report with its CPU clock (Donkey Kong Bananza's)
// reads the same; nothing reads later than it was, also after a record run early with c1 = now (post_early, or a later fence's handler), whose reports may read later than
// the next submission's times. 0: not a game of that family (no cost); 1: none now, the floor following the reports. Below 1 (the GPU time scale, profile gpu_time_scale:
// Donkey Kong Bananza's 0.6144, times any rung's or the rescue's stretch) the same map shortens the spans toward the end, each report between its own time and the end.
// Under g_post_mu (post_run), in fence order
static _Atomic uint64_t g_stretch_bits;   // the stretch k, a double's bits (0: off)
static uint64_t g_stretch_floor;   // under g_post_mu: the latest report time written, in NVN's raw unit (nvn_timestamp.h; never lowered)
void mtl_gpu_stretch_set(double k) { uint64_t b; memcpy(&b, &k, sizeof b); atomic_store_explicit(&g_stretch_bits, k > 0 ? b : 0, memory_order_relaxed); }
static _Atomic uint64_t g_scale_noted;   // the host's composed render scale once it changed (hle_nvn.c scale_set), a double's bits (0: not changed yet), for the crop line
void mtl_render_scale_note(double v) { uint64_t b; memcpy(&b, &v, sizeof b); atomic_store_explicit(&g_scale_noted, v > 0 ? b : 0, memory_order_relaxed); }
static double gpu_stretch_k(void) { uint64_t b = atomic_load_explicit(&g_stretch_bits, memory_order_relaxed); double k; memcpy(&k, &b, sizeof k); return b ? k : 0; }
double mtl_gpu_stretch_now(void) { return gpu_stretch_k(); }   // the stretch post_run applies now (t_thermal: what scale_set handed over)
static void post_run(post_rec *r, uint64_t c0, uint64_t c1) {
    // A guest SyncWait may run completion on a thread whose outer pool never drains.
    // MTLBuffer.contents may autorelease its receiver; keep that lifetime inside the completed copy.
    @autoreleasepool {
    int n = r->n; post_op *ops = r->ops; seg_clk *sc = r->sc; uint32_t seg_last = r->seg_last;
    uint64_t off = sub_place(r, c0, c1);
    const double sk = gpu_stretch_k(); uint64_t se = 0;   // the stretch, and its anchor: the submission's end as its last report reads it (0: not known, nothing moves)
    const uint64_t s_lo = g_stretch_floor; uint64_t s_hi = 0;   // the floor for every report of this submission, and the latest time it writes (the next one's floor)
    if (sk > 0 && c1) { uint64_t b = place_back(sc, c1, c0, off); se = nvn_timestamp_from_ns(c1 - b); }
    for (int i = 0; i < n; i++) {
        if (ops[i].kind == 1) continue;   // A terminal release publishes after every earlier GPU write has landed.
        else if (ops[i].kind == 3) {   // Samples passed: the running total, in submission order
            if (ops[i].mode == VIS_ZERO) { g_vis_acc = 0; continue; }
            g_vis_acc += vis_sum(&ops[i], &r->va);
            if (ops[i].mode == VIS_REPORT) { uint64_t rec[2] = {g_vis_acc, gpu_ticks()}; memcpy((void *)ops[i].addr, rec, sizeof rec); }
        }
        else {
            uint64_t t = rep_ticks(&ops[i], sc, seg_last, c0, c1, off);
            if (sk > 0) { t = nvn_heat_stretch_ts(t, se, sk, s_lo); if (t > s_hi) s_hi = t; }
            uint64_t rec[2] = {(ops[i].type == 0 || ops[i].type == 0x10) && !DM_GAME_RENDER_COND ? t : 0, t}; memcpy((void *)ops[i].addr, rec, sizeof rec);   // render_cond: a timestamp report's counter field is 0, as on the GPU (see rc_value)
        }
    }
    if (s_hi > g_stretch_floor) g_stretch_floor = s_hi;
    // Forwarded counter values expire once their CPU-visible reports have landed.
    // This precedes event publication so a released CPU writer is never hidden by stale knowledge.
    uint64_t completed=atomic_load_explicit(&g_rc_complete,memory_order_relaxed);
    while(completed<r->fence && !atomic_compare_exchange_weak_explicit(&g_rc_complete,&completed,r->fence,memory_order_release,memory_order_relaxed)) {}
    // Pass teardown can append mirror readbacks after the recorded signal. They are
    // preceding GPU writes, and must be CPU-visible before this prefix releases its event.
    for (int i=0;i<n;i++) if(ops[i].kind==1) nvn_event_publish_gpu(ops[i].val,ops[i].mode,ops[i].v,r->fence);
    free(ops); seg_clk_put(sc); r->ops = NULL; r->sc = NULL; vis_arena_done(&r->va);
    atomic_store(&r->claimed, 1);
    pthread_mutex_unlock(&g_post_mu);
    }
}
// Both GPU feedback and an early waiter complete records in submission order.
// Delayed callbacks carry their fence, never the identity of a recyclable slot.
static void post_complete(uint64_t fence, uint64_t c0, uint64_t c1) {
    uint64_t now = guest_ns();
    for (uint64_t f = g_done + 1; f <= fence; f++) {
        post_rec *r = &g_postr[f % POST_RING];
        if (!post_claim(r, f)) continue;
        uint64_t start = r->t_commit;
        if (r->sc && r->sc->ncm) {   // nor before the command buffer committed before it ended
            uint64_t pe = atomic_load(&r->sc->t[r->sc->cm[r->sc->ncm - 1]][1]); if (pe > start) start = pe;
        }
        if (start > now) start = now;
        post_run(r, f == fence && c1 ? c0 : seg_ts() ? start : 0, f == fence && c1 ? c1 : seg_ts() ? now : 0);
    }
    mu_lock(); if (fence > g_done) g_done = fence;
    uint64_t done = g_done;
    uint32_t *scr = atomic_load(&g_mesh_scr); if (scr) __atomic_store_n(scr + DMSH_MESH_SCRATCH_DONE, (uint32_t)done, __ATOMIC_RELAXED);   // the slices of groups this fence cut off are free again
    pthread_cond_broadcast(&g_cv); pthread_mutex_unlock(&g_mu);
    fence_ev_raise(done);   // a failed command buffer's feedback can come without the GPU's signal
    nvn_queue_gpu_progress();
}
static uint64_t g_sub_ready;   // mtl_sub_ready, for the submission being encoded
void mtl_sub_ready(uint64_t t) { g_sub_ready = t; }
void mtl_sub_cpu_limit(uint64_t lim) { reup_limit_set(lim); }
static _Atomic int g_seg_inflight;   // main command buffers committed and not reported back yet (sub_cut)
static void rt_preserve_bound(void);
static void queue_program_preserve(void);
static void up_seq_drained(void);
static void ghost_commit(void);
static void shared_idle_commit(void);
static void tex_idle_commit(void);
// Every commit of the submission's command buffer (mtl_sub_commit, sub_cut, mdi_wait) ends it through cb_commit, so that none misses a step:
// upstream's mdi_wait committed without patching the raw pool table words until its PR #2330. Sealed first: the blit encoder, the upload batch (its own command buffer, committed before
// this one) and the raw pool table words of the argument blocks encoded so far (gmem_commit_patch); then the residency set (after the patch, which may res_add a new table). A commit whose
// bookkeeping must see all of that (the submission's fence and the writes it counts, a segment's state list) seals before it: cb_commit seals again and finds nothing left to do.
// (Upstream's seal also ends its transform feedback capture pass; NX 18 has none.)
static void cb_seal(void) {
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    up_flush();
    gmem_commit_patch();
}
static void cb_commit(DmCommitFB *o, int end) {   // end: the submission ends with this command buffer (rec_commit: the encode thread may hold it)
    cb_seal();
    res_commit_soon(1, 0);   // with the encode thread, it commits what is left before this command buffer's queue commit (rca_queue_guard)
    [g_cb endCommandBuffer];
    rec_commit(g_cb, o, end); g_cbgen++;
}
uint64_t mtl_sub_commit(void) {
    lc_land();   // clears still waiting (the command list ends with them)
    rp_flush(); ubd_land();
    g_ts_pend = -1;   // nothing after it: the last segment's end is the command buffer's own (rep_ticks)
    cb_seal();   // before the fence and the writes it counts
    g_cut_copy = 0;
    ghost_commit();   // idle finalized-texture entries above 512, or all of them at low headroom, go behind this submission's fence
    shared_idle_commit();   // shared textures kept by the sharing table alone and long unused go behind this fence too (DM_NVN_SHARED_IDLE)
    tex_idle_commit();   // at low headroom, live textures idle for 3 s whose storage holds their content go behind this fence too (DM_NVN_IDLE_TEX_MB)
    treg_finish_submission();   // Late descriptor views retire behind this submission's fence.
    void dlss_retire_drain(void); dlss_retire_drain();   // finalized DLSS networks' scalers retire behind this submission's fence
    rt_preserve_bound();   // The game may reuse completed command memory; queue bindings must not point into its texture snapshots.
    queue_program_preserve(); // Submitted metadata may retire while these programs remain bound.
    // The post ring holds the completion writes of POST_RING submissions. With a frame's submissions sharing one allocator (and a visibility buffer taken only by a pass that counts
    // samples) nothing else bounds how many are in flight: signal_events split makes one per GPU event signal, and t_wait_event's 400 signals overran the ring ("never ran").
    // So a submission whose slot still holds a fence the GPU has not completed waits for it here (on the wait ledger as the post ring: as the allocator's it disagreed with g_alloc_waits)
    if (g_fence + 1 > POST_RING && g_done < g_fence + 1 - POST_RING) mtl_wait_at(g_fence + 1 - POST_RING, UINT64_MAX, WS_POST);
    uint64_t fence = ++g_fence;
    if (vis_pending()) post(vis_op(VIS_FOLD, 0, 0));   // this submission's slots after its last report: read at its completion (Occlusion queries)
    gw_commit(fence); rc_commit(fence);
    if (g_vis_ring_i >= 0) g_vis_ring[g_vis_ring_i].fence = fence;
    // CPU-visible effects after completion: copy the op table into the callback
    int n = g_npost; post_op *ops = n ? malloc(n * sizeof *ops) : NULL; post_rec *pr = &g_postr[fence % POST_RING];
    if (ws_on()) for (int i = 0; i < n; i++) { int k = g_post[i].kind == 2 ? (g_post[i].type == 0 || g_post[i].type == 0x10 ? 3 : 4) : g_post[i].kind == 3 ? (g_post[i].mode == VIS_REPORT ? 2 : 0) : 1; atomic_fetch_add(&g_ws_post[k], 1); }   // 1 event, 2 samples passed, 3 timestamp, 4 other counter
    if (n) memcpy(ops, g_post, n * sizeof *ops);
    NSArray<dispatch_block_t> *commit_blocks = [g_commit_blocks copy];
    DmCommitFB *o = [DmCommitFB new];
    atomic_fetch_add(&g_seg_inflight, 1);
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> f) { (void)f; fb_in("submission (its commit blocks)"); atomic_fetch_sub(&g_seg_inflight, 1); for (dispatch_block_t block in commit_blocks) block(); fb_out(); }];
    uint64_t gpu_f = atomic_load(&g_cur_frame); gpu_tag_begin(gpu_f);
    NSString *cctx = @(cctx_snap());
    cbs_list *cbs = cbs_take(); cbs_fly_put(fence, cbs);
    seg_clk *sc = g_sclk; uint32_t seg_last = g_seg; g_sclk = NULL;
    pthread_mutex_lock(&g_post_mu);
    if (!atomic_load(&pr->claimed) && pr->fence && !gpu_gone()) MDIE("post ring: the writes of fence %llu never ran", (unsigned long long)pr->fence);   // gone: they never will
    pr->n = n; pr->ops = ops; pr->sc = sc; pr->seg_last = seg_last; pr->t_commit = guest_ns(); pr->t_ready = g_sub_ready; g_sub_ready = 0; atomic_store(&pr->claimed, 0); atomic_store(&pr->fence, fence);
    { vis_arena t = pr->va; pr->va = g_va; g_va = t; g_va_mark = 0; }   // the slots go with their completion; its record's last arena, read and emptied (post_run), comes back
    pthread_mutex_unlock(&g_post_mu);
    int lost_test = gpu_lost_test();
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> cb) {
        fb_in("submission");
        gpu_tag_done(gpu_f, cb.GPUStartTime, cb.GPUEndTime); gpu_busy_note(cb.GPUStartTime, cb.GPUEndTime);
        if (ws_on()) ws_fb(fence, cb.GPUEndTime);
        uint64_t c0 = 0, c1 = 0; if (seg_ts()) { c0 = gpu_s_guest_ns(cb.GPUStartTime); c1 = gpu_s_guest_ns(cb.GPUEndTime); }
        if (cb.error) { atomic_store(&g_last_commit_error, 1); res_top_once(cb.error); victim_note(cb.error, "submission", fence); static int n, nv; int victim = [cb.error.description containsString:@"InnocentVictim"]; if (victim ? nv++ < 1 : n++ < 8) MLOG("[RED] command buffer error details fence=%llu: %s | GPU %.3f→%.3f", (unsigned long long)fence, cb.error.description.UTF8String, cb.GPUStartTime, cb.GPUEndTime); if (!victim) MLOG("[RED] state of the failed submission fence=%llu: %s", (unsigned long long)fence, cctx.UTF8String); MLOG("[RED] command buffer execution error: %s", cb.error.localizedDescription.UTF8String); }
        char where[64]; snprintf(where, sizeof where, "fence %llu, its last command buffer", (unsigned long long)fence); cbs_feedback(cbs, cb.error, where);
        gpu_lost_check(lost_test ? gpu_lost_test_error() : cb.error, "submission");
        post_complete(fence, c0, c1);
        defer_drain(); defer_idle_commit();
        fb_out();
    }];
    void arena_commit(uint64_t fence); arena_commit(fence);
    if (g_gp_state == 1 && !gp_active()) { int gn = g_gp_n; gp_lab *gl = malloc(sizeof(gp_lab) * (gn ? gn : 1)); memcpy(gl, g_gp_lab, sizeof(gp_lab) * gn); uint64_t gf = g_gp_frame; g_gp_state = 2; atomic_store(&g_gp_busy, 1);
        [o addFeedbackHandler:^(id<MTL4CommitFeedback> f) { (void)f; fb_in("GPU profile report"); gp_report(gn, gl, gf); fb_out(); }]; }
    cb_commit(o, 1);   // the stores it holds come before any later upload batch (gsb_held)
    if (!lost_test) rec_signal(g_ev, fence);
    // With the encode thread the records go to it and the replay goes on with the next submission: what comes after it on the queue is a record too (the next submission's commits,
    // upload batches, snapshot copies), a CPU wait for the GPU waits for the fence's signal behind this commit, and a present of the game's own texture waits for this note
    // (sub_commit_wait). The replay used to wait for the encode thread here: Ocarina of Time makes about 30 submissions a frame (one at each event signal), and on the iPhone the GPU
    // sat idle before most of them while the replay waited and then translated the next one (13.6 of 14.8 ms of gaps in a 35 ms frame; docs/reference/rendering.md)
    // DM_NVN_SUB_DRAIN=1 waits for the encode thread here as before (ab: alternates with the DM_AB phases, for measurement)
    static int drain = -1; if (drain < 0) drain = sw_mode("DM_NVN_SUB_DRAIN", 0);
    if (rec_on() && g_rb_started) { rec_t *r = rec_put(RO_NOTE, 0); r->a[0] = (uint64_t)(uintptr_t)&g_sub_cmt; r->a[1] = fence; if (drain && sw_on(drain)) rec_drain(); else rec_publish(); }
    else atomic_store(&g_sub_cmt, fence);
    up_seq_drained();   // every upload batch begun so far is recorded ahead of this submission's note, which a present without a snapshot waits for (present_enqueue's note)
    g_alloc_fence[g_alloc_cur] = fence;
    g_cb = nil;
    atomic_store(&g_sub_open, 0);   // after ++g_fence and the last encoding: a buffer retired from now on waits for this fence at most
    defer_idle_commit();   // a feedback handler that drained since this submission's own commit saw it open
    g_commit_blocks = nil;
    objc_autoreleasePoolPop(g_sub_pool); g_sub_pool = NULL;
    return fence;
}

// A present of the game's own texture waits for the submissions before it (g_sub_cmt), as the display command buffer goes to the queue directly and must come after the work that drew the picture
static void sub_commit_wait(uint64_t fence) { if (fence && rec_on()) rec_note_wait(&g_sub_cmt, fence); }
uint64_t mtl_completed_fence(void) { return atomic_load_explicit(&g_done,memory_order_acquire); }
uint64_t mtl_last_fence(void) { return g_fence; }
int mtl_last_commit_error(void) { return atomic_load(&g_last_commit_error); }

static int fast_wake(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_FAST_WAKE"); v = !(e && !strcmp(e, "0")); MLOG("game SyncWaits wake on the GPU's signal of the fence%s (DM_NVN_FAST_WAKE)", v ? "" : ": off, on the feedback handler"); } return v; }
// A SyncWait woken by the GPU's signal: the CPU-side writes of every submission up to the fence that no feedback handler has run yet, run here. The fence's last segment ended
// now (c1); it started at the later of its commit and the previous segment's end (c0), as near as the CPU can tell without its feedback
static void post_early(uint64_t fence) {
    if (atomic_load_explicit(&g_done, memory_order_acquire) >= fence) return;   // its feedback already ran (and raised g_ev, fence_ev_raise)
    post_complete(fence, 0, 0);
}
// A fence wait at the 10 s mark (mtl_wait_at, both of its paths, once per wait): what it waits for, then what the command buffer after the last completed fence runs (cbs_fly_report).
// Called without g_mu: the shader list's lock is never taken under it. PRAGMATA's queue worker stopped at its first 3D scene with no GPU error, and the line named the shaders
static void wait_fence_say(uint64_t fence, int site) {
    static _Atomic int n; if (atomic_fetch_add(&n, 1) >= WAIT_SAY_MAX) return;
    uint64_t done = atomic_load(&g_done);
    MLOG("[RED] the host has waited %g s for GPU work up to fence %llu (wait site %d, %s): completed %llu, submitted %llu; the GPU runs nothing it can finish",
         g_wait_say_ns / 1e9, (unsigned long long)fence, site, site >= 0 && site < WS_N ? ws_name[site] : "?", (unsigned long long)done, (unsigned long long)atomic_load(&g_fence));
    cbs_fly_report(done + 1);
}
static int mtl_wait_at(uint64_t fence, uint64_t timeout_ns, int site) {
    if (g_done >= fence) { if (ws_on()) ws_put(site, 0, 0); return 1; }
    if (gpu_gone()) { if (ws_on()) ws_put(site, 0, 0); return 1; }   // a GPU taken as lost completes nothing more: the wait gives way (gpu_watch), so the game and the exit can go on
    uint64_t w0 = ws_t0();
    int told = 0;   // this wait has said it reached the 10 s mark (once per wait, whichever path it was on)
    if ((site == WS_SYNC || site == WS_SYNC_NEWEST || site == WS_ACQ) && fast_wake() && g_ev && fence <= g_fence) {   // the game's own wait: wake on the GPU's signal (rec_signal(g_ev, fence) after each submission)
        uint64_t ms = timeout_ns / 1000000ull; if (ms > 3600000ull) ms = 3600000ull;
        // In slices of the mark (10 s) up to the same total: a wait still going after the first slice says so, with what the stuck command buffer runs, as the feedback wait below does
        uint64_t slice = g_wait_say_ns / 1000000ull; if (!slice) slice = 1;
        int sig;
        wn_in(WN_EVENT, fence);
        if (ms && g_ev.signaledValue < fence) {   // it blocks: inside the game's nvnQueueFinish or nvnSyncWait the waiting guest thread gives its core away (hle_nvn.c). Entering
            nvn_acquire_block();                  // can wait for the thread lock, so the time left is read after it (as sleep_until_ns does): a timeout must not end late by that wait
            if (timeout_ns != UINT64_MAX) { uint64_t used = (ws_t0() - w0) / 1000000ull; ms = used >= ms ? 0 : ms - used; }
        }
        for (uint64_t left = ms;;) {
            uint64_t s = left < slice ? left : slice;
            sig = [g_ev waitUntilSignaledValue:fence timeoutMS:s]; left -= s;
            if (sig || !left || gpu_gone()) break;
            if (!told) { told = 1; wait_fence_say(fence, site); }
        }
        wn_out(WN_EVENT);
        if (sig && !gpu_gone()) post_early(fence);   // gone: the event was raised from the CPU (gpu_gone_release), the GPU ran nothing up to the fence
        int ok = g_done >= fence || gpu_gone();
        if (ok || timeout_ns < 1000000ull) {   // the ledger counts the wait once: here, or in the feedback wait it falls through to (NXNative 4fdfd4793)
            if (ws_on()) { ws_put(site, w0, 1); ws_wake(fence); }
            return ok;
        }
        // The event and feedback waits share a finite budget; a timeout must not buy another full wait.
        if (timeout_ns != UINT64_MAX) {
            uint64_t used = ws_t0() - w0;
            if (used >= timeout_ns) {
                if (ws_on()) { ws_put(site, w0, 1); ws_wake(fence); }
                return 0;
            }
            timeout_ns -= used;
        }
    }
    if (timeout_ns && g_done < fence) {   // it blocks: as above (not under g_mu, as it takes the thread lock), and the deadline is what is left after it
        uint64_t m0 = ws_t0(); nvn_acquire_block();
        if (timeout_ns != UINT64_MAX) { uint64_t m = ws_t0() - m0; timeout_ns = m >= timeout_ns ? 0 : timeout_ns - m; }
    }
    struct timespec dl; clock_gettime(CLOCK_REALTIME, &dl);
    uint64_t ns = (uint64_t)dl.tv_nsec + (timeout_ns > 3600000000000ull ? 3600000000000ull : timeout_ns);
    dl.tv_sec += ns / 1000000000ull; dl.tv_nsec = ns % 1000000000ull;
    mu_lock();
    int r = 0;
    // A wait still waiting at the 10 s mark is a hang: said once, with what it waits for (PRAGMATA's queue worker stopped here at its first 3D scene, no GPU error). A wait whose limit
    // comes first has nothing to say
    struct timespec said; clock_gettime(CLOCK_REALTIME, &said);
    { uint64_t sn = (uint64_t)said.tv_nsec + g_wait_say_ns; said.tv_sec += sn / 1000000000ull; said.tv_nsec = sn % 1000000000ull; }
    told |= timeout_ns <= g_wait_say_ns;
    int noted = g_done < fence; if (noted) wn_in(WN_DONE, fence);
    while (g_done < fence && !gpu_gone()) {   // gpu_gone_release broadcasts under g_mu
        int late = !told && (dl.tv_sec > said.tv_sec || (dl.tv_sec == said.tv_sec && dl.tv_nsec > said.tv_nsec));
        if (!(r = pthread_cond_timedwait(&g_cv, &g_mu, late ? &said : &dl))) continue;
        if (!late) break;
        told = 1;
        pthread_mutex_unlock(&g_mu); wait_fence_say(fence, site); mu_lock();
    }
    int ok = g_done >= fence || gpu_gone();
    if (noted) wn_out(WN_DONE);
    pthread_mutex_unlock(&g_mu);
    if (ws_on()) { ws_put(site, w0, 1); if (site == WS_SYNC_NEWEST || site == WS_SYNC || site == WS_ACQ) ws_wake(fence); }
    return ok;
}
// The game's SyncWait (hle_nvn.c), with what it waits for in the wait ledger
int mtl_wait(uint64_t fence, uint64_t timeout_ns) { return mtl_wait_at(fence, timeout_ns, !timeout_ns ? WS_SYNC_POLL : fence >= g_fence ? WS_SYNC_NEWEST : WS_SYNC); }
int mtl_wait_acq(uint64_t fence, uint64_t timeout_ns) { return mtl_wait_at(fence, timeout_ns, !timeout_ns ? WS_SYNC_POLL : WS_ACQ); }

static void up_wait_zero(_Atomic int *v, int site);
// Under the suspend's limit (t_drain_by) both waits end there; the caller (drain_steps) reads what is left
static void mtl_finish_gpu_at(int site) {
    if (g_fence) mtl_wait_at(g_fence, drain_left(), site);
    if (on_sub_thread()) rec_publish();   // a batch's commit may still be a record in the encode thread's current block (rec_commit_upload), as in up_begin
    up_wait_zero(&g_up_pending, site);
}
#define mtl_finish_gpu() mtl_finish_gpu_at(WS_DIAG)
void mtl_present_flush(void);
// nvnQueueFinish waits for the GPU work submitted so far, not for queued presents to reach the screen: with a window, the display link takes one present per tick, so waiting for them
// made every QueueFinish cost one or two display frames. Fire Emblem: Three Houses' loader submits a copy and calls QueueFinish for each resource it uploads, and its first loading screen
// took 78 s on the iPhone (5 s windowless on the Mac). A swapchain texture is not handed back before its previous present is processed (AcquireTexture waits for that ticket)
void mtl_finish(void) { mtl_finish_gpu_at(WS_FINISH); }
static int present_drop_for_suspend(void);
static int present_flush_ok(const char *site);
static int snap_drain(void);
// Everything submitted so far has run (suspend, the tests), the one-off command buffers too (once_drain). With no limit (t_drain_by 0) each step waits until it is done and
// this returns NULL; under the suspend's limit (mtl_drain_by) a step whose wait reached it ends the drain, and this names it: the steps after it would only wait on the same GPU
static const char *drain_steps(void) {
    if (gpu_gone()) return "the GPU, taken as lost (DM_GPU_LOST_S)";   // nothing it held will complete: the suspend takes its not-drained path (no trim, the archive written at the exit)
    if (!present_drop_for_suspend()) return "the present on the GPU (present_drop_for_suspend)";
    if (!present_flush_ok("mtl_present_flush (a queue finish, or the suspend)")) return "the present queue (mtl_present_flush)";
    if (!snap_drain()) return "the present snapshot copies (snap_drain)";
    // A limit already reached commits no one-off command buffer: its wait would end at once, and the buffer would go to the queue after the suspend has given up (a drain thread
    // let go late by a lock, in the background, or a resume's retry while the GPU stays stuck), one more never completed behind work that does not finish
    if (drain_over()) return "a one-off command buffer behind all earlier work (once_drain)";
    mtl_init();
    if (!once_drain()) return "a one-off command buffer behind all earlier work (once_drain)";
    mtl_finish_gpu();
    if (g_fence && atomic_load(&g_done) < g_fence) return "the GPU work up to the last fence (mtl_finish_gpu)";
    if (atomic_load(&g_up_pending)) return "the upload batches (mtl_finish_gpu)";
    return NULL;
}
void mtl_drain(void) { drain_steps(); }
// mtl_drain with every wait ending at by (CLOCK_UPTIME_RAW ns): NULL when everything drained, else which step's wait reached the limit. Going to the background (hle_nvn.c
// dm_gfx_suspend), on a thread of its own whose end the main thread waits for no longer than the limit: a lock taken on the way has no limit of its own
const char *mtl_drain_by(uint64_t by) {
    t_drain_by = by ? by : 1;
    const char *what = drain_steps();
    t_drain_by = 0;
    return what;
}

// ================= Render replay =================
#include "../../host/front.h"
__attribute__((weak)) float dm_game_aspect(void) { return 0; }   // loader.c's (the camera stub's acknowledged ratio); the graphics tests have no loader
// Ultrawide's camera (nvn_aspect.h): the final picture, learnt in rp_begin_ex_ (the renderer's thread), and the window textures presented lately (present_enqueue)
static nvn_aspect_canvas g_aspect_canvas; static nvn_aspect_wins g_aspect_wins;
// Texture lookups run on the submit thread and other game threads. Cache conformance for the few Metal texture and wrapper classes they see.
// Only classes and answers are kept here. The caller's reference to the object must be valid for the check (upstream efd1bddd8)
static BOOL obj_is_tex(id object) {
    if (!object) return NO;
    enum { CACHE_SIZE = 8 };
    static _Thread_local struct {
        struct { __unsafe_unretained Class cls; BOOL is_texture; } entries[CACHE_SIZE];
        unsigned next;
    } cache;
    Class cls = object_getClass(object);
    for (unsigned i = 0; i < CACHE_SIZE; i++)
        if (cache.entries[i].cls == cls) return cache.entries[i].is_texture;

    BOOL is_texture = [object conformsToProtocol:@protocol(MTLTexture)];
    unsigned slot = cache.next++ % CACHE_SIZE;
    cache.entries[slot].cls = cls;
    cache.entries[slot].is_texture = is_texture;
    return is_texture;
}

static int g_red_once[184];   // one past the highest key: a new key raises this, and the macro refuses to compile otherwise
#define RED_ONCE(k, ...) do { _Static_assert((k) < sizeof g_red_once / sizeof *g_red_once, "a RED_ONCE key past g_red_once: raise its size"); if (!g_red_once[k]++) MLOG("[RED] " __VA_ARGS__); } while (0)
// Every texture view with a level / layer range goes through mtl_view / mtl_view_sw (after S2Arm a6ba2b665). A range past its source makes newTextureView abort the whole process in
// Metal's validation, with or without the debug layer ("newSliceRange.location + length (3) must be <= (2)": S2Arm's iPhone reports; copy_t2t_draw had its own check, f36edf8c6). Out of
// range, no view is made and the caller gets nil, which each caller takes as "no view" (an empty slot, no draw, the texture as it is). The first one is a red line naming the function,
// the source's shape and the range asked for; later ones a plain line at each power of two of the count. Views that change only the format take no range and do not come here
static NSUInteger mtl_view_slices(id<MTLTexture> t) {   // the slices a view's range counts in: layers of an array, 6 faces of a cube, 6 per cube of a cube array, else 1
    switch (t.textureType) {
        case MTLTextureType1DArray: case MTLTextureType2DArray: case MTLTextureType2DMultisampleArray: return t.arrayLength;
        case MTLTextureTypeCube: return 6;
        case MTLTextureTypeCubeArray: return t.arrayLength * 6;
        default: return 1;
    }
}
static _Atomic uint64_t g_view_refused;   // views refused for their range (mtl_view_range_ok)
static int mtl_view_range_ok(id<MTLTexture> b, NSRange lv, NSRange sl, const char *fn) {
    if (!b) return 0;
    NSUInteger ns = mtl_view_slices(b);
    if (lv.length && sl.length && lv.location < b.mipmapLevelCount && lv.length <= b.mipmapLevelCount - lv.location && sl.location < ns && sl.length <= ns - sl.location) return 1;
    uint64_t n = atomic_fetch_add(&g_view_refused, 1) + 1;
    if (n == 1) MLOG("[RED] texture view outside its source (%s): levels %lu+%lu of %lu, slices %lu+%lu of %lu (source Metal type %lu, %lux%lu, format %lu): not made (Metal would abort the "
                     "process), the caller takes it as no view", fn, (unsigned long)lv.location, (unsigned long)lv.length, (unsigned long)b.mipmapLevelCount, (unsigned long)sl.location,
                     (unsigned long)sl.length, (unsigned long)ns, (unsigned long)b.textureType, (unsigned long)b.width, (unsigned long)b.height, (unsigned long)b.pixelFormat);
    else if (!(n & (n - 1))) MLOG("texture views outside their source, not made: %llu so far (this one in %s: levels %lu+%lu of %lu, slices %lu+%lu of %lu)", (unsigned long long)n, fn,
                                  (unsigned long)lv.location, (unsigned long)lv.length, (unsigned long)b.mipmapLevelCount, (unsigned long)sl.location, (unsigned long)sl.length, (unsigned long)ns);
    return 0;
}
static id<MTLTexture> mtl_view_(id<MTLTexture> b, MTLPixelFormat pf, MTLTextureType tt, NSRange lv, NSRange sl, const char *fn) {
    return mtl_view_range_ok(b, lv, sl, fn) ? [b newTextureViewWithPixelFormat:pf textureType:tt levels:lv slices:sl] : nil;
}
static id<MTLTexture> mtl_view_sw_(id<MTLTexture> b, MTLPixelFormat pf, MTLTextureType tt, NSRange lv, NSRange sl, MTLTextureSwizzleChannels sw, const char *fn) {
    return mtl_view_range_ok(b, lv, sl, fn) ? [b newTextureViewWithPixelFormat:pf textureType:tt levels:lv slices:sl swizzle:sw] : nil;
}
#define mtl_view(b, pf, tt, lv, sl) mtl_view_((b), (pf), (tt), (lv), (sl), __func__)
#define mtl_view_sw(b, pf, tt, lv, sl, sw) mtl_view_sw_((b), (pf), (tt), (lv), (sl), (sw), __func__)
// NVN vertex streams 0–15 → Metal vertex buffer slots: 0–13 go to 16–29 (30 is the constant fallback buffer), 14 and 15 to 14 and 15. Metal has only the 31 slots 0–30; translated shaders use only buffer(0) (the argument buffer),
// and the host's own vertex functions read no vertex buffers. 13 Sentinels uses stream 15, and the old 16 + stream went out of range (Metal assertion: buffer index (31) must be < 31)
#define VB_SLOT(st) ((st) < 14 ? 16 + (st) : (st))

// ---------- Texture → MTLTexture ----------
static int fmt_compressed(int f) { return (f >= 0x41 && f <= 0x50) || (f >= 0x79 && f <= 0x94); }
static int fmt_depth(int f) { return f >= 0x31 && f <= 0x36; }
typedef struct { MTLPixelFormat a, b; } pfv_pair;
static const pfv_pair g_pfv_srgb[] = {
    {MTLPixelFormatRGBA8Unorm, MTLPixelFormatRGBA8Unorm_sRGB},
    {MTLPixelFormatBGRA8Unorm, MTLPixelFormatBGRA8Unorm_sRGB},
    {MTLPixelFormatBC1_RGBA, MTLPixelFormatBC1_RGBA_sRGB},
    {MTLPixelFormatBC2_RGBA, MTLPixelFormatBC2_RGBA_sRGB},
    {MTLPixelFormatBC3_RGBA, MTLPixelFormatBC3_RGBA_sRGB},
    {MTLPixelFormatBC7_RGBAUnorm, MTLPixelFormatBC7_RGBAUnorm_sRGB},
};
// The linear format of an sRGB one (the other half of its g_pfv_srgb pair), or MTLPixelFormatInvalid for a format that is not sRGB
static MTLPixelFormat pf_srgb_linear(MTLPixelFormat pf) {
    for (size_t i = 0; i < sizeof g_pfv_srgb / sizeof *g_pfv_srgb; i++) if (pf == g_pfv_srgb[i].b) return g_pfv_srgb[i].a;
    return MTLPixelFormatInvalid;
}
static int tex_need_pfv(MTLPixelFormat base, MTLPixelFormat view) {
    if (base == view) return 0;
