// or one the ring has overwritten) makes the table be built whole. Under g_snote_lk
enum { SER_LOG = 4096 };
typedef struct { uint64_t gen, serial; } ser_lnote;
static ser_lnote g_ser_log[SER_LOG];
static void ser_note(uint64_t serial) {
