// pool_sers is an open-addressed table by serial (0: an empty slot; serials start at 1), cappool_sers slots, a power of two, at most half full: the pool walks ask about
// every entry they patch (Ocarina of Time: each ID in its 2D and its 2D-array table), and the list it was scanned in full under the lock on each, growing with every member made
static int ls_in_pool(uint64_t ser);   // a texture ID is registered with ser (1 while g_rmu is busy: kept)
static inline uint32_t fam_ser_slot(uint64_t serial, uint32_t cap) { uint64_t h = serial * 0x9e3779b97f4a7c15ull; return (uint32_t)(h >> 32) & (cap - 1); }
static void fam_track_pool_serial(NvImageHeap *o, uint64_t serial, uint64_t wh) {
    if (!o || !serial) return;
    os_unfair_lock_lock(&o->pool_lk);
    if ((o->npool_sers + 1) * 2 > o->cappool_sers) {   // grow, rehashing
