        fam_pool_ser *nt = calloc(ncap, sizeof *nt); if (!nt) { os_unfair_lock_unlock(&o->pool_lk); return; }
        for (uint32_t i = 0; i < o->cappool_sers; i++) if (o->pool_sers[i].serial) {
            uint32_t j = fam_ser_slot(o->pool_sers[i].serial, ncap); while (nt[j].serial) j = (j + 1) & (ncap - 1); nt[j] = o->pool_sers[i]; }
        free(o->pool_sers); o->pool_sers = nt; o->cappool_sers = ncap;
