    if (live != o->npool_sers) {   // rehash the survivors (open addressing has no deletion)
        fam_pool_ser *nt = calloc(o->cappool_sers, sizeof *nt);
        if (nt) { for (uint32_t i = 0; i < o->cappool_sers; i++) if (o->pool_sers[i].serial) {
