                  free(o->pool_sers); o->pool_sers = nt; o->npool_sers = live; }
        else o->npool_sers = live;   // the cleared slots stay empty; a probe may stop early at one and add a serial again, which a later switch notes twice at most
    }
    for (uint32_t i = 0; i < o->cappool_sers; i++) {
        if (!o->pool_sers[i].serial) continue;
        uint64_t ewh = o->pool_sers[i].wh;
        if (ewh != prev && ewh != wh) continue;
        if (ns == cap) {
            cap *= 2;
            uint64_t *nb = sers == stack_s ? malloc(cap * sizeof *nb) : realloc(sers, cap * sizeof *nb);
            if (!nb) break;
            if (sers == stack_s) memcpy(nb, stack_s, ns * sizeof *nb);
            sers = nb;
        }
        sers[ns++] = o->pool_sers[i].serial;
    }
    os_unfair_lock_unlock(&o->pool_lk);
    for (uint32_t i = 0; i < ns; i++) ser_note(sers[i]);
