        static _Atomic uint64_t nsw, nnoted, nmax; uint64_t k = atomic_fetch_add_explicit(&nsw, 1, memory_order_relaxed) + 1; atomic_fetch_add_explicit(&nnoted, ns, memory_order_relaxed);
        uint64_t m = atomic_load_explicit(&nmax, memory_order_relaxed); while (ns > m && !atomic_compare_exchange_weak(&nmax, &m, ns)) {}
        if (k % 2000 == 0) MLOG("resolution families: %llu size switches, %.1f serials noted a switch on average, at most %llu (notes kept per sync: %d)", (unsigned long long)k,
