// A pool table entry of a compressed family member: its serial is tracked, and 0 (the dummy) when the heap holds another size
static inline int fam_pool_masked(id<MTLTexture> t, uint64_t serial) {
    uint64_t wh = 0; NvImageHeap *o = fam_owner(t, &wh);
    if (!o || !o->compressed) return 0;
    fam_track_pool_serial(o, serial, wh);
    return atomic_load_explicit(&o->valid_wh, memory_order_acquire) != wh;
