            uintptr_t fk = (uintptr_t)x->u.fam; uint32_t fi = (uint32_t)(uintptr_t)nvn_hm_get(&famix, &fk);
            if (!fi) {
                if (nf == fcap) { fcap = fcap ? fcap * 2 : 32; fams = realloc_or_die(fams, fcap * sizeof *fams, "the resolution families asked"); }
                NvImageHeap *own = objc_getAssociatedObject((__bridge id)val, &g_image_heap_owner_key);   // the record's family heap, which the member holds (its record was made for it: tu_register)
                fams[nf] = (tu_fam){own == (__bridge NvImageHeap *)x->u.fam ? own : nil, e, e, e, UINT32_MAX, 0};
                fi = ++nf; nvn_hm_put(&famix, &fk, (void *)(uintptr_t)fi);
            } else {
                tu_fam *f = &fams[fi - 1]; ents[f->last].next = e; f->last = e;
                if (x->u.use > ents[f->best].u.use) f->best = e;
            }
            tu_fam *f = &fams[fi - 1];
            if (f->own && val == f->own->hint) f->hint = e;
            if (nb < max) f->asked = 1; else cut = 1;
            continue;
        }
        if (nb >= max) { cut = 1; continue; }
        int d = tu_ask(x, now, idle, pinned);
        if (d == 2) st.pinned++;
        if (d != 1) continue;
        dead_push(&vk, &nv, &cap, alias_key_at(x->slot)); CFSetAddValue(dead, val); nb++;
    }
    int unc_built = 0; CFMutableSetRef unc_own = NULL;
    for (uint32_t fi = 0; fi < nf; fi++) {
        tu_fam *f = &fams[fi];
        if (!f->asked || !f->own) continue;   // no member came before the limit: none of it is asked this pass, as before (nor a family whose record and heap disagree, which no path makes)
        uint32_t keep = UINT32_MAX;   // a member not dead: the family stays
        if (f->hint != UINT32_MAX && tu_ask(&ents[f->hint], now, idle, pinned) != 1) keep = f->hint;
        else if (tu_ask(&ents[f->best], now, idle, pinned) != 1) keep = f->best;
        if (keep != UINT32_MAX) {   // the others unasked: those unused for the wait marked at their last use (not counted for the skip), the one not dead unmarked
            for (uint32_t e = f->first; e != UINT32_MAX; e = ents[e].next) {
                tu_ent *x = &ents[e]; id o = (__bridge id)g_alias.vals[x->slot];
                if (e == keep) { if (x->u.kept) tu_kept(o, 0, now, idle); continue; }
                if (x->u.use && now - x->u.use >= idle) { st.fam_kept++; if (x->u.kept != x->u.use) tu_kept(o, 1, now, idle); }
            }
            f->own->hint = g_alias.vals[ents[keep].slot];
            continue;
        }
        // Both dead: every member is asked, and the old rule decides
        if (!unc_built) { unc_built = 1; if (CFSetGetCount(unc)) { unc_own = CFSetCreateMutable(NULL, 0, NULL); CFSetApplyFunction(unc, tu_unc_owner, unc_own); } }
        int all = !(unc_own && CFSetContainsValue(unc_own, (__bridge const void *)f->own)), cand = 0; uint32_t alive = UINT32_MAX;   // alive: the first member not dead
        for (uint32_t e = f->first; e != UINT32_MAX; e = ents[e].next) {
            int d = tu_ask(&ents[e], now, idle, pinned);
            all &= d == 1; cand |= e < cut_at && d == 1;
            if (e < cut_at && d == 2) st.pinned++;
            if (d != 1 && alive == UINT32_MAX) alive = e;
        }
        if (alive != UINT32_MAX) f->own->hint = g_alias.vals[ents[alive].slot];   // asked first next time
        if (!cand) continue;   // no member before the limit is dead: the old rule asked no more of it
        for (uint32_t e = f->first; all && e != UINT32_MAX; e = ents[e].next)   // each member's own family heap, read once a family goes (records are made for their texture: tu_register, alias_put, tex_names_move)
            all = objc_getAssociatedObject((__bridge id)g_alias.vals[ents[e].slot], &g_image_heap_owner_key) == f->own;
        if (all) {   // it goes whole, past `max`
            for (uint32_t e = f->first; e != UINT32_MAX; e = ents[e].next) { dead_push(&vk, &nv, &cap, alias_key_at(ents[e].slot)); CFSetAddValue(dead, g_alias.vals[ents[e].slot]); }
            st.fam_n++; st.fam_bytes += f->own->heap.size; if (g_tu_drop) f->own->drop = 1;
            continue;
        }
        for (uint32_t e = f->first; e != UINT32_MAX; e = ents[e].next) {   // it stays: the dead members before the limit are kept at their last use, the first member not dead unmarked
            tu_ent *x = &ents[e]; id o = (__bridge id)g_alias.vals[x->slot];
            if (x->d == 1) { if (e < cut_at) { st.fam_kept++; tu_kept(o, 1, now, idle); } }
            else if (e == alive && x->u.kept) tu_kept(o, 0, now, idle);
        }
    }
    if (unc_own) CFRelease(unc_own);
    CFRelease(pinned);
    if (nv) {
        uint64_t *ks = NULL; uint32_t nk = 0; drop_entries_naming_locked(dead, 1, 1, &ks, &nk);   // the serial entries that name one of them or a view of one, live and ghost
        for (uint32_t j = 0; j < nv; j++) {
            id<MTLTexture> o = hm_get_id(&g_alias, &vk[j]);
            if (o && objc_getAssociatedObject(o, &g_image_heap_owner_key)) st.fam++;
            else if ([o respondsToSelector:@selector(allocatedSize)]) st.bytes += rh_tex_bytes(o, g_tu_drop);
            alias_del(&vk[j]);
        }
        st.n = nv; st.serials = nk; *serials = ks; *nserials = nk;
    }
    free(vk); CFRelease(dead);
    if (!cut) g_tu_kept_gone = atomic_load_explicit(&g_alias_gone, memory_order_relaxed);   // after its own releases: every family was asked again (a member kept for one that left the table counts no more)
    return st;
}
// ---------- Shared textures kept by the sharing table alone (DM_NVN_SHARED_IDLE) ----------
// The memory line's "kept by the sharing table alone" (alias_unheld_locked): entries no live or finalized serial, view or pin holds. Only a pool's Finalize, a takeover by a new
// texture over their storage (alias_take_over) or a release of a target another drew over (DM_NVN_RT_DEAD) let them go, so one whose storage nothing reuses stays for good: in
// Ocarina of Time on an iPhone 18 Pro Max (oot-x2-1117, frame 23,400, Hyrule Castle) 190 of them held 425 MB, the oldest unused for 536,436 submissions (about the whole run), at a
// 5.5 GB footprint. An entry stays only so that a texture object made again over the same storage with the same description finds what the old one held. So one that no lookup found
// for `idle` submissions (g_alias_seen) goes when its storage holds what it holds, and a new object over that storage is made from there as any texture is:
// Off by default since 2026-11-22: on an iPhone 18 Pro Max Ocarina of Time's field showed blocks of other ground textures after the player travelled far and came back, gone only
// with this switch at 0 (every other suspect ruled out one by one, docs/reference/memory.md), while the release gave back 2-10 MB a run. Which released texture the game wanted
// back with other content is not known; =1 keeps the rules below for a test.
//  - mode 1: a texture the GPU cannot render or write into (no render-target or shader-write usage) in a pool the CPU can read, not sparse and not COMPRESSIBLE,
//    LINEAR or display / video (tex_storage_ok: its content came from the storage, and a GPU copy into it is stored there too, gsb_store), or one the GPU can render into
//    whose writes are stored into its storage (tex_storage_ok of the uncompressed kind, gsb_host_ok: a format the host neither widens nor makes depth);
//  - mode 2: every such entry, the GPU's own content included (a render target in a CPU_NO_ACCESS pool, whose storage never gets what the GPU drew). A game that makes a texture
//    object again over such storage long after and reads it before drawing would read what the storage holds (zeros, or the dummy); off by default until a device A/B shows none does.
// A resolution family member (image_texture) stays: alone it gives nothing back (its family's heap goes with its last member, DM_NVN_RT_DEAD). The entry leaves the table as a takeover
// takes one (alias_del: retired behind the submission in flight, a note that names no texture), its recycled heap waiting for reuse. A walk of the table, under g_smu, at a commit
// every SI_EVERY submissions. DM_NVN_SHARED_IDLE=0 keeps them all, as before; DM_NVN_SHARED_IDLE_SUBS sets `idle` (65,536 by default, about 40-60 s of play at Ocarina's
// 25-40 submissions a frame: a texture released and wanted again costs an upload, so the wait is long)
enum { SI_EVERY = 1024, SI_IDLE_DEF = 65536, SI_IDLE_MIN = 1024 };
static int tex_storage_ok(const tex_t *t, int unc); static int gsb_on(void); static int gsb_host_ok(const tex_t *t, id<MTLTexture> mt);
static int g_si_mode = -1; static uint64_t g_si_idle;   // the tests set them
static uint64_t g_si_n, g_si_bytes, g_si_win_n, g_si_win_bytes, g_si_gpu_n, g_si_gpu_bytes, g_si_walk_ns, g_si_reg_kept;   // g_si_reg_kept: idle entries a texture ID still names, kept (last walk)
static void rmu_lock(void); static void rmu_unlock(void); static CFMutableSetRef treg_held_set(void);   // released in all / in the window; idle and kept for the GPU's own content (last walk); walks' time
static int si_mode(void) {
    if (g_si_mode < 0) {
        const char *e = getenv("DM_NVN_SHARED_IDLE"), *s = getenv("DM_NVN_SHARED_IDLE_SUBS"); int m = e ? atoi(e) : 0;   // off by default (see below)
        g_si_mode = m < 0 ? 0 : m > 2 ? 2 : m;
        g_si_idle = s && strtoull(s, NULL, 10) >= SI_IDLE_MIN ? strtoull(s, NULL, 10) : SI_IDLE_DEF;
        if (g_si_mode) MLOG("DM_NVN_SHARED_IDLE=%d: shared textures kept by the sharing table alone and unused for %llu submissions are released%s", g_si_mode, (unsigned long long)g_si_idle,
                            g_si_mode == 1 ? " when their storage holds their content" : ", their content the GPU's own included");
    }
    return g_si_mode;
}
// Whether entry k's texture o holds nothing its storage does not: 1 its content is the storage's, 0 the GPU's own
static int si_storage_holds(const alias_key *k, id<MTLTexture> o) {
    const pool_t *p = (const pool_t *)(uintptr_t)k->pool; if (!p || !p->mem) return 0;
    tex_t t; memset(&t, 0, sizeof t); t.d = k->d; t.pool = (pool_t *)p; t.off = k->off; t.mem = p->mem + k->off;
    if (!(o.usage & (MTLTextureUsageRenderTarget | MTLTextureUsageShaderWrite))) return tex_storage_ok(&t, 0) && !(k->d.flags & (NVN_TEXTURE_FLAGS_DISPLAY | NVN_TEXTURE_FLAGS_VIDEO_DECODE));
    return !fmt_compressed(k->d.format) && tex_storage_ok(&t, 1) && gsb_on() && gsb_host_ok(&t, o);
}
// One walk: the entries to release, at most `max`. Returns how many went. Caller holds g_smu
// treg_held: the textures a live texture ID registration still names (its view, type / class views and their parents; treg_held_set), or NULL. Such a texture is in use whatever
// g_alias_seen says: an ID's cached view and the pool tables built from it name it without a lookup, so a terrain tile Ocarina of Time samples through its texture pool was released
// once the player had been elsewhere for a minute, and the tables kept naming it (wrong ground, blocks of other textures, until a scene load rebuilt them; docs/reference/memory.md, shared textures released while the game still used them; S2Arm 50f032a62, MIT)
static uint32_t shared_idle_locked(int mode, uint64_t idle, uint32_t max, CFSetRef treg_held) {
    if (!mode || !g_alias.n) return 0;
    const uint64_t now = g_fence + 1;
    alias_key *ks = NULL; uint32_t n = 0, cap = 0; uint64_t gpu_n = 0, gpu_b = 0, bytes = 0, reg_n = 0;
    CFMutableSetRef sized = CFSetCreateMutable(NULL, 0, NULL);
    for (uint32_t i = 0; i < g_alias.cap && n < max; i++) {
        void *v = g_alias.vals[i]; id o = (__bridge id)v;
        if (!v || entry_holds(v) || tex_object_pinned(o) || ![o respondsToSelector:@selector(allocatedSize)] || objc_getAssociatedObject(o, &g_image_heap_owner_key)) continue;
        const alias_key *k = alias_key_at(i);
        uint64_t seen = (uint64_t)(uintptr_t)nvn_hm_get(&g_alias_seen, k);
        if (!seen || now <= seen || now - seen < idle) continue;
        if (treg_held && CFSetContainsValue(treg_held, v)) { reg_n++; continue; }
        int own = !si_storage_holds(k, (id<MTLTexture>)o);
        uint64_t b = CFSetContainsValue(sized, v) ? 0 : rh_tex_bytes((id<MTLTexture>)o, 0);
        if (own && mode < 2) { if (b) { gpu_n++; gpu_b += b; CFSetAddValue(sized, v); } continue; }
        if (b) CFSetAddValue(sized, v);
        bytes += b;
        if (n == cap) { cap = cap ? cap * 2 : 64; ks = realloc_or_die(ks, cap * sizeof *ks, "the idle shared textures"); }
        ks[n++] = *k;
    }
    CFRelease(sized);
    for (uint32_t j = 0; j < n; j++) alias_del(&ks[j]);   // deletion shifts entries: collected first
    if (n) ser_note_all();
    free(ks);
    g_si_n += n; g_si_win_n += n; g_si_bytes += bytes; g_si_win_bytes += bytes; g_si_gpu_n = gpu_n; g_si_gpu_bytes = gpu_b; g_si_reg_kept = reg_n;
    return n;
}
static void shared_idle_commit(void) {   // mtl_sub_commit, submit thread
    if (((g_fence + 1) % SI_EVERY) || !si_mode()) return;
    uint64_t t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    rmu_lock(); CFMutableSetRef held = treg_held_set(); smu_lock(); rmu_unlock();   // g_rmu before g_smu, as the idle-texture release takes them
    shared_idle_locked(g_si_mode, g_si_idle, 256, held); pthread_mutex_unlock(&g_smu); CFRelease(held);
    g_si_walk_ns += clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0;
}
// Each submission's commit (mtl_sub_commit, submit thread): above ghost_floor, the low-headroom drop or the idle drain (see g_ghost). The headroom is read outside g_smu, at most every
// GHOST_HEADROOM_EVERY_NS, and only while the table is above its floor; on the Mac none is known (g_rh_avail NULL) and only the drain runs. A table at its floor costs one lock
static void ghost_commit(void) {
    smu_lock(); unsigned keep = ghost_floor(), held = g_ghost.n; pthread_mutex_unlock(&g_smu);
    if (held <= keep) return;
    uint64_t avail = 0;
    if (g_rh_avail) { uint64_t now = clock_gettime_nsec_np(CLOCK_MONOTONIC); if (!g_ghost_hr_at || now - g_ghost_hr_at >= GHOST_HEADROOM_EVERY_NS) { g_ghost_hr_at = now; avail = g_rh_avail(); } }
    int low = avail && avail < GHOST_LOW_HEADROOM;
    smu_lock();
    unsigned n = low ? ghost_release(keep, UINT_MAX, 0) : ghost_release(keep, GHOST_DRAIN, 1);
    if (low) g_ghost_low += n; else g_ghost_drained += n;
    held = g_ghost.n; pthread_mutex_unlock(&g_smu);
    static uint64_t logged_frame; static int logged;
    uint64_t f = atomic_load_explicit(&g_cur_frame, memory_order_relaxed);
    if (low && n && (!logged || f >= logged_frame + 300)) {
        logged = 1; logged_frame = f;
        MLOG("finalized-texture table: headroom to the system memory limit %llu MB, under %llu MB: %u entries let go at once, %u held now (down to %u but for what submissions in flight use), frame %llu",
             (unsigned long long)(avail >> 20), (unsigned long long)(GHOST_LOW_HEADROOM >> 20), n, held, keep, (unsigned long long)f);
    }
}
// Host record of a packaged texture: the current MTLTexture, the upload stamp, and the global write generation at the last check
// spare: the texture the last re-upload replaced, kept resident and written by the next re-upload once the GPU has passed spare_fence (a texture the CPU rewrites every frame, a movie frame,
// alternates between two textures instead of allocating one per frame: Link's Awakening's title movie made and freed an 8 MB texture a frame)
@interface NvPkg : NSObject { @public id<MTLTexture> tex, spare, view; uint64_t stamp, seen, hash, spare_fence, spare_stamp, spare_sub, vgen, vseen, sub, tex_gen, spare_gen; uint64_t pnow, dnow, dlim; unsigned tex_seq, spare_seq; const void *span; int sparse, vbase; uint8_t *edge[2]; uint32_t edge_n[2], stored; id ps; id<MTLBuffer> eb; uint8_t md, md_no, md_ext, gw_lost; uint64_t md_saved; uint64_t (*runs)[2]; int nruns; uint8_t lok; uint64_t lid, lseq; } @end   // hash: full hash of the uploaded content under DM_NVN_DIRTYCHECK; span: its tracked range (nvn_dirty_span, NULL = untracked);
// spare_stamp: the stamp spare's content was read at (pkg_upload_'s partial re-upload into it), 0 when that content is not known good (its upload was dropped and redone into another texture)
// pnow: the dirty clock just after tex's upload protected its pages (g_pkg_pnow; 0 unknown), for nvn_dirty_needed; dnow, dlim: the clock and submission write limit of its last deferred
// re-upload (reup_defer)
// tex_seq, spare_seq: the upload batch that wrote tex and spare (g_pkg_seq), 0 when not known: tex_upgrade's copy, which a submission's own blit writes (up_seq_back); tex_gen, spare_gen: the main
// command buffer that batch ran before (g_pkg_gen), for the GPU stores since (gsb_log_since)
// spare_sub: the submission (g_sub_serial) of the re-upload that made spare; a spare no re-upload has used for PKG_SPARE_IDLE submissions is let go (pkg_spare_trim)
// sparse: in a sparse virtual pool, read through its page table (hle_nvn.c nvn_sparse_*), vgen the page table's generation at the upload and vseen at the last look; view: what it is bound as (sparse_view)
// ps: its placement sparse texture (NvSparse, sparse_make), which tex is: mapped and uploaded tile by tile (sparse_sync)
// edge: the uploaded bytes of the storage's first and last host pages where other data shares them (pkg_edges_take); in eb from the first GPU store into its storage on (pkg_edges_gpu),
// where the store writes them too
// Its release retires its textures (defer_obj_release, not res_remove at once): serials that took its texture over (cpu_unc_drop) keep it resident (defer_drain)
// stored: GPU writes stored into its storage since its upload (gsb_swz; the DM_NVN_REUPLOADS line), which DM_NVN_DIRTYCHECK does not count as missed CPU writes; gw_lost: a GPU write
// into it that its storage did not get (gsb_lost), for good: the idle release keeps it (tidle_tex_w)
// runs, nruns, lok, lid, lseq: a sparse texture's runs of physical memory and where its pool's change log stood when a walk of its page table found it clean (lok: they are kept; pkg_sparse_clean)
// md: the top levels tex was made without (DM_NVN_MIP_DROP, md_note), md_saved their bytes, md_ext which switch let it in (md_ext_of: 1 DM_NVN_MIP_DROP_COMPRESSIBLE, 2 DM_NVN_MIP_DROP_PARTIAL, 0 neither); md_no: made whole again for a host use of its levels (md_whole), never dropped again
static void md_forget(uint64_t bytes, unsigned ext);
@implementation NvPkg
- (void)dealloc { free(runs); if (md) md_forget(md_saved, md_ext); defer_obj_release(tex); defer_obj_release(spare); if (eb) defer_obj_release(eb); else { free(edge[0]); free(edge[1]); } }
@end
// Spares that have gone idle. A texture re-uploaded once kept its spare for good: in NieR:Automata's heavy scene two 32 MB arrays re-upload every slow frame, and their spares (48-64 MB) stayed after the scene. Each re-upload that makes a spare puts its NvPkg in g_pkg_spares (weak: the serials' entries own it); every PKG_SPARE_SCAN submissions the submit thread looks at them, and a spare no re-upload has used for PKG_SPARE_IDLE submissions (about 10 s at 60 fps) goes through the deferred-release queue, which takes it out of the residency set after the next submission's fence (or leaves it resident while a serial entry that took it over still draws it, defer_drain). The next re-upload of that texture then makes a new texture and copies the layers not written since from the one it replaces (pkg_upload_'s from-old path), or uploads it whole, as a texture with no spare always did. The scan also counts the spares alive for the memory line. DM_NVN_PKG_SPARE_IDLE=0 keeps every spare, as before
enum { PKG_SPARE_IDLE = 600, PKG_SPARE_SCAN = 64 };
static NSHashTable *g_pkg_spares; static os_unfair_lock g_pkg_spares_lk = OS_UNFAIR_LOCK_INIT;
static _Atomic uint64_t g_pkg_spare_n, g_pkg_spare_bytes, g_pkg_spare_freed, g_pkg_spare_freed_bytes;   // spares alive at the last scan and their bytes; spares let go when idle and their bytes, in total (the memory line)
static int pkg_spare_idle_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("DM_NVN_PKG_SPARE_IDLE"); on = !e || atoi(e); } return on; }
static void pkg_spare_note(NvPkg *pk) { @autoreleasepool { os_unfair_lock_lock(&g_pkg_spares_lk); if (!g_pkg_spares) g_pkg_spares = [NSHashTable weakObjectsHashTable]; [g_pkg_spares addObject:pk]; os_unfair_lock_unlock(&g_pkg_spares_lk); } }
// On the submit thread at a submission's start (mtl_sub_begin), where no re-upload runs: only the submit thread re-uploads a packaged texture or reads its spare (the fetch above)
// idle: the submissions without a re-upload that let a spare go (UINT64_MAX: none; 0: every one, mtl_trim); fence: the one it waits for in the deferred-release queue. Returns the bytes let go; *nout the spares
static uint64_t pkg_spare_release(uint64_t idle, uint64_t fence, int *nout) { uint64_t freed = 0; int nf = 0; @autoreleasepool {
    os_unfair_lock_lock(&g_pkg_spares_lk); NSArray<NvPkg *> *all = g_pkg_spares.allObjects; os_unfair_lock_unlock(&g_pkg_spares_lk);
    if (!all.count) { atomic_store(&g_pkg_spare_n, 0); atomic_store(&g_pkg_spare_bytes, 0); *nout = 0; return 0; }
    uint64_t n = 0, bytes = 0; NSMutableArray<NvPkg *> *gone = nil;
    for (NvPkg *pk in all) {
        if (pk->spare && g_sub_serial - pk->spare_sub >= idle) {
            uint64_t z = pk->spare.allocatedSize; nf++; freed += z;
            atomic_fetch_add(&g_pkg_spare_freed, 1); atomic_fetch_add(&g_pkg_spare_freed_bytes, z);
            defer_obj_at(pk->spare, 0, fence); pk->spare = nil; pk->spare_stamp = 0; pk->spare_seq = 0; pk->spare_gen = 0;
        }
        if (pk->spare) { n++; bytes += pk->spare.allocatedSize; }
        else { if (!gone) gone = [NSMutableArray array]; [gone addObject:pk]; }
    }
    if (gone) { os_unfair_lock_lock(&g_pkg_spares_lk); for (NvPkg *pk in gone) [g_pkg_spares removeObject:pk]; os_unfair_lock_unlock(&g_pkg_spares_lk); }
    atomic_store(&g_pkg_spare_n, n); atomic_store(&g_pkg_spare_bytes, bytes);
} *nout = nf; return freed; }
static void pkg_spare_trim(void) { if (g_sub_serial % PKG_SPARE_SCAN) return; int n; pkg_spare_release(pkg_spare_idle_on() ? subs_for_frames(PKG_SPARE_IDLE) : UINT64_MAX, g_fence + 1, &n); }   // PKG_SPARE_IDLE frames
// Packaged textures by storage and description. Engines make many texture objects over one texture's bytes, each with a serial of its own: Ocarina of Time's 32,768 registered IDs name 3,607 storages,
// 2.0 GB, and an upload per serial took 6 GB, past what a 16 GB Mac can keep wired once the pools are added. A new serial with the same storage and description takes the same NvPkg, so its
// dirty-page checks and re-uploads are one. Weak: the serials' entries own it, and a table entry never keeps one alive. Under g_smu; a pool's entries go when it is finalized (mtl_alias_drop_pool)
@interface NvPkgRef : NSObject { @public __weak NvPkg *pkg; } @end
@implementation NvPkgRef @end
// A memory pool's Finalize (after upstream NXNative 13c35e90a, by hand onto this tree's in-file tables). On NVN it ends the pool's memory, and with it every texture made on that
// storage, whether or not the game has finalized the texture objects yet.
// - The pool's textures leave the sharing table (the keys collected first, then deleted: deletion shifts entries back). The sharing table used not to evict: Mario's pools stay for
//   good, so entries are bounded; Engage frees pools on scene changes and rebuilds on new ones, so the old pools' render targets and other private textures stayed in the table
//   forever (about 0.8 GB more GPU memory over 850 s of the title demo), and linear textures built directly on a pool also kept the whole pool buffer alive. Also, when a pool
//   object's address is reused, old entries would hand a texture on the old storage to the new pool's texture at the same offset and description.
// - The entries of the pool's live texture objects go (g_pool_tex), whatever they hold: a shared texture, a view of one, a packaged texture, its texture taken over by the GPU. Kept
//   until the object's own Finalize, an entry held the Metal texture and its memory: Ocarina of Time finalizes its 12288x12288 Depth16 shadow target's 288 MB pool at the load into
//   Hyrule Field and the texture object only at the load back into Kakariko Village, after it has made the target again, so the old 300 MB heap stayed resident through the whole
//   field and beside the new one at the village load (docs/reference/memory.md, A texture object finalized after its pool kept the pool's memory). The objects keep their place in
//   g_tex_live: their own Finalize comes later, finds nothing to end and retires their descriptors as before.
// - The finalized serials' entries (ghost) that name one of those textures go too: a ghost entry is kept by use, and one under the table's floor is never drained. So does any other
//   entry that still names one (drop_entries_naming_locked, which the held counts usually let skip its walk).
// `also` (may be NULL): objects of the pool the sharing table does not name (its packaged textures, g_pkg_share, which finalized serials may hold); pkg_parts adds the textures each
// object stands for (a package's texture, which the GPU's first write over its storage hands to its serials, cpu_unc_drop). The work encoded before the Finalize still has them: the
// release waits for the submission in flight (defer_obj_release), and a pin (a queued descriptor, a saved binding) still holds them. A later lookup of such a serial finds no host
// texture (tex_mtl_: a texture of a pool that is gone makes nothing). → how many sharing-table entries went. Caller holds g_smu
