static void gone_add(CFMutableSetRef gone, id o) { if (!o) return; CFSetAddValue(gone, (__bridge const void *)o); pkg_parts(o, ^(id part) { if (part) CFSetAddValue(gone, (__bridge const void *)part); }); }
static uint32_t pool_finalize_locked(const void *pool, CFSetRef also) {
