static alias_key tex_alias_key(const tex_t *t) {
    alias_key k; memset(&k, 0, sizeof k); k.pool = (uint64_t)(uintptr_t)t->pool; k.off = t->off; k.d = t->d;
    // IMAGE permits shader writes; it does not change storage. Xenoblade Chronicles 3's depth and stencil-sampling objects differ only by this flag. Separate Metal textures
    // made the stencil read zero and rejected every deferred-lighting pass. Actual image writes add Metal usage before opening their encoder (image_prepare).
    k.d.flags &= ~NVN_TEXTURE_FLAGS_IMAGE;
    // Sample count 0 and 1 both mean single-sampled (nvn_tex.h) and lay the storage out the same, so the key takes 1 for both. S2Arm found a game whose compute pass writes an
    // image object and whose render pass samples another over the same storage, differing only so: two Metal textures, the reads saw one nothing wrote, a black 3D scene on iOS
    // (ported from S2Arm 5863a69c, Apache-2.0)
    if (k.d.samples == 0) k.d.samples = 1;
    return k;
}
static NvPkg *pkg_shared(const tex_t *t) {
    alias_key k = tex_alias_key(t); NvPkg *pk = nil;
    smu_lock(); NvPkgRef *r = hm_get_id(&g_pkg_share, &k); if (r) pk = r->pkg; pthread_mutex_unlock(&g_smu);
    return pk;
}
// r's package under t's key, for a resolution that read fs before t's pool's magic: none under a pool that is gone (g_pool_ended, pool_fin_since). Caller holds g_smu, and puts the
// serial's entry in the same hold (tex_mtl_)
