static uint64_t md_bytes(const tex_t *t, unsigned k) {   // the bytes of t's levels 0 .. k - 1, every layer
    int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh); uint64_t n = 0;
