static _Atomic uint64_t g_mdr_n[MDR_N], g_mdr_bytes[MDR_N];   // uploads that kept every level, by reason, and the bytes of their top K levels (what leaving them out would have saved)
// The reason t itself cannot be made without its top k levels (MDR_*), or -1: every reason md_pick checks of the texture, the floor last
static int md_shape_why(const tex_t *t, unsigned k) {
    if (!fmt_compressed(t->d.format)) return MDR_FORMAT;
    if (t->d.target != NVN_TEXTURE_TARGET_2D && t->d.target != NVN_TEXTURE_TARGET_2D_ARRAY) return MDR_TARGET;
    uint32_t extra = t->d.flags & ~(uint32_t)NVN_TEXTURE_FLAGS_MINIMAL_LAYOUT;
    if (t->d.samples > 1 || (extra & ~(uint32_t)NVN_TEXTURE_FLAGS_COMPRESSIBLE)) return MDR_FLAGS;
    if (extra && !md_cflag_on()) return MDR_CFLAG;
    if (t->pool && nvn_sparse_pool(t->pool)) return MDR_SPARSE;
    uint32_t w = t->d.width, h = t->d.height, n = t->d.levels, big = MAX(w, h);
    unsigned fit = 1; while (big >> fit) fit++;
    if (n > fit || n < k + 2) return MDR_CHAIN;
    if ((big >> (n - 1)) > 4 && !md_partial_on()) return MDR_SHORT;
    int bw, bh; if (!nvn_fmt_bpb(t->d.format, &bw, &bh)) return MDR_FORMAT;
    if (MIN(w, h) < (16u << k) || ((w | h) & ((1u << k) - 1)) || (w % bw == 0 && (w >> k) % bw) || (h % bh == 0 && (h >> k) % bh)) return MDR_SHAPE;
    if (big < g_md_min) return MDR_FLOOR;
