}
// The top levels this upload of t leaves out (0: all of them made), and with DM_NVN_MIP_DROP on, why not when none (*why, MDR_*; -1 when it drops them). path: the upload's own
// reason, MDR_DRAWN or MDR_UNTRACKED, or -1; t_md_allow set by the caller
static unsigned md_pick(const tex_t *t, int path, int *why) {
    unsigned k = (unsigned)md_k(); *why = -1;
    if (!k) return 0;
    int w = md_shape_why(t, k);
    if (w < 0) w = path >= 0 ? path : t_md_allow == 2 ? MDR_WHOLE : t_md_allow != 1 ? MDR_OUTSIDE : -1;
    *why = w;
    return w < 0 ? k : 0;
}
static void md_tally(const tex_t *t, int why) {
    if (why < 0 || why >= MDR_N) return;
    atomic_fetch_add_explicit(&g_mdr_n[why], 1, memory_order_relaxed); atomic_fetch_add_explicit(&g_mdr_bytes[why], md_bytes(t, (unsigned)md_k()), memory_order_relaxed);
}
// The tally's text for the mip drop line: "; uploads that kept every level in all, by reason (the MB of their top levels): R N (M MB), …", the reasons with any, in MDR_* order
static void md_tally_text(char *out, size_t n) {
    int o = snprintf(out, n, "; uploads that kept every level in all, by reason (the MB of their top levels):"); int any = 0;
    for (int r = 0; r < MDR_N && o > 0 && (size_t)o < n; r++) {
        uint64_t c = atomic_load_explicit(&g_mdr_n[r], memory_order_relaxed); if (!c) continue;
        o += snprintf(out + o, n - (size_t)o, "%s %s %llu (%.1f MB)", any ? "," : "", mdr_name[r], (unsigned long long)c,
                      atomic_load_explicit(&g_mdr_bytes[r], memory_order_relaxed) / 1048576.0); any = 1;
    }
    if (!any) out[0] = 0;
}
// The mip drop line's last part: "; of those held now, through DM_NVN_MIP_DROP_COMPRESSIBLE N (M MB), through DM_NVN_MIP_DROP_PARTIAL N (M MB)", the switches that are on
static void md_ext_text(char *out, size_t n) {
    static const char *const sw[3] = {NULL, "DM_NVN_MIP_DROP_COMPRESSIBLE", "DM_NVN_MIP_DROP_PARTIAL"}; const int on[3] = {0, md_cflag_on(), md_partial_on()};
    int o = 0; out[0] = 0;
    for (int e = 1; e < 3 && o >= 0 && (size_t)o < n; e++) if (on[e])
        o += snprintf(out + o, n - (size_t)o, "%s through %s %llu (%llu MB)", o ? "," : "; of those held now,", sw[e], (unsigned long long)atomic_load(&g_md_ext_n[e]),
                      (unsigned long long)(atomic_load(&g_md_ext_bytes[e]) >> 20));
}
// The top levels t's host texture mt lacks: 0 for every texture md_pick did not shrink (its size is the game's)
static unsigned md_levels(const tex_t *t, id<MTLTexture> mt) {
    if (!mt || (t->d.target != NVN_TEXTURE_TARGET_2D && t->d.target != NVN_TEXTURE_TARGET_2D_ARRAY) || mt.width >= t->d.width || !fmt_compressed(t->d.format)) return 0;
    for (unsigned k = 1; k <= 2; k++) if (mt.width == (t->d.width >> k) && mt.height == (t->d.height >> k) && mt.mipmapLevelCount + k == t->d.levels) return k;
    return 0;
}
static void md_forget(uint64_t bytes, unsigned ext) {
    atomic_fetch_sub(&g_md_live_n, 1); atomic_fetch_sub(&g_md_live_bytes, bytes);
    if (ext) { atomic_fetch_sub(&g_md_ext_n[ext], 1); atomic_fetch_sub(&g_md_ext_bytes[ext], bytes); }
}
// After pk->tex was made: counts what it lacks (the memory line's mip drop figures)
static void md_note(NvPkg *pk, const tex_t *t) {
