    if (k) {
        atomic_fetch_add(&g_md_live_n, 1); atomic_fetch_add(&g_md_live_bytes, saved);
        if (ext) { atomic_fetch_add(&g_md_ext_n[ext], 1); atomic_fetch_add(&g_md_ext_bytes[ext], saved); }
        uint64_t u = atomic_fetch_add(&g_md_uploads, 1) + 1; atomic_fetch_add(&g_md_skip_bytes, saved);
        if (u <= 3) MLOG("mip drop: texture ser=%llu %ux%u%s format %#x levels %u made as %lux%lu with %lu levels (%llu KB less)", (unsigned long long)t->serial, t->d.width, t->d.height,
                         t->d.target == NVN_TEXTURE_TARGET_2D_ARRAY ? " array" : "", t->d.format, t->d.levels, (unsigned long)pk->tex.width, (unsigned long)pk->tex.height,
                         (unsigned long)pk->tex.mipmapLevelCount, (unsigned long long)(saved >> 10));
    }
    pk->md = (uint8_t)k; pk->md_saved = saved; pk->md_ext = (uint8_t)ext;
