        d.mipmapLevelCount = fit;
    }
    if (d.textureType == MTLTextureType2DMultisample || d.textureType == MTLTextureType2DMultisampleArray) {
        NSUInteger want = d.sampleCount, n = want;
        while (n > 1 && ![g_dev supportsTextureSampleCount:n]) n >>= 1;
        if (want < 2 || n < 2) {
            RED_ONCE(115, "multisample texture of %lu samples: this GPU has no such texture, not made (format %#x, first case ser=%llu)", (unsigned long)want, t->d.format, (unsigned long long)t->serial);
            return nil;
        }
        if (n != want) { d.sampleCount = n;
            static int nl; if (nl++ < 4) MLOG("[RED] multisample texture of %lu samples: this GPU has no such texture, made with %lu (%u×%u format %#x, ser=%llu); a shader reading sample %lu or higher reads undefined texels",
                                              (unsigned long)want, (unsigned long)n, t->d.width, t->d.height, t->d.format, (unsigned long long)t->serial, (unsigned long)n); }
    }
    d.storageMode = MTLStorageModePrivate;   // Render targets and assets both go in GPU private storage (lossless compression available)
    d.usage = MTLTextureUsageShaderRead | (fmt_compressed(t->d.format) || packaged ? 0 : MTLTextureUsageRenderTarget)
            | img_usage(t, d.pixelFormat) | pcm_usage(d, packaged);   // pcm_usage: DM_NVN_PCM's kernels write small colour targets. Image usage: shader-writable (compute kernels generating the 3D color lookup table, etc.
    // A depth-stencil texture has the format-view usage from the start: its stencil is read through an X32_Stencil8 view (stencil-mode views and textures, the depth-stencil copy), which Metal's
    // contract allows only with that usage. Apple GPUs read the view correctly without it, but the API validation layer aborts the process at the first such view (PR #106, found on Luigi's
    // Mansion 3), and upgrading later would recreate a depth buffer in use. Unlike colour formats it costs nothing measured: on an M4 Pro a 2560x1440 one has the same allocated size and the same
    // GPU time over eight load / store passes with and without it
    if (d.pixelFormat == MTLPixelFormatDepth32Float_Stencil8) d.usage |= MTLTextureUsagePixelFormatView;
    // An RGB9E5 render target has it from the start too: a game that packs its HDR colour itself writes the packed words through an R32UI view of it. Without the usage that view cannot
    // be attached (rt_view_fmt falls back to the base format, red line 68), the pass draws in RGB9E5 and the words are written as floats: the whole picture red. At attach time the only
    // way left would be tex_upgrade, which recreates a render target in use (reported by the S2Arm project). Packaged ones are never drawn into, so they keep lossless compression
    if (d.pixelFormat == MTLPixelFormatRGB9E5Float && !packaged) d.usage |= MTLTextureUsagePixelFormatView;
