}
typedef struct { uint64_t used_ns, overflow_ns, window_ns; size_t peak; } up_idle_slot;   // the slot's last batch, its last batch that used the overflow block, its interval's start and peak batch
static up_idle_slot g_up_idle_slot[UP_SLOTS_MAX];
static uint64_t g_up_idle_n, g_up_idle_bytes;   // blocks this trim let go, and their bytes, in total
typedef struct {
    __unsafe_unretained id<MTLBuffer> src;
    size_t off, row, image;
    MTLSize size;
    __unsafe_unretained id<MTLTexture> dst;   // Strongly referenced by g_up_texs until the flush is encoded
    NSUInteger slice, level;
    MTLOrigin at;   // where in the level (a sparse texture's tile, sparse_sync); 0 otherwise
    __unsafe_unretained id<MTLTexture> tsrc;   // non-nil: a copy of the same slice and level of this texture (the region at `at` of size; the level's whole for a kept image) instead of src; kept by g_up_views until the batch completes (pkg_upload_'s partial re-upload)
} up_blit;
static up_blit *g_up_blits; static int g_nup_blits, g_up_blitcap;
static NSMutableArray *g_up_texs, *g_up_views;   // Targets and temporary integer-write views kept through their upload
static id<MTLBuffer> g_up_block;
static size_t g_up_block_off, g_up_block_size;
static NSMutableArray *g_up_keep;
// Limit overflow staging per batch. The three upload slots bound in-flight
// batches; up_begin publishes queued commits before waiting for a slot. A single
// texture larger than the budget gets its own block (uploads are not tiled here).
static size_t g_up_staging_bytes;
#define UP_BATCH_BYTES (128u * 1024u * 1024u)
// The staging block pool (ported from S2Arm 01afd92a and 6e708d3e, Apache-2.0; not its upload-ahead list, tex_pre.tsv). A batch past its slot's two blocks takes temporary
// UP_BLOCK_SIZE private blocks (up_alloc), and the batch's completion retired them: out of the residency set and freed, and the next burst made and added them again. S2Arm
// measured a menu entry uploading about 900 MB: the residency commit took 418 of the 755 ms frame, and with the pool the worst frame went from 630 ms to 251-272 ms. Now a
// retired temporary block stays resident in this pool (up_pool_put, in the batch's feedback handler, so the GPU is done with it) and the next one up_alloc needs comes from it
// (up_pool_get) with no allocation and no residency change. Only UP_BLOCK_SIZE private blocks: the slot and overflow blocks (g_up_slot_blk, g_up_slot_over), the slots' 64 KB
// parameter blocks (g_up_slot_pblk, shared) and the zero-copy sources keep their own lifetimes. The pool holds up to DM_NVN_STAGE_POOL_MB (default 128 on iOS, 512 on the Mac;
// 0 off, as before). It goes whole, out of the residency set (up_pool_release): 5 s after its last use (up_pool_trim, at a submission's start), at once when the headroom to
// the memory limit (g_rh_avail; none on the Mac) is under 1 GB, at a memory trim (mtl_trim_at: pressure, the background) and going to the background (mtl_bg_purge). A block
// is not kept while the headroom is under its size + 1 GB. A headroom of 0 (no limit known: the Simulator) limits nothing, as rh_cap
#define UP_POOL_MARGIN (1ull << 30)
#define UP_POOL_IDLE_NS 5000000000ull
#if TARGET_OS_IPHONE
#define UP_POOL_MB_DEF 128
#else
#define UP_POOL_MB_DEF 512
#endif
static NSMutableArray *g_up_pool; static os_unfair_lock g_up_pool_lk = OS_UNFAIR_LOCK_INIT;
static NSMutableSet *g_up_pool_vol;   // the pooled blocks marked volatile (DM_NVN_CACHE_VOLATILE, up_pool_trim); under g_up_pool_lk
static uint64_t g_up_pool_bytes, g_up_pool_used_ns, g_up_pool_hits, g_up_pool_puts, g_up_pool_skip_bytes, g_up_pool_freed;   // under g_up_pool_lk
static int64_t g_up_pool_cap = -1;   // bytes; -1 not read yet (a test sets it)
static uint64_t up_pool_cap(void) {
    if (g_up_pool_cap < 0) {
        const char *e = getenv("DM_NVN_STAGE_POOL_MB"); char *end = NULL; long long mb = e && *e ? strtoll(e, &end, 10) : UP_POOL_MB_DEF;
        if (e && *e && (*end || mb < 0 || mb > (1ll << 20))) mb = UP_POOL_MB_DEF;
        if (e && *e) MLOG("upload staging pool: %lld MB (DM_NVN_STAGE_POOL_MB%s)", mb, mb ? "" : "=0: temporary staging blocks are freed after each batch, as before");
        g_up_pool_cap = (int64_t)mb << 20;
    }
    return (uint64_t)g_up_pool_cap;
}
static int up_pool_low(uint64_t extra) { uint64_t a = g_rh_avail ? g_rh_avail() : 0; return a && a < extra + UP_POOL_MARGIN; }   // the headroom is under extra + 1 GB
static int up_pool_put(id<MTLBuffer> b) {   // the batch's feedback handler (the GPU is done with b): 1 kept, still resident; 0 the caller retires it
    if (!up_pool_cap() || ![(id)b conformsToProtocol:@protocol(MTLBuffer)] || b.length != UP_BLOCK_SIZE || b.storageMode != MTLStorageModePrivate) return 0;
    int low = up_pool_low(b.length);
    os_unfair_lock_lock(&g_up_pool_lk);
    int ok = !low && g_up_pool_bytes + b.length <= up_pool_cap();
    if (ok) { if (!g_up_pool) g_up_pool = [NSMutableArray array]; [g_up_pool addObject:b]; g_up_pool_bytes += b.length; g_up_pool_puts++; g_up_pool_used_ns = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); }
    else if (low) g_up_pool_skip_bytes += b.length;
    os_unfair_lock_unlock(&g_up_pool_lk);
    return ok;
}
static id<MTLBuffer> up_pool_get(void) {   // submit thread (up_alloc): an idle resident UP_BLOCK_SIZE block, or nil
    if (!up_pool_cap()) return nil;
    for (;;) {
        id<MTLBuffer> b = nil; int vol = 0;
        os_unfair_lock_lock(&g_up_pool_lk);
        if (g_up_pool.count) { b = g_up_pool.lastObject; [g_up_pool removeLastObject]; g_up_pool_bytes -= b.length; g_up_pool_hits++;
            if (g_up_pool_vol.count && [g_up_pool_vol containsObject:b]) { vol = 1; [g_up_pool_vol removeObject:b]; } }
        g_up_pool_used_ns = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
        os_unfair_lock_unlock(&g_up_pool_lk);
        // marked volatile while it waited: non-volatile again before the batch writes it; one the system emptied leaves the set and the next is tried (none left: up_alloc makes one)
        if (!b || !vol || !cv_back(b, b.length)) return b;
        res_remove(b);
    }
}
// Every pooled block out of the residency set (queued: the caller commits; each stays alive until that commit). Returns the bytes, *nout the blocks
static uint64_t up_pool_release(int *nout) { @autoreleasepool {
    os_unfair_lock_lock(&g_up_pool_lk);
    NSArray *drop = g_up_pool.count ? [g_up_pool copy] : nil; uint64_t bytes = drop ? g_up_pool_bytes : 0;
    for (id<MTLBuffer> b in g_up_pool_vol) cv_gone(b.length);   // freed volatile: nothing to take back
    [g_up_pool removeAllObjects]; [g_up_pool_vol removeAllObjects]; g_up_pool_bytes = 0; g_up_pool_freed += drop.count;
    os_unfair_lock_unlock(&g_up_pool_lk);
    for (id<MTLBuffer> b in drop) res_remove(b);
    *nout = (int)drop.count; return bytes;
} }
static uint64_t g_up_pool_hr_at;   // when up_pool_trim last read the headroom (submit thread): at most every RH_CAP_EVERY_NS while the pool holds blocks
static void up_pool_trim(void) {   // a submission's start (up_trim): 5 s unused, or the headroom under 1 GB
    os_unfair_lock_lock(&g_up_pool_lk); uint64_t held = g_up_pool_bytes, used = g_up_pool_used_ns; os_unfair_lock_unlock(&g_up_pool_lk);
    if (!held) return;
    uint64_t now = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    int idle = now - used >= UP_POOL_IDLE_NS, low = 0;
    if (!idle && g_rh_avail && (!g_up_pool_hr_at || now - g_up_pool_hr_at >= RH_CAP_EVERY_NS)) { g_up_pool_hr_at = now; low = up_pool_low(0); }
    if (!idle && !low) {
        // unused for CV_IDLE_NS: the pooled blocks go volatile (DM_NVN_CACHE_VOLATILE). Each was put by its batch's feedback handler (the GPU is done with it) and is written whole by
        // the next batch that takes it (up_pool_get takes it back first). Under the lock, so a block is never taken between the look and the mark
        if (now - used >= CV_IDLE_NS && cv_on()) {
            os_unfair_lock_lock(&g_up_pool_lk);
            if (g_up_pool_used_ns == used && g_up_pool.count != g_up_pool_vol.count) {
                if (!g_up_pool_vol) g_up_pool_vol = [NSMutableSet set];
                for (id<MTLBuffer> b in g_up_pool) if (![g_up_pool_vol containsObject:b] && cv_mark(b, b.length)) [g_up_pool_vol addObject:b];
            }
            os_unfair_lock_unlock(&g_up_pool_lk);
        }
        return;
    }
    int n; uint64_t bytes = up_pool_release(&n);
    if (!n) return;
    res_commit_soon(0, 0);   // nothing reads them: the worker commits the removals (DM_NVN_RES_ASYNC), or this thread does
    MLOG("upload staging pool: %d blocks, %llu MB, released (%s); %llu taken from the pool, %llu returned to it, %llu MB not kept for low memory headroom, so far", n, (unsigned long long)(bytes >> 20),
         idle ? "5 s unused" : "memory headroom under 1 GB", (unsigned long long)g_up_pool_hits, (unsigned long long)g_up_pool_puts, (unsigned long long)(g_up_pool_skip_bytes >> 20));
}


// The upload command buffer was discarded by the system (dropped along during GPU error recovery; the first frame on entering Travincal drops one every run): the objects of this batch of textures are built and the timestamps updated, but the content was never written in,
// and if the pool memory on the game side no longer changes it will never be re-uploaded. Record this batch of target textures, and the next time any of them is fetched treat it as dirty and re-upload once.
// DM_TEST_UP_LOST=<batch index> (for testing): treat that batch of uploads as dropped, to verify the re-upload path.
static NSHashTable *g_up_lost; static os_unfair_lock g_up_lost_lk = OS_UNFAIR_LOCK_INIT; static _Atomic int g_up_lost_n; static _Atomic uint64_t g_up_lost_redo;   // Weak-reference table: if a texture in the record is never fetched again and is released normally, this table does not keep it alive
static int up_lost_take(id tex) {   // This texture's upload was dropped: take it out of the record and return 1
    if (!tex) return 0; os_unfair_lock_lock(&g_up_lost_lk); int hit = [g_up_lost containsObject:tex]; if (hit) { [g_up_lost removeObject:tex]; atomic_store(&g_up_lost_n, (int)g_up_lost.allObjects.count); atomic_fetch_add(&g_up_lost_redo, 1); } os_unfair_lock_unlock(&g_up_lost_lk); return hit;
}
static void up_lost_add(NSArray *dsts) {   // a dropped batch's targets (its feedback handler; unit tests)
    os_unfair_lock_lock(&g_up_lost_lk); if (!g_up_lost) g_up_lost = [NSHashTable weakObjectsHashTable]; for (id d in dsts) [g_up_lost addObject:d]; atomic_store(&g_up_lost_n, (int)g_up_lost.allObjects.count); os_unfair_lock_unlock(&g_up_lost_lk);
}
// Whether this texture's last upload was dropped, and taking it out of the record once an upload rewrites it whole (pkg_upload_): g_up_lost_n is only an upper bound (a texture in the weak table that
// is freed leaves it as it was), so it is counted again here while it is not 0; a 0 means the record is empty
static int up_lost_has(id tex) {
    if (!tex || !atomic_load_explicit(&g_up_lost_n, memory_order_relaxed)) return 0;
    os_unfair_lock_lock(&g_up_lost_lk); int hit = [g_up_lost containsObject:tex]; atomic_store(&g_up_lost_n, (int)g_up_lost.allObjects.count); os_unfair_lock_unlock(&g_up_lost_lk); return hit;
}
static void up_lost_drop(id tex) {
    if (!tex || !atomic_load_explicit(&g_up_lost_n, memory_order_relaxed)) return;
    os_unfair_lock_lock(&g_up_lost_lk); [g_up_lost removeObject:tex]; atomic_store(&g_up_lost_n, (int)g_up_lost.allObjects.count); os_unfair_lock_unlock(&g_up_lost_lk);
}
// Which upload batches have come back: per slot, the number (g_up_seq) of the last batch whose feedback handler has run, stored after that handler has put a dropped batch's targets in g_up_lost.
// A slot's batches come back in order (up_begin waits for the slot's last one), so batch s has come back once its slot holds s or more. A partial re-upload builds only on a texture whose last
// upload batch has come back and was not dropped (pkg_upload_): one copied from a texture whose batch was still running, and then dropped, kept that batch's unwritten texels for good
static _Atomic unsigned g_up_slot_back[UP_SLOTS_MAX];
static unsigned g_pkg_seq;   // the batch pkg_upload_ wrote its last texture in (submit thread)
static uint64_t g_pkg_pnow;   // the dirty clock after pkg_upload_'s last protect of a texture's pages, 0 with none (NvPkg pnow)
static int up_seq_back(unsigned s) { return s && atomic_load_explicit(&g_up_slot_back[(s - 1) % g_up_nslots], memory_order_acquire) >= s; }   // 0: not known to come from an upload batch
static void up_diag(void);
static void up_flush(void) {
    up_owner_check("up_flush");
    if (!g_up_cb) return;
    if (g_up_ce) {
        m4_end(g_up_ce); g_up_ce = nil;
    }
    id<MTL4ComputeCommandEncoder> b = g_nup_blits ? g_up_ce = [g_up_cb computeCommandEncoder] : nil;
    if (b) [b barrierAfterQueueStages:MTLStageAll beforeStages:hb_compute() visibilityOptions:resource_vis()];
    for (int i = 0; b && i < g_nup_blits; i++) {
        up_blit *x = &g_up_blits[i];
        if (x->tsrc) enc_b_copy_texture(b, x->tsrc, x->slice, x->level, x->at, x->size, x->dst, x->slice, x->level, x->at);
        else enc_b_copy_buffer_texture(b, x->src, x->off, x->row, x->image, x->size, x->dst, x->slice, x->level, x->at);
    }
    if (b) { m4_end(b); g_up_ce = nil; }
    id<MTL4CommandBuffer> cb = g_up_cb;
    unsigned seq = g_up_seq, slot = (seq - 1) % g_up_nslots;
    // Only this upload batch uses its overflow staging. Retire it on upload
    // completion, even when the main rendering submission is still being built.
    NSMutableArray *staging = g_up_keep;
    if (g_up_block && !up_retained(g_up_block, slot)) [staging addObject:g_up_block];
    if (g_up_pblock && g_up_pblock != g_up_slot_pblk[slot]) [staging addObject:g_up_pblock];   // a parameter block filled within this batch (the slot's own stays)
    g_up_pblock = nil; g_up_pblock_off = 0;   // the next batch starts on its slot's parameter block
    NSMutableArray *views = g_up_views; g_up_views = nil;
    g_up_keep = nil; g_up_block = nil;
    g_up_block_off = g_up_block_size = g_up_staging_bytes = 0;
    NSMutableSet *targets = [NSMutableSet setWithArray:g_up_texs]; for (int i = 0; i < g_nup_blits; i++) if (g_up_blits[i].dst) [targets addObject:g_up_blits[i].dst];
    NSArray *dsts = targets.allObjects;
    static int lost_at = -2; static uint64_t batch_n; if (lost_at == -2) { const char *e = getenv("DM_TEST_UP_LOST"); lost_at = e ? atoi(e) : -1; } int fake_lost = dsts.count && lost_at > 0 && (int)++batch_n == lost_at;
    MTL4CommitOptions *o = [MTL4CommitOptions new];
    atomic_fetch_add(&g_up_pending, 1);
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> f) {
        fb_in("upload batch");
        if (f.error) { MLOG("[RED] upload command buffer execution error: %s", f.error.description.UTF8String); res_top_once(f.error); victim_note(f.error, "upload batch", 0); gpu_lost_check(f.error, "upload"); }
        if (f.error || fake_lost) {
            up_lost_add(dsts); int n = atomic_load(&g_up_lost_n);
            smu_lock(); g_ser_gen++; pthread_mutex_unlock(&g_smu);   // Make the view cache of every texture ID take the slow path once (on a cache hit tex_mtl is not passed through and this record is not seen)
            MLOG("%supload command buffer dropped: the %lu textures of this batch are marked unwritten and re-uploaded on next use (%d awaiting re-upload)", fake_lost ? "DM_TEST_UP_LOST: " : "", (unsigned long)dsts.count, n);
        }
        up_gpu_note(seq, f.GPUStartTime, f.GPUEndTime); gpu_busy_note(f.GPUStartTime, f.GPUEndTime);
        int retire = 0;
        @autoreleasepool {
            for (id<MTLResource> obj in staging) if (!up_pool_put((id<MTLBuffer>)obj)) { res_remove(obj); retire = 1; }   // a temporary block kept in the pool stays resident (up_pool_put)
            [staging removeAllObjects];
            [views removeAllObjects];   // upload-only integer views share their targets' residency
        }
        atomic_store_explicit(&g_up_slot_back[slot], seq, memory_order_release);   // after a drop's g_up_lost entries (up_seq_back)
        atomic_store(&g_up_alloc_busy[slot], 0);   // the slot's command buffer and allocator are free: its retained blocks never leave the set
        // The staging's removal is committed on the residency commit worker, not here (res_commit_async); the batch stays pending until it is. One with nothing to retire (its
        // slot's blocks only, the usual case) is done now, as before
        if (retire) res_commit_async(^{ atomic_fetch_sub(&g_up_pending, 1); up_wake(); });
        else atomic_fetch_sub(&g_up_pending, 1);
        up_wake();
        fb_out();
    }];
    res_commit_soon(1, 0);   // as cb_commit's: before the batch's queue commit
    [cb endCommandBuffer];
    rec_commit_upload(cb, o);
    // Outside a submission nothing else hands the encode thread its current block until the next submission, so a batch flushed on the spot stayed a record and every wait for it
    // (nvnQueueFinish on any thread, up_begin on another) waited for that submission: hand it over now (from PR #141, which found the nvnQueueFinish half)
    if (!g_cb) rec_publish();
    if (up_reuse()) g_up_slot_want[slot] = MAX(g_up_slot_want[slot], g_up_batch_bytes);
    if (g_up_batch_bytes > UP_SLOT_BLOCK) g_up_slot_big_at[slot] = g_sub_serial;   // up_trim's idle counts
    if (g_up_over_used) g_up_slot_over_at[slot] = g_sub_serial;
    if (g_up_batch_bytes && up_idle_period()) {   // up_idle_release's clocks
        up_idle_slot *age = &g_up_idle_slot[slot];
        age->used_ns = clock_gettime_nsec_np(CLOCK_MONOTONIC);
        if (g_up_over_used) age->overflow_ns = age->used_ns;
        if (!age->window_ns) age->window_ns = age->used_ns;
        age->peak = MAX(age->peak, g_up_batch_bytes);
    }
    g_up_cb = nil;
    up_diag();
    g_nup_blits = 0;
    [g_up_texs removeAllObjects];
}

static void up_begin(void) {
    up_owner_check("up_begin");
    if (g_up_cb) return;
    unsigned slot = g_up_seq++ % g_up_nslots;
    // The slot's last batch may still be only a commit record in the encode thread's current block (rec_commit_upload), which is handed over when it fills or the submission drains:
    // waiting without handing it over waited for a batch never committed. Little Nightmares II's first render passes zero-filled enough new targets to come round to a slot within one
    // block, and its RHI thread waited for good inside nvnQueueSubmitCommands (the removed classic queue's command buffers drained before they waited for the same reason)
    if (atomic_load(&g_up_alloc_busy[slot])) rec_publish();
    up_wait_zero(&g_up_alloc_busy[slot], WS_UPALLOC);
    atomic_store(&g_up_alloc_busy[slot], 1); g_up_cur_slot = slot;
    g_up_batch_bytes = g_up_src_bytes = 0; g_up_over_used = 0;
    [g_up_alloc4[slot] reset];
    g_up_cb = [g_dev newCommandBuffer];
    [g_up_cb beginCommandBufferWithAllocator:g_up_alloc4[slot]];
    g_up_ce = [g_up_cb computeCommandEncoder];
    [g_up_ce barrierAfterQueueStages:MTLStageAll beforeStages:hb_compute() visibilityOptions:resource_vis()];
    [g_up_ce setArgumentTable:g_up_ct];
    if (!g_up_texs) g_up_texs = [NSMutableArray array];
    if (!g_up_keep) g_up_keep = [NSMutableArray array];
}

// The upload-only unwire (DM_NVN_UNWIRE_UP; its state at pool_res_mark). An upload whose staging flushed the batch the lookup was made in reads the pool's buffer in batch seq too
// (pkg_upload_): the pool's note is raised to it. The entry is the one whose buffer the upload reads (mb, from mtl_addr's length-aware lookup), not whichever entry holds addr: with
// overlapping pools, or g_plast moved by another thread, pool_held(addr, 1) could name another entry, raise its note and leave the read pool's at the flushed batch, and the sweep could
// then take the read pool out while the new batch still reads it. No chunk is made, and a large pool is not the sweep's
static int pool_of_buf(uint64_t addr, uint64_t len, const void *mb) {   // caller holds g_mu
    int i = pool_held(addr, len);
    if (i >= 0 && (__bridge const void *)g_pools[i].buf == mb) return i;
    for (i = 0; i < g_npool; i++) if ((__bridge const void *)g_pools[i].buf == mb) return i;
    return -1;
}
static void pool_up_note(uint64_t addr, uint64_t len, const void *mb, unsigned seq) {
    mu_lock();
    if (big_of(addr) < 0) { int i = pool_of_buf(addr, len, mb); if (i >= 0 && g_pools[i].up_seq < seq) g_pools[i].up_seq = seq; }
    pthread_mutex_unlock(&g_mu);
}
// The highest upload batch W such that every batch up to W has run its feedback handler (submit thread). Batch s goes in slot (s - 1) % g_up_nslots, and a slot's batches come back
// in order (up_begin waits for the slot's last one), so a slot that has seen batch b back has batch b + g_up_nslots next, and one that has seen none has its first, slot + 1. The
// first such batch that has been opened (≤ g_up_seq) is not back, and W stays below it; the open batch, not flushed yet, is one of them
static unsigned up_back_floor(void) {
    unsigned w = g_up_seq;
    for (unsigned j = 0; j < g_up_nslots; j++) {
        unsigned b = atomic_load_explicit(&g_up_slot_back[j], memory_order_acquire), first_out = b ? b + g_up_nslots : j + 1;
        if (first_out <= g_up_seq && first_out - 1 < w) w = first_out - 1;
    }
    return w;
}
// The sweep: at a submission's start, before any lookup of it (mtl_sub_begin, after up_trim; and at a memory trim, idle_rule 0), pools only texture uploads have read leave the
// residency set, so their file pages are no longer wired and the kernel may drop them. A pool goes only when
// - it is resident, uploads have read it and nothing else has looked it up (n_other: every other use is counted, a per-thread cache entry comes only from one, pc_put), and it is
//   no large pool's (its chunks and whole buffer: big_of) and not sticky (three quick re-adds);
// - no raw pool table can name it: not addressed (addr_meets). An addressed pool stays even while no table has been built: the first table (gmem_map_at) puts every addressed pool
//   back, and with the sweep taking them out before it, a game whose first raw global memory shader comes minutes in paid one page-in and prewire of all of them in front of that
//   draw's queue commit. One addressed only after the sweep took it out is put back by the next table, alone;
// - every upload batch that reads it has come back (up_seq ≤ up_back_floor), so no GPU work in flight or held uses it: main command buffers never had it (no other lookup, no table),
//   and nothing encoded later can, as every later use looks it up again (pool_res: the lookups' residency rule) or builds the table again (gmem_map_at), and the sweep bumps
//   g_pool_gen, which empties every thread's cache (pc_get) and the pool table memo;
// - uploads have not looked it up for 3 s (idle_rule), its hold after a quick re-add has passed (pool_res_mark), and the submission being encoded stores into none of it (gsb_held).
// At most 256 pools or 512 MB a sweep, and one sweep every 500 ms (the trim's is not held back by the clock). Pages are never discarded, unlocked by hand, punched or unmapped:
// leaving the set is all, and the pages, clean file pages or dirty ones, keep their content. =m counts what would go and changes nothing
enum { UNW_EVERY_NS = 500000000, UNW_IDLE_NS = 3000000000u, UNW_MAX_POOLS = 256 }; static const uint64_t UNW_MAX_BYTES = 512ull << 20;
static void up_unwire_sweep(int idle_rule) {
    if (g_unw_mode < 0) return;   // before unw_init (mtl_init)
    int on = g_unw_mode && sw_on(g_unw_mode);
    if (!on && !g_unw_measure) return;
    uint64_t now = unw_now(), t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW);
    if (idle_rule && !g_unw_stress) { if (g_unw_last_at && now - g_unw_last_at < UNW_EVERY_NS) return; }
    g_unw_last_at = now;
    if (g_unw_stress) idle_rule = 0;
    unsigned w = up_back_floor();
    int n = 0; uint64_t bytes = 0;
    mu_lock();
    for (int i = 0; i < g_npool && (!on || (n < UNW_MAX_POOLS && bytes < UNW_MAX_BYTES)); i++) {   // =m counts them all
        pool_ent *p = &g_pools[i];
        if (!p->res || !p->n_tex_reads || p->n_other || p->sticky || p->reach == REACH_WHOLE) continue;
        if (p->up_seq > w || now < p->ev_hold || (idle_rule && now - p->up_ns < UNW_IDLE_NS)) continue;
        if (g_nbig && big_of(p->lo) >= 0) continue;
        if (addr_meets(p->lo, p->hi)) continue;   // addressed: a raw table, now or later, may name it
        if (gsb_held((const void *)p->lo, p->hi - p->lo)) continue;
        uint64_t z = p->buf.length;
        n++; bytes += z;
        if (!on) continue;
        res_remove(p->buf);   // g_res_mu inside g_mu, as pool_res
        p->res = 0; p->ev = 1; p->ev_at = now; g_pool_res_n--;
        g_unw_n++; g_unw_b += z;
    }
    if (!on) { g_unw_would_n = (uint64_t)n; g_unw_would_b = bytes; }   // =m: what the last sweep would have taken out
    if (on && n) {
        g_plast = -1;
        atomic_store(&g_pool_drop_gen, atomic_fetch_add(&g_pool_gen, 1) + 1);   // every thread's cache and the memos go, and the raw table is not kept (defence in depth: none names these pools)
    }
    g_unw_sweeps++; g_unw_sweep_ns += clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - t0;
    pthread_mutex_unlock(&g_mu);
    if (on && n) {
        args_dirty_all_w(AW_REG_POOL);
        res_commit_soon(0, 0);   // the removal leaves the committed set (the worker on the replay thread with DM_NVN_RES_ASYNC), and with it the wiring
    }
}
static void unw_init(void) {
    const char *e = getenv("DM_NVN_UNWIRE_UP");
    g_unw_measure = 0;
    if (!e || !*e || !strcmp(e, "m")) { g_unw_measure = 1; g_unw_mode = 0; }   // m is the default until the byte-exact replays of game captures have passed (env_switches.tsv)
    else g_unw_mode = sw_mode("DM_NVN_UNWIRE_UP", 0);
    if (g_unw_mode != 1) MLOG("DM_NVN_UNWIRE_UP=%s: %s", e && *e ? e : "m (default)", g_unw_measure ? "pools only texture uploads read are counted as they would leave the residency set; nothing changes"
                                    : g_unw_mode ? "pools only texture uploads read leave the residency set once their batches are back, in the A/B phases it is on in" : "pools only texture uploads read stay in the residency set, as before");
}
// The 10 s line (mtl_unwire_report, called beside the guest file's line): what left and came back, and the resident pools by class (pool_res_classes)
// The resident pools by class, exactly (n_tex_reads / n_other count every lookup, mtl_addr): U1 only uploads read it and no raw pool table can name it (not addressed: the sweep's),
// U2 only uploads read it and a raw table, built or to come, keeps it (addressed), split by how its address was given (ak: its own address or a virtual pool's
// mapping, buffers only, textures only, both or not known), U3 anything else read it; EV the sweep took it out and it is out now. Each with its count, MB and the MB of it in
// file pages (fwire_range). For the 10 s line, and for the idle-texture cap's line (claude/x2-cap2's tidle_line) once merged
void pool_res_classes(char *out, size_t on) {
    enum { U1, U2, U3, EV, NC }; uint64_t c[NC] = {0}, b[NC] = {0}, f[NC] = {0}, ak[4] = {0};   // ak: U2's MB by POOL, BUF only, TEX only, other
    typedef struct { uintptr_t lo; size_t n; int k; } cls_ent; cls_ent *v = NULL; int nv = 0;
    mu_lock();
    if (g_npool) v = malloc((size_t)g_npool * sizeof *v);
    for (int i = 0; v && i < g_npool; i++) {
        pool_ent *p = &g_pools[i]; int k;
        if (p->ev) k = EV; else if (!p->res) continue;
        else if (!p->n_tex_reads || p->n_other) k = U3;
        else k = addr_meets(p->lo, p->hi) ? U2 : U1;
        uint64_t z = p->buf.length;
        c[k]++; b[k] += z;
        if (k == U2) ak[(p->ak & AK_POOL) ? 0 : p->ak == AK_BUF ? 1 : p->ak == AK_TEX ? 2 : 3] += z;
        v[nv++] = (cls_ent){p->base, (size_t)z, k};
    }
    pthread_mutex_unlock(&g_mu);
    // Which of them are file pages, after g_mu: the guest's layout answers at once, a range outside it asks the kernel (fwire_kernel, about 1 us), which must not hold every lookup
    uintptr_t pg = (uintptr_t)getpagesize();
    for (int i = 0; i < nv; i++) {
        uintptr_t lo = v[i].lo & ~(pg - 1), hi = (v[i].lo + v[i].n + pg - 1) & ~(pg - 1);
        int fb = g_fwire_backed_hook ? g_fwire_backed_hook((const void *)lo, hi - lo) : dm_guest_file_backed((const void *)lo, hi - lo);
        if (fb < 0) fb = fwire_kernel(lo, hi);
        if (fb) f[v[i].k] += hi - lo;
    }
    free(v);
    #define CM(x) (unsigned long long)((x) >> 20)
    snprintf(out, on, "resident pools: only uploads read, no raw table names (U1) %llu / %llu MB (file %llu MB); only uploads read, kept by the raw table (U2) %llu / %llu MB (file %llu MB; POOL %llu MB BUF %llu MB TEX %llu MB other %llu MB); "
             "other uses (U3) %llu / %llu MB (file %llu MB); unwired now (EV) %llu / %llu MB (file %llu MB)",
             (unsigned long long)c[U1], CM(b[U1]), CM(f[U1]), (unsigned long long)c[U2], CM(b[U2]), CM(f[U2]), CM(ak[0]), CM(ak[1]), CM(ak[2]), CM(ak[3]),
             (unsigned long long)c[U3], CM(b[U3]), CM(f[U3]), (unsigned long long)c[EV], CM(b[EV]), CM(f[EV]));
    #undef CM
}
static uint64_t g_unw_reports;   // 10 s lines written (the test's)
void mtl_unwire_report(void) {
    if (g_unw_mode < 0 || (!g_unw_mode && !g_unw_measure)) return;   // before unw_init, or =0: off, no line and no walk of the pools, as before
    static uint64_t last_n, last_b;
    uint64_t out_n = 0, out_b = 0;
    mu_lock();
    for (int i = 0; i < g_npool; i++) if (g_pools[i].ev) { out_n++; out_b += g_pools[i].buf.length; }
    uint64_t un = g_unw_n, ub = g_unw_b, wn = g_unw_would_n, wb = g_unw_would_b, r0 = g_unw_re[0], r1 = g_unw_re[1], r2 = g_unw_re[2], st = g_unw_sticky, sn = g_unw_src_n, sb = g_unw_src_b, sw = g_unw_sweeps, swn = g_unw_sweep_ns;
    pthread_mutex_unlock(&g_mu);
    char cls[600]; pool_res_classes(cls, sizeof cls);
    const char *mode = g_unw_measure ? "m" : g_unw_mode == 1 ? "1" : g_unw_mode ? "ab" : "0";
    MLOG("[mem] upload-only unwire (DM_NVN_UNWIRE_UP=%s): unwired %llu pools / %llu MB this period (%llu / %llu MB total, now out %llu / %llu MB), would unwire (m, last sweep) %llu / %llu MB; re-added: upload fallback %llu, other use %llu, raw table %llu; sticky %llu; %s; uploads read through a batch buffer after unwire %llu / %llu MB; sweep %llu us (%llu sweeps)",
         mode, (unsigned long long)(un - last_n), (unsigned long long)((ub - last_b) >> 20), (unsigned long long)un, (unsigned long long)(ub >> 20), (unsigned long long)out_n, (unsigned long long)(out_b >> 20),
         (unsigned long long)wn, (unsigned long long)(wb >> 20), (unsigned long long)r0, (unsigned long long)r1, (unsigned long long)r2, (unsigned long long)st, cls,
         (unsigned long long)sn, (unsigned long long)(sb >> 20), (unsigned long long)(sw ? swn / sw / 1000 : 0), (unsigned long long)sw);
    last_n = un; last_b = ub; g_unw_reports++;
}
// Diagnostic readout (low frequency; printed only when the block switch count changed and ≥ 1 second since the last line, at most 200 lines per game): how many times an upload batch ran out of staging block and switched blocks midway; GPU allocated, residency set object count, deferred-release queue length.
// If the old block is not retired on a switch it stays in the residency set and can never be freed, and "GPU allocated" climbs one block at a time with the switch count
static uint64_t g_up_blocks_new, g_up_swaps, g_up_swap_bytes; static NSHashTable *g_up_old;   // g_up_old: old blocks switched out (weak references); the diagnostic line counts how many are still alive
static void up_diag(void) { @autoreleasepool {
    // Weak-table enumeration autoreleases the buffers it finds. Do not keep
    // completed batches alive until the whole rendering submission ends.
    // Print a line when the block switch count changes; then one more line 5 seconds later (that batch's commit is long done and deferred retirement drained, so "GPU allocated" is the settled number)
    static uint64_t said_swaps = ~0ull, last_ns; static int lines, follow; uint64_t now = clock_gettime_nsec_np(CLOCK_MONOTONIC);
    int chg = g_up_swaps != said_swaps, fol = follow && now - last_ns >= 5000000000ull; if ((!chg && !fol) || lines >= 200) return;
    if (chg && last_ns && now - last_ns < 1000000000ull) return; last_ns = now; said_swaps = g_up_swaps; lines++; follow = chg;
    unsigned long alive = 0, inres = 0; uint64_t abytes = 0; NSArray *olds = g_up_old.allObjects;
    res_mu_lock(); unsigned long nres = (unsigned long)g_res_objects.allObjects.count; for (id<MTLBuffer> o in olds) { alive++; abytes += o.length; inres += [g_res_objects containsObject:o]; } res_mu_unlock();
    pthread_mutex_lock(&g_deferred_mu); unsigned long ndef = (unsigned long)g_deferred.count; pthread_mutex_unlock(&g_deferred_mu);
    os_unfair_lock_lock(&g_up_pool_lk); uint64_t pool = g_up_pool_bytes; os_unfair_lock_unlock(&g_up_pool_lk);
    MLOG("upload staging blocks%s: %llu created in total, swapped within a batch %llu times (%llu MB of old blocks swapped out); swapped-out blocks still alive now %lu, %llu MB, still in the residency set %lu (in the staging pool %llu MB, kept for reuse); GPU allocated %llu MB, residency set %lu objects, deferred-release queue %lu", fol && !chg ? " (settled)" : "",
         (unsigned long long)g_up_blocks_new, (unsigned long long)g_up_swaps, (unsigned long long)(g_up_swap_bytes >> 20), alive, (unsigned long long)(abytes >> 20), inres, (unsigned long long)(pool >> 20), (unsigned long long)(g_dev.currentAllocatedSize >> 20), nres, ndef);
} }
static id<MTLBuffer> up_alloc(size_t n, size_t *off) {
    size_t need = (n + 255u) & ~((size_t)255u);
    size_t extra = MAX(need, UP_BLOCK_SIZE);
    // This call starts one texture's upload: all prior deswizzles and copies are
    // complete records, so the batch can be split without ending the render pass.
    if (g_up_staging_bytes && (!g_up_block || need > g_up_block_size - g_up_block_off)
        && extra > UP_BATCH_BYTES - MIN(g_up_staging_bytes, UP_BATCH_BYTES)) {
        up_flush();
        up_begin();
    }
    g_up_batch_bytes += MIN(need, UP_BLOCK_SIZE - g_up_batch_bytes);   // demand saturates at one retained block
    if (!g_up_block && need <= UP_BLOCK_SIZE) {   // first allocation of the batch: the slot's own block, grown to the next power of two that holds it (a movie frame re-uploaded every frame, 8 MB in Link's Awakening)
        __strong id<MTLBuffer> *sb = &g_up_slot_blk[g_up_cur_slot];
        size_t demand = up_reuse() ? MAX(need, g_up_slot_want[g_up_cur_slot]) : need;
        size_t want = up_slot_block_size(demand);
        if (*sb && (*sb).length < want) { defer_obj_release(*sb); *sb = nil; }   // the slot's previous batch has finished (up_begin waited for it)
        if (!*sb) { *sb = [g_dev newBufferWithLength:want options:MTLResourceStorageModePrivate]; if (!*sb) MDIE("failed to create the swizzled-upload staging block %#zx", want); res_add(*sb); g_up_blocks_new++; }
        g_up_block = *sb; g_up_block_size = (*sb).length; g_up_block_off = 0;
        g_up_staging_bytes += (*sb).length;
    }
    if (!g_up_block || g_up_block_off + need > g_up_block_size) {
        // Block switch: the old block is still referenced by copy / decompress commands already recorded in this batch and cannot be freed on the spot; hand it to g_up_keep, to be retired later with the other staging after the flush commits (removed from the residency set on retire).
        // Previously g_up_block was simply replaced with the new block here: nobody retired the old block, yet it stayed in the residency set, so each extra block switch in an upload batch leaked one block (usually 32 MB) of GPU memory.
        // The old block and the "current block" retired at flush are two objects, so nothing is retired twice
        if (g_up_block) { g_up_swaps++; g_up_swap_bytes += g_up_block_size; if (!up_retained(g_up_block, g_up_cur_slot)) { @autoreleasepool { if (!g_up_old) g_up_old = [NSHashTable weakObjectsHashTable]; [g_up_old addObject:g_up_block]; } }
            if (!up_retained(g_up_block, g_up_cur_slot)) { if (!g_up_keep) g_up_keep = [NSMutableArray array]; [g_up_keep addObject:g_up_block]; } }
        if (up_reuse() && need <= UP_BLOCK_SIZE && !g_up_over_used) {
            __strong id<MTLBuffer> *sb = &g_up_slot_over[g_up_cur_slot];
            if (!*sb) { *sb = [g_dev newBufferWithLength:UP_BLOCK_SIZE options:MTLResourceStorageModePrivate]; if (!*sb) MDIE("failed to create the overflow staging block"); res_add(*sb); g_up_blocks_new++; }
            g_up_block = *sb; g_up_block_size = (*sb).length; g_up_over_used = 1;
        } else {
            g_up_block_size = n > UP_BLOCK_SIZE ? need : UP_BLOCK_SIZE;
            g_up_block = g_up_block_size == UP_BLOCK_SIZE ? up_pool_get() : nil;   // a pooled block is resident already (up_pool_put)
            if (!g_up_block) { g_up_block = [g_dev newBufferWithLength:g_up_block_size options:MTLResourceStorageModePrivate]; res_add(g_up_block); g_up_blocks_new++; }
        }
        if (!g_up_block) MDIE("failed to create the swizzled-upload staging block %#zx", g_up_block_size);
        g_up_staging_bytes += g_up_block_size;
        g_up_block_off = 0;
    }
    *off = g_up_block_off;
    g_up_block_off += need;
    return g_up_block;
}

// The idle trim (see UP_TRIM_IDLE), on the submit thread at a submission's start. A slot not busy has had its last batch's feedback (the GPU is done with its blocks), and none is open on it; the blocks still leave through the deferred-release queue, which takes them out of the residency set after the next submission's fence
// idle: the submissions since the slot's last use that let a block go (0: every idle slot's, mtl_trim); fence: the one the blocks wait for in the deferred-release queue. Returns the bytes; *nout the blocks
static uint64_t up_trim_idle(uint64_t idle, uint64_t fence, int *nout) {
    uint64_t bytes = 0; int n = 0;
    for (unsigned s = 0; s < g_up_nslots; s++) {
        if ((g_up_cb && g_up_cur_slot == s) || atomic_load(&g_up_alloc_busy[s])) continue;
        if (g_up_slot_over[s] && g_sub_serial - g_up_slot_over_at[s] >= idle) {
            n++; bytes += g_up_slot_over[s].length; defer_obj_at(g_up_slot_over[s], 0, fence); g_up_slot_over[s] = nil;
        }
        if (g_sub_serial - g_up_slot_big_at[s] >= idle) {
            if (g_up_slot_blk[s] && g_up_slot_blk[s].length > UP_SLOT_BLOCK) { n++; bytes += g_up_slot_blk[s].length; defer_obj_at(g_up_slot_blk[s], 0, fence); g_up_slot_blk[s] = nil; }
            g_up_slot_want[s] = 0;
        }
    }
    g_up_trimmed += n; g_up_trim_bytes += bytes; *nout = n;
    return bytes;
}
static void up_idle_drop(__strong id<MTLBuffer> *block) {
    if (!*block) return;
    g_up_idle_n++; g_up_idle_bytes += (*block).length; g_up_trimmed++; g_up_trim_bytes += (*block).length;
    res_remove(*block); *block = nil;
}
// The opt-in trim by time (see up_idle_period), at a submission's start after NX 18's own trim, with no upload batch open
static void up_idle_release(void) {
    uint64_t idle = up_idle_period();
    if (!g_up_idle_report || g_up_cb) return;
    uint64_t now = clock_gettime_nsec_np(CLOCK_MONOTONIC), before = g_up_idle_n;
    for (unsigned s = 0; idle && s < g_up_nslots; s++) {
        up_idle_slot *age = &g_up_idle_slot[s];
        if (!age->used_ns || atomic_load(&g_up_alloc_busy[s])) continue;   // never used, or its batch still on the GPU (the feedback handler clears busy)
        if (now - age->used_ns >= idle) {   // fully idle: both blocks and the demand they were grown to
            up_idle_drop(&g_up_slot_blk[s]); up_idle_drop(&g_up_slot_over[s]);
            g_up_slot_want[s] = 0; *age = (up_idle_slot){0};
            continue;
        }
        if (g_up_slot_over[s] && now - age->overflow_ns >= idle) up_idle_drop(&g_up_slot_over[s]);
        if (now - age->window_ns >= idle) {   // an interval over: the slot sized for its peak
            if (g_up_slot_blk[s].length > up_slot_block_size(age->peak)) up_idle_drop(&g_up_slot_blk[s]);
            g_up_slot_want[s] = age->peak; age->peak = 0; age->window_ns = now;
        }
    }
    if (g_up_idle_n != before) res_commit();   // the removals committed before this submission can make more GPU memory
    static uint64_t said_ns;
    if (!said_ns || now - said_ns >= 30000000000ull || (!before && g_up_idle_n)) {
        said_ns = now; size_t held = 0;
        for (unsigned s = 0; s < g_up_nslots; s++) held += g_up_slot_blk[s].length + g_up_slot_over[s].length;
        MLOG("upload staging: slots hold %zu MiB; %llu blocks allocated, %llu trimmed by DM_NVN_UPLOAD_IDLE_MS (%llu MiB in total)", held >> 20,
             (unsigned long long)g_up_blocks_new, (unsigned long long)g_up_idle_n, (unsigned long long)(g_up_idle_bytes >> 20));
    }
}
static void up_trim(void) { if (up_trim_on()) { int n; up_trim_idle(subs_for_frames(UP_TRIM_IDLE), g_fence + 1, &n); } up_idle_release(); up_pool_trim(); }   // UP_TRIM_IDLE frames; then the opt-in by time; then the staging pool

// Deswizzle parameter blocks: 64 bytes per cell, cut sequentially from a 64 KB shared-storage block that lives as the upload batch's staging does (see g_up_slot_pblk)
static uint64_t g_up_pblocks_new;
static id<MTLBuffer> up_pblock_new(void) {
    id<MTLBuffer> b = [g_dev newBufferWithLength:64 << 10 options:MTLResourceStorageModeShared];
    if (!b) MDIE("failed to create the deswizzle parameter block");
    res_add(b); g_up_pblocks_new++; return b;
}
static id<MTLBuffer> up_param_alloc(size_t *off) {   // inside an open upload batch (up_begin)
    if (!g_up_pblock) {   // the batch's first cell: its slot's block, from the start (the slot's previous batch has run: up_begin waited for it)
        __strong id<MTLBuffer> *sb = &g_up_slot_pblk[g_up_cur_slot];
        if (!*sb) *sb = up_pblock_new();
        g_up_pblock = *sb; g_up_pblock_off = 0;
    }
    if (g_up_pblock_off + 64 > g_up_pblock.length) {   // full: a block of this batch alone, retired with it (up_flush; the cells recorded so far still read the old one)
        if (g_up_pblock != g_up_slot_pblk[g_up_cur_slot]) [g_up_keep addObject:g_up_pblock];
        g_up_pblock = up_pblock_new(); g_up_pblock_off = 0;
    }
    *off = g_up_pblock_off; g_up_pblock_off += 64;
    return g_up_pblock;
}
static void up_blit_add_at(id<MTLBuffer> src, size_t off, size_t row, size_t image, MTLSize size,
                           id<MTLTexture> dst, NSUInteger slice, NSUInteger level, MTLOrigin at) {
    if (g_nup_blits == g_up_blitcap) {
        g_up_blitcap = g_up_blitcap ? g_up_blitcap * 2 : 256;
        g_up_blits = realloc_or_die(g_up_blits, g_up_blitcap * sizeof *g_up_blits, "the upload blits");
    }
    g_up_blits[g_nup_blits++] = (up_blit){src, off, row, image, size, dst, slice, level, at, nil};
}
static void up_tcopy_add_at(id<MTLTexture> src, id<MTLTexture> dst, NSUInteger slice, NSUInteger level, MTLOrigin at, MTLSize size) {   // a region of a slice and level copied from another texture of the same shape (the same origin in both), in the batch's copies
    up_blit_add_at(nil, 0, 0, 0, size, dst, slice, level, at); g_up_blits[g_nup_blits - 1].tsrc = src;
    if (!g_up_views) g_up_views = [NSMutableArray array];
    [g_up_views addObject:src];
}
static void up_tcopy_add(id<MTLTexture> src, id<MTLTexture> dst, NSUInteger slice, NSUInteger level, MTLSize size) { up_tcopy_add_at(src, dst, slice, level, MTLOriginMake(0, 0, 0), size); }   // the whole slice and level
static void up_blit_add(id<MTLBuffer> src, size_t off, size_t row, size_t image, MTLSize size,
                        id<MTLTexture> dst, NSUInteger slice, NSUInteger level) { up_blit_add_at(src, off, row, image, size, dst, slice, level, MTLOriginMake(0, 0, 0)); }

// What a re-upload may keep of earlier content (pkg_upload_): the texture it replaces and the stamp its content was read at, the stamp of the spare it may be made into, the upload batches that
// wrote the two (NvPkg tex_seq, spare_seq), the storage's tracked range, and the main command buffers the two uploads ran before (NvPkg tex_gen, spare_gen; gsb_log_since)
typedef struct { __unsafe_unretained id<MTLTexture> old; uint64_t old_stamp, spare_stamp; unsigned old_seq, spare_seq; const void *span; uint64_t old_gen, spare_gen; } pkg_base;
// GPU stores into texture storage (gsb_swz), for the partial re-upload: the storage range each one wrote and the main command buffer it was encoded in (g_cbgen + 1). An upload reads the storage in
// a batch that runs after every main command buffer committed before it and before the one being encoded (each commit flushes the open batch first), so a texture uploaded while command buffer
// `gen` was being encoded holds a store of an earlier one and lacks one of `gen` or later. The CPU's page tracking does not see these writes, and a store through another texture object over the
// same storage (another format: another record) leaves this texture's record (NvPkg stored) as it was: pkg_upload_ counts a level of a layer that a store since its base's command buffer overlaps
// as written. Before, a partial re-upload kept such a layer from the spare or the texture it replaces for good. Submit thread (the replay encodes the stores and makes the uploads). A ring of
// GSB_LOG ranges, a store into the range of the one before it in the same command buffer widening it; once the ring has overwritten a range of command buffer `gen` or later (lost), a re-upload
// whose base is from `gen` on cannot tell, and is made whole
enum { GSB_LOG = 4096, GSB_NEAR = 32 };
