    typeof(g_gsb_log[0]) *p = &g_gsb_log[g_gsb_log_n % GSB_LOG];
    if (g_gsb_log_n >= GSB_LOG && p->gen > g_gsb_log_lost) g_gsb_log_lost = p->gen;
