static id<MTLTexture> pkg_upload(const tex_t *t, uint64_t *stamp, id<MTLTexture> reuse, MTLTextureUsage keep, const pkg_base *base) {
    struct timespec a, b; clock_gettime(CLOCK_MONOTONIC, &a);
