    int pf = pf_enter(PF_UPLOAD);
    id<MTLTexture> r = pkg_upload_(t, stamp, reuse, keep, base);
    pf_leave(pf);
    t_lft_up = was_up;
    if (r && r != reuse) bg_pkg_note(r);   // one the background purge may let the system empty: it is uploaded again from the game's memory (mtl_bg_purge)
    clock_gettime(CLOCK_MONOTONIC, &b); uint64_t d_ = (uint64_t)((b.tv_sec - a.tv_sec) * 1000000000ll + b.tv_nsec - a.tv_nsec);
    atomic_fetch_add(&g_upload_ns, d_); g_up_total_ns += d_;
