    if (!(*part = calloc(1, n + 64))) MDIE("texture copy of %llu bytes failed", (unsigned long long)n);
    uint64_t rd = safe_copy(*part, t->mem, n);
    if (rd < n) RED_ONCE(180, "texture ser=%llu %ux%u format %#x not readable from a memory pool buffer: only %llu of its %llu storage bytes could be read; the rest is read as 0 "
                         "(storage %p = pool %p + offset %#llx, pool size %#llx, pool flags %#x)", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format,
                         (unsigned long long)rd, (unsigned long long)n, (void *)t->mem, t->pool ? (void *)t->pool->mem : NULL, (unsigned long long)t->off,
                         t->pool ? (unsigned long long)t->pool->size : 0ull, t->pool ? t->pool->flags : 0u);
