            sp_op(&c->ops[c->nheaps], (MTL4UpdateSparseTextureMappingOperation){MTLSparseTextureMappingModeUnmap, rg, lev, y, 0});
            sp_release(*sl - 1); *sl = 0; s->nmap[lev]--;
