        for (NSUInteger slice = 0; slice < slices; slice++) for (NSUInteger d = 0; d < z; d += depth) for (NSUInteger y = 0; y < h; y += rows) {
            NSUInteger n = MIN(rows, h - y);
            up_blit_add_at(zb, 0, row, row * n, MTLSizeMake(w, n, MIN(depth, z - d)), mt, slice, l, MTLOriginMake(0, y, d));
        }
    }
    [g_up_texs addObject:mt];
    if (!g_cb) up_flush();
    if (!g_tex_zeroed++) MLOG("new-texture zeroing: on (new Metal textures are undefined; new Switch memory reads 0)");
}

// ---------- Large depth textures backed lazily (DM_NVN_DEPTH_LAZY, profile key depth_lazy) ----------
// Ocarina of Time makes a 12288x12288 Depth16 (288 MiB) and a 4096x4096 Depth32F (64 MiB) at each save load, and in the areas looked at it only samples the first while it holds
// the zeros it was made with (memory.md, "A clear pass on a large depth texture"). With the switch, a new single-sample, single-level 2D Depth16Unorm / Depth32Float texture of
// LZ_MIN or more is made a placement sparse texture with no tile mapped: an unmapped tile reads 0 to every read (sample, compare, gather, read() at any integer coordinate) and drops
// what is written to it, which is what a newly zeroed texture holds, so it needs no zeroing either. A tile is mapped, from the sparse tiles' placement heaps (sp_slot), and zeroed
// by a copy in the upload batch (the mapping goes to the queue first, rec_queue_block, and the batch is committed before the command buffer that writes: cb_seal) where the GPU
// is about to write something other than zero: a draw that writes depth maps the tiles under its scissor and viewport (lz_draw, with a margin for wide points and lines), a
// scissored clear to another value the cleared area, and anything the host cannot bound (a copy, an image binding, a colour view of it, a texture clear through one) the whole texture.
// A whole clear to another value (a load action, a texture clear of the whole level) makes it a normal texture instead (lz_whole): every tile would be mapped and stay mapped; not
// when its mapped tiles and the heaps' free ones hold most of it (lz_whole_pays), which then map the rest. Tiles are not unmapped while the texture lives. Game-agnostic: no
// profile sets the key yet. Every size the host reads comes from the full-size texture, so nothing else changes
#define LZ_MIN ((uint64_t)64 << 20)
#define LZ_MARGIN 256   // pixels around a draw's viewport: Metal's points are up to 511 wide, and a point is kept by its centre
@interface NvLazy : NSObject { @public
    __weak id<MTLTexture> tex; uint64_t serial, bytes, frame0; uint32_t w, h, tw, th, nx, ny, bpp, nmap, logged_q; MTLPixelFormat pf;
    uint32_t done[4];   // the tile rectangle (x0, y0, x1, y1, inclusive) last found all mapped: a pass's draws mostly repeat it, and a mapped tile stays mapped
    uint32_t *slot;   // per tile: heap slot + 1, 0 = not mapped
} @end
static _Atomic uint64_t g_lz_n, g_lz_live, g_lz_bytes, g_lz_tiles, g_lz_peak, g_lz_whole, g_lz_kept;   // textures made; live; their bytes; tiles mapped in the live ones; the most at once;
                                                                                                    // made normal by a whole clear (lz_whole); mapped whole at one instead (lz_whole_pays)
@implementation NvLazy
- (void)dealloc {
    uint32_t n = 0; pthread_mutex_lock(&g_sp_mu);
    for (size_t i = 0; slot && i < (size_t)nx * ny; i++) if (slot[i]) { sp_release(slot[i] - 1); n++; }   // back to the free list once the GPU is past the fence (sp_slot_free)
    pthread_mutex_unlock(&g_sp_mu);
    atomic_fetch_sub(&g_lz_tiles, n); atomic_fetch_sub(&g_lz_live, 1); atomic_fetch_sub(&g_lz_bytes, bytes); free(slot);
}
@end
static char g_lz_key;   // a lazy texture's NvLazy, as its associated object
static int g_lz_on = -1, g_lz_env, g_lz_test_nosparse;   // g_lz_test_nosparse: a unit test makes the device query answer no tile (the fallback)
// On by default on the iPhone and iPad for the X2.0 test round (DM_NVN_DEPTH_LAZY=0 turns it off); the Mac follows the game profile's depth_lazy
#if TARGET_OS_IPHONE && !TARGET_OS_MACCATALYST
#define LZ_DEFAULT 1
#else
#define LZ_DEFAULT 0
#endif
static int depth_lazy_on(void) {
    if (g_lz_on < 0) {
        const char *e = getenv("DM_NVN_DEPTH_LAZY"); g_lz_env = e && *e; g_lz_on = g_lz_env ? atoi(e) != 0 : (DM_GAME_DEPTH_LAZY || LZ_DEFAULT);
        if (g_lz_on || g_lz_env) MLOG("lazy depth: single-sample 2D Depth16 / Depth32F textures of %llu MB or more %s (%s)", (unsigned long long)(LZ_MIN >> 20),
                                      g_lz_on ? "take memory only where the GPU writes them (placement sparse)" : "are backed whole", g_lz_env ? "DM_NVN_DEPTH_LAZY" : DM_GAME_DEPTH_LAZY ? "game profile depth_lazy" : "the iPhone default");
    }
    return g_lz_on;
}
static const char *lz_fmt(MTLPixelFormat pf) { return pf == MTLPixelFormatDepth16Unorm ? "Depth16Unorm" : "Depth32Float"; }
// The NvLazy of a texture or of a view of one, with its root texture; nil for every other texture (a pointer test while none has been made)
static NvLazy *lz_of(id<MTLTexture> in, id<MTLTexture> __strong *root) {
    if (!atomic_load_explicit(&g_lz_n, memory_order_relaxed) || !in) return nil;
    id<MTLTexture> t = in; while (t.parentTexture) t = t.parentTexture;
    if (!t.isSparse) return nil;
    NvLazy *z = objc_getAssociatedObject(t, &g_lz_key);
    if (z && root) *root = t;
    return z;
}
static void lz_line(const char *why) {
    uint64_t made = atomic_load(&g_lz_n); if (!made) return;
    uint64_t live = atomic_load(&g_lz_live), bytes = atomic_load(&g_lz_bytes), tiles = atomic_load(&g_lz_tiles), mapped = tiles * SP_TILE;
    MLOG("lazy depth (%s): %llu textures live of %llu made (%llu made normal textures by a whole clear to a non-zero depth, %llu mapped whole there instead), %llu MB declared, %llu tiles mapped "
         "(%llu MB), %llu MB not backed; at most %llu tiles mapped at once (%llu MB)", why, (unsigned long long)live, (unsigned long long)made, (unsigned long long)atomic_load(&g_lz_whole),
         (unsigned long long)atomic_load(&g_lz_kept), (unsigned long long)(bytes >> 20),
         (unsigned long long)tiles, (unsigned long long)(mapped >> 20),
         (unsigned long long)((bytes > mapped ? bytes - mapped : 0) >> 20), (unsigned long long)atomic_load(&g_lz_peak), (unsigned long long)(atomic_load(&g_lz_peak) * SP_TILE >> 20));
}
static void lz_at_exit(void) { lz_line("at exit"); }
static void lz_tick(uint64_t f) {   // from mtl_set_frame: a line a minute (at 60 fps) while lazy textures exist and the mapped tiles have changed
    static uint64_t last_f, last_tiles = ~0ull;
    if (!atomic_load_explicit(&g_lz_n, memory_order_relaxed) || f < last_f + 3600) return;
    uint64_t tiles = atomic_load(&g_lz_tiles); last_f = f;
    if (tiles != last_tiles) { last_tiles = tiles; lz_line("every 3600 frames"); }
}
// Map the tiles of the pixel rectangle [x0, x1) x [y0, y1) that are not mapped yet, and zero them. Submit thread only (the upload batch is its own)
static void lz_map(NvLazy *z, id<MTLTexture> mt, long x0, long y0, long x1, long y1, const char *why) {
    if (x0 < 0) x0 = 0;
    if (y0 < 0) y0 = 0;
    if (x1 > (long)z->w) x1 = z->w;
    if (y1 > (long)z->h) y1 = z->h;
    if (x1 <= x0 || y1 <= y0 || z->nmap == z->nx * z->ny) return;
    uint32_t tx0 = (uint32_t)x0 / z->tw, tx1 = (uint32_t)(x1 - 1) / z->tw, ty0 = (uint32_t)y0 / z->th, ty1 = (uint32_t)(y1 - 1) / z->th;
    if (tx0 >= z->done[0] && ty0 >= z->done[1] && tx1 <= z->done[2] && ty1 <= z->done[3]) return;
    {   int all = 1;   // slots change only here (the submit thread) and when the texture goes: looked at without the lock
        for (uint32_t ty = ty0; ty <= ty1 && all; ty++) for (uint32_t tx = tx0; tx <= tx1 && all; tx++) all = z->slot[(size_t)ty * z->nx + tx] != 0;
        if (all) { z->done[0] = tx0; z->done[1] = ty0; z->done[2] = tx1; z->done[3] = ty1; return; } }
    MTL4UpdateSparseTextureMappingOperation *op = NULL; uint32_t *hi = NULL; size_t n = 0, cap = 0; int full = 1;
    pthread_mutex_lock(&g_sp_mu);
    for (uint32_t ty = ty0; ty <= ty1; ty++) for (uint32_t tx = tx0; tx <= tx1; tx++) {
        uint32_t *sl = &z->slot[(size_t)ty * z->nx + tx], s;
        if (*sl) continue;
        if (!sp_slot(&s)) { full = 0; goto out; }   // no heap could be made (red line 144): the rest stay unmapped, their writes dropped
        if (n == cap) { cap = cap ? 2 * cap : 64; op = realloc_or_die(op, cap * sizeof *op, "the lazy depth mappings"); hi = realloc_or_die(hi, cap * sizeof *hi, "the lazy depth mappings"); }
        op[n] = (MTL4UpdateSparseTextureMappingOperation){MTLSparseTextureMappingModeMap, MTLRegionMake3D(tx, ty, 0, 1, 1, 1), 0, 0, s % sp_ht()}; hi[n++] = s / sp_ht(); *sl = s + 1;
    }
out:;
    if (full) { z->done[0] = tx0; z->done[1] = ty0; z->done[2] = tx1; z->done[3] = ty1; }
    // the operations by heap, each heap's in one queue operation: the heaps are read under the lock, as sp_slot may add one
    NSMutableArray *heaps = [NSMutableArray array]; NSMutableArray *runs = [NSMutableArray array];
    for (size_t i = 0; i < n; i++) {
        if (hi[i] == ~0u) continue;
        uint32_t h = hi[i]; size_t k = 0; for (size_t j = i; j < n; j++) if (hi[j] == h) k++;
        MTL4UpdateSparseTextureMappingOperation *o = malloc(k * sizeof *o); if (!o) MDIE("the lazy depth mappings");
        k = 0; for (size_t j = i; j < n; j++) if (hi[j] == h) { o[k++] = op[j]; if (j != i) hi[j] = ~0u; }
        [heaps addObject:g_sp_heaps[h]]; [runs addObject:[NSValue valueWithPointer:o]]; [runs addObject:@(k)];
    }
    pthread_mutex_unlock(&g_sp_mu);
    for (NSUInteger r = 0; r < heaps.count; r++) {
        id<MTLHeap> heap = heaps[r]; MTL4UpdateSparseTextureMappingOperation *o = [runs[2 * r] pointerValue]; NSUInteger k = [runs[2 * r + 1] unsignedIntegerValue];
        rec_queue_block(^{ [g_q4 updateTextureMappings:mt heap:heap operations:o count:k]; free(o); });
    }
    if (n) {   // a heap tile held something before: zeroed after its mapping, before the command buffer that writes it (cb_seal flushes the batch first)
        id<MTLBuffer> zb = zero_buf((size_t)z->tw * z->th * z->bpp);
        if (zb) { up_begin();
            for (size_t i = 0; i < n; i++) { NSUInteger X = op[i].textureRegion.origin.x * z->tw, Y = op[i].textureRegion.origin.y * z->th;
                up_blit_add_at(zb, 0, (size_t)z->tw * z->bpp, (size_t)z->tw * z->th * z->bpp, MTLSizeMake(MIN(z->tw, z->w - X), MIN(z->th, z->h - Y), 1), mt, 0, 0, MTLOriginMake(X, Y, 0)); }
            [g_up_texs addObject:mt]; if (!g_cb) up_flush(); }
        z->nmap += (uint32_t)n;
        uint64_t all = atomic_fetch_add(&g_lz_tiles, n) + n, pk = atomic_load(&g_lz_peak); while (all > pk && !atomic_compare_exchange_weak(&g_lz_peak, &pk, all)) {}
        uint32_t total = z->nx * z->ny, q = z->nmap == total ? 4 : (uint32_t)((uint64_t)z->nmap * 4 / total);
        if (z->nmap == (uint32_t)n || q > z->logged_q) { z->logged_q = q;
            MLOG("lazy depth texture ser=%llu %ux%u %s: %u of %u tiles mapped (%.1f of %llu MB) by %s in frame %llu (made in frame %llu)", (unsigned long long)z->serial, z->w, z->h, lz_fmt(z->pf), z->nmap, total,
                 (double)z->nmap * SP_TILE / 1048576.0, (unsigned long long)(z->bytes >> 20), why, (unsigned long long)atomic_load(&g_cur_frame), (unsigned long long)z->frame0); }
    }
    free(op); free(hi);
}
static void lz_map_all(NvLazy *z, id<MTLTexture> mt, const char *why) { lz_map(z, mt, 0, 0, z->w, z->h, why); }
// The GPU writes t in a way the host cannot bound (a copy, a texture clear through a colour view, an image binding, an attachment through a colour view): every tile
static void lz_wrote(id<MTLTexture> t, const char *why) { id<MTLTexture> root = nil; NvLazy *z = lz_of(t, &root); if (z) lz_map_all(z, root, why); }
// A placement sparse texture for a GPU texture t (tex_desc's d) that qualifies, with no tile mapped; nil otherwise, and with one line a format when this GPU has no such texture
static id<MTLTexture> lz_make(const tex_t *t, MTLTextureDescriptor *d) {
    if (!d || !depth_lazy_on()) return nil;
    MTLPixelFormat pf = d.pixelFormat; uint32_t bpp = pf == MTLPixelFormatDepth16Unorm ? 2 : pf == MTLPixelFormatDepth32Float ? 4 : 0;
    if (!bpp || d.textureType != MTLTextureType2D || d.sampleCount > 1 || d.mipmapLevelCount != 1 || d.arrayLength != 1 || d.depth != 1) return nil;
    if ((uint64_t)d.width * d.height * bpp < LZ_MIN || (t->pool && nvn_sparse_pool(t->pool))) return nil;   // a sparse pool's texture follows the game's own mappings (sparse_gpu_make)
    MTLSize ms = g_lz_test_nosparse ? MTLSizeMake(0, 0, 0) : [g_dev sparseTileSizeWithTextureType:MTLTextureType2D pixelFormat:pf sampleCount:1 sparsePageSize:MTLSparsePageSize64];
    static int said[2]; int fi = bpp == 4;
    if (!ms.width || !ms.height || (uint64_t)ms.width * ms.height * bpp != SP_TILE) {
        if (!said[fi]++) MLOG("lazy depth: this GPU has no placement sparse %s texture (tile %lux%lu): such textures are backed whole, as without DM_NVN_DEPTH_LAZY (first case ser=%llu %lux%lu)",
                              lz_fmt(pf), (unsigned long)ms.width, (unsigned long)ms.height, (unsigned long long)t->serial, (unsigned long)d.width, (unsigned long)d.height);
        return nil;
    }
    MTLTextureDescriptor *x = [d copy];
    // Every usage a view or a clear could ask for from the start: a placement sparse texture is never remade (tex_upgrade keeps it), and it has no lossless compression to lose
    x.placementSparsePageSize = MTLSparsePageSize64; x.allowGPUOptimizedContents = NO; x.storageMode = MTLStorageModePrivate;
    x.usage |= MTLTextureUsageShaderRead | MTLTextureUsageRenderTarget | MTLTextureUsagePixelFormatView;
    id<MTLTexture> mt = [g_dev newTextureWithDescriptor:x];
    if (!mt || mt.firstMipmapInTail < 1) {   // level 0 in the tail: no tile of it could be mapped alone
        if (!said[fi]++) MLOG("lazy depth: a placement sparse %s %lux%lu could not be made%s: backed whole (first case ser=%llu)", lz_fmt(pf), (unsigned long)d.width, (unsigned long)d.height,
                              mt ? " with its level in tiles" : "", (unsigned long long)t->serial);
        return nil;
    }
    NvLazy *z = [NvLazy new];
    z->tex = mt; z->serial = t->serial; z->pf = pf; z->bpp = bpp; z->w = (uint32_t)d.width; z->h = (uint32_t)d.height; z->tw = (uint32_t)ms.width; z->th = (uint32_t)ms.height;
    z->nx = (z->w + z->tw - 1) / z->tw; z->ny = (z->h + z->th - 1) / z->th; z->bytes = (uint64_t)z->w * z->h * bpp; z->frame0 = atomic_load(&g_cur_frame);
    z->done[0] = z->done[1] = UINT32_MAX; z->done[2] = z->done[3] = 0;   // none yet
    if (!(z->slot = calloc((size_t)z->nx * z->ny, sizeof *z->slot))) MDIE("the lazy depth tile table");
    objc_setAssociatedObject(mt, &g_lz_key, z, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    atomic_fetch_add(&g_lz_live, 1); atomic_fetch_add(&g_lz_bytes, z->bytes);
    if (atomic_fetch_add(&g_lz_n, 1) == 0) atexit(lz_at_exit);
    res_add(mt);
    MLOG("lazy depth texture ser=%llu %ux%u %s: %llu MB not backed until the GPU writes it (placement sparse, %u tiles of %ux%u, none mapped; %s)", (unsigned long long)t->serial, z->w, z->h, lz_fmt(pf),
         (unsigned long long)(z->bytes >> 20), z->nx * z->ny, z->tw, z->th, g_lz_env ? "DM_NVN_DEPTH_LAZY" : DM_GAME_DEPTH_LAZY ? "game profile depth_lazy" : "the iPhone default");
    return mt;
}
// Whether a normal texture for z adds at most an eighth more memory than mapping its other tiles (an eighth: a recycled heap's headroom up to 32 MB, rh_heap): those take the tiles the heaps
// have free (sp_free_now) and whole heaps for the rest, the normal texture its whole size. A 4096x4096 Depth32F all of whose 1,024 tiles a draw mapped before a clear to 1 would take
// 64 MB more and leave its 64 MB of tiles free in heaps never freed; Ocarina of Time's save load (no tile mapped, no tile free) takes its size either way
static int lz_whole_pays(NvLazy *z, uint64_t *need, uint64_t *free_, uint64_t *heaps) {
    uint64_t total = (uint64_t)z->nx * z->ny, ht = sp_ht();
    pthread_mutex_lock(&g_sp_mu); *free_ = sp_free_now(); pthread_mutex_unlock(&g_sp_mu);
    *need = total - z->nmap; *heaps = *need > *free_ ? (*need - *free_ + ht - 1) / ht * ht : 0;   // tiles of the new heaps
    return total <= *heaps + total / 8;
}
// A whole clear of the lazy depth texture `in` (t's) to a non-zero depth: a load action (NVN clears the whole target; rp_begin_ex_) or a texture clear of the whole level (lz_tex_clear).
// Every tile would be mapped, zeroed and cleared, and would stay mapped while the texture lives, so lazy depth would save nothing there and cost the mapping: Ocarina of Time clears
// both its save load's depth textures to a non-zero depth as it makes them, and on an iPhone 18 Pro Max all 5,632 tiles were mapped and zeroed in that frame, which the load's frames
// of 600-650 ms followed (153-279 ms with the switch off and the textures zeroed by copies). The texture is
// made the normal way instead, as tex_mtl_ makes it without the switch (a recycled heap or an allocation of its own, lossless compression kept), but not zeroed, since the clear
// writes every texel before anything reads it; it takes every name of the lazy one, each serial noted (tex_names_move), and its RT_DEAD record (tu_register). The lazy one is retired
// once the submissions that used it complete, its mapped tiles going back to the heaps' free list then. That only while it adds little memory (lz_whole_pays): the heaps are never
// freed, so the tiles it has mapped would stay with them, and free tiles they hold would map the rest for nothing. Returns the new texture; nil when `in` is no lazy texture, and when
// the heaps can take the rest, it is a view of one or the texture cannot be made (then every tile is mapped, as before). Submit thread
static id<MTLTexture> lz_whole(const tex_t *t, id<MTLTexture> in, const char *why) {
    id<MTLTexture> root = nil; NvLazy *z = lz_of(in, &root);
    if (!z) return nil;
    // A texture whose memory pool is gone reaches here only through a pin (a queued descriptor or a saved binding; tex_mtl_ makes nothing for it): its pool's Finalize ended its
    // entries (pool_finalize_locked), and a normal texture would make its whole size again under its serial, kept until the object's own Finalize, as the entry the Finalize ended
    // had kept it (Ocarina of Time's 12288x12288 shadow target, 288 MB). Its memory is gone on NVN, so the clear may drop its writes into the unmapped tiles: nothing is mapped either.
    // A Finalize after this look refuses the normal texture's put (fs, pool_fin_since): it serves this clear, and is retired after it (tex_put_made)
    uint64_t fs = fin_snap();
    if (t && t->pool && t->pool->magic != MAGIC('P', 'O', 'O', 'L')) {
        static int said; if (!said++) MLOG("lazy depth texture ser=%llu %ux%u %s: %s after its memory pool's Finalize: kept as it is, not made a normal texture nor mapped (first case)",
                                           (unsigned long long)z->serial, z->w, z->h, lz_fmt(z->pf), why);
        return nil;
    }
    if (t && t->pool && g_pool_read_after) g_pool_read_after(t->pool);
    uint64_t need, free_, heaps;
    if (!lz_whole_pays(z, &need, &free_, &heaps)) {
        atomic_fetch_add(&g_lz_kept, 1);
        static int nk; if (nk++ < 64)
            MLOG("lazy depth texture ser=%llu %ux%u %s: %s maps its other %llu tiles in frame %llu instead of making it a normal texture (%u of %u mapped, %llu free in the placement "
                 "heaps): the heaps, which are never freed, grow by %llu MB, a normal texture would take %llu MB", (unsigned long long)z->serial, z->w, z->h, lz_fmt(z->pf), why,
                 (unsigned long long)need, (unsigned long long)atomic_load(&g_cur_frame), z->nmap, z->nx * z->ny, (unsigned long long)free_, (unsigned long long)(heaps * SP_TILE >> 20),
                 (unsigned long long)(z->bytes >> 20));
        lz_map_all(z, root, why); return nil;
    }
    MTLTextureDescriptor *d = t && in == root ? tex_desc(t, 0) : nil;
    id<MTLTexture> mt = nil;
    if (d && d.textureType == MTLTextureType2D && d.pixelFormat == root.pixelFormat && d.width == root.width && d.height == root.height && d.mipmapLevelCount == 1 && (d.usage & MTLTextureUsageRenderTarget)) {
        mt = rh_texture(t, d); if (!mt) mt = [g_dev newTextureWithDescriptor:d];
    }
    if (!mt) {
        static int said; if (!said++) MLOG("lazy depth texture ser=%llu: %s cannot make it a normal texture (cleared through a view, or no texture of its description could be made): every tile mapped instead", (unsigned long long)z->serial, why);
        lz_map_all(z, root, why); return nil;
    }
    res_add(mt);
    int had_tu = 0; if (g_tu.n) { os_unfair_lock_lock(&g_tu_lk); had_tu = tu_find(root) != NULL; os_unfair_lock_unlock(&g_tu_lk); }
    smu_lock(); int named = tex_names_move(root, mt, t->serial, 1); pthread_mutex_unlock(&g_smu);
    if (!named) tex_put_made(t, fs, mt);
    if (had_tu) { tu_register(mt, t->serial); tu_wrote(mt); } else tu_forget(mt);   // a record a freed texture left at its address is not its own (as alias_put)
    defer_obj_release(root);
    atomic_fetch_add(&g_lz_whole, 1);
    static int nl; if (nl++ < 64)
        MLOG("lazy depth texture ser=%llu %ux%u %s: made a normal texture by %s in frame %llu (made in frame %llu, %u of %u tiles mapped): every tile would be mapped, so it is backed whole "
             "(%llu MB) and not zeroed, the clear writing every texel", (unsigned long long)z->serial, z->w, z->h, lz_fmt(z->pf), why, (unsigned long long)atomic_load(&g_cur_frame),
             (unsigned long long)z->frame0, z->nmap, z->nx * z->ny, (unsigned long long)(z->bytes >> 20));
    return mt;
}

// Initial content: what a memory pool's storage holds at nvnMemoryPoolInitialize is the pool's content, also in a pool the CPU cannot access afterwards (CPU_NO_ACCESS), where the
// game never writes it again. Rhythm Heaven Groove reads each texture file into memory and makes a CPU_NO_ACCESS | GPU_CACHED pool on it (245 by its first screens), with BC7 textures
// that have no packaged layout; as GPU textures of zeros its sprite shader discarded every fragment (alpha 0) and the screen stayed black. A new texture in such a pool whose storage
// holds data is filled from it once, as a GPU texture that can still be rendered into (no re-upload on page writes, unlike packaged / CPU-written ones). Left out: storage of zeros
// (the zero fill does the same), COMPRESSIBLE textures (their memory is meaningless without the compression tags), multisample, depth / stencil and sparse ones.
// In a pool the CPU can write, the same holds for storage the game flushed (nvnMemoryPoolFlushMappedRange) before the texture's first use, when the GPU has not written it yet
// (nvn_flushed in hle_nvn.c: Breath of the Wild's sky scattering tables, copied into their pools and flushed; without them the sky was brownish grey). DM_NVN_FLUSH_FILL=0 leaves
// those out, as before. In a CPU_UNCACHED pool the CPU's writes reach memory with no flush, and the GPU reads that memory: what the storage holds at the texture's first use is its
// content there too, flushed or not. Donkey Kong Country: Tropical Freeze's title logo and menu panels (ASTC 5x5, no packaged layout) sit in CPU_UNCACHED | GPU_CACHED pools
// (flags 0x22) whose storage holds their texels at first use (the 912x512 logo: 242,374 of 376,832 bytes non-zero), never flushed; as GPU textures of zeros they were magenta
int nvn_flushed(const void *p, uint64_t n);   // hle_nvn.c
static int mem_any(const uint8_t *p, uint64_t n) {   // whether any byte is non-zero (stops at the first)
    uint64_t i = 0, v;
    if (!p) return 0;
    for (; i + 8 <= n; i += 8) { memcpy(&v, p + i, 8); if (v) return 1; }
    for (; i < n; i++) if (p[i]) return 1;
    return 0;
}
static int tex_mem_any(const tex_t *t) { int pf = pf_enter(PF_SCAN); uint8_t *pp; int any = mem_any(tex_src(t, t->L.size, &pp), t->L.size); free(pp); pf_leave(pf); return any; }
// Stale storage read as floating-point texels. A render target placed in CPU_NO_ACCESS memory that held other data (Splatoon 3 12.0.0's environment-probe arrays, RG11B10F, over
// reused storage) starts as that data on the Switch too; the game renders faces with SRC_ALPHA / ONE_MINUS_SRC_ALPHA blending and alpha 1, and Maxwell's float blender (SET_BLEND_FLOAT_OPTION:
// zero times anything is zero) drops the old value even where it decodes as NaN. Metal computes NaN x 0 = NaN, so any stale NaN stays and spreads through reflections. Workaround for Metal's
// fixed-function blender: if a non-COMPRESSIBLE float texture's first-use storage in a CPU_NO_ACCESS pool holds any NaN or infinite element, skip the fill and start from zeros instead.
// Only CPU_NO_ACCESS pools are checked: in CPU-visible pools the storage holds what the CPU wrote (t_direct_upload writes NaN and infinity on purpose).
static int storage_float_size(MTLPixelFormat pf) {   // element size in bytes, 0 for a format this does not check
    switch (pf) {
        case MTLPixelFormatRG11B10Float: return 4;
        case MTLPixelFormatRGBA16Float: case MTLPixelFormatRG16Float: case MTLPixelFormatR16Float: return 2;
        case MTLPixelFormatRGBA32Float: case MTLPixelFormatRG32Float: case MTLPixelFormatR32Float: return 4;
        default: return 0;
    }
}
static int span_has_nonfinite(const uint8_t *p, size_t n, void *ctx) {
    MTLPixelFormat pf = *(const MTLPixelFormat *)ctx;
    if (pf == MTLPixelFormatRG11B10Float) {
        for (size_t i = 0; i + 4 <= n; i += 4) {
            uint32_t v; memcpy(&v, p + i, 4);
            if (((v >> 6) & 31) == 31 || ((v >> 17) & 31) == 31 || ((v >> 27) & 31) == 31) return 1;
        }
        return 0;
    }
    if (storage_float_size(pf) == 2) {
        for (size_t i = 0; i + 2 <= n; i += 2) {
            uint16_t v; memcpy(&v, p + i, 2);
            if ((v & 0x7c00) == 0x7c00) return 1;
        }
        return 0;
    }
    for (size_t i = 0; i + 4 <= n; i += 4) {
        uint32_t v; memcpy(&v, p + i, 4);
        if ((v & 0x7f800000) == 0x7f800000) return 1;
    }
    return 0;
}
// Only the texels the texture can address are scanned (upstream NXNative 401c7b09c): a NaN in block-linear GOB, block, mip or layer padding, or past a linear row's pixels in its
// stride, no longer zeroes a finite texture. Levels, layers and slices of block-linear storage go through nvn_deswizzle_visit, a linear texture's one 2D level row by row; a layout
// neither can read is left to the fill. NX 18 reads the storage through tex_src, as tex_mem_any does (an unmapped page reads as 0)
static int storage_has_nonfinite_(const tex_t *t, id<MTLTexture> mt, const uint8_t *p, MTLPixelFormat pf) {
    if (t->d.flags & (NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET)) {
        int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh);
        if (!bpb || bw != 1 || bh != 1) return 0;
        uint32_t w, h, z; tex_lsize(t, 0, &w, &h, &z);
        size_t pitch = (size_t)w * (size_t)bpb, srow = tex_linear_row(t);
        if (z != 1 || srow < pitch || (uint64_t)srow * h > t->L.size) return 0;
        for (uint32_t r = 0; r < h; r++)
            if (span_has_nonfinite(p + (size_t)r * srow, pitch, &pf)) return 1;
        return 0;
    }
    unsigned levels = (unsigned)mt.mipmapLevelCount, max_levels = t->d.levels ? t->d.levels : 1;
    if (levels > max_levels) levels = max_levels;
    unsigned layers = t->L.layers ? t->L.layers : 1;
    for (unsigned l = 0; l < levels; l++)
        for (unsigned y = 0; y < layers; y++) {
            int rc = nvn_deswizzle_visit(&t->d, l, y, p, span_has_nonfinite, &pf);
            if (rc > 0) return 1;
            if (rc < 0) return 0;
        }
    return 0;
}
static int storage_has_nonfinite(const tex_t *t, id<MTLTexture> mt) {
    MTLPixelFormat pf = mt.pixelFormat;
    if (!storage_float_size(pf)) return 0;
    int pf_ = pf_enter(PF_SCAN); uint8_t *pp; int r = storage_has_nonfinite_(t, mt, tex_src(t, t->L.size, &pp), pf); free(pp); pf_leave(pf_); return r;
}
static int tex_init_fill(const tex_t *t, id<MTLTexture> mt) {
    if (!t->mem || !t->pool || (t->pool->flags & NVN_MEMORY_POOL_FLAGS_VIRTUAL) || t->has_layout) return 0;
    if (t->d.samples > 1 || ((int)mt.pixelFormat >= 250 && (int)mt.pixelFormat <= 262)) return 0;   // 250..262: Depth16Unorm … X24_Stencil8 (some names are macOS-only)
    int no_cpu = (t->pool->flags & NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS) != 0, uncached = (t->pool->flags & NVN_MEMORY_POOL_FLAGS_CPU_UNCACHED) != 0;
    // COMPRESSIBLE is a memory-compression hint, not a data format. In a CPU_NO_ACCESS pool the game never writes the storage, so the memory may mean nothing to the CPU (Rhythm Heaven Groove's render
    // targets). In a pool the CPU writes the texels are plain: SD GUNDAM G GENERATION CROSS RAYS (SDK 9.4.1) sets it on every texture it creates in 0xa2 pools and writes ordinary texels into them,
    // and skipping the fill left all 74 of them with content 0, the screen black but for text
    if (no_cpu && (t->d.flags & NVN_TEXTURE_FLAGS_COMPRESSIBLE)) return 0;
    static int flush_fill = -1; if (flush_fill < 0) { const char *e = getenv("DM_NVN_FLUSH_FILL"); flush_fill = !e || atoi(e) != 0; }
    if (!no_cpu && !uncached && (!flush_fill || !nvn_flushed(t->mem, t->L.size))) return 0;
    if (!atomic_load(&g_sub_thread_set) || !on_sub_thread() || !tex_mem_any(t)) return 0;   // the upload batch belongs to the submit thread
    static int stale_keep = -1; if (stale_keep < 0) { const char *e = getenv("DM_NVN_STALE_FLOAT"); stale_keep = e && atoi(e) == 1; }
    if (no_cpu && !stale_keep && storage_has_nonfinite(t, mt)) {
        static uint64_t ns;
        if (ns++ < 8 || !(ns & (ns - 1))) MLOG("initial content: ser=%llu %ux%ux%u format %#x: its storage holds non-finite float texels; starts from zeros (%llu so far; DM_NVN_STALE_FLOAT=1 keeps it)",
                                               (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, (unsigned long long)ns);
        return 0;
    }
    if (pkg_upload(t, NULL, mt, 0, NULL) != mt) return 0;
    int why = no_cpu ? 0 : uncached ? 1 : 2;
    static uint64_t n[3]; if (n[why]++ < 4) MLOG("initial content: ser=%llu %ux%ux%u format %#x filled from its storage, %s (%llu so far)", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format,
                                                 (const char *[]){"a CPU_NO_ACCESS pool's", "a CPU_UNCACHED pool's", "flushed by the CPU before its first use"}[why], (unsigned long long)n[why]);
    return 1;
}

static int clear_rect_zero(int i);
// Whether a linear texture can be a view on its pool's buffer: 1 yes (*pf, *mb, *mo, *row filled), 0 not a linear texture this applies to, -1 linear but its offset or row pitch is not aligned
// to the device's minimum (iOS: 64 bytes on an A18 Pro and an M4; 16 on the Macs here; DM_TBUF_ALIGN raises it to reproduce a phone's on a Mac). An unaligned one whose storage holds its
// content (linear_storage_ok) is uploaded from its storage instead, and again after each CPU write (tex_mtl_)
static NSUInteger tbuf_align(NSUInteger al);
static int linear_fit(const tex_t *t, uint32_t *pf, void **mb, uint64_t *mo, size_t *row) {
    // LINEAR_RENDER_TARGET is a linear layout too (SMBW's sky colour ramps: four 64×1 RGBA16F, written by the CPU every frame). Also in a pool the CPU cannot access, whose buffer holds what
    //   its storage held at creation (see tex_init_fill): Rhythm Heaven Groove's 228 linear R8 textures (sprite masks), read from files into CPU_NO_ACCESS pools, were private textures of zeros
    if (!(t->d.flags & (NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET)) || !t->mem || !t->pool) return 0;
    if (t->d.target != NVN_TEXTURE_TARGET_2D || t->d.levels > 1 || t->d.samples > 1) return 0;
    uint8_t swz[4]; int bw, bh, bpb = nvn_fmt_bpb(t->d.format, &bw, &bh);
    if (!nvn_fmt_to_mtl(t->d.format, pf, swz) || !*pf || !bpb || bw != 1 || bh != 1) return 0;
    *row = tex_linear_row(t);
    if (!mtl_addr((uint64_t)t->mem, (uint64_t)*row * (t->d.height ? t->d.height : 1), mb, mo)) { RED_ONCE(64, "linear texture storage is not in a memory pool (%ux%u format %#x)", t->d.width, t->d.height, t->d.format); return 0; }
    NSUInteger al = tbuf_align([g_dev minimumLinearTextureAlignmentForPixelFormat:(MTLPixelFormat)*pf]);
    if (*mo % al || *row % al) {
        static int n; if (n++ < 4) MLOG("linear texture ser=%llu %ux%u format %#x flags %#x: offset %#llx / row pitch %zu not aligned to %lu bytes (%d so far)",
                                        (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, t->d.flags, (unsigned long long)*mo, *row, (unsigned long)al, n);
        return -1;
    }
    return 1;
}
// Whether a linear texture's storage holds its content, so that one no view can take is uploaded from there and again after each CPU write (tex_mtl_), and read there (mtl_read_texels).
// In NVN a linear texture's content is its storage until the GPU writes it. LINEAR alone: always, as a GPU copy into it is written into the storage too (tex_storage_dst).
// LINEAR_RENDER_TARGET or IMAGE only say that the GPU may render or store into it, not that it does: Hades II decodes its Bink movies on the CPU into IMAGE | LINEAR R8 planes of
// 736-byte rows that its shaders only sample (GitHub issue #1956). Such a texture's storage holds its content while the GPU has not written it (gws_owned, from the GPU writes the
// commands record, mtl_tex_gpu_written), and one taken from it becomes a GPU texture at the GPU's next write there (cpu_unc_take / cpu_unc_drop). In a pool the CPU cannot write,
// GPU writes are not recorded: there it stays a GPU texture (its first fill takes its storage, tex_init_fill)
static int gws_owned(uintptr_t lo, uintptr_t hi);
static int linear_gpu_may_write(const tex_t *t) {   // a linear texture the GPU may render or store into; IMAGE alone is a block-linear texture
    return (t->d.flags & (NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET)) && (t->d.flags & (NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET | NVN_TEXTURE_FLAGS_IMAGE));
}
static int linear_storage_ok(const tex_t *t) {
    if (!(t->d.flags & (NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET)) || !t->mem) return 0;
    if (!linear_gpu_may_write(t)) return 1;
    return t->pool && !(t->pool->flags & (NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS | NVN_MEMORY_POOL_FLAGS_VIRTUAL)) && !gws_owned((uintptr_t)t->mem, (uintptr_t)t->mem + t->L.size);
}
// Linear textures (LINEAR) in a CPU-visible pool: the game writes the pool memory directly from the CPU (SMBW's glyph cache: 2048×8192 R8, IMAGE|LINEAR, pool CPU_UNCACHED|GPU_CACHED,
// the font engine rasterizes glyphs into it on the CPU). A GPU-private texture never sees those writes → all menu / dialog text is blank. On unified memory, create a linear texture directly on the pool buffer (zero copy): the GPU reads the current content at execution time, same as NVN.
static id<MTLTexture> tex_linear(const tex_t *t) {
    uint32_t pf = 0; void *mb; uint64_t mo; size_t row;
    int fit = linear_fit(t, &pf, &mb, &mo, &row);
    if (fit < 0) RED_ONCE(65, "linear texture %ux%u format %#x flags %#x: rows of %zu bytes no view can take, a private texture the CPU's writes do not reach (the GPU wrote its storage, or first used off the submit thread)",
                          t->d.width, t->d.height, t->d.format, t->d.flags, row);
    if (fit != 1) return nil;
    id<MTLBuffer> b = (__bridge id<MTLBuffer>)mb;
    MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:(MTLPixelFormat)pf width:t->d.width ? t->d.width : 1 height:t->d.height ? t->d.height : 1 mipmapped:NO];
    d.resourceOptions = b.resourceOptions;
    d.usage = MTLTextureUsageShaderRead | img_usage(t, (MTLPixelFormat)pf) | (t->d.flags & NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET ? MTLTextureUsageRenderTarget : 0);
    return [b newTextureWithDescriptor:d offset:mo bytesPerRow:row];
}
// CPU-written block-linear textures (WriteTexels): the game gave no packaged layout and changes the content from the CPU each frame (Engage's movie frames: a Y plane R8 + a UV plane RG8, WriteTexels every frame).
// Only packaged textures used to be uploaded from guest memory, so such a texture became a GPU-only texture whose content stayed 0. Their serials are recorded and they resolve through the packaged path (upload + re-upload on dirty pages)
// Every texture resolve asks about CPU writes. Mix serial keys: consecutive serials in a callback-free CFSet made misses probe long bucket runs (see reference/frame-rate.md).
// Finalize removes live membership, but command records and registered descriptors can still resolve the serial. Keep their classification until the storage pool is finalized;
// a copied flag would miss writes made after recording. Retired metadata can grow while a pool lives: expiring it earlier requires tracking ownership of all snapshots.
static pthread_mutex_t g_cpu_tex_mu = PTHREAD_MUTEX_INITIALIZER;
static nvn_hmap g_cpu_tex = {.klen = 8}, g_cpu_tex_retired = {.klen = 8};   // serial → pool (or (void *)1 for a live test texture without a pool)
// The uncompressed 2D textures tex_cpu_content took from their storage, which leave the CPU-written set once the GPU writes that storage (cpu_unc_drop)
typedef struct { const void *pool; uintptr_t lo, hi; } cpu_unc;
static nvn_hmap g_cpu_unc = {.klen = 8};   // serial → malloc'ed cpu_unc
// The uncompressed 3D textures tex_cpu_content took from their storage, by the sharing table's key (tex_alias_key). One storage named by an image object (a GPU texture in the sharing
// table) and by a sampled 3D object taken from its storage was two textures: the kernel wrote one, the shaders sampled the other, which kept guest memory's bytes for good (S2Arm #768:
// a 3D RGBA16F volume a compute kernel writes, its deferred lighting black). An image write through the shared texture makes such objects that texture (cpu_key_join); image first,
// tex_cpu_content takes no uncompressed texture over storage the GPU owns (gws_owned). Ported from S2Arm 2e9a6ce7 (Apache-2.0). Under g_cpu_tex_mu
enum { CPU_KEY_MAX = 4 };
typedef struct { uint32_t n; uint64_t ser[CPU_KEY_MAX]; } cpu_key_set;
static nvn_hmap g_cpu_key = {.klen = sizeof(alias_key)};   // alias key → malloc'ed cpu_key_set
static _Atomic uint32_t g_cpu_key_n;   // entries in g_cpu_key: an image write looks only when there are some
static void hm_drop_pool(nvn_hmap *m, const void *pool, int owned) {   // owned: the values are malloc'ed cpu_unc records; g_cpu_tex_mu held
    for (uint32_t i = 0; i < m->cap;) {
        const void *v = m->vals[i];
        const void *of = owned && v ? ((const cpu_unc *)v)->pool : v;
        if (!v || of != pool) {
            i++;
            continue;
        }

        uint64_t serial; memcpy(&serial, m->keys + (size_t)i * 8, 8);
        nvn_hm_del(m, &serial);   // deletion shifts entries: examine this slot again
        if (owned) {
            free((void *)v);
        }
    }
}
static void cpu_tex_drop_pool(const void *pool) {
    pthread_mutex_lock(&g_cpu_tex_mu);
    hm_drop_pool(&g_cpu_tex, pool, 0);
    hm_drop_pool(&g_cpu_tex_retired, pool, 0);
    hm_drop_pool(&g_cpu_unc, pool, 1);
    for (uint32_t i = 0; i < g_cpu_key.cap;) {
        alias_key k; memcpy(&k, g_cpu_key.keys + (size_t)i * g_cpu_key.klen, sizeof k);
        if (g_cpu_key.vals[i] && k.pool == (uint64_t)(uintptr_t)pool) { free(nvn_hm_del(&g_cpu_key, &k)); atomic_fetch_sub(&g_cpu_key_n, 1); } else i++;   // deletion shifts entries: this slot again
    }
    pthread_mutex_unlock(&g_cpu_tex_mu);
}
// Storage the GPU writes, by address range: a render target, a texture clear, a copy into a texture or a shader image recorded over it (mtl_tex_gpu_written). tex_cpu_content takes an
// uncompressed 2D texture from its storage unless the GPU wrote that storage and the CPU has not written it since. The rule was per pool: Ocarina of Time draws its terrain tiles' normal
// maps into the pool that also holds their height (260x260 R32F) and blend / hole (260x260 RGBA8, two layers) maps, which the CPU fills before nvnTextureInitialize with no flush, so
// every tile streamed in after the first normal map was drawn came out as zeros: holes in the ground, until a reload (aCidcOde found the pool rule's part in GitHub issue #1326). A span
// keeps the dirty-page generation of its last GPU write (stamp) and has its whole pages write-protected, so a CPU write into it afterwards (a tile's storage reused for another texture)
// is seen. Only whole pages count: a span's first and last pages are shared with whatever lies beside it, which the CPU may write at any time. Spans do not overlap: a GPU write over
// part of one cuts it, and the parts outside keep their own stamp, so a CPU write there since stays seen (merging them made the whole merged span the GPU's again). Storage the CPU
// cannot write (a CPU_NO_ACCESS or virtual pool) has no span: tex_cpu_content takes no texture there, and most render targets lie there. GPU writes are stamped when recorded, so a
// command buffer submitted again does not stamp its writes again (open: storage the CPU wrote since counts as the CPU's until the next recorded GPU write there)
typedef struct { uintptr_t lo, hi; uint64_t stamp, seen; const void *rg; int taken; } gws_span;   // seen: dirty generation at the last look; rg: the dirty-page range holding its whole pages
                                                                                                 // (NULL: none, or untracked); taken: tex_cpu_content took a texture over it since its stamp
static gws_span *g_gws; static size_t g_ngws, g_cgws; static pthread_mutex_t g_gws_mu = PTHREAD_MUTEX_INITIALIZER;
static _Atomic int g_gws_new;   // the GPU wrote storage anew, or wrote storage a texture was taken from, since cpu_unc_drop last looked
static void whole_pages(uintptr_t lo, uintptr_t hi, uintptr_t *a, uintptr_t *e) {
    uintptr_t pg = (uintptr_t)getpagesize();
    *a = (lo + pg - 1) & ~(pg - 1);
    *e = hi & ~(pg - 1);
}
static size_t gws_find(uintptr_t a) {   // the first span that ends after a; g_gws_mu held
    size_t l = 0, h = g_ngws;
    while (l < h) {
        size_t m = (l + h) / 2;
        if (g_gws[m].hi <= a) {
            l = m + 1;
            continue;
        }
        h = m;
    }
    return l;
}
static void gws_stamp(gws_span *s) {   // the stamp first, then the protection (nvn_dirty_now); g_gws_mu held
    uintptr_t a, e;
    whole_pages(s->lo, s->hi, &a, &e);
    s->stamp = s->seen = nvn_dirty_now();
    s->rg = e > a ? nvn_dirty_span((const void *)a, e - a) : NULL;
    if (s->rg) {
        nvn_dirty_protect((const void *)a, e - a);
    }
}
// The CPU wrote a whole page of [lo, hi) within the span after its stamp; g_gws_mu held. Through the span's kept range: a scan of every registered pool per look would be on the
// recording thread, at every render target, clear and copy, whenever any page anywhere was written
static int gws_cpu_since(gws_span *s, uintptr_t lo, uintptr_t hi) {
    uintptr_t a, e;
    whole_pages(MAX(lo, s->lo), MIN(hi, s->hi), &a, &e);
    if (e <= a || !s->rg) {
        return 0;
    }
    return nvn_dirty_since_cached(&s->rg, (const void *)a, e - a, s->stamp);
}
static void gws_rewritten(gws_span *s) {   // the GPU writes a span again: a CPU write since its stamp is overwritten now; g_gws_mu held
    uint64_t now = nvn_dirty_now();
    if (now == s->seen) {
        return;
    }

    s->seen = now;
    if (!gws_cpu_since(s, s->lo, s->hi)) {
        return;
    }

    gws_stamp(s);
    if (s->taken) {
        s->taken = 0;
        atomic_store(&g_gws_new, 1);
    }
}
static void gws_room(size_t more) {   // g_gws_mu held
    if (g_ngws + more <= g_cgws) {
        return;
    }

    size_t cap = g_cgws ? 2 * g_cgws : 256;
    while (cap < g_ngws + more) {
        cap *= 2;
    }
    gws_span *grown = realloc(g_gws, cap * sizeof *g_gws);
    if (!grown) {
        MDIE("GPU-written storage spans: out of memory");
    }
    g_gws = grown;
    g_cgws = cap;
}
static void gws_set(uintptr_t lo, uintptr_t hi) {   // [lo, hi) becomes one span, stamped now; the spans it overlaps keep their parts outside it, with their own stamps; g_gws_mu held
    size_t i = gws_find(lo), j = i;
    while (j < g_ngws && g_gws[j].lo < hi) {   // spans i .. j-1 overlap [lo, hi)
        j++;
    }

    int nl = i < j && g_gws[i].lo < lo, nr = i < j && g_gws[j - 1].hi > hi;
    gws_span left = nl ? g_gws[i] : (gws_span){0}, right = nr ? g_gws[j - 1] : (gws_span){0};
    left.hi = lo;
    right.lo = hi;
    size_t n = (size_t)nl + 1 + (size_t)nr;
    gws_room(n);
    memmove(g_gws + i + n, g_gws + j, (g_ngws - j) * sizeof *g_gws);
    g_ngws = g_ngws - (j - i) + n;
    if (nl) {
        g_gws[i++] = left;
    }
    g_gws[i] = (gws_span){.lo = lo, .hi = hi};
    gws_stamp(&g_gws[i]);
    if (nr) {
        g_gws[i + 1] = right;
    }
    atomic_store(&g_gws_new, 1);
}
void mtl_tex_gpu_written(const tex_t *t) {
    if (!t || !t->mem || !t->L.size || !t->pool || (t->pool->flags & (NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS | NVN_MEMORY_POOL_FLAGS_VIRTUAL))) {
        return;
    }

    uintptr_t lo = (uintptr_t)t->mem, hi = lo + t->L.size;
    pthread_mutex_lock(&g_gws_mu);
    size_t i = gws_find(lo);
    if (i < g_ngws && g_gws[i].lo == lo && g_gws[i].hi == hi) {
        gws_rewritten(&g_gws[i]);
    } else {
        gws_set(lo, hi);
    }
    pthread_mutex_unlock(&g_gws_mu);
}
// A span whose overlap with [lo, hi) holds no whole page of it, and which does not cover it, is a sliver of something beside it, and does not decide: textures are 512-byte aligned,
// so a GPU-drawn one may end in the page a CPU-filled one begins in; a span outlives the texture it was recorded for, so the game may hand part of that storage to a new texture; and
// a GPU write over part of a span leaves the parts outside, which can be smaller than a page (gws_set). gws_cpu_since cannot answer for a sliver (no whole page to ask the dirty
// tracker about), and taking its silence as the GPU's made the texture behind it a GPU texture: Ocarina of Time's CPU-filled 260x260 height (R32F) and hole (RGBA8) maps came up as
// zeros when the span of a 260x260 RG8 normal map (laid out at 214,528 bytes) reached 1,536 or 13,824 bytes into them, or a 2,560-byte remnant of an old span lay inside them, and
// whole terrain tiles vanished or showed another tile's surface (GitHub issue #1566). A span that covers the whole texture keeps the GPU's: a texture smaller than a page inside storage
// the GPU wrote, whose neighbours' CPU writes in the same page do not count for it either
static int gws_sliver(const gws_span *s, uintptr_t lo, uintptr_t hi) {
    if (s->lo <= lo && s->hi >= hi) {
        return 0;
    }
    uintptr_t a, e;
    whole_pages(MAX(lo, s->lo), MIN(hi, s->hi), &a, &e);
    return e <= a;
}
static int gws_owned(uintptr_t lo, uintptr_t hi) {   // the GPU wrote some of [lo, hi) and the CPU has not rewritten it since: the storage is not the content
    int owned = 0;
    pthread_mutex_lock(&g_gws_mu);
    for (size_t i = gws_find(lo); i < g_ngws && g_gws[i].lo < hi && !owned; i++) {
        owned = !gws_sliver(&g_gws[i], lo, hi) && !gws_cpu_since(&g_gws[i], lo, hi);
    }
    pthread_mutex_unlock(&g_gws_mu);
    return owned;
}
static void gws_take(uintptr_t lo, uintptr_t hi) {   // a texture over [lo, hi) is taken from its storage: the next GPU write there makes it a GPU texture (gws_rewritten, gws_set)
    pthread_mutex_lock(&g_gws_mu);
    for (size_t i = gws_find(lo); i < g_ngws && g_gws[i].lo < hi; i++) {
        g_gws[i].taken = 1;
    }
    pthread_mutex_unlock(&g_gws_mu);
}
// A pool's zero-copy buffer, which the GPU writes through. One made while any of its pages is read-only drops every GPU write through it, silently, so it is made over its protected pages
// opened (nvn_dirty_open: writable, not counted as written, protected again once it is made; issue #1591). A chunk of a large pool is made long after the pool, by when uploads and GPU writes
// have protected pages in it; a small pool's first or last page may be a neighbour's, protected by that pool's texture
static id<MTLBuffer> pool_buf_(uintptr_t a, uintptr_t b);
static id<MTLBuffer> pool_buf(uintptr_t a, uintptr_t b) { int pf = pf_enter(PF_PBUF); id<MTLBuffer> r = pool_buf_(a, b); pf_leave(pf); return r; }   // page-ins by part (PF_PBUF): a no-copy buffer made over the guest's pages
static id<MTLBuffer> pool_buf_(uintptr_t a, uintptr_t b) {
    nvn_dirty_open((void *)a, b - a);
    id<MTLBuffer> buf = [g_dev newBufferWithBytesNoCopy:(void *)a length:b - a options:MTLResourceStorageModeShared deallocator:nil];
    nvn_dirty_close();
    return buf;
}
static void gws_drop_pool(const pool_t *p) {   // the pool goes: its spans with it
    if (!p->mem || (p->flags & NVN_MEMORY_POOL_FLAGS_VIRTUAL)) {
        return;
    }

    uintptr_t lo = (uintptr_t)p->mem, hi = lo + p->size;
    pthread_mutex_lock(&g_gws_mu);
    size_t i = gws_find(lo), j = i;
    while (j < g_ngws && g_gws[j].lo < hi) {
        j++;
    }
    memmove(g_gws + i, g_gws + j, (g_ngws - j) * sizeof *g_gws);
    g_ngws -= j - i;
    pthread_mutex_unlock(&g_gws_mu);
}
// The GPU owns the texture's content: its host texture was made to be rendered into or written by shaders (nvn_ft_poll in hle_nvn.c never re-uploads such a texture from guest memory)
int mtl_tex_gpu_owned(uint64_t serial) {
    __unsafe_unretained id o = tex_get(serial);
    if (!obj_is_tex(o)) return 0;
    return (((id<MTLTexture>)o).usage & (MTLTextureUsageRenderTarget | MTLTextureUsageShaderWrite)) != 0;
}
void mtl_tex_cpu_written(const tex_t *t) {
    uint64_t serial = t->serial;
    if (!serial) return;
    // nvn_ft_poll can mark a snapshot after Finalize. Serialize the live check with release (g_smu → g_cpu_tex_mu), so that mark goes straight to retired metadata.
    smu_lock();
    pthread_mutex_lock(&g_cpu_tex_mu);
    int live = nvn_hm_get(&g_tex_live, &serial) != NULL;
    if ((live || (t->pool && t->mem)) && !nvn_hm_get(&g_cpu_tex, &serial) && !nvn_hm_get(&g_cpu_tex_retired, &serial)) {
        nvn_hm_put(live ? &g_cpu_tex : &g_cpu_tex_retired, &serial, t->pool ? (void *)t->pool : (void *)1);
        ser_note(serial);   // its texture IDs resolve again through the packaged path (tex_by_id view_pkg)
        static int n; if (n++ < 16) MLOG("CPU-written texture ser=%llu %ux%ux%u format %#x target %d levels %u: uploaded / re-uploaded like a swizzled texture", (unsigned long long)serial, t->d.width, t->d.height, t->d.depth, t->d.format, t->d.target, t->d.levels);
    }
    pthread_mutex_unlock(&g_cpu_tex_mu);
    pthread_mutex_unlock(&g_smu);
}
unsigned mtl_cpu_tex_count(void) { pthread_mutex_lock(&g_cpu_tex_mu); unsigned n = g_cpu_tex.n; pthread_mutex_unlock(&g_cpu_tex_mu); return n; }
static int tex_cpu_written(uint64_t serial) {
    pthread_mutex_lock(&g_cpu_tex_mu);
    int r = nvn_hm_get(&g_cpu_tex, &serial) != NULL || nvn_hm_get(&g_cpu_tex_retired, &serial) != NULL;
    pthread_mutex_unlock(&g_cpu_tex_mu);
    return r;
}
// Whether the host takes a texture's content from its storage (tex_mtl_'s packaged path): a packaged layout, CPU-written, or a sampled texture in a sparse virtual pool, which holds what
// the CPU wrote into the physical pages mapped there (Monster Hunter Rise: the hunter's innerwear, ASTC 6x6 with no packaged layout, came out magenta, and the face black) and is read
// through the page table. Render targets, images, linear and buffer textures stay GPU textures (as ft_add), except a linear texture whose storage holds its content that no view on
// its buffer can take (linear_storage_ok, made CPU-written by tex_mtl_). mtl_read_texels reads these from the storage too, on whatever thread asks
static int tex_from_storage(const tex_t *t) {
    if (!t->mem) return 0;
    if (t->has_layout || tex_cpu_written(t->serial)) return 1;
    if (!t->pool || t->d.target == NVN_TEXTURE_TARGET_BUFFER || (t->d.flags & (NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET |
        NVN_TEXTURE_FLAGS_COMPRESSIBLE | NVN_TEXTURE_FLAGS_IMAGE))) return 0;
    if (t->pool->flags & NVN_MEMORY_POOL_FLAGS_VIRTUAL)
        return nvn_sparse_pool(t->pool);
    // SPARSE selects the layout even in non-virtual memory: Bloodstained (upstream 950212b9f) writes such block-compressed textures through a CPU-visible pool after creating them.
    // Their storage is tracked from the start, so the first CPU writes and later mip uploads both reach the host texture (tex_storage_ok leaves SPARSE out of the first-use path)
    return (t->d.flags & NVN_TEXTURE_FLAGS_SPARSE) && !(t->pool->flags & NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS) &&
        t->d.samples <= 1 && t->d.target != NVN_TEXTURE_TARGET_1D_ARRAY && fmt_compressed(t->d.format);
}
// Storage the CPU wrote before the texture's first use (every game): until the GPU first uses a texture it has not written it, and a block-compressed one it can never render into
// (BC and ASTC formats are not colour-renderable; GPU copies into it are written into its storage too, tex_storage_dst). So a sampled block-compressed texture in a pool the CPU can
// write, with no packaged layout, whose storage holds data at its first use (tex_mtl_, submit thread) holds what the CPU wrote, flushed or not, before or after nvnTextureInitialize:
// it is made CPU-written, uploaded now and re-uploaded when its pages change. A one-time fill (tex_init_fill) is not enough: that GPU texture goes into the sharing table (g_alias),
// and a new texture object over the same storage with the same description gets it back after the CPU has rewritten the storage. The Great Ace Attorney Chronicles (Japanese release
// 0100D7F00FB1A000, GitHub issue #568) decodes its court-record pictures (256x256 to 2048x2048 BC1, a CPU_CACHED pool, no flush) into storage it reuses, building a new texture over
// it for each item: they were black, and once filled once, showed the previous item's picture. An uncompressed 2D texture cannot be told from a render target by its flags (NVN has
// none for that, so tex_desc gives it render-target use), but storage the GPU has not written holds only what the CPU wrote: there it takes its storage the same way (Mario Kart World's
// terrain patches, 260x260 R16, RG8, RGBA8, R11G11B10F and RGBA16 in a CPU_CACHED pool, written with no flush: zeros, so every patch was a flat plane at its base height; see gws_span for
// Ocarina of Time's). Once the GPU writes that storage such a texture becomes a GPU texture (cpu_unc_drop), and over storage the GPU writes it keeps the flushed-range fill. An uncompressed
// 3D texture with none of the flags below is taken from its storage in any pool: Xenoblade
// Chronicles 3's particle steering fields (10x10x10 RGBA8 and RGBA16F, flags 0) were GPU textures of zeros, so every send-off particle moved along (-1, -1, -1) and sank into the ground;
// the 3D textures it renders into carry IMAGE | COMPRESSIBLE. That is what Xenoblade Chronicles 3, Breath of the Wild and Tears of the Kingdom do, not an NVN rule: a 3D render target
// with neither flag and data in its storage at first use would still be drawn into (attach gives it render-target use), but a ReadTexels of it, or a second texture object over the
// same storage, would read the storage rather than what the GPU drew. DM_NVN_STORAGE_FIRST_USE=0 turns this off (to measure it)
static int tex_unc(const tex_t *t) { return !fmt_compressed(t->d.format) && t->d.target != NVN_TEXTURE_TARGET_3D; }   // the uncompressed 2D kind, which the GPU can render into
// Whether the texture's storage can be what the host takes its content from, whatever it holds now (tex_cpu_content at first use, mtl_tex_cpu_rewritten after it); unc: tex_unc
static int tex_storage_ok(const tex_t *t, int unc) {
    if (!t->mem || !t->pool || t->has_layout || t->d.samples > 1 || t->d.target == NVN_TEXTURE_TARGET_BUFFER) return 0;
    // not what only the GPU or the decoder fills (a display or video-decode texture, depth or stencil)
    if (unc && (fmt_depth(t->d.format) || (t->d.flags & (NVN_TEXTURE_FLAGS_DISPLAY | NVN_TEXTURE_FLAGS_VIDEO_DECODE)))) return 0;
    if (t->pool->flags & (NVN_MEMORY_POOL_FLAGS_CPU_NO_ACCESS | NVN_MEMORY_POOL_FLAGS_VIRTUAL)) return 0;   // the CPU cannot write it (tex_init_fill fills it once) / sparse (tex_from_storage)
    // IMAGE only matters for an uncompressed texture: shaders cannot write a block-compressed one. Pokopia gives nearly every texture IMAGE (flags 0x4), its icons BC1 / BC7 in a
    // CPU_UNCACHED pool; left to the one-time fill, a new icon over reused storage got the previous icon's picture from the sharing table (xFractals/pokopia-native issue #1)
    return !((t->d.flags & (NVN_TEXTURE_FLAGS_COMPRESSIBLE | NVN_TEXTURE_FLAGS_LINEAR | NVN_TEXTURE_FLAGS_LINEAR_RENDER_TARGET | NVN_TEXTURE_FLAGS_SPARSE))
             || ((t->d.flags & NVN_TEXTURE_FLAGS_IMAGE) && !fmt_compressed(t->d.format)));
}
static void cpu_unc_take(const tex_t *t) {   // an uncompressed texture is taken from its storage: the GPU's next write there makes it a GPU texture again (cpu_unc_drop)
    uintptr_t lo = (uintptr_t)t->mem, hi = lo + t->L.size;
    cpu_unc *u = malloc(sizeof *u);
    if (!u) {
        MDIE("cpu_unc_take: out of memory");
    }
    *u = (cpu_unc){t->pool, lo, hi};

    uint64_t s = t->serial;
    pthread_mutex_lock(&g_cpu_tex_mu);
    free(nvn_hm_put(&g_cpu_unc, &s, u));
    pthread_mutex_unlock(&g_cpu_tex_mu);
    gws_take(lo, hi);
}
static int tex_cpu_content(const tex_t *t) {
    static int on = -1; if (on < 0) { const char *e = getenv("DM_NVN_STORAGE_FIRST_USE"); on = !e || atoi(e) != 0; }
    int unc = tex_unc(t);
    if (!on || !tex_storage_ok(t, unc)) return 0;
    // not over storage the GPU writes (gws_owned: it takes a lock); a 3D one as well, which an image object over the same storage may have written (cpu_key_join)
    if ((!fmt_compressed(t->d.format) && gws_owned((uintptr_t)t->mem, (uintptr_t)t->mem + t->L.size)) || !tex_mem_any(t)) return 0;
    if (unc) {
        cpu_unc_take(t);
    }
    static uint64_t n[2]; if (n[unc]++ < 4) MLOG("texture written by the CPU before its first use ser=%llu %ux%ux%u format %#x%s pool flags %#x: uploaded from its storage, re-uploaded when it changes (%llu so far)",
                                         (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, unc ? " (uncompressed, in storage the GPU has not written)" : "", t->pool ? t->pool->flags : 0, (unsigned long long)n[unc]);   // tex_storage_ok has checked pool; the analyzer does not follow it
    return 1;
}
static void cpu_key_add(const tex_t *t) {   // an uncompressed 3D texture taken from its storage (tex_cpu_content), by its storage's key
    alias_key k = tex_alias_key(t);
    pthread_mutex_lock(&g_cpu_tex_mu);
    cpu_key_set *e = nvn_hm_get(&g_cpu_key, &k);
    if (!e && (e = calloc(1, sizeof *e))) { nvn_hm_put(&g_cpu_key, &k, e); atomic_fetch_add(&g_cpu_key_n, 1); }
    if (e) { uint32_t i = 0; while (i < e->n && e->ser[i] != t->serial) i++;
        if (i == CPU_KEY_MAX) { memmove(e->ser, e->ser + 1, (CPU_KEY_MAX - 1) * sizeof *e->ser); i = CPU_KEY_MAX - 1; }   // the oldest leaves
        else if (i == e->n) e->n++;
        e->ser[i] = t->serial; }
    pthread_mutex_unlock(&g_cpu_tex_mu);
}
// An image write through w (image_prepare, submit thread): when w resolves to the shared texture of its storage, the 3D textures taken from that storage (g_cpu_key) resolve to it from now
// on, out of the CPU-written set, as cpu_unc_drop hands uncompressed 2D ones their own texture. A write through a CPU-written texture of its own joins nothing
static void cpu_key_join(const tex_t *w) {
    if (!atomic_load_explicit(&g_cpu_key_n, memory_order_relaxed)) return;
    alias_key k = tex_alias_key(w); uint64_t fs = fin_snap();
    __unsafe_unretained id wo = tex_get(w->serial);
    smu_lock(); id shared = hm_get_id(&g_alias, &k); pthread_mutex_unlock(&g_smu);
    if (!shared || shared != wo) return;
    uint64_t ser[CPU_KEY_MAX]; uint32_t n = 0;
    pthread_mutex_lock(&g_cpu_tex_mu);
    cpu_key_set *e = nvn_hm_get(&g_cpu_key, &k);
    if (e) { for (uint32_t i = 0; i < e->n; i++) { ser[n++] = e->ser[i]; nvn_hm_del(&g_cpu_unc, &e->ser[i]); nvn_hm_del(&g_cpu_tex, &e->ser[i]); nvn_hm_del(&g_cpu_tex_retired, &e->ser[i]); }
        free(nvn_hm_del(&g_cpu_key, &k)); atomic_fetch_sub(&g_cpu_key_n, 1); }   // out of the CPU-written set first, as cpu_unc_drop: a resolution in between must not make the package again
    pthread_mutex_unlock(&g_cpu_tex_mu);
    if (n && g_pool_read_after) g_pool_read_after(w->pool);
    uint32_t nj = 0;
    for (uint32_t i = 0; i < n; i++) {
        __unsafe_unretained id o = tex_get(ser[i]);
        if (![o isKindOfClass:[NvPkg class]] || ((NvPkg *)o)->view) continue;   // gone, made a GPU texture already, or a sparse package's view
        if (tex_put_in(ser[i], shared, w->pool, fs)) nj++;   // the package goes behind the submissions that use it
        ser_note(ser[i]);
    }
    if (nj) { static int nl; if (nl++ < 8) MLOG("storage an image wrote through its shared texture ser=%llu: %u 3D texture(s) taken from it resolve to that texture from now on", (unsigned long long)w->serial, nj); }
}
// nvn_ft_poll (hle_nvn.c, tex_dirty_upload): the CPU wrote the pages of a registered texture after its first use. It is taken from its storage by the rule tex_cpu_content uses at first
// use: a texture whose storage can hold its content (tex_storage_ok); an uncompressed 2D one not while the GPU has written that storage and the CPU has not rewritten it since (gws_owned:
// MTL_REWRITE_GPU_NOW, which the poll asks again at the CPU's next write), and with the same way back (cpu_unc_take: the GPU's next write there makes it a GPU texture again). Its host
// texture's usage cannot tell: tex_desc gives every uncompressed texture made without a CPU fill render-target use, and with the usage as the test every such rewrite was dropped. Ocarina of
// Time rewrites its terrain tiles' height (260x260 R32F) and blend / hole (260x260 RGBA8, two layers) maps from the CPU as tile slots are reused while the player walks: the tiles kept
// what they held before, flat blue holes in the ground after an hour. Its normal maps, which the CPU zeroes and the GPU then draws, stay the GPU's. A block-compressed texture is uploaded
// whatever the GPU wrote: it cannot be rendered into, and GPU copies into it while registered are written into its storage too (tex_storage_dst), so a GPU-written span over it does not
// make its storage stale (Tears of the Kingdom's BC4 atlas and ASTC arrays). Any other texture keeps the usage test (MTL_REWRITE_GPU: left to the GPU for good), as before
int mtl_tex_cpu_rewritten(const tex_t *t) {
    int unc = tex_unc(t);
    if (tex_storage_ok(t, unc)) {
        if (unc && gws_owned((uintptr_t)t->mem, (uintptr_t)t->mem + t->L.size)) return MTL_REWRITE_GPU_NOW;
        mtl_tex_cpu_written(t);
        if (unc) {
            cpu_unc_take(t);
        }
        return MTL_REWRITE_UPLOADED;
    }
    if (mtl_tex_gpu_owned(t->serial)) return MTL_REWRITE_GPU;
    mtl_tex_cpu_written(t);
    return MTL_REWRITE_UPLOADED;
}
// WriteTexels wrote a linear texture's storage (hle_nvn.c write_texels). One a view on its pool's buffer can take (linear_fit) is that view, which reads the storage itself: made
// CPU-written, it would become an upload of the whole texture at each write. Any other is taken from its storage, as tex_mtl_ takes one at its first use (linear_storage_ok), and one the
// GPU may render or store into becomes a GPU texture again at the GPU's next write there (cpu_unc_drop)
void mtl_tex_linear_cpu_written(const tex_t *t) {
    uint32_t pf; void *mb; uint64_t mo; size_t row;
    if (linear_fit(t, &pf, &mb, &mo, &row) == 1) return;
    if (linear_gpu_may_write(t)) cpu_unc_take(t);
    mtl_tex_cpu_written(t);
}
// The GPU writes storage an uncompressed texture was taken from: what the storage holds is no longer the whole truth, so the texture becomes a GPU texture with the content it has, and
// CPU writes to it are no longer uploaded. Submit thread, as tex_cpu_content is, so a texture it has just taken is seen here if its storage was written meanwhile. The finalize count is
// read before the records (fin_snap): a record of a pool finalized after that reading hands its serial nothing (a pin may still hold the package; tex_put_in), and a pool finalized
// before it has no record left (mtl_alias_drop_pool drops them before it counts the Finalize)
static void cpu_unc_drop(void) {
    if (!atomic_load_explicit(&g_gws_new, memory_order_relaxed) || !atomic_exchange(&g_gws_new, 0)) return;
    typedef struct { uint64_t serial; const void *pool; } unc_ser;
    unc_ser *ser = NULL; uint32_t n = 0, cap = 0;
    uint64_t fs = fin_snap();
    pthread_mutex_lock(&g_cpu_tex_mu);
    for (uint32_t i = 0; i < g_cpu_unc.cap;) {
        cpu_unc *u = g_cpu_unc.vals[i];
        if (!u || !gws_owned(u->lo, u->hi)) {
            i++;
