        uint64_t m = (uint64_t)(uintptr_t)t->mem, lo = nvn_tex_level_offset(&t->d, level), hi = level + 1 < t->d.levels ? nvn_tex_level_offset(&t->d, level + 1) : t->L.layer_size;
        if (g->lin || g->d3 || hi <= lo || hi > t->L.layer_size) { if (g->d3 && hi > lo && hi <= t->L.layer_size) gsb_log_note(m + lo, m + hi); else gsb_log_note(m, m + t->L.size); }
        else gsb_log_note(m + (uint64_t)slice * t->L.layer_size + lo, m + (uint64_t)(slice + n - 1) * t->L.layer_size + hi);
    }
    g_gsb_bytes += (uint64_t)(g->xb1 - g->xb0) * g->rows * n;
    if (g_gsb_stores++ < 4) MLOG("texture in storage the CPU can read ser=%llu %ux%ux%u format %#x: what the GPU wrote is written into its storage on the GPU (bytes %u-%u of %u rows from %u, %u images)",
                                 (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, g->xb0, g->xb1, g->rows, g->by0, n);
}
// A GPU write into the texture that its storage does not get (not a store target, a host texture that does not hold its bytes, a region the store does not take): its package
// keeps that for good (gw_lost), so the idle release (tex_idle_commit) never makes it again from the storage, which lacks the write
static void gsb_lost(const tex_t *t) {
    if (!t || !t->serial) return;
    __unsafe_unretained id o = tex_get(t->serial);
    if ([o isKindOfClass:[NvPkg class]]) ((NvPkg *)o)->gw_lost = 1;
}
static void gsb_missed(const tex_t *t, unsigned level, const char *why) {   // a write the storage of a texture uploaded from it does not get: its next upload drops it
    gsb_lost(t);
    static int n; if (tex_storage_dst(t) && n++ < 8) MLOG("[RED] GPU write into ser=%llu %ux%ux%u format %#x target %d level %u not written into its storage (%s): the next upload from there drops it",
                                                         (unsigned long long)t->serial, t->d.width, t->d.height, t->d.depth, t->d.format, t->d.target, level, why);
}
// After a GPU write into level `level`, images [slice, slice + n) (layers, or a 3D texture's depth planes), of the texture: its region r (texels; NULL for the whole level) from the host texture mt
static void gsb_store(const tex_t *t, id<MTLTexture> mt, unsigned level, unsigned slice, unsigned n, const NVNcopyRegion *r) {
    if (!n || !mt) return;
    if (!gsb_target(t)) { gsb_lost(t); return; }
    if (!gsb_host_ok(t, mt) || level >= mt.mipmapLevelCount) { gsb_missed(t, level, "the host texture does not hold its bytes"); return; }
    gsb_geo g; if (gsb_geom(t, level, slice, n, r, &g) || (16 % g.bpb)) { gsb_missed(t, level, "a region or layout the store does not take"); return; }
    if (!g.d3 && slice + n > mt.arrayLength * (mt.textureType == MTLTextureTypeCube || mt.textureType == MTLTextureTypeCubeArray ? 6 : 1)) { gsb_lost(t); return; }
    uint32_t pad = g.xb0 & 15u;
    size_t pitch = ((size_t)(g.xb1 - (g.xb0 & ~15u)) + 15) & ~(size_t)15, img = pitch * g.rows;
    id<MTLBuffer> ab; size_t ao = arena_alloc(img * n, &ab);
    id<MTL4ComputeCommandEncoder> e = blit();
    for (unsigned z = 0; z < n; z++)
        enc_b_copy_texture_buffer(e, mt, g.d3 ? 0 : slice + z, level, MTLOriginMake((NSUInteger)g.tx, (NSUInteger)g.ty, g.d3 ? slice + z : 0), MTLSizeMake((NSUInteger)g.tw, (NSUInteger)g.tth, 1),
                                  ab, ao + z * img + pad, pitch, img);
    int shift = rb_copy_shift(t, mt);   // into the guest's order
    if (shift && !rb_swap_gpu(ab.gpuAddress + ao + pad, pitch, img, ab.gpuAddress + ao + pad, pitch, img, (size_t)(g.xb1 - g.xb0), g.rows, n, shift)) { gsb_lost(t); return; }
    gsb_swz(t, level, slice, &g, n, ab.gpuAddress + ao, pitch, img);
}
// After a buffer-to-texture copy into it: the region from the copy's source, at GPU address src (its first texel; rows row apart, images img apart), which holds the storage's bytes
static void gsb_store_buf(const tex_t *t, unsigned level, unsigned slice, unsigned n, const NVNcopyRegion *r, uint64_t src, size_t row, size_t img) {
    int bw, bh;
    if (!n) return;
    if (!gsb_target(t) || !nvn_fmt_bpb(t->d.format, &bw, &bh) || bw <= 0 || bh <= 0) { gsb_lost(t); return; }
    gsb_geo g;
    if (r->xoffset < 0 || r->yoffset < 0 || r->xoffset % bw || r->yoffset % bh || gsb_geom(t, level, slice, n, r, &g)
        || (uint32_t)((r->width + bw - 1) / bw) * g.bpb != g.xb1 - g.xb0 || (uint32_t)((r->height + bh - 1) / bh) != g.rows) { gsb_missed(t, level, "a region or layout the store does not take"); return; }
    gsb_swz(t, level, slice, &g, n, src - (g.xb0 & 15u), row, img);
}
// slice: the attachment's first slice, or of a 3D texture its depth plane (gsb_store stores a 3D texture's planes from there on)
static void rt_mirror_add(const tex_t *t, id<MTLTexture> mt, NSUInteger level, NSUInteger slice, int att) {
    if (!mt) return;
    if (!gsb_target(t)) { gsb_lost(t); return; }
    if (!gsb_host_ok(t, mt)) { gsb_missed(t, (unsigned)level, "a render target that does not hold its bytes"); return; }
    for (int i = 0; i < g_nrtm; i++) if (g_rtm[i].t.serial == t->serial && g_rtm[i].level == level && g_rtm[i].slice == slice) return;
    if (g_nrtm == (int)(sizeof g_rtm / sizeof g_rtm[0])) { gsb_lost(t); RED_ONCE(131, "more than %d render targets in storage the CPU can read in one pass: the rest are not stored into it", g_nrtm); return; }
    g_rtm[g_nrtm++] = (typeof(g_rtm[0])){*t, (void *)CFBridgingRetain(mt), (unsigned)level, (unsigned)slice, 1, att};
}
// Once the pass's layers are known: a layered or slice-merged pass (renderTargetArrayLength) draws into that many layers of each attachment from its attached slice on, all stored
static void rt_mirror_layers(MTL4RenderPassDescriptor *pd) {
    for (int i = 0; i < g_nrtm; i++) { MTLRenderPassColorAttachmentDescriptor *c = pd.colorAttachments[g_rtm[i].att];
        g_rtm[i].slice = (unsigned)(c.texture.textureType == MTLTextureType3D ? c.depthPlane : c.slice); g_rtm[i].n = pd.renderTargetArrayLength > 1 ? (unsigned)pd.renderTargetArrayLength : 1; }
}
// After the pass has ended, every layer it drew. The stores open the copy encoder, which is closed again: callers of rp_end may open an encoder of their own next and rely on none being
// open (with it left open, Tears of the Kingdom stopped presenting on loading its opening at frame 1983)
static void rt_mirror_flush(void) {
    int n = g_nrtm; g_nrtm = 0;
    for (int i = 0; i < n; i++) {
        id<MTLTexture> mt = CFBridgingRelease(g_rtm[i].tex);
        gsb_store(&g_rtm[i].t, mt, g_rtm[i].level, g_rtm[i].slice, g_rtm[i].n, NULL);
    }
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
}
static void rp_end_at(const char *fn, int line) { if (g_enc) { AP_B; geo_mesh_flush_pass(); PD("E %llu pass ends in %s:%d", g_stat_pass, fn, line);
    if (enc_label_on()) { static uint64_t lf = ~0ull, base; uint64_t f = atomic_load(&g_cur_frame); if (f != lf) { lf = f; base = g_stat_pass - 1; }   // Intra-frame serial: the same pass has the same name every frame, so the table can aggregate by name
        [(id)g_enc setLabel:[NSString stringWithFormat:@"p%02llu %dx%d %s d%d", (unsigned long long)(g_stat_pass - base), g_el_w, g_el_h, g_el_key[0] ? g_el_key : "-", g_el_draws]]; }
    sd_finish(); g_ldc_mask = g_lfc_mask = 0; enc_r_end_pass(g_enc); g_gp_bw_l0 = g_bw_load; g_gp_bw_s0 = g_bw_store;   // the profile's per-pass ledger counts from the previous pass end, profiled or not
    g_enc = nil; g_enc_geo_nocolor = 0; g_rt_merged = 0; g_rt_sub = 0; g_sm_pass = 0; g_fsp_pass = 0; ts_after(); ms_after();
    if (g_nubd && g_nubd >= ubd_lazy()) ubd_flush();   // the inline updates deferred in this pass, in order (see mtl_sub_update); across passes they wait for the next copy or dispatch (blit_raw)
    if (g_nbcrt) bcrt_flush();   // blocks drawn into shadows go back into their compressed textures
    if (g_nrtm) rt_mirror_flush();
    AP_E(0);
} }
// The format an attachment is actually attached with: the view's format if the view changes the format and can be attached, otherwise the base texture's. Shared by attaching (attach) and pipeline prediction (pso_predict_rest) so both agree --
// prediction used the base format, so for a pass written through an sRGB view (Mario's last pass) the predicted pipeline had the wrong format and the real one was compiled at the first draw (from d2r-mobile e2a0c9a9b)
// A compressed texture as a render target (The Legend of Zelda: Breath of the Wild a 32x32 RGTC1 (BC4) texture, Tears of the Kingdom a 32x32x32 3D one drawn one depth plane per pass, both written
// through an RGBA16UI view: one pixel = one 8-byte block, i.e. BC4 encoded on the GPU). Metal can neither attach a compressed format as a colour attachment nor create compressed <-> uncompressed views
// (the pipeline descriptor validation aborts the process). A BC texture with an uncompressed view whose pixel size equals the block size is drawn through a shadow (bcrt_attach); any other compressed target
// is left out (a pass with no attachment at all skips its draws), with a red line
static int mtl_fmt_block(MTLPixelFormat f) { return (f >= MTLPixelFormatBC1_RGBA && f <= MTLPixelFormatBC7_RGBAUnorm_sRGB) || (f >= MTLPixelFormatEAC_R11Unorm && f < MTLPixelFormatGBGR422); }   // BC, then EAC/ETC2 and ASTC (170-236; the deprecated PVRTC formats below them, 160-167, are never made: NVN has none)
static int nvn_fmt_bc(uint32_t f) { return f >= 0x41 && f <= 0x50; }   // NVN BC1–7 / BC6H formats (0x41 RGB_DXT1 … 0x50 BC6H unsigned)
static int bc_block_bytes(MTLPixelFormat f) {   // bytes per 4x4 block of a BC format, 0 for other formats
    if (f < MTLPixelFormatBC1_RGBA || f > MTLPixelFormatBC7_RGBAUnorm_sRGB) return 0;
    return f <= MTLPixelFormatBC1_RGBA_sRGB || f == MTLPixelFormatBC4_RUnorm || f == MTLPixelFormatBC4_RSnorm ? 8 : 16;
}
// A depth texture drawn through a colour view of the same pixel size (Luigi's Mansion 3: a D16 texture through an R16 view at boot) is drawn the same way: Metal can neither attach a depth format
// as a colour attachment nor make a colour view of a depth texture, and the pipeline descriptor validation aborts the process. Only formats whose Metal pixel is the NVN pixel qualify (D16 and D32F;
// D24S8 is Depth32Float_Stencil8 here, whose bytes are not the game's)
static int shrt_block(MTLPixelFormat f, int *side) {   // bytes per block of a texture drawn through a shadow, and the block's side in pixels; 0 for any other format
    int bb = bc_block_bytes(f); if (bb) { *side = 4; return bb; }
    *side = 1; return f == MTLPixelFormatDepth16Unorm ? 2 : f == MTLPixelFormatDepth32Float ? 4 : 0;
}
static int mtl_fmt_depth(MTLPixelFormat f) { return f == MTLPixelFormatDepth16Unorm || f == MTLPixelFormatDepth32Float || f == MTLPixelFormatDepth32Float_Stencil8 || f == MTLPixelFormatX32_Stencil8 || f == MTLPixelFormatStencil8; }
// The shadow's format: the view's, when the base is BC (or a depth format, above) and the view is an uncompressed colour format with one block's bytes per pixel
static int bcrt_view(id<MTLTexture> base, const view_t *v, int has_v, MTLPixelFormat *pf_out) {
    uint32_t pf = 0; uint8_t swz[4]; int bw = 0, bh = 0, side = 0, bb = base ? shrt_block(base.pixelFormat, &side) : 0;
    if (!bb || !has_v || !v->set_format || !nvn_fmt_to_mtl(v->format, &pf, swz) || !pf || mtl_fmt_block((MTLPixelFormat)pf) || mtl_fmt_depth((MTLPixelFormat)pf)) return 0;
    if (nvn_fmt_bpb(v->format, &bw, &bh) != bb || bw != 1 || bh != 1) return 0;
    *pf_out = (MTLPixelFormat)pf; return 1;
}
// Drawing into a BC texture: the pass draws into an uncompressed shadow of blocks x blocks in the view's format. The level / layer / depth plane's blocks are copied into it through a buffer before the pass
// and back, byte for byte, after it (bcrt_flush, from rp_end). The shadow is an attachment of its own: always loaded and stored, and kept out of the store-elision bookkeeping,
// which keys by the BC texture's serial. Shadows and staging buffers stay resident and are reused by format and size (bcrt_slot), so a pass per depth plane adds no residency churn.
// From PR #11 (digitalhivehub), where Tears of the Kingdom first drew this way
typedef struct { id<MTLTexture> base, shadow; id<MTLBuffer> buf; NSUInteger level, slice, z, w, h, bw, bh, bpb; } bcrt_t;
static bcrt_t g_bcrt[8];
// The shadow cache: each entry a shadow texture and its staging buffer, with when it was last taken (use: an order; ns: the time) and its bytes. It used to be indexed by the attachment's
// number in the pass, which starts at 0 again every pass, so an entry was made again whenever the passes that used that number changed format or size. Luigi's Mansion 3 draws its D16 shadow
// maps of 1024, 512 and 256 square through R16 views, one attachment per pass, so entry 0 was made again about 3 times a frame: in the iPhone log 1,300-1,900 textures and buffers, about
// 1.6 GB, and about 600 residency commits every 300 frames, all from the res_add line below. Now an entry is found by its shadow's Metal format and size in blocks (bcrt_slot): every attach
// copies the base's blocks in first and every pass end copies them back, so what a shadow held before never shows, and which entry a pass takes cannot change a picture; the copies
// themselves are as before (the blit barriers order one pass's copy back before the next pass's copy in through the same buffer, as they did when two passes shared an entry number).
// DM_NVN_BCRT_CACHE=0 takes the entry by attachment number again, made again whenever its format or size differs, as before, for A/B tests on a device
enum { BCRT_CACHE = 8 };   // as many as a pass has colour attachments, so an entry not attached in the open pass is always left
#define BCRT_CAP ((uint64_t)64 << 20)   // the bytes the cache keeps (textures and buffers) before it lets the least recently used entries go; Luigi's Mansion 3 needs 5.25 MiB
#define BCRT_IDLE_NS (5000000000ull)   // an entry no pass has taken for this long (5 s) is let go at the next submission's start (bcrt_trim), so a scene that needed large shadows does not pin them
typedef struct { __strong id<MTLTexture> sh; __strong id<MTLBuffer> buf; uint64_t use, ns, bytes; } bcrt_cache_t;
static bcrt_cache_t g_bcrtc[BCRT_CACHE]; static uint64_t g_bcrtc_use;
static int g_bcrt_res_line;   // the source line of bcrt_slot's res_add, as the residency line counts it (g_rs_site), so t_bcrt_cache can check that shadows stop adding to the set
static int bcrt_cache_on(void) { static _Atomic int on = -1; if (on < 0) { const char *e = getenv("DM_NVN_BCRT_CACHE"); on = !e || atoi(e);
    if (!on) MLOG("render-target shadows: one per attachment number, made again whenever its format or size changes, as before (DM_NVN_BCRT_CACHE=0)"); } return on; }
static int bcrt_is(id<MTLTexture> t) { for (int i = 0; i < g_nbcrt; i++) if (t && g_bcrt[i].shadow == t) return 1; return 0; }
static inline int bcrt_fits(const bcrt_cache_t *e, MTLPixelFormat spf, NSUInteger bw, NSUInteger bh, NSUInteger img) { return e->sh && e->sh.pixelFormat == spf && e->sh.width == bw && e->sh.height == bh && e->buf.length >= img; }
static void bcrt_bytes_note(void) { uint64_t b = 0; for (int i = 0; i < BCRT_CACHE; i++) b += g_bcrtc[i].bytes; atomic_store(&g_bcrt_bytes, b); }
// An entry's pair leaves through the deferred-release queue: out of the residency set and released once the submission of fence has completed (the open one's, g_fence + 1, for an entry a
// pass of it may have used)
static uint64_t bcrt_drop(bcrt_cache_t *e, uint64_t fence) {
    uint64_t b = e->bytes; defer_obj_at(e->sh, 0, fence); defer_obj_at(e->buf, 0, fence); e->sh = nil; e->buf = nil; e->bytes = e->use = e->ns = 0; return b;
}
// Over the byte cap: the least recently used entries go, never keep (just taken) nor one attached in the open pass. An entry larger than the cap by itself stays while it is attached, and is
// the first to go at the next miss. A game whose shadow shapes add up to more than the cap (two or three 2048-square D32 maps through R32F views, 32 MiB a shadow and its buffer) would
// make its shadows again at every pass, as before the cache, and only 'retired' in the residency line would show it; so the first eviction is logged once with every entry's shape and
// the total, and a device log names the cause if it ever happens
static void bcrt_cap(int keep) {
    uint64_t total = 0; for (int i = 0; i < BCRT_CACHE; i++) total += g_bcrtc[i].bytes;
    static int logged;
    if (total > BCRT_CAP && !logged++) {
        char shapes[640]; size_t o = 0; shapes[0] = 0;
        for (int i = 0; i < BCRT_CACHE && o < sizeof shapes; i++) { const bcrt_cache_t *e = &g_bcrtc[i]; if (!e->sh) continue;
            o += snprintf(shapes + o, sizeof shapes - o, "%s%lux%lu Metal format %lu %.1f MiB%s", o ? ", " : "", (unsigned long)e->sh.width, (unsigned long)e->sh.height, (unsigned long)e->sh.pixelFormat,
                          e->bytes / 1048576.0, i == keep ? " (new)" : ""); }
        MLOG("render-target shadows: the cache holds %.1f MiB, over its %llu MiB, so the least recently used shadows go and are made again when next drawn (logged once): %s",
             total / 1048576.0, (unsigned long long)(BCRT_CAP >> 20), shapes);
    }
    while (total > BCRT_CAP) {
        int v = -1; for (int i = 0; i < BCRT_CACHE; i++) { bcrt_cache_t *e = &g_bcrtc[i]; if (i == keep || !e->sh || bcrt_is(e->sh)) continue; if (v < 0 || e->use < g_bcrtc[v].use) v = i; }
        if (v < 0) break;
        total -= bcrt_drop(&g_bcrtc[v], g_fence + 1); atomic_fetch_add(&g_bcrt_retired, 1);
    }
}
// Entries no pass has taken for idle_ns (0: all) go behind fence. Only between submissions (no pass is open, so none is attached), from mtl_sub_begin and the memory trim (mtl_trim_at);
// returns the bytes let go, *nout the entries
static uint64_t bcrt_trim(uint64_t idle_ns, uint64_t fence, int *nout) {
    uint64_t freed = 0, now = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); int n = 0;
    *nout = 0; if (!bcrt_cache_on() || atomic_load(&g_sub_open) || g_nbcrt) return 0;
    for (int i = 0; i < BCRT_CACHE; i++) { bcrt_cache_t *e = &g_bcrtc[i];
        if (e->sh && now - e->ns >= idle_ns) { freed += bcrt_drop(e, fence); n++; } }
    if (n) { atomic_fetch_add(&g_bcrt_retired, (uint64_t)n); bcrt_bytes_note(); }
    *nout = n; return freed;
