        if (dz) { if (j[@"entry_z"]) { entry = j[@"entry_z"]; ez = 1; } else RED_ONCE(85, "vertex shader %s has no near=0 entry (entry_z): depth stays in the GL convention", pc.UTF8String); }
        if (layer) entry = dz ? j[@"entry_layer_z"] : j[@"entry_layer"];
    }
