        // Key = sha256(first 0x880 bytes of the control section + code area): many of Mario's shaders share a control section but differ in code (dm/gfx/tools/shader_split.py). It was computed at SetShaders (hle_nvn.c): by now the game may have freed the control section
        uint8_t md[8]; if (!prog_key(p, i, md)) MDIE("program stage %u has no shader key", i);
        NSString *k = [NSString stringWithFormat:@"%02x%02x%02x%02x%02x%02x%02x%02x", md[0], md[1], md[2], md[3], md[4], md[5], md[6], md[7]];
        NSString *stage = g_shmap[k];
        if (!stage) {   // Not in the package: look up the compute kernels embedded in the main body (nvn_builtin.h)
            NvShader *b = builtin_get(k.UTF8String);
            if (b) { o->sh[5] = b; o->stages |= (uint8_t)(1u << 5); continue; }
            o->stages |= PROG_ST_UNKNOWN;
            MLOG("[RED] shader %s is not in the shader map (DM_NVN_SHDUMP=directory saves its control section and code area)", k.UTF8String);
            // DM_NVN_SHDUMP=directory: shaders missing from the map are saved as <key>.ctl (the control section's key bytes) and <key>.code (code area, nvn_ctl_lens), to trace their source / add them to the map offline
            static const char *shd; static int shd_init; if (!shd_init) { shd = getenv("DM_NVN_SHDUMP"); shd_init = 1; if (shd && *shd) mkdir(shd, 0777); }   // create the dump folder: a missing one made every fopen fail silently
            if (shd) { char path[1024]; FILE *f; uint32_t ncode, nctl; nvn_ctl_lens(p->sd[i].control, &nctl, &ncode);   // with SHDUMP set the control section is the host's copy
                snprintf(path, sizeof path, "%s/%s.ctl", shd, k.UTF8String); if ((f = fopen(path, "wb"))) { fwrite(p->sd[i].control, 1, nctl, f); fclose(f); }
                snprintf(path, sizeof path, "%s/%s.code", shd, k.UTF8String);
                if (p->sd[i].data && ncode && ncode < (1u << 24) && (f = fopen(path, "wb"))) { fwrite((const void *)(uintptr_t)p->sd[i].data, 1, ncode, f); fclose(f); } }
            continue;
        }
        int st = stage_of(stage);
        o->stages |= prog_stage_bit(stage);
        NvShader *sh = st >= 0 ? shader_get([k stringByAppendingString:@"_b"], st) : nil;
        if (sh) o->sh[st] = sh; else MLOG("[RED] shader %s (%s) failed to load: build the shaders with dm/gfx/tools/dmsh_build.py first", k.UTF8String, stage.UTF8String);
        if (sh && st == 5) up_mfx_read_color(sh, &p->sd[i]);
        if (!sh && st == 2) strlcpy(o->gs_miss, k.UTF8String, sizeof o->gs_miss);
    }
    prog_fold_gs(o);   // a slice-writing geometry shader: the vertex shader's layer entry points instead
    if (p->serial) serial_put(p->serial, o);
    else { if (g_prog_noserial) defer_obj_unref(g_prog_noserial); g_prog_noserial = o; }
    return (__bridge void *)o;
}
// Stage mask of a program without loading shader libraries: reads a resolved NvProg (or its sh[] for synthetic test objects) or the shader map alone,
// so OP_BIND_PROGRAM and lookahead state walks never trigger shader_get or warm_start (ported from NXNative e59c910ad)
static uint8_t prog_stage_mask(const prog_t *p) {
    if (!p) return 0;
    typedef struct { uint64_t ser, gen; uint8_t mask; } smc_ent;
    static smc_ent smc[256];
    uint64_t ser = p->serial, gen = g_ser_gen;
    unsigned h = (unsigned)ser & 255u;
    if (ser && smc[h].ser == ser && smc[h].gen == gen) return smc[h].mask;
    __unsafe_unretained NvProg *o = ser ? serial_get(ser) : nil;
    if (o) {
        if (o->stages) { smc[h] = (smc_ent){ser, gen, o->stages}; return o->stages; }
        uint8_t m = 0;
        for (int st = 0; st < 6; st++) if (o->sh[st]) m |= (uint8_t)(1u << st);
        if (o->sh[4] && o->sh[4]->mesh_kind == 2) m |= PROG_ST_MESH;
        return m;
    }
    if (!p->nstage) return 0;
    shmap_read_once();
    uint8_t m = 0;
    unsigned n = p->nstage < 6 ? p->nstage : 6;
    for (unsigned i = 0; i < n; i++) {
        uint8_t md[8];
        if (!prog_key(p, i, md)) { m |= PROG_ST_UNKNOWN; continue; }
        char hx[17];
        snprintf(hx, sizeof hx, "%02x%02x%02x%02x%02x%02x%02x%02x", md[0], md[1], md[2], md[3], md[4], md[5], md[6], md[7]);
        NSString *stage = g_shmap[@(hx)];
        if (stage) m |= prog_stage_bit(stage);
        else m |= builtin_has(hx) ? (uint8_t)(1u << 5) : (uint8_t)PROG_ST_UNKNOWN;
    }
    if (ser) smc[h] = (smc_ent){ser, gen, m};
    return m;
}
// A submitted descriptor and a queue binding hold the compiled program by its
// immutable initialization serial. Retaining it must not mint serial aliases:
// alias churn invalidates texture tables and changes composite-program keys.
typedef struct { unsigned refs, retired; } prog_pin;
static nvn_hmap g_prog_pins={.klen=8}; // protected by the submission lock
static void prog_release_serial(uint64_t serial) {   // under g_sub_mu
    prog_pin *pin=nvn_hm_get(&g_prog_pins,&serial);
    if(pin) pin->retired=1; else serial_del(serial);
}
void mtl_prog_release(prog_t *p) { if(p->serial) prog_release_serial(p->serial); }
// nvnProgramSetShaders on a game thread queues the program's old serial here instead of waiting for g_sub_mu, which the replay holds through a whole submission (Ocarina of Time:
// the game's submits waited about 1 ms a frame for it, 2-4 ms in heavy stretches; NX18-X2.0 oot-alldata-analysis.md). The replay drains the queue under g_sub_mu before each
// submission it runs, so the old serial goes no sooner than before (a queued submission that still names it runs first or holds a pin)
static os_unfair_lock g_prog_rel_lk = OS_UNFAIR_LOCK_INIT; static uint64_t *g_prog_rel; static size_t g_prog_rel_n, g_prog_rel_cap;
void mtl_prog_release_later(uint64_t serial) {
    if (!serial) return;
    os_unfair_lock_lock(&g_prog_rel_lk);
    if (g_prog_rel_n == g_prog_rel_cap) { size_t c = g_prog_rel_cap ? g_prog_rel_cap * 2 : 256; uint64_t *q = realloc(g_prog_rel, c * sizeof *q); if (!q) MDIE("program release queue allocation failed"); g_prog_rel = q; g_prog_rel_cap = c; }
    g_prog_rel[g_prog_rel_n++] = serial;
    os_unfair_lock_unlock(&g_prog_rel_lk);
}
void mtl_prog_release_drain(void) {   // under g_sub_mu
    if (!__atomic_load_n(&g_prog_rel_n, __ATOMIC_RELAXED)) return;
    os_unfair_lock_lock(&g_prog_rel_lk);
    for (size_t i = 0; i < g_prog_rel_n; i++) prog_release_serial(g_prog_rel[i]);
    g_prog_rel_n = 0;
    os_unfair_lock_unlock(&g_prog_rel_lk);
}
void mtl_prog_unpin(prog_t *p) {
    prog_pin *pin=nvn_hm_get(&g_prog_pins,&p->serial);
    if(pin && !--pin->refs) { nvn_hm_del(&g_prog_pins,&p->serial); if(pin->retired) serial_del(p->serial); free(pin); }
}
void mtl_prog_snapshot(prog_t *copy,const prog_t *source) {
    prog_get(source); *copy=*source;
    if(!source->serial) MDIE("cannot retain a program without an initialization serial");
    prog_pin *pin=nvn_hm_get(&g_prog_pins,&source->serial);
    if(!pin) { pin=calloc(1,sizeof *pin); if(!pin) MDIE("program retention allocation failed"); nvn_hm_put(&g_prog_pins,&source->serial,pin); }
    pin->refs++;
}

// ---------- Descriptor pool: texture ID / sampler ID → object ----------
// A texture ID's type or class view (treg_t alt, im) made again or let go: a resource ID a slot table entry holds can name the old one with no registration or storage change
// (bindless-plan.md g_alt_gen; DM_NVN_BINDLESS, bl_note)
static uint64_t g_alt_gen = 1;
// At registration the whole texture object is snapshotted (NVN semantics: the descriptor has been written into the pool); view: the MTLTexture for that ID (a view or the base texture, held via CFBridgingRetain) and the serial-table / guest-write generations at the time it was obtained
typedef struct { tex_t t; int ok; view_t v; int has_v; void *view, *view_fam; uint64_t view_id, view_rid, view_fam_wh, view_ser, view_dirty, view_stamp; const void *view_span; int view_pkg; const void *view_wp; uint64_t view_w;   // view_pkg: CPU-written (packaged); only those depend on guest writes (view_dirty)
                 uint16_t view_pf; uint8_t view_tt;   // view's pixel format and texture type, kept with view_rid so a binding asks the view nothing (tex_fast_rid_tp)
                 // view_wp / view_w: a packaged view's tracked range found clean at its write sequence view_w (nvn_dirty_since_seq; DM_NVN_TEX_SEQ): while it reads so, a guest write elsewhere leaves the view current
                 void *alt, *alt_of; uint64_t alt_rid; uint8_t alt_type;   // alt: compatible view used when the shader's declared type differs from view (tex_fit), alt_of = the view it was built from
                 void *alt2, *alt2_of; uint64_t alt2_rid; uint8_t alt2_type;   // the alt view before it (DM_NVN_TEX_ALT2): an ID read as two types, or from two views, keeps both
                 void *im, *im_of; uint64_t im_rid;                       // im: the view an image slot reads in the shader's pixel class (img_fit), im_of = the view it was built from
                 int prev, next, retired, gone; uint64_t transient_sub; uint8_t tt1;   // prev / next: descriptor index + 1, by texture serial; gone: its memory pool was finalized (treg_drop_pool_views)
                 void *stand; uint64_t stand_rid, stand_sum, reg_frame; uint8_t stand_tt1, stand_no; uint32_t used; } treg_t;   // stand: what its pool table entries hold while its texture is not made (pool_stand; retained), stand_tt1 its texture type + 1, stand_no: it can have none; reg_frame: the frame of the registration
static treg_t *g_treg; static int g_ntreg;
// fam_is_valid / fam_pool_masked for texture ID tid when t is the ID's cached view: its family and geometry were taken when the view was made (tex_by_id_ref), so no walk to the
// root and no owner lookup per bind (NXNative cde54c161: OoT on an M4 Pro, -8 M submit instructions a frame). Another texture takes the full check. Caller holds g_rmu
static inline __attribute__((always_inline)) int treg_fam_valid(int tid, __unsafe_unretained id<MTLTexture> t) {
    if (!atomic_load_explicit(&g_image_heap_comp_n, memory_order_relaxed)) return 1;
    if (tid > 0 && tid < g_ntreg && g_treg[tid].view == (__bridge void *)t) {
        void *fam = g_treg[tid].view_fam;
        return __builtin_expect(!fam, 1) || atomic_load_explicit(&((__bridge NvImageHeap *)fam)->valid_wh, memory_order_acquire) == g_treg[tid].view_fam_wh;
    }
    return fam_is_valid(t);
}
static inline __attribute__((always_inline)) int treg_fam_pool_masked(int tid, __unsafe_unretained id<MTLTexture> t, uint64_t serial) {
    if (!atomic_load_explicit(&g_image_heap_comp_n, memory_order_relaxed)) return 0;
    if (tid > 0 && tid < g_ntreg && g_treg[tid].view == (__bridge void *)t) {
        void *fam = g_treg[tid].view_fam;
        if (__builtin_expect(!fam, 1)) return 0;
        __unsafe_unretained NvImageHeap *fo = (__bridge NvImageHeap *)fam; uint64_t fwh = g_treg[tid].view_fam_wh;
        fam_track_pool_serial(fo, serial, fwh);
        return atomic_load_explicit(&fo->valid_wh, memory_order_acquire) != fwh;
    }
    return fam_pool_masked(t, serial);
