// The textures live registrations name (DM_NVN_SHARED_IDLE, shared_idle_commit): each one's view, type and class views, and every parent of those. Caller holds g_rmu
static void treg_held_add(CFMutableSetRef s, void *v) { for (id<MTLTexture> t = (__bridge id<MTLTexture>)v; t; t = t.parentTexture) CFSetAddValue(s, (__bridge const void *)t); }
static CFMutableSetRef treg_held_set(void) {
    CFMutableSetRef s = CFSetCreateMutable(NULL, 0, NULL);
    for (int i = 0; i < g_ntreg; i++) { const treg_t *r = &g_treg[i]; if (!r->ok || r->gone) continue;
        if (r->view) treg_held_add(s, r->view); if (r->alt) treg_held_add(s, r->alt); if (r->alt2) treg_held_add(s, r->alt2); if (r->im) treg_held_add(s, r->im); }
    return s;
}
static nvn_hmap g_treg_serial = {.klen = 8};   // serial → first registered descriptor index + 1, under g_rmu
// DM_NVN_LS_STATS: whether texture serial ser has a descriptor in the texture pool (a shader may sample it); 1 when g_rmu is busy (the caller may hold it, or another thread)
static int ls_in_pool(uint64_t ser) { if (!os_unfair_lock_trylock(&g_rmu)) return 1; int in = nvn_hm_get(&g_treg_serial, &ser) != NULL; os_unfair_lock_unlock(&g_rmu); return in; }
// Texture ID views are valid for an epoch (view_ser), not for every serial table change: ser_sync takes the notes (ser_note) and sends only the IDs registered with a noted serial
// down the slow path; a change without a note starts a new epoch, which sends them all (what every g_ser_gen bump did before). A battle map in Fire Emblem: Fortune's Weave changes a
// few serials a frame (the per-stage program ring in bind_stages among them), and each change made the next pool walk (pool_gpu) resolve all ~5,000 IDs again, 2 ms a frame.
// Once any sparse mapping exists (nvn_sparse_gen) every change starts a new epoch, as before: a sparse texture's page-table changes bump no generation the ID cache follows. Under g_rmu
static uint64_t g_treg_ep = 1, g_ser_synced = 1;
static void ser_sync(void) {
