        if (g_rh_avail) MLOG("DM_NVN_IDLE_TEX_MB=%lld: %s", (long long)g_tidle_mb, g_tidle_mb ? "under this headroom to the memory limit, live textures unused for 3 s whose storage holds their content are released" : "idle live textures are kept"); }
