// Why a live entry stays (the footprint cap's sweep line, tidle_line): the first rule it fails, in the order the sweep tries them. TW_OK: it can go
enum { TW_OK, TW_NOID, TW_GONE, TW_POOL, TW_STAND, TW_UNUSED, TW_BUSY, TW_DISPLAY, TW_STORAGE, TW_PKG_OFF, TW_MIPDROP, TW_SHAPE, TW_TARGET, TW_SHARED, TW_PIN, TW_GPU, TW_N };
static const char *const g_tw_name[TW_N] = {"could go", "no texture ID", "ID gone", "named by a pool table", "a pool stand-in", "never bound", "bound within the wait", "display or video",
    "storage not its content", "packaged (DM_NVN_IDLE_TEX_PKG=0)", "mip drop", "view, sparse or buffer", "render-target or shader-write use", "named by another entry", "pinned or held",
    "storage the GPU wrote"};
// The serial's IDs: their latest use if all are idle and none is in a pool table, else 0 (*why the first rule an ID failed, if why); *t the registered description. Caller holds g_rmu
static uint32_t tidle_ids_w(uint64_t ser, uint32_t now, const tex_t **t, int *why) {
    uint32_t last = 0; int w = TW_NOID;
    for (int k = (int)(uintptr_t)nvn_hm_get(&g_treg_serial, &ser); k; k = g_treg[k - 1].next) {
