        // PR #1696), so its parent is what the residency set holds. The cache key takes the root's offsets and vc_get checks the root, so a cached view still names its range exactly
        id<MTLTexture> root = base; NSUInteger rl = l0, rs = s0;
        while (root.parentTexture) { rl += root.parentRelativeLevel; rs += root.parentRelativeSlice; root = root.parentTexture; }
        vc_key k; memset(&k, 0, sizeof k); k.pf = pf; k.tt = (uint8_t)tt; k.l0 = (uint32_t)rl; k.nl = (uint32_t)nl; k.s0 = (uint32_t)rs; k.ns = (uint32_t)ns; memcpy(k.sw, sw, 4);
        tl_ts_made = TSM_VC;
