    rp->view = (void *)CFBridgingRetain(v); rp->view_rid = v.gpuResourceID._impl;
    // the view's compressed family and geometry, fixed for the view's life (its heap is retained by its root texture, which the view holds): the bindings and pool walks read
    // them here instead of walking to the root and asking Metal for the owner on every bind (treg_fam_valid; NXNative cde54c161)
    { uint64_t fwh = 0; NvImageHeap *fo = fam_owner(v, &fwh); rp->view_fam = fo && fo->compressed ? (__bridge void *)fo : NULL; rp->view_fam_wh = rp->view_fam ? fwh : 0; }
