}
void arena_begin(void) {
    if (!g_arenas) { g_arenas = [NSMutableArray array]; g_sub_arenas = [NSMutableArray array]; }
    g_cur_arena = nil;
    int n; arena_trim(ARENA_IDLE, &n);
    if (g_arena_next) { NvArena *a = g_arena_next; g_arena_next = nil; [g_arenas removeObjectIdenticalTo:a]; [g_sub_arenas addObject:a]; g_cur_arena = a; }
}
void arena_commit(uint64_t fence) {
    for (NvArena *a in g_sub_arenas) { a->fence = fence; [g_arenas addObject:a]; }
    [g_sub_arenas removeAllObjects];
    g_arena_next = arena_share_on() && g_cur_arena && g_cur_arena->len <= ARENA_KEEP && g_cur_arena->used + 256 <= g_cur_arena->len ? g_cur_arena : nil;
    g_cur_arena = nil;
}
// An unqualified id * out-parameter is __autoreleasing under ARC; __strong avoids autoreleasing the arena buffer at every allocation.
// Measurements: docs/reference/frame-rate.md, Arena buffer ownership on allocation.
// arena_take: n bytes in the current arena (*buf its buffer), with their offset in it and their CPU and GPU addresses as of the allocation (upstream NXNative 1073e98b2). Use these,
// never g_cur_arena after it: any allocation in between (a helper that takes a slot of its own) can roll g_cur_arena over to a new block, and its base plus this offset then names
// the wrong arena (NieR:Automata's GPU hang: an argument block patched across cbsize_table's rollover pointed into the new arena)
typedef struct { size_t off; uint8_t *cpu; uint64_t gpu; } arena_at;
// arena_take_u / arena_alloc_u lend the block (ported from S2Arm 89ab9704, after NXNative e82aedb8d): *buf is not retained. Its NvArena is in g_sub_arenas from here until the
// submission's arena_commit, then in g_arenas until the GPU has passed that submission's fence (arena_new reuses, arena_trim drops, only blocks with fence <= g_done), so a caller
// that binds the block or writes through it while it encodes this submission needs no reference of its own: a retain and a release less per argument block, several a draw.
// A caller that keeps the buffer past the submission assigns it to a strong field (sh->ab_buf) or takes arena_take / arena_alloc, the retaining forms
static arena_at arena_take_u(size_t n, __unsafe_unretained id<MTLBuffer> *buf) {
    n = (n + 255) & ~(size_t)255;
    if (!g_cur_arena || g_cur_arena->used + n > g_cur_arena->len) {
        mu_lock(); g_cur_arena = arena_new(n); pthread_mutex_unlock(&g_mu);
