    return (arena_at){off, a->cpu + off, a->gpu + off};
}
static arena_at arena_take(size_t n, __strong id<MTLBuffer> *buf) { __unsafe_unretained id<MTLBuffer> b; arena_at a = arena_take_u(n, &b); *buf = b; return a; }
static size_t arena_alloc_u(size_t n, __unsafe_unretained id<MTLBuffer> *buf) { return arena_take_u(n, buf).off; }
static size_t arena_alloc(size_t n, __strong id<MTLBuffer> *buf) { return arena_take(n, buf).off; }   // the offset alone: for a caller that addresses its slot through *buf

// ---------- Draw state ----------
static struct {
    const prog_t *prog;
    const prog_t *cprog;       // compute program: NVN binds it apart from the graphics stages (see OP_BIND_PROGRAM in state_op)
    p_prim_restart restart;
    const prog_t *bst[5];      // program bound per stage (NVN stage bits 1 vertex 2 fragment 4 geometry 8 / 16 tessellation, indices as in NvProg.sh), see bind_stages
    blend_st blend[8]; color_st color; chmask_st chmask; ms_st ms; poly_st poly; ds_st ds;
    va_st attr[32]; int nattr; vs_st stream[16]; int nstream;
    NVNbufferRange vbuf[16];
    p_bind_buf ubo[6][16], ssbo[6][16]; uint16_t ubo_set[6];   // ubo_set: the uniform slots a bind has set (cbuf_slot: an empty binding the game made, apart from a slot never bound)
    uint64_t tex[6][NTEX], samp[6][128], img[6][32];
    uint32_t st_vmask[2], st_wmask[2], st_ref[2];
    p_poly_offset po; float vp[16][4]; float dr[2]; uint8_t vp_origin[16]; int has_vp; int depth_clamp; float line_width; uint8_t vp_sw[16][4];   // vp_sw: viewport swizzles XOR the identity (p_vp_swizzle)
    float blend_color[4], alpha_ref; int64_t copy_stride, copy_img_stride;   // alpha_ref: SetAlphaRef (at_bind)
    p_depth_bounds dbnd;   // SetDepthBounds as the game set it (draw resolves it, nvn_dbnd.h); off after state_reset, as on a new NVN queue
    uint8_t push[2][DMSH_PUSH_BLOCKS * DMSH_PUSH_SIZE];   // NVN2 push constants of the graphics stages and of compute, both blocks (p_push_const), bound as c[24]
    p_tf_bind tf[4]; int tf_on, rast_discard;   // capture buffers and enables; byte offsets and captured count stay on the GPU (nvn_feedback.inc)
    int tex_base, samp_base;   // host-table bases of the texture / sampler pool bound (OP_SET_TEX_POOL / OP_SET_SAMP_POOL), for handles read at replay from uniform buffers (encode_args)
} S;
// Explicit viewports carry the device origin at recording time, independently of
// the submitting queue's raster flip and later device changes. Legacy records and
// the implicit full-target viewport keep the current device-origin fallback.
static int vp_origin_ll(void) {
    return S.vp_origin[0] ? S.vp_origin[0] == NVN_WINDOW_ORIGIN_MODE_LOWER_LEFT + 1 : atomic_load_explicit(&g_origin_ll, memory_order_relaxed);
}
// A draw into a pass whose depth attachment is a lazy depth texture (g_pass.lz): one that writes depth gets the tiles under its scissor sc and its viewport's box v (x0, y0, x1, y1)
// mapped, with LZ_MARGIN round the viewport, before its command buffer runs. One that writes none (no test, or no depth write: NVN writes depth only with the test on, as dss_get) maps nothing
static void lz_draw(MTLScissorRect sc, const double v[4]) {
    if (!g_pass.lz || !S.ds.dt || !S.ds.dw || S.rast_discard) return;
    long x0 = MAX((long)sc.x, (long)floor(v[0]) - LZ_MARGIN), y0 = MAX((long)sc.y, (long)floor(v[1]) - LZ_MARGIN);
    long x1 = MIN((long)(sc.x + sc.width), (long)ceil(v[2]) + LZ_MARGIN), y1 = MIN((long)(sc.y + sc.height), (long)ceil(v[3]) + LZ_MARGIN);
    lz_map(g_pass.lz, g_pass.lz_tex, x0, y0, x1, y1, "a draw");
}
// The handle c2 holds at byte b, as encode_args fills the table (DRV2): a combined slot (past slot 31 the image there, tex_slot_h), a separate texture, else none
static uint64_t c2_handle(int stage, unsigned b) {
    if (b >= DMSH_C2_TEX && b < DMSH_C2_SEPTEX && !((b - DMSH_C2_TEX) % DMSH_C2_ROW)) return tex_slot_h(S.tex[stage], S.img[stage], (b - DMSH_C2_TEX) / DMSH_C2_ROW);
    if (b >= DMSH_C2_SEPTEX && b < DMSH_C2_SAMP && !((b - DMSH_C2_SEPTEX) % DMSH_C2_ROW)) return S.tex[stage][NVN_SEPTEX_SLOT0 + (b - DMSH_C2_SEPTEX) / DMSH_C2_ROW];
    if (b >= DMSH_C2_SAMP && b < DMSH_C2_SAMP + DMSH_C2_ROW * DMSH_C2_SEP_SLOTS && !((b - DMSH_C2_SAMP) % DMSH_C2_ROW)) return S.samp[stage][(b - DMSH_C2_SAMP) / DMSH_C2_ROW];
    return 0;
}
// Argument blocks are valid by generation, not by a flag per stage. Each change of a stage's bindings takes the next number of one sequence for every stage: g_args_gen for any binding,
// g_args_ugen for what its uniform slots point at only (OP_BIND_UBO, ubd_dirty). A block keeps the numbers it was written at (NvShader ab_gen / ab_ugen) and is reused only while both still
// hold, patched when only the uniform one moved (encode_args_). A flag cleared by whichever shader wrote the stage's block last told the next shader on that stage nothing: another shader
// of the stage could write in between, clear it, and leave the first one's block from before the change looking current (upstream PR #2249)
static uint64_t g_args_seq = 6, g_args_gen[6] = {1, 2, 3, 4, 5, 6}, g_args_ugen[6];   // the starting numbers differ per stage: a block is never current on a stage it was not written for
static uint64_t g_args_wrote[6];   // g_args_seq when the stage last wrote a block: a stage changed since then needs no new number (ubd_dirty)
// Blocks across passes and program changes (DM_NVN_ARGS_XPASS, args_xpass_ok). Two of the reasons g_args_gen moves say nothing about what a shader's block holds: a new render pass and
// a new program (args_dirty_soft). Every other one does, or is not proven not to, and moves g_args_hgen too (args_dirty, args_dirty_all): a block stays good for a later pass or for
// its shader's return after another program only while its stage's hard number holds. The pass rule itself guarded the arena, and an arena block outlives every pass of its
// submission (arena_take, arena_commit: blocks are reclaimed only after their submission's fence), so a block is reused only within the submission that encoded it
static uint64_t g_args_hgen[6] = {1, 2, 3, 4, 5, 6};
static int g_args_xpass = -1;   // DM_NVN_ARGS_XPASS: 1 (default) or 0 (blocks reused only within their pass, as before); read at the first encode (args_xpass_on)
static uint64_t g_stat_args_xpass;   // blocks reused (or patched) by that rule where the pass rule would have encoded them again
static uint8_t g_args_why[6], g_args_swhy[6], g_args_uwhy[6];   // the last reason each generation moved (AW_*; g_args_uwhy: 0 a uniform binding, 1 an inline update over one), for DM_NVN_ARGS_STATS
// Partial patches (DM_NVN_ARGS_PARTIAL, args_partial). A hard change of a texture, sampler or storage binding moves the hard generation as any other, but also says which kind moved,
// and for textures and samplers which slots (bit slot % 64), in a short history per stage: one entry per change, or the last entry widened while no block of the stage was written
// since it (g_args_wrote); when it is full its two oldest entries are joined, so an old block is patched for more than changed since it. Every other hard change empties it and raises
// its floor to its number: a block written before the floor (NvShader ab_pkh) is never patched. A block whose changes since it are all in the history is copied and only those kinds'
// entries are written again
enum { PK_TEX = 1, PK_SAMP = 2, PK_SSBO = 4, PK_BINST = 8, PK_UBO = 16, PK_POOL = 32, PK_X = 64 };   // PK_BINST (base instance) and PK_UBO (uniform slots) are not in the history: see args_partial; PK_X: allowed by the cross-pass rule only
enum { PK_RING = 8 };
typedef struct { uint64_t seq, tm, sm; uint8_t k; } pk_ent;   // the change's number (g_args_seq), the texture and sampler slots it moved, its kinds
static struct { uint64_t floor; int n; pk_ent e[PK_RING]; } g_args_pk[6];
static int g_pk_last;   // the kinds of the last partial patch (DM_NVN_ARGS_STATS: ast_encode_args)
static uint64_t g_args_sgen[6];   // the number of the stage's last soft change (a new pass or program, args_dirty_soft_w)
static inline void args_hard(int st, uint8_t w) { g_args_gen[st] = g_args_hgen[st] = ++g_args_seq; g_args_why[st] = w; }
// DM_NVN_BINDLESS: each stage's texture / sampler binding generation: a texture, sampler or image slot moved, or a hard change that may have moved them (restored state, a queue
// switch, an upgrade, one without a reason). Push constants, feedback, the host's encoders, drains and dispatches move no slot; registrations, guest writes and storage changes start
// a table epoch (bl_note). A slot table version checked at this number holds for a shader whose last check saw it (bl_note checks every entry against the slot path all the same)
static uint64_t g_bl_tgen[6];
static inline void args_dirty_w(int st, uint8_t w) {   // a hard change no partial patch takes
    args_hard(st, w); g_args_pk[st].floor = g_args_seq; g_args_pk[st].n = 0;
    if (w == AW_IMG || w == AW_RESTORE || w == AW_QUEUE || w == AW_UPGRADE || w == AW_OTHER) g_bl_tgen[st]++;
}
static void args_dirty_pk(int st, uint8_t w, uint8_t k, uint64_t tm, uint64_t sm) {   // a texture, sampler or storage binding of the stage changed (OP_BIND_TEX, OP_BIND_SAMP, OP_BIND_SSBO)
    args_hard(st, w); if (k & (PK_TEX | PK_SAMP)) g_bl_tgen[st]++;
    __typeof__(g_args_pk[0]) *r = &g_args_pk[st];
    if (r->n && r->e[r->n - 1].seq > g_args_wrote[st]) { pk_ent *e = &r->e[r->n - 1]; e->seq = g_args_seq; e->k |= k; e->tm |= tm; e->sm |= sm; return; }   // no block written since its last entry
    if (r->n == PK_RING) {   // full: the two oldest entries become one (the later number, both kinds and slots): a block between them sees more than changed since it, never less
        pk_ent *a = &r->e[0], *b = &r->e[1]; b->k |= a->k; b->tm |= a->tm; b->sm |= a->sm; memmove(r->e, r->e + 1, (PK_RING - 1) * sizeof r->e[0]); r->n--; }
    r->e[r->n++] = (pk_ent){g_args_seq, tm, sm, k};
}
static inline void args_dirty(int st) { args_dirty_w(st, AW_OTHER); }
static inline void args_dirty_ubo_w(int st, uint8_t w) { g_args_ugen[st] = ++g_args_seq; g_args_uwhy[st] = w; }
static inline void args_dirty_ubo(int st) { args_dirty_ubo_w(st, 0); }
static inline void args_dirty_all_w(uint8_t w) { for (int st = 0; st < 6; st++) args_dirty_w(st, w); }
static inline void args_dirty_all(void) { args_dirty_all_w(AW_OTHER); }
static inline void args_dirty_soft_w(uint8_t w) { for (int st = 0; st < 6; st++) { g_args_gen[st] = g_args_sgen[st] = ++g_args_seq; g_args_swhy[st] = w; } }   // a new pass or program: the pass rule's blocks go, the stages' bindings stand
static inline void args_dirty_soft(void) { args_dirty_soft_w(AW_PASS); }
// A binding of the stage changed since it last wrote a block so that every block of the stage is encoded in full (with the cross-pass rule, a hard change: after a soft one a block may still
// be reused; with partial patches, one the history does not hold: after a texture, sampler or storage change a block is patched, and the patch must see an update over its uniform slots)
static inline int args_changed(int st) {
    if (g_args_ugen[st] > g_args_wrote[st]) return 1;
    if (g_args_partial > 0) return g_args_pk[st].floor > g_args_wrote[st] || (g_args_xpass <= 0 && g_args_sgen[st] > g_args_wrote[st]);
    return (g_args_xpass > 0 ? g_args_hgen[st] : g_args_gen[st]) > g_args_wrote[st];
}
// A deferred inline update changes what the draws after it read through the uniform bindings it overlaps (they get a shadow): the argument blocks of those stages are written again.
// Only those: marking every stage made each later draw encode all of its blocks again, which with the updates kept across passes cost about 1.5 ms a frame in Breath of the Wild.
// Only the uniform slots change, so it marks them as a binding change does (args_dirty_ubo): a block whose shader reads its uniforms only as uniforms is patched (encode_args_)
static void ubd_dirty(uint64_t lo, uint64_t hi) {
    for (int st = 0; st < 6; st++) { if (args_changed(st)) continue;
        for (int r = 0; r < 16; r++) { const p_bind_buf *u = &S.ubo[st][r]; if (u->addr && lo < u->addr + ub_bound(u->size) && u->addr < hi) { args_dirty_ubo_w(st, 1); break; } } }   // as far as the shader can read it (ub_bound)
}
// NVN permits byte-aligned vertex streams; Metal drops the low two address bits. Keep an aligned copy in the submission arena.
// A CPU copy is safe only without GPU writers (including earlier submissions and sparse aliases). Otherwise copy on the GPU before
// opening the draw's encoder. Guest writes and pool remaps invalidate reuse; scratch copies themselves do not change guest memory.
// The same copy bounds a stream the draw reads past: Maxwell's fetch stops at the size the stream was bound with and reads zeros beyond it, Metal's reads on into
// whatever follows. Such a stream (vbuf_need) gets the bound bytes followed by zeros up to the last byte the draw reads. Super Mario Odyssey's agl mist composite
// draws 9 vertices from a 36-byte stream holding one full-screen triangle: the 6 vertices past it read the pool's next bytes, which drew a second triangle of the
// mist over the scene (hard-edged white slabs in the Cascade Kingdom)
#define VBUF_COPY_MAX (64u << 20)
typedef struct { uint64_t gpu, epoch, writes; uint32_t sbw; int npend; } vbuf_copy;
static nvn_hmap g_vbuf_unaligned = {.klen = 24};
static uint64_t g_vbuf_write_epoch;   // shader writes invalidate snapshots without disturbing indirect conversions of the same draw
static uint64_t g_vbuf_need[16];   // per stream: the bytes the draw reads when that is more than the bound size, else 0
static uint64_t vbuf_unaligned(uint64_t addr, uint64_t size, uint64_t need, int prepare) {   // need: 0, or the copy's length (more than size; zeros past size)
    uint64_t key[3] = {addr, size, need}, len = need > size ? need : size; vbuf_copy *c = nvn_hm_get(&g_vbuf_unaligned, key);
    if (c && !prepare) return c->gpu;
    if (c) {
        int changed = c->epoch != g_wr_epoch || c->writes != g_vbuf_write_epoch || c->sbw != g_sbw_gen || c->npend != g_npend;
        int dirty = size && (g_pend_over || g_sbw_over || (changed && nvn_sparse_gen())   // aliases may write through another guest address
            || (changed && sbw_hits(addr, addr + size))
            || (c->npend != g_npend && pend_last(addr, size) >= c->npend));
        if (!dirty) { c->epoch = g_wr_epoch; c->writes = g_vbuf_write_epoch; c->sbw = g_sbw_gen; c->npend = g_npend; return c->gpu; }
    }
    void *mb = NULL; uint64_t mo = 0;
    if (len > VBUF_COPY_MAX || (size && !mtl_addr(addr, size, &mb, &mo))) {
        if (need) RED_ONCE(121, "a draw reads %llu bytes of the vertex stream at %#llx, bound with %llu: no copy padded with zeros, so Metal reads past the bound range", (unsigned long long)need, (unsigned long long)addr, (unsigned long long)size);
        else RED_ONCE(120, "vertex stream at an address not 4-byte aligned (%#llx, %llu bytes) could not be copied: bound as it is, which Metal reads from the aligned address below", (unsigned long long)addr, (unsigned long long)size);
        return 0;
    }
    id<MTLBuffer> src = (__bridge id<MTLBuffer>)mb;
    int cpu = !size || (!pend_hits(addr, size) && !g_sbw_over && !sbw_hits(addr, addr + size) && !gw_live(addr, addr + size)
        && !nvn_sparse_gen() && nvn_host_readable(addr, size) && src.contents);   // a sparse mapping may alias this physical range
    if (!cpu && !prepare) MDIE("unaligned vertex stream was not prepared before its render encoder");
    id<MTLBuffer> ab; size_t off = arena_alloc((size_t)len, &ab);
    if (len > size) memset((uint8_t *)ab.contents + off + size, 0, (size_t)(len - size));   // the bytes past the bound range read as zeros
    if (cpu) { if (size) memcpy((uint8_t *)ab.contents + off, (const uint8_t *)src.contents + mo, (size_t)size); }
    else {
        g_blit_alias = 1;
        id<MTL4ComputeCommandEncoder> e = blit();   // lands deferred updates and orders all preceding GPU writes, including aliases
        g_blit_alias = 1;
        enc_b_copy_buffer(e, src, mo, ab, off, size);
    }
    g_vbuf_copies++; g_vbuf_copy_bytes += size;
    if (!c) { c = malloc(sizeof *c); if (!c) MDIE("cannot allocate vertex copy cache entry"); nvn_hm_put(&g_vbuf_unaligned, key, c); }
    *c = (vbuf_copy){ab.gpuAddress + off, g_wr_epoch, g_vbuf_write_epoch, g_sbw_gen, g_npend}; return c->gpu;
}
static int vattr_bytes(int f) {   // bytes of one element of NVN vertex format f; 0 = not a vertex format
    static const uint8_t c[12] = {1, 1, 1, 1, 2, 2, 2, 2, 2, 4, 4, 4};   // per component of 0x01-0x30 (one to four components): UNORM8 SNORM8 UINT8 SINT8, F16 UNORM16 SNORM16 UINT16 SINT16, F32 UINT32 SINT32
    if (f >= 0x01 && f <= 0x30) return c[(f - 1) % 12] * ((f - 1) / 12 + 1);
    if (f == 0x3D || f == 0x69 || f == 0x3F || f == 0x9A) return 4;   // 10:10:10:2, 11:11:10 float, BGRA8
    if (f >= 0x51 && f <= 0x68) { int i = (f - 0x51) >> 1; return (i / 3 + 1) * (1 << (i % 3)); }   // integers read as floats (vconv_i2f): 8 / 16 / 32-bit components
    return 0;
}
// The last element a draw reads from stream st: [*last]; 0 = not known on the CPU (indirect, multi-draw, or a per-vertex stream of an indexed draw, whose indices are not scanned here)
static int vstream_last(int st, const p_draw *dw, const p_draw_idx *di, uint64_t *last) {
    if ((unsigned)st >= 16) return 0;   // an absent stream has no known vertex range (vconv_bind binds zero for it)
    if ((dw && (dw->ind || dw->mdi_cnt)) || (di && (di->ind || di->mdi_cnt)) || (!dw && !di)) return 0;
    uint32_t stride = S.stream[st].stride, div = S.stream[st].divisor;
    if (!stride) { *last = 0; return 1; }
    if (div) { int32_t n = dw ? dw->instances : di->instances, b = dw ? dw->base_instance : di->base_instance; if (n < 1) n = 1; if (b < 0) return 0; *last = (uint64_t)b + (uint64_t)(n - 1) / div; return 1; }
    if (!dw || dw->first < 0 || dw->count <= 0) return 0;
    *last = (uint64_t)dw->first + (uint64_t)dw->count - 1; return 1;
}
static void vbuf_need(const nvn_refl *rf, const p_draw *dw, const p_draw_idx *di) {   // fills g_vbuf_need for the inputs the vertex shader reads
    memset(g_vbuf_need, 0, sizeof g_vbuf_need);
    for (int v = 0; rf && v < rf->nv; v++) {
        int a = rf->v[v].nvn; if (a >= 32 || a >= S.nattr || !S.attr[a].fmt) continue;
        int st = S.attr[a].stream, eb = vattr_bytes(S.attr[a].fmt); uint64_t last;
        if (st >= 16 || !eb || !S.vbuf[st].address || !vstream_last(st, dw, di, &last)) continue;
        uint64_t end = last * S.stream[st].stride + S.attr[a].offset + (uint64_t)eb;
        if (end > S.vbuf[st].size && end > g_vbuf_need[st]) g_vbuf_need[st] = end;
    }
}
static void vbuf_prepare_(const nvn_refl *rf, const p_draw *dw, const p_draw_idx *di);
static void vbuf_prepare(const nvn_refl *rf, const p_draw *dw, const p_draw_idx *di) { int pf = pf_enter(PF_VBUF); vbuf_prepare_(rf, dw, di); pf_leave(pf); }   // page-ins by part (PF_VBUF)
static void vbuf_prepare_(const nvn_refl *rf, const p_draw *dw, const p_draw_idx *di) {   // before the draw's render encoder: rf, dw / di the draw's vertex shader and record (NULL: no bounds)
    static uint64_t sub, gen, sparse;
    uint64_t pool_gen = atomic_load_explicit(&g_pool_gen, memory_order_acquire), sparse_gen = nvn_sparse_gen();
    if (sub != g_sub_serial || gen != pool_gen || sparse != sparse_gen) nvn_hm_clear(&g_vbuf_unaligned, free);
    vbuf_need(rf, dw, di);
    for (int s = 0; s < 16; s++) if (((S.vbuf[s].address & 3) && S.vbuf[s].size) || g_vbuf_need[s]) {   // an empty stream no draw reads past has no bytes to align
        if (g_vbuf_need[s]) { static int once; if (!once++) MLOG("a draw reads %llu bytes of vertex stream %d, bound with %llu: bound as a copy with zeros past the bound range, as Maxwell's fetch reads them", (unsigned long long)g_vbuf_need[s], s, (unsigned long long)S.vbuf[s].size); }
        vbuf_unaligned(S.vbuf[s].address, S.vbuf[s].size, g_vbuf_need[s], 1);
    }
    sub = g_sub_serial; gen = pool_gen; sparse = sparse_gen;
}
// Resolved guest streams are separate from the table cache: vconv_bind may overwrite a stream's table slot.
// Take the pool generation before resolving, so a concurrent pool change forces a fresh lookup next time.
static unsigned vs_streams(const nvn_refl *rf) {   // the streams the vertex shader's inputs read (bit per stream)
    unsigned m = 0;
    for (int v = 0; rf && v < rf->nv; v++) { int a = rf->v[v].nvn; if (a < 32 && a < S.nattr && S.attr[a].fmt && S.attr[a].stream < 16) m |= 1u << S.attr[a].stream; }
    return m;
}
static void ix_minmax(const void *p, int isz, int32_t count, uint32_t *mn, uint32_t *mx);
// A failed whole-stream lookup can still prove a prefix for a direct indexed draw whose indices the CPU sees as the GPU will read them (upstream NXNative 79555b676): none
// pending from a copy, update or fill, no GPU write over them, no sparse aliases, all of them readable. Restart indices only make the proof more conservative
static int vbuf_index_last_(const p_draw_idx *di, uint64_t *last);
static int vbuf_index_last(const p_draw_idx *di, uint64_t *last) { int pf = pf_enter(PF_IDX); int r = vbuf_index_last_(di, last); pf_leave(pf); return r; }   // page-ins by part (PF_IDX)
static int vbuf_index_last_(const p_draw_idx *di, uint64_t *last) {
    if (!di || di->ind || di->mdi_cnt || di->count <= 0 || !di->ibuf || (unsigned)di->itype > 2) return 0;
    int isz = 1 << di->itype;
    uint64_t addr = di->ibuf, bytes = (uint64_t)di->count * isz, end = addr + bytes;
    if (end < addr || (addr & (isz - 1)) || nvn_sparse_gen()) return 0;
    void *mb; uint64_t mo;
    if (!mtl_addr(addr, bytes, &mb, &mo) || mem_readable((const void *)(uintptr_t)addr, bytes) < bytes) return 0;
    if (pend_hits(addr, bytes) || g_sbw_over || sbw_hits(addr, end) || gw_live(addr, end)) return 0;
    const uint8_t *src = [(__bridge id<MTLBuffer>)mb contents];
    if (!src) return 0;
    uint32_t mn, mx;
    ix_minmax(src + mo, isz, di->count, &mn, &mx);
    int64_t hi = (int64_t)mx + di->base_vertex;
    if ((int64_t)mn + di->base_vertex < 0 || hi > UINT32_MAX) return 0;
    *last = (uint64_t)hi;
    return 1;
}
// A draw can bind a stream from an offset inside a buffer with the buffer's whole size (Snowdrop's character preview and UI, upstream NXNative c96c45e9b): the declared tail can run
// past its pool while every vertex the draw fetches is mapped. A failed lookup is narrowed only when the draw and every format on the stream give a known end: the bytes the
// draw reads from stream st, or 0
static uint64_t vbuf_draw_bytes(int st, const nvn_refl *rf, const p_draw *dw, const p_draw_idx *di) {
    uint64_t last, attr_end = 0;
    for (int v = 0; rf && v < rf->nv; v++) {
        int a = rf->v[v].nvn;
        if (a >= 32 || a >= S.nattr || !S.attr[a].fmt || S.attr[a].stream != st) continue;
        int width = vattr_bytes(S.attr[a].fmt);
        if (!width) return 0;
        uint64_t end = S.attr[a].offset + (uint64_t)width;
        if (end > attr_end) attr_end = end;
    }
    if (!attr_end || (!vstream_last(st, dw, di, &last) && (S.stream[st].divisor || !vbuf_index_last(di, &last)))) return 0;
    return last * S.stream[st].stride + attr_end;
}
// Returns the first stream the vertex shader reads (rf) whose non-zero address is in no memory pool, or -1. Such a slot would keep the buffer an earlier draw bound
// there, so the caller skips the draw, as for an index buffer in no pool; a stream with address 0 reads the zero buffer through the vertex descriptor (ZERO_ATTR).
// dw / di: the draw (NULL: no bounds), whose fetches may resolve a mapped prefix of a stream bound past its pool (vbuf_draw_bytes); such a binding holds for this draw only
static unsigned g_vbuf_prefix_mask;
static uint64_t g_vbuf_prefix_bytes[16];   // the same limit bounds the draw's format conversion (vconv_bind)
// Slot 30's 64 bytes (upstream ef8b25d2c): zeros at offset 0, for inactive shadow inputs and formats with no Metal vertex format; (0, 0, 0, 1.0) at offset 16, which an attribute the
// draw does not set reads (pso_desc), as NVN / Maxwell give an absent attribute: Splatoon Raiders' depth shader reads attribute 12.w of a draw that sets 0-9 as its opacity
static id<MTLBuffer> vertex_constants(void) {
    static id<MTLBuffer> b;
    if (!b) { b = [g_dev newBufferWithLength:64 options:MTLResourceStorageModeShared]; res_add(b); ((uint32_t *)b.contents)[7] = 0x3f800000; }
    return b;
}
static int bind_vbufs(id<MTL4RenderCommandEncoder> en, const nvn_refl *rf, const p_draw *dw, const p_draw_idx *di) {
    static struct { uint64_t addr, size, gpu, gen; } cache[16];
    uint64_t gen = atomic_load_explicit(&g_pool_gen, memory_order_acquire);
    unsigned used = vs_streams(rf); int bad = -1;
    // Only the streams the vertex shader's inputs read are bound: the pipeline's vertex descriptor names no other (pso_desc takes the same inputs), and a game leaves the streams
    // of earlier meshes bound, each looked up and compared draw after draw (docs/reference/frame-rate.md, "Vertex streams the shader does not read looked up every draw").
    // With no vertex shader (a draw without one, or a unit test) every bound stream is, as before. Unread streams still count in ubd_conflict and vbuf_prepare, and their table
    // slots keep what they held, which no pipeline of this draw reads
    unsigned want = rf ? used : 0xffffu;
    g_vbuf_prefix_mask = 0;
    for (int s = 0; s < 16; s++) {
        uint64_t addr = S.vbuf[s].address, gpu;
        if (!addr || !(want >> s & 1)) continue;
        if (((addr & 3) && S.vbuf[s].size) || g_vbuf_need[s]) { uint64_t c = vbuf_unaligned(addr, S.vbuf[s].size, g_vbuf_need[s], 0); if (c) { cache[s].addr = 0; enc_r_vbuf(en, VB_SLOT(s), c); continue; } }   // not cached: the copy is per submission
        uint64_t size = S.vbuf[s].size ? S.vbuf[s].size : 1;
        if (g_vbuf_cache && cache[s].addr == addr && cache[s].size == size && cache[s].gen == gen) { gpu = cache[s].gpu; g_vbuf_reuse++; }
        else {
            void *mb; uint64_t mo; g_vbuf_resolve++;
            if (!mtl_gpu_addr(addr, size, &mb, &mo, &gpu)) {
                cache[s].addr = 0;
                uint64_t bytes = !(addr & 3) && (used >> s & 1) ? vbuf_draw_bytes(s, rf, dw, di) : 0;
                if (bytes && bytes < size && mtl_gpu_addr(addr, bytes, &mb, &mo, &gpu)) {
                    g_vbuf_prefix_mask |= 1u << s; g_vbuf_prefix_bytes[s] = bytes;
                    PD("v %llu stream %d at %#llx: mapped %llu of %llu declared bytes for this draw", g_stat_pass, s, (unsigned long long)addr, (unsigned long long)bytes, (unsigned long long)size);
                    enc_r_vbuf(en, VB_SLOT(s), gpu);   // this lookup proved only the current draw's range: not cached
                    continue;
                }
                if (bad < 0 && used >> s & 1) bad = s;   // a stale stream no input reads is no matter
                continue;
            }
            cache[s].addr = addr; cache[s].size = size; cache[s].gpu = gpu; cache[s].gen = gen;
        }
        enc_r_vbuf(en, VB_SLOT(s), gpu);
    }
    static uint64_t zero_gpu;
    if (!zero_gpu) zero_gpu = vertex_constants().gpuAddress;
    enc_r_vbuf(en, 30, zero_gpu);
    return bad;
}
// The per-draw layout block of a pulling pipeline (dm/gfx/tools/dmsh_pull.metal dm_vlayout, at buffer 16): per stream the base address, stride and divisor, per NVN attribute (all 32)
// its state word. A base address is kept 4-byte aligned, its low bits moved into its attributes' offsets (dm_fetch reads whole words where the element is aligned); elements keep their
// components' alignment as for Metal's own fetch (16-bit components at even addresses, packed 32-bit words at multiples of 4). An attribute whose stream has no buffer reads zeros,
// as through the zero buffer (t_pull.m)
enum { PULL_SLOT = 16 };   // = dmsh_pull.py SLOT
typedef struct { uint64_t base; uint32_t stride, divisor; } pull_stream;
typedef struct { pull_stream s[16]; uint32_t attr[32]; } pull_layout;
_Static_assert(sizeof(pull_layout) == 384, "dmsh_pull.metal dm_vlayout");
static void pull_layout_fill(pull_layout *Lp, const nvn_refl *rf, const p_draw *dw, const p_draw_idx *di) {   // rf, dw / di: the vertex shader and the draw, for a mapped prefix (bind_vbufs)
    pull_layout L; memset(&L, 0, sizeof L); uint32_t lo[16] = {0};
    unsigned want = rf ? vs_streams(rf) : 0xffffu;   // as bind_vbufs: the streams the shader's inputs read (every one with no shader given); an attribute of another stream is never fetched
    for (int st = 0; st < 16; st++) {
        uint64_t addr = S.vbuf[st].address, gpu; void *mb; uint64_t mo;
        if (!addr || !(want >> st & 1)) continue;
        if (!g_vbuf_need[st] || !(gpu = vbuf_unaligned(addr, S.vbuf[st].size, g_vbuf_need[st], 0))) {   // a stream the draw reads past: its copy padded with zeros (vbuf_need)
            uint64_t size = S.vbuf[st].size ? S.vbuf[st].size : 1;
            if (!mtl_gpu_addr(addr, size, &mb, &mo, &gpu)) {
                uint64_t bytes = !(addr & 3) ? vbuf_draw_bytes(st, rf, dw, di) : 0;
                if (!bytes || bytes >= size || !mtl_gpu_addr(addr, (bytes + 3) & ~3ull, &mb, &mo, &gpu)) continue;   // the pulling shader loads whole words
            }
        }
        L.s[st].base = gpu & ~3ull; lo[st] = (uint32_t)(gpu & 3); L.s[st].stride = S.stream[st].stride; L.s[st].divisor = S.stream[st].divisor;
    }
    for (int a = 0; a < 32 && a < S.nattr; a++) {
        va_st v = S.attr[a];
        if (!v.fmt) continue;   // format 0: dm_fetch gives the absent attribute's (0, 0, 0, 1.0)
        if (v.stream < 16) {   // a stream with no buffer keeps its format word, so dm_fetch reads zeros for it rather than the absent default (upstream ef8b25d2c)
            if (!(want >> v.stream & 1)) continue;
            if (!L.s[v.stream].base && S.vbuf[v.stream].address) RED_ONCE(159, "vertex stream %d's buffer %#llx is in no memory pool; its attributes read zeros", v.stream, (unsigned long long)S.vbuf[v.stream].address);
            v.offset += lo[v.stream];
        }
