static inline int vin_fmt(const pso_key *k, int a) { return a >= 32 ? 0 : k ? pso_key_attr(k, a).fmt : a < S.nattr ? S.attr[a].fmt : 0; }   // as pso_key_fill fills the key
// The routes vin_on gives a pipeline: VIN_SHADOW, the shadow-input entry point; VIN_I2F, native integer-to-float fetch (vin_i2f). 0: every attribute that needs it is converted on the CPU
enum { VIN_SHADOW = 1, VIN_I2F = 2 };
static inline int vin_i2f_native(int f) { int ib, is; return vconv_i2f(f, &ib, &is) && ib < 32; }   // the integer-read-as-float formats Metal's fetch converts
// The component type input v takes its attribute as: the class of the attribute's format when a shadow of that class exists (on & VIN_SHADOW; an 8 / 16-bit integer-read-as-float
// format goes to the float one with VIN_I2F as well), else the declared type
static int vin_ct(const nvn_refl *rf, int v, int f, int on) {
    int ct = rf->v[v].ct, ib, is;
    if (!(on & VIN_SHADOW) || ct == NVN_CT_FLOAT) return ct;
    int want = vconv_ncomp(f) || ((on & VIN_I2F) && vin_i2f_native(f)) ? NVN_CT_FLOAT : vconv_int(f, &ib, &is) ? (is ? NVN_CT_INT : NVN_CT_UINT) : ct;
