}
// The routes of this pipeline (k, or the current state at bind time: both give the same answer): VIN_I2F unless a capture or a switch keeps the CPU conversion; VIN_SHADOW when
// some input takes a shadow and the library loads. Asked by pso_desc and vconv_bind alike, so the converted attributes and the pipeline's buffer slots agree
static int vin_on(NvShader *vs, const pso_key *k, int tf) {
    const nvn_refl *rf = &vs->rf;
    if (tf || vin_cpu()) return 0;
    int on = vin_i2f() ? VIN_I2F : 0;
    if (!rf->has_vin) return on;
    int need = 0; for (int v = 0; v < rf->nv && !need; v++) need = vin_ct(rf, v, vin_fmt(k, rf->v[v].nvn), on | VIN_SHADOW) != rf->v[v].ct;
