static int ix_range_(const p_draw_idx *di, uint32_t *mn, uint32_t *mx);
static int ix_range(const p_draw_idx *di, uint32_t *mn, uint32_t *mx) { int pf = pf_enter(PF_IDX); int r = ix_range_(di, mn, mx); pf_leave(pf); return r; }   // page-ins by part (PF_IDX)
static int ix_range_(const p_draw_idx *di, uint32_t *mn, uint32_t *mx) {
