// g_compact_periods: periods that may hold recaptured bases, handed over and not written yet; g_compact_closed: the last of them is handed over (compact_close);
// g_compact_bad: one was not written, or a noted base was not captured again: the old files stay (arch_compact_finish); g_compact_busy: such bases
// not captured because another capture of their vertex-stage function did not return in time (fn_claim); g_compact_once: arch_compact_finish ran (the last period's write and
// compact_close may both come to it)
static _Atomic int g_compact_periods, g_compact_closed, g_compact_bad, g_compact_busy, g_compact_once;
// A base, compute or task / mesh pipeline the prewarm took from a file the compaction replaces (compact_note), captured again after the first frame (compact_step). kind: 0 a
// render base (vd: it has a vertex layout), 1 a compute pipeline, 2 a task / mesh pipeline
@interface CompactNote : NSObject { @public MTL4PipelineDescriptor *d; int kind, vd; } @end
@implementation CompactNote @end
// The compaction's captures (compact_step). g_cnotes: the noted pipelines in the order noted, one per index key (g_cnote_keys; a pipeline with no key is noted each time),
// g_cnote_next: the next to capture; under g_cnote_lock. g_cpass: 0 none yet, 1 scheduled (waiting for the first frame and the rest, compact_ready), 2 capturing, 3 closed (every note
// taken and its last period handed over: compact_close), 4 stopped (the process is ending; the old files stay). g_cpass_held: held (heat, Low Power Mode, the background), when
// the timer's flushes go on (arch_hand_over). g_cpass_subs: submissions while scheduled (a run that never presents)
static os_unfair_lock g_cnote_lock = OS_UNFAIR_LOCK_INIT; static NSMutableArray<CompactNote *> *g_cnotes; static NSMutableSet<NSNumber *> *g_cnote_keys; static NSUInteger g_cnote_next;
// Keep the crash-recovery guard if a compaction still fails in Metal. Markers name the OS build and capture method: a marker from the old archive-import path must not
// disable the safer original-function capture. A failed flush of this method disables compaction on this OS build until it changes; ordinary archive reads remain available.
static NSString *arch_compact_marker(void) { return [g_arch_dir stringByAppendingPathComponent:@"compacting"]; }
static NSString *arch_os_build(void) { char b[64] = ""; size_t n = sizeof b; sysctlbyname("kern.osversion", b, &n, NULL, 0); return [NSString stringWithFormat:@"os\t%s\n", b]; }
static NSString *arch_compact_stamp(void) { return [arch_os_build() stringByAppendingString:@"capture\toriginal-functions-v1\n"]; }
static int arch_compact_allowed(void) {
    NSString *m = [NSString stringWithContentsOfFile:arch_compact_marker() encoding:NSUTF8StringEncoding error:nil];
    if (!m) return 1;
    if ([m isEqualToString:arch_compact_stamp()]) { MLOG("[RED] pipeline archive: a compaction did not finish on this system build (issue #342): the files are left as they are"); return 0; }
    unlink(arch_compact_marker().fileSystemRepresentation);   // another system build or capture method: try once more
    return 1;
}
// A compaction that ended without removing the old files (g_compact_bad: a flush failed, or a base was not captured again) leaves them beside the new files that hold their bases
// again, and the next start, with more files still, tried again: a failure that repeats added a set of copies every start. compact_failed.tsv names the system build and the plain
// files there were when it failed (old and new; a file Metal refused is removed at the start, pso4_init; not one the start kept but could not open or read, g_arch_unusable); a start of that system build with all of them still there tries again only once more than PSO_ARCH_COMPACT files were added since
static NSString *arch_compact_fail_path(void) { return [g_arch_dir stringByAppendingPathComponent:@"compact_failed.tsv"]; }
static NSArray<NSString *> *arch_plain_files(void) {   // the folder's plain files (<seq>.mtl4a), by name
    NSArray<NSString *> *a = [[NSFileManager.defaultManager contentsOfDirectoryAtPath:g_arch_dir error:nil] filteredArrayUsingPredicate:[NSPredicate predicateWithFormat:@"self ENDSWITH '.mtl4a'"]];
    NSMutableArray<NSString *> *r = [NSMutableArray array]; for (NSString *n in a) if (!arch_name_kind(n)) [r addObject:n];
    return [r sortedArrayUsingSelector:@selector(compare:)];
}
// plain files pso4_init kept but could not open or read (an open() error, refused[i] 0), by name: never in arch_compact_retry's set, so the note leaves them out too, or a
// failed compaction would run again at every start while such a file stays
static NSMutableSet<NSString *> *g_arch_unusable;
static void arch_compact_fail_note(void) {
    NSMutableArray<NSString *> *f = [arch_plain_files() mutableCopy]; if (g_arch_unusable) [f removeObjectsInArray:g_arch_unusable.allObjects];
    NSString *t = [NSString stringWithFormat:@"# pipeline archive: a compaction of these files did not finish; not tried again on them (nvn_mtl.m, arch_compact_retry)\n%@%@\n", arch_os_build(),
                   [f componentsJoinedByString:@"\n"]];
    [t writeToFile:arch_compact_fail_path() atomically:YES encoding:NSUTF8StringEncoding error:nil];
}
static int arch_compact_retry(NSArray<NSString *> *runf) {   // runf: the plain files opened, by path
    NSString *m = [NSString stringWithContentsOfFile:arch_compact_fail_path() encoding:NSUTF8StringEncoding error:nil];
    if (!m) return 1;
    NSMutableSet<NSString *> *have = [NSMutableSet set]; for (NSString *p in runf) [have addObject:p.lastPathComponent];
    NSMutableArray<NSString *> *named = [NSMutableArray array]; NSString *os = nil;
    for (NSString *l in [m componentsSeparatedByString:@"\n"]) { if (!l.length || [l hasPrefix:@"#"]) continue; if ([l hasPrefix:@"os\t"]) os = [l stringByAppendingString:@"\n"]; else [named addObject:l]; }
    int all = 1; for (NSString *n in named) all &= [have containsObject:n];
