    if (!g_arch_probe_path) { g_arch_probe_path = [NSMutableArray array]; g_arch_probe_keys = [NSMutableArray array]; }
    arch_probe *np = realloc(g_arch_probe, (size_t)(g_arch_probe_n + 1) * sizeof *np);
    if (!np) return;   // no memory for it: the file is just not probed
    g_arch_probe = np; memset(&np[g_arch_probe_n], 0, sizeof *np); np[g_arch_probe_n].complete = complete;
    np[g_arch_probe_n].scan = !(arch_name_kind(path.lastPathComponent) == 2 && !arch_pre_mine(path));   // another program of the application holds its bases there: this one's lookups miss in it by design
    [g_arch_probe_path addObject:path]; [g_arch_probe_keys addObject:keys ?: (id)NSNull.null];
    void *a_ = (__bridge void *)a; g_arch_probe_n++; nvn_hm_put(&g_arch_probe_ix, &a_, (void *)(uintptr_t)g_arch_probe_n);
}
// After the prewarm (warm_finish), once: every lookup of its lists has asked the files by then. An open archive stays usable for the rest of the run after its file is removed, as
// after a compaction. Returns the files removed (the tests)
static int arch_probe_settle(void) {
    if (!g_arch_probe_n || atomic_exchange(&g_arch_probe_done, 1)) return 0;
    int stamped = 0, gone = 0, open = 0; unsigned long long bytes = 0;
    for (int i = 0; i < g_arch_probe_n; i++) {
        arch_probe *p = &g_arch_probe[i]; NSString *path = g_arch_probe_path[i]; id keys = g_arch_probe_keys[i];
        uint32_t asks = atomic_load(&p->asks), hits = atomic_load(&p->hits), nmiss = atomic_load(&p->nmiss);
        if (![NSFileManager.defaultManager fileExistsAtPath:path]) continue;   // a compaction or the prebuild's trim removed it meanwhile
        if (hits) { stamped += arch_keys_write(arch_keys_path(path), keys == NSNull.null ? nil : keys, keys == NSNull.null ? 0 : p->complete); continue; }   // no index: an empty one, not complete, looks the same
        if (nmiss >= (uint32_t)g_arch_probe_miss || (p->scan && asks >= (uint32_t)g_arch_probe_asks)) {
            unsigned long long sz = [[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil] fileSize];
            if (!unlink(path.fileSystemRepresentation)) { gone++; bytes += sz; }
            unlink(arch_keys_path(path).fileSystemRepresentation);
            continue;
        }
        open++;
    }
    MLOG("pipeline archive: %d files without a chain stamp probed: %d served this chain's pipelines and were stamped, %d served none and were removed (%.1f MB), %d undecided (DM_PSO_KEEP_OLD=1 keeps them all)",
         g_arch_probe_n, stamped, gone, bytes / 1048576.0, open);
    return gone;
}
// A pipeline from the archive: the file the index names for its key alone, else each file without a complete index (the bundle first among the p files, which plain skips: the
// device's own p files never hold a base with a vertex layout or a compute pipeline). *from_run: it came from a run file this compaction takes, so the compacting prewarm captures it
// again. A miss in the named file asks the bundle too: the key names no translation chain (lib_name), so after an app update with a new chain and a new bundle a device file of the
// old chain was named for bases the bundle holds, and each was compiled and captured again into a p file that then shadowed the bundle for good. A plain lookup (a base with a
// vertex layout) asks the bundle before the device's own files too: pso_offline.py compiles the layout base of every prewarm R row into it (as pso_desc describes it), so a first
// start takes them from the app instead of compiling them (pso_build_ex counts them, g_pb_bundle_vd). A bundle hit is never from_run: arch_compact_takes knows only the device's
// files. A compute lookup never asks the bundle here: cps_new asked it first, with the same descriptor
static int arch_compact_takes(id<MTL4Archive> a);
static id<MTL4Archive> g_arch_bundle;   // pso_bundle_open
// found: the file it came from (pre_pair credits a prebuild file by it, pre_credit)
static id arch_lookup_in(MTL4PipelineDescriptor *d, int plain, int *from_run, id<MTL4Archive> __strong *found) {
    if (from_run) *from_run = 0;
    if (found) *found = nil;
    int compute = [d isKindOfClass:MTL4ComputePipelineDescriptor.class];
    id (^ask)(id<MTL4Archive>) = ^id(id<MTL4Archive> a) {
        atomic_fetch_add_explicit(&g_arch_asks, 1, memory_order_relaxed);
        return compute ? (id)[a newComputePipelineStateWithDescriptor:(MTL4ComputePipelineDescriptor *)d error:nil] : (id)[a newRenderPipelineStateWithDescriptor:d error:nil];
    };
    uint64_t k = g_arch_ix.n ? arch_key(d) : 0;
    id<MTL4Archive> named = k ? (__bridge id<MTL4Archive>)nvn_hm_get(&g_arch_ix, &k) : nil;
    if (named) {
        id ps = ask(named);
        arch_probe_note(named, ps != nil, 1);
        if (ps && from_run) *from_run = arch_compact_takes(named);
        if (ps && found) *found = named;
        if (!ps && !compute && g_arch_bundle && named != g_arch_bundle && (ps = ask(g_arch_bundle)) && found) *found = g_arch_bundle;
        return ps;
    }
    if (!plain) for (id<MTL4Archive> a in g_arch4p) { id ps = ask(a); arch_probe_note(a, ps != nil, 0); if (ps) { if (found) *found = a; return ps; } }
    else if (g_arch_bundle && !compute) { id ps = ask(g_arch_bundle); if (ps) { if (found) *found = g_arch_bundle; return ps; } }   // the bundle is never probed (arch_probe_note): no file of the device's
    for (id<MTL4Archive> a in g_arch4) { id ps = ask(a); arch_probe_note(a, ps != nil, 0); if (ps) { if (from_run) *from_run = arch_compact_takes(a); if (found) *found = a; return ps; } }
    return nil;
}
static id arch_lookup(MTL4PipelineDescriptor *d, int plain, int *from_run) { return arch_lookup_in(d, plain, from_run, NULL); }
// the current period, and the prebuild's own while it runs (arch_pre_begin): its bases go into files of their own, so that a later prebuild can tell them from the draws'
static ArchEpoch *g_ep, *g_ep_pre; static os_unfair_lock g_ep_lock = OS_UNFAIR_LOCK_INIT;
static _Atomic uint64_t g_ep_t0;   // when the draws' period (g_ep) began (bp_now): a prewarm's timer flush hands it over once it is old enough (arch_warm_flush_due)
static _Atomic uint64_t g_arch_deaths;   // compiler-service deaths this run: every unwritten period made before the latest one is untrusted, including ones already handed over
static int g_arch_cap;   // compiles are captured (an archive folder, a serializer): immutable after pso4_init
static dispatch_group_t g_arch_pending;   // periods handed over and not written yet
static _Atomic uint64_t g_pb_built, g_pb_archived, g_pb_reused, g_pb_spec, g_pb_base_ns;
static _Atomic uint64_t g_pb_bundle_vd;   // of g_pb_archived, bases with a vertex layout from the archive bundled with the app (pso_offline.py's layout bases, the prewarm list's R rows)
// Time by kind, all threads (the 'pipelines up to frame' line): archive lookups that found the base / found none, specializations, base compiles; predictions (submit thread)
static _Atomic uint64_t g_pt_hit_n, g_pt_hit_ns, g_pt_miss_n, g_pt_miss_ns, g_pt_spec_ns, g_pt_comp_ns, g_pt_pred_n, g_pt_pred_ns, g_pp_done_n;   // bases compiled / taken from the archive / reused, specializations
// Of those archive lookups (found or not), the ones made on the submit thread, and their time; and the compile 0 calls on the submit thread that waited for another thread's archive
// lookup of the same base (pso_build_ex, PbaseBuild.looked), and their time: the phone log's split of where the lookups ran and what a draw paid for a worker's (pso_bg_look)
static _Atomic uint64_t g_pt_sub_n, g_pt_sub_ns, g_lw_n, g_lw_ns;
typedef struct { const void *vf, *ff; uint32_t samples, a2c, rast, topo, amp, off; uint32_t va[31][3], vl[31][3]; } pbase_key;   // what a base depends on: pso_desc's descriptor less the colour attachments; off: its functions without the border corrections (fn_off)
static nvn_hmap g_pbase = {.klen = sizeof(pbase_key)};
// Bases the archives do not have. After the prepare step nothing adds to the open archives in a run (arch_adopt_prebuilt clears this map before the first frame when it opens the
// files the prebuild just wrote), so a miss holds for the rest of the process: a later call for the base skips the search
// (a compile 0 one returns nil, a compiling one goes straight to the compiler), and g_pbase, looked at first, takes the base once it is built. Without it every draw of a pipeline
// whose build the full table refused (pso_pend_demand) searched every archive again while it drew with its stand-in: Ocarina of Time's castle town, 9,208 searches / 30.5 s in
// 300 frames, CPU translation 114 ms a frame (PR #1825)
static nvn_hmap g_pbase_miss = {.klen = sizeof(pbase_key)};
// Only callers for the same base wait on this group; unrelated bases compile in parallel.
// compiled: its owner asked the compiler (a compile 0 owner only looks in the archive, and a waiter that needs the base builds it itself when that found none).
// looked: left once the owner has looked in the archives (or skipped them for a base known missing), found: the base that found, set before; a compile 0 waiter waits on it
// (upstream edc7eff9c, PR #2770)
@interface PbaseBuild : NSObject { @public dispatch_group_t done, looked; id<MTLRenderPipelineState> ps, found; NSError *error; int compiled; } @end
@implementation PbaseBuild @end
static nvn_hmap g_pbase_pending = {.klen = sizeof(pbase_key)};
static os_unfair_lock g_pbase_lock = OS_UNFAIR_LOCK_INIT;
static NSString *pso_user_path(void);
// The pipeline archive made offline (dm/gfx/tools/pso_offline.py, metal-tt) and bundled with the app: DM_PSO_BUNDLE=<folder> (the iOS app sets it to its pso/ folder when it has one;
// off: not used) holds <GPU architecture>.mtl4a per architecture it was built for and prebuilt.tsv, what it covers (pso_prebuild). The file named after this device's architecture is
// opened read only and looked up first among the files of bases without a vertex layout; it is never written or compacted. The device's own archive (pso_archive/) so takes only
// what it lacks: a draw, the prewarm and the prebuild compile a base, and the serializer captures it, only after the bundle missed (it also holds the layout bases of the prewarm list's R rows, which plain lookups ask it for: arch_lookup_in). A system
// that cannot open it (one older than the archive's minimum, or an OS update that changed the GPU compiler) or a GPU it was not built for gets an info line, and the device builds
// the bases itself as before (the on-device prebuild is the fallback)
static NSString *g_bundle_dir;   // and g_arch_bundle, before arch_lookup_in
// The ranges of an archive file that Metal reads when it opens it (arch_read_ahead): rd collects them while the container is checked, rd == NULL only checks
// coff / clen / cn: the GPU code, the rest of each GPU image's __TEXT, which Metal reads only when a pipeline is taken (the read-ahead's ranges, DM_PSO_READAHEAD: ra_note)
typedef struct { uint64_t off[64], len[64]; int n; uint64_t coff[64], clen[64]; int cn; } arch_reads;
static void arch_reads_add(arch_reads *rd, uint64_t off, uint64_t len) { if (rd && len && rd->n < 64) { rd->off[rd->n] = off; rd->len[rd->n++] = len; } }
static void arch_reads_code(arch_reads *rd, uint64_t off, uint64_t len) { if (rd && len && rd->cn < 64) { rd->coff[rd->cn] = off; rd->clen[rd->cn++] = len; } }
// Metal's loader crashes on malformed containers rather than returning an error. Check the GPU image's load commands and referenced file ranges, including every slice of a
// universal archive, before giving it to Metal. This checks the container, not the compiler's private payload: Metal still decides whether this system can use its binaries.
static int arch_macho_ok(int fd, uint64_t off, uint64_t size, arch_reads *rd) {
    struct mach_header_64 h;
    if (size < sizeof h || pread(fd, &h, sizeof h, (off_t)off) != sizeof h || h.magic != MH_MAGIC_64 || h.filetype != MH_GPU_EXECUTE ||
        !h.ncmds || h.sizeofcmds > size - sizeof h || h.ncmds > h.sizeofcmds / sizeof(struct load_command)) return 0;
    uint64_t pos = sizeof h, end = pos + h.sizeofcmds; int pipeline = 0;
    for (uint32_t i = 0; i < h.ncmds; i++) {
        struct load_command lc;
        if (end - pos < sizeof lc || pread(fd, &lc, sizeof lc, (off_t)(off + pos)) != sizeof lc || lc.cmdsize < sizeof lc || lc.cmdsize > end - pos) return 0;
        if (lc.cmd == LC_SEGMENT_64) {
            struct segment_command_64 s;
            if (lc.cmdsize < sizeof s || pread(fd, &s, sizeof s, (off_t)(off + pos)) != sizeof s || s.fileoff > size || s.filesize > size - s.fileoff ||
                s.nsects > (lc.cmdsize - sizeof s) / sizeof(struct section_64)) return 0;
            // what the open reads: every segment but __TEXT (the pipelines' records, __AIR_DATA), and in __TEXT the libraries (__metallib); the GPU code is read when a pipeline is taken
            if (strncmp(s.segname, "__TEXT", sizeof s.segname)) arch_reads_add(rd, off + s.fileoff, s.filesize);
            else for (uint32_t j = 0; rd && j < s.nsects; j++) {
                struct section_64 sc;
                if (pread(fd, &sc, sizeof sc, (off_t)(off + pos + sizeof s + j * sizeof sc)) != sizeof sc) return 0;
                if (sc.offset > size || sc.size > size - sc.offset) continue;
                if (!strncmp(sc.sectname, "__metallib", sizeof sc.sectname)) arch_reads_add(rd, off + sc.offset, sc.size);
                else arch_reads_code(rd, off + sc.offset, sc.size);   // the GPU code: read when a pipeline is first taken, from flash on a phone (the read-ahead's)
            }
        } else if (lc.cmd == LC_NOTE) {
            struct note_command n;
            if (lc.cmdsize < sizeof n || pread(fd, &n, sizeof n, (off_t)(off + pos)) != sizeof n || n.offset > size || n.size > size - n.offset) return 0;
            if (n.size && !memcmp(n.data_owner, "AIR_PIPELINE", sizeof "AIR_PIPELINE")) pipeline = 1;
        }
        pos += lc.cmdsize;
    }
    return pos == end && pipeline;
}
static int arch_container_ok(int fd, uint64_t size, arch_reads *rd) {
    struct fat_header h;
    if (size < sizeof h || pread(fd, &h, sizeof h, 0) != sizeof h) return 0;
    if (h.magic == MH_MAGIC_64) return arch_macho_ok(fd, 0, size, rd);
    // The serializer's 0xcbfebabe wrapper uses fat_arch entries and includes a Metal library slice beside the GPU images.
    int metal = h.magic == OSSwapBigToHostInt32(0xcbfebabe), wide = h.magic == OSSwapBigToHostInt32(FAT_MAGIC_64);
    if (!metal && !wide && h.magic != OSSwapBigToHostInt32(FAT_MAGIC)) return 0;
    uint32_t n = OSSwapBigToHostInt32(h.nfat_arch); uint64_t ent = wide ? sizeof(struct fat_arch_64) : sizeof(struct fat_arch);
    if (!n || n > (size - sizeof h) / ent) return 0;
    uint64_t table = sizeof h + n * ent; int gpu = 0;
    for (uint32_t i = 0; i < n; i++) {
        uint64_t off, len;
        if (wide) {
            struct fat_arch_64 a; if (pread(fd, &a, sizeof a, (off_t)(sizeof h + i * ent)) != sizeof a) return 0;
            off = OSSwapBigToHostInt64(a.offset); len = OSSwapBigToHostInt64(a.size);
        } else {
            struct fat_arch a; if (pread(fd, &a, sizeof a, (off_t)(sizeof h + i * ent)) != sizeof a) return 0;
            off = OSSwapBigToHostInt32(a.offset); len = OSSwapBigToHostInt32(a.size);
        }
        if (off < table || off > size || len > size - off) return 0;
        uint32_t magic;
        if (len < sizeof magic || pread(fd, &magic, sizeof magic, (off_t)off) != sizeof magic) return 0;
        if (metal && magic == 0x424c544d) {   // MTLB: its header declares the full slice length and four section ranges
            uint64_t lib[11];
            if (len < sizeof lib || pread(fd, lib, sizeof lib, (off_t)off) != sizeof lib || lib[2] != len) return 0;
            for (int j = 3; j < 11; j += 2) if (lib[j] > len || lib[j + 1] > len - lib[j]) return 0;
        } else {
            if (!arch_macho_ok(fd, off, len, rd)) return 0;
            gpu = 1;
        }
    }
    return gpu;
}
// 1 a pipeline archive's container, 0 a file arch_container_ok rejects or one that is empty or no regular file (a write cut short leaves an empty one), -1 not known: it could not
// be opened or its size read (pso4_init removes a 0, never a -1). rd: what Metal's open reads (arch_read_ahead), or NULL
static int arch_file_state_rd(NSString *path, arch_reads *rd) {
    int fd = open(path.fileSystemRepresentation, O_RDONLY); if (fd < 0) return -1;
    struct stat st; int r = fstat(fd, &st) ? -1 : !S_ISREG(st.st_mode) || st.st_size <= 0 ? 0 : arch_container_ok(fd, (uint64_t)st.st_size, rd) ? 1 : 0;
    close(fd); return r;
}
static int arch_file_state(NSString *path) { return arch_file_state_rd(path, NULL); }
static int arch_file_ok(NSString *path) { return arch_file_state(path) == 1; }
// Opens an archive file that arch_file_state passed (rd: the ranges it collected). Metal's open (MTL4ArchiveImpl::loadFromURL, macOS 27) makes a library of every Metal library
// in the file and hashes all of it (SHA-256), on the calling thread: it reads the whole __AIR_DATA segment and __metallib section of every GPU image (the GPU code it leaves until
// a pipeline is taken). From a mapping not read yet, that is one 16 KB page fault after another: upstream measured Ocarina of Time's bundled archive (4.4 GB, 2.9 GB of libraries)
// at 12.5 s on an M4 Max with the file not in memory, 1.5 s with it. So those ranges are asked for first, 8 MB at a time on every core, and Metal finds them in memory. Each piece
// is mapped on its own, given MADV_WILLNEED and unmapped: the kernel reads it into the file cache, which Metal's mapping shares, with no buffer of ours (a heap buffer per piece
// kept +99 MB of footprint) and no copy when the pages are already in memory. Only a piece at a time is mapped, as Metal maps the whole file too (a second whole mapping of a
// 4.4 GB file does not fit an iPhone's address space). If the system ignores the advice, Metal reads as before (upstream PR #2657)
static id<MTL4Archive> arch_open_read_on(id<MTLDevice> dev, NSString *path, const arch_reads *r, NSError **err) {   // dev: the bundled archive opened early (mtl_pso_bundle_preopen)
    int fd = open(path.fileSystemRepresentation, O_RDONLY);
    if (fd >= 0) {
        enum { CH = 8 << 20 }; size_t first[65] = {0}, *fp = first;   // first[i]: the first 8 MB piece of range i
        for (int i = 0; i < r->n; i++) first[i + 1] = first[i] + (r->len[i] + CH - 1) / CH;
        dispatch_apply(first[r->n], dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^(size_t k) {
            int i = 0; while (k >= fp[i + 1]) i++;
            uint64_t at = r->off[i] + (uint64_t)(k - fp[i]) * CH, len = MIN((uint64_t)CH, r->len[i] - (uint64_t)(k - fp[i]) * CH);
            uint64_t pg = (uint64_t)getpagesize(), a0 = at / pg * pg; size_t ml = (size_t)(len + (at - a0));   // a mapping starts on a page
            void *w = mmap(NULL, ml, PROT_READ, MAP_SHARED, fd, (off_t)a0);
            if (w != MAP_FAILED) { (void)madvise(w, ml, MADV_WILLNEED); munmap(w, ml); }
        });
        close(fd);
    }
    return [dev newArchiveWithURL:[NSURL fileURLWithPath:path] error:err];
}
static id<MTL4Archive> arch_open_read(NSString *path, const arch_reads *r, NSError **err) { return arch_open_read_on(g_dev, path, r, err); }
// The crash guard (nvn_pso_guard.h, which says how it decides and why). A bundled archive that is well formed (arch_file_ok above passes it) but makes Metal crash as it loads
// or first uses it (one built for another GPU family than its name says, LNPANDY/NX2Apple#640 on an iPhone Air, cause unknown) used to crash the game at every start, until the
// player put DM_PSO_BUNDLE=off in env.txt or the app was rebuilt without it. Every NVN game's app carries the archive of its device's GPU by default, and every game reads it, so
// one bad archive would leave a game that never starts. So before Metal first reads the bundled archive, a record beside the device's own archive folder (pso_bundle_guard.tsv, in
// Documents on iOS) says a start with it is under way; the start takes it back once past its first frames (PSG_FRAMES frames after the prepare step and every compile of its
// prebuild ended, or the background prebuild; PSG_FRAMES_MAX frames without that). While the app is away (mtl_pso_guard_away: dm_gfx_suspend, dm_gfx_inactive, dm_gfx_exiting)
// and at a clean exit, the record is as the start's end would leave it, so a start that ends there (the player swiping the app away, iOS ending it in the background) is not
// counted. Two starts in a row with the archive that ended early in the foreground (PSO_GUARD_NEED) leave it out: the device builds the bases itself, as with DM_PSO_BUNDLE=off
// (Preparing pipelines, once), with a [RED] line that says why, and whether that start gets past its first frames decides if it stays out. Nothing a game sees changes: the
// bases are the same pipelines either way, looked up by content; a wrong verdict costs one long first start. On by default on iOS, where #640 was found and the app runs one
// process at a time; off on the Mac, whose runs (the launcher, bench.py, regress.py) keep using their archive after a crash in bring-up as before. DM_PSO_BUNDLE_GUARD=0 (or off,
// false, no) / 1 (any other value) turns it off / on (off: the archive is always used and no record is read or written)
static psg_guard g_psg = PSG_GUARD_INIT;
static _Atomic(const char *) g_psg_why;   // the end of the start the window waited for (the log line)
// Starts in a row with the archive that end early before one leaves it out: two for every game. The Nintanium line took one for games that had no archive before it became the
// default there and two for a profile that set pso_mtl4 on (a game that had its archive at every start and may need it: 13 Sentinels: Aegis Rim was reported to crash on an
// A20 Pro without it). In NX 18 the Metal 4 path is always on and pso_mtl4 is retired, so every game is such a game: one unrelated early end (a crash in the first seconds that
// has nothing to do with the archive, iOS ending the app for memory in the foreground) is followed by another start with the archive, never by one without it
#define PSO_GUARD_NEED 2
// The app's own build, for the archive's identity: its executable's LC_UUID (out: 32 hex digits, empty when not found)
static void exe_uuid(char out[33]) {
    out[0] = 0;
    const struct mach_header_64 *h = (const struct mach_header_64 *)_dyld_get_image_header(0);   // image 0: the main executable
    if (!h || h->magic != MH_MAGIC_64) return;
    const uint8_t *p = (const uint8_t *)(h + 1);
    for (uint32_t i = 0; i < h->ncmds; i++) {
        const struct load_command *lc = (const struct load_command *)p;
        if (lc->cmd == LC_UUID) { const uint8_t *u = ((const struct uuid_command *)p)->uuid; for (int k = 0; k < 16; k++) snprintf(out + 2 * k, 3, "%02x", u[k]); return; }
        if (lc->cmdsize < sizeof *lc) return;
        p += lc->cmdsize;
    }
}
// An archive file's identity for the record: its name, size, a digest of its first and last 64 KiB (reading it whole would cost a boot hundreds of MB of reads) and the app's own
// build. A rebuilt archive is another one, and so is the same archive in an app with another host: #640's cause is not known, so a host change tries the archive again. An app
// rebuilt from the same inputs is the same (the archive is reused, and the linker's LC_UUID is a digest of its output), so it keeps its record
static NSString *pso_bundle_identity(NSString *p) {
    int fd = open(p.fileSystemRepresentation, O_RDONLY); if (fd < 0) return nil;
    struct stat st = {0}; enum { PART = 65536 }; uint8_t *b = malloc(PART), h[CC_SHA256_DIGEST_LENGTH]; CC_SHA256_CTX c; CC_SHA256_Init(&c);
    int ok = b && !fstat(fd, &st) && st.st_size > 0;
    for (int i = 0; ok && i < 2; i++) {
        ssize_t n = pread(fd, b, PART, i ? MAX(0, (off_t)st.st_size - PART) : 0);
        if (n <= 0) ok = 0; else CC_SHA256_Update(&c, b, (CC_LONG)n);
    }
    free(b); close(fd); CC_SHA256_Final(h, &c);
    char u[33]; exe_uuid(u);
    return ok ? [NSString stringWithFormat:@"%@ %lld %02x%02x%02x%02x%02x%02x%02x%02x host %s", p.lastPathComponent, (long long)st.st_size, h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7],
                 *u ? u : "unknown"] : nil;
}
// exit(): a clean end (a front end's quit). The host's graceful exit ends in _exit; dm_gfx_exiting, its first step, puts the record back there. A crash or a kill runs neither
static void pso_guard_atexit(void) { psg_exit(&g_psg); }
#if TARGET_OS_IPHONE
#define PSO_GUARD_RETRY "delete that file (the Files app, in the app's folder) or put DM_PSO_BUNDLE_GUARD=0 in Documents/env.txt"
#else
#define PSO_GUARD_RETRY "delete that file or set DM_PSO_BUNDLE_GUARD=0"
#endif
// What brings the archive back by itself, and how to retry the same build (an app rebuilt from the same inputs has the same identity)
#define PSO_GUARD_AGAIN "An app built with another archive or host (new shaders, an NX 18 update) or a system update tries it again by itself; to try this one again, " PSO_GUARD_RETRY
// Whether this start opens the bundled archive at p (before Metal reads it): the record's verdict, with a [RED] line when it leaves the archive out
// The device's own archive folder: DM_PSO_ARCHIVE (off: none), else pso_archive/ beside pso_user.tsv. g_arch_dir once pso4_init has run; from the environment alone, so the
// crash guard finds its record beside it on any thread (the bundled archive's early open, mtl_pso_bundle_preopen, begins the guard before pso4_init)
static NSString *arch_dir_env(void) {
    const char *e = getenv("DM_PSO_ARCHIVE"); NSString *user = pso_user_path();
    return e && !strcmp(e, "off") ? nil : e && *e ? @(e) : user ? [user.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"pso_archive"] : nil;
}
static int pso_guard_begin(NSString *p) {
    const char *e = getenv("DM_PSO_BUNDLE_GUARD");
    // Off: on the Mac unless asked for, and wherever DM_PSO_BUNDLE_GUARD is 0, off, false or no (any case). The old commit took only 0 as off, so DM_PSO_BUNDLE_GUARD=off, the
    // word its sibling DM_PSO_BUNDLE takes, kept the guard on without a line saying so (and turned it on on the Mac); any other value still turns it on, the Mac included
    int off_word = e && (!strcmp(e, "0") || !strcasecmp(e, "off") || !strcasecmp(e, "false") || !strcasecmp(e, "no"));
    if (e && *e ? off_word : !TARGET_OS_IPHONE) {
        if (e && *e) MLOG("DM_PSO_BUNDLE_GUARD=%s: the pipeline archive bundled with the app is used without its crash guard (no record read or written)", e);
        return 1;
    }
    NSString *home = arch_dir_env().stringByDeletingLastPathComponent, *id_ = pso_bundle_identity(p);
    if (!home.length) home = pso_user_path().stringByDeletingLastPathComponent;   // DM_PSO_ARCHIVE=off: beside pso_user.tsv, where the archive folder would be
    char os[64] = ""; size_t n = sizeof os; if (sysctlbyname("kern.osversion", os, &n, NULL, 0)) os[0] = 0;
    if (!home.length || !id_ || !*os) {
        MLOG("pipeline archive bundled with the app: %s: used without its crash guard", !id_ ? "its size and digest cannot be read" : !*os ? "the system build (kern.osversion) is not known"
             : "no folder for the crash guard's record (neither DM_PSO_ARCHIVE nor DM_SAVE)");
        return 1;
    }
    [NSFileManager.defaultManager createDirectoryAtPath:home withIntermediateDirectories:YES attributes:nil error:nil];
    NSString *rec = [home stringByAppendingPathComponent:@"pso_bundle_guard.tsv"];
    atomic_store(&g_psg_why, NULL);
    psg_start s = psg_begin(&g_psg, rec.fileSystemRepresentation, os, id_.UTF8String, PSO_GUARD_NEED);   // copied under its lock: the background hook may write the guard meanwhile
    if (s.armed != PSG_NONE) { static dispatch_once_t once; dispatch_once(&once, ^{ atexit(pso_guard_atexit); }); }
    const char *r = rec.UTF8String, *ident = id_.UTF8String;
    // What this start's outcome decides, said only when the record says so (s.err: not watched, nothing recorded; the line after says so)
    const char *then = s.err ? "" : "If this start gets past its first frames, the archive stays out for this archive, app build and system build; if it does not either, the "
                                    "archive is not shown to be the cause and the next start uses it again. ";
    switch (s.found) {
    case PSG_WITH:
        if (s.use) MLOG("[RED] pipeline archive bundled with the app: a start with %s on this system build (%s) did not get past its first frames (it crashed, or iOS ended it in the "
                        "foreground): this start uses it again%s, since one such start can have another cause; only a second such start in a row leaves it out (crash guard: %s)",
                        ident, os, s.err ? "" : ", watched", r);
        else MLOG("[RED] pipeline archive bundled with the app: a start with %s on this system build (%s) did not get past its first frames (it crashed, or iOS ended it in the "
                  "foreground): this start leaves the archive out and the device builds the bases itself (Preparing pipelines, once). %s(crash guard: %s). " PSO_GUARD_AGAIN,
                  ident, os, then, r);
        break;
    case PSG_WITH2:
        MLOG("[RED] pipeline archive bundled with the app: two starts in a row with %s on this system build (%s) did not get past their first frames (they crashed, or iOS ended them "
             "in the foreground): this start leaves the archive out and the device builds the bases itself (Preparing pipelines, once). %s(crash guard: %s). " PSO_GUARD_AGAIN,
             ident, os, then, r);
        break;
    case PSG_WITHOUT:
        MLOG("[RED] pipeline archive bundled with the app: the start without %s did not get past its first frames either, after starts with it did not: the archive is not shown to "
             "be what ended them, so this start uses it again%s (crash guard: %s)", ident, s.err ? "" : ", watched as a first start", r);
        break;
    case PSG_SKIP:
        MLOG("[RED] pipeline archive bundled with the app: %s is left out on this system build (%s): starts with it did not get past their first frames and the start without it did "
             "(crash guard: %s), so the device's own archive serves the bases. " PSO_GUARD_AGAIN, ident, os, r);
        break;
    default: if (s.armed == PSG_WITH) MLOG("pipeline archive bundled with the app: crash guard on until this start is past its first frames (%s: archive %s, system build %s)",
                                          r, ident, os); break;
    }
    // Nothing recorded: the record stays as this start found it, and so does every later start's verdict until it can be written
    if (s.err) MLOG("[RED] pipeline archive bundled with the app: the crash guard cannot write %s (%s): this start is not watched and the record stays as it is, so until it can "
                    "be written (free some space) every start %s", r, strerror(s.err), s.use ? "uses the archive unwatched" : "leaves the archive out (Preparing pipelines)");
    return s.use;
}
static void pso_guard_mark(const char *why) {   // the prepare step and its prebuild, or the background prebuild, ended (the first of them names it in the log)
    if (!atomic_load(&g_psg.watching)) return;
    const char *none = NULL; atomic_compare_exchange_strong(&g_psg_why, &none, why); psg_mark(&g_psg);
}
static void pso_guard_frame(void) {   // a frame presented while watched (present_now): the frame that ends the window hands the record to a utility queue
    if (!psg_frame(&g_psg)) return;
    uint32_t frames = atomic_load(&g_psg.frames), at = atomic_load(&g_psg.mark_at); const char *why = at != PSG_UNMARKED ? atomic_load(&g_psg_why) : NULL;
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
        int err = 0, was = psg_pass(&g_psg, &err);
        if (was == PSG_WITH || was == PSG_WITH2) MLOG("pipeline archive bundled with the app: this start got past its first frames with it (%s, %u frames %s): the crash guard's record is "
                                                    "taken back", why ?: "no end of the prepare step or prebuild", why ? frames - at : frames, why ? "after it" : "presented");
        else if (was == PSG_WITHOUT) MLOG("[RED] pipeline archive bundled with the app: this start got past its first frames without it, after %s did not: it stays out for this "
                                         "archive, app build and system build (%s; to try it again, " PSO_GUARD_RETRY ")", g_psg.need > 1 ? "two in a row with it" : "one with it", g_psg.path);
        if (err) MLOG("[RED] pipeline archive bundled with the app: the crash guard cannot write %s (%s)", g_psg.path, strerror(err));
    });
}
void mtl_pso_guard_away(int why, int on) {
    int err = 0, was = psg_away(&g_psg, why, on, &err);
    if (was == PSG_NONE) return;
    MLOG("pipeline archive bundled with the app: %s before this start got past its first frames: the crash guard's record %s",
         !on ? "back in the foreground" : why == PSG_AWAY_INACTIVE ? "inactive (the app switcher, a system sheet)" : why == PSG_AWAY_EXIT ? "in the graceful exit" : "in the background",
         on ? "is as the start's end would leave it (an app ended while away is not counted)" : "is written again");
    if (err) MLOG("[RED] pipeline archive bundled with the app: the crash guard cannot write %s (%s)", g_psg.path, strerror(err));
}
// The archive opened early (mtl_pso_bundle_preopen) is set aside (on 1) until the first submission takes it (0, pso_bundle_join): nothing reads it in between, so the record is as
// the start's end would leave it there (nvn_pso_guard.h PSG_AWAY_IDLE), and an early end in the game's own start is no start with the archive, as when it was opened at the
// first submission.
// The first version kept the record from the early open on, so two unrelated early ends in the boot of a game (a boot crash, a foreground jetsam while its files load) left the
// archive out, and once the start without it got past its window, for good on that app and system build. A start that leaves the archive out is watched from the first
// submission as well
static void pso_guard_idle(int on) {
    int err = 0, was = psg_away(&g_psg, PSG_AWAY_IDLE, on, &err);
    if (was != PSG_NONE && on) MLOG("pipeline archive bundled with the app: until the first submission, the archive's first use, the crash guard's record is as the start's end "
                                    "would leave it (an early end in the game's own start is not counted)");
    if (err) MLOG("[RED] pipeline archive bundled with the app: the crash guard cannot write %s (%s)", g_psg.path, strerror(err));
}
// The bundled archive's file for this device's GPU (DM_PSO_BUNDLE=<folder>, <GPU architecture>.mtl4a), or nil, with a line that says why; *dir: the folder
static NSString *pso_bundle_file(id<MTLDevice> dev, NSString **dir) {
    const char *e = getenv("DM_PSO_BUNDLE");
    if (!e || !*e || !strcmp(e, "off")) return nil;
    NSString *d = @(e), *gpu = dev.architecture.name;   // every device of macOS 27.2 / iOS 27.2 has it (MTLDevice.architecture: macOS 14, iOS 17); a test with a fake device leaves DM_PSO_BUNDLE unset
    NSString *p = gpu ? [d stringByAppendingPathComponent:[gpu stringByAppendingPathExtension:@"mtl4a"]] : nil;
    if (!p || ![NSFileManager.defaultManager fileExistsAtPath:p]) {
        NSArray<NSString *> *have = [[NSFileManager.defaultManager contentsOfDirectoryAtPath:d error:nil] filteredArrayUsingPredicate:[NSPredicate predicateWithFormat:@"self ENDSWITH '.mtl4a'"]];
        MLOG("pipeline archive bundled with the app: none for this GPU (%s; %s has %s): the bases are built on the device", gpu ? gpu.UTF8String : "architecture unknown", e,
             have.count ? [have componentsJoinedByString:@", "].UTF8String : "none");
        return nil;
    }
    if (dir) *dir = d;
    return p;
}
// Checks the bundled archive's container, begins its crash guard and opens it on dev (arch_open_read_on): the archive, or nil with a line that says why
static uint64_t g_bundle_bytes, g_arch_dev_bytes;   // the bundled archive's size and the device's opened files' (pso4_init), for the address-space line (arch_vm_line)
// The task's address space: free, and the largest gap between mappings, from min_address to max_address (TASK_VM_INFO); top-level mappings and reservations count whole, submaps
// included, so their holes are not counted as room. From upstream 24e007bed (its measurement only: NX 18 does not port its admission, which turns every archive off when they do not
// fit with a 2 GiB reserve; Ocarina's 4.7 GB bundled archive would need a 6.7 GB gap, and losing it would cost far more than the freezes it guards against). 0: not readable
static int arch_vm_room(uint64_t *free, uint64_t *largest) {
    task_vm_info_data_t vi; mach_msg_type_number_t count = TASK_VM_INFO_COUNT;
    if (task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&vi, &count) != KERN_SUCCESS || count < TASK_VM_INFO_REV2_COUNT || vi.max_address <= vi.min_address) return 0;
    uint64_t prev = vi.min_address, hi = vi.max_address; vm_address_t a = (vm_address_t)prev; vm_size_t size;
    *free = *largest = 0;
    while ((uint64_t)a < hi) {
        natural_t depth = 0; vm_region_submap_short_info_data_64_t info; count = VM_REGION_SUBMAP_SHORT_INFO_COUNT_64;
        kern_return_t kr = vm_region_recurse_64(mach_task_self(), &a, &size, &depth, (vm_region_recurse_info_t)&info, &count);
        if (kr == KERN_INVALID_ADDRESS) break;
        if (kr != KERN_SUCCESS || !size || size > UINT64_MAX - (uint64_t)a) return 0;
        uint64_t start = MIN((uint64_t)a, hi), end = MIN((uint64_t)a + size, hi);
        if (start > prev) { uint64_t gap = start - prev; *free += gap; *largest = MAX(*largest, gap); }
        if (end <= prev) return 0;
        prev = end; a = (vm_address_t)end;
    }
    if (prev < hi) { uint64_t gap = hi - prev; *free += gap; *largest = MAX(*largest, gap); }
    return 1;
}
// Once, after the archives are open (pso4_init): what they map (Metal maps each file whole) and the room left. Diagnostics only, no behaviour change: a game that aborts in
// pthread_create or realloc with its footprint well under the limit (upstream #2444, Breath of the Wild on an iPhone 16 Pro Max) shows here whether the address space ran short
static void arch_vm_line(void) {
    uint64_t fr = 0, lg = 0; int ok = arch_vm_room(&fr, &lg); const double M = 1048576.0;
    char room[160] = "the task's address map could not be read";
    if (ok) snprintf(room, sizeof room, "task address space free %.1f MB, largest free gap %.1f MB", fr / M, lg / M);
    MLOG("pipeline archives' address space: bundled %.1f MB + this device's %.1f MB = %.1f MB mapped; %s (diagnostics only, nothing is turned off)",
         g_bundle_bytes / M, g_arch_dev_bytes / M, (g_bundle_bytes + g_arch_dev_bytes) / M, room);
}
static void ra_schedule(void);   // below
static void ra_note(NSString *p, const arch_reads *rd);   // the read-ahead's ranges (DM_PSO_READAHEAD), below
static id<MTL4Archive> pso_bundle_load(id<MTLDevice> dev, NSString *p) {
    NSError *ae = nil; arch_reads rd = {0};
    if (arch_file_state_rd(p, &rd) != 1) { MLOG("[RED] pipeline archive bundled with the app: %s is not a pipeline archive: the bases are built on the device", p.UTF8String); return nil; }
    // After the container checks (a file they refuse is never read by Metal, so it needs no record) and before Metal reads it: an earlier start with it did not get past its first
    // frames (its [RED] line says what happens next). The caller's 'opened in' time also counts the guard's record and its 128 KiB digest
    if (!pso_guard_begin(p)) return nil;
    id<MTL4Archive> a = arch_open_read_on(dev, p, &rd, &ae);
    if (!a) { psg_unused(&g_psg); MLOG("pipeline archive bundled with the app: this system cannot open %s (%s; made for another system version, or an OS update changed the GPU compiler): the bases are built on the device",
                   p.UTF8String, ae.localizedDescription.UTF8String); return nil; }
    ra_note(p, &rd);
    return a;
}
static int pso_bundle_join(NSMutableArray<id<MTL4Archive>> *archp);   // the archive opened early (mtl_pso_bundle_preopen), below
static void pso_bundle_open(NSMutableArray<id<MTL4Archive>> *archp) {
    if (pso_bundle_join(archp)) return;
    NSString *dir = nil, *p = pso_bundle_file(g_dev, &dir);
    if (!p) return;
    uint64_t t0 = bp_now();
    id<MTL4Archive> a = pso_bundle_load(g_dev, p);
    if (!a) return;
    g_arch_bundle = a; g_bundle_dir = dir; [archp addObject:a];
    g_bundle_bytes = [[NSFileManager.defaultManager attributesOfItemAtPath:p error:nil] fileSize];
    MLOG("pipeline archive bundled with the app: %s, %.1f MB, opened in %.1f ms", p.UTF8String, g_bundle_bytes / 1048576.0, (bp_now() - t0) / 1e6);
}
// gpuarchiver-* folders are Metal's private compiler state: one per pipeline data set serializer, so one per flush period (ep_new), up to about 127 MB each, never removed by
// Metal. Metal puts them in <user cache folder>/<main bundle ID>/com.apple.gpuarchiver, or <user cache folder>/com.apple.gpuarchiver for a process without a bundle ID
// (getCacheMainFolder in Metal; its exported MTLGetGPUArchiverCachePath returns the folder). A host without a bundle (dmhost from a build) shares that folder with every other
// such program: a directory appearing there during our capture or flush may belong to another compiler, so it removes none (scripts/clean_metal_cache.py does, from outside). A
// host with a bundle ID (the Mac app, the iOS app) has a folder of its own, shared only with other copies of the same game's app. Every such host holds a shared lock on
// gpuarchiver.lock beside the folder for its whole run, from before its first serializer; at start it tries an exclusive one first, and with it no other copy is running, so the
// folders there are earlier runs' and it removes them. Never infer ownership from a live directory delta or remove compiler state at flush or exit: serialization success does not
// end a folder's lifetime (docs/reference/shaders.md, "Metal's build folders left by pipeline archive flushes")
static NSString *ga_dir(void) {
    static NSString *dir; static dispatch_once_t once;
    dispatch_once(&once, ^{
        NSString *(*metal)(void) = (NSString *(*)(void))dlsym(RTLD_DEFAULT, "MTLGetGPUArchiverCachePath");
        NSString *d = metal ? metal() : nil;
        if (![d isKindOfClass:NSString.class] || !d.length) {   // a system without it: the same rule. confstr gives nothing in an iOS simulator app, where Metal takes Library/Caches
            char b[PATH_MAX]; NSString *base = confstr(_CS_DARWIN_USER_CACHE_DIR, b, sizeof b) > 1 ? @(b) : NSSearchPathForDirectoriesInDomains(NSCachesDirectory, NSUserDomainMask, YES).firstObject;
            NSString *bid = NSBundle.mainBundle.bundleIdentifier;
            d = base ? [(bid.length ? [base stringByAppendingPathComponent:bid] : base) stringByAppendingPathComponent:@"com.apple.gpuarchiver"] : nil;
        }
        dir = d.stringByStandardizingPath;
    });
    return dir;
}
static int ga_own(void) { return NSBundle.mainBundle.bundleIdentifier.length > 0 && ga_dir() != nil; }   // the folder is this game's app's, not every program's
// Each snapshotted gpuarchiver-* directory carries its (dev, ino) identity so background removal never deletes a file, symlink, or replacement directory with the same name.
@interface GaDir : NSObject { @public NSString *name; dev_t dev; ino_t ino; } @end
@implementation GaDir @end
static NSArray<GaDir *> *ga_list(NSString *dir) {
    if (!dir) return @[];
    int dfd = open(dir.fileSystemRepresentation, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
    if (dfd < 0) return @[];
    DIR *dp = fdopendir(dfd);
    if (!dp) { close(dfd); return @[]; }
    int rfd = dirfd(dp);
    NSMutableArray<GaDir *> *out = [NSMutableArray array];
    struct dirent *de;
    while ((de = readdir(dp))) {
        if (strncmp(de->d_name, "gpuarchiver-", 12)) continue;
        struct stat st;
        if (fstatat(rfd, de->d_name, &st, AT_SYMLINK_NOFOLLOW) || !S_ISDIR(st.st_mode)) continue;   // skip files and symlinks; Metal's state is a directory
        NSString *name = [NSFileManager.defaultManager stringWithFileSystemRepresentation:de->d_name length:strlen(de->d_name)];
        if (!name) continue;
        GaDir *g = [GaDir new]; g->name = name; g->dev = st.st_dev; g->ino = st.st_ino;
        [out addObject:g];
    }
    closedir(dp);
    return out;
}
// Recursively empty an already-opened directory fd without following symlinks; always consumes fd. Returns 1 when every entry was removed (or already gone).
static int ga_rmtree_fd(int fd, int depth) {
    if (depth > 64) { close(fd); return 0; }
    DIR *dp = fdopendir(fd);
    if (!dp) { close(fd); return 0; }
    int dfd = dirfd(dp), ok = 1;
    for (;;) {
        int saw = 0, unlinked = 0;
        struct dirent *de;
        while ((de = readdir(dp))) {
            if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, "..")) continue;
            saw = 1;
            struct stat st;
            if (fstatat(dfd, de->d_name, &st, AT_SYMLINK_NOFOLLOW)) {
                if (errno != ENOENT) ok = 0;
                continue;
            }
            if (S_ISDIR(st.st_mode)) {
                int sub = openat(dfd, de->d_name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
                if (sub < 0) {
                    if (errno != ENOENT) ok = 0;
                    continue;
                }
                if (!ga_rmtree_fd(sub, depth + 1)) ok = 0;
                if (!unlinkat(dfd, de->d_name, AT_REMOVEDIR)) unlinked = 1;
                else if (errno != ENOENT) ok = 0;
            } else {
                if (!unlinkat(dfd, de->d_name, 0)) unlinked = 1;
                else if (errno != ENOENT) ok = 0;
            }
        }
        if (!saw || !unlinked) break;
        rewinddir(dp);
    }
    closedir(dp);
    return ok;
}
static int ga_remove(NSString *dir, NSArray<GaDir *> *old) {
    if (!dir || !old.count) return 0;
    int dfd = open(dir.fileSystemRepresentation, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
    if (dfd < 0) return 0;
    int removed = 0;
    for (GaDir *g in old) {
        const char *name = g->name.fileSystemRepresentation;
        if (!name || strncmp(name, "gpuarchiver-", 12) || strchr(name, '/')) continue;
        int cfd = openat(dfd, name, O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC);
        if (cfd < 0) continue;   // gone, or replaced by a file or symlink
        struct stat st;
        if (fstat(cfd, &st) || !S_ISDIR(st.st_mode) || st.st_dev != g->dev || st.st_ino != g->ino) {
            close(cfd);   // replaced by a different directory with the same name
            continue;
        }
        if (!ga_rmtree_fd(cfd, 0)) continue;   // consumes cfd
        // Recheck (dev, ino) before removing the directory entry itself; AT_REMOVEDIR also refuses non-empty dirs, files, and symlinks.
        if (fstatat(dfd, name, &st, AT_SYMLINK_NOFOLLOW) || !S_ISDIR(st.st_mode) || st.st_dev != g->dev || st.st_ino != g->ino) continue;
        if (!unlinkat(dfd, name, AT_REMOVEDIR)) removed++;
    }
    close(dfd);
    return removed;
}
// The lock beside dir, held shared from here on through *fd (left open for the run: the lock ends with the process, a forked child sharing it). → the folders of earlier runs
// to remove, when no other copy holds the lock; nil otherwise. Listed under the exclusive lock, before this process makes a serializer: a copy starting meanwhile waits for the
// listing at its shared lock, so no folder of a running copy is ever among them. A copy that cannot take the lock at all removes nothing and goes on unprotected
static NSArray<GaDir *> *ga_claim(NSString *dir, int *fd) {
    *fd = -1;
    if (!dir || ![NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil]) return nil;
    int f = open([dir.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"gpuarchiver.lock"].fileSystemRepresentation, O_RDWR | O_CREAT | O_CLOEXEC, 0644);
    if (f < 0) return nil;
    NSArray<GaDir *> *old = flock(f, LOCK_EX | LOCK_NB) ? nil : ga_list(dir);
    int r; while ((r = flock(f, LOCK_SH)) && errno == EINTR) {}   // from the exclusive lock, or after a starting copy's listing
    if (r) { close(f); return nil; }
    *fd = f;
    return old;
}
static ArchEpoch *ep_new(int pre) {   // a flush period (pre: the prebuild's): its compiler and serializer, nil when Metal makes none
    MTL4PipelineDataSetSerializerDescriptor *sd = [MTL4PipelineDataSetSerializerDescriptor new]; sd.configuration = MTL4PipelineDataSetSerializerConfigurationCaptureBinaries;
    ArchEpoch *ep = [ArchEpoch new]; ep->pre = pre; ep->deaths = atomic_load(&g_arch_deaths); ep->ser = [g_dev newPipelineDataSetSerializerWithDescriptor:sd];
    if (!ep->ser) return nil;
    MTL4CompilerDescriptor *cd = [MTL4CompilerDescriptor new]; cd.pipelineDataSetSerializer = ep->ser;
    ep->comp = [g_dev newCompilerWithDescriptor:cd error:nil];
    if (!ep->comp) return nil;
    ep->busy = dispatch_group_create();
    return ep;
}
static ArchEpoch *ep_enter(int pre) {   // the current period (pre: the prebuild's, while it has one), joined: a flush hands it to arch_write only once every compile that joined it has left
    os_unfair_lock_lock(&g_ep_lock);
    ArchEpoch *ep = pre && g_ep_pre ? g_ep_pre : g_ep; atomic_fetch_add(&ep->active, 1); dispatch_group_enter(ep->busy);
    os_unfair_lock_unlock(&g_ep_lock);
