static FnBusy g_fn_busy[FN_BUSY_MAX]; static int g_fn_nbusy; static uint64_t g_fn_ser;   // the functions of the captures under way, one entry per function
static _Atomic int g_fn_waits, g_fn_plain;   // captures that found one of their functions under way; of them, the ones built without the archive after the wait (fn_gave_up)
static uint64_t g_fn_lent;   // threads holding a function that a wait lent its QoS to (fn_lend; under g_fn_mu)
static uint64_t fn_id(MTL4FunctionDescriptor *fd) {
