static int fn_mine(const uint64_t *k, int n, int j) { for (int i = 0; i < n; i++) if (g_fn_busy[j].k == k[i]) return 1; return 0; }   // under g_fn_mu
static int fn_busy(const uint64_t *k, int n) { for (int j = 0; j < g_fn_nbusy; j++) if (fn_mine(k, n, j)) return 1; return 0; }   // under g_fn_mu
// A wait lends its thread's QoS to the threads whose captures hold one of k's functions, as pso_pend_take lends it to a build it waits for (a condition variable passes none):
// a draw's capture on the submit thread otherwise waited, up to g_fn_wait_ms, for a later draw's capture at utility QoS on pp_bg_queue, which iOS tends to run on the efficiency
// cores, and then built its pipeline with the plain compiler after all. Under g_fn_mu, where a holder is in its compile (fn_release takes the lock first), so its thread is alive.
// ov / ot: this wait's overrides and their threads (*nov of them, at most FN_LEND_MAX); those of threads that hold none of k's functions any more end here (all: none is kept)
static void fn_lend(const uint64_t *k, int n, int all, pthread_override_t *ov, pthread_t *ot, int *nov) {
    for (int i = 0; i < *nov;) {
        int holds = 0; for (int j = 0; j < g_fn_nbusy && !holds && !all; j++) holds = pthread_equal(g_fn_busy[j].th, ot[i]) && fn_mine(k, n, j);
        if (holds) { i++; continue; }
        pthread_override_qos_class_end_np(ov[i]); ov[i] = ov[*nov - 1]; ot[i] = ot[*nov - 1]; --*nov;
    }
    if (all) return;
