static void fn_deadline(struct timespec *until, int ms) {
    clock_gettime(CLOCK_REALTIME, until); until->tv_sec += ms / 1000; until->tv_nsec += (long)(ms % 1000) * 1000000;
    if (until->tv_nsec >= 1000000000) { until->tv_sec++; until->tv_nsec -= 1000000000; }
}
static int fn_holders(const uint64_t *k, int n, uint64_t s[3]) {   // the serials of the captures holding k's functions (at most one each), under g_fn_mu
    int m = 0; for (int j = 0; j < g_fn_nbusy && m < 3; j++) if (fn_mine(k, n, j)) s[m++] = g_fn_busy[j].ser;
    return m;
}
static int fn_returned(const uint64_t *k, int n, uint64_t s[3], int *m) {   // 1: one of the *m captures in s returned since; s becomes those holding them now (under g_fn_mu)
    int gone = 0;
    for (int i = 0; i < *m && !gone; i++) { int still = 0; for (int j = 0; j < g_fn_nbusy && !still; j++) still = g_fn_busy[j].ser == s[i]; gone = !still; }
