    dispatch_block_t done;   // the open, waited for once by the first submission (pso_bundle_join; a block made by dispatch_block_create counts as not done until it has run)
    id<MTLDevice> dev; id<MTL4Archive> a; NSString *path, *dir; uint64_t t0, t1, size;
