static void arch_compact_finish(void) {   // after every period that may hold recaptured bases is written (arch_write, compact_close; g_arch_q): the old files go once their bases are in the new ones
    if (!g_compact_files || !g_compacted || atomic_exchange(&g_compact_once, 1)) return;
