static id<MTLRenderPipelineState> pso_build(MTLRenderPipelineDescriptor *d, int off, NSError **e) { return pso_build_ex(d, off, e, 1); }   // off: !pso_key.border of the key d was made from
// Pipeline key: current state S + pass formats (normal pass; a merged pass additionally carries lmap / specialized function, filled in by pso_get)
static void pso_key_fill(pso_key *k, NvShader *vs, NvShader *fs, const uint32_t cfmt[8], uint32_t dfmt, uint32_t sfmt, uint32_t samples, int lmap) {
    memset(k, 0, sizeof *k);
    k->vs = (__bridge void *)vs; k->fs = (__bridge void *)fs;
    memcpy(k->cfmt, cfmt, sizeof k->cfmt); k->dfmt = dfmt; k->sfmt = sfmt; k->samples = samples;
    k->blend_en = S.color.blend_en; k->chmask = S.chmask.mask; k->a2c = S.ms.a2c; k->atest = atest_key(fs, cfmt, lmap ? g_pso_lmap : NULL);
    for (int i = 0; i < 8; i++) if (k->cfmt[i] || lmap) k->blend[i] = S.blend[i];
    k->logic = lop_key(k, fs, lmap);
    k->border = border_need(vs, vs->stage) || border_need(fs, 1);   // as prog_border, which the draw compares
    const nvn_refl *rf = &vs->rf;
    for (int v = 0; v < rf->nv; v++) { int a = rf->v[v].nvn; if (a < 32 && a < S.nattr) { if (a < 16) k->attr[a] = S.attr[a]; else k->attr_hi[a - 16] = S.attr[a]; int st = S.attr[a].stream; if (st < 16) k->stream[st] = S.stream[st]; } }
    pso_key_norm(k, lmap);
}
// ---- Parallel precompile: pipelines met for the first time used to be compiled synchronously one by one on the submit thread; 9 misses in a row in one frame = 284 ms (heavy scene on a real device).
// After satisfying the first pipeline miss in a submission, scan ahead once along the remaining commands (replaying state only, no drawing) and kick a bounded number of normal-pass pipelines to the background;
// when the submit thread reaches that draw it only waits for 'the remaining time not yet compiled'. The compiled pipelines are identical to synchronously compiled ones (same descriptor). Pipeline keys of merged passes / specialized fragments depend on the planning result at replay time, are not predicted, and are compiled synchronously as before.
#define PSO_PEND_MAX 384
// PSO_PEND_ACTIVE / PSO_PREDICT_BUDGET bound the first builds the look-ahead admits and the guesses (a key with another depth / stencil attachment than the draw's). The other draws
// the scan met with their attachments as they are come later in this submission and would wait: each of their pipelines is admitted too (pso_pend_kick_next), bounded by the
// table. Upstream (PR #1344): bounded by 2 as well, a cold load of FINAL FANTASY RESONANCE into Grandshelt Castle waited 2.8 s for pipelines, worst frame 2.2 s, against 0.74-0.79 s.
// NX 18 starts the first PSO_PREDICT_BUDGET at user-initiated QoS on the global queue as before, and the rest on pp_bg_queue's utility queues, not on the global queue as upstream
// does: a burst there ran on every core beside the game's threads (Breath of the Wild, below). DM_NVN_PREDICT_NEXT=0 keeps the bound of 2 for them all, ab alternates (DM_AB)
enum { PSO_PEND_ACTIVE = 2, PSO_PREDICT_BUDGET = 2 };
// One budget per prediction, retained by its lookup workers (pso_bg_look). Both the submit thread and the workers spend it under g_pp_mu, only when a guess is admitted. A single
// generation/count pair loses an older prediction's count when its workers finish after a newer prediction's workers (upstream 9d3a58364, PR #2677)
@interface PsoPredictBudget : NSObject { @public unsigned admitted; } @end
@implementation PsoPredictBudget @end
static int predict_next_mode(void) { static int m = -1; if (m < 0) m = sw_mode("DM_NVN_PREDICT_NEXT", 1); return m; }
// order: admission order (the oldest finished, untaken entry is reclaimed first); demand: a build a draw asked for while it draws with its pulling stand-in (hybrid pipelines),
// outside the speculative limit; next: a later draw's build the look-ahead admitted (pso_pend_kick_next), also outside it, so a backlog of them on pp_bg_queue never turns
// the next submission's first PSO_PREDICT_BUDGET away from the global queue nor refuses its guesses; run: 0 queued, 1 taken by its worker (th, while it builds); d: the
// descriptor while queued (a draw that would wait for a queued build makes the pipeline itself: pso_pend_take); gen tells a slot's fills apart, so a worker whose slot was taken
// that way and filled again does nothing; taking: the submit thread waits for this slot, so no admission (a base-lookup worker's, pso_bg_look) may reclaim it once done before that
// draw takes its pipeline (upstream 9d3a58364: its full-table fixture handed the waiting draw another key's pipeline without it)
static struct { pso_key k; id<MTLRenderPipelineState> ps; MTLRenderPipelineDescriptor *d; int used, done, run, demand, next, taking; pthread_t th; uint32_t gen; uint64_t order; } g_pp[PSO_PEND_MAX];
static pthread_mutex_t g_pp_mu = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t g_pp_cv = PTHREAD_COND_INITIALIZER;
static uint64_t g_pp_submit_mark, g_pp_taken, g_pp_stolen, g_pp_boost;   // Whether this submission has already been predicted (by submission serial); taken counts; builds made by their draw (g_pp_mu); waits that lent their QoS to a running build (pso_pend_take)
static _Atomic uint64_t g_pp_kicked;   // admissions (g_pp_mu), by the submit thread and the base-lookup workers; also read by the timing summary
static _Atomic uint64_t g_pp_admit;   // speculative builds the predictions admitted (on the submit thread, or by a base lookup handed to the background: pso_bg_look)
static _Atomic uint64_t g_bgl_n, g_bgl_done, g_bgl_found, g_bgl_ns;   // the predictions' base lookups handed to the background (pso_bg_look), finished, of them found a base (the key's own or its pulling one), and the workers' time
static void pso_predict_rest(void);
