// the global queue, a cold start's burst (777 builds on entering Zora's Domain, Breath of the Wild) ran on every core, beside the game's own threads, for the seconds it took.
// Speculative guesses (pso_pend_kick: at most PSO_PEND_ACTIVE at a time) keep the global queue, so a demanded build never waits behind speculation. The look-ahead's later draws
// past them (pso_pend_kick_next) take these queues: a draw that reaches its build still queued makes it itself (pso_pend_take), so none waits behind the others, and one
// whose build already runs lends its QoS to the worker while it waits.
// How many: one per two performance cores (hw.perflevel0), but at least half of what Metal's compiler runs at once (maximumConcurrentCompilationTaskCount), up to 3. Level 0 alone
// was 1 queue on an iPhone 18 Pro Max (the A20 Pro has 2 performance cores) and on an M6 (2 Super cores beside 4 Performance and 6 Efficiency): on the iPhone a backlog of 323
// builds in Super Mario Odyssey ran one at a time, about 20 s with stand-ins drawn meanwhile, and the M6's prebuild of 2,125 pairs took 45.1 s on 1 worker against 28.0 s on 3
// (docs/reference/shaders.md, A prebuild pool sized from the Super cores). The cap of 3 keeps these utility queues a share of the compiler, beside the game's threads; a Mac whose
// level 0 already gives more (an M2 Max: 4) keeps its count. DM_PSO_BG_QUEUES=<n> sets the count (1-8)
static int pp_bg_count(void) {
    static int n; static dispatch_once_t once;
    dispatch_once(&once, ^{
        int pc = 0; size_t sz = sizeof pc; if (sysctlbyname("hw.perflevel0.physicalcpu", &pc, &sz, NULL, 0) || pc < 2) pc = 2;
        NSUInteger mc = g_dev.maximumConcurrentCompilationTaskCount;   // every device of macOS 27.2 / iOS 27.2 has it (macOS 13.3, iOS 26; as compile_tasks)
        int share = (int)(mc / 2 > 3 ? 3 : mc / 2);
        n = pc / 2 > share ? pc / 2 : share;
        const char *e = getenv("DM_PSO_BG_QUEUES"); int v = e ? atoi(e) : 0;
        if (e && (v < 1 || v > 8)) MLOG("[RED] DM_PSO_BG_QUEUES=%s is not a count of 1-8: %s", e, v < 1 ? "ignored" : "taking 8");
        if (v >= 1) n = v;
        if (n > 8) n = 8;
        MLOG("pipeline builds in the background: %d serial queues (%d performance-level-0 cores, Metal runs %lu compiles at once; %s)",
             n, pc, (unsigned long)mc, v >= 1 ? "set by DM_PSO_BG_QUEUES" : "DM_PSO_BG_QUEUES=<n> sets them");
    });
    return n;
}
static dispatch_queue_t pp_bg_queue(void) {
    static dispatch_queue_t q[8]; static int n; static _Atomic unsigned rr; static dispatch_once_t once;
    dispatch_once(&once, ^{ n = pp_bg_count();
        for (int i = 0; i < n; i++) q[i] = dispatch_queue_create("dm.nvn.pso-bg", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_UTILITY, 0)); });
    return q[atomic_fetch_add(&rr, 1) % (unsigned)n];
}
// Draws that waited for their pipeline on the submit thread, by why no stand-in served them: 0 hybrid pipelines off, 1 merged pass or readable-tile fragment, 2 diagnostic fragment,
// 3 no pulling entry (layer-writing or transform feedback vertex shader, or no pulling library), 4 pulling base not made yet; count and time (prediction walks left out)
static uint64_t g_pw_n[5], g_pw_ns[5];
static const char *const g_pw_why[5] = {"hybrid off", "merged pass or readable tile", "diagnostic fragment", "no pulling entry", "pulling base not made yet"};
// Takes a slot for k (with g_pp_mu held): a free one, else the oldest finished entry no draw took (its worker no longer touches it). spec: 0 a demanded build; 1 a speculative guess,
// refused while PSO_PEND_ACTIVE speculative guesses (spec 1) run; 2 a later draw of this submission, speculative but neither refused nor counted. Returns the slot, -1 when refused
// or k is in the table already
static int pso_pend_slot(const pso_key *k, int spec, uint32_t *gen) {
    int slot = -1, reclaim = -1, active = 0;
    if (pso_pend_find(k) >= 0) return -1;
    for (int i = 0; i < PSO_PEND_MAX; i++) {
        if (!g_pp[i].used) { if (slot < 0) slot = i; }
        else if (!g_pp[i].done) active += !g_pp[i].demand && !g_pp[i].next;
        else if (!g_pp[i].taking && (reclaim < 0 || g_pp[i].order < g_pp[reclaim].order)) reclaim = i;
    }
    if (spec == 1 && active >= PSO_PEND_ACTIVE) return -1;
    if (slot < 0) slot = reclaim;
    if (slot < 0) return -1;
    g_pp[slot].k = *k; g_pp[slot].ps = nil; g_pp[slot].d = nil; g_pp[slot].done = g_pp[slot].run = g_pp[slot].taking = 0; g_pp[slot].used = 1; g_pp[slot].demand = !spec; g_pp[slot].next = spec == 2; g_pp[slot].th = NULL;
    g_pp[slot].order = ++g_pp_kicked; *gen = ++g_pp[slot].gen;
    return slot;
}
static void pso_pend_start(int slot, uint32_t gen, MTLRenderPipelineDescriptor *d, int off, dispatch_queue_t q) {
    pthread_mutex_lock(&g_pp_mu); if (g_pp[slot].gen == gen) g_pp[slot].d = d; pthread_mutex_unlock(&g_pp_mu);   // only the submit thread takes a queued build, so none has yet
    dispatch_async(q, ^{
        pthread_mutex_lock(&g_pp_mu);
        int go = g_pp[slot].used && g_pp[slot].gen == gen && !g_pp[slot].run; if (go) { g_pp[slot].run = 1; g_pp[slot].d = nil; g_pp[slot].th = pthread_self(); }
        pthread_mutex_unlock(&g_pp_mu);
        if (!go) return;   // the draw made it itself
        NSError *e = nil; id<MTLRenderPipelineState> ps = pso_build(d, off, &e);
        pthread_mutex_lock(&g_pp_mu); if (g_pp[slot].gen == gen) { g_pp[slot].ps = ps; g_pp[slot].done = 1; g_pp[slot].th = NULL; } g_pp_done_n++; pthread_cond_broadcast(&g_pp_cv); pthread_mutex_unlock(&g_pp_mu);
    });
}
// Admission of a build of d, the descriptor of k (spec as pso_pend_slot: 1 a speculative guess, within budget when one is given, on the global queue; 2 a later draw of this
// submission as the scan met it, admitted whatever runs, on pp_bg_queue). Any thread (g_pp_mu): the submit thread and the predictions' base-lookup workers (pso_bg_look)
static int pso_pend_kick_d(const pso_key *k, MTLRenderPipelineDescriptor *d, int spec, PsoPredictBudget *budget) {
    pthread_mutex_lock(&g_pp_mu); uint32_t gen = 0; int slot = -1;
    if (spec != 1 || !budget || budget->admitted < PSO_PREDICT_BUDGET) {
        slot = pso_pend_slot(k, spec, &gen);
        if (slot >= 0 && spec == 1 && budget) budget->admitted++;
    }
    pthread_mutex_unlock(&g_pp_mu);
    if (slot < 0) return 0;
    pso_pend_start(slot, gen, d, !k->border, spec == 2 ? pp_bg_queue() : dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0));
    return 1;
}
static int pso_pend_kick_budget(const pso_key *k, NvShader *vs, NvShader *fs, int spec, PsoPredictBudget *budget) {   // the submit thread
    if (hm_get_id(&g_pso, k)) return 0;
    PD("J pipeline source=%s key=%016llx vs=%s fs=%s depth=%u stencil=%u samples=%u", spec == 2 ? "predict-next" : "predict", (unsigned long long)nvn_hm_hash(k, sizeof *k), vs->key, fs ? fs->key : "-", k->dfmt, k->sfmt, k->samples);
    return pso_pend_kick_d(k, pso_desc(k, vs, fs, nil, 0), spec, budget);
}
static int pso_pend_kick_(const pso_key *k, NvShader *vs, NvShader *fs, int spec) { return pso_pend_kick_budget(k, vs, fs, spec, nil); }
// Nonblocking admission of a speculative guess: no speculative backlog in front of a demanded compile
static int pso_pend_kick(const pso_key *k, NvShader *vs, NvShader *fs) { return pso_pend_kick_(k, vs, fs, 1); }
// A later draw of this submission as the scan met it, which would wait for its pipeline: admitted whatever runs, on pp_bg_queue. Its draw takes it when built, or makes it at once
// while it is still queued (pso_pend_take), so it never waits behind the others
static int pso_pend_kick_next(const pso_key *k, NvShader *vs, NvShader *fs) { return pso_pend_kick_(k, vs, fs, 2); }
// A pipeline served by a hybrid stand-in is a demand even if its background build has not finished when the process exits (upstream NXNative 015fed3a1). Record it for the next
// start's prepare step, independently of build admission; the existing writer drops the identical completion row. The map bounds early recording to 65,536 keys and avoids
// serializing repeated stand-in draws (submit thread). DM_PSO_DEMAND_RECORD=0 keeps record-on-completion. Measurements and the prepare-time tradeoff: docs/reference/shaders.md
static nvn_hmap g_demand_rec = {.klen = sizeof(pso_key)};
static void demand_record(const pso_key *k, NvShader *vs, NvShader *fs) {
    static int on = -1; if (on < 0) { const char *ev = getenv("DM_PSO_DEMAND_RECORD"); on = !(ev && !strcmp(ev, "0")); }
    if (!on || nvn_hm_get(&g_demand_rec, k) || g_demand_rec.n >= (1u << 16)) return;
    nvn_hm_put(&g_demand_rec, k, (void *)1);
    pso_skey sk; char shex[sizeof sk * 2 + 1]; pso_skey_from(k, vs, fs, 0, NULL, &sk); pso_skey_hex(&sk, shex);
    pso_user_record("R\t%s\n", shex);
}
// The build a hybrid draw asked for while it draws with its stand-in: outside the speculative limit, on pp_bg_queue
static int pso_pend_demand(const pso_key *k, NvShader *vs, NvShader *fs) {
    if (hm_get_id(&g_pso, k)) return 0;
    pthread_mutex_lock(&g_pp_mu); uint32_t gen = 0; int slot = pso_pend_slot(k, 0, &gen); pthread_mutex_unlock(&g_pp_mu);
    if (slot < 0) return 0;
    pso_pend_start(slot, gen, pso_desc(k, vs, fs, nil, 0), !k->border, pp_bg_queue());
    return 1;
}
// Called by the submit thread: a build in the table is taken (waited for while its worker runs it; made here at once while it is still queued, so a draw that waits waits for its
// own pipeline alone, not for the builds queued before it: Breath of the Wild's cold start waited 0.5-0.9 s for one pipeline behind a burst); nil when it is not in the table.
// A wait for a build its worker already runs lends the waiting thread's QoS to that worker until it ends (pthread_override_qos_class_start_np; a condition variable passes none):
// a later draw's build on pp_bg_queue runs at utility QoS, and without it the submit thread, which compiled such a draw itself before the look-ahead admitted it (upstream PR
// #1344), would wait for a utility compile, on the efficiency cores as iOS tends to run them
static id<MTLRenderPipelineState> pso_pend_take(const pso_key *k) {
    pthread_mutex_lock(&g_pp_mu);
    int at = pso_pend_find(k); id<MTLRenderPipelineState> ps = nil;
    if (at >= 0 && !g_pp[at].done && !g_pp[at].run && g_pp[at].d) {
        MTLRenderPipelineDescriptor *d = g_pp[at].d; g_pp[at].d = nil; g_pp[at].used = 0; g_pp_stolen++;
        pthread_mutex_unlock(&g_pp_mu);
        NSError *e = nil; return pso_build(d, !k->border, &e);
    }
    pthread_override_t ov = NULL;
    if (at >= 0 && !g_pp[at].done && g_pp[at].run && g_pp[at].th) {   // th is set until done: the worker is in pso_build, so the thread is alive here
        qos_class_t qc = qos_class_self(); ov = pthread_override_qos_class_start_np(g_pp[at].th, qc == QOS_CLASS_UNSPECIFIED ? QOS_CLASS_DEFAULT : qc, 0);
        if (ov) g_pp_boost++;
    }
    if (at >= 0) {
        g_pp[at].taking = 1;   // a base-lookup worker may admit, and reclaim a done slot, while the condition wait releases g_pp_mu: this one stays the draw's
        while (!g_pp[at].done) pthread_cond_wait(&g_pp_cv, &g_pp_mu);
        ps = g_pp[at].ps; g_pp[at].ps = nil; g_pp[at].used = g_pp[at].taking = 0;
    }
    pthread_mutex_unlock(&g_pp_mu);
    if (ov) pthread_override_qos_class_end_np(ov);
    return ps;
}
// Without waiting: 0 = not in the table; 1 = in it, still being built; 2 = built and taken into *out (nil when the build failed)
static int pso_pend_try(const pso_key *k, id<MTLRenderPipelineState> *out) {
    pthread_mutex_lock(&g_pp_mu);
    int at = pso_pend_find(k), st = at < 0 ? 0 : g_pp[at].done ? 2 : 1;
    *out = nil;
    if (st == 2) { *out = g_pp[at].ps; g_pp[at].ps = nil; g_pp[at].d = nil; g_pp[at].used = 0; }
    pthread_mutex_unlock(&g_pp_mu);
    return st;
}
// ---- Hybrid pipelines: a draw never waits for the Metal compiler ----
// On a pipeline miss the draw first takes its pipeline without compiling (the base made already, or in the pipeline archive: pso_build_ex(..., 0)). Failing that it draws with the
// pair's pulling pipeline (<key>_bp, dmsh_pull.py: no vertex descriptor; the vertex streams are read through a per-draw layout block, pull_bind), specialized with the draw's colour
// state, while the pipeline for its vertex layout is built in the background (pso_pend_demand); a later draw takes that one when it is ready (pso_pend_try). The pulling pipeline costs
// vertex time (the run-time format decode: about 1 ms per million vertices on an M2 Max), so it only bridges those frames. Both compute the same positions: [[position, invariant]],
// built with preserved invariance, from bit-identical inputs (t_pull.m, t_pull_inv.m). Only a pulling base already made or in the archive is used (the prebuild makes them); otherwise
// the draw waits as before and the pulling base is built in the background for the pair's next miss. Not for merged passes, readable-tile or diagnostic fragments, layer-writing or
// transform feedback vertex shaders. DM_PSO_HYBRID=0 turns it off
static int hybrid_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_PSO_HYBRID"); pso4_init(); v = !(e && !strcmp(e, "0")); if (!v) MLOG("hybrid pipelines off: a draw whose pipeline is not built yet waits for it"); }
    return v;
}
static nvn_hmap g_pso_hy = {.klen = sizeof(pso_key)};   // pulling pipelines by the key they stand in for (submit thread)
static int g_pso_pull;   // the pipeline pso_get_ returned reads its vertex streams through the layout block
static _Atomic uint64_t g_hy_draws, g_hy_made, g_hy_none, g_hy_kicked, g_hy_ns;   // draws with a pulling pipeline, pulling pipelines made, misses with no pulling base ready, pulling bases built for later, time
static _Atomic uint64_t g_hy_unkicked;   // pulling bases not sent to the background (DM_PSO_HYBRID_KICK=0 with an archive of cover pairs only), each counted once as g_hy_kicked is
// The pulling bases sent to the background (g_hy_kick_set) and those the switch left unbuilt (g_hy_skip_set), by base: hybrid_get meets the same key again on every draw while
// its layout pipeline is still pending, and on every submission's prediction scan (pso_predict_rest), so both counts are of distinct bases, not of lookups, and a run that
// kicks compares with one that skips. A base skipped while the switch held is still kicked if the decision changes later (another probe)
static NSMutableSet<NSData *> *g_hy_kick_set, *g_hy_skip_set; static os_unfair_lock g_hy_lock = OS_UNFAIR_LOCK_INIT;
// Set by pso_bundle_covers when the archive bundled with the app holds the bases of the pair list and the list is the shader split's cover pairs (pre_cover_only): a game whose
// programs have a single stage (a vertex shader alone, or a pixel shader alone), which the shader split pairs through a cover of one or a few pixel shaders because the real
// pairs exist only when a draw binds the two. 13 Sentinels: Aegis Rim has 376 vertex shaders, each listed with the pixel shader 0ddfcfcdcc3ddf9e, which no draw uses as its
// fragment; Luigi's Mansion 3 lists 963, each with the same 4. The bundled archive then holds no pulling base a draw asks for, so on such a game every hybrid miss also kicks the
// compile of a pulling base that only the same pair's next miss can use, beside the layout base the draw compiles at once on the submit thread; both reach Metal's compiler
// service at the same moment (sentinels/results.txt, topic pipelines). Cleared by every probe that does not find such an archive. Read by hybrid_kick_ok on the submit thread
static _Atomic int g_bundle_cover_only;
// Whether a hybrid miss sends its pulling base to the background (pp_bg_queue) to be built for the pair's next miss. DM_PSO_HYBRID_KICK=0 leaves it unbuilt when the archive bundled
// with the app has cover pairs only (above): an A/B test of whether those compiles, about half of a first run's in-play compiles on 13 Sentinels by the diagnosis's estimate, cost
// more than they save. It changes no draw: the miss waits for its layout base either way (pso_get_), and a pair whose pulling base is never built simply has no stand-in on a later
// miss of another layout or colour state, as before the base was made. The default (1) kicks it as before; with any other archive, or none, the switch does nothing. The env value
// is read once (g_hy_kick_env: -1 until read; t_pso_bundle sets it back to -1 to read the environment again), then decided per miss (pure, so t_pso_bundle checks it without the
// environment)
static int hybrid_kick_decide(int env_on, int cover_only) { return env_on || !cover_only; }
static _Atomic int g_hy_kick_env = -1;   // atomic, as the other switches the ntzuca port added: read once, on whichever thread first asks
static int hybrid_kick_ok(void) {
    if (g_hy_kick_env < 0) {
        const char *e = getenv("DM_PSO_HYBRID_KICK"); g_hy_kick_env = !(e && !strcmp(e, "0"));
        if (!g_hy_kick_env) MLOG("hybrid pipelines: DM_PSO_HYBRID_KICK=0, a miss does not build its pulling base in the background when the archive bundled with the app has cover pairs only");
    }
    return hybrid_kick_decide(g_hy_kick_env, atomic_load(&g_bundle_cover_only));
