static MTLRenderPipelineDescriptor *pso_desc_pull(const pso_key *k, NvShader *vs, NvShader *fs) {   // pso_desc's pipeline with the pulling entry point and no vertex descriptor
    id<MTLFunction> pf = pull_fn(vs); if (!pf) return nil;
    MTLRenderPipelineDescriptor *d = pso_desc(k, vs, fs, nil, 0);
    d.vertexFunction = pf; d.vertexDescriptor = [MTLVertexDescriptor vertexDescriptor];
    return d;
}
// A pulling base neither made nor archived: built in the background for the pair's next miss, once (any thread: a draw's miss through hybrid_get, or a prediction's base-lookup
// worker, pso_bg_look; upstream 9d3a58364 made this its own function). Unless DM_PSO_HYBRID_KICK=0 and the bundled archive has cover pairs only (hybrid_kick_ok): then the draw
// waits for its layout base alone. Either way a base is counted once (the sets above), so 'kicked' in one run and 'not kicked' in the other count the same thing
static void hy_base_kick(MTLRenderPipelineDescriptor *d, int off) {
    int kick = hybrid_kick_ok();
    pbase_key bk; pbase_key_of(d, off, &bk); NSData *kd = [NSData dataWithBytes:&bk length:sizeof bk];
    os_unfair_lock_lock(&g_hy_lock); if (!g_hy_kick_set) { g_hy_kick_set = [NSMutableSet set]; g_hy_skip_set = [NSMutableSet set]; }
    int fresh = ![g_hy_kick_set containsObject:kd];
    if (fresh && kick) [g_hy_kick_set addObject:kd];
    else if (fresh) { fresh = ![g_hy_skip_set containsObject:kd]; if (fresh) [g_hy_skip_set addObject:kd]; }
    os_unfair_lock_unlock(&g_hy_lock);
    if (fresh && kick) { g_hy_kicked++; dispatch_async(pp_bg_queue(), ^{ NSError *be = nil; (void)pso_build(d, off, &be); }); }
    else if (fresh) g_hy_unkicked++;
}
static __unsafe_unretained id<MTLRenderPipelineState> hybrid_get(const pso_key *k, NvShader *vs, NvShader *fs) {
    __unsafe_unretained id<MTLRenderPipelineState> h = hm_get_id(&g_pso_hy, k);
    if (h) return h;
    MTLRenderPipelineDescriptor *d = vs->has_pull ? pso_desc_pull(k, vs, fs) : nil;
    if (!d) return nil;
    NSError *e = nil; int off = !k->border; id<MTLRenderPipelineState> ps = pso_build_ex(d, off, &e, 0);
    if (!ps) { hy_base_kick(d, off); g_hy_none++; return nil; }   // the pulling base is neither made nor archived
    g_hy_made++; hm_put_id(&g_pso_hy, k, ps);
    return ps;
}
void mtl_hybrid_stats(uint64_t *draws, uint64_t *made, uint64_t *none) { *draws = g_hy_draws; *made = g_hy_made; *none = g_hy_none; }
// The pipeline time line of the timing summary (hle_nvn.c), the difference since the last call. 'pulling base builds kicked' counts the distinct pulling bases that hybrid lookups
// sent to the background (hybrid_get: a draw's miss, and the prediction scan's lookup of a predicted key, pso_predict_rest), apart from the predictions' layout builds ('background
// builds kicked', g_pp_kicked): a run's bases compiled then split into these, the layout bases the draws compiled and the predicted ones. Without it a 13 Sentinels log could only
// guess that split. 'not kicked' (the distinct bases the switch left unbuilt) appears only with DM_PSO_HYBRID_KICK=0 (hybrid_kick_ok)
void mtl_pso_line(char *o, size_t n) {
    enum { NV = 28 };
    // A background admission may finish between independent loads: the three are sampled together, so 'in flight' never underflows from mixed instants (upstream 9d3a58364)
    pthread_mutex_lock(&g_pp_mu); uint64_t kicked = g_pp_kicked, done = g_pp_done_n, stolen = g_pp_stolen; pthread_mutex_unlock(&g_pp_mu);
    static uint64_t p[NV]; uint64_t v[NV] = {g_bp_pso_ns, g_bp_lib_ns, g_pt_hit_n, g_pt_hit_ns, g_pt_miss_n, g_pt_miss_ns, g_pb_spec, g_pt_spec_ns, g_pb_built, g_pt_comp_ns, g_pt_pred_n, g_pt_pred_ns, g_hy_draws, g_hy_made, kicked, done, stolen, g_hy_none,
                                           g_pp_admit, g_hy_kicked, g_hy_unkicked, g_bgl_n, g_bgl_found, g_bgl_ns, g_pt_sub_n, g_pt_sub_ns, g_lw_n, g_lw_ns};
    uint64_t d[NV]; for (int i = 0; i < NV; i++) d[i] = v[i] - p[i];
    char unk[64] = "";
    if (d[20]) snprintf(unk, sizeof unk, ", %llu not kicked (DM_PSO_HYBRID_KICK=0)", (unsigned long long)d[20]);
    snprintf(o, n, "on the submit thread pipelines %.1f ms, shader libraries %.1f ms, predictions %llu / %.1f ms (builds admitted %llu); all threads: archive lookups found %llu / %.1f ms, found none %llu / %.1f ms, "
             "specializations %llu / %.1f ms, bases compiled %llu / %.1f ms; draws with a hybrid pipeline %llu (%llu pulling pipelines made, %llu misses with no pulling base ready, %llu pulling base builds kicked%s); "
             "background builds kicked %llu, done %llu, made by the draw %llu, in flight %llu; base lookups handed to the background %llu (found %llu, %.1f ms); "
             "of the archive lookups, on the submit thread %llu / %.1f ms; draws that waited for another thread's archive lookup %llu / %.1f ms",
             d[0] / 1e6, d[1] / 1e6, (unsigned long long)d[10], d[11] / 1e6, (unsigned long long)d[18], (unsigned long long)d[2], d[3] / 1e6, (unsigned long long)d[4], d[5] / 1e6, (unsigned long long)d[6], d[7] / 1e6,
             (unsigned long long)d[8], d[9] / 1e6, (unsigned long long)d[12], (unsigned long long)d[13], (unsigned long long)d[17], (unsigned long long)d[19], unk,
             (unsigned long long)d[14], (unsigned long long)d[15], (unsigned long long)d[16], (unsigned long long)(v[14] - v[15] - v[16]),
             (unsigned long long)d[21], (unsigned long long)d[22], d[23] / 1e6, (unsigned long long)d[24], d[25] / 1e6, (unsigned long long)d[26], d[27] / 1e6);
    memcpy(p, v, sizeof p);
    static uint64_t pn[5], pns[5]; size_t o2 = strlen(o);
    o2 += snprintf(o + o2, n > o2 ? n - o2 : 0, "; draws that waited:");
    for (int i = 0; i < 5; i++) if (g_pw_n[i] > pn[i]) o2 += snprintf(o + o2, n > o2 ? n - o2 : 0, " %s %llu / %.1f ms,", g_pw_why[i], (unsigned long long)(g_pw_n[i] - pn[i]), (g_pw_ns[i] - pns[i]) / 1e6);
    memcpy(pn, g_pw_n, sizeof pn); memcpy(pns, g_pw_ns, sizeof pns);
    static uint64_t pca, pcr, pcb, pcl, pcn; uint64_t ca = g_cps_arch, cr = g_cps_run, cb = g_cps_built, cl = g_cps_look_ns, cn = g_cps_build_ns;   // compute pipelines (cps_new)
    if (ca > pca || cr > pcr || cb > pcb)
        snprintf(o + o2, n > o2 ? n - o2 : 0, "; compute pipelines from the archive bundled with the app %llu, from this device's archive %llu, built %llu (%.1f ms looking up, %.1f ms building)",
                 (unsigned long long)(ca - pca), (unsigned long long)(cr - pcr), (unsigned long long)(cb - pcb), (cl - pcl) / 1e6, (cn - pcn) / 1e6);
    pca = ca; pcr = cr; pcb = cb; pcl = cl; pcn = cn;
}

// ---- Prebuild: the base of every shader pair of the game, into the pipeline archive ----
// For each pair in the profile's shader_pairs.tsv, the base a hybrid draw needs: the pulling vertex entry (<key>_bp; a vertex shader without stage inputs: its own entry), the pixel
// shader, no vertex descriptor, one sample, no alpha-to-coverage, the colour state unspecialized: the descriptor pso_desc_pull / pso_desc make at run time, so the archive gives it back
// there (the archive matches libraries by content). Bases already in the archive are skipped; what is built goes into the archive, flushed every 1,000 bases (the serializer holds
// what it captured until then). The pairs are handed out grouped by vertex shader (pre_order), and a pair whose vertex function another capture has is put back, never built
// beside it (fn_claim, pre_later_take). Runs once per chain version, depth mode and pair list, and again when a library file it lacked arrives (pso_archive/prebuilt.tsv, pre_stamp_done): in the app after the prewarm, on a background queue at utility QoS
// (DM_PSO_PREBUILD=0: not at all), or as a tool on the Mac (DM_PSO_PREBUILD=tool: build, write, exit). Vertex shaders that write the layer, pairs whose vertex shader has stage
// inputs but no pulling library, and integer-output or multisampled bases are left to the draws. An app that bundles these bases made offline (DM_PSO_BUNDLE, pso_bundle_covers)
// builds none of them, only the pairs that archive left to the device (rest_pairs.tsv beside it: functions with constants). A pair with no pixel key is a depth-only program's: its
// base has the host's empty fragment (pre_desc, nop_fragment). The split writes no such pairs yet; a depth-only draw builds its base itself, and the archive keeps it as any other
static _Atomic int g_pre_running; static _Atomic int g_pre_next, g_pre_done, g_pre_built, g_pre_archived, g_pre_skipped, g_pre_failed;   // g_pre_next: pairs handed to a worker
// g_pre_flushing: every worker has returned and the done block is writing the last period (prepare_prebuild then waits for it without a limit)
static _Atomic int g_pre_flushing;
// Pairs whose base failed to build, kept with the system build and the stamp they failed under (prebuild_failed.tsv beside prebuilt.tsv): prebuilt.tsv is written with them, and a
// later start with both the same leaves them to the draws instead of building them again, which would fail the same way (Metal reports a compile that its compiler service
// could not finish only after retrying it itself: Super Mario Odyssey's alRenderMaterialUber at -O2, 33.7 minutes, on every start in the background). Another system build (a new
// GPU compiler) or another stamp tries them again. g_pre_known: those lines by pair ("vertex<TAB>pixel"); g_pre_fails: this run's new lines
static NSDictionary<NSString *, NSString *> *g_pre_known; static NSMutableArray<NSString *> *g_pre_fails; static os_unfair_lock g_pre_fail_lock = OS_UNFAIR_LOCK_INIT;
static _Atomic int g_pre_known_n;   // pairs left to the draws because they failed on an earlier start
// Pairs whose capture found one of its shader functions under way in another (fn_claim): put back with those functions (k, n) and built once none of them is under way. g_pre_later,
// under g_fn_mu, so a worker picks one whose functions are free and a release (fn_release) wakes the ones waiting for one; g_pre_deferred: the put-backs this prebuild
typedef struct { int p, n; uint64_t k[3]; } PreLater;
static PreLater *g_pre_later; static int g_pre_later_n, g_pre_later_cap; static _Atomic int g_pre_deferred;
static void pre_later_put(const PreLater *l) {
    pthread_mutex_lock(&g_fn_mu);
    if (g_pre_later_n == g_pre_later_cap) {
        int cap = g_pre_later_cap ? g_pre_later_cap * 2 : 256; PreLater *m = realloc(g_pre_later, (size_t)cap * sizeof *m);
        if (!m) abort();
        g_pre_later = m; g_pre_later_cap = cap;
    }
    g_pre_later[g_pre_later_n++] = *l; g_pre_deferred++;
    pthread_cond_broadcast(&g_fn_cv); pthread_mutex_unlock(&g_fn_mu);
}
// → 1 and *l: a put-back pair none of whose functions is under way, taken off the list. wait: until there is one, without a limit: what it waits for is a compile under way, which
// holds its worker as long, so one that does not return (#294) keeps the prebuild from finishing either way (the prepare step does not wait for it: prepare_prebuild). → 0: none
// (wait: none left), or the process is ending (mtl_warm_stop), which is looked at before the list: each capture that returns frees its function's next pair, so a worker that
// took them after the stop built a shader's whole put-back run beside the archive's write, into a period the exit had handed over
static int pre_later_take(PreLater *l, int wait) {
    pthread_mutex_lock(&g_fn_mu);
    for (;;) {
        if (atomic_load(&g_warm_stop)) break;
        for (int i = 0; i < g_pre_later_n; i++)
            if (!fn_busy(g_pre_later[i].k, g_pre_later[i].n) && g_fn_nbusy + g_pre_later[i].n <= FN_BUSY_MAX) {
                *l = g_pre_later[i]; g_pre_later[i] = g_pre_later[--g_pre_later_n]; pthread_mutex_unlock(&g_fn_mu); return 1;
            }
        if (!wait || !g_pre_later_n) break;
        struct timespec until; clock_gettime(CLOCK_REALTIME, &until); until.tv_sec++;   // the process ending sets no condition: looked at every second
        pthread_cond_timedwait(&g_fn_cv, &g_fn_mu, &until);
    }
    pthread_mutex_unlock(&g_fn_mu);
    return 0;
}
static int pre_later_count(void) { pthread_mutex_lock(&g_fn_mu); int n = g_pre_later_n; pthread_mutex_unlock(&g_fn_mu); return n; }
// Pairs with a library file the app does not carry (an IPA packed without the pulling libraries _bp.metallib, IOS_PULL=0; a shader a partial build has not made yet):
// their bases cannot be made yet, so the stamp names one such file (pre_device_stamp) and a later start builds them once it is there. g_pre_nolib_file: the first one seen in this
// run, a name in the library, under g_pre_fail_lock
static _Atomic int g_pre_nolib; static NSString *g_pre_nolib_file;
// Whether the library has the file: in its folder or in its image (msl_image_file), as msl_data and lib_from_file read it
static int msl_has(NSString *path) { romfs_img *m; return !access(path.fileSystemRepresentation, F_OK) || msl_image_file(path, &m) != NULL; }
// 1 (and the file noted) when the library lacks <key><suffix>
static int pre_lib_absent(NSString *key, NSString *suffix) {
    NSString *name = [key stringByAppendingString:suffix];
    if (msl_has([g_msl_dir stringByAppendingPathComponent:name])) return 0;
    g_pre_nolib++; os_unfair_lock_lock(&g_pre_fail_lock); if (!g_pre_nolib_file) g_pre_nolib_file = name; os_unfair_lock_unlock(&g_pre_fail_lock);
    return 1;
}
static NSString *pre_fail_head(NSString *want) { return [arch_os_build() stringByAppendingString:want]; }   // what a failure list must have been written for
// The prebuild's files it no longer needs. Its bases go into files of their own (pb<seq>_<program>, arch_pre_begin), so a file the prebuild wrote holds nothing else, and only
// its own program's files are candidates (arch_pre_mine: the programs of one application share the folder, each with its own pair list). A prebuild that runs (a new stamp:
// other pairs, another chain version or depth mode) looks every pair up in the files first; each of its earlier files that gave no pair's base holds only bases of pairs no
// longer listed, of other libraries or of the other depth mode, or bases another file gave first, and is removed once every pair is done, before the new stamp is written. When
// the archive bundled with the app holds every pair's base and left none to the device (pso_bundle_covers, no rest_pairs.tsv), every one of them only repeats it: they are
// removed, and prebuilt.tsv with them when it is this program's stamp (the folder has one, which another program's prebuild may have written last), so that a later start the
// bundle does not cover (an OS update that changed the GPU compiler) builds them again. Before it had files of its own the prebuild wrote p<seq> files, which also hold draws'
// bases: those are never removed. A file a base was found in stays, also when it holds stale bases beside it. DM_PSO_PREBUILD_TRIM=0 keeps every file. g_pre_old: this run's candidates (the prebuild's files opened at start, among those looked up; archive → path),
// g_pre_used: those of them a pair's base was found in
static NSMapTable *g_pre_old; static NSHashTable *g_pre_used; static os_unfair_lock g_pre_used_lock = OS_UNFAIR_LOCK_INIT;
static void pre_candidates(void) {
    const char *e = getenv("DM_PSO_PREBUILD_TRIM");
    g_pre_old = nil; g_pre_used = nil;
    if ((e && !strcmp(e, "0")) || !g_arch_pre_files.count) return;
    g_pre_old = [[NSMapTable alloc] initWithKeyOptions:NSPointerFunctionsStrongMemory | NSPointerFunctionsObjectPointerPersonality valueOptions:NSPointerFunctionsStrongMemory capacity:0];
    g_pre_used = [[NSHashTable alloc] initWithOptions:NSPointerFunctionsStrongMemory | NSPointerFunctionsObjectPointerPersonality capacity:0];
    for (NSArray<id<MTL4Archive>> *l in @[g_arch4p ?: @[], g_arch_ixf ?: @[]])   // a file with a complete index is in g_arch_ixf alone
        for (id<MTL4Archive> a in l) { NSString *p = [g_arch_pre_files objectForKey:a]; if (p) [g_pre_old setObject:p forKey:a]; }
}
static void pre_credit(id<MTL4Archive> a) {   // a pair's base was found in a (pre_pair)
    if (!g_pre_old) return;
    os_unfair_lock_lock(&g_pre_used_lock); if ([g_pre_old objectForKey:a]) [g_pre_used addObject:a]; os_unfair_lock_unlock(&g_pre_used_lock);
}
static int pre_trim(int all, const char *why) {   // removes the candidates no base was found in (all: every one); the number removed
    int n = 0; unsigned long long bytes = 0;
    for (id<MTL4Archive> a in g_pre_old) {
        if (!all && [g_pre_used containsObject:a]) continue;
        NSString *p = [g_pre_old objectForKey:a]; if (!p) continue;
        unsigned long long sz = [[NSFileManager.defaultManager attributesOfItemAtPath:p error:nil] fileSize];
        if (!unlink(p.fileSystemRepresentation)) { n++; bytes += sz; }   // an open archive stays usable for the rest of the run, as after a compaction
        unlink(arch_keys_path(p).fileSystemRepresentation);
        [g_arch_pre_files removeObjectForKey:a];
    }
    if (n) MLOG("pipeline prebuild: %d of its files removed, %.1f MB (%s)", n, bytes / 1048576.0, why);
    g_pre_old = nil; g_pre_used = nil;
    return n;
}
// The failure list at path, by pair, when it was written for this system build and stamp (else empty). *other: a list written for another system build or stamp exists
static NSDictionary<NSString *, NSString *> *pre_fail_load(NSString *path, NSString *want, int *other) {
    NSString *txt = [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil];
    *other = 0; if (!txt) return @{};
    NSMutableString *head = [NSMutableString string]; NSMutableDictionary<NSString *, NSString *> *pairs = [NSMutableDictionary dictionary];
    for (NSString *l in [txt componentsSeparatedByString:@"\n"]) {
        if (!l.length || [l hasPrefix:@"#"]) continue;
        NSArray<NSString *> *c = [l componentsSeparatedByString:@"\t"];
        if (c.count >= 3 && [c[0] isEqualToString:@"fail"]) pairs[[NSString stringWithFormat:@"%@\t%@", c[1], c[2]]] = l;
        else [head appendFormat:@"%@\n", l];
    }
    if ([head isEqualToString:pre_fail_head(want)]) return pairs;
    *other = 1; return @{};
}
static MTL4FunctionDescriptor *pre_fn(id<MTLLibrary> lib, NSString *name) {   // the common draw's specialization: defaults, with unused border corrections off (as fn_off's)
    id<MTLFunction> f = [lib newFunctionWithName:name]; if (!f) return nil;
    MTL4LibraryFunctionDescriptor *ld = [MTL4LibraryFunctionDescriptor new]; ld.library = lib; ld.name = name;
    if (!f.functionConstantsDictionary.count) return ld;
    MTLFunctionConstantValues *cv = [MTLFunctionConstantValues new];
    if (f.functionConstantsDictionary[@"dm_border_off"]) { BOOL yes = YES; [cv setConstantValue:&yes type:MTLDataTypeBool atIndex:DMSH_BORDER_FC]; }
    MTL4SpecializedFunctionDescriptor *sd = [MTL4SpecializedFunctionDescriptor new]; sd.functionDescriptor = ld; sd.constantValues = cv; return sd;
}
static NSDictionary *pre_json(NSString *key) { NSData *d = msl_data([NSString stringWithFormat:@"%@/%@_b.json", g_msl_dir, key]); return d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:nil] : nil; }
// The base of one pair as the draws make it (pso_desc_pull / pso_desc), or nil when the pair is left to the draws. Call inside an autorelease pool. A pair with no pixel key
// (a line "<vertex key><TAB>" in a pair list) is a depth-only program's: its base takes the host's empty fragment (nop_fragment), as pso_desc4 gives such a draw. fe, samples and
// a2c: a stand-in of the bundle's standins.tsv (pso_offline.py plan_standins), the pulling base of a pair a prewarm row draws with: the fragment entry its targets call for (nil:
// the shader's own), its sample count and alpha to coverage, as pso_desc_pull describes such a draw's pipeline
static MTL4RenderPipelineDescriptor *pre_desc_ex(NSString *vk, NSString *fk, int zero, NSString *fe, NSUInteger samples, int a2c) {
    int depth = !fk.length;
    NSDictionary *vj = pre_json(vk), *fj = depth ? @{} : pre_json(fk);
    if ((!vj && pre_lib_absent(vk, @"_b.json")) || (!fj && pre_lib_absent(fk, @"_b.json"))) return nil;
    if (!vj || !fj || ![vj[@"chain"] isEqual:@DMSH_CHAIN] || (!depth && ![fj[@"chain"] isEqual:@DMSH_CHAIN])) return nil;
    if (vj[@"mesh_stage"]) return nil;   // a mesh shader's pair (shader_pairs.tsv holds them for its padding): mesh pipelines are built at the draw (nvn_geometry.inc mtk_pso), no base
    NSString *ventry = zero && vj[@"entry_z"] ? vj[@"entry_z"] : vj[@"entry"], *fentry = fe.length ? fe : fj[@"entry"] ?: @"main0";
    int pull = [vj[@"pull"] isKindOfClass:[NSDictionary class]];
    if (pull) ventry = side_entry(vj[@"pull"], zero && vj[@"entry_z"] ? @"entry_z" : @"entry", ventry);   // its name in the pulling library, as shader_load gives pull_load
    if (!pull && [vj[@"vertex_inputs"] count]) return nil;   // stage inputs and no pulling library: its pipelines need the draw's layout
    if ([vj[@"layer_out"] boolValue]) return nil;   // writes the layer (as shader_load takes it): its pipelines take an input primitive class (pso_desc), no pulling pipeline
    NSDictionary *fr = fj[@"raster"]; if ([fr isKindOfClass:[NSDictionary class]] && [fr[@"primitive_id"] intValue]) return nil;   // reads the primitive ID: its pipelines are built whole (pso_build_ex), no base
    NSError *e = nil;
    if (pre_lib_absent(vk, pull ? @"_bp.metallib" : @"_b.metallib") || (!depth && pre_lib_absent(fk, @"_b.metallib"))) return nil;
    id<MTLLibrary> vl = lib_from_file([NSString stringWithFormat:@"%@/%@%@.metallib", g_msl_dir, vk, pull ? @"_bp" : @"_b"], &e);
    if (!vl) return nil;
    id<MTLLibrary> fl = depth ? nil : lib_from_file([NSString stringWithFormat:@"%@/%@_b.metallib", g_msl_dir, fk], &e);
    MTL4FunctionDescriptor *vf = pre_fn(vl, ventry), *ff = depth ? fn4_of(nop_fragment()) : fl ? pre_fn(fl, fentry) : nil;
    if (!vf || !ff) return nil;
    MTL4RenderPipelineDescriptor *m = [MTL4RenderPipelineDescriptor new];
    m.vertexFunctionDescriptor = vf; m.fragmentFunctionDescriptor = ff; m.vertexDescriptor = [MTLVertexDescriptor vertexDescriptor]; m.rasterSampleCount = samples ?: 1;
    if (a2c) m.alphaToCoverageState = MTL4AlphaToCoverageStateEnabled;
    for (int i = 0; i < 8; i++) { MTL4RenderPipelineColorAttachmentDescriptor *a = m.colorAttachments[i];
        a.pixelFormat = MTLPixelFormatUnspecialized; a.writeMask = MTLColorWriteMaskUnspecialized; a.blendingState = MTL4BlendStateUnspecialized;
        a.sourceRGBBlendFactor = a.destinationRGBBlendFactor = a.sourceAlphaBlendFactor = a.destinationAlphaBlendFactor = MTLBlendFactorUnspecialized;
        a.rgbBlendOperation = a.alphaBlendOperation = MTLBlendOperationUnspecialized; }
    return m;
}
static MTL4RenderPipelineDescriptor *pre_desc(NSString *vk, NSString *fk, int zero) { return pre_desc_ex(vk, fk, zero, nil, 1, 0); }
// → 1 when another capture has one of its shader functions (fn_claim; never waited for here): the pair is not built, l->k and l->n name its functions (the prebuild puts it back)
static int pre_pair(NSString *vk, NSString *fk, int zero, PreLater *l) {
    @autoreleasepool {
        if (g_pre_known.count && g_pre_known[[NSString stringWithFormat:@"%@\t%@", vk, fk]]) { g_pre_skipped++; g_pre_known_n++; return 0; }
        MTL4RenderPipelineDescriptor *m = pre_desc(vk, fk, zero);
        if (!m) { g_pre_skipped++; return 0; }
        id<MTL4Archive> from = nil;
        if (arch_lookup_in(m, 0, NULL, &from)) { g_pre_archived++; pre_credit(from); return 0; }
        NSError *e = nil; int busy = 0; id ps = arch_capture_try(m, &e, 0, NULL, 1, 0, &busy);
        if (busy) { l->n = fn_ids(m, l->k); return 1; }
        if (ps) g_pre_built++;
        else {
            if (g_pre_failed++ < 4) MLOG("[RED] pipeline prebuild: the base of %s + %s failed: %s", vk.UTF8String, fk.UTF8String, e.localizedDescription.UTF8String);
            NSString *why = [[[e.localizedDescription ?: @"no error" componentsSeparatedByCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]
                              filteredArrayUsingPredicate:[NSPredicate predicateWithFormat:@"length > 0"]] componentsJoinedByString:@" "];
            os_unfair_lock_lock(&g_pre_fail_lock); [g_pre_fails addObject:[NSString stringWithFormat:@"fail\t%@\t%@\t%@", vk, fk, why]]; os_unfair_lock_unlock(&g_pre_fail_lock);
        }
    }
    return 0;
}
// What a prebuild covers (prebuilt.tsv): the chain version, the depth mode, and the pair lists' length in bytes and SHA-256 (first 16 hex digits). dm/gfx/tools/pso_offline.py writes
// the same for the archive it makes offline, from the same files
static NSString *pre_stamp(NSString *txt, int zero) {
    NSData *d = [txt dataUsingEncoding:NSUTF8StringEncoding]; uint8_t h[CC_SHA256_DIGEST_LENGTH]; CC_SHA256(d.bytes, (CC_LONG)d.length, h);
    return [NSString stringWithFormat:@"chain\t%s\ndepth\t%s\npairs\t%lu\t%02x%02x%02x%02x%02x%02x%02x%02x\n", DMSH_CHAIN, zero ? "near=0" : "near=-w", (unsigned long)d.length,
            h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]];
}
// The device's own prebuilt.tsv: that stamp, then whether the run found every library file its pairs need: "libs all", or "libs missing <file>" naming one it lacked (pre_lib_absent).
// The stamp describes the pair lists, not the libraries the app carries, which a later package of the same chain can add (an IPA packed with the pulling libraries), so a stamp
// that names a file counts as done only while the library still lacks it. A stamp without this line was written before it existed and may hide pairs left out for an absent
// library, so it does not count as done; the bases already in the archive make that one more run short. The archive made offline keeps the stamp alone (pso_bundle_covers)
static NSString *pre_device_stamp(NSString *want) { return g_pre_nolib_file ? [want stringByAppendingFormat:@"libs\tmissing\t%@\n", g_pre_nolib_file] : [want stringByAppendingString:@"libs\tall\n"]; }
static int pre_stamp_done(NSString *have, NSString *want) {
    if (![have hasPrefix:want]) return 0;
    NSString *libs = [have substringFromIndex:want.length], *head = @"libs\tmissing\t";
    if ([libs isEqualToString:@"libs\tall\n"]) return 1;
    if (![libs hasPrefix:head] || ![libs hasSuffix:@"\n"] || libs.length <= head.length + 1) return 0;
    NSString *name = [libs substringWithRange:NSMakeRange(head.length, libs.length - head.length - 1)];
    if ([name rangeOfCharacterFromSet:[NSCharacterSet characterSetWithCharactersInString:@"/\t\n"]].location != NSNotFound) return 0;
    return !msl_has([g_msl_dir stringByAppendingPathComponent:name]);   // still absent: the same app, nothing more to build
}
static NSArray<NSArray<NSString *> *> *pre_parse(NSString *txt) {   // (vertex key, pixel key) per line, without empty lines, comments, # cover padding sections and repeated lines
    NSMutableArray<NSArray<NSString *> *> *pairs = [NSMutableArray array]; NSMutableSet<NSString *> *seen = [NSMutableSet set]; int cover = 0;
    for (NSString *l in [txt componentsSeparatedByString:@"\n"]) {
        if (!l.length) continue;
        if ([l hasPrefix:@"#"]) {
            if ([l isEqualToString:@"# cover"] || [l hasPrefix:@"# cover:"] || [l hasPrefix:@"# cover "] || [l hasPrefix:@"# cover\t"]) cover = 1;
            else if ([l hasPrefix:@"# kind:"]) cover = 0;
            continue;
        }
        if (cover || [seen containsObject:l]) continue;
        [seen addObject:l]; NSArray *c = [l componentsSeparatedByString:@"\t"]; if (c.count >= 2) [pairs addObject:c];
    }
    return pairs;
}
// A row's key for a set: its columns joined. Never a set of the NSArrays themselves: an NSArray's hash is its count, so every pair falls in one bucket and each lookup compares
// against all of them (Ocarina of Time's 34,600 rows: some 600 million comparisons before the first frame, which never came on the iPhone)
static NSString *pre_key(NSArray<NSString *> *p) { return [p componentsJoinedByString:@"\t"]; }
static NSArray<NSArray<NSString *> *> *pre_parse_files(NSArray<NSString *> *texts) {   // parse each file independently so a # cover section never hides a headerless later file
    NSMutableArray<NSArray<NSString *> *> *pairs = [NSMutableArray array]; NSMutableSet<NSString *> *seen = [NSMutableSet set];
    for (NSString *t in texts) for (NSArray<NSString *> *p in pre_parse(t)) { NSString *k = pre_key(p); if (![seen containsObject:k]) { [seen addObject:k]; [pairs addObject:p]; } }
    return pairs;
}
// Whether the archive bundled with the app (pso_bundle_open) holds this run's prebuild: its prebuilt.tsv is the stamp the device would write for these pairs and this depth mode,
// and a probe of up to 16 pairs spread over the list (not those it left to the device, rest) finds every base it makes in it (an archive that opens but whose binaries this system
// does not take finds none)
// What the probe proves is narrower than 'every base the game needs': the archive holds only bases without a vertex layout (pulling bases), and only for the pairs of the list
// (shader_pairs.tsv, with pso_pairs.tsv or DM_PSO_PAIRS). Of the bases with a vertex layout that the draws take, it holds only those of the prewarm list's R rows (pso_offline.py's
// layout bases, which the prepare line counts: 'layout bases from the archive bundled with the app'); any other is compiled on the device, and a game whose programs have one stage
// is listed through cover pixel shaders no draw pairs that way (pre_cover_only). The line used to read 'holds the bases of every shader pair (16 of 16 probed bases found)', which
// a 13 Sentinels run printed while it compiled 110 bases in play; it now names what was probed (lists: the pair lists pso_prebuild read), and says when the list holds cover pairs only
enum { PRE_PROBE = 16 };
// Whether the list is the shader split's cover pairs (separable_pairs in shader_split.py), not pairs any draw makes: every single-stage vertex shader is listed with the same cover,
// the fewest pixel shaders whose read locations together equal those of all of them, so the list is a full cross product of many vertex shaders over a few pixel shaders. 13
// Sentinels: 376 vertex shaders × 1; Luigi's Mansion 3: 963 × 4; about 50 profiles in all, from 6 × 1 to 45,614 × 2. One pixel shader over at least two vertex shaders counts, as
// before; with more pixel shaders it takes at least 4 vertex shaders for each, since three Unity games list real BNSH variation pairs that also form a full cross product, 3 × 2
// (Pokémon Brilliant Diamond, Subnautica, Subnautica: Below Zero), and a cover list has hundreds of vertex shaders over its few pixel shaders. A list with cover pairs and real
// pairs beside them (pso_pairs.tsv) is no cross product and does not count. A depth-only pair (no pixel key) does not count either way
static int pre_cover_only(NSArray<NSArray<NSString *> *> *pairs) {
    NSMutableDictionary<NSString *, NSMutableSet<NSString *> *> *by = [NSMutableDictionary dictionary]; NSMutableSet<NSString *> *px = [NSMutableSet set];
    for (NSArray<NSString *> *p in pairs) {
        if (p.count < 2 || !p[1].length) continue;
        NSMutableSet<NSString *> *s = by[p[0]]; if (!s) by[p[0]] = s = [NSMutableSet set];
        [s addObject:p[1]]; [px addObject:p[1]];
    }
    if (by.count < 2 || (px.count > 1 && by.count < 4 * px.count)) return 0;
    for (NSSet<NSString *> *s in by.objectEnumerator) if (s.count != px.count) return 0;   // each vertex shader's set is part of px: the same size means the same set
    return 1;
}
static const char *stamp_line(NSString *st) {   // a stamp on one line, for the log
    return [[[st stringByTrimmingCharactersInSet:NSCharacterSet.newlineCharacterSet] stringByReplacingOccurrencesOfString:@"\n" withString:@"; "] stringByReplacingOccurrencesOfString:@"\t" withString:@" "].UTF8String;
}
// The stand-ins of the archive bundled with the app (its standins.tsv, pso_offline.py plan_standins): the pulling bases of the pairs the prewarm list's R rows draw with, which a
// hybrid miss of such a pair takes from the archive (hybrid_get) instead of waiting for the compiler, where the pair lists hold cover pairs no draw makes or lack pairs made at draw
// time. standin_rows: the file's rows (vertex key, pixel key, fragment entry, samples, alpha to coverage), from the bundle's folder dir
static NSArray<NSArray<NSString *> *> *standin_rows(NSString *dir) {
    NSString *txt = dir ? [NSString stringWithContentsOfFile:[dir stringByAppendingPathComponent:@"standins.tsv"] encoding:NSUTF8StringEncoding error:nil] : nil;
    NSMutableArray<NSArray<NSString *> *> *rows = [NSMutableArray array];
    for (NSString *l in [txt componentsSeparatedByString:@"\n"]) { NSArray<NSString *> *c = [l componentsSeparatedByString:@"\t"]; if (c.count >= 5 && c[0].length) [rows addObject:c]; }
    return rows;
}
// *probed / *found: up to STANDIN_PROBE of rows spread over the file, looked up in arch as pso_desc_pull describes them (pre_desc_ex). Returns how many rows there are
enum { STANDIN_PROBE = PRE_PROBE / 2 };
static int standin_probe_in(id<MTL4Archive> arch, NSArray<NSArray<NSString *> *> *rows, int zero, int *probed, int *found) {
    *probed = *found = 0;
    NSUInteger n = rows.count;
    for (NSUInteger k = 0; k < STANDIN_PROBE && k < n; k++) @autoreleasepool {
        NSArray<NSString *> *c = rows[k * n / MIN(n, (NSUInteger)STANDIN_PROBE)];
        MTL4RenderPipelineDescriptor *m = pre_desc_ex(c[0], c[1], zero, c[2], (NSUInteger)MAX(1, c[3].intValue), c[4].intValue != 0);
        if (!m) continue;
        (*probed)++; *found += [arch newRenderPipelineStateWithDescriptor:m error:nil] != nil;
    }
    return (int)n;
}
// The probe's lookups only tell the log whether this system takes the stand-ins (pso_bundle_covers' verdict does not depend on them), and each costs two reflections, two library
// loads and a lookup: the pair probe's 15 took 18.8 ms on an iPhone 18 Pro Max (Ocarina of Time, the oot-field1 log), so 8 more would add about 10 ms before the first frame at
// every start. They run at utility QoS beside the game's first frames instead, and say so on a line of their own; the probe line gives the count alone. g_standin_bg: t_pso_bundle
// waits for it
static dispatch_group_t g_standin_bg;
static void standin_probe_bg(NSArray<NSArray<NSString *> *> *rows, int zero) {
    static dispatch_once_t once; dispatch_once(&once, ^{ g_standin_bg = dispatch_group_create(); });
    id<MTL4Archive> arch = g_arch_bundle;
    dispatch_group_async(g_standin_bg, dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{ @autoreleasepool {
        uint64_t t0 = bp_now(); int sp = 0, sf = 0; standin_probe_in(arch, rows, zero, &sp, &sf);
        MLOG("pipeline archive bundled with the app: stand-ins for the pairs the prewarm list's R rows draw with: %d of %d probed found (%.1f ms, in the background)", sf, sp,
             (bp_now() - t0) / 1e6);   // scripts/devlog.py reads it with the probe line's count
    } });
}
static int pso_bundle_covers(NSArray<NSArray<NSString *> *> *pairs, NSString *want, int zero, NSString *rest, const char *lists) {
    atomic_store(&g_bundle_cover_only, 0);   // until this probe finds an archive of cover pairs: an earlier probe's flag must not outlive an archive this one refuses
    NSString *have = [NSString stringWithContentsOfFile:[g_bundle_dir stringByAppendingPathComponent:@"prebuilt.tsv"] encoding:NSUTF8StringEncoding error:nil];
    if (![have isEqualToString:want]) {
        MLOG("pipeline archive bundled with the app: made for %s, this run needs %s: the device builds the bases it does not hold%s", have ? stamp_line(have) : "(no prebuilt.tsv)", stamp_line(want),
             have && [have rangeOfString:zero ? @"depth\tnear=-w" : @"depth\tnear=0"].location != NSNotFound ? " (the game's depth mode is not the one built for: the profile key depth_mode)" : "");
        return 0;
    }
    NSMutableSet<NSString *> *left = [NSMutableSet set]; for (NSArray<NSString *> *p in pre_parse(rest ?: @"")) [left addObject:pre_key(p)];   // string keys (pre_key)
    NSMutableArray<NSArray<NSString *> *> *cand = [NSMutableArray array];
    for (NSArray<NSString *> *p in pairs) if (![left containsObject:pre_key(@[p[0], p[1]])]) [cand addObject:p];
    uint64_t t0 = bp_now(); int probed = 0, found = 0; NSUInteger n = cand.count;
    for (NSUInteger k = 0; k < PRE_PROBE && k < n; k++) @autoreleasepool {
        NSArray<NSString *> *p = cand[k * n / MIN(n, (NSUInteger)PRE_PROBE)];
        MTL4RenderPipelineDescriptor *m = pre_desc(p[0], p[1], zero);
        if (!m) continue;
        probed++; found += [g_arch_bundle newRenderPipelineStateWithDescriptor:m error:nil] != nil;
    }
    int ok = probed > 0 && found == probed;   // skipped samples give no evidence that this system can take a base from the archive
    int cover = ok && pre_cover_only(pairs);
    atomic_store(&g_bundle_cover_only, cover);
    NSArray<NSArray<NSString *> *> *srows = ok ? standin_rows(g_bundle_dir) : nil; int sn = (int)srows.count;
    if (sn) standin_probe_bg(srows, zero);   // their lookups: in the background (above)
    NSString *tail = [NSString stringWithFormat:@"%s%@", !ok ? ": the device builds them" : !cover ? "" : sn
        ? "; cover pairs only: the listed pairs are not those the game draws with; of those it holds the layout bases of the prewarm list's R rows (the prepare line counts them) and "
          "their stand-ins, their other bases are compiled as the draws meet them"
        : "; cover pairs only: the pairs the game draws with are not in this archive (it holds only the layout bases of the prewarm list's R rows, which the prepare "
          "line counts), their other bases are compiled as the draws meet them",
        sn ? [NSString stringWithFormat:@"; stand-ins for the pairs the prewarm list's R rows draw with: %d (looked up in the background)", sn] : @""];
    MLOG("pipeline archive bundled with the app: %s (%d of %d probed pairs from %s found, %.1f ms)%s", ok ? "holds the bases of the listed shader pairs" : "this system does not take its bases",
         found, probed, lists, (bp_now() - t0) / 1e6, tail.UTF8String);
    return ok;
}
// The prebuild tool's workers: each waits on one synchronous compile, so as many as Metal's compiler runs at once (maximumConcurrentCompilationTaskCount); the device's active cores where Metal
// does not say. Not hw.perflevel0: on the chips with three core levels that is only the Super cores (2 on an M6, 5 on an M5 Pro), which gave the tool 1 and 4 workers
// (docs/reference/shaders.md, A prebuild pool sized from the Super cores). The prepare step keeps the active cores (prepare_workers) until a device run reports Metal's count there: pp_bg_count reads it on the iPhone too and logs it in its
// 'pipeline builds in the background' line. The background pools take a share of level 0, raised by that count (pp_bg_count)
static int compile_tasks(void) {
    NSUInteger n = g_dev.maximumConcurrentCompilationTaskCount;   // every device of macOS 27.2 / iOS 27.2 has it (macOS 13.3, iOS 26)
    if (n >= 2) return (int)n;
    int c = 0; size_t sz = sizeof c; if (sysctlbyname("hw.activecpu", &c, &sz, NULL, 0) || c < 2) c = 2;
    return c;
}
// The prebuild's order: the pairs by the index in which they are handed out, the pairs of a vertex shader one after another and the shader with the most pairs first (upstream
// NXNative 75758b940). The captures of one shader never run at once (fn_claim): the workers put its other pairs back, take other shaders' pairs, and build the ones put back one at
// a time as the shader comes free (pre_later_take). So each shader's pairs follow one another from the start, the longest run first, within few flush periods. The price: no
// prebuild is shorter than its largest shader's pairs one at a time, and a list where one vertex shader has most pairs is prebuilt about one capture at a time (STEINS;GATE
// RE:BOOT: 474 of 483; Kirby and the Forgotten Land: 3,148 of 21,409, more than 16 workers' even share; rendering.md, Two captures of one shader function). Upstream's Ocarina
// of Time tool prebuild on an M4 Pro (34,649 pairs, 14 workers, a cold archive): 493-496 s and 8.5 GB of archive, against 644-664 s and 9.2 GB in list order without fn_claim
// (which crashed 1 run of 6 there), and 707-713 s and 10 GB with the pairs spread across the list (each period then had nearly every shader, and wrote its own copy of each)
// Upstream sorts the indices with a comparator that looks both shaders' counts up and compares their keys at every step; here each pair's count and its shader's place among
// the sorted keys are found once and the sort is on integers, in the same order (the list's index last: list order within a shader). Monster Hunter Rise's 102,345 pairs on
// an M4 Max under load: 0.2-0.3 s against 0.85-1.4 s; Ocarina of Time's shader_pairs.tsv (28,178): 37-46 ms against 100-265 ms
static int pre_order_cmp(const void *a, const void *b) {   // {count, the shader key's rank, index}: the most pairs first, then by key, then list order
    const int *x = a, *y = b;
    return x[0] != y[0] ? (x[0] > y[0] ? -1 : 1) : x[1] != y[1] ? (x[1] < y[1] ? -1 : 1) : (x[2] > y[2]) - (x[2] < y[2]);
}
static NSArray<NSNumber *> *pre_order(NSArray<NSArray<NSString *> *> *pairs) {
    NSUInteger n = pairs.count;
    NSMutableDictionary<NSString *, NSNumber *> *c = [NSMutableDictionary dictionary];   // a vertex shader's pairs
    for (NSArray<NSString *> *p in pairs) c[p[0]] = @(c[p[0]].intValue + 1);
    NSArray<NSString *> *keys = [c.allKeys sortedArrayUsingSelector:@selector(compare:)];
    NSMutableDictionary<NSString *, NSNumber *> *rank = [NSMutableDictionary dictionaryWithCapacity:keys.count];
    for (NSUInteger i = 0; i < keys.count; i++) rank[keys[i]] = @(i);
    int (*e)[3] = malloc((n ? n : 1) * sizeof *e);
    if (!e) abort();
    for (NSUInteger i = 0; i < n; i++) { NSString *v = pairs[i][0]; e[i][0] = c[v].intValue; e[i][1] = rank[v].intValue; e[i][2] = (int)i; }
    qsort(e, n, sizeof *e, pre_order_cmp);
    NSMutableArray<NSNumber *> *ord = [NSMutableArray arrayWithCapacity:n];
    for (NSUInteger i = 0; i < n; i++) [ord addObject:@(e[i][2])];
    free(e);
    return ord;
}
// threads: workers; wait: run on the calling thread until done (the tool), else in the background. Returns the number of pairs, -1 when there is nothing to do
static int pso_prebuild(int threads, int wait, dispatch_qos_class_t qos) {
    shmap_load(); pso4_init();
    if ((!g_arch_bundle && !g_arch_cap) || atomic_exchange(&g_pre_running, 1)) return -1;
    // The pairs: shader_pairs.tsv (BNSH variations and the other readers' pairs) and pso_pairs.tsv (agl BAHS program variations, also read by vs_pad; DM_PSO_PAIRS: another path),
    // both beside the shader map
    NSString *pp = [g_shmap_path.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"shader_pairs.tsv"];
    const char *ev = getenv("DM_PSO_PAIRS");
    NSString *pp2 = ev && *ev ? @(ev) : [g_shmap_path.stringByDeletingLastPathComponent stringByAppendingPathComponent:@"pso_pairs.tsv"];
    NSString *txt = [NSString stringWithContentsOfFile:pp encoding:NSUTF8StringEncoding error:nil], *txt2 = [NSString stringWithContentsOfFile:pp2 encoding:NSUTF8StringEncoding error:nil];
    if (!txt) { MLOG("pipeline prebuild: no %s, nothing to build", pp.UTF8String); g_pre_running = 0; return -1; }
    NSMutableArray<NSString *> *parts = [NSMutableArray arrayWithObject:txt];   // each file parsed on its own (pre_parse_files): a # cover section never hides the next file
    if (txt2) { [parts addObject:txt2]; txt = [txt stringByAppendingString:txt2]; }
    NSString *lists = txt2 ? [@"shader_pairs.tsv and " stringByAppendingString:pp2.lastPathComponent] : @"shader_pairs.tsv";   // for the probe's line
    int zero = atomic_load(&g_depth_zero);
    NSString *want = pre_stamp(txt, zero);
    NSArray<NSArray<NSString *> *> *pairs = pre_parse_files(parts);
    if (!pairs.count) { MLOG("pipeline prebuild: no prebuild pairs (only padding covers or a header), nothing to build"); g_pre_running = 0; return -1; }   // NXNative faf91a9df
    NSString *rp = g_arch_bundle ? [g_bundle_dir stringByAppendingPathComponent:@"rest_pairs.tsv"] : nil, *rest = rp ? [NSString stringWithContentsOfFile:rp encoding:NSUTF8StringEncoding error:nil] : nil;
    if (g_arch_bundle && pso_bundle_covers(pairs, want, zero, rest, lists.UTF8String)) {   // the archive made offline holds them: only the pairs it left to the device (function constants) are built here
        if (!rest.length) {   // none: the device's own prebuild files only repeat the bundle
            pre_candidates();
            NSString *st = g_arch_dir ? [g_arch_dir stringByAppendingPathComponent:@"prebuilt.tsv"] : nil;
            if (pre_trim(1, "the archive bundled with the app holds every pair's base") && st && [[NSString stringWithContentsOfFile:st encoding:NSUTF8StringEncoding error:nil] hasPrefix:want])
                unlink(st.fileSystemRepresentation);
            g_pre_running = 0; return -1;
        }
        txt = rest; want = pre_stamp(rest, zero); pairs = pre_parse(rest); pp = rp; txt2 = nil;
    }
    if (!g_arch_cap) { g_pre_running = 0; return -1; }
    NSString *stamp = [g_arch_dir stringByAppendingPathComponent:@"prebuilt.tsv"], *failp = [g_arch_dir stringByAppendingPathComponent:@"prebuild_failed.tsv"];
    int other = 0; g_pre_known = pre_fail_load(failp, want, &other); g_pre_fails = [NSMutableArray array]; g_pre_known_n = 0;
    // done, unless its failures were found on another system build: then they are tried again (the rest are taken from the archive)
    if (pre_stamp_done([NSString stringWithContentsOfFile:stamp encoding:NSUTF8StringEncoding error:nil], want) && !other) { g_pre_running = 0; return -1; }
    g_pre_nolib = 0; g_pre_nolib_file = nil;
    int n = (int)pairs.count; uint64_t t0 = bp_now();
    pre_candidates(); arch_pre_begin();
    MLOG("pipeline prebuild: %d shader pairs of %s%s%s, %d workers (%s)", n, pp.UTF8String, txt2 ? " and " : "", txt2 ? pp2.UTF8String : "", threads, wait ? "tool" : prepare_on() ? "prepare step, before the first frame" : "background");
    pthread_mutex_lock(&g_fn_mu); g_pre_later_n = 0; pthread_mutex_unlock(&g_fn_mu);
    atomic_store(&g_pre_next, 0); atomic_store(&g_pre_flushing, 0); g_pre_deferred = 0;
    NSArray<NSNumber *> *ord = pre_order(pairs);
    void (^pre_done)(void) = ^{
        int d = ++g_pre_done;
        if (d % 1000 == 0) {
            MLOG("pipeline prebuild: %d of %d pairs, %d built, %d already archived, %d left to the draws, %d failed, %.0f s", d, n, (int)g_pre_built, (int)g_pre_archived, (int)g_pre_skipped, (int)g_pre_failed, (bp_now() - t0) / 1e9);
            if (atomic_load(&g_arch_new) >= 1000) arch_flush();   // the serializer holds what it captured until written
        }
    };
    // a pair: built (or archived, left to the draws, failed), or put back while another capture has one of its shader functions
    void (^one)(int) = ^(int p) { PreLater l = {.p = p}; if (pre_pair(pairs[(NSUInteger)p][0], pairs[(NSUInteger)p][1], zero, &l)) pre_later_put(&l); else pre_done(); };
    dispatch_group_t g = dispatch_group_create();
    for (int t = 0; t < threads; t++) dispatch_group_async(g, dispatch_get_global_queue(qos, 0), ^{
        PreLater l;
        for (;;) {
            if (atomic_load(&g_warm_stop)) break;   // the process is ending: the pairs left are built at the next start
            // a pair put back whose functions are free now goes before a new one: the captures of a shader function many pairs share (Ocarina of Time: one vertex shader
            // in 996) follow one another all along the prebuild, not all at its end
            if (pre_later_take(&l, 0)) { one(l.p); continue; }
            int i = atomic_fetch_add(&g_pre_next, 1);
            // the first worker to find no pair left hands the period over: it is written once the compiles still under way in it return, not after the slowest of all
            if (i >= n) { if (i == n) arch_flush(); break; }
            one(ord[(NSUInteger)i].intValue);
        }
        while (pre_later_take(&l, 1)) one(l.p);   // then the ones still put back, each once its functions are free: every worker stays until none is left
    });
    dispatch_block_t done = ^{
        atomic_store(&g_pre_flushing, 1);
        arch_pre_end(); arch_flush_wait();
        // every pair asked for, none left put back: not cut short by the process's end (mtl_warm_stop). One cut short removes none of its earlier files (the pairs it did not
        // reach were not looked up in them) and writes no stamp, so the next start builds what is left (the rest it finds in the archive)
        int whole = atomic_load(&g_pre_next) >= n && !pre_later_count();
        if (whole) pre_trim(0, "no pair's base was found in them");   // every pair is done; before the stamp, so that a start cut short here runs the prebuild again
        else { g_pre_old = nil; g_pre_used = nil; }
        NSMutableArray<NSString *> *fails = [NSMutableArray arrayWithArray:g_pre_known.allValues]; [fails addObjectsFromArray:g_pre_fails];
        if (fails.count) [[NSString stringWithFormat:@"# pipeline prebuild: pairs whose base failed to build on this system build, left to the draws until it or the stamp changes (nvn_mtl.m, pre_fail_load)\n%@%@\n",
                            pre_fail_head(want), [fails componentsJoinedByString:@"\n"]] writeToFile:failp atomically:YES encoding:NSUTF8StringEncoding error:nil];
        else unlink(failp.fileSystemRepresentation);
        if (whole) [pre_device_stamp(want) writeToFile:stamp atomically:YES encoding:NSUTF8StringEncoding error:nil];
        MLOG("pipeline prebuild done: %d pairs, %d bases built, %d already archived, %d left to the draws, %d failed, %.1f s; %d times a pair was put back while another capture had "
             "one of its shader functions, %d captures so far waited for one, %d of them built without the archive (fn_claim)%s", n, (int)g_pre_built, (int)g_pre_archived,
             (int)g_pre_skipped, (int)g_pre_failed, (bp_now() - t0) / 1e9, (int)g_pre_deferred, (int)atomic_load(&g_fn_waits), (int)atomic_load(&g_fn_plain),
             whole ? "" : "; cut short by the process's end: no stamp, the next start builds the pairs left");
        if (g_pre_nolib) MLOG("[RED] pipeline prebuild: %d pairs need a library file this app does not carry (first: %s), left to the draws until a package with them is installed (the pulling libraries <key>_bp.metallib: an IPA packed with IOS_PULL=0 leaves them out)", (int)g_pre_nolib, g_pre_nolib_file.UTF8String);
        if (fails.count) MLOG("pipeline prebuild: %lu pairs whose base failed are left to the draws (%s; %d of them failed on an earlier start of this system build, not built again); another system build tries them again",
                              (unsigned long)fails.count, failp.UTF8String, (int)g_pre_known_n);
        if (!wait) pso_guard_mark("the pipeline prebuild ended");   // the bundled archive's crash guard: the app's prebuild is behind it, every compile in it returned
        g_pre_running = 0;
        atomic_store(&g_pre_flushing, 0);
    };
    if (wait) { dispatch_group_wait(g, DISPATCH_TIME_FOREVER); done(); }
    else dispatch_group_notify(g, dispatch_get_global_queue(qos, 0), done);
    return n;
}
// DM_PSO_PREBUILD=tool: the prebuild alone (the host's other environment as for a run: DM_NVN_SHMAP, DM_MSL_DIR, DM_SAVE or DM_PSO_ARCHIVE), then exit; DM_PSO_PREBUILD_DEPTH=zero for
// a game that sets the near=0 depth mode, DM_PSO_PREBUILD_THREADS=<n> workers (default: compile_tasks). Returns 0 when not asked for
int mtl_pso_prebuild_tool(void) {
    const char *e = getenv("DM_PSO_PREBUILD"); if (!e || strcmp(e, "tool")) return 0;
    setenv("DM_PSO_MANIFEST", "off", 1);   // no prewarm (loading the shader map starts it)
    mtl_init(); const char *z = getenv("DM_PSO_PREBUILD_DEPTH"); if (z && !strcmp(z, "zero")) atomic_store(&g_depth_zero, 1);
    int threads = getenv("DM_PSO_PREBUILD_THREADS") ? atoi(getenv("DM_PSO_PREBUILD_THREADS")) : 0;
    if (threads <= 0) threads = compile_tasks();
    if (pso_prebuild(threads, 1, QOS_CLASS_USER_INITIATED) < 0) MLOG("pipeline prebuild: nothing to do (no archive, no shader_pairs.tsv, prebuilt.tsv says it is done, or the archive bundled with the app holds every base)");
    MLOG("pipeline prebuild: %d captures found another of the same shader function under way (fn_claim); %d of them waited %d ms in vain and were built without the archive",
         (int)atomic_load(&g_fn_waits), (int)atomic_load(&g_fn_plain), g_fn_wait_ms);
    return 1;
}
static int prepare_on(void);
static void pso_prebuild_bg(void) {   // after the prewarm, in the app without a prepare step (with one, prepare_prebuild builds them before the first frame)
    if (prepare_on()) return;
    const char *e = getenv("DM_PSO_PREBUILD");
    if ((e && !strcmp(e, "0")) || !hybrid_on()) { pso_guard_mark("the prewarm ended, no prebuild"); return; }   // the crash guard's window: no prebuild comes
    int pc = 0; size_t sz = sizeof pc; if (sysctlbyname("hw.perflevel0.physicalcpu", &pc, &sz, NULL, 0) || pc <= 1) pc = 4;
    if (pso_prebuild(pc > 4 ? pc / 2 : 2, 0, QOS_CLASS_UTILITY) < 0) pso_guard_mark("the prewarm ended, nothing to prebuild");   // else its end marks it (pso_prebuild)
}
// The pipeline lookups return a borrowed pointer (ported from S2Arm 89ab9704, after NXNative e82aedb8d), as prog_get_ptr: every pipeline pso_get_ptr returns is held by g_pso
//   (or g_pso_hy, a pulling stand-in, which hybrid_get fills the same way), and nothing deletes or clears an entry of either: hm_put_id puts only after a miss on the same key, so it
//   never replaces one. Returning the object paid a retain, an autorelease and a claim at every call, as ARC ignores __unsafe_unretained on a return type
static void *pso_get_ptr_(NvProg *pr);
#define pso_get_(pr) ((__bridge id<MTLRenderPipelineState>)pso_get_ptr_(pr))
static id<MTLFunction> ms_fs_override_(NvShader *fs);   // DM_NVN_MAGSCAN (defined before draw)
static int ms_on(void);
// Its function only while the diagnostic is on (ported from S2Arm cd9e2826, after NXNative 7c7c45479): an object return costs an autorelease and a claim, and every pipeline lookup asks
#define ms_fs_override(fs) (ms_on() ? ms_fs_override_(fs) : nil)
static int pf_int_kind(MTLPixelFormat f);
// A pipeline Metal refused: when a colour the fragment shader writes has an integer attachment, its output was most likely translated as float (a game without PC reflection has no output types,
// Tears of the Kingdom's BC4 block encoder and Ultrahand mask were the first cases). A shader with the typed-output entry point (dmsh_entry.py fs_uint) takes it for such a pipeline, and the
// six profiles' hand-written rows went with it; one without (main0 of a shape fs_uint does not know) gets the facts row that declares the outputs, for the profile's
// shader_facts_manual.tsv (merged by shader_split.py), until fs_uint knows that shape
static const char *pso_fout_hint(NvShader *fs, const uint32_t cfmt[8], char *b, size_t n) {
    if (!fs || fs->u_name || strlen(fs->key) < 16) return "";
    int o = snprintf(b, n, "; if its outputs are integers, add to shader_facts_manual.tsv: %.16s\t{\"fout\":{", fs->key), any = 0;
    for (int c = 0; c < 8; c++) { int kind = !fs->rf.color_known || fs->rf.color_mask >> c & 1 ? pf_int_kind((MTLPixelFormat)cfmt[c]) : 0;
        if (kind && o < (int)n) o += snprintf(b + o, n - o, "%s\"%d\":\"%s\"", any++ ? "," : "", c, kind == 1 ? "uint" : "sint"); }
    if (!any) return "";
    if (o < (int)n) snprintf(b + o, n - o, "}}");
    return b;
}
static void *pso_get_ptr(NvProg *pr) { AP_B; int pf = pf_enter(PF_PSO); void *r = pso_get_ptr_(pr); pf_leave(pf); AP_E(2); return r; }   // page-ins by part (PF_PSO)
