}
static NSArray<WarmTask *> *warm_parse(NSArray<NSString *> *paths, long *lines) { return warm_parse_h(paths, lines, NULL); }
static void warm_task_(WarmTask *t);
static void warm_task(WarmTask *t) { warm_task_(t); }
static void warm_task_(WarmTask *t) {
