    if (v < 0) { const char *e = getenv("DM_PSO_LATE_S"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("DM_PSO_LATE_S=0: the prepare step loads every shader-only line before the first frame, as before"); }
    return v;
}
// tasks without the S lines no R, M or C line uses, which go into *late (in the lists' order); *lines loses them too. The other tasks keep their order
static NSArray<WarmTask *> *warm_split_late(NSArray<WarmTask *> *tasks, NSMutableArray<WarmTask *> *late, long *lines) {
    NSMutableSet<NSString *> *used = [NSMutableSet set];
    for (WarmTask *t in tasks) {
        if (t->kind == 0) continue;
        if (t->key) [used addObject:t->key];   // C: its compute shader
        if (t->vkey.length) [used addObject:t->vkey];
        if (t->fkey.length) [used addObject:t->fkey];
        if (t->tkey.length) [used addObject:t->tkey];
    }
    NSMutableArray<WarmTask *> *now = [NSMutableArray arrayWithCapacity:tasks.count];
    for (WarmTask *t in tasks) { if (t->kind == 0 && ![used containsObject:t->key]) [late addObject:t]; else [now addObject:t]; }
    *lines -= (long)late.count;
    return now;
}
static void warm_late_one(WarmTask *t) { @autoreleasepool {
    if (!progpf_first(t->key)) { atomic_fetch_add(&g_warm_late_had, 1); return; }   // the game's prefetch or draw has it, or is loading it
    NvShader *sh = shader_acquire(t->key, t->stage, hybrid_on());   // its pulling entry too, as the prewarm does (warm_shader)
    if (!sh) return;
    WarmItem *item = [WarmItem new]; item->kind = 0; item->key = t->key; item->shader = sh; warm_enqueue(item); atomic_fetch_add(&g_warm_late_loaded, 1);
} }
// The prepare step, before its prebuild (warm_start, on the submit thread): the lines wait for the next frame presented. A game that presented before its first submission
// (DRAGON QUEST XI S presents three times first) starts them at its next present, which may come while the prebuild runs, the loads at utility QoS beside its compiles
static void warm_late_arm(NSArray<WarmTask *> *late) {
    if (!late.count) return;
    g_warm_late = late; g_warm_late_t0 = bp_now();
    atomic_store_explicit(&g_warm_late_state, 1, memory_order_release);
}
// Any thread, once (the first present, or warm_late_tick): the workers take the lines in order and end with the line that says what they loaded
static void warm_late_start(const char *why) {
    int one = 1; if (!atomic_compare_exchange_strong_explicit(&g_warm_late_state, &one, 2, memory_order_acq_rel, memory_order_relaxed)) return;
    NSArray<WarmTask *> *late = g_warm_late; g_warm_late = nil;
    long n = (long)late.count; uint64_t t0 = bp_now(), waited = t0 - g_warm_late_t0;
    __block _Atomic long next = 0;
    dispatch_group_t g = dispatch_group_create();
    for (int w = 0; w < PREPARE_LATE_WORKERS; w++) dispatch_group_async(g, dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
        for (;;) { long i = atomic_fetch_add(&next, 1); if (i >= n || atomic_load(&g_warm_stop)) break; warm_late_one(late[(NSUInteger)i]); }
    });
    dispatch_group_notify(g, dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
        MLOG("pipeline prewarm after the first frame: %ld shader-only lines (%s, %.1f s after the prepare step), %llu libraries loaded, %llu loaded already by the game, in %.2f s on %d workers at utility QoS%s",
             n, why, waited / 1e9, (unsigned long long)atomic_load(&g_warm_late_loaded), (unsigned long long)atomic_load(&g_warm_late_had), (bp_now() - t0) / 1e9, PREPARE_LATE_WORKERS,
             atomic_load(&g_warm_stop) ? "; stopped: the process is ending" : "");
        atomic_store(&g_warm_late_state, 3);
    });
}
// When a submission begins while the lines wait (mtl_sub_begin; submit thread): a run that has not presented after PREPARE_LATE_SUBS submissions starts them
static void warm_late_tick(void) {
    static unsigned subs;
    if (++subs >= PREPARE_LATE_SUBS) warm_late_start("no frame presented after the submissions that would have shown one");
}
// ---- The compaction's captures, after the first frame ----
// A compacting start captured every base the prewarm took from a file the compaction replaces again in its prepare step, a full compile each, before the first frame: Fortune's
// Weave's step took 8.41 s (447 bases, 37.2 s on 6 workers) and Smash's 7.70 s (866 bases, 38.4 s), where the lookups alone take 1-2 s (iPhone 18 Pro Max, build 29dcbb4d). Now
// the prewarm notes them (compact_note) and this pass captures them on one thread at utility QoS once the start is over: the first frame presented (or PREPARE_LATE_SUBS
// submissions in a run that never presents), the shader-only lines after it loaded (warm_late_start), no prebuild under way, and the bundled archive's crash guard past its
// window (pso_guard_frame: a Metal crash in a capture must not count against that archive), COMPACT_START_MS after the prewarm at the earliest. It captures COMPACT_BATCH at
// a time and then rests as long as the batch took (COMPACT_REST_MS at least), so it takes at most half of one core and never a burst in the first minute of play. It holds, and
// the timer's flushes go on meanwhile, while the device is thermally serious or critical, in Low Power Mode, or in the background (iOS: arch_mark_bg), and stops when the
// process ends (mtl_warm_stop): the old files stay, as every file does until the compaction's last period is written, and the next start notes their bases again (those
// already captured are found in the newer file first). Its captures go into the draws' flush period, so ARCH_PERIOD_MAX still hands a full one over; the timer's flushes wait
// while it captures, as they wait for the prewarm, so its bases make as few files as they can. Each capture claims its vertex-stage function (fn_claim, FN_PATIENT) like any
// other, so it never compiles beside a draw's capture of the same function (upstream 75758b9): a draw that wants it waits for the one capture under way and lends it its QoS.
// The draws keep the bases the prepare step took from the old files (open archives stay usable after their files go). The 'captured again' work cannot be skipped by copying
// binaries between archives: MTL4Archive only looks pipelines up, MTL4PipelineDataSetSerializer only captures what its compiler builds, and the one way to feed it an archive's
// binaries (MTL4CompilerTaskOptions.lookupArchives) is the import that crashed Metal in materializeAirNTFromOnlineForSlice (issue #342, shaders.md)
enum { COMPACT_START_MS = 10000, COMPACT_BATCH = 8, COMPACT_REST_MS = 1000, COMPACT_HOLD_MS = 2000 };
static int g_cpass_start_ms = COMPACT_START_MS, g_cpass_batch = COMPACT_BATCH, g_cpass_rest_ms = COMPACT_REST_MS, g_cpass_hold_ms = COMPACT_HOLD_MS;   // the tests lower them
static int g_cpass_hold_test = -1;   // the tests: 0 no hold, 1 hot, 2 Low Power Mode, 3 the background, in place of the device's state (compact_hold)
static uint64_t g_cpass_t0, g_cpass_cap_ns, g_cpass_held_ns, g_cpass_held_at, g_cpass_sched; static int g_cpass_holds, g_cpass_files;   // compact_step's thread alone (g_cpass_sched: compact_schedule's, before)
static dispatch_queue_t compact_q(void) {
    static dispatch_queue_t q; static dispatch_once_t once;
    dispatch_once(&once, ^{ q = dispatch_queue_create("dm.nvn.arch-compact", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_UTILITY, 0)); });
    return q;
}
static void compact_step(void);
static _Atomic int g_cpass_gen;   // a step scheduled under another generation does nothing (the tests start the pass again; the game never changes it)
static void compact_after(int ms) {
    int gen = atomic_load(&g_cpass_gen);
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)MAX(ms, 0) * NSEC_PER_MSEC), compact_q(), ^{ if (atomic_load(&g_cpass_gen) == gen) @autoreleasepool { compact_step(); } });
}
static int compact_ready(void) {
    if (!__atomic_load_n(&g_present_n, __ATOMIC_RELAXED) && atomic_load(&g_cpass_subs) < PREPARE_LATE_SUBS) return 0;
    int late = atomic_load(&g_warm_late_state);
    return late != 1 && late != 2 && !atomic_load(&g_pre_running) && !atomic_load(&g_psg.watching);
}
static const char *compact_hold(void) {   // why the captures wait now, or NULL
    static const char *why[] = {NULL, "the device is hot (thermal state serious or critical)", "Low Power Mode is on", "the app is in the background"};
    if (g_cpass_hold_test >= 0) return why[g_cpass_hold_test & 3];
    os_unfair_lock_lock(&g_mark_lock); int bg = g_mark_bg; os_unfair_lock_unlock(&g_mark_lock);
    if (bg) return why[3];
    NSProcessInfo *pi = NSProcessInfo.processInfo;
    return pi.thermalState >= NSProcessInfoThermalStateSerious ? why[1] : pi.lowPowerModeEnabled ? why[2] : NULL;
}
static int compact_noted(NSUInteger *next) { os_unfair_lock_lock(&g_cnote_lock); int n = (int)g_cnotes.count; if (next) *next = g_cnote_next; os_unfair_lock_unlock(&g_cnote_lock); return n; }
// Every note taken: the period under way is the compaction's last (arch_flush_slot, g_cpass 3); the old files go once it and every earlier one of the pass are written
// (arch_write, or here when they are written already). A period Metal made no new compiler for stays current, its captures unwritten: the old files stay
static void compact_close(void) {
    os_unfair_lock_lock(&g_cnote_lock); atomic_store(&g_cpass, 3); os_unfair_lock_unlock(&g_cnote_lock);   // under the lock: no note comes after the last was taken
    int handed = arch_flush_slot(&g_ep, nil, 0);
    if (handed < 0) g_compact_bad = 1;
    if (handed <= 0) atomic_store(&g_compact_closed, 1);
    MLOG("pipeline archive compaction after the first frame: %d of %d bases captured again in %.1f s (%.1f s of captures%s%s), %s", (int)atomic_load(&g_compacted), compact_noted(NULL),
         (bp_now() - g_cpass_t0) / 1e9, g_cpass_cap_ns / 1e9, g_cpass_holds ? [NSString stringWithFormat:@", held %d times for %.1f s", g_cpass_holds, g_cpass_held_ns / 1e9].UTF8String : "",
         atomic_load(&g_compact_busy) ? [NSString stringWithFormat:@"; %d not captured because another capture of their shader function did not return in time", (int)atomic_load(&g_compact_busy)].UTF8String : "",
         g_compact_bad ? "the old files stay" : "the old files go once its last period is written");
    os_unfair_lock_lock(&g_cnote_lock); g_cnotes = nil; g_cnote_keys = nil; g_cnote_next = 0; os_unfair_lock_unlock(&g_cnote_lock);   // the descriptors, no longer needed
    if (!atomic_load(&g_compact_periods)) dispatch_async(g_arch_q, ^{ @autoreleasepool { arch_compact_finish(); } });   // written already (or none): arch_write did not finish it
}
static void compact_one(CompactNote *n) {   // one noted pipeline captured again, from its original shader functions (the #342 workaround), never with archive imports
    NSError *ce = nil; int cap = 0, busy = 0; uint64_t t0 = bp_now();
    if (n->kind == 1) (void)arch_capture_cs((MTL4ComputePipelineDescriptor *)n->d, &ce, &cap, FN_PATIENT, &busy);
    else (void)arch_capture_try(n->d, &ce, n->vd, &cap, 0, FN_PATIENT, &busy);
    uint64_t dt = bp_now() - t0; g_cpass_cap_ns += dt; g_compact_ns += dt;
    if (cap) g_compacted++; else { g_compact_bad = 1; if (busy) g_compact_busy++; }   // not in the new files: the old ones stay
}
static void compact_stop(void) {
    atomic_store(&g_cpass, 4);
    NSUInteger next = 0; int n = compact_noted(&next);
    MLOG("pipeline archive compaction stopped: the process is ending (%d of %d bases captured again): the old files stay, and the next start compacts them", (int)next, n);
}
static void compact_step(void) {   // on compact_q: a batch, then the next step after a rest (or a hold)
    int st = atomic_load(&g_cpass);
    if (st != 1 && st != 2) return;
    if (atomic_load(&g_warm_stop)) { compact_stop(); return; }
    if (st == 1 && !compact_ready()) { compact_after(g_cpass_hold_ms); return; }
    const char *hold = compact_hold();
    if (hold) {
        if (!atomic_exchange(&g_cpass_held, 1)) { g_cpass_holds++; g_cpass_held_at = bp_now(); MLOG("pipeline archive compaction held: %s", hold); }
        compact_after(g_cpass_hold_ms); return;
    }
    if (atomic_exchange(&g_cpass_held, 0)) { g_cpass_held_ns += bp_now() - g_cpass_held_at; MLOG("pipeline archive compaction goes on after %.1f s", (bp_now() - g_cpass_held_at) / 1e9); }
    if (st == 1) {
        atomic_store(&g_cpass, 2); g_cpass_t0 = bp_now();   // before its first capture joins a period (arch_flush_slot)
        for (NSUInteger i = 0; g_compact_state && i < g_compact_files.count; i++) g_cpass_files += g_compact_state[i] != 0;
        MLOG("pipeline archive compaction after the first frame: capturing %d bases again from %d files (%.1f s after the prewarm ended), %d at a time on one thread at utility QoS",
             compact_noted(NULL), g_cpass_files, (bp_now() - g_cpass_sched) / 1e9, g_cpass_batch);
    }
    if (!arch_capturing()) { g_compact_bad = 1; compact_close(); return; }   // capturing stopped (arch_cap_failed): nothing more goes into the new files
    uint64_t t0 = bp_now();
    for (int i = 0; i < MAX(g_cpass_batch, 1); i++) {
        if (atomic_load(&g_warm_stop)) { compact_stop(); return; }
        os_unfair_lock_lock(&g_cnote_lock); CompactNote *n = g_cnote_next < g_cnotes.count ? g_cnotes[g_cnote_next++] : nil; os_unfair_lock_unlock(&g_cnote_lock);
        if (!n) { compact_close(); return; }
        @autoreleasepool { compact_one(n); }
    }
    arch_note_new();   // the timer looks at the period's age while the pass captures (arch_warm_flush_due)
    compact_after(MAX(g_cpass_rest_ms, (int)((bp_now() - t0) / NSEC_PER_MSEC)));
}
// The prewarm ended (warm_finish): the pass waits COMPACT_START_MS, then for the rest of compact_ready
static void compact_schedule(void) {
    if (!g_compact_enabled || !g_arch_cap) return;
    if (!compact_noted(NULL)) { MLOG("pipeline archive: the prewarm took no base from the files the compaction would replace: they stay until a start takes some"); return; }
    int z = 0; if (atomic_compare_exchange_strong(&g_cpass, &z, 1)) { g_cpass_sched = bp_now(); compact_after(g_cpass_start_ms); }
}
// ---- The bundled archive's read-ahead (DM_PSO_READAHEAD=1, off by default) ----
// Metal's open reads every library of the bundled archive (arch_open_read_on asks for those ranges first), but a GPU image's code only when a pipeline is first taken: on the
// iPhone each in-play lookup in Ocarina of Time's 4.7 GB archive took about 50 ms, page faults on flash (round 3: archive lookups found 470 / 23,524 ms in one window). With the
// switch on, once the start's pipeline work is over (the first frame presented, the prewarm, the shader-only lines, the prebuild and the bundled archive's crash guard window
// done: compact_ready; no compaction pass scheduled or capturing), one thread at utility QoS reads that code (ra_note's ranges) into the file cache, RA_CHUNK at a time with a rest
// at least as long as the read after each, so later lookups find it in memory. Plain reads into one 1 MB buffer: no mapping, nothing wired or pinned, and the pages stay clean
// file cache the system can drop under pressure (they are not the app's footprint). It waits while the device is hot (thermal serious or critical), in Low Power Mode or the app is
// in the background (compact_hold, as the compaction does), and stops for good when the headroom to the memory limit falls under RA_HEADROOM_MB (os_proc_available_memory) or the
// process ends. One line when it is scheduled, one summary (MB read, time, holds). The A/B: DM_PSO_READAHEAD=1 against none, on the same route, on battery (flash energy)
enum { RA_CHUNK = 8 << 20, RA_PIECE = 1 << 20, RA_START_MS = 5000, RA_REST_MS = 25, RA_HOLD_MS = 2000, RA_HEADROOM_MB = 1024 };
enum { RA_GO, RA_WAIT, RA_STOP };
static int g_ra_start_ms = RA_START_MS, g_ra_rest_ms = RA_REST_MS, g_ra_hold_ms = RA_HOLD_MS;   // the tests lower them
static struct { char path[1024]; uint64_t off[64], len[64]; int n; uint64_t total; } g_ra;   // set once, by the bundled archive's open (ra_note)
static struct { int fd, i, holds, held, done, stops; uint64_t pos, read, read_ns, t0, held_at, held_ns; uint8_t *buf; const char *why; } g_ras = {.fd = -1};   // ra_step's thread alone
static os_unfair_lock g_ra_lock = OS_UNFAIR_LOCK_INIT;
static int ra_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_PSO_READAHEAD"); v = e && atoi(e) > 0; } return v; }
static void ra_note(NSString *p, const arch_reads *rd) {
    os_unfair_lock_lock(&g_ra_lock);
    if (!g_ra.n && rd->cn && strlen(p.fileSystemRepresentation) < sizeof g_ra.path) {
        strcpy(g_ra.path, p.fileSystemRepresentation);
        for (int i = 0; i < rd->cn; i++) { g_ra.off[i] = rd->coff[i]; g_ra.len[i] = rd->clen[i]; g_ra.total += rd->clen[i]; }
        g_ra.n = rd->cn;
    }
    os_unfair_lock_unlock(&g_ra_lock);
}
// What the read-ahead does now (pure, so t_pso_readahead checks it): stop at the process's end or low headroom (avail 0: not known, the Mac), wait for a hold or the start's work
static int ra_decide(int ending, const char *hold, int busy, uint64_t avail) {
    if (ending || (avail && avail < (uint64_t)RA_HEADROOM_MB << 20)) return RA_STOP;
    return hold || busy ? RA_WAIT : RA_GO;
}
static int ra_busy(void) { int st = atomic_load(&g_cpass); return atomic_load(&g_warm_running) || st == 1 || st == 2 || !compact_ready(); }
static void ra_end(const char *why) {
    if (g_ras.fd >= 0) close(g_ras.fd);
    g_ras.fd = -1; free(g_ras.buf); g_ras.buf = NULL; g_ras.done = 1;
    if (g_ras.held) g_ras.held_ns += bp_now() - g_ras.held_at;
    MLOG("pipeline archive read-ahead %s: %.1f of %.1f MB of GPU code read in %.1f s (%.1f s reading), held %d times (%.1f s)", why, g_ras.read / 1048576.0, g_ra.total / 1048576.0,
         g_ras.t0 ? (bp_now() - g_ras.t0) / 1e9 : 0.0, g_ras.read_ns / 1e9, g_ras.holds, g_ras.held_ns / 1e9);
}
// One step on ra_q: the ms to the next, or -1 when it is over (its summary said why)
static int ra_step(void) {
    if (g_ras.done) return -1;
    const char *hold = compact_hold(); int busy = ra_busy();
    int d = ra_decide(atomic_load(&g_warm_stop), hold, busy, g_rh_avail ? g_rh_avail() : 0);
    if (d == RA_STOP) { ra_end(atomic_load(&g_warm_stop) ? "stopped, the process is ending" : "stopped, the headroom to the memory limit is low"); return -1; }
    if (d == RA_WAIT) {
        if (!g_ras.held && g_ras.t0) { g_ras.held = 1; g_ras.holds++; g_ras.held_at = bp_now(); }   // a hold after it began (before, it waits for the start's work)
        return g_ra_hold_ms;
    }
    if (g_ras.held) { g_ras.held = 0; g_ras.held_ns += bp_now() - g_ras.held_at; }
    if (!g_ras.t0) {
        g_ras.t0 = bp_now(); g_ras.fd = open(g_ra.path, O_RDONLY); g_ras.buf = malloc(RA_PIECE);
        if (g_ras.fd < 0 || !g_ras.buf) { ra_end("stopped, the archive could not be opened"); return -1; }
    }
    uint64_t t0 = bp_now(), got = 0;
    while (got < RA_CHUNK && g_ras.i < g_ra.n) {
        uint64_t left = g_ra.len[g_ras.i] - g_ras.pos;
        if (!left) { g_ras.i++; g_ras.pos = 0; continue; }
        size_t n = (size_t)MIN((uint64_t)RA_PIECE, MIN(left, RA_CHUNK - got));
        ssize_t r = pread(g_ras.fd, g_ras.buf, n, (off_t)(g_ra.off[g_ras.i] + g_ras.pos));
        if (r <= 0) { g_ras.i++; g_ras.pos = 0; continue; }   // a short file: that range is over
        g_ras.pos += (uint64_t)r; got += (uint64_t)r;
    }
    uint64_t dt = bp_now() - t0; g_ras.read += got; g_ras.read_ns += dt;
    if (g_ras.i >= g_ra.n) { ra_end("done"); return -1; }
    return MAX(g_ra_rest_ms, (int)(dt / NSEC_PER_MSEC));
}
static dispatch_queue_t ra_q(void) {
    static dispatch_queue_t q; static dispatch_once_t once;
    dispatch_once(&once, ^{ q = dispatch_queue_create("dm.nvn.arch-readahead", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_UTILITY, 0)); });
    return q;
}
static void ra_tick(void) { int ms = ra_step(); if (ms >= 0) dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)ms * NSEC_PER_MSEC), ra_q(), ^{ @autoreleasepool { ra_tick(); } }); }
static void ra_schedule(void) {   // pso4_init, once the archives are open
    static int once; if (once || !ra_on()) return;
    once = 1;
    if (!g_ra.n) { MLOG("pipeline archive read-ahead (DM_PSO_READAHEAD=1): no bundled archive with GPU code to read: nothing to do"); return; }
    MLOG("pipeline archive read-ahead (DM_PSO_READAHEAD=1): %.1f MB of GPU code in %d ranges of %s, after the start's pipeline work, %d MB at a time at utility QoS; it waits while hot, "
         "in Low Power Mode or in the background, and stops under %d MB of headroom", g_ra.total / 1048576.0, g_ra.n, g_ra.path, RA_CHUNK >> 20, RA_HEADROOM_MB);
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)g_ra_start_ms * NSEC_PER_MSEC), ra_q(), ^{ @autoreleasepool { ra_tick(); } });
}
static void warm_finish(void) {
    MLOG("pipeline prewarm done: shaders %llu / render pipelines %llu (specialized fragment skipped %llu) / compute pipelines %llu, background time %.1f ms; shader keys not in the shader map (another game version) %llu",
         (unsigned long long)g_warm_shaders, (unsigned long long)g_warm_rps, (unsigned long long)g_warm_skip_fz, (unsigned long long)g_warm_cps, (bp_now() - g_warm_t0) / 1e6, (unsigned long long)g_warm_skip_stale);
    if (g_warm_mps) MLOG("pipeline prewarm: %llu native task / mesh pipelines; so far %llu taken from the pipeline archive, %llu compiled and captured for it",
                         (unsigned long long)g_warm_mps, (unsigned long long)g_mtk_arch, (unsigned long long)g_mtk_built);
    char again[96] = "";   // only a compacting start notes bases, for its captures after the first frame (compact_step)
    if (g_compact_enabled) snprintf(again, sizeof again, " (%d of them noted for the compaction after the first frame)", (int)g_compact_bases);
    char bvd[96] = ""; if (g_arch_bundle) snprintf(bvd, sizeof bvd, "; %llu layout bases from the archive bundled with the app", (unsigned long long)g_pb_bundle_vd);
    MLOG("pipeline bases so far: %llu compiled, %llu from the archive%s, %llu reused (%.1f ms for the bases); %llu specializations (their descriptors %s)%s",
         (unsigned long long)g_pb_built, (unsigned long long)g_pb_archived, again, (unsigned long long)g_pb_reused, g_pb_base_ns / 1e6, (unsigned long long)g_pb_spec,
         (const char *[]){"not asked for yet", "returned retained", "returned autoreleased"}[atomic_load(&g_spec_own) % 3], bvd);
    if (g_arch_bundle || g_arch_cap) MLOG("compute pipelines so far: %llu from the archive bundled with the app, %llu from this device's archive, %llu built (%.1f ms looking up, %.1f ms building)",
                                         (unsigned long long)g_cps_arch, (unsigned long long)g_cps_run, (unsigned long long)g_cps_built, g_cps_look_ns / 1e6, g_cps_build_ns / 1e6);
    // All warm tasks have joined. WarmItems retain published shaders until the submit thread claims them.
    // Drop negative results too: demand loading keeps its existing retry behavior, independent of the warm dictionary.
    g_warm_dict = nil; g_warm_loads = nil;
    if (shader_share_on()) MLOG("shader sharing so far: %llu preparations joined, %llu made (DM_NVN_SHADER_SHARE=0 turns it off)", (unsigned long long)atomic_load(&g_shload_joined), (unsigned long long)atomic_load(&g_shload_made));
    atomic_store(&g_warm_running, 0);
    arch_probe_settle();   // every line of the prewarm lists has asked the archive by now
    arch_flush();   // what the prewarm compiled, written now the timer's flushes no longer wait for it
    compact_schedule();   // the compaction's captures of what the prewarm noted, after the first frame
    @autoreleasepool { pso_prebuild_bg(); }   // then, once, the bases every shader pair's hybrid draws need
}
// The process is ending (dm_gfx_quit_begin, atexit): the prewarm and the pairs' prebuild take nothing more, so the archive's write does not share the compiler with them and no
// capture joins a period after the exit handed it over; what they had not built is built at the next start. The compiles under way finish (the period's write waits for them)
void mtl_warm_stop(void) {
    if (atomic_exchange(&g_warm_stop, 1)) return;
    if (atomic_load(&g_warm_running)) MLOG("pipeline prewarm stopped: the process is ending (%llu lines done)", (unsigned long long)g_warm_done);
    if (atomic_load(&g_pre_running)) MLOG("pipeline prebuild stopped: the process is ending (%d pairs handed out)", (int)atomic_load(&g_pre_next));
}
// Wait for the background warm-up to finish (at most timeout_ms): returns how many milliseconds were actually waited, 0 if it is not running. On first install the system shader cache is fully cold; if warm-up is slower than the player entering a run,
// pipelines not yet warmed are compiled on the spot on the submit thread = in-run stutter; the loading screen on entering a run blocks the player anyway, so let it load a little longer (called where hle_nvn.c presents).
int mtl_warm_wait(int timeout_ms) {
    if (!atomic_load(&g_warm_running)) return 0;
    uint64_t t0 = bp_now();
    while (atomic_load(&g_warm_running) && (bp_now() - t0) / 1000000ull < (uint64_t)timeout_ms) usleep(2000);
    return (int)((bp_now() - t0) / 1000000ull) + 1;
}
// ---- The prepare step: the prewarm before the game's first frame, with a progress screen ----
// With a window (or DM_PSO_PREPARE=1), the first submission waits until every line of the prewarm lists (the profile's pso_manifest.tsv, then this device's pso_user.tsv) is built:
// the shaders loaded and the pipelines made, on as many workers as the device has cores, at user-initiated QoS, since the game draws nothing meanwhile. It runs at the first
// submission and not before the game starts because the vertex entry every pipeline is built with follows the game's depth mode (nvnDeviceSetDepthMode), which is known only by then.
// Each start runs it: when everything is in the Metal shader cache and the pipeline archive it takes well under a second, and only past 0.5 s (with 0.3 s or more still to go) does the front end show its screen
// ("Preparing shaders", a bar and a count: front_progress). A stamp that says the step ran would skip it exactly when the system dropped the Metal cache (an OS update, storage
// pressure on iOS), which is when it is needed; a later start (warm_later_ready) runs every line still, in the background, so the first frame no longer waits for the lookups of
// lists this device has prepared before. DM_PSO_PREPARE=0: the prewarm runs in the background as before (as it does without a window); DM_PSO_PREPARE_THREADS=<n> sets the workers
void front_progress(const char *title, long done, long total);
__attribute__((weak)) void front_progress(const char *title, long done, long total) { (void)title; (void)done; (void)total; }   // the front ends' (front.h); none in the unit tests
static int prepare_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_PSO_PREPARE");
        if (e && !strcmp(e, "0")) { MLOG("DM_PSO_PREPARE=0: the pipeline prewarm runs in the background, the game does not wait for it"); v = 0; }
        else v = (e && !strcmp(e, "1")) || front_metal_layer() != NULL; }
    return v;
}
static int prepare_workers(void) {
    const char *e = getenv("DM_PSO_PREPARE_THREADS"); int n = e ? atoi(e) : 0;
    if (n <= 0) { size_t sz = sizeof n; if (sysctlbyname("hw.activecpu", &n, &sz, NULL, 0) || n < 2) n = 2; }
    return n;
}
// The pipelines compiled so far, not taken from an archive (pso_build_ex's bases, cps_new_b's compute pipelines, mtk_build's task / mesh pipelines), every thread's
static uint64_t warm_compiled(void) { return atomic_load(&g_pb_built) + atomic_load(&g_cps_built) + atomic_load(&g_mtk_built); }
// The time left in the prepare step (ns), for whether its screen shows (idea from S2Arm 98fc203eb). The lines' rate alone said a cold start's rest was quick: archive hits run
// thousands of lines a second at the front, and the real compiles behind them take minutes. So once PREPARE_EST_COMPILES pipelines have really compiled (warm_compiled), the
// rest is the lines left at the compile rate so far (compiles over the whole step's time, hits included: the estimate errs long, toward showing the screen). Before that the real
// compiles give no number (*from_lines = 1) and the lines' rate decides, as before: a later start whose every line is an archive hit has no compile to time, and the decision is
// taken again every 50 ms, so a screen held back by the hits at the front shows once the compiles behind them have a rate. No time left is shown anywhere: the screen has a bar and
// a count (front_progress), so this is the show decision and the log's estimate alone
enum { PREPARE_EST_COMPILES = 32 };
static double prepare_rest(uint64_t el, long done, long lines, uint64_t compiled, int *from_lines) {
    *from_lines = compiled < PREPARE_EST_COMPILES;
    if (!*from_lines) return (double)el * (double)(lines - done) / (double)compiled;
    return done ? (double)el * (double)(lines - done) / (double)done : 1e18;
}
static void warm_prepare(NSArray<WarmTask *> *tasks, long lines, long later) {   // later: the shader-only lines left to after the first frame (warm_split_late)
    int workers = prepare_workers(); long n = (long)tasks.count;
    uint64_t t0 = bp_now(), built0 = g_pb_built, arch0 = g_pb_archived, reused0 = g_pb_reused, spec0 = g_pb_spec, bvd0 = g_pb_bundle_vd;
    __block _Atomic long next = 0;
    dispatch_group_t g = dispatch_group_create();
    for (int w = 0; w < workers; w++) dispatch_group_async(g, dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        for (;;) { long i = atomic_fetch_add(&next, 1); if (i >= n || atomic_load(&g_warm_stop)) break; warm_task(tasks[(NSUInteger)i]); }
    });
    int shown = 0; uint64_t comp0 = warm_compiled();
    while (dispatch_group_wait(g, dispatch_time(DISPATCH_TIME_NOW, 50 * (int64_t)NSEC_PER_MSEC))) {
        // the screen shows past 0.5 s, unless the estimate says the rest takes less than 0.3 s more (no screen that flashes up and goes); from the real compiles once there are
        // PREPARE_EST_COMPILES of them (prepare_rest)
        uint64_t el = bp_now() - t0, comp = warm_compiled() - comp0; long done = g_warm_done; int from_lines = 0; double rest = prepare_rest(el, done, lines, comp, &from_lines);
        if (!shown && el >= 500000000ull && rest >= 3e8) { shown = 1;
            MLOG("pipeline prepare: %ld of %ld lines done after %.1f s, %llu really compiled (%s %.1f s more), the progress screen shows", done, lines, el / 1e9, (unsigned long long)comp,
                 from_lines ? "too few compiles for a rate: the lines' rate says" : "at that compile rate", rest / 1e9); }
        if (shown) front_progress("Preparing shaders", g_warm_done, lines);
    }
    if (shown) front_progress(NULL, lines, lines);
    char again[80] = "";   // only a compacting start notes bases, for its captures after the first frame (compact_step)
    if (g_compact_enabled) snprintf(again, sizeof again, " (%d of them noted for the compaction after the first frame)", (int)g_compact_bases);
    // with the archive bundled with the app: how many of the bases from the archive were layout bases it holds (pso_offline.py's, the R rows'); scripts/devlog.py reads it
    // and the shader-only lines left to after the first frame (warm_split_late), in the same part: the line's format stays the one scripts/devlog.py reads
    char bvd[192] = ""; int bn = 0; if (g_arch_bundle) bn = snprintf(bvd, sizeof bvd, "; %llu layout bases from the archive bundled with the app", (unsigned long long)(g_pb_bundle_vd - bvd0));
    if (later && bn >= 0 && (size_t)bn < sizeof bvd) snprintf(bvd + bn, sizeof bvd - (size_t)bn, "; %ld shader-only lines left to after the first frame", later);
    MLOG("pipeline prepare: %ld lines (%llu shaders, %llu render pipelines, %llu compute pipelines) in %.2f s on %d workers before the first frame, progress screen %s; "
         "bases %llu compiled, %llu from the archive%s, %llu reused; %llu specializations%s",
         lines, (unsigned long long)g_warm_shaders, (unsigned long long)g_warm_rps, (unsigned long long)g_warm_cps, (bp_now() - t0) / 1e9, workers, shown ? "shown" : "not shown",
         (unsigned long long)(g_pb_built - built0), (unsigned long long)(g_pb_archived - arch0), again, (unsigned long long)(g_pb_reused - reused0), (unsigned long long)(g_pb_spec - spec0), bvd);
}
// ---- Later starts: the lists to the background, the first frame not waiting (idea from S2Arm e899d98a1) ----
// The prepare step ran every line of the lists before the first frame at every start. On a later start each line is an archive hit, but a hit is still a lookup and a library
// load, so a large list held the first frame for seconds each time (Ocarina of Time's bundled archive: about 50 ms a lookup on the iPhone). Now a start whose lists this device
// has prepared to the end before, in this archive, hands them all to the background instead (warm_later_bg): half the performance cores at utility QoS, below the game's own start
// work, and the first frame goes on. A first start, and any start after the lists, the shader chain, the app, the system or the archive changed, waits as before.
// What 'prepared before' means is prepared.tsv in the device's archive folder (pso_archive/, beside pso_user.tsv in the game's save folder; never in the game's files), written
// once a prepare step that waited ran every line and the archive wrote every period it captured (warm_later_mark). It holds warm_later_stamp: the shader chain, the app's build
// (its LC_UUID: a new build may carry new shaders, a new bundled archive or a new compiler path), the system build (an OS update drops the archive's binaries: pso4_init removes
// the files Metal refuses), the depth mode (every pipeline's vertex entry follows it), the bundled archive (opened, its size; none when its crash guard left it out), and the
// lists' names, lengths and SHA-256 (a line the device recorded since, pso_user.tsv, makes it wait once more). Any file pso4_init removed or could not read (another chain's, one Metal refused:
// g_arch_lost) removes prepared.tsv too, there. A line that failed to build counts as run: it fails again either way. Unlike a stamp that skipped the step, the step still runs every
// line at every start, so a pipeline the system dropped is built again, only not before the first frame.
// A draw that needs a pipeline the background has not reached builds it as without the prepare step (DM_PSO_PREPARE=0): a base one worker looks up or compiles is shared
// (g_pbase_pending: a draw takes the base the lookup found, or waits for that one compile, never compiles it again; the wait does not raise the worker's QoS, which is why this
// is only for lists already in the archive, where the waits are lookups), a library is shared (shader_acquire), and a pipeline the background made later is dropped at the claim
// when the draw's is in the cache (warm_claim). The process's end stops the workers between lines (g_warm_stop, mtl_warm_stop's line) and leaves prepared.tsv as it was.
// DM_PSO_LATER_START=0 makes every start wait, as before
static int later_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_PSO_LATER_START"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("DM_PSO_LATER_START=0: every start waits for the prepare step, as the first does"); }
    return v;
}
static NSString *warm_later_path(void) { return g_arch_dir ? [g_arch_dir stringByAppendingPathComponent:@"prepared.tsv"] : nil; }
// What the lists' pipelines on this device depend on; h: the lists as warm_parse_h read them (finished here). nil when the app's build cannot be told (no LC_UUID)
static NSString *warm_later_stamp(CC_SHA256_CTX *h, long lines) {
    uint8_t d[CC_SHA256_DIGEST_LENGTH]; CC_SHA256_Final(d, h); char app[33]; exe_uuid(app);
    if (!*app) return nil;
    return [NSString stringWithFormat:@"chain\t%s\napp\t%s\n%@depth\t%s\nbundle\t%@\nlists\t%ld\t%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x\n", DMSH_CHAIN, app,
            arch_os_build(), atomic_load(&g_depth_zero) ? "near=0" : "near=-w", g_arch_bundle ? [NSString stringWithFormat:@"%llu", (unsigned long long)g_bundle_bytes] : @"none", lines,
            d[0], d[1], d[2], d[3], d[4], d[5], d[6], d[7], d[8], d[9], d[10], d[11], d[12], d[13], d[14], d[15]];
}
// Whether this start hands the lists to the background: the switch, an archive that captures, and prepared.tsv the same as this start's stamp
static int warm_later_ready(NSString *stamp) {
    NSString *p = warm_later_path();
    if (!stamp || !p || !g_arch_cap || !later_on()) return 0;
    if (g_arch_lost) return 0;   // pso4_init removed prepared.tsv with the files
    NSString *have = [NSString stringWithContentsOfFile:p encoding:NSUTF8StringEncoding error:nil];
    if (!have) return 0;   // a first start: no line said so before
    if ([have isEqualToString:stamp]) return 1;
    MLOG("pipeline prepare: this device prepared the lists for %s; this start has %s: it waits for the step", stamp_line(have), stamp_line(stamp));
    return 0;
}
// After a prepare step that waited ran every line (warm_finish's flush handed the period over): prepared.tsv is written once every period handed over so far is written, unless
// one was not (lost0: g_arch_write_lost when the step began) or the process is ending
static void warm_later_mark(NSString *stamp, int lost0) {
    NSString *p = warm_later_path();
    if (!stamp || !p || !g_arch_cap || !g_arch_pending || atomic_load(&g_warm_stop)) return;
    dispatch_group_notify(g_arch_pending, g_arch_q, ^{ @autoreleasepool {
        if (atomic_load(&g_warm_stop)) return;
        if (atomic_load(&g_arch_write_lost) != lost0) { MLOG("pipeline prepare: a period of the archive was not written: no prepared.tsv, the next start waits for the step again"); return; }
        if ([[NSString stringWithContentsOfFile:p encoding:NSUTF8StringEncoding error:nil] isEqualToString:stamp]) return;
        if ([stamp writeToFile:p atomically:YES encoding:NSUTF8StringEncoding error:nil])
            MLOG("pipeline prepare: every line of the lists is in this device's archive: a later start with the same lists hands them to the background (%s)", p.UTF8String);
    } });
}
static _Atomic int g_warm_later;   // this start handed its lists to the background (the tests read it)
static int later_workers(void) {   // half the performance cores, 2 at least, as the background prebuild (pso_prebuild_bg)
    int pc = 0; size_t sz = sizeof pc; if (sysctlbyname("hw.perflevel0.physicalcpu", &pc, &sz, NULL, 0) || pc <= 1) pc = 4;
    return pc > 4 ? pc / 2 : 2;
}
static void warm_later_bg(NSArray<WarmTask *> *tasks, long lines, long left) {   // left: the shader-only lines after the first frame (warm_split_late)
    int workers = later_workers(); long n = (long)tasks.count;
    uint64_t t0 = bp_now(), built0 = g_pb_built, arch0 = g_pb_archived, reused0 = g_pb_reused, spec0 = g_pb_spec;
    atomic_store(&g_warm_bg, 1); atomic_store(&g_warm_later, 1);   // the archive's timer flushes as for a prewarm the game plays through (arch_warm_flush_due)
    MLOG("pipeline prepare: a later start: %ld lines this device prepared before go to the background on %d workers at utility QoS, the first frame does not wait for them%s "
         "(DM_PSO_LATER_START=0 waits)", lines, workers, left ? [NSString stringWithFormat:@"; %ld shader-only lines after the first frame", left].UTF8String : "");
    __block _Atomic long next = 0;
    dispatch_group_t g = dispatch_group_create(); dispatch_queue_t q = dispatch_get_global_queue(QOS_CLASS_UTILITY, 0);
    for (int w = 0; w < workers; w++) dispatch_group_async(g, q, ^{
        for (;;) { long i = atomic_fetch_add(&next, 1); if (i >= n || atomic_load(&g_warm_stop)) break; warm_task(tasks[(NSUInteger)i]); }
    });
    dispatch_group_notify(g, q, ^{ @autoreleasepool {
        if (atomic_load(&g_warm_stop)) return;   // the process is ending (mtl_warm_stop's line): what is left is built at the next start
        MLOG("pipeline prepare in the background: %ld lines in %.2f s on %d workers; bases %llu compiled, %llu from the archive, %llu reused; %llu specializations (the draws' meanwhile included)",
             lines, (bp_now() - t0) / 1e9, workers, (unsigned long long)(g_pb_built - built0), (unsigned long long)(g_pb_archived - arch0), (unsigned long long)(g_pb_reused - reused0),
             (unsigned long long)(g_pb_spec - spec0));
        warm_finish();
    } });
}
// The files the prepare step's prebuild just wrote, opened before the first frame (upstream NXNative 4add5fbb4, MIT). pso4_init opens the archive folder once, before the
// prebuild, so its bases went into files this run never looked in: every hybrid draw of a first start found no pulling base ("pulling base not made yet") and built it again in
// the background (hy_base_kick), until the next start opened the files. Here the folder's p and pb files that pso4_init did not find (g_arch_opened) are opened, oldest first, and
// their indexes go into g_arch_ix with the newest file's key winning, as pso4_init's do; a file without a complete index goes to the front of g_arch4p's device files (after the
// bundled archive). Then the misses recorded so far (g_pbase_miss) are forgotten, since one of these files may hold them. It runs on the prepare step's thread with no draw and no
// prebuild worker running, so the lookups need no lock, and nothing changes these tables once the first frame starts. The files are left out of the chain probe (they carry this
// chain's stamp) and of the prebuild's trim (g_arch_pre_files: this run's trim is over; the next start notes them). Plain run files written meanwhile (the prewarm's) are not
// taken: their bases are already built in this run. They open only with g_arch_adopt_reserve of the task's largest free address-space gap left beside them (upstream's 2 GiB
// runtime reserve; NX 18 applies it here alone, not to pso4_init's opens: see arch_vm_room); otherwise they are left to the next start
static uint64_t g_arch_adopt_reserve = 2ull << 30;   // the tests raise it
static void arch_adopt_prebuilt(void) {
    const char *pt = getenv("DM_PSO_PREBUILD");
    if (!g_arch_dir || !g_arch_opened || (pt && !strcmp(pt, "tool"))) return;   // no folder (or a GPU capture run), or the prebuild tool, which runs no game
    NSMutableArray<NSString *> *names = [NSMutableArray array];
    for (NSString *n in [NSFileManager.defaultManager contentsOfDirectoryAtPath:g_arch_dir error:nil])
        if ([n hasSuffix:@".mtl4a"] && arch_name_kind(n) && ![g_arch_opened containsObject:n]) [names addObject:n];
    if (!names.count) return;
    [names sortUsingComparator:^NSComparisonResult(NSString *x, NSString *y) {   // oldest first: a later file's key replaces an earlier one's in g_arch_ix
        int a = [x substringFromIndex:arch_name_kind(x)].intValue, b = [y substringFromIndex:arch_name_kind(y)].intValue;
        return a < b ? NSOrderedAscending : a > b ? NSOrderedDescending : NSOrderedSame;
    }];
    uint64_t bytes = 0, pg = (uint64_t)getpagesize();   // what Metal maps: each file whole, in pages
    for (NSString *n in names) {
        struct stat st; if (stat([g_arch_dir stringByAppendingPathComponent:n].fileSystemRepresentation, &st) || st.st_size <= 0) continue;
        bytes += ((uint64_t)st.st_size + pg - 1) / pg * pg;
    }
