    if (!vm || bytes > lg || g_arch_adopt_reserve > lg - bytes) {
        char room[128] = "the task's address map could not be read";
        if (vm) snprintf(room, sizeof room, "largest free address-space gap %.1f MB, %.1f MB kept free", lg / 1048576.0, g_arch_adopt_reserve / 1048576.0);
        MLOG("pipeline archive %s: %lu files the prebuild just wrote (%.1f MB) not opened in this run (%s): the next start opens them", g_arch_dir.UTF8String,
             (unsigned long)names.count, bytes / 1048576.0, room);
        return;
    }
    uint64_t t0 = bp_now(); NSUInteger nn = names.count;
    NSMutableArray *opened = [NSMutableArray arrayWithCapacity:nn], *ixs = [NSMutableArray arrayWithCapacity:nn], *why = [NSMutableArray arrayWithCapacity:nn];
    for (NSUInteger i = 0; i < nn; i++) { [opened addObject:NSNull.null]; [ixs addObject:NSNull.null]; [why addObject:NSNull.null]; }
    arch_open_begin();   // mapped, as pso4_init's opens are
    dispatch_apply(nn, dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^(size_t i) { @autoreleasepool {
        NSString *p = [g_arch_dir stringByAppendingPathComponent:names[i]]; NSError *ae = nil; int complete = 0, stamp = 0;
        NSData *keys = arch_keys_read_st(arch_keys_path(p), &complete, &stamp);
        if (stamp < 0) return;   // another chain's (not seen: this run wrote it): left to the next start, which removes it
        arch_reads rd = {0};
        id<MTL4Archive> a = arch_file_state_rd(p, &rd) == 1 ? arch_open_read(p, &rd, &ae) : nil;
        @synchronized (opened) {
            if (a) opened[i] = a;
            if (a && keys) ixs[i] = @[keys, @(complete)];
            if (ae) why[i] = ae.localizedDescription ?: @"";
        }
    } });
    arch_open_end();
    NSMutableArray<id<MTL4Archive>> *ixf = [NSMutableArray arrayWithArray:g_arch_ixf ?: @[]], *archp = [NSMutableArray arrayWithArray:g_arch4p ?: @[]];
    NSUInteger front = archp.count && g_arch_bundle && archp[0] == g_arch_bundle;   // the device's files go after the bundled archive, which is asked first
    int nopen = 0, nidx = 0; unsigned long nkeys = 0; unsigned long long obytes = 0;
    for (NSUInteger i = 0; i < nn; i++) {
        NSString *p = [g_arch_dir stringByAppendingPathComponent:names[i]];
        if (opened[i] == NSNull.null) {   // left as it is: the next start's open decides (pso4_init removes a file Metal refuses)
            MLOG("[RED] pipeline archive: the prebuild's new file %s not opened in this run (%s): the next start opens it", p.UTF8String, why[i] != NSNull.null ? [why[i] UTF8String] : "not a pipeline archive");
            continue;
        }
        id<MTL4Archive> a = opened[i]; NSArray *ix = ixs[i] != NSNull.null ? ixs[i] : nil;
        [g_arch_opened addObject:names[i]];
        obytes += [[NSFileManager.defaultManager attributesOfItemAtPath:p error:nil] fileSize];
        nopen++; nidx += ix != nil;
        if (ix) {
            NSData *keys = ix[0]; const uint64_t *kv = keys.bytes; NSUInteger nk = keys.length / sizeof(uint64_t);
            for (NSUInteger j = 0; j < nk; j++) if (!nvn_hm_put(&g_arch_ix, &kv[j], (__bridge void *)a)) nkeys++;   // oldest first: the newest file holds a key
        }
