static void prepare_prebuild(void) {
    const char *e = getenv("DM_PSO_PREBUILD"); if (e && !strcmp(e, "0")) return;
    if (!hybrid_on()) return;
    int n = pso_prebuild(prepare_workers(), 0, QOS_CLASS_USER_INITIATED);
    if (n <= 0) return;
