        if (!atomic_load(&g_pre_running) || atomic_load(&g_warm_stop) || (handed && !later)) break;
        if (p != prog) { prog = p; tp = bp_now(); }
        else if (handed && bp_now() - tp >= (uint64_t)g_pre_prep_idle_ms * NSEC_PER_MSEC) { idle = 1; break; }
        usleep(50000);
