        if (shown) front_progress("Preparing pipelines", g_pre_done, n);
    }
    // the last compiles, g_pre_tail_ms at most, then the last period's write once every worker has returned; none after the idle limit (a compile that does not return)
    uint64_t tail0 = bp_now();
