             (unsigned long long)f, id_, r->stand ? (stale ? "its stand-in, written since" : "its stand-in") : r->stand_no ? "the dummy (no stand-in for it)" : "the dummy", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, t->d.target, t->d.levels, t->d.flags,
             (unsigned long long)(pool_tex_size(t) >> 10), (unsigned long long)(f - r->reg_frame), r->has_v, r->v.set_format, r->v.format, r->v.set_levels, r->v.base_level, r->v.nlevels, r->v.set_layers, r->v.min_layer, r->v.nlayers, r->v.set_target, r->v.target, r->v.set_swizzle);
}
static void pool_seen_scan(void) {
    if (!g_seen_buf || g_seen_sub == g_sub_serial) return;
    g_seen_sub = g_sub_serial;
    uint32_t forked = 0;
    uint64_t f = atomic_load(&g_cur_frame); if (f != g_walk_frame) { g_walk_frame = f; g_walk_spent = 0; g_walk_req = 0; }
    if (g_stand_todo_n) pool_stand_scan(&forked);
    { static uint64_t at, was; uint64_t now = g_stand_made + g_first_stand + g_first_dummy;   // the totals, every 300 frames in which they changed
      if (f >= at + 300 && now != was) { at = f; was = now;
          MLOG("pool stand-ins up to frame %llu: %llu made in %.1f ms (%llu of them a level cut down), %llu gave way to their texture, %llu held now in %d heaps of %u MB (%llu not made: the heaps were full), %u waiting; first reads of a texture not made found a stand-in %llu times%s and the dummy %llu times (%llu of them textures of 256 KB or more)",
               (unsigned long long)f, (unsigned long long)g_stand_made, g_stand_ns / 1e6, (unsigned long long)g_stand_picked, (unsigned long long)g_stand_done, (unsigned long long)g_stand_live, g_nstand_heap, (unsigned)(STAND_HEAP >> 20), (unsigned long long)g_stand_full, g_stand_todo_n, (unsigned long long)g_first_stand,
               g_first_stale ? [NSString stringWithFormat:@" (%llu written since the stand-in was made)", (unsigned long long)g_first_stale].UTF8String : "", (unsigned long long)g_first_dummy, (unsigned long long)g_first_dummy_big); } }
    const uint32_t *w = (const uint32_t *)g_seen_buf.contents; unsigned words = MIN((unsigned)g_ntreg / 32 + 1, (unsigned)POOL_SEEN_WORDS);
    for (unsigned i = 0; i < words; i++) {
        uint32_t fresh = w[i] & ~g_seen_done[i];
        if (fresh) { g_seen_done[i] |= fresh; g_seen_todo[i] |= fresh; for (uint32_t bits = fresh; bits; bits &= bits - 1) { pool_ds_note((int)i * 32 + __builtin_ctz(bits)); pool_first_read((int)i * 32 + __builtin_ctz(bits), f); } }
        for (uint32_t bits = g_seen_todo[i]; bits; bits &= bits - 1) {
            int b = __builtin_ctz(bits), id_ = (int)i * 32 + b;
            if (id_ <= 0 || id_ >= g_ntreg || !g_treg[id_].ok || g_treg[id_].gone || (!g_treg[id_].view && !tex_storage_live(&g_treg[id_].t))) { g_seen_todo[i] &= ~(1u << b); continue; } // NOLINT(clang-analyzer-core.BitwiseShift): bits is nonzero, so ctz returns 0..31
            if (!g_treg[id_].view && pool_unwritten_id(id_, &g_treg[id_].t)) { g_seen_todo[i] &= ~(1u << b); continue; }
            if (!g_treg[id_].view && !pkg_shared(&g_treg[id_].t) && !tex_get(g_treg[id_].t.serial)) { if (g_walk_req >= POOL_REQ_BYTES) return; g_walk_req += pool_tex_size(&g_treg[id_].t); }
            g_seen_todo[i] &= ~(1u << b);
            void *tv = NULL; uint64_t tr = tex_fast_rid(id_, &tv); if (!tv || !tr) continue;
            if (treg_fam_pool_masked(id_, (__bridge id<MTLTexture>)tv, g_treg[id_].t.serial)) continue;   // a compressed family member whose heap holds another size stays the dummy (ser_note on a size switch)
            MTLTextureType tt = ((__bridge id<MTLTexture>)tv).textureType; int trans = g_treg[id_].retired && g_treg[id_].transient_sub == g_sub_serial;
            for (int k = 0; k < POOL_SNAPS; k++) { pool_snap *q = &g_psnap[k]; int at = id_ - q->base;
                if (!q->buf || q->samp || at < 0 || (uint32_t)at >= *(uint32_t *)q->buf.contents || (MTLTextureType)q->dtt != tt) continue;
                pool_snap_set(q, (uint32_t)at, tr, &forked);
                if (trans) { ids_push(&q->trans, id_); if (!q->sub) q->sub = g_sub_serial; } }   // a view of a retired registration goes at this submission's end, so the next one takes it again (pool_gpu)
        }
    }
}
// A table replaced by a new walk, or the buffer a patch left, is reused once the submission that may read it has completed, the last segment's fence covering every segment before it: a new
// buffer each time meant an allocation, a residency add and remove, and a kernel call or more each way, about 3 a frame in Ocarina of Time. Sizes round up to 64 KB, as a pool grows by a
// few IDs at a time. What cannot be used again soon leaves when the spares are full (the idea is from PR 1428).
// The X1.0 iPhone runs of Ocarina of Time made about 6 new tables of about 312 KB a frame (a residency add each) with 16 spares, which three frames in flight fill with tables still
// in flight, so the lowest fence that left was the next to come back. With replay_spares (nvn_replay_spares, hle_nvn.c) up to POOL_SPARES_MAX are kept, and when every one is still
// in flight the table given now, the newest, goes instead (g_pool_dropped); a full set with one completed still lets the lowest fence go, a size the pools have left behind.
// A patched table goes into another buffer, as draws already encoded read the old one: copying the whole table was about 5 MB a frame in Ocarina of Time (16-24 patches a frame of
// its 33,025-entry tables in Kokiri Forest, 0.13-0.18 ms of the submit thread on an M6 against 0.015-0.025 with spares; upstream NXNative d6585a2de, PR #2663). So the buffer a patch
// leaves names its table, that table's build and the log position it holds (g_plog): a later patch of the table takes its finished spare furthest along and writes the entries logged
// since, and copies the table whole only when it has none, or the log has moved past them. A table built whole takes a spare of no live table first
enum { POOL_SPARES = 16, POOL_SPARES_MAX = 64 };
#define POOL_SPARE_BYTES (24u << 20)   // replay_spares: the spares' total, as the command copies have NQ_SPARE_BYTES (Ocarina's tables were about 320 KB, 64 of them 20 MB)
typedef struct { __strong id<MTLBuffer> buf; uint64_t fence, build, lpos; int k; } pool_spare;   // k: the table (g_psnap) of build whose state at log position lpos it holds; -1 none
static pool_spare g_pool_spare[POOL_SPARES_MAX]; static int g_npool_spare; static uint64_t g_pool_made, g_pool_reused, g_pool_dropped; static size_t g_pool_spare_bytes;
static int g_pool_spares = -1;   // how many are kept: POOL_SPARES, or POOL_SPARES_MAX with replay_spares (a unit test may set it directly)
static int pool_spares(void) { if (g_pool_spares < 0) g_pool_spares = nvn_replay_spares() ? POOL_SPARES_MAX : POOL_SPARES; return g_pool_spares; }
// Patches: into a spare of their own table, the entries that took, copied whole because the table had no spare of its own, none finished or the log had moved past them; the time they took
static uint64_t g_stat_pool_replayed, g_stat_pool_replay_n, g_stat_pool_copied[3], g_stat_pool_take_ns;
static int spare_live(const pool_spare *s) { return s->k >= 0 && g_plog[s->k].build == s->build; }
static id<MTLBuffer> spare_out(int i) { id<MTLBuffer> b = g_pool_spare[i].buf; g_pool_spare_bytes -= b.length; g_pool_spare[i] = g_pool_spare[--g_npool_spare]; g_pool_spare[g_npool_spare].buf = nil; return b; }
static id<MTLBuffer> pool_table_take(size_t need) {
    size_t len = (need + 0xffff) & ~(size_t)0xffff; uint64_t done = g_done; int o = -1;
    for (int i = 0; i < g_npool_spare; i++) { const pool_spare *s = &g_pool_spare[i];
        if (s->fence > done || s->buf.length != len) continue;
        if (o < 0 || (spare_live(&g_pool_spare[o]) && !spare_live(s)) || (spare_live(&g_pool_spare[o]) == spare_live(s) && s->fence < g_pool_spare[o].fence)) o = i; }
    if (o >= 0) { g_pool_reused++; return spare_out(o); }
    id<MTLBuffer> b = [g_dev newBufferWithLength:len options:MTLResourceStorageModeShared];
    if (b) { res_add(b); g_pool_made++; }
    return b;
}
static void pool_table_give(id<MTLBuffer> b, int k, uint64_t lpos) {   // k: the table (g_psnap) whose current build b holds at log position lpos; -1 none
    if (!b) return;
    int cap = pool_spares(), big = cap > POOL_SPARES;
    if (cap <= 0) { defer_obj_release(b); return; }   // none kept (a unit test's cap of 0): the loop below would take one out of an empty list
    if (big && b.length > POOL_SPARE_BYTES) { g_pool_dropped++; defer_obj_release(b); return; }   // replay_spares: one table past the whole budget is never kept
    // the oldest goes: a size the pools have left behind, most likely. With replay_spares also while the spares' bytes are over POOL_SPARE_BYTES, so pools that grew never hold more
    while (g_npool_spare >= cap || (big && g_npool_spare && g_pool_spare_bytes + b.length > POOL_SPARE_BYTES)) {
        int o = 0; for (int i = 1; i < g_npool_spare; i++) if (g_pool_spare[i].fence < g_pool_spare[o].fence) o = i;
        g_pool_dropped++;
        if (big && g_pool_spare[o].fence > g_done) { defer_obj_release(b); return; }   // replay_spares, every spare in flight: the newest goes, not the next to come back
        defer_obj_release(spare_out(o)); }
    g_pool_spare[g_npool_spare] = (pool_spare){b, g_fence + 1, k >= 0 ? g_plog[k].build : 0, lpos, k}; g_npool_spare++; g_pool_spare_bytes += b.length;
}
// A buffer for the next version of q's table, holding what q->buf holds now (the patch writes its entries after): its finished spare furthest along, brought up to date from the log, or a copy
static id<MTLBuffer> pool_patch_take(const pool_snap *q) {
    uint64_t t0 = mach_absolute_time(), done = g_done, ln; int k = (int)(q - g_psnap), o = -1, own = 0, fin = 0; ln = g_plog[k].n;
    for (int i = 0; i < g_npool_spare; i++) { const pool_spare *s = &g_pool_spare[i];
        if (s->k != k || s->build != g_plog[k].build || s->buf.length != q->buf.length) continue;
        own = 1; if (s->fence > done) continue;
        fin = 1; if (ln - s->lpos > g_plog[k].cap) continue;
        if (o < 0 || s->lpos > g_pool_spare[o].lpos) o = i; }
    id<MTLBuffer> b;
    if (o < 0) { g_stat_pool_copied[!own ? 0 : !fin ? 1 : 2]++; b = pool_table_take(q->buf.length); if (b) memcpy(b.contents, q->buf.contents, q->buf.length); }
    else {
        uint64_t from = g_pool_spare[o].lpos; b = spare_out(o); g_pool_reused++;
        uint64_t *e = (uint64_t *)((uint8_t *)b.contents + DMSH_POOL_HEAD); const uint32_t *at = g_plog[k].at; const uint64_t *v = g_plog[k].v; uint32_t cap = g_plog[k].cap;
        memcpy(b.contents, q->buf.contents, DMSH_POOL_HEAD);   // the head: the bound and the read bitmap's address
        for (uint64_t j = from; j < ln; j++) e[at[j % cap]] = v[j % cap];
        g_stat_pool_replayed++; g_stat_pool_replay_n += ln - from;
    }
    g_stat_pool_take_ns += mach_absolute_time() - t0;   // ticks: mtl_pool_stats converts
    return b;
}
// The power line's pool table counts (hle_nvn.c): builds, their time (us), patched, kept, of those over pool changes and over a new submission; patches into a spare of their own and the entries
// that took, patches copied whole (no spare of their own, none finished, the log past them), the patches' copy and replay time (us); the bytes of the tables' buffers in use and spare
void mtl_pool_stats(uint64_t s[POOL_STATS]) {
    static mach_timebase_info_data_t tb; if (!tb.denom) mach_timebase_info(&tb);
    // The power line (hle_nvn.c power_line) calls this on the game's present thread, while the thread that encodes (the encoding thread, or the submit thread) replaces each
    // table's buffer in its walks (pool_walk, pool_snap_set) and lets the one before go, under g_rmu: read the tables and the walk's counts under it too. Unlocked, the read
    // could message a buffer just released (issue #3300)
    os_unfair_lock_lock(&g_rmu);
    uint64_t used = 0; for (int k = 0; k < POOL_SNAPS; k++) if (g_psnap[k].buf) used += g_psnap[k].buf.length;
    uint64_t v[POOL_STATS] = {g_stat_pool_builds, (uint64_t)(g_stat_pool_ms * 1000), g_stat_pool_patched, g_stat_pool_kept, g_stat_pool_pchg, g_stat_pool_schg, g_stat_pool_replayed, g_stat_pool_replay_n,
        g_stat_pool_copied[0], g_stat_pool_copied[1], g_stat_pool_copied[2], g_stat_pool_take_ns * tb.numer / tb.denom / 1000, used, g_pool_spare_bytes};
    os_unfair_lock_unlock(&g_rmu);
    memcpy(s, v, sizeof v);
}
// The spares' counts for the power line's 'pool tables up to frame' (hle_nvn.c), with replay_spares: tables made, reused, spares kept now and of how many, let go. The patch path
// (pool_table_take in pool_gpu) makes and reuses nearly all of Ocarina of Time's tables, and the 'pool walk' line, written from the whole-table path every 500 builds, came once a run
void mtl_pool_spare_stats(uint64_t s[5]) { s[0] = g_pool_made; s[1] = g_pool_reused; s[2] = (uint64_t)g_npool_spare; s[3] = (uint64_t)pool_spares(); s[4] = g_pool_dropped; }
// One entry of a pool table, as the walk takes it: the resource ID of what the ID holds (0: nothing of the type, or a texture not made). gone counts IDs without storage, and *dead is set for
// one whose storage does not exist (yet): one marked gone stays so until it is registered again, which is noted. left / left_req count the textures past limit (what this frame may still
// make) and those of them a shader read. *transient is set for a view of a retired registration, which goes at the end of this submission. Caller holds g_rmu
static uint64_t pool_entry(int samp, int dtt, int id_, uint64_t limit, int *gone, int *left, int *left_req, int *transient, int *dead) {
    if (samp) return samp_reg(id_) && samp_fast(id_) ? g_srid[id_] : 0;
    if (id_ <= 0) return 0;
    if (id_ >= g_ntreg || !g_treg[id_].ok) return 0;
    const treg_t *r = &g_treg[id_];
    if (r->gone) { ++*gone; return 0; }
    // DM_NVN_POOL_ENTRY: an ID whose texture type is known (tt1, cleared by a registration) and not the table's holds nothing here, whatever its storage, budget or stand-in: answered
    // first. A patch takes each ID it reads in the registration log again in every table of the pool (a 2D one and a 2D-array one in Ocarina of Time), and the checks below cost a
    // lock or three an ID (tex_storage_live's g_mu, pool_unwritten_target's and pkg_shared's g_smu); they also counted such an ID as left out (a walk the next frame) or dead
    if (g_pool_entry > 0 && r->tt1 && r->tt1 - 1 != dtt) return 0;
    if (!r->view && !tex_storage_live(&r->t)) { ++*gone; *dead = 1; return 0; }
    if (!r->view && pool_unwritten_id(id_, &r->t)) return 0;   // dummy until a pass writes it (its new texture is noted: ser_note)
    if (!r->view && pool_tex_size(&r->t) > limit && !pkg_shared(&r->t) && !tex_get(r->t.serial) && !(pool_seen(id_) && g_walk_req < POOL_REQ_BYTES)) { ++*left; *left_req += pool_seen(id_); return pool_stand(id_, dtt); }   // a texture a shader read is made whatever the budget, so it reads its stand-in or the dummy for a few frames at most
    if (r->tt1 && r->tt1 - 1 != dtt) return 0;   // an ID of another texture type, seen before (the table holds only its own type): nothing to look up or charge (the idea is from PR 1428)
    if (!r->view && !pkg_shared(&r->t)) { g_walk_spent += pool_tex_size(&r->t); if (pool_seen(id_)) g_walk_req += pool_tex_size(&r->t); }
    void *tv = NULL; unsigned tt = 0, tpf = 0; uint64_t tr = g_pool_entry > 0 ? tex_fast_rid_tp(id_, &tv, &tt, &tpf) : tex_fast_rid(id_, &tv);   // DM_NVN_POOL_ENTRY: the type kept with the view
    if (!tv) return 0;
    if (treg_fam_pool_masked(id_, (__bridge id<MTLTexture>)tv, r->t.serial)) return 0;   // a compressed family member whose heap holds another size: the dummy, until a size switch notes its serial (fam_set_valid)
    MTLTextureType got = g_pool_entry > 0 ? (MTLTextureType)tt : ((__bridge id<MTLTexture>)tv).textureType; g_treg[id_].tt1 = (uint8_t)got + 1;
    if (got != (MTLTextureType)dtt) return 0;
    // a pool entry carries no offset table entry, so a buffer texture whose view starts before it (tbuf_lead) is read that many elements early through it
    if (got == MTLTextureTypeTextureBuffer && !g_red_once[182]) { uint32_t lead = tbuf_lead(id_, (__bridge id<MTLTexture>)tv);
        if (lead) RED_ONCE(182, "buffer texture (texture ID %d) whose view starts %u elements before it (below Metal's view alignment), read through a texture pool or handle table: read %u elements early", id_, lead, lead); }
    if (g_treg[id_].retired && g_treg[id_].transient_sub == g_sub_serial) *transient = 1;
    return tr;
}
static uint64_t pool_walk(int samp, int dtt, int dpf, int base, __unsafe_unretained id<MTLBuffer> *out);
// The pool walk's read-ahead (DM_NVN_POOL_READAHEAD, on by default; =0 off): before a walk or a patch resolves its texture IDs, the storage of each one whose texture is not made yet
// (no view: pool_entry will make it, give it a stand-in from its smallest levels, or scan it) is asked for ahead, all of them at once on the read-ahead queue (fwire_advise: F_RDADVISE,
// off this lock). With DM_NVN_PF_PARTS=1, Ocarina of Time on the iPhone 18 Pro Max (7cc596635) put 4,000-6,600 page-ins of 310-480 ms area-load frames in the pool tables: the walk
// met each new texture's storage one page at a time, after memory pressure had sent the game's pages back to its files. Asked for together, the reads go to the disk at once. A
// texture is asked for once (its serial, g_pra), and one under 16 KB not at all. Caller holds g_rmu
static int g_pra_on = -1;   // the switch (a test may set it)
static nvn_hmap g_pra = {.klen = 8};   // serial -> 1 its stand-in's levels asked for, 2 its whole storage; emptied when it grows past PRA_MAX
enum { PRA_MAX = 1 << 20 };
static int pra_on(void) { if (g_pra_on < 0) { const char *e = getenv("DM_NVN_POOL_READAHEAD"); g_pra_on = e && atoi(e) > 0; if (g_pra_on) MLOG("DM_NVN_POOL_READAHEAD=1: the pool walk asks ahead for the storage of the textures it will make this frame and the levels of the stand-ins it will make"); } return g_pra_on; }
// The second version (narrow): only what this walk will read. A texture it will make (no larger than limit, within this frame's room as the walk spends it) has its whole storage
// asked for, up to the room; one it will give a stand-in (larger than limit, the table over its budget: pool_stand) only the stand-in's levels of its first layers, up to
// STAND_FRAME a walk. Each once (g_pra by serial and kind). The first version asked for every texture not made, which the walk passes again at each walk: about 317 GB in 137 s
