        g_tu_pend.n += st.n; g_tu_pend.bytes += st.bytes; g_tu_pend.fam += st.fam; g_tu_pend.fam_n += st.fam_n; g_tu_pend.fam_bytes += st.fam_bytes; g_tu_pend.passes++;
