             "every %u ms, %llu passes in this window (%llu more skipped in all: no covered target unused for the wait), %.2f ms", g_tu_idle / 10.0, pw, (unsigned long long)f, (unsigned long long)(g_tu_n - w_n), (unsigned long long)((g_tu_bytes - w_bytes) >> 20),
             fam, (unsigned long long)(remade - w_remade), press, (unsigned long long)g_tu_n, (unsigned long long)(g_tu_bytes >> 20), (unsigned long long)remade,
             (unsigned long long)g_tu_serials, (unsigned long long)g_tu_pinned, (unsigned long long)g_tu_fam_n, g_tu_fam_bytes / 1048576.0, live, g_tu_every * 100, (unsigned long long)(g_tu_passes - w_passes), (unsigned long long)g_tu_skipped, (g_tu_ns - w_ns) / 1e6);
        at = f; w_n = g_tu_n; w_bytes = g_tu_bytes; w_fam = g_tu_fam; w_remade = remade; w_ns = g_tu_ns; w_passes = g_tu_passes; w_fam_n = g_tu_fam_n; w_fam_bytes = g_tu_fam_bytes; w_pn = g_tu_press_n; w_pb = g_tu_press_bytes; w_plo = w_phi = 0; g_tu_lines++;
