static void tu_check_at(uint32_t idle, int why) { g_tu_checked = g_tu_now; if (tu_any_idle(g_tu_now, idle)) tu_pass_at(idle, why); else g_tu_skipped++; }
static void tu_check(void) { tu_check_at(g_tu_idle, 0); }
// The back-off's next window (g_tu_bo_ep): from 1, a low spell's start, which is the spell's first window too; 2, a step
static void tu_bo_window(int from) {
    g_tu_bo_n0 = g_tu_press_n; g_tu_bo_from = from;
    os_unfair_lock_lock(&g_tu_lk); g_tu_bo_ep++; g_tu_bo_q = 0; if (from == 1) { g_tu_spell_ep = g_tu_bo_ep; g_tu_spell_q = 0; } os_unfair_lock_unlock(&g_tu_lk);
}
// The headroom (at most every TU_HR_EVERY_NS) and whether it is low; a low spell's start and end are a line each, and its end takes the back-off down a step
static int tu_low_now(void) {
    if (!g_rh_avail || !tu_press_mode()) return 0;
    uint64_t t = clock_gettime_nsec_np(CLOCK_MONOTONIC);
    if (g_tu_hr_at && t - g_tu_hr_at < TU_HR_EVERY_NS) return g_tu_low;
    g_tu_hr_at = t; g_tu_hr = g_rh_avail();
    int low = tu_low_next(g_tu_low, g_tu_hr);
    if (low == g_tu_low) return low;
    g_tu_low = low;
    uint64_t f = atomic_load(&g_cur_frame);
    if (low) {
        g_tu_spell.n = g_tu_press_n; g_tu_spell.bytes = g_tu_press_bytes; g_tu_spell.frame = f; g_tu_spell.at = g_tu_now;
        tu_bo_window(1);
        MLOG("render targets drawn over (DM_NVN_RT_DEAD_PRESSURE): headroom to the system memory limit %llu MB, under %llu MB, at frame %llu: released after %.1f s unused (and the last %d frames), "
             "a check every %d ms, until the headroom is over %llu MB", (unsigned long long)(g_tu_hr >> 20), (unsigned long long)(TU_LOW_HEADROOM >> 20), (unsigned long long)f,
             tu_press_wait(g_tu_now, 0) / 10.0, TU_PRESS_FRAMES, TU_PRESS_EVERY * 100, (unsigned long long)(TU_HEADROOM_OK >> 20));
    } else {
        int step = g_tu_shift > 0; if (step) g_tu_shift--;
        char bo[96] = ""; if (step) snprintf(bo, sizeof bo, "; the back-off down a step: %.1f s at the next low headroom", (TU_PRESS_IDLE << g_tu_shift) / 10.0);
        os_unfair_lock_lock(&g_tu_lk); uint64_t q = g_tu_spell_q; os_unfair_lock_unlock(&g_tu_lk);
        uint64_t n = g_tu_press_n - g_tu_spell.n; if (q > n) q = n;   // (a texture released under two serials and made again as two textures would count twice)
        MLOG("render targets drawn over (DM_NVN_RT_DEAD_PRESSURE): headroom back to %llu MB, over %llu MB, at frame %llu after %.1f s low: %llu textures, %llu MB released sooner in it, "
             "%llu of them made again within %d s; the wait is %.1f s again%s", (unsigned long long)(g_tu_hr >> 20), (unsigned long long)(TU_HEADROOM_OK >> 20), (unsigned long long)f,
             (g_tu_now - g_tu_spell.at) / 10.0, (unsigned long long)n, (unsigned long long)((g_tu_press_bytes - g_tu_spell.bytes) >> 20), (unsigned long long)q, TU_PRESS_REMADE_DS / 10, g_tu_idle / 10.0, bo);
    }
