// The back-off: of the targets pressure passes released in its window (since its last step or the low spell's start), TU_BACKOFF_MIN or more, and a quarter or more, made again
// within TU_PRESS_REMADE_DS of their release
static void tu_backoff(void) {
    uint64_t r = g_tu_press_n - g_tu_bo_n0;
    if (!r) return;
    os_unfair_lock_lock(&g_tu_lk); uint64_t q = g_tu_bo_q; os_unfair_lock_unlock(&g_tu_lk);
    if (q > r) q = r;   // (a texture released under two serials and made again as two textures would count twice)
    if (q < TU_BACKOFF_MIN || 4 * q < r) return;
    static const char *const since[] = {"the start", "the low headroom began", "the last back-off step"};
    const char *from = since[g_tu_bo_from];
    tu_bo_window(2);
    if (g_tu_shift >= TU_BACKOFF_MAX) return;
    g_tu_shift++;
    MLOG("render targets drawn over (DM_NVN_RT_DEAD_PRESSURE): %llu of %llu textures released at memory pressure since %s were made again within %d s: the low-headroom wait doubles to %.1f s (back-off step %d)",
         (unsigned long long)q, (unsigned long long)r, from, TU_PRESS_REMADE_DS / 10, ((TU_PRESS_IDLE << g_tu_shift) < g_tu_idle ? (TU_PRESS_IDLE << g_tu_shift) : g_tu_idle) / 10.0, g_tu_shift);
}
// The release line, once the GPU is done with what went (two submissions past the last pass's: the heaps' residency removal committed too) and a second after the first release
static void tu_press_line(void) {
