    uint64_t hr1 = g_rh_avail ? g_rh_avail() : 0, fp1 = mem_footprint(); char hr[64];
    if (g_tu_pend.hr0 && hr1) snprintf(hr, sizeof hr, "%llu → %llu MB", (unsigned long long)(g_tu_pend.hr0 >> 20), (unsigned long long)(hr1 >> 20)); else snprintf(hr, sizeof hr, "none");
    static const char *const whyn[] = {"", "low memory headroom", "a memory warning", "low memory headroom and a memory warning"};
    MLOG("render targets drawn over and unused for %.1f s, released at %s (DM_NVN_RT_DEAD_PRESSURE): %llu textures, %llu MB (and %llu resolution-family members in %llu whole families, their heaps %.1f MB), "
         "freed, not kept for reuse; headroom to the system memory limit %s, footprint %llu → %llu MB; from frame %llu, %llu pass%s", g_tu_pend.wait / 10.0, whyn[g_tu_pend.why & 3],
         (unsigned long long)g_tu_pend.n, (unsigned long long)(g_tu_pend.bytes >> 20), (unsigned long long)g_tu_pend.fam, (unsigned long long)g_tu_pend.fam_n, g_tu_pend.fam_bytes / 1048576.0,
         hr, (unsigned long long)(g_tu_pend.fp0 >> 20), (unsigned long long)(fp1 >> 20), (unsigned long long)g_tu_pend.frame, (unsigned long long)g_tu_pend.passes, g_tu_pend.passes == 1 ? "" : "es");
