static id<MTLBuffer> gmem_map(void) { return gmem_map_at(0); }   // a draw's: the commit makes its word current (gmem_commit_patch)
static id<MTLBuffer> gmem_map_at(int current) {
    uint64_t gen = atomic_load(&g_pool_gen);
    if (g_gmem_buf && g_gmem_gen == gen) return g_gmem_buf;
    if (!current && g_gmem_buf && g_gmem_sub == g_sub_serial && atomic_load(&g_pool_drop_gen) <= g_gmem_gen && gmem_keep_on()) { g_gmem_kept++; return g_gmem_buf; }
    id<MTLBuffer> b = [g_dev newBufferWithLength:DMSH_GMEM_MAP_ENTRIES * DMSH_GMEM_MAP_ENTRY options:MTLResourceStorageModeShared];
    g_gmem_seen = 1;   // res_trickle may start
    uint8_t *t = (uint8_t *)b.contents; memset(t, 0, b.length);
    for (int k = 1; k < DMSH_GMEM_MAP_ENTRIES; k++) memset(t + (size_t)k * DMSH_GMEM_MAP_ENTRY, 0xff, 8);
    int n = 1, over = 0, added = 0; uint64_t end = 0;
