        pool_ent *p = &g_pools[g_pidx[k]];
        if (!addr_meets(p->lo, p->hi)) continue;
        if (!p->res) { pool_res_mark(g_pidx[k], UNW_RE_RAW); res_add(p->buf); p->res = 1; g_pool_res_n++; atomic_fetch_add(&g_pool_res_open, 1); added++; }   // committed below, after g_mu (pool_res)
        uint64_t lo = MAX((uint64_t)p->lo, end), hi = p->hi;
        if (lo >= hi) continue;
        if (n == DMSH_GMEM_MAP_ENTRIES) { over++; continue; }
        uint8_t *entry = t + (size_t)n++ * DMSH_GMEM_MAP_ENTRY;
        uint64_t e[3] = {lo, hi, p->gpu - p->base}; memcpy(entry, e, sizeof e);
