    { static int said; if (!said++) MLOG("raw global memory: pool table of %d ranges (pool generation %llu), rebuilt at the next draw when a pool goes or a submission begins after a change, and at each commit when pools came (DM_NVN_GMEM_KEEP=0: whenever a pool comes or goes)", n - 1, (unsigned long long)gen); }
