        const p_bind_buf *u = &S.ssbo[stage][sh->rf.gptr[q].reg]; uint64_t off = sh->rf.gptr[q].off, ptr = 0;
        if (!u->addr || (u->size && (off > u->size || u->size - off < 8))) continue;
