    if (predict) for (int i = 0; i < g_gml_n; i++) sbw_note(g_gml_lo[i], g_gml_hi[i] - g_gml_lo[i], SBW_GPU);
    pthread_mutex_unlock(&g_gml_mu);
    if (!predict) sbw_note(0, 0, SBW_GPU);
