    for (int i = r->n - 1; i >= 0 && r->e[i].seq > seq; i--) { k |= r->e[i].k; t |= r->e[i].tm; m |= r->e[i].sm; }
    *tm = t; *sm = m; return k;
}
static uint64_t drv_bank(const NvShader *sh, int st, int bank, __unsafe_unretained id<MTLBuffer> *out) {
    const int c2 = bank != 0; drv_bank_t *c = &g_drvb[c2][st];
    const int dyn = c2 ? sh->rf.dyn : 0, tb = c2 && sh->rf.pool ? S.tex_base : 0, sb = c2 && sh->rf.pool ? S.samp_base : 0;
    uint64_t tm = 0, sm = 0; int k = -1;
    if (c->cpu && c->sub == g_sub_serial && c->dyn == dyn && c->tb == tb && c->sb == sb) k = pk_since(st, c->seq, &tm, &sm);
    const int bi = c->binst != g_draw_binst, sa = st == 1 && c->samples != g_pass.samples;
    if (k >= 0 && (c2 ? !(k & (PK_TEX | PK_SAMP)) : !(k & PK_SSBO) && !bi && !sa)) { g_stat_drv[c2][DB_HIT]++; *out = c->buf; return c->gpu; }
    __unsafe_unretained id<MTLBuffer> db; arena_at a = arena_take_u(DMSH_DRV_SIZE, &db); uint8_t *d = a.cpu;
    if (k >= 0) {
