            for (uint64_t bits = (k & PK_TEX) ? tm : 0; bits; bits &= bits - 1) for (int i = __builtin_ctzll(bits); i < NTEX; i += 64) c2_row_tex(d, st, i, dyn, tb, sb);
            for (uint64_t bits = (k & PK_SAMP) ? sm : 0; bits; bits &= bits - 1) for (int i = __builtin_ctzll(bits); i < DMSH_C2_SEP_SLOTS; i += 64) c2_row_samp(d, st, i, dyn, tb, sb);
