    return gpu;
}
// The uniform slots' readable sizes (DMSH_CBSIZE_BANK, ub_live: the bound size rounded up to 256 bytes where its pool reaches), which the translator's reads at computed offsets compare
// with: one past it gives 0, as on Maxwell. 0 for an unbound slot, whose reads go to the zero bank (cbuf_slot) and get 0 here too
static uint64_t cbsize_table(int nvn_stage, __unsafe_unretained id<MTLBuffer> *use) {   // *use: borrowed, an arena block (arena_take_u)
    arena_at at_off = arena_take_u(16 * ((DMSH_CBSIZE_SLOTS + 3) / 4), use); uint32_t *d = (uint32_t *)(void *)at_off.cpu;
    memset(d, 0, 16 * ((DMSH_CBSIZE_SLOTS + 3) / 4));
    for (int r = 0; r < DMSH_CBSIZE_SLOTS; r++) { const p_bind_buf *u = &S.ubo[nvn_stage][r]; if (u->addr) d[r] = u->size < 65536 ? (uint32_t)ub_live(u) : 65536; }
    return at_off.gpu;
}
// Whether a block of sh can be patched when only what the uniform bindings point at changed: every binding that reads through a uniform buffer is a plain CBUF slot (no handles or
// addresses read out of one: TEXU, SAMPU, IMGU, TBUFU, TEXH, SAMPH, SBUFU, UBOP), or the slots' size table (CBSIZE, made from the bindings alone), and no slot is registered by its
// location (GMEM / GMEML: gmem_slot_note). An allow-list, so a new kind is never patched
// With partial patches on (DM_NVN_ARGS_PARTIAL), the list also takes the kinds that read nothing through a uniform buffer but were left off it: buffer textures in texture slots (TBUF), the
// dynamic handle arrays (TEXD / SAMPD: the bound slots) and the driver table's (TEXA / SAMPA: c2's handles, the bound slots too), and the pools (TEXP / SAMPP: their tables are checked
// by g_psnap_gen, as for a reuse); and a shader that reads no uniform at all (PKF_NOUBO) keeps its block as it is. These were full encodes counted as ubo_unpatchable
enum { PKF_DONE = 1, PKF_PART = 2, PKF_UBO = 4, PKF_NOUBO = 8 };
enum { PKK_UBO, PKK_OK, PKK_WIDE, PKK_GEO, PKK_NO };   // a binding kind for args_pkind: a uniform slot or its sizes, on args_cbuf_only's list, added to it, the geometry buffers, neither
static int pk_kclass(int kind) {
    switch (kind) {
        case NVN_RB_CBUF: case NVN_RB_CBSIZE: return PKK_UBO;
        case NVN_RB_SAMP: case NVN_RB_SAMPT: case NVN_RB_SAMPI: case NVN_RB_TEX: case NVN_RB_IMG: case NVN_RB_SBUFP: case NVN_RB_SUPPORT: case NVN_RB_C1: case NVN_RB_DRV0: case NVN_RB_DRV2:
        case NVN_RB_PUSH: case NVN_RB_BORDER: return PKK_OK;
        case NVN_RB_TBUF: case NVN_RB_TEXD: case NVN_RB_SAMPD: case NVN_RB_TEXA: case NVN_RB_SAMPA: case NVN_RB_TEXP: case NVN_RB_SAMPP: return PKK_WIDE;
        case NVN_RB_GEOMETRY: return PKK_GEO;   // set per draw: kept as the uniform patch keeps it, never part of a partial one
        default: return PKK_NO;                 // a uniform buffer's handles or addresses (TEXU, SAMPU, IMGU, TBUFU, SBUFU, SBUFQ, TEXH, SAMPH, UBOP), the raw pool table, a kind not listed
    }
}
static int args_pkind(NvShader *sh) {   // PKF_*, decided once a shader: PKF_PART its kinds allow a partial patch (args_partial), PKF_UBO the wider uniform patch, PKF_NOUBO no uniform read
    if (__builtin_expect(sh->ab_pkind, 1)) return sh->ab_pkind;
    int part = 1, ubo = 1, reads = 0;
    for (int i = 0; i < sh->rf.nb; i++) switch (pk_kclass(sh->rf.b[i].kind)) {
        case PKK_UBO: reads = 1; break;
        case PKK_GEO: part = 0; break;
        case PKK_NO: part = ubo = 0; reads = 1; break;
    }
    sh->ab_pkind = (uint8_t)(PKF_DONE | (part ? PKF_PART : 0) | (ubo ? PKF_UBO : 0) | (ubo && !reads ? PKF_NOUBO : 0));
    return sh->ab_pkind;
}
static int args_cbuf_only(NvShader *sh) {
    if (__builtin_expect(g_res_check_on, 0)) return 0;   // the resource check (USE) sees every slot of a full encode
    if (g_args_partial > 0 && (args_pkind(sh) & PKF_UBO)) return 1;
    if (sh->ab_cbuf_only) return sh->ab_cbuf_only == 1;
    int ok = 1, cb = 0;
    for (int i = 0; i < sh->rf.nb && ok; i++) switch (sh->rf.b[i].kind) {
        case NVN_RB_CBUF: cb = 1; break;
        case NVN_RB_SAMP: case NVN_RB_SAMPT: case NVN_RB_SAMPI: case NVN_RB_TEX: case NVN_RB_IMG: case NVN_RB_SBUFP: case NVN_RB_SUPPORT: case NVN_RB_C1:
        case NVN_RB_DRV0: case NVN_RB_DRV2: case NVN_RB_PUSH: case NVN_RB_BORDER: case NVN_RB_GEOMETRY: case NVN_RB_CBSIZE: break;
        default: ok = 0;
    }
    sh->ab_cbuf_only = ok && cb ? 1 : 2;
    return sh->ab_cbuf_only == 1;
}
// The shader lists of the last CBS_FLY committed command buffers, by fence: a hang report names what the command buffer it waits for runs (mtl_wait_at)
#define CBS_FLY 64
static struct { uint64_t fence; cbs_list *l; uint32_t cap; } g_cbs_fly[CBS_FLY]; static uint32_t g_cbs_fly_i;   // cap: entries the slot's list has room for, so it is reused, not made again each commit
static void cbs_fly_put(uint64_t fence, const cbs_list *l) {
    if (!l) return;
    pthread_mutex_lock(&g_cbs_mu); uint32_t i = g_cbs_fly_i++ % CBS_FLY;
    if (!g_cbs_fly[i].l || g_cbs_fly[i].cap < l->n) {   // with no memory the slot keeps its older list and fence: the hang report is a diagnostic
        cbs_list *c = realloc(g_cbs_fly[i].l, sizeof *l + l->n * sizeof *l->e); if (!c) { pthread_mutex_unlock(&g_cbs_mu); return; }
        g_cbs_fly[i].l = c; g_cbs_fly[i].cap = l->n;
    }
    memcpy(g_cbs_fly[i].l, l, sizeof *l + l->n * sizeof *l->e); g_cbs_fly[i].fence = fence; pthread_mutex_unlock(&g_cbs_mu);
}
// The last IND_FLY indirect dispatches (fence of their command buffer, shader, where the GPU reads the group counts): a hang report prints the counts as they are now
#define IND_FLY 64
static struct { uint64_t fence, ind, off; void *buf; char key[CBS_KEY]; } g_ind_fly[IND_FLY]; static uint32_t g_ind_fly_i;
static void ind_fly_put(const char *key, uint64_t ind, uint64_t off, void *buf) {
    pthread_mutex_lock(&g_cbs_mu); uint32_t i = g_ind_fly_i++ % IND_FLY;
    g_ind_fly[i].fence = g_fence + 1; g_ind_fly[i].ind = ind; g_ind_fly[i].off = off; g_ind_fly[i].buf = buf; strlcpy(g_ind_fly[i].key, key, CBS_KEY);
    pthread_mutex_unlock(&g_cbs_mu);
}
static void cbs_fly_report(uint64_t fence) {
    pthread_mutex_lock(&g_cbs_mu);
    for (uint32_t i = 0; i < CBS_FLY; i++) if (g_cbs_fly[i].l && g_cbs_fly[i].fence == fence) {
        const cbs_list *l = g_cbs_fly[i].l; char b[CBS_SHOW * (CBS_KEY + 1) + 32], *e = b; *b = 0;
        for (uint32_t k = 0; k < l->n && k < CBS_SHOW; k++) e += snprintf(e, sizeof b - (size_t)(e - b), "%s%s", k ? " " : "", l->e[k].key);
        MLOG("[RED] game shaders of the command buffer of fence %llu: %u: %s%s", (unsigned long long)fence, l->n, l->n ? b : "none", l->n > CBS_SHOW ? " and more" : "");
    }
    for (uint32_t i = 0; i < IND_FLY; i++) if (g_ind_fly[i].buf && g_ind_fly[i].fence == fence) {
        const uint32_t *g = (const uint32_t *)((uint8_t *)[(__bridge id<MTLBuffer>)g_ind_fly[i].buf contents] + g_ind_fly[i].off);
        MLOG("[RED]   its indirect dispatch of %s: %u x %u x %u groups now at %#llx", g_ind_fly[i].key, g[0], g[1], g[2], (unsigned long long)g_ind_fly[i].ind);
    }
    pthread_mutex_unlock(&g_cbs_mu);
}
static int encode_args_(id<MTL4CommandEncoder> en, NvShader *sh, int nvn_stage, int metal_vertex);
static int args_xpass_on(void) {
    if (__builtin_expect(g_args_xpass < 0, 0)) { const char *e = getenv("DM_NVN_ARGS_XPASS"); g_args_xpass = !(e && !strcmp(e, "0"));
        if (!g_args_xpass) MLOG("DM_NVN_ARGS_XPASS=0: argument blocks are reused only within the render pass that encoded them, as before"); }
    return g_args_xpass;
}
// Whether sh's bindings let its blocks outlive their pass (decided once a shader, NvShader ab_xkind): 1 yes, 3 yes while the uniform memory it reads handles or addresses from holds
// (TEXU, SAMPU, IMGU, TBUFU, SBUFU, TEXH, SAMPH: read on the CPU at the encode, through the inline updates queued in this submission), 2 no: a stage other than vertex and fragment,
// the geometry emulation's buffers (set per draw), the raw pool table and its write log (gmem_slot_note, gml_take: a log per block), or a kind this list does not know. An allow-list,
// as args_cbuf_only's, so a new kind is never reused across passes before it is looked at
static int args_xkind(NvShader *sh, int nvn_stage) {
    if (sh->ab_xkind) return sh->ab_xkind;
    int ok = nvn_stage == 0 || nvn_stage == 1, mem = 0;
    for (int i = 0; i < sh->rf.nb && ok; i++) switch (sh->rf.b[i].kind) {
        case NVN_RB_CBUF: case NVN_RB_SAMP: case NVN_RB_SAMPT: case NVN_RB_SAMPI: case NVN_RB_TEX: case NVN_RB_IMG: case NVN_RB_TBUF: case NVN_RB_TEXD: case NVN_RB_SAMPD:
        case NVN_RB_TEXA: case NVN_RB_SAMPA: case NVN_RB_TEXP: case NVN_RB_SAMPP: case NVN_RB_SBUFP: case NVN_RB_UBOP: case NVN_RB_SBUFQ: case NVN_RB_C1: case NVN_RB_SUPPORT:
        case NVN_RB_CBSIZE: case NVN_RB_PUSH: case NVN_RB_DRV0: case NVN_RB_DRV2: case NVN_RB_BORDER: break;
        case NVN_RB_TEXU: case NVN_RB_SAMPU: case NVN_RB_IMGU: case NVN_RB_TBUFU: case NVN_RB_SBUFU: case NVN_RB_TEXH: case NVN_RB_SAMPH: mem = 1; break;
        default: ok = 0;
    }
    sh->ab_xkind = !ok ? 2 : mem ? 3 : 1;
    return sh->ab_xkind;
}
// A block of this submission whose stage's hard generation holds is reused in a later pass or after another program (DM_NVN_ARGS_XPASS). What the pass rule (ab_pass) caught besides
// the arena, checked here: the pass's sample count (c0's sample rows); a block made of copies or of handles read from memory (ab_xok 2) also needs no write queued or made since
// (g_npend, g_pend_over: inline updates, copies, fills; g_wr_epoch: buffer writes outside a pass, landed deferred updates; g_tba_gen: aligned buffer-texture copies made again; g_sbw_gen:
// GPU storage writes noted). The rest is checked as for the pass rule (encode_args_): base instance, pool and handle tables, uniform slots. A same-pass feedback snapshot never outlives its
// draw (ab_xok 0), and a binding change of the stage, a registration, a guest write or a replaced texture moves the hard generation (args_dirty, args_sync_dirty)
static inline int args_xpass_ok(const NvShader *sh, int nvn_stage) {
    if (!sh->ab_xok || sh->ab_sub != g_sub_serial || sh->ab_hgen != g_args_hgen[nvn_stage]) return 0;
    if (nvn_stage == 1 && sh->rf.drv_read[0] && sh->ab_samples != g_pass.samples) return 0;
    if (sh->ab_xok == 2 && (sh->ab_npend != g_npend || g_pend_over || sh->ab_wr != g_wr_epoch || sh->ab_tba != g_tba_gen || sh->ab_sbw != g_sbw_gen)) return 0;
    return 1;
}
static inline void args_xpass_stamp(NvShader *sh) { sh->ab_npend = g_npend; sh->ab_wr = g_wr_epoch; sh->ab_tba = g_tba_gen; sh->ab_sbw = g_sbw_gen; }
// DM_NVN_ARGS_REGCHK: whether sh's kinds let args_rck tell its block's IDs (decided once a shader, ab_rkind): every binding names its texture, image or sampler by a slot of the
// stage (TEX, TBUF, IMG, SAMP, SAMPT; SAMPI a constant ID), or names none (uniform and storage slots, their sizes, c0 / c2 (handles, not resource IDs), c1, the support buffer, push
// constants, the border block made from the samplers), or is a pool (TEXP / SAMPP: taken again, args_partial). An allow-list: a kind not on it is never checked
static int args_rkind(NvShader *sh) {
    if (__builtin_expect(sh->ab_rkind, 1)) return sh->ab_rkind;
    int ok = 1;
    for (int i = 0; i < sh->rf.nb && ok; i++) switch (sh->rf.b[i].kind) {
        case NVN_RB_TEX: case NVN_RB_TBUF: case NVN_RB_IMG: case NVN_RB_SAMP: case NVN_RB_SAMPT: case NVN_RB_SAMPI: case NVN_RB_CBUF: case NVN_RB_CBSIZE: case NVN_RB_SBUFP:
        case NVN_RB_DRV0: case NVN_RB_DRV2: case NVN_RB_C1: case NVN_RB_SUPPORT: case NVN_RB_PUSH: case NVN_RB_BORDER: case NVN_RB_TEXP: case NVN_RB_SAMPP: break;
        default: ok = 0;
    }
    sh->ab_rkind = ok ? 1 : 2;
    return sh->ab_rkind;
}
// Whether sh's block, from before the last registration sync (g_args_rck > ab_rck), still holds what its texture, image and sampler bindings resolve to: none of the IDs the stage's
// slots name now (the IDs the block was made from: its stage's hard generation held, or each change since is one the patch writes again) was stamped since. 1: current (ab_rck
// moves to now), 0: an ID it holds was registered since, or its kinds allow no check (AW_REG_ID / AW_REG_UNCHK for DM_NVN_ARGS_STATS)
static uint8_t g_rck_fail;
static __attribute__((noinline)) int args_rck(NvShader *sh, int st) {
