            case NVN_RB_IMG: t = b->reg < 32 ? rck_tex(S.img[st][b->reg]) : 0; break;
            case NVN_RB_SAMP: case NVN_RB_SAMPT: case NVN_RB_SAMPI: t = rck_samp(bind_sid(st, b)); break;
        }
        if (t > at) { g_stat_rck[3]++; g_rck_fail = AW_REG_ID; return 0; }
