        if (st == 1 && sh->rf.drv_read[0] && sh->ab_samples != g_pass.samples) return 0;
        if (sh->ab_xok == 2 && (sh->ab_npend != g_npend || g_pend_over || sh->ab_wr != g_wr_epoch || sh->ab_tba != g_tba_gen || sh->ab_sbw != g_sbw_gen)) return 0;
    }
