    if (sh->rf.htab && sh->ab_pgen != g_psnap_gen) return 0;
    if (sh->rf.pool && (sh->ab_pgen != g_psnap_gen || pool) && (g_args_regchk <= 0 || sh->rf.htab)) return 0;
    int pk = sh->rf.pool && (sh->ab_pgen != g_psnap_gen || pool) ? PK_POOL : 0; uint64_t t = 0, m = 0;
