        case NVN_RB_SAMP: return sh->rf.border ? ts : (pk & PK_SAMP) && (sm >> bit & 1);
        case NVN_RB_SAMPI: return sh->rf.border && ts;   // a constant ID: only for the border block
        case NVN_RB_TEXD: case NVN_RB_SAMPD: case NVN_RB_TEXA: case NVN_RB_SAMPA: return ts;
        case NVN_RB_DRV2: return ts && sh->rf.drv_read[2];
        case NVN_RB_DRV0: return (pk & (PK_SSBO | PK_BINST)) && sh->rf.drv_read[0];
        case NVN_RB_SBUFP: return (pk & PK_SSBO) != 0;
        case NVN_RB_CBUF: case NVN_RB_CBSIZE: return (pk & PK_UBO) != 0;
        case NVN_RB_TEXP: case NVN_RB_SAMPP: return (pk & PK_POOL) != 0;   // DM_NVN_ARGS_REGCHK: the pool tables taken again
        default: return 0;   // made from nothing these change (images, c1, support, push; pools but with PK_POOL)
    }
}
// DM_NVN_ARGS_STATS: why a block was encoded in full. A hard change of its stage since its last full encode gives that change's reason (the last one); with none, what else kept its
// block from being reused or patched: base instance, pool table, a uniform slot change on a shader that cannot be patched, or, after only a new pass or program, a block that could not
// outlive it: another submission's, a kind never kept (args_xkind 2), one not kept (a feedback snapshot, a host encoder's), or a write or sample count since (args_xpass_ok)
static uint8_t ast_fresh_why(NvShader *sh, int st, int same, int cross, int xpass) {
    if (!sh->ab_buf) return AW_FIRST;
    if (st == 5) return AW_CS;
    if (passdump() || g_res_check_on) return AW_OTHER;
    if (sh->ast_hgen != g_args_hgen[st]) return g_args_why[st];
    if (g_rck_fail) return g_rck_fail;   // DM_NVN_ARGS_REGCHK: an ID it holds registered since, or kinds it cannot check
    if (same || cross) {
        if (sh->rf.drv_read[0] && sh->ab_binst != g_draw_binst) return AW_BINST;
        if ((sh->rf.pool || sh->rf.htab) && sh->ab_pgen != g_psnap_gen) return AW_PSNAP;
        return AW_UBO;
    }
    if (!xpass) return g_args_swhy[st];
    if (sh->ast_sub != g_sub_serial) return AW_NEWSUB;
    if (!sh->ab_xok) return args_xkind(sh, st) == 2 ? AW_XKIND : AW_NOX;
