static const uint8_t g_ag_of[64] = {   // a binding kind's time group (AG_MISC: C1, SUPPORT, GEOMETRY and any kind not listed)
    [NVN_RB_SAMP] = AG_TEX, [NVN_RB_SAMPT] = AG_TEX, [NVN_RB_SAMPU] = AG_TEX, [NVN_RB_SAMPI] = AG_TEX, [NVN_RB_TEX] = AG_TEX, [NVN_RB_TEXU] = AG_TEX, [NVN_RB_TBUF] = AG_TEX, [NVN_RB_TBUFU] = AG_TEX,
    [NVN_RB_TEXD] = AG_TEX, [NVN_RB_SAMPD] = AG_TEX, [NVN_RB_TEXA] = AG_TEX, [NVN_RB_SAMPA] = AG_TEX, [NVN_RB_BORDER] = AG_TEX,
    [NVN_RB_TEXP] = AG_POOL, [NVN_RB_SAMPP] = AG_POOL, [NVN_RB_TEXH] = AG_POOL, [NVN_RB_SAMPH] = AG_POOL,
    [NVN_RB_CBUF] = AG_CBUF, [NVN_RB_CBSIZE] = AG_CBUF, [NVN_RB_DRV0] = AG_DRV, [NVN_RB_DRV2] = AG_DRV, [NVN_RB_PUSH] = AG_PUSH,
    [NVN_RB_IMG] = AG_STORE, [NVN_RB_IMGU] = AG_STORE, [NVN_RB_SBUFP] = AG_STORE, [NVN_RB_UBOP] = AG_STORE, [NVN_RB_SBUFU] = AG_STORE, [NVN_RB_SBUFQ] = AG_STORE, [NVN_RB_GMEM] = AG_STORE, [NVN_RB_GMEML] = AG_STORE,
