// Time since the last mark goes to the group running, less the texture lookups past the cached view in it, which go to AG_TEXSLOW (inside the span, so never more than it)
static inline void ast_span(uint64_t n, uint64_t t, int g) { uint64_t sl = tl_tex_slow - g_ast.slow0; g_ast.slow0 = tl_tex_slow; g_ast.tg[g] += n - t - sl; g_ast.tg[AG_TEXSLOW] += sl; g_ast.tsg[g] += sl; }
static inline void ast_mark(uint64_t *t, int *g, int ng) { if (ng != *g) { uint64_t n = ast_now(); ast_span(n, *t, *g); *t = n; *g = ng; } }
// The shader's entry in the half of the table being written (open addressing by its address; NULL when its probe run is full: counted)
static ast_key_t *ast_key(NvShader *sh, int st) {
    int w = atomic_load_explicit(&g_ast.kw, memory_order_relaxed) & 1; ast_key_t *t = g_ast.keys[w]; const void *p = (__bridge const void *)sh;
    uint64_t h = ((uint64_t)(uintptr_t)p >> 4) * 0x9E3779B97F4A7C15ull >> 55;   // 9 bits: AK_N
    for (int k = 0; k < AK_PROBE; k++) { ast_key_t *e = &t[(h + (uint64_t)k) % AK_N];
        if (e->sh == p) return e;
        if (e->sh) continue;
