        e->pool = sh->rf.pool != 0; e->htab = sh->rf.htab != 0; e->drv2 = sh->rf.drv_read[2] != 0;
        for (int i = 0; i < sh->rf.nb; i++) { int kd = sh->rf.b[i].kind;
