}
static __attribute__((noinline)) void ast_fresh_end(NvShader *sh, int st, uint8_t w, const unsigned *fx) {
    g_ast.fresh[w]++; for (int i = 0; i < FX_N; i++) g_ast.fx[i] += fx[i];
    if (w == AW_UBO) { int k = 0; for (int i = 0; i < sh->rf.nb && !k; i++) { int c = pk_kclass(sh->rf.b[i].kind); if (c == PKK_NO || (c == PKK_WIDE && g_args_partial <= 0)) k = sh->rf.b[i].kind & 63; } g_ast.ubok[k]++; }
