// A partial patch: its kinds and the texture / sampler bindings it wrote and kept; the stage's hard changes so far are its, not a later full encode's (ast_fresh_why)
enum { PKC_TEX, PKC_SSBO, PKC_BINST, PKC_MIX, PKC_N };   // its time's class: textures and samplers only, storage (with or without the base instance), base instance only, any other mix
static const char *const g_pkc_name[PKC_N] = {"textures/samplers", "storage", "base instance", "mixed or with uniforms"};
static inline int pk_class(int pk) { pk &= ~PK_X; return !(pk & ~(PK_TEX | PK_SAMP)) ? PKC_TEX : !(pk & ~(PK_SSBO | PK_BINST)) ? (pk & PK_SSBO ? PKC_SSBO : PKC_BINST) : PKC_MIX; }
static __attribute__((noinline)) void ast_partial(NvShader *sh, int st, int pk, const unsigned *pn) {
    for (int i = 0; i < 6; i++) g_ast.part[i] += (pk >> i) & 1;
    g_ast.pslot[0] += pn[0]; g_ast.pslot[1] += pn[1];
    sh->ast_hgen = g_args_hgen[st]; sh->ast_sub = g_sub_serial;
}
// encode_args_ timed whole, by how it ended (the counters it moved)
static __attribute__((noinline)) int ast_encode_args(id<MTL4CommandEncoder> en, NvShader *sh, int nvn_stage, int metal_vertex) {
    uint64_t e0 = g_stat_args_enc, r0 = g_stat_args_reuse, p0 = g_stat_args_patch, q0 = g_stat_args_partial, t0 = ast_now();
    int r = encode_args_(en, sh, nvn_stage, metal_vertex);
    uint64_t dt = ast_now() - t0; int k = g_stat_args_enc != e0 ? 0 : g_stat_args_partial != q0 ? 4 : g_stat_args_patch != p0 ? 1 : g_stat_args_reuse != r0 ? 2 : 3;
    g_ast.t[k] += dt; g_ast.n[k]++;
    if (k == 4) { int c = pk_class(g_pk_last); g_ast.pt[c] += dt; g_ast.pn[c]++; }
    return r;
}
// A draw: whether a texture or sampler registration came in since the last one (as the replay sees them: registrations land when the game makes them, draws when they are replayed)
static __attribute__((noinline)) void ast_draw(void) {
    uint64_t ts = atomic_load_explicit(&g_ast_reg_ts, memory_order_relaxed), d = ts - g_ast.draw_ts; g_ast.draw_ts = ts;
    g_ast.draws++; if (d) { g_ast.draws_reg++; g_ast.regs_between += d; }
}
static int encode_args(id<MTL4CommandEncoder> en, NvShader *sh, int nvn_stage, int metal_vertex) {
    int pf = pf_enter(PF_ARGS);   // page-ins by part (PF_ARGS)
    cbs_note(sh); AP_B; int r = __builtin_expect(g_ast_on, 0) ? ast_encode_args(en, sh, nvn_stage, metal_vertex) : encode_args_(en, sh, nvn_stage, metal_vertex); AP_E(3);
    pf_leave(pf); return r;
}
// The resource ID a sampler binding b of stage st holds for sampler ID sid, as the slot path writes it (and a slot table would: bindless-plan.md, one resolver for both): the
// registered sampler, its twin when b corrects a border colour Metal lacks (dmsh_rewrite.py border_emu; the twin's bit and factors go into *bmask / bk), or the dummy. *out: the
// sampler state (the dummy's for none). fx: the fix-ups counted (FX_*); bl: the pass dump's binding line. Caller holds g_rmu
