static struct { const void *t; uint64_t rid; } g_fam_no[1 << 20];
static inline int fam_valid_tid(int tid, __unsafe_unretained id<MTLTexture> t, uint64_t rid) {
    if (!atomic_load_explicit(&g_image_heap_comp_n, memory_order_relaxed)) return 1;
