            else if (g_args_drv > 0 && nvn_stage < 5) { __unsafe_unretained id<MTLBuffer> db = nil; slots[aid] = drv_bank(sh, nvn_stage, bank, &db); USE(db, MTLResourceUsageRead); }   // DM_NVN_ARGS_DRV
            else {
                __unsafe_unretained id<MTLBuffer> db; arena_at at_doff = arena_take_u(DMSH_DRV_SIZE, &db); size_t doff = at_doff.off; uint8_t *d = at_doff.cpu; memset(d, 0, DMSH_DRV_SIZE); g_stat_drv[bank != 0][DB_FULL]++;
                if (bank == 0) { drv_fill_c0(d, nvn_stage); if (nvn_stage == 5) { g_c0_dim_buf = db; g_c0_dim_off = doff + DMSH_C0_DISPATCH; } }
                else drv_fill_c2(d, nvn_stage, sh->rf.dyn, sh->rf.pool ? S.tex_base : 0, sh->rf.pool ? S.samp_base : 0);
