    }
    if (ast) ast_mark(&ast_t, &ast_g, AG_TEX);
    if (sh->rf.border && (!pk || (pk & (PK_TEX | PK_SAMP)))) {   // the border colour block: all zero (the shared zero bank) unless a twin corrects, then its mask and factors (dmsh_abi.h DMSH_BORDER_*)
        int reg = 0, aid = sh->rf.b[sh->rf.border - 1].aid;
        if (!bmask) { slots[aid] = zero_bank_gpu(); USE(zero_bank(), MTLResourceUsageRead); }
        else {
            int n = 32 - __builtin_clz(bmask); __unsafe_unretained id<MTLBuffer> db; arena_at at_doff = arena_take_u(DMSH_BORDER_K + 16 * n, &db); uint8_t *d = at_doff.cpu;
            memset(d, 0, DMSH_BORDER_K); memcpy(d, &bmask, 4); memcpy(d + DMSH_BORDER_K, bk, 16 * n);
            slots[aid] = at_doff.gpu; USE(db, MTLResourceUsageRead);
