    }
    #undef USE
    if (__builtin_expect(g_bl_on, 0) && nvn_stage == 1 && !metal_vertex && (!pk || (pk & (PK_TEX | PK_SAMP)))) { if (ast) ast_mark(&ast_t, &ast_g, AG_BL); bl_note(sh, nvn_stage, slots, pk, pk_tm, pk_sm); }   // DM_NVN_BINDLESS (stage 1)
    if (ast) ast_mark(&ast_t, &ast_g, AG_TAIL);
    if (__builtin_expect(t_pf_sec >= 0, 0) && t_pf_sec != PF_ARGS) { pf_credit(); t_pf_sec = PF_ARGS; }   // back to the arguments' own part for the tail
    os_unfair_lock_unlock(&g_rmu);
    __unsafe_unretained id<MTLBuffer> ab; arena_at at_off = arena_take_u(arg_len, &ab); size_t off = at_off.off;
    memcpy(at_off.cpu, slots, arg_len);
    if (gmem_aid >= 0) gmem_slot_note((uint64_t *)(void *)at_off.cpu + gmem_aid, gml_taken ? (__bridge void *)g_gml_last : NULL);   // the arena arena_alloc took it from (no contents message: see ubo_read)
    bind_args(en, nvn_stage, metal_vertex, ab, at_off.gpu, off, sh->rf.abi);
    if (pk) {   // the pass rule's block from now on; base instance and pool tables as the old block's unless written again, the cross-pass marks as a uniform patch moves them
        sh->ab_buf = ab; sh->ab_gpu = at_off.gpu; sh->ab_off = off; sh->ab_pass = g_pass.serial; sh->ab_gen = g_args_gen[nvn_stage]; sh->ab_ugen = g_args_ugen[nvn_stage]; sh->ab_pkh = g_args_hgen[nvn_stage];
        if (pk & (PK_SSBO | PK_BINST)) sh->ab_binst = g_draw_binst;
        if (pk & PK_POOL) sh->ab_pgen = g_psnap_gen;   // after every pool_gpu of the patch, as a full encode's
        sh->ab_rck = rck0;
        g_args_wrote[nvn_stage] = g_args_seq;
        if (sh->ab_xok) {   // a block the cross-pass rule kept: still one while it is for the pass's own encoder with no same-pass snapshot; a block of copies keeps its older marks
            if (!xpass || (id)en != (id)g_enc || g_ab_nox) sh->ab_xok = 0;
            else { sh->ab_hgen = g_args_hgen[nvn_stage]; sh->ab_samples = g_pass.samples; if (g_ab_snap && sh->ab_xok == 1) { sh->ab_xok = 2; args_xpass_stamp(sh); } } }
        if (__builtin_expect(g_ast_on, 0)) ast_partial(sh, nvn_stage, pk, pk_n);
        g_pk_last = pk; g_stat_args_partial++; g_stat_args_patch++; g_stat_args_xpass += (pk & PK_X) != 0;
        return 1;
    }
    sh->ab_buf = ab; sh->ab_gpu = at_off.gpu; sh->ab_off = off; sh->ab_pass = g_pass.serial; sh->ab_binst = g_draw_binst; sh->ab_pgen = g_psnap_gen; sh->ab_gen = g_args_gen[nvn_stage]; sh->ab_ugen = g_args_ugen[nvn_stage]; g_args_wrote[nvn_stage] = g_args_seq;
    sh->ab_pkh = g_args_hgen[nvn_stage]; sh->ab_rck = rck0;
    // For the cross-pass rule (args_xpass_ok): only a block written for the pass's own encoder (the host's capture and emulation encoders move the hard generation around theirs anyway)
    sh->ab_xok = 0;
    if (xpass && (id)en == (id)g_enc && !g_ab_nox && !g_res_check_on) { int xk = args_xkind(sh, nvn_stage);
        if (xk != 2) { sh->ab_xok = g_ab_snap || xk == 3 ? 2 : 1; sh->ab_sub = g_sub_serial; sh->ab_hgen = g_args_hgen[nvn_stage]; sh->ab_samples = g_pass.samples; if (sh->ab_xok == 2) args_xpass_stamp(sh); } }
    #undef ARGS_XPASS_TAKE
    if (ast) { ast_span(ast_now(), ast_t, ast_g); ast_fresh_end(sh, nvn_stage, ast_w, fx); }
    g_stat_args_enc++;
    return 1;
}
static id<MTLBuffer> g_quad_ib; static uint64_t g_quad_gpu;
static id<MTLBuffer> g_fan_ib; static uint64_t g_fan_gpu;   // non-indexed triangle fans: shared indices (0, i, i+1), base vertex = first
#define SHARED_IB_N 65536   // quads / fan triangles the shared index buffers cover
static void quad_ib_make(void) {   // Quads: shared indices 0,1,2,0,2,3
    if (g_quad_ib) return;
    uint32_t n = SHARED_IB_N; uint32_t *ix = malloc(n * 6 * 4);
    for (uint32_t q = 0; q < n; q++) { uint32_t b = q * 4; uint32_t v[6] = {b, b + 1, b + 2, b, b + 2, b + 3}; memcpy(ix + q * 6, v, 24); }
    g_quad_ib = [g_dev newBufferWithBytes:ix length:n * 24 options:MTLResourceStorageModeShared]; g_quad_gpu = g_quad_ib.gpuAddress; res_add(g_quad_ib); free(ix);
}
static void fan_ib_make(void) {
    if (g_fan_ib) return;
    uint32_t n = SHARED_IB_N; uint32_t *ix = malloc(n * 12);
    for (uint32_t i = 0; i < n; i++) { uint32_t v[3] = {0, i + 1, i + 2}; memcpy(ix + i * 3, v, 12); }
    g_fan_ib = [g_dev newBufferWithBytes:ix length:n * 12 options:MTLResourceStorageModeShared]; g_fan_gpu = g_fan_ib.gpuAddress; res_add(g_fan_ib); free(ix);
}
static id<MTL4RenderCommandEncoder> rp_begin(void);
// ---------- Replay position: the lookaheads (cs_hoist_try, lc, mdx_prescan, ixc / wide scans, geometry runs) walk on from here with op_next ----------
static const uint8_t *g_exec_next;   // The op following the current draw in the replay
static const uint8_t *g_exec_cur;    // The current draw's own op (set with g_exec_next)
static const uint8_t *g_ret[16]; static int g_ret_n;   // Call return stack of the replay (at OP_CALL the caller's next op is pushed)
static const uint64_t *g_rest; static int g_nrest;      // Handles in this submission still to be replayed after the current handle
void mtl_exec_rest(const uint64_t *h, int n) { g_rest = h; g_nrest = n; }
typedef struct { const uint8_t *p, *ret[8]; int ret_n, rest_i, bad; } op_cursor;
static int op_next(op_cursor *c, const uint8_t **out, op_hdr *oh, const void **oa) {
    for (int guard = 0; guard < 1000000; guard++) {
        if (!c->p) return 0;
        op_hdr h; memcpy(&h, c->p, sizeof h); const void *a = c->p + 8;
        switch (h.op) {
            // The live draws and their argument addresses are resolved at replay. A speculative scan cannot move work across this range.
            case OP_MULTI_DRAW: c->bad = 1; return 0;
            case OP_END:
                if (c->ret_n) c->p = c->ret[--c->ret_n];
                else if (c->rest_i < g_nrest) c->p = (const uint8_t *)g_rest[c->rest_i++];
                else { c->p = NULL; return 0; }
                continue;
            case OP_JUMP: memcpy(&c->p, a, 8); continue;
            case OP_CALL: { uint64_t t; memcpy(&t, a, 8); if (c->ret_n >= 8) { c->bad = 1; return 0; }
                c->ret[c->ret_n++] = c->p + h.size; c->p = (const uint8_t *)t; continue; }
            default: break;
        }
        const uint8_t *p = c->p; c->p += h.size;
        if (out) *out = p; if (oh) *oh = h; if (oa) *oa = a; return 1;
    }
    c->bad = 1; return 0;
}
// ---------- Stores no later operation reads (DM_NVN_DS_DEAD_STORE, rule b; DM_NVN_MSAA_RESOLVE_ONLY, rule c) ----------
// An attachment's store is only needed if something reads those bytes before they are overwritten whole. From the replay's position (the op being replayed, g_exec_cur, which ended the
// pass or is the resolve), ls_dead_scan walks the rest of the submission's recorded stream (as ldc_scan does) and proves the store dead only when a clear of the same subresource through
// the same view, over the whole level and every plane asked for (depth and stencil: depth mask; stencil mask 0xff; colour: all four channels), comes before anything that could read
// it. Between, only state, target and buffer-update operations may come: any draw, dispatch, texture copy, clear of a texture, event, fence, query, conditional rendering, or the end
// of the submission ends the scan with the store kept; so does a clear drawn as a triangle (a scissored or masked one opens a draw pass that loads its targets), a clear of other
// targets while the texture is attached among them, a target set that names memory overlapping the texture under another serial or view, and a buffer update over its guest
// memory. A clear found waits as a load-action Clear (lazy clear) or lands in a clear-only pass of its own, which clears the whole attachment (the pass-of-its-own rule for a target
// larger than the pass), so every byte the store would have written is overwritten before any read. Not with pass_alternate <W>x<H> shapes on (a kept frame turns a later Clear into a Load),
// not into window textures (a pass on them may cover only the presented crop, DM_NVN_WIN_AREA), not while conditional rendering may skip the clear (g_rc_skip). planes: 1 depth, 2
// stencil (color 0) or 1 the colour (color 1); returns the planes proven dead
static int ls_overlap(const tex_t *t, uint64_t ser, uint64_t mem, uint64_t msize) {
    if (!t) return 0;
    if (t->serial == ser) return 1;
    uint64_t a = (uint64_t)(uintptr_t)t->mem, n = t->has_layout && t->L.size ? t->L.size : 1;
    return a && mem && a < mem + (msize ? msize : 1) && mem < a + n;
}
static int ls_rt_overlap(const p_set_rt *rt, uint64_t ser, uint64_t mem, uint64_t msize) {
    if (ls_overlap(rt->depth, ser, mem, msize)) return 1;
    for (int k = 0; k < rt->n && k < 8; k++) if (ls_overlap(rt->color[k], ser, mem, msize)) return 1;
    return 0;
}
static int ls_range_hits(uint64_t a, uint64_t n, uint64_t mem, uint64_t msize) { return mem && n && a < mem + (msize ? msize : 1) && mem < a + n; }
static int ls_scissor_full(const tex_t *t, const view_t *v, int has_v, int has_sc, const p_scissor *sc) {
    NSUInteger level = has_v && v->set_levels ? v->base_level : 0;
    uint32_t w, h; tex_lsize(t, (unsigned)MIN(level, 32ul), &w, &h, NULL);
    return !has_sc || (sc->x <= 0 && sc->y <= 0 && (int64_t)sc->x + sc->w >= (int64_t)w && (int64_t)sc->y + sc->h >= (int64_t)h);
}
static int ls_dead_scan(uint64_t ser, int has_v, const view_t *v, uint64_t mem, uint64_t msize, int color, int planes, int skip_first) {
    if (!g_exec_cur || g_ret_n > 8 || g_rc_skip || (pa_on() & 1)) return 0;   // <W>x<H> shapes (a cube shape's pass has no depth and draws into a cube, never a multisample texture)
    g_dsd_scans++;
    op_cursor cur = {.p = g_exec_cur}; for (int k = 0; k < g_ret_n; k++) cur.ret[cur.ret_n++] = g_ret[k];
    p_set_rt rt = R.rt; int has_sc = R.has_sc; p_scissor sc = R.sc;
    const uint8_t *p; op_hdr h; const void *a;
    for (int n = 0; n < 4096; n++) {
        if (!op_next(&cur, &p, &h, &a)) return 0;   // the submission's end (or a stream the scan cannot follow): kept
        g_dsd_scan_ops++;
        if (skip_first && !n) continue;   // the op being replayed (the resolve's own copy)
        switch (h.op) {
            case OP_SET_RT: rt = *(const p_set_rt *)a; break;
            case OP_SCISSOR: sc = *(const p_scissor *)a; has_sc = 1; break;
            case OP_CLEAR_DS: { const p_clear_ds *c = a; unsigned smk = (unsigned)c->stencil_mask & 0xff;
                if (!c->depth_mask && !smk) break;
                if (!ls_rt_overlap(&rt, ser, mem, msize)) break;   // other targets
                if (color || !rt.depth || rt.depth->serial != ser || rt.has_dview != has_v || (has_v && memcmp(&rt.dview, v, sizeof *v))) return 0;
                for (int k = 0; k < rt.n && k < 8; k++) if (ls_overlap(rt.color[k], ser, mem, msize) || (rt.color[k] && (rt.color[k]->d.flags & NVN_TEXTURE_FLAGS_DISPLAY))) return 0;
                if (!ls_scissor_full(rt.depth, &rt.dview, rt.has_dview, has_sc, &sc) || (smk && smk != 0xff)) return 0;   // drawn as a triangle in a pass that loads it
                return planes & ((c->depth_mask ? 1 : 0) | (smk == 0xff ? 2 : 0)); }
            case OP_CLEAR_COLOR: { const p_clear_color *c = a;
                if (c->index < 0 || c->index >= rt.n || c->index >= 8 || !rt.color[c->index]) break;
                if (!ls_rt_overlap(&rt, ser, mem, msize)) break;
                const tex_t *t = rt.color[c->index];
                if (!color || t->serial != ser || rt.has_cview[c->index] != has_v || (has_v && memcmp(&rt.cview[c->index], v, sizeof *v))) return 0;
                if (ls_overlap(rt.depth, ser, mem, msize) || (t->d.flags & NVN_TEXTURE_FLAGS_DISPLAY)) return 0;
                for (int k = 0; k < rt.n && k < 8; k++) if (k != c->index && ls_overlap(rt.color[k], ser, mem, msize)) return 0;
                if ((c->mask & 0xf) != 0xf || !ls_scissor_full(t, &rt.cview[c->index], rt.has_cview[c->index], has_sc, &sc)) return 0;
                return planes & 1; }
            case OP_UPDATE_UB: { uint64_t d, nb; memcpy(&d, a, 8); memcpy(&nb, (const uint8_t *)a + 8, 8); if (ls_range_hits(d, nb, mem, msize)) return 0; break; }
            case OP_COPY_B2B: { uint64_t s_, d, nb; memcpy(&s_, a, 8); memcpy(&d, (const uint8_t *)a + 8, 8); memcpy(&nb, (const uint8_t *)a + 16, 8);
                if (ls_range_hits(s_, nb, mem, msize) || ls_range_hits(d, nb, mem, msize)) return 0; break; }
            case OP_CLEAR_BUF: { const p_clear_buf *cb = a; if (ls_range_hits(cb->addr, cb->size, mem, msize)) return 0; break; }
            case OP_BEGIN: case OP_BIND_PROGRAM: case OP_BIND_STATE: case OP_BIND_VATTR: case OP_BIND_VSTREAM: case OP_BIND_VBUF: case OP_BIND_VBUF1:
            case OP_BIND_UBO: case OP_BIND_UBO_SMALL: case OP_BIND_SSBO: case OP_BIND_TEX: case OP_BIND_TEX1: case OP_BIND_SAMP: case OP_BIND_IMG: case OP_STENCIL:
            case OP_POLY_OFFSET: case OP_VIEWPORTS: case OP_DEPTH_RANGE: case OP_DEPTH_CLAMP: case OP_DEPTH_BOUNDS: case OP_LINE_WIDTH: case OP_VP_SWIZZLE: case OP_BLEND_COLOR: case OP_ALPHA_REF: case OP_PUSH_CONST:
            case OP_COPY_STRIDE: case OP_TF_BIND: case OP_TF_STATE: case OP_RAST_DISCARD: case OP_PRIM_RESTART: case OP_BARRIER: case OP_SET_TEX_POOL: case OP_SET_SAMP_POOL: break;
            default: return 0;   // a draw, dispatch, texture copy or clear, event, query, conditional rendering, or anything else
        }
    }
    return 0;
}
static void draw(const p_draw *dw, const p_draw_idx *di);
static void sd_need(sd_att *t, int why) { if (!t->state) { t->state = 1; t->why = (uint8_t)why; } }   // why: 1 a draw reads it as a texture 2 as an attachment, drawn before cleared 3 copy 4 texture clear 5 scanned to the end undecided 6 no start point / index unavailable
static void sd_finish(void) {
    if (!g_nsd) return;
    // Unchanged, loaded attachments already have their content in memory. Their proof depends only on writes in this pass, independently of future bindless readers or the optional lookahead.
    for (int i = 0; i < g_nsd; i++) sd_need(&g_sd[i], 6);   // Pass ended outside the list / index unavailable: always write back
    // Rule (b): depth / stencil planes the pass wrote whose bytes a whole clear overwrites before any read (ls_dead_scan; eligibility at rp_begin_ex_, dse)
    int dsd_dead = 0;
    { int want = 0; const sd_att *ds = NULL;
        for (int i = 0; i < g_nsd; i++) { const sd_att *t = &g_sd[i]; if (t->depth && t->dse && !(udc_on() && t->load && !t->wrote)) { want |= t->depth; ds = t; } }
        if (want) dsd_dead = ls_dead_scan(ds->ser, ds->has_v, &ds->v, ds->mem, ds->msize, 0, want, 0); }
    // A combined depth-stencil family attachment whose cross-size load was rewritten to a clear on one plane (fam_san) while the other plane is stored: both planes are stored, so both
    // hold valid compressed blocks of the size that becomes the live one
    int ds_store = 0; void *ds_tex = NULL;
    for (int i = 0; i < g_nsd; i++) { const sd_att *t = &g_sd[i]; if (t->depth && t->fam_san) ds_tex = t->fam_tex; }
    if (ds_tex) for (int i = 0; i < g_nsd; i++) { const sd_att *t = &g_sd[i]; int ud = udc_on() && t->load && !t->wrote;
        if (t->depth && t->fam_tex == ds_tex && !ud && !((dsd_dead >> (t->depth - 1) & 1))) ds_store = 1; }
    for (int i = 0; i < g_nsd; i++) {
        sd_att *t = &g_sd[i]; int udc_dead = udc_on() && t->load && !t->wrote;
        int fam_keep = ds_store && t->depth && t->fam_tex == ds_tex;
        int dsd = t->depth && (dsd_dead >> (t->depth - 1) & 1) && !udc_dead && !fam_keep;
        // A loaded color tile with no raster output or clear holds only the old memory contents. Storing it can overwrite image writes to the same texture
        // (Dark Souls' image-only AO pass). This is required for correctness even when store optimizations are disabled; mixed tile/image writers retain their store.
        int img_dead = t->depth == 0 && t->load && t->img && !t->rast;
