void mtl_fb_dsnap_stats(uint64_t s[5]) { s[0] = g_fb_dsnap_saved; s[1] = g_fb_dsnap_saved_bytes; s[2] = g_fb_dsnap_kept; s[3] = g_fb_dsnap_copies; s[4] = g_fb_dsnap_copy_bytes; }
static int g_fb_dsnap_m = -1;   // DM_NVN_FB_DSNAP (a unit test may set it)
static int fb_dsnap_on(void) {
    if (g_fb_dsnap_m < 0) { const char *e = getenv("DM_NVN_FB_DSNAP"); g_fb_dsnap_m = !(e && !strcmp(e, "0")); if (!g_fb_dsnap_m) MLOG("DM_NVN_FB_DSNAP=0: a draw that samples a depth plane its pass wrote ends the pass each time"); }
