        if (g_fb_tile_draws == 1 || g_fb_tile_draws == 1000 || g_fb_tile_draws % 100000 == 0)
            MLOG("same-pass feedback sampling: draw #%llu reads its attachments from the tile, %llu snapshots so far (frame %llu, shader %s, attachments %#x)", (unsigned long long)g_fb_tile_draws, (unsigned long long)g_fb_count,
                 (unsigned long long)atomic_load(&g_cur_frame), fs->key, g_fb_tdesc.fbmask); }
}
// ---------- Indirect draws Metal cannot take as they are ----------
// Buffer textures below the alignment that a draw or dispatch reads: copied on the GPU before it (see tba_ent). Whether a shader reads buffer textures at all is decided once (tb_reads)
static int tb_reads(NvShader *x) {
    if (!x->tb_reads) { int any = 0;
        for (int i = 0; i < x->rf.nb && !any; i++) { const nvn_rbind *b = &x->rf.b[i];
            any = b->kind == NVN_RB_TBUF || b->kind == NVN_RB_TBUFU || ((b->kind == NVN_RB_TEX || b->kind == NVN_RB_TEXU || b->kind == NVN_RB_TEXD) && (b->dtt == (uint8_t)MTLTextureTypeTextureBuffer
                  || ((b->f1d || b->kind == NVN_RB_TEXU) && b->dtt == (uint8_t)MTLTextureType2D))); }
        x->tb_reads = any ? 2 : 1; }
    return x->tb_reads == 2;
}
typedef struct { __unsafe_unretained id<MTLTexture> root; uint64_t lo; size_t len, need; uint32_t lead, bpb; } tba_job;   // lo: the guest address of the bytes, len: what the copy takes, need: what it holds (rows)
// One texture ID a binding reads (rows: as 2D rows of a wrapped 1D fetch, else as a texture buffer): a job when it is a buffer texture below the alignment with no valid copy as long
// as it needs. Caller holds g_rmu
static int tba_want(int tid, int rows, tba_job *jobs, int n) {
    if (tid <= 0 || tid >= g_ntreg || !g_treg[tid].ok || n >= TBA_MAX) return n;
    void *tv = NULL; (void)tex_fast_rid(tid, &tv); __unsafe_unretained id<MTLTexture> t = (__bridge id<MTLTexture>)tv;
    if (!t || t.textureType != MTLTextureTypeTextureBuffer) return n;
    id<MTLTexture> root = t; while (root.parentTexture) root = root.parentTexture;
    uint32_t lead = tbuf_lead(tid, t);   // its view starts this many elements before its own (tex_buffer); 0: aligned, nothing to copy
    if (!lead || !root.buffer) return n;
    const tex_t *tt = &g_treg[tid].t; int bw, bh; uint32_t bpb = (uint32_t)nvn_fmt_bpb(tt->d.format, &bw, &bh), w, h, row;
    if (!bpb || !tt->mem) return n;
    NSUInteger al = tbuf_al(root.pixelFormat), off = root.bufferOffset + (NSUInteger)lead * bpb;   // the texture's own bytes
    if (off & 3) return n;   // not 4-byte aligned, which a buffer copy cannot take (the CPU copy stays)
    size_t need = ((size_t)tt->d.width * bpb + al - 1) / al * al;   // its own elements, rounded up to the alignment
    if (rows && bw == 1 && bh == 1 && nvn_tbuf_rows(tt->d.width, bpb, (uint32_t)al, &w, &h, &row) && (size_t)row * h > need) need = (size_t)row * h;
    if (!need) return n;
    if (off >= root.buffer.length) return n;
    uint64_t avail = root.buffer.length - off; size_t len = (size_t)MIN((uint64_t)need, avail) & ~(size_t)3;   // past the pool buffer: undefined reads anyway (zeros here)
    if (!len) return n;
    tba_ent *e = tba_find(root); if (e && e->need_al >= need) return n;
    for (int i = 0; i < n; i++) if (jobs[i].root == root) { if (need > jobs[i].need) { jobs[i].need = need; jobs[i].len = len; } return n; }
    jobs[n] = (tba_job){root, (uint64_t)(uintptr_t)tt->mem, len, need, lead, bpb}; return n + 1;
}
static int tba_collect(NvShader *x, int stage, tba_job *jobs, int n) {   // caller holds g_rmu; mirrors the bindings of encode_args_ that read buffer textures
    for (int i = 0; i < x->rf.nb; i++) { const nvn_rbind *b = &x->rf.b[i]; int reg = b->reg;
        if (b->tbx && (b->kind == NVN_RB_TBUF || b->kind == NVN_RB_TBUFU || b->kind == NVN_RB_TEXD || b->kind == NVN_RB_TEXA)) continue;   // read in place through the offset table (tbuf_lead)
        if (b->kind == NVN_RB_TBUF || b->kind == NVN_RB_TBUFU)
            n = tba_want(b->kind == NVN_RB_TBUFU ? ubo_tex_id(ubo_bind_handle(stage, b)) : (int)(tex_slot_h(S.tex[stage], S.img[stage], reg) & 0xfffff), 0, jobs, n);   // the complete handle, as encode_args_ binds it
        else if (b->kind == NVN_RB_TEXU && b->n) { if (b->dtt == (uint8_t)MTLTextureTypeTextureBuffer) for (int k = 0; k < b->n; k++) n = tba_want(ubo_tex_id(ubo_handle(stage, reg, b->off + 8 * k)), 0, jobs, n); }
        else if (b->kind == NVN_RB_TEX || b->kind == NVN_RB_TEXU) {
            int tid = b->kind == NVN_RB_TEXU ? ubo_tex_id(ubo_bind_handle(stage, b)) : (int)(tex_slot_h(S.tex[stage], S.img[stage], reg) & 0xfffff);
            if (b->dtt == (uint8_t)MTLTextureTypeTextureBuffer) n = tba_want(tid, 0, jobs, n);
            else if ((b->f1d || b->kind == NVN_RB_TEXU) && b->dtt == (uint8_t)MTLTextureType2D) n = tba_want(tid, 1, jobs, n);
        } else if (b->kind == NVN_RB_TEXD && b->dtt == (uint8_t)MTLTextureTypeTextureBuffer)
            for (int k = 0; k < b->n && k < 128; k++) { uint64_t hk = S.tex[stage][k] ? S.tex[stage][k] : S.tex[stage][NVN_SEPTEX_SLOT0 + k]; n = tba_want((int)(hk & 0xfffff), 0, jobs, n); }
    }
    return n;
}
static void tba_prepare_(NvShader *const *sh, int nsh, int compute);
static void tba_prepare(NvShader *const *sh, int nsh, int compute) { int pf = pf_enter(PF_TBA); tba_prepare_(sh, nsh, compute); pf_leave(pf); }   // page-ins by part (PF_TBA)
static void tba_prepare_(NvShader *const *sh, int nsh, int compute) {
    if (!atomic_load_explicit(&g_tb_unaligned, memory_order_relaxed) || !tba_on()) return;
    int any = 0; for (int k = 0; k < nsh; k++) if (sh[k] && tb_reads(sh[k])) any = 1;
    if (!any) return;
    tba_job jobs[TBA_MAX]; int n = 0;
    rmu_lock();
    tba_drop_stale();
    for (int k = 0; k < nsh; k++) if (sh[k] && tb_reads(sh[k])) n = tba_collect(sh[k], compute ? 5 : k, jobs, n);
    os_unfair_lock_unlock(&g_rmu);
    if (!n) return;
    if (g_enc) { g_tba_splits++; PD("M %llu buffer texture aligned copy on the GPU: render pass split here", g_stat_pass); rp_end(); }
    for (int j = 0; j < n; j++) {
        void *mb; uint64_t mo;
        if (!mtl_addr(jobs[j].lo, jobs[j].len, &mb, &mo) || (mo & 3)) continue;   // the bytes in their pool, for this submission (residency)
        int slot = -1; for (int i = 0; i < g_tba_n; i++) if (g_tba[i].root == jobs[j].root) slot = i;
        if (slot < 0) { if (g_tba_n == TBA_MAX) { static int full; if (!full++) MLOG("[RED] buffer textures below the alignment: more than %d copied before one draw; the rest are copied on the CPU", TBA_MAX); break; } slot = g_tba_n++; }
        NSUInteger al = tbuf_al(jobs[j].root.pixelFormat);
        id<MTLBuffer> ab = nil; size_t ao = arena_alloc(jobs[j].need + (al > 256 ? al : 0), &ab); if (!ab) continue;
        ao = (ao + al - 1) / al * al;
        id<MTL4ComputeCommandEncoder> e = blit();   // ordered after every copy or dispatch before it in this encoder, and opened behind a queue barrier
        enc_b_copy_buffer(e, (__bridge id<MTLBuffer>)mb, (NSUInteger)mo, ab, ao, jobs[j].len);
        if (jobs[j].need > jobs[j].len) [e fillBuffer:ab range:NSMakeRange(ao + jobs[j].len, (jobs[j].need - jobs[j].len + 3) & ~(size_t)3) value:0];
        g_tba[slot] = (tba_ent){jobs[j].root, g_sub_serial, g_wr_epoch, g_tba_gen, jobs[j].lo, jobs[j].lo + jobs[j].len, g_sbw_gen, g_npend, ab, ao, jobs[j].len}; g_tba[slot].lead = jobs[j].lead; g_tba[slot].bpb = jobs[j].bpb; g_tba[slot].need_al = jobs[j].need;
        g_tba_copies++; g_tba_bytes += jobs[j].len;
        if (g_tba_copies == 1 || g_tba_copies % 100000 == 0) MLOG("buffer texture at pool offset %#lx (not a multiple of the %lu-byte alignment), read through a binding with no offset table entry: copied on the GPU before the draw or dispatch that reads it (%zu bytes; %llu copies so far)",
                                                                   (unsigned long)(jobs[j].lo), (unsigned long)al, jobs[j].len, (unsigned long long)g_tba_copies);
    }
}
void mtl_tba_stats(uint64_t *copies, uint64_t *bytes, uint64_t *splits, uint64_t *cpu) { *copies = g_tba_copies; *bytes = g_tba_bytes; *splits = g_tba_splits; *cpu = g_tba_cpu; }
// Quads and triangle fans (DrawArraysIndirect), and indexed quads / fans / 8-bit indices (DrawElementsIndirect). The {count, instances, first, ...} record is usually written by the GPU earlier
// in the frame (Hyrule Warriors: Age of Calamity draws GPU-driven effects as indirect quads in its first battle), so the CPU cannot expand it at replay. A compute pass converts each record into
// MTLDrawIndexedPrimitivesIndirectArguments in the frame arena, and the draw becomes an indexed indirect draw: arrays index the shared g_quad_ib / g_fan_ib with first as the base vertex,
// indexed ones are expanded into a 32-bit list of at most IXC_CAP indices. The compute pass cannot run inside a render pass. When the first such draw is met, ixc_run converts it and every
// such draw after it up to the next buffer write outside a render pass (copy, update / fill, texture → buffer, dispatch: they bump g_wr_epoch), so each record is read after its last writer
// and the later draws find their conversion. Only a draw met inside an open render pass with no conversion yet splits that pass.
#define IXC_MAX 128
#define IXC_CAP (3 * 16384)
typedef struct { uint64_t ind, ibuf; int32_t prim, itype; uint64_t args, ixb; uint32_t ixlen; } ixc_ent;   // args 0: the record could not be converted
static ixc_ent g_ixc[IXC_MAX]; static int g_ixc_n; static uint64_t g_ixc_epoch, g_ixc_sub, g_ixc_runs, g_ixc_splits;
// The kernels: dm/gfx/msl/ixc.metal
static int ixc_wanted(const p_draw *dw, const p_draw_idx *di) {
    if (dw) return dw->ind && (dw->prim == 6 || dw->prim == 7);
    return di->ind && (di->prim == 6 || di->prim == 7 || di->itype == 0);
}
static const ixc_ent *ixc_find(const p_draw *dw, const p_draw_idx *di) {
    if (g_ixc_epoch != g_wr_epoch || g_ixc_sub != g_sub_serial) return NULL;
    uint64_t ind = dw ? dw->ind : di->ind, ib = dw ? 0 : di->ibuf; int prim = dw ? dw->prim : di->prim, it = dw ? -1 : di->itype;
    for (int i = 0; i < g_ixc_n; i++) if (g_ixc[i].ind == ind && g_ixc[i].ibuf == ib && g_ixc[i].prim == prim && g_ixc[i].itype == it) return &g_ixc[i];
    return NULL;
}
static void ixc_take(const p_draw *dw, const p_draw_idx *di) {
    if (g_ixc_n < IXC_MAX && !ixc_find(dw, di)) g_ixc[g_ixc_n++] = (ixc_ent){dw ? dw->ind : di->ind, dw ? 0 : di->ibuf, dw ? dw->prim : di->prim, dw ? -1 : di->itype, 0, 0, 0};
}
static void ixc_run(const p_draw *dw, const p_draw_idx *di) {
    static id<MTLComputePipelineState> ps[2]; static id<MTL4ArgumentTable> at; static int failed;
    if (failed) return;
    if (!at) { NSError *e = nil; id<MTLLibrary> lib = host_lib("ixc", &e);
        for (int k = 0; k < 2 && lib; k++) ps[k] = host_cps(lib, k ? @"ixc_expand" : @"ixc_arrays", nil, &e);
        MTL4ArgumentTableDescriptor *ad = [MTL4ArgumentTableDescriptor new]; ad.maxBufferBindCount = 1; at = ps[0] && ps[1] ? rec_table([g_dev newArgumentTableWithDescriptor:ad error:&e]) : nil;
        if (!at) { failed = 1; MLOG("[RED] indirect draw conversion: cannot create the compute pipeline %s (indirect draws of quads / fans / 8-bit indices are skipped)", e.localizedDescription.UTF8String); return; } }
    if (g_ixc_epoch != g_wr_epoch || g_ixc_sub != g_sub_serial || g_ixc_n > IXC_MAX - 8) { g_ixc_n = 0; g_ixc_epoch = g_wr_epoch; g_ixc_sub = g_sub_serial; }
    int n0 = g_ixc_n; ixc_take(dw, di);
    if (g_exec_next && g_ret_n <= 8) {   // Later draws in replay order (current list → callers → the rest of this submission), up to the next buffer write
        op_cursor cur = {.p = g_exec_next, .ret_n = g_ret_n}; memcpy(cur.ret, g_ret, sizeof(*g_ret) * (size_t)g_ret_n);
        const uint8_t *q; op_hdr h; const void *a;
        for (int guard = 0; guard < 200000 && g_ixc_n < IXC_MAX && op_next(&cur, &q, &h, &a); guard++) {
            if (h.op == OP_DISPATCH || h.op == OP_COPY_B2B || h.op == OP_UPDATE_UB || h.op == OP_CLEAR_BUF || h.op == OP_COPY_T2B) break;
            p_draw dt; p_draw_idx it; const p_draw *d = h.op == OP_DRAW ? draw_rec(a, h.size, &dt) : NULL; const p_draw_idx *x = h.op == OP_DRAW_IDX ? draw_idx_rec(a, h.size, &it) : NULL;
            if (d && ixc_wanted(d, NULL)) ixc_take(d, NULL);
