        MTL4ArgumentTableDescriptor *ad = [MTL4ArgumentTableDescriptor new]; ad.maxBufferBindCount = 1; at = ps ? rec_table([g_dev newArgumentTableWithDescriptor:ad error:&e]) : nil;
        if (!at) { failed = 1; MLOG("[RED] indirect-count multi-draw masking: cannot create the compute pipeline %s (those draws wait for the GPU)", e.localizedDescription.UTF8String); return; } }
    if (g_mdx_ep != g_mdx_epoch || g_mdx_sub != g_sub_serial || g_mdx_n > MDX_SLOTS / 4) { g_mdx_tag++; g_mdx_n = 0; g_mdx_ep = g_mdx_epoch; g_mdx_sub = g_sub_serial; g_mdx_wr = ~0ull; }
    enum { QMAX = MDX_SLOTS / 4 };
    static struct { mdx_ent *e; uint32_t i, words; } q[QMAX]; int nq = 0;
    uint64_t lo = ~0ull, hi = 0;   // the hull of the records and counts taken, for the uniform update check
    #define MDX_TAKE(IND, CNT, I, W) do { mdx_ent *e_ = mdx_slot((IND), (CNT)); if (e_->tag != g_mdx_tag && nq < QMAX) { *e_ = (mdx_ent){(IND), (CNT), 0, g_mdx_tag}; g_mdx_n++; \
        q[nq].e = e_; q[nq].i = (uint32_t)(I); q[nq++].words = (W); lo = MIN(lo, MIN((IND), (CNT))); hi = MAX(hi, MAX((IND) + 4 * (W), (CNT) + 4)); } } while (0)
    if (dw && dw->prim == DM_PRIM_MESH_TASKS) MDX_TAKE(dw->ind, dw->ind, DMSH_MESH_GRID, 0); else if (dw) MDX_TAKE(dw->ind, dw->mdi_cnt, dw->mdi_i, 4); else if (di) MDX_TAKE(di->ind, di->mdi_cnt, di->mdi_i, 5);   // words 0: an indirect mesh draw, keyed by its record alone (i: the mesh grid's limit, mdx.metal); neither: mdx_prescan, only the draws after this one
    if (g_mdx_range && (dw || di)) {
        const p_multi_draw *m = g_mdx_range;
        for (int i = (dw ? dw->mdi_i : di->mdi_i) + 1; i < m->max && nq < QMAX; i++) {
            uint64_t ind = m->ind + (uint64_t)i * (uint64_t)m->stride;
            MDX_TAKE(ind, m->cnt, i, dw ? 4u : 5u);
        }
    } else if (g_exec_next && g_ret_n <= 8) {   // later draws in replay order (current list → callers → the rest of this submission)
        op_cursor cur = {.p = g_exec_next, .ret_n = g_ret_n}; memcpy(cur.ret, g_ret, sizeof(*g_ret) * (size_t)g_ret_n);
        const uint8_t *p; op_hdr h; const void *a;
        for (int guard = 0; guard < 200000 && nq < QMAX && op_next(&cur, &p, &h, &a); guard++) {
            if (h.op == OP_DISPATCH || h.op == OP_COPY_B2B || h.op == OP_CLEAR_BUF || h.op == OP_COPY_T2B) break;
            if (h.op == OP_UPDATE_UB) { uint64_t d, n; memcpy(&d, a, 8); memcpy(&n, (const uint8_t *)a + 8, 8);
                int hit = 0; for (int k = 0; d < hi && lo < d + n && k < nq && !hit; k++) { const mdx_ent *e = q[k].e; hit = (d < e->ind + 4 * q[k].words && e->ind < d + n) || (d < e->cnt + 4 && e->cnt < d + n); }
                if (hit) { g_mdx_stop = p; break; } continue; }
            p_draw dt; p_draw_idx it; const p_draw *d = h.op == OP_DRAW ? draw_rec(a, h.size, &dt) : NULL; const p_draw_idx *x = h.op == OP_DRAW_IDX ? draw_idx_rec(a, h.size, &it) : NULL;
            if (d && d->prim == DM_PRIM_MESH_TASKS && d->ind) MDX_TAKE(d->ind, d->ind, DMSH_MESH_GRID, 0);
            else if (d && mdx_wanted(d, NULL)) MDX_TAKE(d->ind, d->mdi_cnt, d->mdi_i, 4);
            else if (x && mdx_wanted(NULL, x)) MDX_TAKE(x->ind, x->mdi_cnt, x->mdi_i, 5);
        }
    }
    #undef MDX_TAKE
    if (!nq) return;
    if (g_enc) { g_mdx_splits++; PD("M %llu indirect-count multi-draw masking: render pass split here", g_stat_pass); rp_end(); }
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    typedef struct { uint64_t rec, cnt, out; uint32_t i, words; } mjob;
    int nj = (nq + 63) & ~63;
    id<MTLBuffer> ab; size_t ao = arena_alloc((size_t)nj * sizeof(mjob) + (size_t)nq * 32, &ab);   // the jobs (padded to whole threadgroups), then the copies 32 bytes apart
    mjob *j = (mjob *)((uint8_t *)ab.contents + ao); uint64_t og = ab.gpuAddress + ao + (uint64_t)nj * sizeof(mjob);
    memset(j, 0, (size_t)nj * sizeof(mjob));
    for (int k = 0; k < nq; k++) { mdx_ent *e = q[k].e; void *mb; uint64_t mo, rg, cg;
        if (!mtl_gpu_addr(e->ind, 4 * (q[k].words ? q[k].words : 2), &mb, &mo, &rg) || !mtl_gpu_addr(e->cnt, 4, &mb, &mo, &cg)) continue;
        e->out = og + 32 * (uint64_t)k; j[k] = (mjob){rg, cg, e->out, q[k].i, q[k].words}; }
    id<MTL4ComputeCommandEncoder> ce = enc_c_begin(); [ce setArgumentTable:at]; [at setAddress:ab.gpuAddress + ao atIndex:0]; [ce setComputePipelineState:ps];
    [ce dispatchThreadgroups:MTLSizeMake((NSUInteger)nj / 64, 1, 1) threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
    enc_c_end(ce);
    args_dirty_all_w(AW_HOST_CS);
    g_mdx_draws += (uint64_t)nq; if (g_mdx_wr == ~0ull) g_mdx_wr = g_vbuf_write_epoch;
    if (!g_mdx_runs++) MLOG("indirect-count multi-draw masking: first time, %d draws (their records are copied on the GPU, zeros past the count, before the render pass)", nq);
    else if (g_mdx_runs % 3600 == 0) MLOG("indirect-count multi-draw masking: %llu times, %llu draws (%llu encoded alone, mdx_next), render pass split %llu times (scans at a pass's opening %llu); waits for the GPU-written count %llu",
                                          (unsigned long long)g_mdx_runs, (unsigned long long)g_mdx_draws, (unsigned long long)g_mdx_fast, (unsigned long long)g_mdx_splits, (unsigned long long)g_mdx_pre, (unsigned long long)g_mdi_waits);
}
// A render pass about to open for a draw that is not such a multi-draw: the multi-draws after it (up to the next write, as mdx_run scans) are copied now, before the pass, so that none of
// them opens the copy inside the pass and splits it. Mario Kart World's scene passes (2048x1152, colour and depth loaded again: 20 MB) were split this way at every frame. Once per epoch
// and submission: a scan taken up to its stop leaves nothing for a second one. Only in a game that has drawn such a multi-draw or an indirect mesh draw (g_mdx_runs): in others the scan
// would walk each submission's draws for nothing. DM_NVN_MDX_PRESCAN=0 turns it off (its cost or gain: ab with DM_AB). Upstream NXNative a4705fe1
static void mdx_prescan(void) {
    static uint64_t ep = ~0ull, sub; static int mode = -1; if (mode < 0) mode = sw_mode("DM_NVN_MDX_PRESCAN", 1);
    if (!g_mdx_runs || !sw_on(mode) || (ep == g_mdx_epoch && sub == g_sub_serial)) return;
    ep = g_mdx_epoch; sub = g_sub_serial; g_mdx_pre++;
    mdx_run(NULL, NULL);
}
// The draws of one multi-draw are recorded back to back with the same state, and only the first few are live: each one replayed right after the one before it (no op between them,
// the same open pass) is encoded alone, without the rest of draw's work, which cost a whole draw for each masked one (about 1.5 µs on an M4 Pro, 1,100 a frame in Kamura Village)
static struct { const uint8_t *next; const void *enc; uint64_t cnt, ig, il, pass; int i; MTLPrimitiveType mp; MTLIndexType it; } g_mdxc;
static void mdx_chain(uint64_t cnt, int i, MTLPrimitiveType mp, MTLIndexType it, uint64_t ig, uint64_t il) {
    const uint8_t *next = g_mdx_range ? g_exec_cur : g_exec_next;
    g_mdxc = !next ? (typeof(g_mdxc)){0} : (typeof(g_mdxc)){next, (__bridge const void *)g_enc, cnt, ig, il, g_stat_pass, i, mp, it};
}
static int mdx_next(const p_draw *dw, const p_draw_idx *di) {
    uint64_t cnt = dw ? dw->mdi_cnt : di->mdi_cnt, out; int i = dw ? dw->mdi_i : di->mdi_i;
    if (!g_mdxc.next || g_mdxc.next != g_exec_cur || !g_enc || g_mdxc.enc != (__bridge const void *)g_enc || g_mdxc.pass != g_stat_pass || g_mdxc.cnt != cnt || g_mdxc.i + 1 != i
        || passdump() || !mdx_find(dw ? dw->ind : di->ind, cnt, &out) || !out) return 0;
    if (dw) enc_r_draw_indirect(g_enc, g_mdxc.mp, out); else enc_r_draw_indexed_indirect(g_enc, g_mdxc.mp, g_mdxc.it, g_mdxc.ig, g_mdxc.il, out);
    g_stat_draw++; g_mdx_fast++; g_mdxc.next = g_mdx_range ? g_exec_cur : g_exec_next; g_mdxc.i = i;
    return 1;
}
#include "nvn_feedback.inc"

static int skip_fs_draw(NvProg *pr);   // DM_NVN_SKIP_FS (diagnostic), also for task / mesh draws
#include "nvn_geometry.inc"
#include "nvn_wline.inc"   // lines wider than a pixel: a quad per segment
static int geo_drawing(void) { return g_geo_program != nil || g_geo_mesh.on; }

// ---------- Colour loads no draw of the pass needs (DM_NVN_UNWRITTEN_LOAD) ----------
// A colour attachment that no draw of its pass writes is stored as DontCare already (sd_finish: its memory keeps what it held), but it was still loaded: on TBDR every Load reads the
// whole attachment into tile memory, 38-90 MB a frame in Donkey Kong Bananza's developer runs (NX18-X2.0 bananza-alldata-analysis.md, fix 4; G-buffer passes whose later draws mask
// some targets off, targets bound beside a depth-only pass). When the pass opens (rp_begin_ex_ for the draw that opens it, g_ldc_pr), a forward scan over the replay (ldc_scan) finds
// the colour attachments no draw up to the pass's certain end may write (a SetRenderTargets to other targets, or the submission's end): those load as DontCare and, never written,
// store as DontCare, so their memory is left as it was, exactly as before. The scan is only a prediction: draw_ checks every draw before it joins the open pass (ldc_draw_mask, a
// superset of what the pipeline writes or reads from the tile: all of them for a tile read, a remapped or specialized fragment, an unknown output set, a geometry or mesh draw), and a
// draw that would write or read such an attachment ends the pass first and opens its own, which loads it; so does a clear drawn as a triangle into one. Not for clear-only,
// face-split, slice-merged, layered, kept-frame (pass_alternate) or multisampled attachments, nor passes not opened by a draw. DM_NVN_UNWRITTEN_LOAD=0 loads them as before; the
// residency set line counts the loads skipped (and their MB) and the pass ends a draw forced
static uint64_t g_ldc_n, g_ldc_bytes, g_ldc_split, g_ldc_scan_ops;   // attachments loaded as DontCare and their bytes; passes ended for a draw that wrote one after all; ops the scans walked
void mtl_ldc_stats(uint64_t *n, uint64_t *bytes, uint64_t *split) { *n = g_ldc_n; *bytes = g_ldc_bytes; *split = g_ldc_split; }
static int g_ldc_on = -1;   // DM_NVN_UNWRITTEN_LOAD (a unit test may set it)
static int ldc_on(void) { if (g_ldc_on < 0) { const char *e = getenv("DM_NVN_UNWRITTEN_LOAD"); g_ldc_on = !(e && !strcmp(e, "0")); if (!g_ldc_on) MLOG("DM_NVN_UNWRITTEN_LOAD=0: colour attachments no draw of the pass writes are loaded as before"); } return g_ldc_on; }
static int g_ldc_off_once;   // the next pass plans none (after a draw ldc_draw_mask did not foresee)
// The colour attachments (guest slots, which the pass attaches at the same index) a draw with fragment stage fs, channel mask chmask may write or read from the tile; 0xff when unknown
static uint32_t ldc_fs_mask(NvShader *fs, uint32_t chmask) {
    if (!fs) return 0;   // no fragment stage: no colour output
    if (!fs->rf.color_known) return 0xff;
    uint32_t m = 0; for (int i = 0; i < 8; i++) if (((chmask >> (4 * i)) & 0xf) && (fs->rf.color_mask >> i & 1)) m |= 1u << i;
    return m;
}
static uint32_t ldc_draw_mask(NvProg *pr) {   // the draw about to join or open a pass, after fb_prepare (its tile read and remap are planned)
    if (!pr || g_geo_program || g_geo_mesh.on || g_mtk.on || pr->sh[2] || pr->sh[3] || pr->sh[4]) return 0xff;
    NvShader *fs = pr->sh[1];
    if (!fs) return 0;
    if (S.rast_discard) return 0;
    if (g_fb_tseq == g_draw_seq || g_pso_lmap || g_pso_fsfn || ms_fs_override(fs)) return 0xff;
    return ldc_fs_mask(fs, S.chmask.mask);
}
// Of the candidates, those a later op may write before the pass certainly ends (a SetRenderTargets to other targets, or the submission's end); all of them when the scan cannot tell
// Rule (a) (DM_NVN_CLEARED_LOAD): a candidate whose first write in the pass is a clear of all four channels over the whole attachment (drawn as a triangle into the open pass,
// clear_color_tri) needs nothing loaded either: it loads as DontCare as well (*fc), and the clear, when it comes and is whole as predicted, takes it out of g_ldc_mask, so the draws after it
// write it and it is stored. One that turns out partial ends the pass first as before (the next one loads it)
static uint32_t ldc_scan(uint32_t cand, uint32_t *fc) {
    *fc = 0;
    if (!g_exec_next || g_ret_n > 8) return cand;
    int has_sc = R.has_sc; p_scissor sc = R.sc;
    op_cursor cur = {.p = g_exec_next}; for (int k = 0; k < g_ret_n; k++) cur.ret[cur.ret_n++] = g_ret[k];
    NvShader *fs = S.prog && prog_get(S.prog) ? prog_get(S.prog)->sh[1] : nil; uint32_t chmask = S.chmask.mask, used = 0;
    int geo = S.prog && prog_get(S.prog) && (prog_get(S.prog)->sh[2] || prog_get(S.prog)->sh[3] || prog_get(S.prog)->sh[4]);
    const uint8_t *p; op_hdr h; const void *a;
    for (int n = 0; n < 4096; n++) {
        if (!op_next(&cur, &p, &h, &a)) return cur.bad ? cand : used;   // the submission's end: the pass ends there (mtl_sub_commit)
        g_ldc_scan_ops++;
        switch (h.op) {
            case OP_BIND_PROGRAM: { const p_bind_program *b = a; int st = gfx_stage_bits(b->stages);
                if (st & 2) { __unsafe_unretained NvProg *np = b->prog ? prog_get(b->prog) : nil; fs = np ? np->sh[1] : nil; }
                if (st & 0x1d) { __unsafe_unretained NvProg *np = b->prog ? prog_get(b->prog) : nil; geo = np && (np->sh[2] || np->sh[3] || np->sh[4]); }
                break; }
            case OP_BIND_STATE: { const p_bind_state *b = a; if (b->kind == 2) memcpy(&chmask, b->bytes, sizeof chmask); break; }
            case OP_DRAW: case OP_DRAW_IDX: used |= (geo ? cand : ldc_fs_mask(fs, chmask) & cand) & ~*fc; break;
            case OP_SCISSOR: sc = *(const p_scissor *)a; has_sc = 1; break;
            case OP_CLEAR_COLOR: { const p_clear_color *c = a; if (c->index < 0 || c->index >= 8) break;
                uint32_t bit = (1u << c->index) & cand & ~used & ~*fc;
                if (bit && lfc_on() && (c->mask & 0xf) == 0xf && c->index < R.rt.n && R.rt.color[c->index]
                    && ls_scissor_full(R.rt.color[c->index], &R.rt.cview[c->index], R.rt.has_cview[c->index], has_sc, &sc)) *fc |= bit;   // rule (a)
                else used |= (1u << c->index) & cand & ~*fc;
                break; }
            case OP_DRAW_TEX: return cand;
            case OP_SET_RT: if (!rt_same(&R.rt, (const p_set_rt *)a) && !(rtsub_on() && rt_prefix_of(&R.rt, (const p_set_rt *)a))) return used; break;   // other targets: the pass ends (rp_flush / lc_push); a leading part of them may go on in it (DM_NVN_RT_SUBSET), whose draws write none of the others (rt_sub_check)
            default: break;
        }
        if ((used | *fc) == cand) return used;
    }
    return cand;
}
// rp_begin_ex_ for a pass a draw opens (g_ldc_pr), its attachments set: the colour attachments loaded as DontCare, their bits returned
static uint32_t ldc_plan(MTL4RenderPassDescriptor *pd) {
    if (g_ldc_off_once) { g_ldc_off_once = 0; return 0; }
    if (!ldc_on() || g_fsp_pass || g_sm_pass || g_pass_alt || g_geo_omit_colors || g_rp_layered || pd.renderTargetArrayLength > 1) return 0;
    uint32_t cand = 0;
    for (int i = 0; i < R.rt.n && i < 8; i++) { MTLRenderPassColorAttachmentDescriptor *c = pd.colorAttachments[i];
        if (c.texture && R.rt.color[i] && c.loadAction == MTLLoadActionLoad && c.texture.sampleCount == 1 && !bcrt_is(c.texture)) cand |= 1u << i; }
    if (!cand) return 0;
    cand &= ~ldc_draw_mask((__bridge NvProg *)g_ldc_pr);
    uint32_t fc = 0; if (cand) cand &= ~ldc_scan(cand, &fc);
    g_lfc_mask = fc & cand;
    for (int i = 0; i < 8; i++) if (cand >> i & 1) { MTLRenderPassColorAttachmentDescriptor *c = pd.colorAttachments[i]; c.loadAction = MTLLoadActionDontCare;
        if (g_lfc_mask >> i & 1) { if (!g_lfc_n++) MLOG("colour attachment loaded as DontCare: the pass clears it whole before any draw writes it (first case pass %llu; DM_NVN_CLEARED_LOAD)", g_stat_pass + 1); g_lfc_bytes += att_bytes(c.texture, c.level); PD("C %llu c%d ser=%llu loaded as DontCare: the pass clears it whole first (DM_NVN_CLEARED_LOAD)", g_stat_pass + 1, i, (unsigned long long)R.rt.color[i]->serial); continue; }
        g_ldc_n++; g_ldc_bytes += att_bytes(c.texture, c.level);
        PD("C %llu c%d ser=%llu loaded as DontCare: no draw of the pass writes it (DM_NVN_UNWRITTEN_LOAD)", g_stat_pass + 1, i, (unsigned long long)R.rt.color[i]->serial); }
    return cand;
}

// Lazy clears. A set of targets that gets only clears before the game sets other targets used to open a pass just to land them (rp_flush), storing the cleared attachments, and the next
// pass that attached them loaded them back. Breath of the Wild clears its G-buffer one target at a time (depth with the lighting target, then albedo, normals, the fourth), then attaches all
// five: four passes stored 27 MB of cleared memory at 1600x900 and the G-buffer pass loaded it again. Such clears now wait (g_lc): the next pass that attaches the same texture level and
// layer through the same view takes the clear as its load action. The rest land as before, in order, each in a pass of its own (lc_land), before anything else could see their textures: a
// draw whose program samples one, the pass of a draw that does not attach it (before that pass opens), and any operation other than targets, clears, state, uniform updates and buffer
// copies or fills, and the end of a command list (not of a sub-list it calls). Every pass that opens takes them (rp_begin_ex_ calls lc_take_rt), so none waits while a pass is open, and a
// scissored zero clear copied into its rectangle (clear_rect_zero) lands them first: they are older than whatever the pass or the copy writes. Only a draw's pass took them once, and a clear
// drawn as a triangle (scissored, masked or mid-pass: clear_color_tri, clear_ds_tri) opened its pass without: FINAL FANTASY IX's field scenes clear the window in full, then clear the 4:3
// field view with a scissor and draw the field in the pass that clear opened; the full clear waited past those draws and landed in the next pass (the UI's), as its load action, wiping
// the field to black (upstream c3afe786698). A newer clear of the same subresource replaces an older one.
// DM_NVN_LAZY_CLEAR=0 turns it off
typedef struct { p_set_rt rt; uint8_t clear_c[8]; MTLClearColor cc[8]; uint8_t clear_d, clear_s; double cd; uint32_t cs; } lc_group;
enum { LC_MAX = 8 };
static lc_group g_lc[LC_MAX];   // g_nlc of them wait
static uint64_t g_lc_taken, g_lc_landed;   // clears a later pass took as its load action / clear-only passes still opened for them (the residency set line)
void mtl_lc_stats(uint64_t *taken, uint64_t *landed) { *taken = g_lc_taken; *landed = g_lc_landed; }
static int lc_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_LAZY_CLEAR"); v = !(e && !strcmp(e, "0")); if (!v) MLOG("DM_NVN_LAZY_CLEAR=0: clears with no draw open a pass of their own as before"); } return v; }
static int lc_same(const p_set_rt *a, int ka, const p_set_rt *b, int kb) {   // the same subresource through the same view (k = 8: depth / stencil)
    uint64_t s1, s2; int l1, l2, x1, x2; rt_sub(a, ka, &s1, &l1, &x1); rt_sub(b, kb, &s2, &l2, &x2);
    if (!s1 || s1 != s2 || l1 != l2 || x1 != x2) return 0;
    int h1 = ka == 8 ? a->has_dview : a->has_cview[ka], h2 = kb == 8 ? b->has_dview : b->has_cview[kb];
    return h1 == h2 && (!h1 || !memcmp(ka == 8 ? &a->dview : &a->cview[ka], kb == 8 ? &b->dview : &b->cview[kb], sizeof(view_t)));
}
// Land every waiting clear, oldest first, each group in a pass of its own (rp_flush's way)
static void lc_land(void) {
    if (!g_nlc) return;
    if (g_enc) rp_end();
    int n = g_nlc; g_nlc = 0;
    typeof(R) save = R;
    for (int gi = 0; gi < n; gi++) { const lc_group *g = &g_lc[gi]; int any = g->clear_d || g->clear_s; for (int i = 0; i < 8; i++) any |= g->clear_c[i];
        if (!any || !g_cb) continue;
        R.rt = g->rt; R.has_rt = 1; memcpy(R.clear_c, g->clear_c, sizeof R.clear_c); memcpy(R.cc, g->cc, sizeof R.cc);
        R.clear_d = g->clear_d; R.clear_s = g->clear_s; R.cd = g->cd; R.cs = g->cs; R.clear_sm = 0;   // a pending masked stencil clear is newer: it waits on (R = save)
        rp_begin_ex(1); rp_end(); g_lc_landed++; }
    R = save;
}
// SetRenderTargets with clears pending and no draw since: the clears wait instead of opening a pass
static void lc_push(void) {
    if (g_nlc == LC_MAX) lc_land();
    lc_group *g = &g_lc[g_nlc];
    g->rt = R.rt; memcpy(g->clear_c, R.clear_c, sizeof g->clear_c); memcpy(g->cc, R.cc, sizeof g->cc); g->clear_d = R.clear_d; g->clear_s = R.clear_s; g->cd = R.cd; g->cs = R.cs;
    for (int gi = 0; gi < g_nlc; gi++) { lc_group *o = &g_lc[gi];   // older clears of the same subresources are overwritten
        for (int i = 0; i < 8; i++) if (o->clear_c[i]) for (int j = 0; j < 8; j++) if (g->clear_c[j]) { uint64_t s1, s2; int l1, l2, x1, x2; rt_sub(&o->rt, i, &s1, &l1, &x1); rt_sub(&g->rt, j, &s2, &l2, &x2);
            if (s1 && s1 == s2 && l1 == l2 && x1 == x2) { o->clear_c[i] = 0; break; } }
        if ((o->clear_d || o->clear_s) && (g->clear_d || g->clear_s)) { uint64_t s1, s2; int l1, l2, x1, x2; rt_sub(&o->rt, 8, &s1, &l1, &x1); rt_sub(&g->rt, 8, &s2, &l2, &x2);
            if (s1 && s1 == s2 && l1 == l2 && x1 == x2) { if (g->clear_d) o->clear_d = 0; if (g->clear_s) o->clear_s = 0; } } }
    g_nlc++;
    memset(R.clear_c, 0, sizeof R.clear_c); R.clear_d = R.clear_s = 0;
}
// Whether the program samples a texture with a waiting clear (a program with bindless or dynamic handles counts as sampling)
static int lc_sampled(NvProg *pr) {
    if (!pr) return 1;
    for (int st = 0; st < 5; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh || sh->stage >= 6) continue;
        if (sh->rf.bindless || sh->rf.dyn) return 1;
        for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i]; uint64_t h;
            if (b->kind == NVN_RB_IMG) h = b->reg < 32 ? S.img[sh->stage][b->reg] : 0; else if (b->kind == NVN_RB_TEX || b->kind == NVN_RB_TBUF) h = tex_slot_h(S.tex[sh->stage], S.img[sh->stage], b->reg); else continue;
            uint64_t ser = h ? h_ser(h) : 0; if (!ser) continue;
            for (int gi = 0; gi < g_nlc; gi++) { const lc_group *g = &g_lc[gi];
                for (int k = 0; k < 8; k++) if (g->clear_c[k] && g->rt.color[k] && g->rt.color[k]->serial == ser) return 1;
                if ((g->clear_d || g->clear_s) && g->rt.depth && g->rt.depth->serial == ser) return 1; } } }
    return 0;
}
// A pass about to open: its attachments take the waiting clears of the same subresources (the newest one; the pass's own pending clear is newer still), the rest land first
static void lc_take_rt(void) {
    for (int gi = g_nlc - 1; gi >= 0; gi--) { lc_group *g = &g_lc[gi];
        for (int i = 0; i < 8; i++) if (g->clear_c[i])
            for (int j = 0; j < R.rt.n && j < 8; j++) if (R.rt.color[j] && !rt_dup_slot(&R.rt, j) && !nvn_fmt_bc(R.rt.color[j]->d.format) && lc_same(&g->rt, i, &R.rt, j)) {
                if (!R.clear_c[j]) { R.clear_c[j] = 1; R.cc[j] = g->cc[i]; }
                g->clear_c[i] = 0; g_lc_taken++; break; }
        if ((g->clear_d || g->clear_s) && R.rt.depth && lc_same(&g->rt, 8, &R.rt, 8)) {
            if (g->clear_d) { if (!R.clear_d) { R.clear_d = 1; R.cd = g->cd; } g->clear_d = 0; }
            if (g->clear_s) { if (!R.clear_s) { R.clear_s = 1; R.cs = g->cs; } g->clear_s = 0; }
            g_lc_taken++; } }
    lc_land();
}
// The draw about to open a pass: as lc_take_rt, unless its program samples a texture with a waiting clear (then every waiting clear lands first)
static void lc_take(NvProg *pr) {
    if (lc_sampled(pr)) { lc_land(); return; }
    lc_take_rt();
}
// The operations a waiting clear can wait across: they neither read nor write textures
static int lc_keeps(uint32_t op) {
    switch (op) {
        case OP_SET_RT: case OP_CLEAR_COLOR: case OP_CLEAR_DS: case OP_DRAW: case OP_DRAW_IDX: case OP_BEGIN: case OP_JUMP: case OP_CALL:
        case OP_SCISSOR: case OP_BIND_PROGRAM: case OP_BIND_STATE: case OP_BIND_VATTR: case OP_BIND_VSTREAM: case OP_BIND_VBUF: case OP_BIND_VBUF1:
        case OP_BIND_UBO: case OP_BIND_UBO_SMALL: case OP_BIND_SSBO: case OP_BIND_TEX: case OP_BIND_TEX1: case OP_BIND_SAMP: case OP_BIND_IMG: case OP_STENCIL:
        case OP_POLY_OFFSET: case OP_VIEWPORTS: case OP_DEPTH_RANGE: case OP_DEPTH_CLAMP: case OP_DEPTH_BOUNDS: case OP_LINE_WIDTH: case OP_VP_SWIZZLE: case OP_BLEND_COLOR: case OP_ALPHA_REF: case OP_PUSH_CONST: case OP_COPY_STRIDE:
        case OP_TF_BIND: case OP_TF_STATE: case OP_RAST_DISCARD: case OP_PRIM_RESTART: case OP_BARRIER: case OP_SET_TEX_POOL: case OP_SET_SAMP_POOL: case OP_RENDER_COND:
        case OP_UPDATE_UB: case OP_COPY_B2B: case OP_CLEAR_BUF: return 1;
        default: return 0;
    }
}

static void dispatch(const p_dispatch *dp);
static int up_mfx_wanted(NvShader *cs); static int up_mfx_encode(NvShader *cs);   // a game's upscaler through MetalFX (see up_mfx_encode)
static void fg_capture_ndsr(NvShader *cs);   // frame generation's depth at the game's upscaler (nvn_framegen.inc)
static int ndve_dispatch_index(NvShader *cs), ndve_engine_dispatch(NvShader *cs, const p_dispatch *dp);   // nn::ndve's movie network as the host's kernels (DM_NDVE_ENGINE=1, nvn_ndve.inc)
// ---------- Compute dispatches moved ahead of the render pass they would split (DM_NVN_CS_HOIST) ----------
// Metal cannot run a compute dispatch inside a render pass, so a dispatch between two draws of one pass ends it, and on a tile-based GPU every attachment is stored and loaded again:
// Breath of the Wild runs one GPU particle dispatch per emitter between the G-buffer's effect draws, six to eight splits of a 1600x900 G-buffer a frame (about 350 MB of attachment
// traffic). When a draw opens a pass, the ops after it are scanned up to the first op that would end the pass anyway; each dispatch met on the way runs right away, before the pass
// opens, if moving it ahead of the draws before it in that stretch changes nothing they read or write: it writes no memory those draws read (vertex, index, indirect, uniform and
// storage buffers; storage buffers count as written by the dispatch), samples no colour attachment of the pass, writes no image, and the draws write no memory (no storage buffer,
// image or transform feedback). Replay then skips it, and the pass stays open across it. A dispatch that samples the pass's depth attachment sees it as the pass began, so it moves
// only while no draw before it in the pass has depth writes on (until then that depth is the same; Breath of the Wild's particle collision samples the G-buffer depth). On by default
// (0 off): Breath of the Wild at 900p on an M2 Max, 28 → 8 compute encoders and 149 → 129 render passes a frame, frame p50 10.2 → 8.8 ms
static int cshoist_on(void) { static int m = -1; if (m < 0) { const char *e = getenv("DM_NVN_CS_HOIST"); m = !(e && !strcmp(e, "0")); if (!m) MLOG("DM_NVN_CS_HOIST=0: compute dispatches between the draws of a pass end it"); } return m; }
typedef struct { uint64_t lo, hi; } csh_rng;
enum { CSH_RN = 1024, CSH_MAX = 64 };
static const uint8_t *g_csh_op[CSH_MAX]; static int g_csh_n; static uint64_t g_csh_moved, g_csh_depth, g_csh_stop[8];
// Why a dispatch that ended a pass was not moved ahead of it (logging only): the op the pass's scan stopped at, 0x100 + a stop index for the full scan's other reasons, 0xff not
// scanned; kept for the pass the scan was made for (g_csh_why_pass)
static uint32_t g_csh_why; static uint64_t g_csh_why_n[0x110], g_csh_why_pass;   // dispatches run ahead and not yet met by replay; moved, of them sampling the pass's depth; why scans stopped
static int csh_take(const uint8_t *p) { for (int i = 0; i < g_csh_n; i++) if (g_csh_op[i] == p) { g_csh_op[i] = g_csh_op[--g_csh_n]; return 1; } return 0; }
static int csh_add(csh_rng *r, int *n, uint64_t a, uint64_t sz) {
    if (!a) return 1;
    // Sparse virtual addresses can name the same storage through different
    // pools. A guest-address comparison cannot establish independence there.
    if (!sz || sz > UINT64_MAX - a || *n >= CSH_RN || nvn_sparse_alias(a, a + sz)) return 0;
    r[(*n)++] = (csh_rng){a, a + sz}; return 1;
}
static int csh_hit(const csh_rng *a, int na, const csh_rng *b, int nb) { for (int i = 0; i < na; i++) for (int j = 0; j < nb; j++) if (a[i].lo < b[j].hi && b[j].lo < a[i].hi) return 1; return 0; }
static int csh_attachment_hit(uint64_t addr, uint64_t size) {
    if (!addr) return 0;
    csh_rng access[1]; int na = 0; if (!csh_add(access, &na, addr, size)) return 1;
    for (int k = 0; k < 9; k++) {
        const tex_t *t = k == 8 ? R.rt.depth : k < R.rt.n ? R.rt.color[k] : NULL;
        if (!t || !t->mem) continue;
        csh_rng storage[1]; int ns = 0;
        if (!csh_add(storage, &ns, (uint64_t)t->mem, t->L.size) || csh_hit(access, na, storage, ns)) return 1;
    }
    return 0;
}
// The memory a draw reads besides textures; 0 when it cannot be listed or the draw may write memory
// pass_alternate: a draw that may write memory (storage buffers, images, global memory, or bindings the reflection cannot list) is drawn in a kept frame too
static int pa_may_write(NvProg *pr) {
    if (!pr) return 1;
    for (int st = 0; st < 6; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh) continue;
        // bindless or dynamically indexed textures are reads (prog_swrites ignores them too): Bananza's view shaders are bindless, and giving up on them kept every draw (run of 2c52f4ee)
        for (int i = 0; i < sh->rf.nb; i++) switch (sh->rf.b[i].kind) {   // a binding the shader only reads (rw 0, as prog_swrites and the dump's "ro") writes nothing: Bananza's view
            // binds its instance data as read-only storage buffers, and counting those as writes kept every one of its ~1,000 draws in the kept frames (the iPhone runs of 61e19abd and ae8d72d8)
            case NVN_RB_SBUFP: case NVN_RB_SBUFU: case NVN_RB_SBUFQ: case NVN_RB_IMG: case NVN_RB_IMGU: case NVN_RB_GMEM: case NVN_RB_GMEML: case NVN_RB_TBUFU: if (sh->rf.b[i].rw) return 1; break;
            default: break; } }
    return S.tf_on;   // transform feedback writes the vertices it captures
}
static int csh_draw_reads(NvProg *pr, const p_draw *dw, const p_draw_idx *di, csh_rng *r, int *n) {
    if (!pr || pr->sh[2] || pr->sh[3] || pr->sh[4] || S.rast_discard || (dw && dw->mdi_cnt) || (di && (di->mdi_cnt || di->ind))) return 0;
    for (int k = 0; k < 16; k++) if (S.vbuf[k].size && !csh_add(r, n, S.vbuf[k].address, S.vbuf[k].size)) return 0;   // an empty stream reads no guest memory
    if (di && !csh_add(r, n, di->ibuf, (uint64_t)(di->count > 0 ? di->count : 0) * 4 + 16)) return 0;
    if (!csh_add(r, n, dw ? dw->ind : di ? di->ind : 0, 32)) return 0;
    for (int st = 0; st < 2; st++) { __unsafe_unretained NvShader *sh = pr->sh[st]; if (!sh) continue;
        if (sh->rf.bindless || sh->rf.dyn) return 0;
        for (int i = 0; i < sh->rf.nb; i++) { const nvn_rbind *b = &sh->rf.b[i];
            switch (b->kind) {
                case NVN_RB_CBUF: case NVN_RB_UBOP: if (b->reg < 16 && !csh_add(r, n, S.ubo[st][b->reg].addr, ub_bound(S.ubo[st][b->reg].size))) return 0; break;   // as far as the shader can read it
                case NVN_RB_TEX: { uint64_t h = tex_slot_h(S.tex[st], S.img[st], b->reg); int tid = (int)(h & 0xfffff); if (!tid) break;
                    rmu_lock(); tex_t t = tid < g_ntreg && g_treg[tid].ok ? g_treg[tid].t : (tex_t){0}; os_unfair_lock_unlock(&g_rmu);
                    // Linear and buffer textures can read directly from pool
                    // buffers. Include storage even when reflection calls it TEX.
                    if (!t.serial || !csh_add(r, n, (uint64_t)t.mem, t.L.size)) return 0;
                    break; }
                case NVN_RB_TEXU: case NVN_RB_TEXD: case NVN_RB_TEXA: return 0;
                case NVN_RB_SBUFP: case NVN_RB_SBUFU: case NVN_RB_SBUFQ: case NVN_RB_IMG: case NVN_RB_TBUF: case NVN_RB_GMEM: return 0;   // may write memory, or reads memory not listed here
                default: break; } } }
    return 1;
}
// A dispatch at its place in the stream (S as it is there): its storage buffers (counted as written), and whether it samples a colour attachment of the pass (1), only the depth (2)
static int csh_cs(NvShader *cs, const p_dispatch *dp, csh_rng *w, int *nw, int *depth) {
    if (!cs || cs->builtin || dp->ind || cs->rf.bindless || cs->rf.dyn) return 0;
    for (int i = 0; i < cs->rf.nb; i++) { const nvn_rbind *b = &cs->rf.b[i];
        switch (b->kind) {
            case NVN_RB_SBUFP: if (b->reg >= 16 || csh_attachment_hit(S.ssbo[5][b->reg].addr, S.ssbo[5][b->reg].size) || !csh_add(w, nw, S.ssbo[5][b->reg].addr, S.ssbo[5][b->reg].size)) return 0; break;
            case NVN_RB_CBUF: case NVN_RB_UBOP: if (b->reg >= 16 || csh_attachment_hit(S.ubo[5][b->reg].addr, ub_bound(S.ubo[5][b->reg].size))) return 0; break;
            case NVN_RB_SBUFU: case NVN_RB_SBUFQ: case NVN_RB_IMG: case NVN_RB_TEXU: case NVN_RB_TEXD: case NVN_RB_TEXA: case NVN_RB_GMEM: return 0;
            case NVN_RB_TEX: case NVN_RB_TBUF: { uint64_t h = tex_slot_h(S.tex[5], S.img[5], b->reg); int tid = (int)(h & 0xfffff); if (!tid) break;
                rmu_lock(); tex_t t = tid < g_ntreg && g_treg[tid].ok ? g_treg[tid].t : (tex_t){0}; os_unfair_lock_unlock(&g_rmu);
                if (!t.serial) return 0;
                for (int k = 0; k < R.rt.n && k < 8; k++) if (tex_storage_overlap(&t, R.rt.color[k])) return 0;
                if (tex_storage_overlap(&t, R.rt.depth)) *depth = 1;
                break; }
            default: break; } }
    return 1;
}
// Whether a dispatch comes before the first op that would stop cs_hoist_try's scan, looking at op codes only. Most passes have none: the scan then saved and restored the
// whole replay state (S, R) and marked every argument table dirty at each pass's first draw for nothing (BotW: 2.5% of the submit thread in those copies alone).
// Ops it cannot rule out (draws whose reads may stop the full scan) count as passable, so a 1 here only means the full scan may move something
static int csh_dispatch_ahead(void) {
    op_cursor cur = {.p = g_exec_next}; for (int k = 0; k < g_ret_n; k++) cur.ret[cur.ret_n++] = g_ret[k];
    for (int guard = 0; guard < 4096; guard++) {
        const uint8_t *q; op_hdr hq; const void *aq;
        if (!op_next(&cur, &q, &hq, &aq)) return 0;
        switch (hq.op) {
            case OP_DISPATCH: return 1;
            case OP_BARRIER: { uint32_t bits; memcpy(&bits, aq, sizeof bits); if (bits) { g_csh_why = OP_BARRIER; return 0; } continue; }
            case OP_DRAW: case OP_DRAW_IDX:
            case OP_ALPHA_REF: case OP_BIND_IMG: case OP_BIND_PROGRAM: case OP_BIND_SAMP: case OP_BIND_SSBO: case OP_BIND_STATE: case OP_BIND_TEX: case OP_BIND_TEX1:
            case OP_BIND_UBO: case OP_BIND_UBO_SMALL: case OP_BIND_VATTR: case OP_BIND_VBUF: case OP_BIND_VBUF1: case OP_BIND_VSTREAM: case OP_BLEND_COLOR: case OP_COPY_STRIDE:
            case OP_DEPTH_CLAMP: case OP_DEPTH_BOUNDS: case OP_LINE_WIDTH: case OP_DEPTH_RANGE: case OP_POLY_OFFSET: case OP_PRIM_RESTART: case OP_PUSH_CONST: case OP_RAST_DISCARD: case OP_SCISSOR: case OP_SET_SAMP_POOL:
            case OP_SET_TEX_POOL: case OP_STENCIL: case OP_TF_BIND: case OP_VIEWPORTS: case OP_VP_SWIZZLE:
                continue;
            default: g_csh_why = hq.op; return 0;   // OP_TF_STATE and everything state_op does not take stop the full scan too
        }
    }
    return 1;
}
static void cs_hoist_try(NvProg *pr0, const p_draw *dw0, const p_draw_idx *di0) {
    g_csh_why = 0xff; g_csh_why_pass = g_stat_pass + 1;   // the pass this draw opens; 0xff: an early return below, not scanned
    if (!g_exec_next || g_ret_n > 8 || g_nlc || R.clear_d || R.clear_s || R.clear_sm) return;
    for (int i = 0; i < 8; i++) if (R.clear_c[i]) return;   // a clear this pass takes as its load action comes before anything a moved dispatch could read
    { static int pre = -1; if (pre < 0) { const char *e = getenv("DM_NVN_CSH_PRESCAN"); pre = !(e && !strcmp(e, "0")); }
      if (pre && !csh_dispatch_ahead()) { g_csh_stop[5]++; return; } }
    static csh_rng rd[CSH_RN]; int nrd = 0;
    if (!csh_draw_reads(pr0, dw0, di0, rd, &nrd)) { g_csh_stop[0]++; g_csh_why = 0x100; return; }
    op_cursor cur = {.p = g_exec_next}; for (int k = 0; k < g_ret_n; k++) cur.ret[cur.ret_n++] = g_ret[k];
    static typeof(S) Ssave; memcpy(&Ssave, &S, sizeof S); typeof(R) Rsave = R; int pso_dirty = g_pso_dirty, dss_dirty = g_dss_dirty, moved = 0;
    int dwrote = R.rt.depth && (S.ds.dw || S.ds.st);   // either plane: a compute texture view may read stencil
    for (int guard = 0; guard < 4096; guard++) {
        const uint8_t *q; op_hdr hq; const void *aq;
        if (!op_next(&cur, &q, &hq, &aq)) break;
        if (hq.op == OP_BARRIER) { uint32_t bits; memcpy(&bits, aq, sizeof bits); if (bits) { g_csh_stop[5]++; g_csh_why = OP_BARRIER; break; } continue; }
        if (hq.op == OP_DRAW || hq.op == OP_DRAW_IDX) {
            p_draw tdw; p_draw_idx tdi; const p_draw *d = hq.op == OP_DRAW ? draw_rec(aq, hq.size, &tdw) : NULL; const p_draw_idx *x = hq.op == OP_DRAW_IDX ? draw_idx_rec(aq, hq.size, &tdi) : NULL;
            prog_resolve(); __unsafe_unretained NvProg *pr = S.prog ? prog_get(S.prog) : nil;
            if (!csh_draw_reads(pr, d, x, rd, &nrd)) { g_csh_stop[1]++; g_csh_why = 0x101; break; }
            if (R.rt.depth && (S.ds.dw || S.ds.st)) dwrote = 1;
            continue; }
        if (hq.op == OP_DISPATCH) {
            const p_dispatch *dp = aq; __unsafe_unretained NvShader *cs = S.cprog && prog_get(S.cprog) ? prog_get(S.cprog)->sh[5] : nil;
            static csh_rng wr[CSH_RN]; int nwr = 0, depth = 0;
            if (!csh_cs(cs, dp, wr, &nwr, &depth)) { g_csh_stop[2]++; g_csh_why = 0x102; break; }
            if (depth && dwrote) { g_csh_stop[7]++; g_csh_why = 0x107; break; }   // it would miss depth the draws before it wrote
            if (csh_hit(wr, nwr, rd, nrd)) { g_csh_stop[3]++; g_csh_why = 0x103; break; }   // the draws before it read what it writes
            if (g_csh_n >= CSH_MAX) { g_csh_stop[4]++; g_csh_why = 0x104; break; }
            PD("H %llu dispatch %s moved ahead of the pass%s", g_stat_pass + 1, cs->key, depth ? " (samples the pass's depth, which no draw before it wrote)" : "");
            dispatch(dp); g_csh_op[g_csh_n++] = q; g_csh_moved++; g_csh_depth += depth; moved++;
            continue; }
        if (hq.op == OP_TF_STATE) { g_csh_stop[5]++; g_csh_why = OP_TF_STATE; break; }   // saves/restores counters in GPU memory
        if (state_op(hq.op, aq)) continue;
        g_csh_stop[5]++; g_csh_why = hq.op; break;   // anything else may end the pass, write memory or depend on the order (copies, updates, clears, targets, queries)
    }
    if (cur.bad) g_csh_stop[6]++;
    memcpy(&S, &Ssave, sizeof S); args_dirty_all_w(AW_RESTORE); R = Rsave; g_pso_dirty = pso_dirty || moved; g_dss_dirty = dss_dirty || moved; prog_resolve();
    { static int once; if (moved && !once++) MLOG("compute dispatches moved ahead of the render pass they would split (DM_NVN_CS_HOIST): first case pass %llu, %d dispatches", g_stat_pass + 1, moved); }
}
void mtl_geomesh_stats(uint64_t *n, uint64_t *wait, uint64_t *run_draws, uint64_t *runs, uint64_t ends[5]) { *n = g_geo_mesh_n; *wait = g_geo_mesh_wait; *run_draws = g_mrun_draws; *runs = g_mrun_runs; memcpy(ends, g_mrun_ends, sizeof g_mrun_ends); }
// Geometry draws the compute path drew since the last call, by reason, and the three pairs that drew most of them: "<n> draws; <reason> <n>, ...; most: <vertex>+<geometry> (<reason>) <n>, ..."
// → the draws (0: none, nothing written)
uint64_t mtl_geocomp_stats(char *out, size_t cap) {
    static uint64_t prev[GCP_N]; uint64_t total = 0; size_t o = 0; out[0] = 0;
    os_unfair_lock_lock(&g_gcp_lk);   // gcp_count runs on the encoding thread
    for (int w = 0; w < GCP_N; w++) total += g_gcp[w] - prev[w];
    if (!total) { g_gcp_npair = 0; os_unfair_lock_unlock(&g_gcp_lk); return 0; }
    o += (size_t)snprintf(out + o, o < cap ? cap - o : 0, "%llu draws;", (unsigned long long)total);
    int first = 1;
    for (int w = 0; w < GCP_N; w++) if (g_gcp[w] != prev[w]) { o += (size_t)snprintf(out + o, o < cap ? cap - o : 0, "%s %s %llu", first ? "" : ",", g_gcp_name[w], (unsigned long long)(g_gcp[w] - prev[w])); first = 0; prev[w] = g_gcp[w]; }
    o += (size_t)snprintf(out + o, o < cap ? cap - o : 0, "; most:");
    for (int k = 0; k < 3; k++) {
        int best = -1; for (int i = 0; i < g_gcp_npair; i++) if (g_gcp_pair[i].n && (best < 0 || g_gcp_pair[i].n > g_gcp_pair[best].n)) best = i;
        if (best < 0) break;
        o += (size_t)snprintf(out + o, o < cap ? cap - o : 0, "%s %s+%s (%s) %llu", k ? "," : "", g_gcp_pair[best].vs ? g_gcp_pair[best].vs->key : "-", g_gcp_pair[best].gs ? g_gcp_pair[best].gs->key : "-",
                              g_gcp_name[g_gcp_pair[best].why], (unsigned long long)g_gcp_pair[best].n);
        g_gcp_pair[best].n = 0;
    }
    g_gcp_npair = 0; os_unfair_lock_unlock(&g_gcp_lk);
    return total;
}
void mtl_geohoist_stats(uint64_t *moved, uint64_t *runs, uint64_t *stops) { *moved = g_geo_hoisted; *runs = g_geo_hoist_runs; memset(stops, 0, 6 * sizeof *stops); stops[3] = g_geo_dependency_splits; }
void mtl_cshoist_stats(uint64_t *moved, uint64_t *depth, uint64_t *stops) { *moved = g_csh_moved; *depth = g_csh_depth; for (int i = 0; i < 8; i++) stops[i] = g_csh_stop[i]; }
// Physical color attachments the selected pipeline can write. A merged pass remaps logical outputs and channel masks; a specialized fragment's outputs are unknown here.
static uint32_t draw_color_writes(NvProg *pr) {
