// A program's libraries are loaded in the background when the game makes the program (nvnProgramSetShaders, most of them while it loads a scene), and the next submission
// takes them (warm_claim) instead of its first draw loading each on the submit thread: in Donkey Kong Bananza a level's first frames loaded 3 to 7 libraries there, 20-90 ms
// with the drive idle and up to 4 s with it busy. A draw that comes before its library has loaded loads it itself, as before. DM_NVN_PREFETCH=0 turns it off.
// The loads have serial queues of their own, one per two performance cores (hw.perflevel0) as the pipeline builds had before pp_bg_count: on the build queues (pp_bg_queue) a load
// waited behind every build queued before it, on an iPhone behind all of them (one queue there then; Super Mario Odyssey once had 323 in flight), and a draw that came first
// loaded its library itself on the submit thread
static _Atomic uint64_t g_progpf_loaded;
static int prefetch_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_PREFETCH"); v = !(e && !strcmp(e, "0")); } return v; }
static dispatch_queue_t progpf_queue(void) {
    static dispatch_queue_t q[8]; static int n; static _Atomic unsigned rr; static dispatch_once_t once;
    dispatch_once(&once, ^{ int pc = 0; size_t sz = sizeof pc; if (sysctlbyname("hw.perflevel0.physicalcpu", &pc, &sz, NULL, 0) || pc < 2) pc = 2;
        n = pc / 2 > 8 ? 8 : pc / 2;
        for (int i = 0; i < n; i++) q[i] = dispatch_queue_create("dm.nvn.lib-prefetch", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_UTILITY, 0)); });
    return q[atomic_fetch_add(&rr, 1) % (unsigned)n];
}
void mtl_prog_prefetch(const prog_t *cp) {
    prog_t *p = (prog_t *)cp;
    if (!g_dev || !prefetch_on()) return;
    shmap_read_once();   // the map only: the prewarm starts on the submit thread (shmap_load)
    for (unsigned i = 0; i < p->nstage; i++) {
        uint8_t md[8]; if (!prog_key(p, i, md)) MDIE("program stage %u has no shader key", i);
        NSString *k = [NSString stringWithFormat:@"%02x%02x%02x%02x%02x%02x%02x%02x", md[0], md[1], md[2], md[3], md[4], md[5], md[6], md[7]];
        NSString *stage = g_shmap[k]; int st = stage ? stage_of(stage) : -1;
        if (st < 0) continue;   // not in the package: a built-in kernel (prog_get)
        NSString *pc = [k stringByAppendingString:@"_b"];
        if (!progpf_first(pc)) continue;
        dispatch_async(progpf_queue(), ^{ @autoreleasepool {
            NvShader *sh = shader_acquire(pc, st, hybrid_on());   // its pulling entry too, as the prewarm does (warm_shader)
            if (!sh) return;
            WarmItem *item = [WarmItem new]; item->kind = 0; item->record = 1; item->key = pc; item->shader = sh; warm_enqueue(item);
            if (!g_progpf_loaded++) MLOG("shader prefetch at program creation: first library %s loaded in the background (DM_NVN_PREFETCH=0 turns it off)", pc.UTF8String);
        } });
    }
}
// Dispatches share the open copy encoder (a Metal 4 compute encoder) with the copies and dispatches around them, each ordered after everything the encoder already holds by a barrier inside it,
// as a texture copy is (blit). An encoder of their own, with full queue barriers on both sides, cost the GPU a drain per dispatch: Hyrule Warriors: Age of Calamity's battles after the first cutscene
// run about 1,060 small dispatches a frame, and the Mac GPU went from 6.7 to 16 ms a frame at the same draws, the iPhone's from 15 to about 50 (17 fps).
// DM_NVN_DISPATCH_OWN=1 gives each dispatch its own encoder again
static int dispatch_own(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DM_NVN_DISPATCH_OWN"); v = e && !strcmp(e, "1"); if (v) MLOG("compute dispatches: each in an encoder of its own (DM_NVN_DISPATCH_OWN=1)"); }
    return v;
}
// A game dispatch's memory, when every binding of its shader can be bounded (dispatch_ranges): its storage buffers as written (read too, so they go in the write list only), its uniform
// slots and the storage of the textures it samples as read. Such a dispatch follows the copies' rule (blit_buf): a barrier before it only when it reads a range written since the last
// barrier, or writes one read or written since then; it is recorded with those ranges, so a later copy or dispatch that touches them gets its barrier. Anything that cannot be bounded
// keeps the old rule, a barrier before the dispatch and "everything written" after it: images, global memory, buffer textures, handles read from uniforms or pushed (bindless, dyn,
// pool, htab, SBUFU / SBUFQ, TEXA), a storage or uniform binding of size 0, a range in a sparse pool (nvn_sparse_alias), a texture the replay cannot resolve or a buffer texture, an
// indirect dispatch (its counts are GPU-written memory, copied into c0 inside the encoder), a binding kind not listed below, more ranges than the tables hold, and the host's own kernels
// (rb_swap_gpu, gsb_swz). Work in other encoders (draws, the helper compute passes, an own encoder) is ordered by the full barrier every encoder ends with (m4_end).
// Before, every dispatch had a barrier before it: a frame of small independent dispatches (one per particle emitter) paid the barrier's fixed cost each time (S2Arm 116fe90e).
// Between two game dispatches with ranges the game's own barriers decide (DM_NVN_DISPATCH_RANGE=2, the default; ported from S2Arm a51b43f7, Apache-2.0, after NXNative 547c5db6, MIT): NVN
// makes a dispatch's writes visible to later work only when the game calls nvnCommandBufferBarrier, and particle systems that share the buffers they write overlap almost every time
// (Mario Kart World, about 230 dispatches a frame, 91 % meeting an earlier one's range: S2Arm measured the encoder 6.6-9.8 → 0.4-1.2 ms and GPU p50 9.0 → 5.3 ms). Such a dispatch gets a
// barrier when the game issued one since the dispatch before it (g_dsp_game_bar), when it touches a copy's ranges or an "everything written" record, or when the dispatch tables are full;
// its ranges go into g_dspw / g_dspr, which later copies are checked against (blit_buf) and later dispatches are not. Dispatches without ranges and the host's own keep the old rule.
// DM_NVN_DISPATCH_RANGE=1 (or range) checks dispatches against each other's ranges too (S2Arm 116fe90e); =0 restores the old rule; =ab... alternates 1 and 2 with the DM_AB phases
// (sw_mode; phase 0 is 1), for A/B runs on the iPhone
enum { DR_MAX = BW_MAX / 2 };
typedef struct { int nw, nr; uint64_t wlo[DR_MAX], whi[DR_MAX], rlo[DR_MAX], rhi[DR_MAX]; } disp_rng;
static uint64_t g_disp_ranged, g_disp_full, g_disp_nobar;   // game dispatches with ranges / without (barrier before each) / with ranges and no barrier before them
static uint64_t g_disp_gbar;   // game dispatches with ranges given a barrier because the game issued one since the dispatch before
uint64_t mtl_dispatch_range_stats(int k) { return k == 0 ? g_disp_ranged : k == 1 ? g_disp_full : k == 2 ? g_disp_nobar : g_disp_gbar; }
static int dispatch_range_mode(void) {   // 0 the old rule, 1 ranges between dispatches, 2 the game's barriers between dispatches
    static int v = -1, ab = -1;
    if (v < 0) { const char *e = getenv("DM_NVN_DISPATCH_RANGE");
        if (e && !strncmp(e, "ab", 2)) { ab = sw_mode("DM_NVN_DISPATCH_RANGE", 0); v = 2; }
        else v = e && !strcmp(e, "0") ? 0 : e && (!strcmp(e, "1") || !strcmp(e, "range")) ? 1 : 2;
        if (!v) MLOG("DM_NVN_DISPATCH_RANGE=0: a barrier before every compute dispatch, which counts as writing all memory (the old rule)");
        else if (v == 1) MLOG("DM_NVN_DISPATCH_RANGE=1: compute dispatches ordered by the memory ranges they touch, not by the game's barriers (the rule before S2Arm a51b43f7)"); }
