static int dispatch_ranges(NvShader *cs, const p_dispatch *dp, disp_rng *o) {
    o->nw = o->nr = 0;
    if (!cs || cs->builtin || dp->ind || cs->rf.bindless || cs->rf.dyn || cs->rf.pool || cs->rf.htab || !dispatch_range_on()) return 0;
    for (int i = 0; i < cs->rf.nb; i++) { const nvn_rbind *b = &cs->rf.b[i];
        switch (b->kind) {
            case NVN_RB_SUPPORT: case NVN_RB_C1: case NVN_RB_DRV0: case NVN_RB_DRV2: case NVN_RB_CBSIZE: case NVN_RB_PUSH: case NVN_RB_BORDER: case NVN_RB_TBIAS:   // the host's own blocks, built at encode time
