// Whether the dispatch touches what the encoder holds since its last barrier (or the tables cannot take its ranges): then it needs a barrier first. An operation recorded as writing
// everything (a texture copy, blit; a dispatch under the old rule; a copy in a sparse pool) orders every dispatch after it, one with no ranges too: a binding's own copy (tex_upgrade
// through blit, in encode_args) must land before the shader reads, whatever the dispatch's ranges are (Compute bindings prepare texture copies before the dispatch encoder)
// Mode 2 (the game's barriers) looks at the copies' sets only, and at the game's barrier; mode 1 at the dispatch sets too (they hold ranges only when the ab phase just changed)
static int dispatch_hits(const disp_rng *rg, int mode) {
    if (mode == 2) {
        if (g_dsp_game_bar) { g_disp_gbar++; return 1; }
        if (g_dspw_n + rg->nw > DW_MAX || g_dspr_n + rg->nr > DW_MAX) return 1;
    } else if (g_bw_n + rg->nw > BW_MAX || g_br_n + rg->nr > BW_MAX) return 1;
    for (int i = 0; i < g_bw_n; i++) if (!g_bw_lo[i] && g_bw_hi[i] == ~0ull) return 1;
    for (int i = 0; i < rg->nr; i++) if (bw_hit(rg->rlo[i], rg->rhi[i]) || (mode != 2 && dw_hit(rg->rlo[i], rg->rhi[i]))) return 1;
    for (int i = 0; i < rg->nw; i++) if (bw_hit(rg->wlo[i], rg->whi[i]) || br_hit(rg->wlo[i], rg->whi[i]) || (mode != 2 && (dw_hit(rg->wlo[i], rg->whi[i]) || dr_hit(rg->wlo[i], rg->whi[i])))) return 1;
    return 0;
}
static void dw_put(uint64_t *lo, uint64_t *hi, int *n, uint64_t a, uint64_t b) { for (int k = 0; k < *n; k++) if (lo[k] == a && hi[k] == b) return; lo[*n] = a; hi[(*n)++] = b; }   // a range already there is not added again: the systems share their tables
// rg: the game dispatch's ranges (dispatch_ranges), NULL for the old rule
static id<MTL4ComputeCommandEncoder> dispatch_enc_r(const disp_rng *rg) {
    id<MTL4ComputeCommandEncoder> e = blit_open(); g_gp_disp++;
    if (rg) { int mode = dispatch_range_mode();
        g_disp_ranged++;
        if (g_blit_ops && dispatch_hits(rg, mode)) blit_barrier();
        else if (g_blit_ops && !g_disp_nobar++) MLOG("compute dispatches: no barrier between ones %s (first case pass %llu; DM_NVN_DISPATCH_RANGE=0 puts one before each)", mode == 2 ? "with no game barrier between them" : "whose memory does not overlap", g_stat_pass);
        if (mode == 2) {   // room checked by dispatch_hits, or emptied by the barrier
            for (int i = 0; i < rg->nw; i++) dw_put(g_dspw_lo, g_dspw_hi, &g_dspw_n, rg->wlo[i], rg->whi[i]);
