        ps = lib ? host_cps(lib, @"rb_swap", nil, &e) : nil;
        if (!ps) { failed = 1; MLOG("[RED] cannot create the red / blue exchange for RGB565-family copies: %s", e.localizedDescription.UTF8String); return 0; }
    }
