    if (!mt || !tex_level_ok(mt, level, "CPU readback") || !fam_is_valid(mt)) { memset(dst, 0, img * nz); return; }   // a compressed family member whose heap holds another size reads 0
    mtl_finish_gpu_at(WS_READTEX);
