        for (int z = 0; z < nz; z++)
            enc_b_copy_texture(b, s, sz0 + c->sr.zoffset + z, sl, MTLOriginMake(c->sr.xoffset, c->sr.yoffset, 0), MTLSizeMake(c->sr.width, c->sr.height, 1), d, dz0 + c->dr.zoffset + z, dl, MTLOriginMake(c->dr.xoffset, c->dr.yoffset, 0));
    // Diagnostic DM_NVN_T2T_TRACE=WxH:file: after each copy into an RGBA16F texture of that size, copy the result once more into a trace buffer on the GPU timeline (frame numbers kept on the CPU side); after 240 copies write the file
    { static int on = -1; static uint32_t tw, th; static const char *tf; static id<MTLBuffer> tb; static int tn; static uint64_t tfr[240], from;
      if (on < 0) { const char *e = getenv("DM_NVN_T2T_TRACE"), *fe = getenv("DM_NVN_T2T_FROM"); on = e && sscanf(e, "%ux%u", &tw, &th) == 2 && (tf = strchr(e, ':')) && *++tf; from = fe ? strtoull(fe, NULL, 10) : 0; }
      if (on > 0 && tn < 240 && atomic_load(&g_cur_frame) >= from && d.width == tw && d.height == th && d.pixelFormat == MTLPixelFormatRGBA16Float && !s3) {
          if (!tb) { tb = [g_dev newBufferWithLength:(size_t)240 * tw * th * 8 options:MTLResourceStorageModeShared]; res_add(tb); }
          enc_b_copy_texture_buffer(blit(), d, dz0, dl, MTLOriginMake(0, 0, 0), MTLSizeMake(tw, th, 1), tb, (size_t)tn * tw * th * 8, (size_t)tw * 8, (size_t)tw * th * 8);
          tfr[tn++] = atomic_load(&g_cur_frame);
          if (tn == 240) {
              rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
              mtl_finish_gpu();
              FILE *f = fopen(tf, "wb");
              if (f) { fprintf(f, "%u %u %d\n", tw, th, tn); fwrite(tfr, 8, 240, f); fwrite(tb.contents, 1, (size_t)240 * tw * th * 8, f); fclose(f); }
              MLOG("[t2t-trace] %d copies → %s (frames %llu–%llu)", tn, tf, (unsigned long long)tfr[0], (unsigned long long)tfr[239]);
          }
      }
    }
    return d;
}
// The destination's written region reaches its storage too when the CPU can read it (gsb_store), after the copy in command order: a 3D destination's planes from the region's z, any
// other's layers from the view's first
static void copy_t2t(const p_copy_t2t *c) {
    id<MTLTexture> d = copy_t2t_enc(c);
    if (d) fam_mark_valid(d);   // its size's blocks are the family heap's now (copy_t2t_enc made a partial destination valid first)
    if (d) gsb_store(c->dst, d, c->has_dv && c->dv.set_levels ? c->dv.base_level : 0, (c->dst->d.target == NVN_TEXTURE_TARGET_3D ? 0 : c->has_dv && c->dv.set_layers ? c->dv.min_layer : 0) + (unsigned)c->dr.zoffset,
                     (unsigned)(c->dr.depth ? c->dr.depth : 1), &c->dr);
}

// NVN2's DLSS on MetalFX's temporal scaler, one scaler per network and set of formats and sizes (hle_nvn.c "NVN2's DLSS"). The flags are NGX's feature flags (the game passes 0x2000000a: motion
// vectors at the input's size, inverted depth, with 0x40 for its DLSSAutoExposure). Where MetalFX takes no scaler for the formats, or a depth or motion texture is missing, the input is scaled
// bilinearly into the output with a red line: the frame stays whole, without the temporal gain.
// NGX's MVLowRes (motion vectors at the input's size; without it they are at the output's) and MVJittered (the vectors include the camera jitter, which the scaler then subtracts using
// jitterOffsetX/Y) are MetalFX's outputResolutionMotionVectorsEnabled (inverted) and jitteredMotionVectorsEnabled (macOS / iOS 27). The flags are in the scaler's key, so a network whose flags change gets a scaler of its own
enum { DLSS_F_MV_LOW_RES = 1 << 1, DLSS_F_MV_JITTERED = 1 << 2, DLSS_F_DEPTH_INVERTED = 1 << 3, DLSS_F_AUTO_EXPOSURE = 1 << 6 };
// The networks are named by their serials (hle_nvn.c nvnDlssNetworkInitialize), so one made again in the same memory is another network here. A scaler retired on
// nvnDlssNetworkFinalize (mtl_dlss_forget) or evicted when the cache is full (Fast Fusion had made 8 networks by its 9th minute) is held until this submission completes
// (defer_obj_release): a Metal 4 command buffer does not retain what is encoded into it, and the network's earlier evaluations in the submission still use it. Dropped at once, the
// commit crashed in -[_MTL4MachineLearningCommandEncoder encodeToCommandQueue:] ("-[AGXG17XFamilyMLContext executable]: unrecognized selector"). When all slots are full, a new
// entry takes the slot used least recently: slot 0 was always taken, which could be the network the game was drawing with
// DLSS's bias-current-colour mask is MetalFX's reactive mask: both run from 0 (the network's own history) to 1 (the current colour alone, history ignored), in the input's
// pixels, so the scaler is made for the mask's format (a part of its key) and takes its texture and corner (Star Fox: R8, 0 or 1, over a band at the top and bottom of its
// cinematics). A mask format MetalFX makes no scaler for is dropped with a red line and the scaler made without it (mask 0 everywhere), rather than losing the scaler to the
// bilinear stand-in. Upstream NXNative 23790f8dc (PR #1904)
// MetalFX's temporal scaler writes alpha 1 even when its RGBA input has another alpha; NVN2 DLSS keeps all four colour channels (upstream NXNative 1db4bcb28: Fast Fusion's
// selector background and interface hidden). After MetalFX has produced RGB, the input's alpha is drawn over its output with an alpha-only write mask (copy.metal fsa). The
// pipeline and argument table are host objects used only inside rec_cb_block, on the real command buffer
static id<MTL4ArgumentTable> g_dlss_alpha_at;
static id<MTLSamplerState> g_dlss_alpha_samp;
static id<MTLRenderPipelineState> dlss_alpha_pso(MTLPixelFormat pf) {
    static NSMutableDictionary<NSNumber *, id<MTLRenderPipelineState>> *cache; static id<MTLLibrary> lib; static int failed;
    if (failed) return nil;
    if (!cache) {
        NSError *e = nil; lib = host_lib("copy", &e);
        MTL4ArgumentTableDescriptor *ad = [MTL4ArgumentTableDescriptor new]; ad.maxTextureBindCount = 1; ad.maxSamplerStateBindCount = 1; ad.maxBufferBindCount = 1;
        g_dlss_alpha_at = lib ? [g_dev newArgumentTableWithDescriptor:ad error:&e] : nil;
        MTLSamplerDescriptor *sd = [MTLSamplerDescriptor new]; sd.minFilter = sd.magFilter = MTLSamplerMinMagFilterLinear;
        sd.sAddressMode = sd.tAddressMode = MTLSamplerAddressModeClampToEdge; sd.supportArgumentBuffers = YES;
        g_dlss_alpha_samp = [g_dev newSamplerStateWithDescriptor:sd];
        if (!lib || !g_dlss_alpha_at || !g_dlss_alpha_samp) {
            failed = 1; MLOG("[RED] DLSS: cannot create the alpha-preserving pass: %s; scaling bilinearly", e ? e.localizedDescription.UTF8String : "no error given"); return nil;
        }
        cache = [NSMutableDictionary dictionary];
    }
    NSNumber *key = @(pf); id<MTLRenderPipelineState> ps = cache[key];
    if (!ps) {
        NSError *e = nil; const MTLColorWriteMask wm = MTLColorWriteMaskAlpha;
        ps = host_rps(lib, @"vs", @"fsa", 1, &pf, &wm, 1, &e);
        if (!ps) { MLOG("[RED] DLSS: cannot create the alpha-only pipeline for output format %lu: %s; scaling bilinearly", (unsigned long)pf, e ? e.localizedDescription.UTF8String : "no error given"); return nil; }
        cache[key] = ps;
    }
    return ps;
}

// One scaler per network and key (formats and sizes; NX 18 keys the input's content size), not one per network: a game with dynamic resolution renders into textures of a few sizes and steps between them every few
// seconds, and each synchronous build stalls the replay about 80 ms (Xenoblade Chronicles DE, 0400FF500E34A001: 1280x720 to 960x540, 191 builds and 190 frames of
// about 88 ms in 5 minutes of play). A kept scaler that becomes the network's current one again starts with a reset, as a new one does: its history is from another size.
// Finalized networks (mtl_dlss_forget) drop all their cached scalers via deferred release on the replay thread so dead networks do not pin GPU memory across slots.
typedef struct { uint64_t net, used; id<MTL4FXTemporalScaler> sc; NSUInteger key[10]; int fresh, mask, cur; } dlss_scaler;
// 12 kept on the Mac, as upstream; 6 on an iPhone, where each kept scaler's history textures stay resident (upstream e9bcc5f35's 12 were measured on a Mac only)
#if TARGET_OS_IPHONE
#define DLSS_KEEP 6
#else
#define DLSS_KEEP 12
#endif
static dlss_scaler g_dlss[DLSS_KEEP];
static uint64_t g_dlss_use;
static void dlss_scaler_drop(dlss_scaler *e) { if (e->sc) defer_obj_release(e->sc); e->sc = nil; }
static pthread_mutex_t g_dlss_retire_mu = PTHREAD_MUTEX_INITIALIZER;
static uint64_t *g_dlss_retire;
static size_t g_dlss_retire_n, g_dlss_retire_cap;
static _Atomic size_t g_dlss_retire_pending;
void mtl_dlss_forget(uint64_t serial) {
    if (!serial) return;
    pthread_mutex_lock(&g_dlss_retire_mu);
    if (g_dlss_retire_n == g_dlss_retire_cap) {
        size_t ncap = g_dlss_retire_cap ? g_dlss_retire_cap * 2 : 16;
        uint64_t *p = realloc(g_dlss_retire, ncap * sizeof *p);
        if (!p) { pthread_mutex_unlock(&g_dlss_retire_mu); return; }
        g_dlss_retire = p; g_dlss_retire_cap = ncap;
    }
    g_dlss_retire[g_dlss_retire_n++] = serial;
    atomic_store_explicit(&g_dlss_retire_pending, g_dlss_retire_n, memory_order_release);
    pthread_mutex_unlock(&g_dlss_retire_mu);
}
void dlss_retire_drain(void) {
    if (!atomic_load_explicit(&g_dlss_retire_pending, memory_order_acquire)) return;
    for (;;) {
        uint64_t batch[16]; size_t n = 0;
        pthread_mutex_lock(&g_dlss_retire_mu);
        n = g_dlss_retire_n < 16 ? g_dlss_retire_n : 16;
        if (n) {
            memcpy(batch, g_dlss_retire, n * sizeof *batch);
            g_dlss_retire_n -= n;
            if (g_dlss_retire_n) memmove(g_dlss_retire, g_dlss_retire + n, g_dlss_retire_n * sizeof *batch);
        }
        atomic_store_explicit(&g_dlss_retire_pending, g_dlss_retire_n, memory_order_release);
        pthread_mutex_unlock(&g_dlss_retire_mu);
        if (!n) break;
        for (size_t k = 0; k < n; k++) for (int i = 0; i < DLSS_KEEP; i++) {
            if (g_dlss[i].net != batch[k]) continue;
            dlss_scaler_drop(&g_dlss[i]);
            g_dlss[i].net = 0; g_dlss[i].used = 0; g_dlss[i].fresh = g_dlss[i].mask = g_dlss[i].cur = 0;
            memset(g_dlss[i].key, 0, sizeof g_dlss[i].key);
        }
    }
}
static dlss_scaler *dlss_scaler_for(const p_dlss *c, id<MTLTexture> col, id<MTLTexture> dep, id<MTLTexture> mot, id<MTLTexture> out, id<MTLTexture> bias, NSUInteger iw, NSUInteger ih) {
    dlss_retire_drain();
    NSUInteger key[10] = {col.pixelFormat, dep.pixelFormat, mot.pixelFormat, out.pixelFormat, bias ? bias.pixelFormat : 0, iw, ih, out.width, out.height, c->flags};
    dlss_scaler *e = NULL, *spare = NULL, *prev = NULL;
    for (int i = 0; i < DLSS_KEEP; i++) {
        dlss_scaler *s = &g_dlss[i];
        if (s->net == c->net && s->net && s->cur) prev = s;
        if (!e && s->net == c->net && s->net && !memcmp(s->key, key, sizeof key)) e = s;
        else if (!spare || (spare->net && (!s->net || s->used < spare->used))) spare = s;
    }
    if (!e) { e = spare; if (e == prev) prev = NULL; e->net = c->net; dlss_scaler_drop(e); memset(e->key, 0, sizeof e->key); e->cur = 0; }
    if (e != prev) { if (prev) prev->cur = 0; e->cur = 1; e->fresh = 1; }   // back to a kept scaler: its history is another size's
    e->used = ++g_dlss_use;
    if (!memcmp(e->key, key, sizeof key)) return e->sc ? e : NULL;
    memcpy(e->key, key, sizeof key); dlss_scaler_drop(e); e->fresh = 1;
    id<MTL4Compiler> comp = mtl_comp4();   // the host's one compiler (g_comp4)
    float scale = (float)out.width / (float)iw;
    MTLFXTemporalScalerDescriptor *d = [MTLFXTemporalScalerDescriptor new];
    d.colorTextureFormat = col.pixelFormat; d.depthTextureFormat = dep.pixelFormat; d.motionTextureFormat = mot.pixelFormat; d.outputTextureFormat = out.pixelFormat;
    d.inputWidth = iw; d.inputHeight = ih; d.outputWidth = out.width; d.outputHeight = out.height;
    d.autoExposureEnabled = (c->flags & DLSS_F_AUTO_EXPOSURE) != 0;
    // Build the final upscaler now, not in the background. With the default (NO), MetalFX hands back an interim upscaler and swaps in the one it compiles behind it; on
    // Xenoblade Chronicles: Definitive Edition – Nintendo Switch 2 Edition (0400FF500E34A001, 2.0.0; M2 Pro, macOS 27.3 26C5035r) that swap failed every run on the 97th
    // evaluation of the fourth scaler the game's dynamic resolution made in its first second: MPSGraph's ANE region asserted `ANE inference operation failed`
    // (Code=-19, inferenceCount 96) and aborted; with MTL_ERROR_MODE=nslog the GPU command buffer waiting on that inference timed out instead and macOS revoked GPU
    // access. Built synchronously, the same boot ran 2,697 evaluations to its time limit, and the frames that make the scalers took no longer
    d.requiresSynchronousInitialization = YES;
    d.outputResolutionMotionVectorsEnabled = !(c->flags & DLSS_F_MV_LOW_RES); d.jitteredMotionVectorsEnabled = (c->flags & DLSS_F_MV_JITTERED) != 0;
    d.inputContentPropertiesEnabled = YES; d.inputContentMinScale = scale; d.inputContentMaxScale = scale;
    const int fx = comp && [MTLFXTemporalScalerDescriptor supportsMetal4FX:g_dev];
    e->mask = bias != nil;
    if (bias) { d.reactiveMaskTextureEnabled = YES; d.reactiveMaskTextureFormat = bias.pixelFormat; }
    e->sc = fx ? [d newTemporalScalerWithDevice:g_dev compiler:comp] : nil;
    if (fx && !e->sc && bias) {
        MLOG("[RED] DLSS: MetalFX makes no temporal scaler with a reactive mask of format %lu; the game's bias mask is dropped", (unsigned long)bias.pixelFormat);
        d.reactiveMaskTextureEnabled = NO; e->mask = 0;
        e->sc = [d newTemporalScalerWithDevice:g_dev compiler:comp];
    }
    if (!e->sc) MLOG("[RED] DLSS: MetalFX makes no temporal scaler for colour format %lu, depth %lu, motion %lu, output %lu, %lux%lu → %lux%lu; scaling bilinearly", (unsigned long)col.pixelFormat, (unsigned long)dep.pixelFormat,
                     (unsigned long)mot.pixelFormat, (unsigned long)out.pixelFormat, (unsigned long)iw, (unsigned long)ih, (unsigned long)out.width, (unsigned long)out.height);
    else MLOG("DLSS: MetalFX temporal scaler %lux%lu → %lux%lu, colour format %lu, depth %lu, motion %lu, output %lu, reactive mask %lu", (unsigned long)iw, (unsigned long)ih, (unsigned long)out.width, (unsigned long)out.height,
              (unsigned long)col.pixelFormat, (unsigned long)dep.pixelFormat, (unsigned long)mot.pixelFormat, (unsigned long)out.pixelFormat, e->mask ? (unsigned long)bias.pixelFormat : 0ul);
    return e->sc ? e : NULL;
}
// MetalFX's Metal 4 scalers open encoders of their own with no barrier, before or after their work. Before them, in the replay's command buffer: an encoder that waits for the
// queue's earlier work and holds the queue's later work (the scaler's encoders) behind its own, a copy of one word of a scratch buffer. Barriers around no work order nothing
// (An encoder of barriers alone orders nothing, docs/reference/rendering.md): behind an empty encoder of them a scaler read what a slow pass just before was still writing, in
// every round of t_dlss_mfx and t_upscaler_mfx, and behind the word none did. The next draw pass then takes its consumer barrier (the relaxed end cleared, enc_r_begin_pass),
// which orders it after the scaler. The present's scaler (fx_encode) already waits behind its real copy of the crop. Upstream NXNative b25b651b
static void mfx_order(void) {
    static id<MTLBuffer> word; static dispatch_once_t once;
    dispatch_once(&once, ^{ word = [g_dev newBufferWithLength:16 options:MTLResourceStorageModePrivate]; word.label = @"MetalFX order word"; res_add(word); res_commit(); });
    id<MTL4ComputeCommandEncoder> ce = [g_cb computeCommandEncoder];
    [ce barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageBlit visibilityOptions:resource_vis()];
    [ce copyFromBuffer:word sourceOffset:0 toBuffer:word destinationOffset:8 size:4];
    [ce barrierAfterStages:MTLStageBlit beforeQueueStages:MTLStageAll visibilityOptions:resource_vis()];
    [ce endEncoding];
    atomic_store_explicit(&g_last_end_relaxed, 0, memory_order_relaxed);   // upstream's place for the clear; dlss_eval and up_mfx_encode keep NX 18's own clear after the scaler too (on purpose: the scaler is encoded between)
}
static void fg_capture_dlss(const p_dlss *a, id<MTLTexture> dep, id<MTLTexture> mot, NSUInteger iw, NSUInteger ih, int reset);   // frame generation (nvn_framegen.inc)
static void dlss_eval(const p_dlss *c) {
    rp_flush();   // the passes before it land first: they write its inputs
    id<MTLTexture> col = c->tex[DLSS_COLOR] ? tex_mtl(c->tex[DLSS_COLOR]) : nil, dep = c->tex[DLSS_DEPTH] ? tex_mtl(c->tex[DLSS_DEPTH]) : nil, mot = c->tex[DLSS_MOTION] ? tex_mtl(c->tex[DLSS_MOTION]) : nil,
                   out = c->tex[DLSS_OUTPUT] ? tex_mtl(c->tex[DLSS_OUTPUT]) : nil, bias = c->tex[DLSS_BIAS] ? tex_mtl(c->tex[DLSS_BIAS]) : nil;
    if (!col || !out) { static int once; if (!once++) MLOG("[RED] DLSS evaluated without %s", col ? "an output" : "an input colour"); return; }
    sc_forget(out);   // MetalFX or the stand-in writes it (sc_note)
    NSUInteger iw = c->iw > 0 ? (NSUInteger)c->iw : col.width, ih = c->ih > 0 ? (NSUInteger)c->ih : col.height;
    if (bias && (c->base[DLSS_BIAS][0] < 0 || c->base[DLSS_BIAS][1] < 0 || (NSUInteger)c->base[DLSS_BIAS][0] + iw > bias.width || (NSUInteger)c->base[DLSS_BIAS][1] + ih > bias.height)) {
        static int once; if (!once++) MLOG("[RED] DLSS: the bias mask's %lux%lu texture does not hold the %lux%lu input at %d,%d; the mask is not used", (unsigned long)bias.width, (unsigned long)bias.height,
                                      (unsigned long)iw, (unsigned long)ih, c->base[DLSS_BIAS][0], c->base[DLSS_BIAS][1]);
        bias = nil;
    }
    rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    // Diagnostic DM_NVN_DLSS_BILINEAR=1 (off by default): every evaluation takes the bilinear stand-in below, to tell MetalFX's part in a GPU fault or stall
    static int bilinear = -1; if (bilinear < 0) { const char *be = getenv("DM_NVN_DLSS_BILINEAR"); bilinear = be && atoi(be); if (bilinear) MLOG("DM_NVN_DLSS_BILINEAR: DLSS drawn bilinear (diagnostic)"); }
    dlss_scaler *e = dep && mot && !bilinear ? dlss_scaler_for(c, col, dep, mot, out, bias, iw, ih) : NULL;
    int keep_alpha = (mtl_pf_chmask(out.pixelFormat) & 8) != 0;
    id<MTLRenderPipelineState> alpha_ps = e && keep_alpha ? dlss_alpha_pso(out.pixelFormat) : nil;
    if (e && keep_alpha && !alpha_ps) e = NULL;   // a bilinear draw keeps all channels; never take MetalFX's opaque output when alpha cannot be restored
    if (!e) {
        NVNcopyRegion sr = {c->base[DLSS_COLOR][0], c->base[DLSS_COLOR][1], 0, (int)iw, (int)ih, 1}, dr = {c->base[DLSS_OUTPUT][0], c->base[DLSS_OUTPUT][1], 0, (int)out.width, (int)out.height, 1};
        if (!(out.usage & MTLTextureUsageRenderTarget) && !mtl_fmt_block(out.pixelFormat) && !fmt_int_or_ds(out.pixelFormat)) out = tex_upgrade(c->tex[DLSS_OUTPUT], out, MTLTextureUsageRenderTarget, out.pixelFormat);
        fam_prepare_write(out, !c->base[DLSS_OUTPUT][0] && !c->base[DLSS_OUTPUT][1]);   // as for MetalFX's output below
        if (!copy_t2t_draw(col, out, 0, 0, 0, 0, &sr, &dr, 1, 0)) { static int once; if (!once++) MLOG("[RED] DLSS: the bilinear stand-in could not draw format %lu into format %lu", (unsigned long)col.pixelFormat, (unsigned long)out.pixelFormat); }
        return;
    }
    id<MTL4FXTemporalScaler> sc = e->sc;
    MTLTextureUsage col_use = sc.colorTextureUsage | (keep_alpha ? MTLTextureUsageShaderRead : 0);
    MTLTextureUsage out_use = sc.outputTextureUsage | (keep_alpha ? MTLTextureUsageRenderTarget : 0);
    if ((col.usage & col_use) != col_use) col = tex_upgrade(c->tex[DLSS_COLOR], col, col_use, col.pixelFormat);
    if ((dep.usage & sc.depthTextureUsage) != sc.depthTextureUsage) dep = tex_upgrade(c->tex[DLSS_DEPTH], dep, sc.depthTextureUsage, dep.pixelFormat);
    if ((mot.usage & sc.motionTextureUsage) != sc.motionTextureUsage) mot = tex_upgrade(c->tex[DLSS_MOTION], mot, sc.motionTextureUsage, mot.pixelFormat);
    if ((out.usage & out_use) != out_use) out = tex_upgrade(c->tex[DLSS_OUTPUT], out, out_use, out.pixelFormat);
    if (!e->mask) bias = nil;
    if (bias && (bias.usage & sc.reactiveMaskTextureUsage) != sc.reactiveMaskTextureUsage) bias = tex_upgrade(c->tex[DLSS_BIAS], bias, sc.reactiveMaskTextureUsage, bias.pixelFormat);
    id<MTLTexture> expo = c->tex[DLSS_EXPOSURE] ? tex_mtl(c->tex[DLSS_EXPOSURE]) : nil;
    if (fg_on()) fg_capture_dlss(c, dep, mot, iw, ih, c->reset || e->fresh);   // frame generation's depth and motion (copies, so the game may reuse its textures)
    if (g_blit) { enc_b_end(g_blit); g_blit = nil; }   // a usage upgrade copies through it
    ubd_land_compute();
    mfx_order();   // the scaler after the frame's work so far: MetalFX opens encoders of its own, which take no barrier
    const p_dlss a = *c; const int reset = c->reset || e->fresh; e->fresh = 0;
    // The scaler's RGB extent: the record's ow/oh keep the builder's original size after NetworkResize (upstream: Star Fox, a 1920x1080 builder, a 960x540 output texture)
    id<MTLBuffer> alpha_pb = nil; size_t alpha_po = 0; const NSUInteger ow = sc.outputWidth, oh = sc.outputHeight;
    if (keep_alpha) {
        int sx = c->base[DLSS_COLOR][0], sy = c->base[DLSS_COLOR][1], dx = c->base[DLSS_OUTPUT][0], dy = c->base[DLSS_OUTPUT][1];
        if (sx < 0 || sy < 0 || dx < 0 || dy < 0 || (NSUInteger)sx + iw > col.width || (NSUInteger)sy + ih > col.height || (NSUInteger)dx + ow > out.width || (NSUInteger)dy + oh > out.height) {
            static int once; if (!once++) MLOG("[RED] DLSS: alpha-preserving rectangles are out of bounds; alpha is left as MetalFX wrote it");
            keep_alpha = 0;
        } else {   // p[0] the source origin and texels per output texel, p[1] the output origin and the source size, p[2] the input content's texel centres (copy.metal fsa)
            alpha_po = arena_alloc(48, &alpha_pb);
            float *p = (float *)((uint8_t *)alpha_pb.contents + alpha_po);
            p[0] = sx; p[1] = sy; p[2] = (float)iw / ow; p[3] = (float)ih / oh;
            p[4] = dx; p[5] = dy; p[6] = col.width; p[7] = col.height;
            p[8] = sx + 0.5f; p[9] = sy + 0.5f; p[10] = sx + iw - 0.5f; p[11] = sy + ih - 0.5f;
        }
    }
    // An output of a compressed resolution family whose heap holds another size: written whole, it takes the heap over; in part, it is zeroed whole first (fam_prepare_write)
    int dlss_full = !c->base[DLSS_OUTPUT][0] && !c->base[DLSS_OUTPUT][1] && ow == out.width && oh == out.height;
    fam_prepare_write(out, dlss_full);
    // On the real command buffer, the scaler's state set with it: on the encoding thread when it runs (the recording's stand-in has none of MetalFX's calls), where a later
    // evaluation through the same scaler may already have been recorded
    rec_cb_block(g_cb, ^(id<MTL4CommandBuffer> cb) {
        sc.colorTexture = col; sc.depthTexture = dep; sc.motionTexture = mot; sc.outputTexture = out; sc.exposureTexture = expo; sc.reactiveMaskTexture = bias;
        sc.inputContentWidth = iw; sc.inputContentHeight = ih;
        sc.colorContentOffsetX = (NSUInteger)a.base[DLSS_COLOR][0]; sc.colorContentOffsetY = (NSUInteger)a.base[DLSS_COLOR][1];   // the rectangles' corners
        sc.depthContentOffsetX = (NSUInteger)a.base[DLSS_DEPTH][0]; sc.depthContentOffsetY = (NSUInteger)a.base[DLSS_DEPTH][1];
        sc.motionContentOffsetX = (NSUInteger)a.base[DLSS_MOTION][0]; sc.motionContentOffsetY = (NSUInteger)a.base[DLSS_MOTION][1];
        if (bias) { sc.reactiveMaskContentOffsetX = (NSUInteger)a.base[DLSS_BIAS][0]; sc.reactiveMaskContentOffsetY = (NSUInteger)a.base[DLSS_BIAS][1]; }
        sc.outputOffsetX = (NSUInteger)a.base[DLSS_OUTPUT][0]; sc.outputOffsetY = (NSUInteger)a.base[DLSS_OUTPUT][1];
        sc.motionVectorScaleX = a.mv[0]; sc.motionVectorScaleY = a.mv[1];
        sc.jitterOffsetX = a.jitter[0]; sc.jitterOffsetY = a.jitter[1];
        sc.preExposure = a.pre_exposure;
        sc.depthReversed = (a.flags & DLSS_F_DEPTH_INVERTED) != 0;
        sc.reset = reset;
        [sc encodeToCommandBuffer:cb];
        if (keep_alpha) {
            MTL4RenderPassDescriptor *rp = [MTL4RenderPassDescriptor new];
            rp.colorAttachments[0].texture = out; rp.colorAttachments[0].loadAction = MTLLoadActionLoad; rp.colorAttachments[0].storeAction = MTLStoreActionStore;
            id<MTL4RenderCommandEncoder> en = [cb renderCommandEncoderWithDescriptor:rp];
            [en barrierAfterQueueStages:MTLStageAll beforeStages:hb_frag() visibilityOptions:resource_vis()];   // copy.metal vs: no vertex reads (see hb_on)
            [en setArgumentTable:g_dlss_alpha_at atStages:MTLRenderStageFragment];
            [g_dlss_alpha_at setTexture:col.gpuResourceID atIndex:0]; [g_dlss_alpha_at setSamplerState:g_dlss_alpha_samp.gpuResourceID atIndex:0];
            [g_dlss_alpha_at setAddress:alpha_pb.gpuAddress + alpha_po atIndex:0];
            [en setViewport:(MTLViewport){a.base[DLSS_OUTPUT][0], a.base[DLSS_OUTPUT][1], ow, oh, 0, 1}];
            [en setScissorRect:(MTLScissorRect){(NSUInteger)a.base[DLSS_OUTPUT][0], (NSUInteger)a.base[DLSS_OUTPUT][1], ow, oh}];
            [en setRenderPipelineState:alpha_ps]; [en drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3]; m4_end(en);
        }
    });
    // The next draw pass waits for the scaler whole (enc_r_begin_pass), as after the spatial upscaler (up_mfx_encode): MetalFX's encoders take no barrier, and the relaxed end of the
    // draw pass before it (rp_end above, draw_barriers game) orders only that pass's own work
    atomic_store_explicit(&g_last_end_relaxed, 0, memory_order_relaxed);
}

// The colour channels a Metal format has, as a channel write mask: a clear whose mask covers them all writes every texel whole (FINAL FANTASY TACTICS - The Ivalice Chronicles clears an
// R8 render target with mask 0x1)
static unsigned mtl_pf_chmask(MTLPixelFormat pf) {
    switch ((int)pf) {
        case 1: return 0x8;                                                                                      // A8
        case 10: case 11: case 12: case 13: case 14: case 20: case 22: case 23: case 24: case 25: case 53: case 54: case 55: return 0x1;   // R8 / R16 / R32
        case 30: case 31: case 32: case 33: case 34: case 60: case 62: case 63: case 64: case 65: case 103: case 104: case 105: return 0x3;   // RG8 / RG16 / RG32
        case 40: case 92: case 93: return 0x7;                                                                   // B5G6R5 / RG11B10F / RGB9E5
    }
    return 0xf;
}
// Whether a texture clear covers only a part of the level (w x h) or of the channels of pf, the format it clears in: clear_tex draws a triangle for it in a colour format and
// nothing in a depth or stencil one (red line 44)
static int clear_tex_part(const p_clear_tex *c, NSUInteger w, NSUInteger h, MTLPixelFormat pf) {
    return c->r.xoffset || c->r.yoffset || (NSUInteger)c->r.width != w || (NSUInteger)c->r.height != h || (c->mask & mtl_pf_chmask(pf)) != mtl_pf_chmask(pf);
}
// A texture clear of a lazy depth texture t: one clear_tex writes nothing for (a part or a channel mask in a depth format, red line 44; a view format with no Metal format, red
// line 42) maps nothing; one of the whole level to 0 maps nothing either (an unmapped tile reads 0, and the mapped ones are cleared), one to another depth makes it a normal
// texture first (lz_whole); any other (a colour view, a view of another level or layer) maps every tile, as before. Returns the texture to clear
static id<MTLTexture> lz_tex_clear(const p_clear_tex *c, id<MTLTexture> t) {
    id<MTLTexture> root = nil; NvLazy *z = lz_of(t, &root);
    if (!z) return t;
    uint32_t vpf = 0; uint8_t swz[4];
    MTLPixelFormat pf = !(c->has_view && c->view.set_format) ? t.pixelFormat : nvn_fmt_to_mtl(c->view.format, &vpf, swz) ? (MTLPixelFormat)vpf : MTLPixelFormatInvalid;   // as clear_tex clears it
    unsigned lv = c->has_view && c->view.set_levels ? c->view.base_level : 0;
    int part = clear_tex_part(c, MAX(t.width >> lv, 1u), MAX(t.height >> lv, 1u), pf);
    if (pf == MTLPixelFormatInvalid || (part && mtl_fmt_depth(pf))) return t;   // nothing written, so no tile (a clear of part of a 12288x12288 Depth16 mapped and zeroed 4,608)
    int whole = t == root && pf == root.pixelFormat && !part && !(c->has_view && ((c->view.set_levels && c->view.base_level) || (c->view.set_layers && c->view.min_layer)))
             && !c->r.zoffset && c->r.depth <= 1;
    if (!whole) { lz_map_all(z, root, "a texture clear"); return t; }
    double cd = root.pixelFormat == MTLPixelFormatDepth16Unorm ? nvn_depth16_clear_value(c->c.f[0]) : c->c.f[0];   // what the clear pass is given (clear_tex)
    if (cd == 0) return t;
    id<MTLTexture> w = lz_whole(c->tex, root, "a texture clear to a non-zero depth");
    return w ? w : t;
}
// GPU: clear a texture region with the given value (previously mislisted as a no-op, called 5 times at initialization; the initial value of a Metal private texture is undefined, and the game relies on the cleared initial value).
// Whole level and whole face, all four channels written -> open one clear-only render pass per layer / depth slice (the hardware converts the clear value by the texture format, including integer and depth);
// View with changed format: clear on that view. Partial colour regions / channel masks use a triangle and preserve everything else.
static void clear_tex_tri(id<MTLTexture> t, unsigned lv, unsigned l0, const p_clear_tex *c);
static void clear_tex(const p_clear_tex *c) {
    id<MTLTexture> t = tex_mtl(c->tex); sparse_gpu_wrote(c->tex); tu_wrote(t); if (t && mtl_fmt_depth(t.pixelFormat)) g_fb_dclr++; t = lz_tex_clear(c, t);
    PD("X ser=%llu view format %#x region %d,%d,%d %dx%dx%d mask %#x %s %g,%g,%g,%g", c->tex ? c->tex->serial : 0ull, c->has_view && c->view.set_format ? c->view.format : -1, c->r.xoffset, c->r.yoffset, c->r.zoffset, c->r.width, c->r.height, c->r.depth, c->mask,
       c->is_uint ? "ui" : "f", c->is_uint ? (double)c->c.u[0] : c->c.f[0], c->is_uint ? (double)c->c.u[1] : c->c.f[1], c->is_uint ? (double)c->c.u[2] : c->c.f[2], c->is_uint ? (double)c->c.u[3] : c->c.f[3]);
    if (!t) return;
    unsigned lv = c->has_view && c->view.set_levels ? c->view.base_level : 0, l0 = c->has_view && c->view.set_layers ? c->view.min_layer : 0;
    NSUInteger w = MAX(t.width >> lv, 1u), h = MAX(t.height >> lv, 1u);
    int is3d = t.textureType == MTLTextureType3D, nz = c->r.depth ? c->r.depth : 1;
    if (!(t.usage & MTLTextureUsageRenderTarget) && !mtl_fmt_block(t.pixelFormat) && t.sampleCount == 1)
        t = tex_upgrade(c->tex, t, MTLTextureUsageRenderTarget, t.pixelFormat);   // a clear of a texture made without render-target use (packaged): give it that use
    if (c->has_view && c->view.set_format) {   // View with changed format: the clear value is interpreted in the view format (all 5 of the game's calls are the ui version with an integer view), and the clear is done on a view of the same format
        uint32_t vpf = 0; uint8_t swz[4];
        if (!nvn_fmt_to_mtl(c->view.format, &vpf, swz) || !vpf) { RED_ONCE(42, "texture clear view format %#x has no equivalent", c->view.format); return; }
        if (tex_need_pfv(t.pixelFormat, (MTLPixelFormat)vpf) && !(t.usage & MTLTextureUsagePixelFormatView)) t = tex_upgrade_pfv(c->tex, t, (MTLPixelFormat)vpf);
        if (tex_need_pfv(t.pixelFormat, (MTLPixelFormat)vpf)) {
            id<MTLTexture> v = [t newTextureViewWithPixelFormat:(MTLPixelFormat)vpf];
            if (!v) { RED_ONCE(43, "texture clear: cannot create the view: format %lu → %u", (unsigned long)t.pixelFormat, vpf); return; }
            t = v;
        }
    }
    id<MTLTexture> whole = t.parentTexture ? t.parentTexture : t;
    MTLPixelFormat pf = t.pixelFormat;
    int depth = pf == MTLPixelFormatDepth32Float || pf == MTLPixelFormatDepth16Unorm || pf == MTLPixelFormatDepth32Float_Stencil8, stencil = pf == MTLPixelFormatStencil8 || pf == MTLPixelFormatDepth32Float_Stencil8;
    if (clear_tex_part(c, w, h, pf) || !(t.usage & MTLTextureUsageRenderTarget)) {
        if (!depth && !stencil && (t.usage & MTLTextureUsageRenderTarget)) {
            fam_prepare_write(whole, 0);   // a part of a compressed family member whose heap holds another size: the member is zeroed whole first
            clear_tex_tri(t, lv, l0, c);
            gsb_store(c->tex, whole, lv, (is3d ? 0 : l0) + (unsigned)c->r.zoffset, (unsigned)nz, &c->r);   // the clear writes the storage too, as a render pass does (rt_mirror_flush)
            return;
        }
        RED_ONCE(44, "texture clear case not implemented: region %d,%d %dx%d (level size %lux%lu) mask %#x render-target capable %d (format %#x flags %#x)", c->r.xoffset, c->r.yoffset, c->r.width, c->r.height,
                 (unsigned long)w, (unsigned long)h, c->mask, !!(t.usage & MTLTextureUsageRenderTarget), c->tex->d.format, c->tex->d.flags);
        return;
    }
    rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    for (int z = 0; z < nz; z++) {
        MTL4RenderPassDescriptor *rp = [MTL4RenderPassDescriptor new];
        MTLRenderPassAttachmentDescriptor *a = depth ? rp.depthAttachment : stencil ? rp.stencilAttachment : rp.colorAttachments[0];
        a.texture = t; a.level = lv; a.loadAction = MTLLoadActionClear; a.storeAction = MTLStoreActionStore;
        if (is3d) a.depthPlane = c->r.zoffset + z; else a.slice = l0 + c->r.zoffset + z;
        if (depth) { rp.depthAttachment.clearDepth = pf == MTLPixelFormatDepth16Unorm ? nvn_depth16_clear_value(c->c.f[0]) : c->c.f[0];
            if (stencil) { rp.stencilAttachment.texture = t; rp.stencilAttachment.level = lv; rp.stencilAttachment.slice = a.slice; rp.stencilAttachment.loadAction = MTLLoadActionClear;
                           rp.stencilAttachment.storeAction = MTLStoreActionStore; rp.stencilAttachment.clearStencil = c->c.u[1]; } }
        else if (stencil) rp.stencilAttachment.clearStencil = c->c.u[0];
        else rp.colorAttachments[0].clearColor = c->is_uint ? MTLClearColorMake(c->c.u[0], c->c.u[1], c->c.u[2], c->c.u[3]) : MTLClearColorMake(c->c.f[0], c->c.f[1], c->c.f[2], c->c.f[3]);
        enc_r_end(enc_r_begin_frag(rp));
    }
    fam_mark_valid(whole);   // a whole clear: its size's blocks are the family heap's now
    if (depth || stencil) return;
    gsb_store(c->tex, whole, lv, (is3d ? 0 : l0) + (unsigned)c->r.zoffset, (unsigned)nz, &c->r);
}

// Context description of one submit (mtl_sub_commit takes one per submit and prints it into the failure line when the command buffer errors): for the GPU memory fault on the first frame entering Travincal, the failure line had only the sequence number and error code, and it was impossible to tell what was in that submit
static const char *cctx_snap(void) {
    static char b[320]; static uint64_t p_pass, p_up, p_reup, p_ser; uint64_t up = 0, reup = 0; mtl_pkg_stats(&up, &reup);
    pthread_mutex_lock(&g_deferred_mu); unsigned long nd = (unsigned long)g_deferred.count; pthread_mutex_unlock(&g_deferred_mu);
    snprintf(b, sizeof b, "frame %llu; since the last submission: passes +%llu, first texture uploads +%llu, re-uploads +%llu, serial table changes +%llu; deferred-release queue %lu",
             (unsigned long long)atomic_load(&g_cur_frame), (unsigned long long)(g_stat_pass - p_pass), (unsigned long long)(up - p_up), (unsigned long long)(reup - p_reup),
             (unsigned long long)(g_ser_gen - p_ser), nd);
    p_pass = g_stat_pass; p_up = up; p_reup = reup; p_ser = g_ser_gen; return b;
}
// When the game itself asks for 30 fps (pacing by the game's present interval, interval 2, hle_nvn.c) the display link runs at 30 Hz too: games whose logic counts frames, such as Engage, are not pulled up to 60 fps by the display link on iOS
__attribute__((weak)) int nvn_game_fps(void) { return 60; }   // hle_nvn.c provides the strong definition
int mtl_fps_target(void) { static int env = -2; if (env == -2) { const char *e = getenv("DM_FPS"); env = e ? atoi(e) : -1; if (env != 30 && env != 60) env = -1; else MLOG("DM_FPS=%d: frame rate pinned by the test switch", env); }
    int g = nvn_game_fps(); return env > 0 ? env : g == 30 || g == 120 ? g : 60; }
// Hand a submission to the GPU in segments (DM_NVN_CUT=draw count, 0 = off; default 64): when the game holds back the next frame's submit until this frame's GPU work is done (The Legend of Zelda: Breath of the Wild: the main thread's nvnSyncWait on the fence of the frame just submitted),
// the GPU sits idle for the milliseconds the host spends translating inside the submit (in the shrine each frame is GPU 13 ms + translation 7 ms back to back). Each time this many draws have accumulated, the command buffer encoded so far is committed between two passes: the GPU runs the earlier passes while the CPU translates the later ones.
// Cut only when no encoder is open and no pass is deferred / merged / hoisted; commit this batch's uploads first (later draws use them). The fence signal and completion work stay on the last segment only: the queue executes in commit order and every encoder starts with a queue barrier
// A buffer → texture copy is cut after as well, at the next pass boundary whatever the draw count (g_cut_copy, set by copy_b2t): on the Switch the GPU runs a submission's copies as soon as the
// submit returns, and a game may reuse the copy's source right after. Catherine: Full Body's resource thread writes the next texture into the staging block 64 ms after the main thread
// recorded a copy from it (main+0x305e64, frame start) and before that frame's submit had even returned: the host was building pipelines inside the submit for 300 ms, and committed the
// copy only at its end, so the subtitle band's gradient (BC3, 32x512) came out as the next texture's blocks. Committed at the first pass boundary, the copies run while the host encodes the rest
static int cut_draws(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_CUT"); v = e ? atoi(e) : 64; MLOG("segmented submission: a segment is submitted between passes every %d draws (DM_NVN_CUT, 0 = off)", v); } return v; }
static uint64_t g_cut_draw0, g_cuts, g_copy_cuts;
// The count starts with the submission (mtl_sub_begin). It used to start at the submission's first sub_cut, which only a render target change reaches (OP_SET_RT): the draws a
// submission makes into the target it inherited, before its first target change, were never counted, and the first segment came that many draws late
static void sub_cut_begin(void) { g_cut_draw0 = g_stat_draw; }
// DM_FSTEP_PROBE_RAMP=1 (default) / 0 / ab: a frame-step probe's grace is renewed while its frames keep getting cheaper (nvn_fstep.h FSTEP_RAMP), the time macOS's GPU clock takes to rise for the shorter deadline
static int probe_ramp_mode(void) { static int m = -1; if (m < 0) m = sw_mode("DM_FSTEP_PROBE_RAMP", 1); return m; }
int mtl_probe_ramp_on(void) { return sw_on(probe_ramp_mode()); }
// DM_FSTEP_GPU_RETRY=1 (default) / 0 / ab: where the failed probes' GPU ratio says the scene does not fit the shorter hold (nvn_fstep.h nvn_fgpu.ratio_at, upstream b1ba6570f), the
// GPU reference still starts a probe each FSTEP_PHOLD_MAX (32 s) since the last step up; 0 starts none while the scene costs the same (upstream's rule: fewer failed probes, but a
// scene whose clock follows the hold after a heavy one as slow at either hold stays at the longer hold until a load)
static int fstep_gpu_retry_mode(void) { static int m = -1; if (m < 0) m = sw_mode("DM_FSTEP_GPU_RETRY", 1); return m; }
int mtl_fstep_gpu_retry_on(void) { return sw_on(fstep_gpu_retry_mode()); }
// Whether a segment may end here, the pass aside: pass_split_try ends a pass only when the commit after it will be made
static int sub_cut_ready(void) {
    int n = cut_draws();
    return g_cb && (g_cut_copy || (n > 0 && g_stat_draw - g_cut_draw0 >= (uint64_t)n)) && !g_rt_merged;
}
// Whether earlier main work still runs, for a cut (sub_cut, pass_split_try). DM_NVN_CUT_EVENT=1 (default) with the encode thread on reads the GPU's own event behind each of the encode
// thread's commits, and the commits recorded but not yet on the queue (nvn_rec.h rec_gpu_busy), instead of the commit feedback's count (g_seg_inflight), which comes back 0.08-1.2 ms
// after the GPU's end: until then the replay kept the boundary and went on encoding into the open command buffer while the GPU sat idle, and with the frame a serial chain (the replay,
// then the encode thread, then the GPU: Ocarina of Time on a warm iPhone, GPU 31-41% busy) each late commit lengthened the frame. 0 reads the feedback count as before; ab alternates
// with the DM_AB phases. Without the encode thread nothing changes
static uint64_t g_cut_early, g_cut_kept, g_cut_held;   // cuts committed while the feedback count still had work (the event said the GPU had run out); boundaries kept with work running; cuts handed over to be held (DM_NVN_CUT_HOLD)
// DM_NVN_CUT_HOLD=1 (with the encode thread): a segment boundary whose earlier work still runs is cut all the same, and its command buffer goes to the encode thread to be held
// with the submissions it holds (DM_NVN_SUB_MERGE): they reach the queue together, in one commit call, the moment the GPU runs out of work (read from its event at each encoder's end,
// at each block of records and every 50 us while nothing is recorded). Kept open instead (0, the rule before), the boundary waited for the replay's next one 64 draws on, and for the
// end of a long pass, while the GPU sat idle; what the frame left after the replay's end was that whole segment. ab alternates with the DM_AB phases. Without the encode thread
// nothing changes. A copy's cut still commits at once
static int cut_hold_mode(void) { static int m = -1; if (m < 0) { m = sw_mode("DM_NVN_CUT_HOLD", 1); if (!m) MLOG("DM_NVN_CUT_HOLD=0: a segment boundary with earlier work running stays open"); } return m; }
static int cut_hold_on(void) { return rec_on() && g_rb_started && rx_merge_on() && sw_on(cut_hold_mode()); }
static int cut_event_mode(void) { static int m = -1; if (m < 0) { m = sw_mode("DM_NVN_CUT_EVENT", 1); if (!m) MLOG("DM_NVN_CUT_EVENT=0: a segment cut waits for the commit feedback of the work before it"); } return m; }
static int cut_busy(void) {
    if (rec_on() && g_rb_started && sw_on(cut_event_mode())) {
        return rec_gpu_busy();
    }
    return atomic_load_explicit(&g_seg_inflight, memory_order_relaxed) > 0;
}
static void sub_cut(void) {
    if (g_enc || !sub_cut_ready()) return;
    // The cut is there so that the GPU does not sit idle while the host encodes. With earlier work still running a commit gains nothing and queues one more command buffer: each is a call into the kernel on Metal's one submission queue, and with buffers queued behind running work
    // the GPU waited 5-40 ms with the next one already committed (docs/reference/frame-rate.md). So it stays a boundary for the game's timestamps (ts_boundary), with the commit left for when the GPU has run out. A copy still commits, as its data must land. DM_NVN_CUT_BUSY=0: every cut commits
    static int busy = -1; if (busy < 0) { const char *e = getenv("DM_NVN_CUT_BUSY"); busy = !e || atoi(e) != 0; }
    const int hold = !g_cut_copy && cut_hold_on();   // the encode thread may hold it while the GPU runs earlier work (DM_NVN_CUT_HOLD)
    if (busy && !g_cut_copy && (!seg_ts() || ts_on())) {
        if (cut_busy()) {
            if (!hold) {
                g_cut_kept++;
                if (ts_on()) { ts_boundary(); g_seg++; }
                g_cut_draw0 = g_stat_draw; return; }
            g_cut_held++;
        } else if (atomic_load_explicit(&g_seg_inflight, memory_order_relaxed) > 0) g_cut_early++;   // the feedback count would have kept it
    }
    if (ts_on()) ts_boundary();
    if (g_cut_copy) g_copy_cuts++;
    g_cut_copy = 0;
    cb_seal();   // before the segment's state list is taken
    uint64_t f = atomic_load(&g_cur_frame); gpu_tag_begin(f);
    uint32_t k = g_seg++; seg_clk *sc = NULL;   // reports encoded so far keep this segment's GPU times (seg_ts)
    if (seg_ts()) { if (!g_sclk) { g_sclk = calloc(1, sizeof *g_sclk); if (!g_sclk) MDIE("segment clock allocation failed"); atomic_store(&g_sclk->refs, 1); } sc = g_sclk; atomic_fetch_add(&sc->refs, 1); if (k < SEG_CLK_N) sc->cm[sc->ncm++] = (uint16_t)k; }   // this command buffer ends with segment k (seg_idle_before, sub_place)
    cbs_list *cbs = cbs_take(); uint64_t cbs_fence = g_fence + 1; cbs_fly_put(cbs_fence, cbs);
    DmCommitFB *o = [DmCommitFB new];
    atomic_fetch_add(&g_seg_inflight, 1);
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> cb) {
        fb_in("segment");
        atomic_fetch_sub(&g_seg_inflight, 1);
        gpu_tag_done(f, cb.GPUStartTime, cb.GPUEndTime); gpu_busy_note(cb.GPUStartTime, cb.GPUEndTime);
        if (sc) { if (k < SEG_CLK_N) { atomic_store(&sc->t[k][0], gpu_s_guest_ns(cb.GPUStartTime)); atomic_store(&sc->t[k][1], gpu_s_guest_ns(cb.GPUEndTime)); } seg_clk_put(sc); }
        if (cb.error) { atomic_store(&g_last_commit_error, 1); static int k; if (k++ < 8) MLOG("[RED] segment command buffer execution error: %s", cb.error.description.UTF8String); res_top_once(cb.error); victim_note(cb.error, "segment command buffer", 0); }
        char where[64]; snprintf(where, sizeof where, "fence %llu, segment %u", (unsigned long long)cbs_fence, k); cbs_feedback(cbs, cb.error, where);
        gpu_lost_check(cb.error, "segment");
        fb_out();
    }];
    cb_commit(o, hold ? 2 : 0);   // 2: a segment the encode thread holds while the GPU has work (nvn_rec.h RO_COMMIT), as it holds a submission's end
    if (rec_on()) rec_publish();   // the segment reaches the encode thread now, not when its block of records fills
    g_cb = rec_cb_new();
    [g_cb beginCommandBufferWithAllocator:g_alloc4[g_alloc_cur]];   // one allocator encodes several command buffers in sequence; it is reset only once its fence (the last segment) has passed, when a later submission starts
    g_cut_draw0 = g_stat_draw;
    if (!g_cuts++) MLOG("segmented submission: first segment submitted at frame %llu pass %llu", (unsigned long long)f, (unsigned long long)g_stat_pass);
}
// A long render pass is one segment: Breath of the Wild draws 2,700 of its 4,100 draws a frame into the G-buffer, and the GPU, done with the shadow passes before it,
// waited for the whole pass to be translated (about 2.5 ms of the 9 ms frame at 120 fps on the Mac). With no segment left on the GPU and DM_NVN_PASS_SPLIT draws (default 256,
// 0 = off) encoded since the last cut, the pass is ended (its attachments stored), the segment committed, and the next draw opens the pass again, loading them. Each split
// costs a store and a load of the attachments, so it is taken only while the GPU would otherwise wait
// A split is taken only when sub_cut will commit after it (sub_cut_ready): otherwise the pass would be
// stored and loaded for nothing (DM_NVN_CUT=0, or above DM_NVN_PASS_SPLIT)
static uint64_t g_pass_splits, g_split_pass; static int g_split_n;   // g_split_n: splits of the pass g_split_pass so far
// NX 18: on by default on the Mac only. On an iPhone each split stores and loads the attachments again (memory traffic, power), so it stays off there until a battery A/B on
// Breath of the Wild and Ocarina of Time (DM_NVN_PASS_SPLIT=256 on, unset or 0 off)
static int pass_split_draws(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_PASS_SPLIT"); v = e && *e ? atoi(e) : TARGET_OS_IPHONE ? 0 : 256; } return v; }
static int pass_split_max(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_NVN_PASS_SPLIT_MAX"); v = e ? atoi(e) : 2; } return v; }   // per NVN pass: each split stores and loads its attachments
static void pass_split_try(void) {
    int n = pass_split_draws();
    if (n <= 0 || !g_enc || g_stat_draw - g_cut_draw0 < (uint64_t)n || !sub_cut_ready() || cut_busy()) return;
    if (g_sm_pass) return;
    if (g_split_pass != g_setrt_n) { g_split_pass = g_setrt_n; g_split_n = 0; }
    if (pass_split_max() > 0 && g_split_n >= pass_split_max()) return;
    g_split_n++;
    rp_end();
    sub_cut(); g_split_resume = 1;
    if (!g_pass_splits++) MLOG("pass split: a long render pass was ended and its segment committed while the GPU had nothing to do (DM_NVN_PASS_SPLIT=%d, frame %llu pass %llu)", n, (unsigned long long)atomic_load(&g_cur_frame), g_stat_pass);
}
uint64_t mtl_pass_splits(void) { return g_pass_splits; }
uint64_t mtl_cut_count(void) { return g_cuts; }
void mtl_cut_stats(uint64_t v[4]) { v[0] = g_cuts; v[1] = g_cut_early; v[2] = g_cut_kept; v[3] = g_cut_held; }   // the segments line (hle_nvn.c): cuts committed, of them early by the event, boundaries kept, cuts handed over to be held
uint64_t mtl_copy_cut_count(void) { return g_copy_cuts; }

// ---------- Clears a load action cannot express ----------
// A colour clear issued inside an open render pass, with a partial channel mask or with a scissor smaller than the target, and a depth / stencil clear with a scissor inside an
// open pass (Tears of the Kingdom issues all of them) are drawn as one triangle over the whole pass in the render encoder. It writes the clear value into the masked channels of
// that attachment, or the depth / the stencil bits of the clear's write mask, inside the scissor, with the depth test ALWAYS and no visibility counting. The value is read from
// the frame arena through the triangle's own argument tables (the draws' g_vt / g_ft are put back after it), so the pipelines depend only on the pass formats, the slot and the
// mask. Clears the load action expresses keep it. Adapted from MacNativeGames' clear_quad / clear_ds_quad (github.com/ly05010419/MacNativeGames, MIT).
static int pf_int_kind(MTLPixelFormat f) {   // the fragment output type a colour attachment takes: 0 float (also normalized), 1 uint, 2 int
    switch (f) {
        case MTLPixelFormatR8Uint: case MTLPixelFormatR16Uint: case MTLPixelFormatR32Uint: case MTLPixelFormatRG8Uint: case MTLPixelFormatRG16Uint: case MTLPixelFormatRG32Uint:
        case MTLPixelFormatRGBA8Uint: case MTLPixelFormatRGB10A2Uint: case MTLPixelFormatRGBA16Uint: case MTLPixelFormatRGBA32Uint: return 1;
        case MTLPixelFormatR8Sint: case MTLPixelFormatR16Sint: case MTLPixelFormatR32Sint: case MTLPixelFormatRG8Sint: case MTLPixelFormatRG16Sint: case MTLPixelFormatRG32Sint:
        case MTLPixelFormatRGBA8Sint: case MTLPixelFormatRGBA16Sint: case MTLPixelFormatRGBA32Sint: return 2;
        default: return 0;
    }
}
static id<MTLLibrary> clr_lib(void) {   // clr_vs (the triangle, depth from buffer 0) and clr_fs_<slot>_<float|uint|int> (that colour slot's value from buffer 0): dm/gfx/msl/clear.metal
    static id<MTLLibrary> lib; static int failed;
    if (lib || failed) return lib;
    NSError *e = nil; lib = host_lib("clear", &e);
    if (!lib) { failed = 1; MLOG("[RED] clear-triangle shaders: no library: %s", e.localizedDescription.UTF8String); }
    return lib;
}
typedef struct { int32_t slot, kind, mask; uint32_t cfmt[8], dfmt, sfmt, samples; } clr_key;   // slot -1: a depth / stencil clear (the host's empty fragment function)
static id<MTLRenderPipelineState> clr_pso(const clr_key *k) {
    static NSMutableDictionary<NSData *, id<MTLRenderPipelineState>> *cache; if (!cache) cache = [NSMutableDictionary dictionary];
    clr_key ck = *k; ck.dfmt = ck.sfmt = 0;   // a Metal 4 pipeline names no depth / stencil format: one pipeline serves them all
    NSData *kd = [NSData dataWithBytes:&ck length:sizeof ck]; id<MTLRenderPipelineState> ps = cache[kd]; if (ps) return ps;
    id<MTLLibrary> lib = clr_lib(); if (!lib) return nil;
    static const char *ty[3] = {"float", "uint", "int"};
    MTLPixelFormat cf[8]; MTLColorWriteMask wm[8];
    for (int i = 0; i < 8; i++) { cf[i] = (MTLPixelFormat)k->cfmt[i]; wm[i] = MTLColorWriteMaskNone; }   // the other attachments stay as they are
    if (k->slot >= 0) wm[k->slot] = (MTLColorWriteMask)((k->mask & 1 ? MTLColorWriteMaskRed : 0) | (k->mask & 2 ? MTLColorWriteMaskGreen : 0) | (k->mask & 4 ? MTLColorWriteMaskBlue : 0) | (k->mask & 8 ? MTLColorWriteMaskAlpha : 0));
    NSError *e = nil; ps = host_rps(lib, @"clr_vs", k->slot >= 0 ? [NSString stringWithFormat:@"clr_fs_%d_%s", k->slot, ty[k->kind]] : nil, 8, cf, wm, k->samples, &e);
    if (!ps) { static int n; if (n++ < 4) MLOG("[RED] cannot create the clear-triangle pipeline (slot %d color format %u depth %u stencil %u samples %u): %s; this clear is skipped", k->slot, k->slot >= 0 ? k->cfmt[k->slot] : 0, k->dfmt, k->sfmt, k->samples, e.localizedDescription.UTF8String); return nil; }
    cache[kd] = ps; return ps;
}
static id<MTLDepthStencilState> clr_dss(int dw, unsigned sm) {   // depth ALWAYS, written when dw; stencil ALWAYS → REPLACE through write mask sm (no stencil test when 0)
    static id<MTLDepthStencilState> c[2][256];
    if (c[dw][sm]) return c[dw][sm];
    MTLDepthStencilDescriptor *d = [MTLDepthStencilDescriptor new]; d.depthCompareFunction = MTLCompareFunctionAlways; d.depthWriteEnabled = dw != 0;
    if (sm) { MTLStencilDescriptor *st = [MTLStencilDescriptor new]; st.stencilCompareFunction = MTLCompareFunctionAlways; st.stencilFailureOperation = st.depthFailureOperation = MTLStencilOperationKeep;
        st.depthStencilPassOperation = MTLStencilOperationReplace; st.readMask = 0xff; st.writeMask = sm; d.frontFaceStencil = d.backFaceStencil = st; }
    return c[dw][sm] = [g_dev newDepthStencilStateWithDescriptor:d];
}
static int clr_scissor(MTLScissorRect *sc) {   // the clear's scissor in the open pass, clamped as for draws; 0 = empty
    NSUInteger tw = g_pass.tw, th = g_pass.th; *sc = (MTLScissorRect){0, 0, tw, th};
    if (!R.has_sc) return tw && th;
    long x0 = R.sc.x < 0 ? 0 : R.sc.x, y0 = R.sc.y < 0 ? 0 : R.sc.y, x1 = (long)R.sc.x + R.sc.w, y1 = (long)R.sc.y + R.sc.h;
    if (x1 > (long)tw) x1 = (long)tw; if (y1 > (long)th) y1 = (long)th;
    if (x1 <= x0 || y1 <= y0) return 0;
    *sc = (MTLScissorRect){(NSUInteger)x0, (NSUInteger)y0, (NSUInteger)(x1 - x0), (NSUInteger)(y1 - y0)}; return 1;
}
static int g_clr_fail_test;   // a unit test: clear_color_tri's pipeline fails (t_ls_reduce)
static int clr_tri(id<MTL4RenderCommandEncoder> en, id<MTLRenderPipelineState> ps, id<MTLDepthStencilState> ds, MTLScissorRect sc, const uint32_t val[4], float z, uint32_t sref, NSUInteger tw, NSUInteger th) {   // 1 when drawn
