    }
}
static void clr_note(int slot, int depth, int stencil) {   // as udc_note_draw for a draw: the attachment was written (unwritten-attachment store)
    for (int i = 0; i < g_nsd; i++) { sd_att *t = &g_sd[i];
        if ((t->depth == 0 && slot >= 0 && t->idx == slot) || (t->depth == 1 && depth) || (t->depth == 2 && stencil)) { t->wrote = t->rast = 1; t->wwhy = 2; } }
}
static uint64_t g_clr_tri[2];   // clears drawn as a triangle: colour, depth / stencil
// A colour clear of all four channels into slot at of the open pass covers the whole attachment: the scissor covers the pass, and the pass is the attachment's level
static int clr_whole(int at, int mask) {
    MTLScissorRect sc; if ((mask & 0xf) != 0xf || !g_enc || at < 0 || at >= R.rt.n || !R.rt.color[at] || !clr_scissor(&sc)) return 0;
    if (sc.x || sc.y || sc.width != g_pass.tw || sc.height != g_pass.th || g_rp_aw || g_rp_win || g_pass_alt) return 0;
    NSUInteger lv = R.rt.has_cview[at] && R.rt.cview[at].set_levels ? R.rt.cview[at].base_level : 0; uint32_t w, h; tex_lsize(R.rt.color[at], (unsigned)MIN(lv, 32ul), &w, &h, NULL);
