static int clear_s_tri_pass(id<MTL4RenderCommandEncoder> en, unsigned mask, uint32_t val, NSUInteger tw, NSUInteger th) {
    if (!en || !mask || !g_pass.hs || !tw || !th || g_pass_alt == PA_KEEP) return 0;
    clr_key k; memset(&k, 0, sizeof k); k.slot = -1; memcpy(k.cfmt, g_pass.cfmt, sizeof k.cfmt); k.dfmt = g_pass.dfmt; k.sfmt = g_pass.sfmt; k.samples = g_pass.samples;
    id<MTLRenderPipelineState> ps = clr_pso(&k); id<MTLDepthStencilState> ds = clr_dss(0, mask & 0xff); if (!ps || !ds) return 0;
    const uint32_t v[4] = {0}; MTLScissorRect sc = {0, 0, tw, th};
    clr_tri(en, ps, ds, sc, v, 0, val & 0xff, tw, th); clr_note(-1, 0, 1);
    fb_ds_note_write(FB_DS_STENCIL);
    if (!g_clr_tri[1]++) MLOG("mid-pass scissored depth-stencil clear: drawn as a full-pass triangle (first case pass %llu depth 0 stencil mask %#x scissor 0,0 %lux%lu; it waited for its pass)", g_stat_pass, mask,
                              (unsigned long)tw, (unsigned long)th);
    PD("c %llu masked stencil clear drawn as a triangle as its pass began ser=%llu stencil=%u mask=%#x %lux%lu (DM_NVN_SAME_CLEAR_TRI)", g_stat_pass, R.rt.depth ? (unsigned long long)R.rt.depth->serial : 0ull, val & 0xff, mask,
       (unsigned long)tw, (unsigned long)th);
    return 1;
}

#define EXEC_CALL_MAX 64   // OP_CALL nesting the replay follows (see OP_CALL below)
void (*g_exec_yield)(void); _Atomic int g_exec_yield_want;   // nvn_obj.h: the safe point for a waiting submit (nvn_queue.inc nq_sub_yield)
void mtl_exec(const uint8_t *p) {
    if (!g_state_inited) state_reset();
    static int dump_all = -1; if (dump_all < 0) dump_all = getenv("DM_NVN_PASSDUMP_ALL") != NULL;
    int trace = dump_all && passdump();   // Normal mode does not check the frame range per operation; the full command position is only used for the designated diagnostic frames
    for (;;) {
        // Between two commands, the previous one done and the next not begun: a game submit waiting for g_sub_mu may take it here (nq_sub_yield). One relaxed load a command
        if (__builtin_expect(atomic_load_explicit(&g_exec_yield_want, memory_order_relaxed) > 0, 0) && g_exec_yield) { g_exec_yield(); t_sop = -1; }
        op_hdr h; memcpy(&h, p, sizeof h);
        g_exec_cur = p;
        if (__builtin_expect(t_pf_sec >= 0, 0)) sop_tick(h.op);   // DM_NVN_PF_PARTS: the commands' times (sop_tick)
        if (trace) PD("o cmd=%p pass=%llu op=%u size=%u", p, g_stat_pass, (unsigned)h.op, (unsigned)h.size);
        // Diagnostic DM_NVN_ALLOCPROF=1: growth of the GPU allocated size is charged to the previous operation's type (rough: allocations on other threads are counted too); the memory report line appends the top 4
        allocprof_level();
        if (g_allocprof == 2) { static int prev = -1; uint64_t now = g_alloc4[g_alloc_cur].allocatedSize; if (prev >= 0 && prev < 64 && now > g_cm_last) g_cm_op[prev] += now - g_cm_last; g_cm_last = now; prev = (int)h.op; if (h.op < 64) g_cm_opn[h.op]++; }
        if (g_allocprof) { static uint64_t last; static int prev = -1; uint64_t now = g_dev.currentAllocatedSize; if (prev >= 0 && prev < 64 && now > last) g_ap_bytes[prev] += now - last; last = now; prev = h.op; }
        const void *a = p + 8;
        if (g_nlc && !lc_keeps(h.op) && !(h.op == OP_END && g_ret_n)) lc_land();   // see lc_keeps (a sub-list's end returns to its caller)
        if (g_mrun.n && !geo_mesh_keeps(h.op) && !(h.op == OP_END && g_ret_n)) geo_mesh_flush();   // see geo_mesh_keeps
        switch (h.op) {
            case OP_END: g_exec_cur = NULL;
                return;   // An end-of-pass triggered outside a list (present / CPU readback etc.) must not scan expired command memory: a null start point means store everything
            case OP_BEGIN: break;
            case OP_JUMP: { const uint8_t *t; memcpy(&t, a, 8); p = t; continue; }
            case OP_CALL: { uint64_t t; memcpy(&t, a, 8);
                // Each call level is a frame of this function on the replay thread's stack (about 0.9 KB optimized, 1.8 KB at -O0; nq_worker has the default 512 KB): a call
                // chain that loops back on itself (command memory recorded over with a call to itself) ran into the stack guard. Past EXEC_CALL_MAX levels the call is skipped and the
                // caller goes on: 64 levels take at most 117 KB, the rest is left to the deepest draw beneath (S2Arm 495a3341)
                if (g_ret_n >= EXEC_CALL_MAX) { RED_ONCE(174, "command list calls nested past %d levels (a call chain that loops back on itself?): that call skipped, its caller goes on (first case cmd=%p target %#llx)",
                                                         EXEC_CALL_MAX, (const void *)p, (unsigned long long)t); break; }
                if (g_ret_n < 16) g_ret[g_ret_n] = p + h.size; g_ret_n++;   // Return stack for lookahead: after a sub-list ends, continue looking at the caller
                mtl_exec((const uint8_t *)t); g_ret_n--; break; }
            case OP_SIGNAL_EVENT: { volatile uint32_t *val; uint32_t m, v; memcpy(&val, a, 8); memcpy(&m, (const uint8_t *)a + 8, 4); memcpy(&v, (const uint8_t *)a + 12, 4);
                PD("Y signal_event cmd=%p dst=%p mode=%u value=%u", p, val, m, v); mtl_sub_event(val, m, v); break; }
            case OP_REPORT_COUNTER: { uint64_t t, ad; memcpy(&t, a, 8); memcpy(&ad, (const uint8_t *)a + 8, 8); g_cnt_report[t & 31]++;
                PD("Q report type=%llu cmd=%p dst=%#llx", (unsigned long long)t, p, (unsigned long long)ad);
                if (DM_GAME_RENDER_COND) rc_note(ad, t == 0 || t == 0x10 ? 1 : t == NVN_COUNTER_TYPE_SAMPLES_PASSED ? 2 : 3);
                if (t == NVN_COUNTER_TYPE_SAMPLES_PASSED) {
                    if (!g_vis_on) {   // a report with no reset before it: the counter runs from the queue's creation, so counting starts here (Occlusion queries)
                        g_vis_on = 1; g_vis_counting = 1; MLOG("occlusion queries: samples passed reported with no ResetCounter before it: counting from this report");
                        if (g_enc && !g_enc_has_vis) { PD("M %llu occlusion query counting starts at a report: render pass split here", g_stat_pass); rp_end(); } }
                    hw_note(ad); post(vis_op(VIS_REPORT, ad, (uint32_t)t)); }   // written at completion, as a counter report
                else mtl_sub_counter(ad, (uint32_t)t);
                break; }
            case OP_RENDER_COND: { const p_render_cond *rc = a;   // recorded only with the profile key render_cond (hle_nvn.c)
                if (rc->mode >= 2) { g_rc_skip = rc->mode == 3; PD("E %llu render enable %d", g_stat_pass, rc->mode == 2); }
                else { uint64_t x = 0, y = 0; int known = rc_values(rc->addr, &x, &y);
                    g_rc_skip = known && (rc->mode ? x == y : x != y);
                    PD("E %llu conditional render %s addr=%#llx values %llu / %llu%s%s", g_stat_pass, rc->mode ? "draw if not equal" : "draw if equal", (unsigned long long)rc->addr, (unsigned long long)x, (unsigned long long)y, known ? "" : " (unknown, drawn)", g_rc_skip ? " → not drawn" : ""); }
                break; }
            case OP_FENCE_SYNC: { sync_t *s; memcpy(&s, a, 8); s->fence = g_fence + 1; s->fenced = 1;   // the fence value this submission (segment) commits with
                PD("Y fence_sync cmd=%p sync=%p fence=%llu", p, (void *)s, (unsigned long long)s->fence); break; }
            case OP_RESET_COUNTER: { uint64_t t; memcpy(&t, a, 8); g_cnt_reset[t & 31]++; PD("Q reset type=%llu cmd=%p", (unsigned long long)t, p);
                if (t == NVN_COUNTER_TYPE_SAMPLES_PASSED) {
                    g_vis_on = 1; g_vis_counting = 1; vis_clear(); post((post_op){3, NULL, VIS_ZERO, 0, 0, (uint32_t)t, NULL});
                    // The first reset can come inside a render pass that was begun without a visibility buffer (Octopath Traveler 0: Unreal's occlusion queries, once at boot): split the pass
                    // here, so the continuation is begun with the buffer and its samples are counted (they used not to be: RED "occlusion query counting began in a pass without a visibility buffer")
                    if (g_enc && !g_enc_has_vis) { PD("M %llu occlusion query counting starts: render pass split here", g_stat_pass); rp_end(); } }
                break; }
            case OP_CLEAR_BUF: { const p_clear_buf *cb = a; mtl_sub_fill(cb->addr, cb->size, cb->value); break; }
            case OP_COPY_B2B: { uint64_t s_, d, n; memcpy(&s_, a, 8); memcpy(&d, (const uint8_t *)a + 8, 8); memcpy(&n, (const uint8_t *)a + 16, 8);
                PD("Y copy_b2b cmd=%p src=%#llx dst=%#llx bytes=%llu", p, (unsigned long long)s_, (unsigned long long)d, (unsigned long long)n); mtl_sub_copy(s_, d, n); break; }
            case OP_UPDATE_UB: { uint64_t d, n; memcpy(&d, a, 8); memcpy(&n, (const uint8_t *)a + 8, 8);
                if (p == g_mdx_stop) { g_mdx_epoch++; g_mdx_stop = NULL; }   // it writes a record or count that masked copies were made of (mdx_run)
                PD("Y update_ub cmd=%p src=%#llx dst=%#llx bytes=%llu f=%g,%g,%g,%g", p, (unsigned long long)((const uint8_t *)a + 16), (unsigned long long)d, (unsigned long long)n,
                   n >= 4 ? ((const float *)((const uint8_t *)a + 16))[0] : 0.f, n >= 8 ? ((const float *)((const uint8_t *)a + 16))[1] : 0.f, n >= 12 ? ((const float *)((const uint8_t *)a + 16))[2] : 0.f, n >= 16 ? ((const float *)((const uint8_t *)a + 16))[3] : 0.f); mtl_sub_update((const uint8_t *)a + 16, d, n); break; }
            case OP_SET_RT: {
                pfm(PFM_RT);
                const p_set_rt *r = a; g_setrt_n++; g_split_resume = 0;   // a split's resume is for its own pass only
                int pend = R.clear_d || R.clear_s || R.clear_sm; for (int i = 0; i < 8; i++) pend |= R.clear_c[i];
                // Do not continue a render pass opened only for a clear; one with fewer depth / stencil attachments can be continued (check the planes before drawing). An identical depth-only binding continues too (upstream a739027a6)
                if (g_enc && g_enc_mode != 1 && !pend && R.has_rt && rtc_on() && (r->n || r->depth)) {
                    const p_set_rt *cur_rt = g_rt_sub ? &g_rt_super : &R.rt;   // in a leading-target continuation: the pass's own targets
                    if (rt_same(cur_rt, r)) {
                        if (g_rt_sub) { g_rt_sub = 0; PD("M %llu the pass's own targets again", g_stat_pass); }
                        else { g_rt_merged = 1; if (!g_rt_merge_n++) MLOG("same-target continuation: first case pass %llu", g_stat_pass); PD("M %llu same-target continuation pass", g_stat_pass); }
                        R.rt = *r; break; }
                    if (rtsub_on() && !g_sm_pass && !g_fsp_pass && !g_nbcrt && rt_prefix(cur_rt, r)) {   // a leading part of them (rt_prefix, DM_NVN_RT_SUBSET)
                        if (!g_rt_sub) g_rt_super = R.rt;
                        g_rt_sub = 1; g_rt_merged = 1; R.rt = *r;
                        if (!g_rt_sub_n++) MLOG("leading-target continuation: the game's targets are the first %d of the open pass's; it goes on (first case pass %llu; DM_NVN_RT_SUBSET)", rt_ncolor(r), g_stat_pass);
                        PD("M %llu leading-target continuation: the first %d targets of the pass", g_stat_pass, rt_ncolor(r)); break; }
                }
                if (g_enc && g_sm_pass && !pend && !g_game_barrier) { int sl;   // another layer of the slice-merged pass's level (sm_scan planned it)
                    if (sm_rt_slice(&R.rt, r, &sl) && sl >= g_sm_lo && sl <= g_sm_hi) { R.rt = *r; g_sm_cur = sl; g_sm_ncont++;
                        { void td_note_layer(id<MTLTexture>, uint64_t, NSUInteger, NSUInteger);   // every target of the pass (DM_NVN_SLICE_MRT)
                          for (int k = 0; k < r->n && k < 8 && r->color[k]; k++) td_note_layer(tex_mtl(r->color[k]), r->color[k]->serial, r->cview[k].set_levels ? r->cview[k].base_level : 0, (NSUInteger)sl); }
                        PD("M %llu slice-merged pass goes on in layer %d", g_stat_pass, sl); break; } }
                if (pend && !g_enc && g_cb && lc_on() && !R.clear_sm) lc_push(); else rp_flush();   // a masked stencil clear (R.clear_sm) does not wait: its pass opens here, as it did when it was drawn at once   // clears with no draw wait for the next pass that attaches their targets (lc_push)
                sub_cut(); R.rt = *r; R.has_rt = 1; break;
            }
            case OP_CLEAR_COLOR: {
                const p_clear_color *c = a;
                if (g_rc_skip) { PD("c %llu color clear skipped by conditional rendering slot%d", g_stat_pass, c->index); break; }
                // A scissored clear to 0 outside a pass with all channels (SMBW clears pyramid levels as sub-rectangles of 480×272 and other targets): copy from the zero buffer into the scissor rectangle in the replay stream
                if (!g_enc && c->mask == 0xf && !c->rgba[0] && !c->rgba[1] && !c->rgba[2] && !c->rgba[3] && R.has_sc && c->index >= 0 && c->index < R.rt.n && R.rt.color[c->index]
                    && !scissor_full(R.rt.color[c->index], &R.rt.cview[c->index], R.rt.has_cview[c->index]) && clear_rect_zero(c->index)) break;
                if (g_rt_merged || g_sm_pass || g_fsp_pass) rp_end();   // A clear arrived in a continued render pass: end it here, and the clear is attached to the start of the next render pass as usual
                if (c->index < 0 || c->index >= R.rt.n || !R.rt.color[c->index]) { RED_ONCE(5, "color clear target %d invalid", c->index); break; }
                if (g_enc || c->mask != 0xf || !scissor_full(R.rt.color[c->index], &R.rt.cview[c->index], R.rt.has_cview[c->index])) {
                    // Inside a pass, with a partial mask or a partial scissor: drawn as a triangle (clear_color_tri)
                    static uint64_t n; static int clog = -1; if (clog < 0) clog = getenv("DM_NVN_CLEARLOG") != NULL; if (clog && n++ < 40) MLOG("color clear drawn as a triangle frame %llu pass %llu target %d ser=%llu %ux%u mid=%d mask=%#x scissor=%d,%d,%d,%d color=%g,%g,%g,%g", (unsigned long long)atomic_load(&g_cur_frame), g_stat_pass, c->index,
                        (unsigned long long)R.rt.color[c->index]->serial, R.rt.color[c->index]->d.width, R.rt.color[c->index]->d.height, g_enc != nil, c->mask, R.sc.x, R.sc.y, R.sc.w, R.sc.h, c->rgba[0], c->rgba[1], c->rgba[2], c->rgba[3]);
                    clear_color_tri(c); break; }
                R.clear_c[c->index] = 1; R.cc[c->index] = MTLClearColorMake(c->rgba[0], c->rgba[1], c->rgba[2], c->rgba[3]);
                PD("c %llu color clear recorded slot%d ser=%llu mask=%#x scissor=%d:%d,%d,%d,%d", g_stat_pass, c->index, (unsigned long long)R.rt.color[c->index]->serial, c->mask, R.has_sc, R.sc.x, R.sc.y, R.sc.w, R.sc.h);
                break;
            }
            case OP_CLEAR_DS: {
                const p_clear_ds *c = a;
                if (g_rc_skip) { PD("c %llu depth-stencil clear skipped by conditional rendering", g_stat_pass); break; }
                g_fb_dclr++;   // a depth snapshot taken before it is not reused by a reading draw (fb_dsnap_live)
                if (g_rt_merged || g_sm_pass || g_fsp_pass) rp_end();
                // A load-action clear covers the whole attachment and every stencil bit. A clear whose scissor does not cover the depth target, or whose stencil mask is partial, is drawn as a triangle
                // (clear_ds_tri), in or before a pass: before the first draw and for a partial stencil mask in a pass it used to clear the whole target (PR #108)
                unsigned sm = (unsigned)c->stencil_mask & 0xff;
                // A partial stencil mask with no pass open and a depth clear over the whole target: only the stencil needs the triangle, and the depth half is the pass's load action, so
                // the depth plane is not loaded only to be cleared (Donkey Kong Bananza: 22.8 MB of depth and stencil loaded a frame for a stencil mask of 1, 4.6 MB this way)
                // With no pass open, over the whole target, on a target that can take a record (sc_eligible): the masked stencil clear waits like the others (R.clear_sm) and its triangle is
                // drawn as its pass begins, so a pass of clears alone stays clear-only and can be left out once its targets hold its results (DM_NVN_SAME_CLEAR_TRI)
                if (R.rt.depth && !g_enc && sm && sm != 0xff && scissor_full(R.rt.depth, &R.rt.dview, R.rt.has_dview) && sct_on() && !(R.rt.has_dview && R.rt.dview.set_format)) {
                    const tex_t *dt = R.rt.depth; id<MTLTexture> root = sc_root(tex_mtl(dt));
                    if (root && sc_eligible(dt, root)) {
                        if (c->depth_mask) { R.clear_d = 1; R.cd = c->depth; }
                        uint32_t v = (uint32_t)c->stencil & sm;
                        if (R.clear_s) R.cs = (R.cs & ~sm) | v;   // a full clear waiting: still a full clear, with these bits replaced
                        else { R.csm = (R.csm & R.clear_sm & ~sm) | v; R.clear_sm |= (uint8_t)sm; }   // an older masked clear: one mask and value for both
                        PD("c %llu masked stencil clear waits for its pass ser=%llu depth=%g(%d) stencil=%d mask=%#x (DM_NVN_SAME_CLEAR_TRI)", g_stat_pass, (unsigned long long)dt->serial, c->depth, c->depth_mask, c->stencil, sm);
                        break; }
                }
                if (R.rt.depth && !g_enc && c->depth_mask && sm && sm != 0xff && scissor_full(R.rt.depth, &R.rt.dview, R.rt.has_dview)) {
                    R.clear_d = 1; R.cd = c->depth; p_clear_ds s = *c; s.depth_mask = 0; clear_ds_tri(&s); break;
                }
                if (R.rt.depth && (!scissor_full(R.rt.depth, &R.rt.dview, R.rt.has_dview) || (sm && sm != 0xff))) { clear_ds_tri(c); break; }
                // A full clear in the middle of a pass: end the pass and attach the clear to the start of the next one (color attachments load as usual, as a continued pass does above when a clear arrives).
                // It used to be skipped, and later draws depth-tested against stale depth
                if (g_enc) {
                    { static int once; if (!once++) MLOG("mid-pass depth-stencil clear: ending this pass; the clear moves to the start of the next pass (first case pass %llu)", g_stat_pass); }
                    rp_end();
                }
                if (c->depth_mask) { R.clear_d = 1; R.cd = c->depth; }
                if (c->stencil_mask) { R.clear_s = 1; R.cs = (uint32_t)c->stencil; R.clear_sm = 0; }   // a waiting masked stencil clear is older: overwritten
                PD("c %llu depth-stencil clear recorded ser=%llu depth=%g depth_mask=%d stencil=%d stencil_mask=%#x", g_stat_pass, R.rt.depth ? (unsigned long long)R.rt.depth->serial : 0ull, c->depth, c->depth_mask, c->stencil, c->stencil_mask);
                break;
            }
            case OP_MULTI_DRAW:
                // A lookahead from outside the range stops at its boundary, including scans for inline writes to the arguments.
                g_mdx_epoch++; g_mdx_stop = NULL;
                if (!g_rc_skip) draw_multi(a);
                g_mdx_epoch++;
                break;
            case OP_DRAW: { if (g_rc_skip) break; if (g_fsm_ntaken && fsm_take(p)) { PD("L %llu face-split draw already drawn in an earlier pass (DM_NVN_FACE_MERGE)", g_stat_pass); break; }
                p_draw t; g_exec_cur = p; g_exec_next = p + h.size; draw(draw_rec(a, h.size, &t), NULL); g_exec_next = NULL; break; }   // Lookahead start point
            case OP_DRAW_IDX: { if (g_rc_skip) break; if (g_fsm_ntaken && fsm_take(p)) { PD("L %llu face-split draw already drawn in an earlier pass (DM_NVN_FACE_MERGE)", g_stat_pass); break; }
                p_draw_idx t; g_exec_cur = p; g_exec_next = p + h.size; draw(NULL, draw_idx_rec(a, h.size, &t)); g_exec_next = NULL; break; }
            // Do not mark dirty if the state did not change (the game often re-sends the same program / state block / vertex format before each draw; the dirty flag only decides whether to re-fetch the pipeline / depth-stencil object, and equal values mean the same object)
            case OP_BIND_PROGRAM: { const p_bind_program *b = a; state_op(h.op,a);
                if (passdump()) { NvProg *pr = S.prog ? prog_get(S.prog) : nil;
                    PD("Y bind_program cmd=%p program=%p stages=%#x vs=%s fs=%s gs=%s",p,(void *)b->prog,b->stages,
                       pr && pr->sh[0] ? pr->sh[0]->key : "-", pr && pr->sh[1] ? pr->sh[1]->key : "-",pr && pr->sh[2] ? pr->sh[2]->key : "-"); }
                break; }
            case OP_SCISSOR: case OP_BIND_STATE: case OP_BIND_VATTR: case OP_BIND_VSTREAM: case OP_BIND_VBUF: case OP_BIND_VBUF1:
            case OP_BIND_UBO: case OP_BIND_UBO_SMALL: case OP_BIND_SSBO: case OP_BIND_TEX: case OP_BIND_TEX1: case OP_BIND_SAMP: case OP_BIND_IMG: case OP_STENCIL:
            case OP_POLY_OFFSET: case OP_DEPTH_RANGE: case OP_DEPTH_CLAMP: case OP_DEPTH_BOUNDS: case OP_LINE_WIDTH: case OP_VP_SWIZZLE: case OP_BLEND_COLOR: case OP_ALPHA_REF: case OP_PUSH_CONST: case OP_COPY_STRIDE:
                state_op(h.op, a); break;
            // PASSDUMP O lines: the viewports the game sets, with the pass they fall in (one set before its pass opens takes that pass's number, as the P lines do). The D line
            // prints the one a draw used, so a viewport the pass set is told from one carried over. Printed here, not in state_op: look-ahead scans replay state_op too
            case OP_VIEWPORTS: { const p_viewports *b = a; state_op(h.op, a);
                if (passdump()) { unsigned long long pn = g_enc ? g_stat_pass : g_stat_pass + 1; PD("O %llu set_viewports first=%d n=%d", pn, b->first, b->n);
                    for (int i = 0; i < b->n && i < 4; i++) PD("O %llu   vp[%d] = %.0f,%.0f,%.0f,%.0f", pn, b->first + i, b->v[i][0], b->v[i][1], b->v[i][2], b->v[i][3]); }
                break; }
            case OP_TF_BIND: { const p_tf_bind *b = a; PD("Y tf bind %d addr=%#llx size=%llu", b->index, (unsigned long long)b->addr, (unsigned long long)b->size); state_op(h.op, a); break; }
            case OP_TF_STATE: { const p_tf_state *b = a; static const char *const w[4] = {"begin", "end", "pause", "resume"}; PD("Y tf %s ctl=%#llx", w[b->what & 3], (unsigned long long)b->ctl);
                state_op(h.op, a); tf_state_gpu(b); break; }
            case OP_PRIM_RESTART: state_op(h.op, a); break;
            case OP_RAST_DISCARD: PD("Y rasterizer discard %d", ((const p_rast_discard *)a)->on); state_op(h.op, a); break;
            case OP_COPY_B2T: copy_b2t(a, h.size); break;
            case OP_COPY_T2B: copy_t2b(a, h.size); break;
            case OP_COPY_T2T: copy_t2t(a); break;
            case OP_DRAW_TEX: draw_tex(a); break;
            case OP_CLEAR_TEX: clear_tex(a); break;
            case OP_DLSS: dlss_eval(a); break;
            case OP_DISPATCH: if (g_csh_n && csh_take(p)) { PD("H %llu dispatch already run ahead of the pass", g_stat_pass); break; }
                dispatch(a); break;
            case OP_BARRIER: { int32_t bits; memcpy(&bits, a, 4);   // ordered at the next draw pass (barrier_game); inside a pass with shader writes, the pass ends first (swrite_note); in one without, before its next write (prog_swrites)
                int order = g_enc && (bits & (NVN_BARRIER_ORDER_PRIMITIVES_BIT | NVN_BARRIER_ORDER_FRAGMENTS_BIT | NVN_BARRIER_ORDER_FRAGMENTS_TILED_BIT));
                int split = g_enc && g_pass_swrite && (order || (bits & NVN_BARRIER_ORDER_INDIRECT_DATA_BIT));   // indirect arguments a draw of the pass wrote: the pass ends too (upstream dc9c2374b)
                // The pass's writes all came from vertex stages (Monolith's skinning draws, one per character, each writing the bone matrices of one shared buffer, then the barrier
                // before the next one): a barrier inside the pass from the vertex stage to the vertex and fragment stages orders them for every later draw, and orders the earlier draws'
                // vertex reads before a later write. It cannot order fragments back to vertices, nor indirect argument fetch, so ORDER_INDIRECT_DATA, or a fragment barrier after draws
                // that read memory in later stages (order_note), still ends the pass; so does a later task / mesh draw (g_pass_vbar). Not in slice-merged or face-split passes.
                // DM_NVN_VBAR_PASS=0 ends the pass as before; ab alternates with DM_AB (upstream dc9c2374b, PR #3374)
                int vbar_keep = split && g_pass_swst == 1 && !(bits & NVN_BARRIER_ORDER_INDIRECT_DATA_BIT)
                    && !((bits & (NVN_BARRIER_ORDER_FRAGMENTS_BIT | NVN_BARRIER_ORDER_FRAGMENTS_TILED_BIT)) && g_pass_late_res)
                    && !g_sm_pass && !g_fsp_pass && vbar_pass_on();
                PD("I %llu barrier bits %#x%s", g_stat_pass, bits, vbar_keep ? " (render pass open; a vertex barrier keeps the pass)" : split ? ": ends the pass (shader writes)" : order ? " (render pass open; a later shader write is ordered after its draws)" : g_enc ? " (render pass open)" : "");
                if (vbar_keep) {
                    [g_enc barrierAfterEncoderStages:MTLStageVertex beforeEncoderStages:MTLStageVertex | MTLStageFragment visibilityOptions:resource_vis()];
                    g_order_vbar++; g_vbar_keep++; g_pass_vbar = 1;
                    static int once; if (!once++) MLOG("a game barrier (bits %#x) after vertex-stage shader writes in a draw pass: a barrier from the vertex stage keeps the pass (first case pass %llu; DM_NVN_VBAR_PASS)", bits, (unsigned long long)g_stat_pass);
                    PD("M %llu vertex-stage writes before the barrier: a barrier from the vertex stage, the pass goes on", g_stat_pass);
                } else if (split) { rp_end(); static int once; if (!once++) MLOG("a game barrier (bits %#x) after shader writes in a draw pass: the pass ends there (first case pass %llu)", bits, (unsigned long long)g_stat_pass); }
                else if (order) g_pass_order |= (bits & NVN_BARRIER_ORDER_PRIMITIVES_BIT ? 1 : 0) | (bits & (NVN_BARRIER_ORDER_FRAGMENTS_BIT | NVN_BARRIER_ORDER_FRAGMENTS_TILED_BIT) ? 2 : 0);
                if ((bits & GAME_BARRIER_FULL) && g_mdx_wr != ~0ull && g_mdx_wr != g_vbuf_write_epoch) g_mdx_epoch++;   // a draw may have written a record or count that was copied before it (g_mdx_wr)
                if (bits) { g_game_barrier |= bits; g_fb_bar++; g_dsp_game_bar = 1; } break; }   // g_fb_bar: snapshots taken before it are stale (see fb_prepare); g_dsp_game_bar: the next dispatch is ordered after the ones before (dispatch_hits)
            case OP_SET_TEX_POOL: case OP_SET_SAMP_POOL: state_op(h.op, a); break;
            default: break;
        }
        p += h.size;
        if (g_rg_redirect) { p = g_rg_redirect; g_rg_redirect = NULL; }   // a level-grouped run (rg_plan) replays from its copy
    }
}

// ---------- Present: draw the swapchain texture to the CAMetalLayer; optional screenshot ----------
static id<MTLRenderPipelineState> g_blit_pso; static MTLPixelFormat g_blit_fmt;
static id<MTLRenderPipelineState> g_rcas_pso;   // the present with Sharpening (present.metal fs_rcas), made with g_blit_pso (present_pipeline)
static id<MTLSamplerState> g_blit_samp;
static uint64_t g_present_n;
uint64_t mtl_present_count(void) { return g_present_n; }   // Actual present count (heat attribution DM_HEAT computes the present frame rate)
void mtl_res_snapshot(mtl_res_count *out) {
    memset(out, 0, sizeof *out);
    out->pso = g_pso.n;
    out->cps = g_cps.n;
    out->dss = g_dss.n;
    out->shaders = (uint32_t)(g_shcache ? g_shcache.count : 0);
    os_unfair_lock_lock(&g_c1_lock);
    out->c1_bufs = (uint32_t)g_c1_banks.count; out->c1_alloc = g_c1_alloc_bytes; out->c1_data = g_c1_data_bytes;
    os_unfair_lock_unlock(&g_c1_lock);
    smu_lock();
    out->live_tex = g_by_serial.n;
    pthread_mutex_unlock(&g_smu);
    mu_lock();
    out->pools = (uint32_t)g_npool;
    out->pool_adds = g_pool_adds;
    pthread_mutex_unlock(&g_mu);
    rmu_lock();
    out->view_slots = (uint32_t)g_ntreg;
    for (int i = 0; i < g_ntreg; i++) if (g_treg[i].view) out->view_nonnull++;
    for (int i = 0; i < g_nsreg; i++) if (g_sview[i]) out->sview_nonnull++;
    os_unfair_lock_unlock(&g_rmu);
}
// Resource counts (read by long-run stability L3): the host calls it per game tick / event (every 250 ticks, loading screen dismissed, exit), not sampled by wall clock / present count.
// Line format: [nvn] resource counts tick <tick number> <trigger>: <name> <value> ... (names contain no spaces, single-space separated); new fields are appended to the end of this line
void mtl_res_counts(uint32_t tick, const char *why) {
    mtl_res_count c;
    mtl_res_snapshot(&c);
    int dl, du; uint64_t da; nvn_dirty_slot_stats(&dl, &du, &da);
    LOG("[nvn] resource counts tick %u %s: render_pipelines %u compute_pipelines %u shaders %u depth_stencil_states %u views_nonnull %u view_slots %u live_textures %u pools_live %u pools_total %llu sampler_views_nonnull %u dirty_ranges_live %d dirty_ranges_total %llu c1_buffers %u c1_bytes %llu c1_used %llu",
        tick, why, c.pso, c.cps, c.shaders, c.dss, c.view_nonnull, c.view_slots, c.live_tex,
        c.pools, (unsigned long long)c.pool_adds, c.sview_nonnull, dl, (unsigned long long)da, c.c1_bufs, (unsigned long long)c.c1_alloc, (unsigned long long)c.c1_data);
}
// Screenshot on request (used by DM_NVN_SHOT_UI): dm_gfx_shot_at(k, path) = take a screenshot at the kth frame after the current present frame; due requests are checked at every frame's present
#define SHOTQ_MAX 8
static struct { uint64_t frame; char path[1024]; } g_shotq[SHOTQ_MAX]; static int g_nshotq;
static pthread_mutex_t g_shotq_mu = PTHREAD_MUTEX_INITIALIZER;
enum { PRESENT_FAILED, PRESENT_STANDARD, PRESENT_METALFX, PRESENT_SHARPENED, PRESENT_AA = 8 };   // PRESENT_SHARPENED: the bilinear pass with Sharpening (present_sharpen); PRESENT_AA: or'ed in after edge smoothing (aa_encode)
static int present_offscreen_m4(id<MTLTexture> src, const int crop[4], id<MTLTexture> out, void (^done)(int));
static int present_offscreen_wait(id<MTLTexture> src, const int crop[4], id<MTLTexture> out);
// Game picture needed by the whole-window screenshot (front end window_shot; no longer does drawViewHierarchy on a Metal layer with the display link attached): at the next present, the present thread draws the same frame
// with the same encoding as the present into an offscreen texture of the view's size, and after the GPU finishes hands out a CGImage in the completion callback. Guarded by g_shotq_mu
static void (^g_grab_cb)(CGImageRef img);
void mtl_grab_next_present(void (^cb)(CGImageRef img)) { pthread_mutex_lock(&g_shotq_mu); g_grab_cb = [cb copy]; pthread_mutex_unlock(&g_shotq_mu); }
static void grab_present_to(id<MTLTexture> src, const int crop[4], CGSize sz, void (^cb)(CGImageRef img));
static void grab_present(id<MTLTexture> src, const int crop[4], CGSize sz) {
    pthread_mutex_lock(&g_shotq_mu); void (^cb)(CGImageRef) = g_grab_cb; g_grab_cb = nil; pthread_mutex_unlock(&g_shotq_mu);
    if (cb) grab_present_to(src, crop, sz, cb);
}
static void grab_present_to(id<MTLTexture> src, const int crop[4], CGSize sz, void (^cb)(CGImageRef img)) {
    size_t w = (size_t)sz.width, h = (size_t)sz.height, row = w * 4;
    MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:w height:h mipmapped:NO];
    d.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; d.storageMode = MTLStorageModePrivate;
    id<MTLTexture> out = w && h ? [g_dev newTextureWithDescriptor:d] : nil; id<MTLBuffer> buf = out ? [g_dev newBufferWithLength:row * h options:MTLResourceStorageModeShared] : nil;
    if (!buf) { MLOG("[RED] full-window screenshot: cannot create output (%zux%zu)", w, h); cb(NULL); return; }
    // GPU completion starts the readback, keeping the present thread free. Each capture owns its scaler and textures until completion. The readback is made and committed on the
    // residency commit worker (res_commit_q), not in the offscreen present's feedback handler: once_commit commits the residency set first, and no feedback handler may (a long
    // commit would hold back every completion); it completes on the feedback queue, without waiting (once_commit)
    void (^readback)(int) = ^(int ok) {
        if (!ok) { cb(NULL); return; }
        NvOnce *cb2 = once_new(1); once_use(cb2, out); once_use(cb2, buf); id<MTL4ComputeCommandEncoder> b = once_copy(cb2);
        [b copyFromTexture:out sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, 1) toBuffer:buf destinationOffset:0 destinationBytesPerRow:row destinationBytesPerImage:row * h];
        once_end(cb2, b);
        once_commit(cb2, ^(int done) {
            if (!done) { cb(NULL); return; }
            CGColorSpaceRef cs = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
            CGContextRef ctx = CGBitmapContextCreate(buf.contents, w, h, 8, row, cs, kCGImageAlphaNoneSkipFirst | kCGBitmapByteOrder32Little);
            CGImageRef img = ctx ? CGBitmapContextCreateImage(ctx) : NULL; cb(img);
            CGImageRelease(img); CGContextRelease(ctx); CGColorSpaceRelease(cs); });
    };
    if (!present_offscreen_m4(src, crop, out, ^(int ok) { dispatch_async(res_commit_q(), ^{ @autoreleasepool { readback(ok); } }); })) cb(NULL);
}
// The player's screenshot (the Capture button, the in-game menu's Take Screenshot; front_capture.h names the file): the next present's game picture, drawn offscreen as the
// present draws it (the same upscale, Sharpening and edge smoothing) but without the touch controls, at the size it has on the screen (the crop's shape fitted in the
// drawable), then a PNG written beside the path and renamed onto it, so a folder watcher (iCloud Drive, Beam) never sees half a file. The present thread only encodes; the
// readback and the PNG are off it. One at a time: 0 while one is pending. done(ctx, path, ok) comes on a background queue. Guarded by g_shotq_mu
static struct { int pending; char path[1024];   // pending: 1 asked for, 2 being drawn and written
    void (*done)(void *ctx, const char *path, int ok); void *ctx; } g_pshot;
int dm_gfx_capture(const char *path, void (*done)(void *ctx, const char *path, int ok), void *ctx) {
    pthread_mutex_lock(&g_shotq_mu);
    int ok = !g_pshot.pending && path && strlen(path) < sizeof g_pshot.path;
    if (ok) { g_pshot.pending = 1; strlcpy(g_pshot.path, path, sizeof g_pshot.path); g_pshot.done = done; g_pshot.ctx = ctx; }
    pthread_mutex_unlock(&g_shotq_mu);
    return ok;
}
static CGSize capture_size(id<MTLTexture> src, const int crop[4], CGSize screen) {   // the picture's shape (the crop, else the whole source) fitted in the drawable
    double pw = crop && crop[2] > 0 && crop[3] > 0 ? crop[2] : (double)src.width, ph = crop && crop[2] > 0 && crop[3] > 0 ? crop[3] : (double)src.height;
    if (pw <= 0 || ph <= 0 || screen.width <= 0 || screen.height <= 0) return CGSizeMake(pw, ph);
    double k = fmin(screen.width / pw, screen.height / ph);
    return CGSizeMake(fmax(1, floor(pw * k)), fmax(1, floor(ph * k)));
}
static void capture_present(id<MTLTexture> src, const int crop[4], CGSize screen) {
    pthread_mutex_lock(&g_shotq_mu);
    if (g_pshot.pending != 1) { pthread_mutex_unlock(&g_shotq_mu); return; }
    g_pshot.pending = 2;   // taken: the next presents leave it alone until it is written
    NSString *path = @(g_pshot.path); void (*done)(void *, const char *, int) = g_pshot.done; void *ctx = g_pshot.ctx;
    pthread_mutex_unlock(&g_shotq_mu);
    void (^finish)(int) = ^(int ok) {
        MLOG("capture: screenshot %s", ok ? "saved" : "failed");   // the path holds no more than the date, but stays out of the log
        pthread_mutex_lock(&g_shotq_mu); g_pshot.pending = 0; pthread_mutex_unlock(&g_shotq_mu);
        if (done) done(ctx, path.fileSystemRepresentation, ok);
    };
    grab_present_to(src, crop, capture_size(src, crop, screen), ^(CGImageRef img) {
        if (!img) { finish(0); return; }
        CGImageRetain(img);
        dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{ @autoreleasepool {
            NSString *part = [path stringByAppendingString:@".part"];
            NSURL *u = [NSURL fileURLWithPath:part];
            CGImageDestinationRef d = CGImageDestinationCreateWithURL((__bridge CFURLRef)u, (__bridge CFStringRef)UTTypePNG.identifier, 1, NULL);
            int ok = 0;
            if (d) { CGImageDestinationAddImage(d, img, NULL); ok = CGImageDestinationFinalize(d); CFRelease(d); }
            CGImageRelease(img);
            ok = ok && rename(part.fileSystemRepresentation, path.fileSystemRepresentation) == 0;
            if (!ok) unlink(part.fileSystemRepresentation);
            finish(ok);
        } });
    });
}
void dm_gfx_shot_at(long k, const char *path) {
    pthread_mutex_lock(&g_shotq_mu);
    if (g_nshotq < SHOTQ_MAX) { g_shotq[g_nshotq].frame = g_present_n + (uint64_t)(k > 0 ? k : 0); strlcpy(g_shotq[g_nshotq].path, path, sizeof g_shotq[0].path); g_nshotq++; }
    else MLOG("[RED] more than %d screenshot requests; dropping %s", SHOTQ_MAX, path);
    pthread_mutex_unlock(&g_shotq_mu);
}
// DM_NVN_SHOT_OUT=WIDTHxHEIGHT (for picture quality metrics): the present-frame screenshot instead captures the result "upscaled to this resolution by the present pass", i.e. the picture the player sees on a screen
// of that size (with DM_PRESENT_UPSCALE=metalfx through MetalFX, on the Metal 4 queue: present_offscreen_m4); screen=0 (texture dump) is unaffected
static void shot(id<MTLTexture> src, const char *path, int screen, const int crop[4]) {
    static int out_w = -1, out_h;
    if (out_w < 0) {
        out_w = 0;
        const char *e = getenv("DM_NVN_SHOT_OUT"); int w = 0, h = 0; char sep = 0, extra = 0;
        if (e && sscanf(e, "%d%c%d%c", &w, &sep, &h, &extra) == 3 && sep == 'x' && w > 0 && h > 0) { out_w = w; out_h = h; }
    }
    id<MTLTexture> read = src;
    if (out_w && screen) {
        MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:out_w height:out_h mipmapped:NO];
        d.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; d.storageMode = MTLStorageModePrivate;
        id<MTLTexture> out = [g_dev newTextureWithDescriptor:d];
        if (!out) { MLOG("[RED] cannot create the screenshot output texture %dx%d", out_w, out_h); return; }
        if (!present_offscreen_wait(src, crop, out)) return;
        read = out;
    }
    if (read.pixelFormat != MTLPixelFormatRGBA8Unorm && read.pixelFormat != MTLPixelFormatRGBA8Unorm_sRGB &&
        read.pixelFormat != MTLPixelFormatBGRA8Unorm && read.pixelFormat != MTLPixelFormatBGRA8Unorm_sRGB) { MLOG("[RED] screenshot does not support format %lu", (unsigned long)read.pixelFormat); return; }
    size_t w = read.width, h = read.height, row = w * 4;
    id<MTLBuffer> buf = [g_dev newBufferWithLength:row * h options:MTLResourceStorageModeShared];
    NvOnce *cb = once_new(1); once_use(cb, read); once_use(cb, buf);   // the offscreen output, or a texture dump's, is resident no longer (or never was)
    id<MTL4ComputeCommandEncoder> b = once_copy(cb);
    [b copyFromTexture:read sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, 1)
              toBuffer:buf destinationOffset:0 destinationBytesPerRow:row destinationBytesPerImage:row * h];
    once_end(cb, b);
    // A readback that failed (a GPU error) or did not finish (the suspend's limit, -1) writes no PNG: its buffer would be saved as a black picture (upstream b95a6b247)
    if (once_wait(cb) <= 0) { MLOG("[RED] screenshot %s: Metal readback did not complete", path); return; }
    if (screen && read == src && atomic_load_explicit(&g_origin_ll, memory_order_relaxed)) {   // lower-left origin: the window image is stored bottom-up (see g_origin_ll)
        uint8_t *p = buf.contents, *tmp = malloc(row);
        if (tmp) { for (size_t y = 0; y < h / 2; y++) { memcpy(tmp, p + y * row, row); memcpy(p + y * row, p + (h - 1 - y) * row, row); memcpy(p + (h - 1 - y) * row, tmp, row); } free(tmp); } }
    int bgra = read.pixelFormat == MTLPixelFormatBGRA8Unorm || read.pixelFormat == MTLPixelFormatBGRA8Unorm_sRGB;
    CGColorSpaceRef cs = CGColorSpaceCreateWithName(kCGColorSpaceSRGB);
    CGBitmapInfo bi = bgra ? (kCGImageAlphaNoneSkipFirst | kCGBitmapByteOrder32Little) : (CGBitmapInfo)kCGImageAlphaNoneSkipLast;
    CGContextRef ctx = CGBitmapContextCreate(buf.contents, w, h, 8, row, cs, bi);
    CGImageRef img = ctx ? CGBitmapContextCreateImage(ctx) : NULL;
    CFURLRef url = CFURLCreateFromFileSystemRepresentation(NULL, (const UInt8 *)path, strlen(path), false);
    CGImageDestinationRef dst = url ? CGImageDestinationCreateWithURL(url, (__bridge CFStringRef)UTTypePNG.identifier, 1, NULL) : NULL;
    // If any step yields null (directory does not exist / not writable, bitmap context cannot be created), report a failure and return; previously it went straight to CFRelease(NULL) and crashed in CFRelease.cold (hit during a 1952-wide TEXDUMP)
    int ok = 0;
    if (!ctx || !img || !dst) MLOG("[RED] screenshot %s failed: %s", path, !ctx ? "cannot create the bitmap context" : !img ? "cannot get the image" : "cannot write (directory missing or not writable)");
    else { CGImageDestinationAddImage(dst, img, NULL); ok = CGImageDestinationFinalize(dst); }
    if (dst) CFRelease(dst); if (url) CFRelease(url); CGImageRelease(img); CGContextRelease(ctx); CGColorSpaceRelease(cs);
    MLOG("screenshot %zux%zu format %lu → %s %s", w, h, (unsigned long)read.pixelFormat, path, ok ? "ok" : "failed");
}
// ---------- DM_NVN_TEXDUMP=frame number:path (%d in the path is replaced with "index*100+mip level"): save each color render target used by that frame as an image ----------
// Diagnostic: before the first render pass of the next frame is opened, wait for the GPU to finish, then draw each one (the mip level used by that frame) by full-screen sampling into RGBA8 and save as PNG (float formats are clamped to [0,1])
static long g_td_frame = -2; static const char *g_td_path; static NSMutableArray *g_td_list; static int g_td_done;
// DM_NVN_TEXDUMP=layers=<n>:path: the first frame with at least n draws into single layers of small (at most 64x64) array or cube texture levels, counted per pass or slice-merged layer
// (Breath of the Wild's cube map filter frame, every tenth: about 150 against 20): its targets are kept frame by frame and dumped when such a frame ends, the same frame with or without DM_NVN_SLICE_MERGE
static int g_td_layers, g_td_lcount; static long g_td_lframe = -1;
static void td_layer_count(id<MTLTexture> t, NSUInteger lv) { if (t && (t.textureType == MTLTextureType2DArray || t.textureType == MTLTextureTypeCube) && MAX(t.width >> lv, 1ul) <= 64) g_td_lcount++; }
static void td_dump(void);
// DM_NVN_TEXDUMP=size=WxH:path instead picks the frame by content: the first frame that opens a render pass whose first color attachment level is WxH (for one-off work whose frame differs between runs)
static unsigned g_td_w, g_td_h;
void td_note(MTL4RenderPassDescriptor *pd, NSUInteger nc) {
    if (g_td_frame == -2) { const char *e = getenv("DM_NVN_TEXDUMP"), *c = e ? strchr(e, ':') : NULL; g_td_frame = c ? atol(e) : -1; g_td_path = c ? c + 1 : NULL; g_td_list = [NSMutableArray array];
        if (c && !strncmp(e, "size=", 5) && sscanf(e + 5, "%ux%u", &g_td_w, &g_td_h) == 2) g_td_frame = LONG_MAX;
        if (c && !strncmp(e, "layers=", 7)) { g_td_layers = atoi(e + 7); g_td_frame = (long)atomic_load(&g_cur_frame); } }
    if (g_td_frame < 0 || g_td_done) return;
    long f = (long)atomic_load(&g_cur_frame);
    if (g_td_layers) {
        if (f != g_td_lframe) { if (g_td_lframe >= 0 && g_td_lcount >= g_td_layers) { MLOG("[texdump] frame %ld: %d draws into small array / cube layers", g_td_lframe, g_td_lcount); g_td_frame = g_td_lframe; td_dump(); return; }
            g_td_lframe = f; g_td_frame = f; g_td_lcount = 0; [g_td_list removeAllObjects]; }
        if (nc) td_layer_count(pd.colorAttachments[0].texture, pd.colorAttachments[0].level); }
    if (g_td_frame == LONG_MAX) { id<MTLTexture> t0 = nc ? pd.colorAttachments[0].texture : nil; NSUInteger lv = pd.colorAttachments[0].level;
        if (t0 && MAX(t0.width >> lv, 1ul) == g_td_w && MAX(t0.height >> lv, 1ul) == g_td_h) { g_td_frame = f; MLOG("[texdump] first %ux%u render target at frame %ld: dumping this frame", g_td_w, g_td_h, f); } }
    if (f > g_td_frame) { td_dump(); return; }
    if (f != g_td_frame) return;
    for (NSUInteger i = 0; i < nc && i < 8; i++) {
        id<MTLTexture> t = pd.colorAttachments[i].texture; if (!t) continue;
        uint64_t ser = i < (NSUInteger)R.rt.n && R.rt.color[i] ? R.rt.color[i]->serial : 0;
        NSUInteger lv = pd.colorAttachments[i].level, sl = t.textureType == MTLTextureType2DArray ? pd.colorAttachments[i].slice : 0;
        BOOL seen = NO; for (NSArray *e in g_td_list) if (e.count < 5 && [e[1] unsignedLongLongValue] == ser && [e[2] unsignedIntegerValue] == lv && [e[3] unsignedIntegerValue] == sl) seen = YES;
        if (!seen) [g_td_list addObject:@[t, @(ser), @(lv), @(sl)]];
    }
}
void td_note_layer(id<MTLTexture> t, uint64_t ser, NSUInteger lv, NSUInteger sl) {   // a slice-merged pass's other layers (see g_sm_plan)
    if (g_td_frame < 0 || g_td_done || g_td_frame == LONG_MAX || (long)atomic_load(&g_cur_frame) != g_td_frame || !t) return;
    if (g_td_layers) td_layer_count(t, lv);
    if (t.textureType != MTLTextureType2DArray) sl = 0;
    for (NSArray *e in g_td_list) if (e.count < 5 && [e[1] unsignedLongLongValue] == ser && [e[2] unsignedIntegerValue] == lv && [e[3] unsignedIntegerValue] == sl) return;
    [g_td_list addObject:@[t, @(ser), @(lv), @(sl)]];
}
// The next frame's targets, on request (the Mac's DM_CTL "texdump <path>", hle_hid.c): the path is kept (strdup), the frame number is the one after the current
// The Mac's DM_CTL "texraw <serial> <path>" (hle_hid.c): level 0 of every slice (a cube's six faces) of the host texture behind a serial, raw, after the GPU finishes (header line: width height Metal format bytes per row, then the slice count when above one);
// for a texture that is no render target (a default texture, a lookup table) whose content a shader depends on
void dm_gfx_texraw(uint64_t serial, const char *path) {
    __unsafe_unretained id o = tex_get(serial);
    if ([o isKindOfClass:[NvPkg class]]) o = ((NvPkg *)o)->tex;   // a texture from the game's files
    if (!o || ![o conformsToProtocol:@protocol(MTLTexture)]) { MLOG("[texraw] ser=%llu: no host texture", (unsigned long long)serial); return; }
    id<MTLTexture> t = o; mtl_finish_gpu();
    if (t.storageMode == MTLStorageModeMemoryless || t.pixelFormat == MTLPixelFormatInvalid) return;
    NSUInteger w = t.width, h = t.height, row = w * 16, sz = row * h;   // 16 bytes a texel: a multiple of every uncompressed texel size
    int d3 = t.textureType == MTLTextureType3D;   // a 3D texture: every depth slice, as slices
    NSUInteger ns = d3 ? MAX(t.depth, 1u) : (t.textureType == MTLTextureTypeCube || t.textureType == MTLTextureTypeCubeArray ? 6 : 1) * MAX(t.arrayLength, 1u);   // every slice (a cube's six faces), one after another
    id<MTLBuffer> buf = [g_dev newBufferWithLength:sz * ns options:MTLResourceStorageModeShared];
    NvOnce *cb = once_new(1); once_use(cb, t); once_use(cb, buf); id<MTL4ComputeCommandEncoder> b = once_copy(cb);
    MTLBlitOption bo = t.pixelFormat == MTLPixelFormatDepth32Float_Stencil8 ? MTLBlitOptionDepthFromDepthStencil : MTLBlitOptionNone;
    for (NSUInteger s = 0; s < ns; s++)
        [b copyFromTexture:t sourceSlice:d3 ? 0 : s sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, d3 ? s : 0) sourceSize:MTLSizeMake(w, h, 1) toBuffer:buf destinationOffset:sz * s destinationBytesPerRow:row destinationBytesPerImage:sz options:bo];
    once_end(cb, b); once_wait(cb);
    FILE *f = fopen(path, "wb"); if (f) { fprintf(f, "%lu %lu %lu %lu", (unsigned long)w, (unsigned long)h, (unsigned long)t.pixelFormat, (unsigned long)row); if (ns > 1) fprintf(f, " %lu", (unsigned long)ns); fputc('\n', f); fwrite(buf.contents, 1, sz * ns, f); fclose(f); }
    const uint8_t *p = buf.contents;
    MLOG("[texraw] ser=%llu %lux%lu format %lu type %lu → %s; first bytes %02x %02x %02x %02x %02x %02x %02x %02x", (unsigned long long)serial, (unsigned long)w, (unsigned long)h, (unsigned long)t.pixelFormat, (unsigned long)t.textureType, path, p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7]);
}
// The Mac's DM_CTL "texlist <NVN target>" (hle_hid.c): the registered textures of that target (2 = 3D), with their storage (guest address, size) and block-linear layout, for "memdump"
void dm_gfx_texlist(int target) {
    rmu_lock();
    for (int i = 1; i < g_ntreg; i++) { const tex_t *t = &g_treg[i].t; if (!g_treg[i].ok || t->d.target != target) continue;
        MLOG("[texlist] tid=%d ser=%llu target %d %ux%ux%u format %#x levels %u flags %#x storage %p size %#llx block height/depth log2 %u/%u", i, (unsigned long long)t->serial, t->d.target,
             t->d.width, t->d.height, t->d.depth, t->d.format, t->d.levels, t->d.flags, (void *)t->mem, (unsigned long long)t->L.size, t->L.tileH, t->L.tileD); }
    os_unfair_lock_unlock(&g_rmu);
}
// For the crash dump (crash.c): what is known of an address. Read without the locks (the process is going), so a table being changed at that moment may print nonsense, never fault
// on a freed table: g_pools and g_treg are only reallocated, and both are read through their current pointer and count
void dm_gfx_addr_note(uint64_t a, char *note, size_t n) {
    size_t k = 0; note[0] = 0;
    #define NOTE(...) do { if (k < n) { int w = snprintf(note + k, n - k, __VA_ARGS__); if (w > 0) k += (size_t)w; } } while (0)
    const pool_ent *pl = g_pools; int np = g_npool;
    for (int i = 0; pl && i < np; i++) if (a >= pl[i].lo && a < pl[i].hi) { NOTE(" memory pool %#lx..%#lx (+%#llx)", (unsigned long)pl[i].lo, (unsigned long)pl[i].hi, (unsigned long long)(a - pl[i].lo)); break; }
    const treg_t *tr = g_treg; int nt = g_ntreg, shown = 0;
    for (int i = 1; tr && i < nt && shown < 2; i++) { const tex_t *t = &tr[i].t; uint64_t m = (uint64_t)(uintptr_t)t->mem;
        if (tr[i].ok && m && a >= m && a < m + t->L.size) { NOTE(" texture ser=%llu %ux%u format %#x storage +%#llx", (unsigned long long)t->serial, t->d.width, t->d.height, t->d.format, (unsigned long long)(a - m)); shown++; } }
    uint64_t pg = a >> 12, done = atomic_load(&g_done); const gw_ent *e = &g_gw[gw_slot(pg)];
    if (e->page == pg || e->page == ~0ull) NOTE(" GPU write recorded on the page%s: fence %llu (completed %llu, last %llu)", e->page == ~0ull ? " (shared slot)" : "", (unsigned long long)e->fence, (unsigned long long)done, (unsigned long long)mtl_last_fence());
    for (int i = 0; i < GWW_N; i++) if (g_gww[i].fence && a >= g_gww[i].lo && a < g_gww[i].hi) NOTE(" in a large GPU write %#llx..%#llx: fence %llu", (unsigned long long)g_gww[i].lo, (unsigned long long)g_gww[i].hi, (unsigned long long)g_gww[i].fence);
    id<MTLBuffer> gm = g_gmem_buf;   // the raw global memory table (gmem_map): what a raw load or store of the address reaches
    if (gm) { const uint64_t *t = (const uint64_t *)gm.contents; int hit = 0;
        for (int k = 1; k < DMSH_GMEM_MAP_ENTRIES && t[(size_t)k * (DMSH_GMEM_MAP_ENTRY / 8)] != ~0ull; k++) { const uint64_t *e = t + (size_t)k * (DMSH_GMEM_MAP_ENTRY / 8); if (a >= e[0] && a < e[1]) { hit = k; break; } }
        if (hit) NOTE(" raw memory table entry %d", hit);
        else NOTE(" in no raw memory table entry (a raw load reads 0, a store is dropped)%s", addr_meets((uintptr_t)a, (uintptr_t)a + 1) ? "" : "; no pool address given in it"); }
    { char vn[200]; void nvn_vpool_note(uint64_t, char *, size_t); nvn_vpool_note(a, vn, sizeof vn); NOTE("%s", vn); }
    #undef NOTE
}
void dm_gfx_texdump_next(const char *path) {
    if (g_td_frame == -2) td_note(nil, 0);   // read DM_NVN_TEXDUMP first, so it does not override the request
    g_td_path = strdup(path); g_td_list = [NSMutableArray array]; g_td_done = 0; g_td_frame = (long)atomic_load(&g_cur_frame) + 1;
}
static void td_dump(void) {
    g_td_done = 1;
    rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    mtl_finish_gpu();
    static id<MTLRenderPipelineState> ps; static id<MTLSamplerState> sp;
    if (!ps) {
        NSError *e = nil; id<MTLLibrary> lib = host_lib("texdump", &e);   // dm/gfx/msl/texdump.metal
        MTLPixelFormat cf = MTLPixelFormatRGBA8Unorm;
        ps = lib ? host_rps(lib, @"vs", @"fs", 1, &cf, nil, 1, &e) : nil;
        MTLSamplerDescriptor *sd = [MTLSamplerDescriptor new]; sd.supportArgumentBuffers = YES; sp = [g_dev newSamplerStateWithDescriptor:sd];   // bound through an argument table on the Metal 4 queue (once_frag)
        if (!ps) { MLOG("[RED] TEXDUMP pipeline failed %s", e.localizedDescription.UTF8String); return; }
    }
    MLOG("[texdump] frame %ld: %lu color targets", g_td_frame, (unsigned long)g_td_list.count);
    // DM_NVN_TEXRAW=index,...: save raw bytes by texture index (including 3D; file: %d in the path is replaced with the index, suffix .raw, first-line text header: width height depth format bytes-per-row)
    for (const char *q = getenv("DM_NVN_TEXRAW"); q && *q; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) {
        if (!strncmp(q, "info", 4)) {   // DM_NVN_TEXRAW=info: the textures remembered by DM_NVN_TEXINFO
            static char buf[256]; size_t o = 0; for (int i = 0; i < g_texinfo_n; i++) o += snprintf(buf + o, sizeof buf - o, "%s%llu", i ? "," : "", (unsigned long long)g_texinfo_ser[i]);
            if (o) { static char env[300]; snprintf(env, sizeof env, "%s", buf); setenv("DM_NVN_TEXRAW", env, 1); q = getenv("DM_NVN_TEXRAW"); MLOG("[texraw] info → %s", q); } else continue;
        }
        uint64_t ser = (uint64_t)atoll(q); id o = tex_get(ser);
        id<MTLTexture> t = [o isKindOfClass:[NvPkg class]] ? ((NvPkg *)o)->tex : o;
        if (!t) { MLOG("[texraw] ser=%llu not in the serial table", ser); continue; }
        int bw, bh; NSUInteger w = t.width, h = t.height, dz = t.depth;
        size_t bpp = mtl_pf_bytes(t.pixelFormat); if (!bpp) bpp = 4; (void)bw; (void)bh;   // the texel size of the format (RG32 is 8 bytes; upstream 0adf5bbc6)
        size_t row = w * bpp, img = row * h;
        id<MTLBuffer> buf = [g_dev newBufferWithLength:img * dz options:MTLResourceStorageModeShared];
        NvOnce *cb = once_new(1); once_use(cb, t); once_use(cb, buf); id<MTL4ComputeCommandEncoder> b = once_copy(cb);
        MTLBlitOption bo = t.pixelFormat == MTLPixelFormatDepth32Float_Stencil8 ? MTLBlitOptionDepthFromDepthStencil : MTLBlitOptionNone;   // depth-stencil: the 32-bit float depth plane only
        [b copyFromTexture:t sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(w, h, dz) toBuffer:buf destinationOffset:0 destinationBytesPerRow:row destinationBytesPerImage:img options:bo];
        once_end(cb, b); once_wait(cb);
        char path[1024]; snprintf(path, sizeof path, g_td_path, (int)ser); strlcat(path, ".raw", sizeof path);
        FILE *f = fopen(path, "wb"); if (f) { fprintf(f, "%lu %lu %lu %lu %zu\n", (unsigned long)w, (unsigned long)h, (unsigned long)dz, (unsigned long)t.pixelFormat, row); fwrite(buf.contents, 1, img * dz, f); fclose(f); }
        MLOG("[texraw] ser=%llu %lux%lux%lu format %lu → %s", ser, (unsigned long)w, (unsigned long)h, (unsigned long)dz, (unsigned long)t.pixelFormat, path);
    }
    for (NSArray *e in g_td_list) {
        id<MTLTexture> t = e[0]; uint64_t ser = [e[1] unsignedLongLongValue]; NSUInteger lv = [e[2] unsignedIntegerValue], sl = [e[3] unsignedIntegerValue];
        // 2D arrays are saved by the attached layer (file index ser*100 + layer*10 + level; layer 0 is named like 2D)
        if (t.textureType != MTLTextureType2D && t.textureType != MTLTextureType2DArray) { MLOG("[texdump] ser=%llu type %lu skipped", ser, (unsigned long)t.textureType); continue; }
        if (getenv("DM_NVN_SNAPRAW")) {   // Also save the raw bytes (converting an HDR target to an 8-bit image truncates; first-line text header: width height format bytes-per-row)
            NSUInteger rw = MAX(t.width >> lv, 1u), rh = MAX(t.height >> lv, 1u);
            size_t bpp = t.pixelFormat == MTLPixelFormatRGBA16Float ? 8 : t.pixelFormat == MTLPixelFormatRGBA32Float ? 16 : t.pixelFormat == MTLPixelFormatR16Float || t.pixelFormat == MTLPixelFormatR16Unorm ? 2 : 4;
            id<MTLBuffer> rb = [g_dev newBufferWithLength:rw * rh * bpp options:MTLResourceStorageModeShared];
            NvOnce *rc = once_new(1); once_use(rc, t); once_use(rc, rb); id<MTL4ComputeCommandEncoder> bb = once_copy(rc);
            [bb copyFromTexture:t sourceSlice:0 sourceLevel:lv sourceOrigin:MTLOriginMake(0, 0, 0) sourceSize:MTLSizeMake(rw, rh, 1) toBuffer:rb destinationOffset:0 destinationBytesPerRow:rw * bpp destinationBytesPerImage:rw * rh * bpp];
            once_end(rc, bb); once_wait(rc);
            char rp_[1024]; snprintf(rp_, sizeof rp_, g_td_path, (int)(ser * 100 + lv));
            if (e.count > 4) { char tail[64]; snprintf(tail, sizeof tail, "_s%03d", [e[4] intValue]); strlcat(rp_, tail, sizeof rp_); }   // TEXSNAP copies of one target: one file per pass
            strlcat(rp_, ".raw", sizeof rp_);
            FILE *f = fopen(rp_, "wb"); if (f) { fprintf(f, "%lu %lu %lu %zu\n", (unsigned long)rw, (unsigned long)rh, (unsigned long)t.pixelFormat, rw * bpp); fwrite(rb.contents, 1, rw * rh * bpp, f); fclose(f); }
        }
        id<MTLTexture> v = mtl_view(t, t.pixelFormat, MTLTextureType2D, NSMakeRange(lv, 1), NSMakeRange(sl, 1));
        if (!v) { MLOG("[texdump] ser=%llu lv=%lu layer %lu: no view (outside the texture), skipped", ser, (unsigned long)lv, (unsigned long)sl); continue; }
        NSUInteger w = MAX(t.width >> lv, 1u), h = MAX(t.height >> lv, 1u);
        MTLTextureDescriptor *od = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:w height:h mipmapped:NO];
        od.usage = MTLTextureUsageRenderTarget | MTLTextureUsageShaderRead; od.storageMode = MTLStorageModePrivate;
        id<MTLTexture> o = [g_dev newTextureWithDescriptor:od];
        NvOnce *cb = once_new(1); once_use(cb, o); once_use(cb, t);
        MTL4RenderPassDescriptor *rp = [MTL4RenderPassDescriptor new];
        rp.colorAttachments[0].texture = o; rp.colorAttachments[0].loadAction = MTLLoadActionDontCare; rp.colorAttachments[0].storeAction = MTLStoreActionStore;
        id<MTL4RenderCommandEncoder> en = once_pass(cb, rp);
        [en setViewport:(MTLViewport){0, 0, (double)w, (double)h, 0, 1}]; [en setRenderPipelineState:ps]; once_frag(cb, en, v, sp);
        [en drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3]; once_end(cb, en); once_wait(cb);
        char path[1024]; snprintf(path, sizeof path, g_td_path, (int)(ser * 100 + sl * 10 + lv));
        if (e.count > 4) { snprintf(path, sizeof path, g_td_path, 0); char *dot = strrchr(path, '.'); char ext[16] = ""; if (dot) { strlcpy(ext, dot, sizeof ext); *dot = 0; }
            char tail[64]; snprintf(tail, sizeof tail, "_s%03d_%llu_%lu%s", [e[4] intValue], (unsigned long long)ser, (unsigned long)lv, ext); strlcat(path, tail, sizeof path); }   // TEXSNAP copy
        MLOG("[texdump] ser=%llu lv=%lu layer %lu format %lu %lux%lu", ser, (unsigned long)lv, (unsigned long)sl, (unsigned long)t.pixelFormat, (unsigned long)w, (unsigned long)h);
        shot(o, path, 0, NULL);
    }
    [g_td_list removeAllObjects];
}
// DM_NVN_TEXSNAP=in-frame index,... (together with the frame number and path of DM_NVN_TEXDUMP): as soon as these render passes end, copy their color attachments and save them together with the end-of-frame dump
// (the same target is often cleared and reused within a frame, so the end-of-frame state cannot reflect the output of intermediate passes); saved as <TEXDUMP path with %d = 0>_s<in-frame index>_<serial>_<level>.png
static int g_ts_idx[64], g_ts_n = -1, g_ts_on; static uint64_t g_ts_first, g_ts_curf = ~0ull;
static __strong id<MTLTexture> g_ts_att[8]; static uint64_t g_ts_ser[8]; static NSUInteger g_ts_lv[8]; static int g_ts_na;
void ts_note(MTL4RenderPassDescriptor *pd, NSUInteger nc) {
    if (g_ts_n < 0) { g_ts_n = 0; const char *e = getenv("DM_NVN_TEXSNAP");
        for (const char *q = e; q && *q && g_ts_n < 64; q = strchr(q, ',') ? strchr(q, ',') + 1 : q + strlen(q)) g_ts_idx[g_ts_n++] = atoi(q); }
    g_ts_on = 0; if (!g_ts_n || g_td_frame < 0 || g_td_done) return;
    uint64_t f = atomic_load(&g_cur_frame); if (f != g_ts_curf) { g_ts_curf = f; g_ts_first = g_stat_pass; }
    if ((long)f != g_td_frame) return;
    int idx = (int)(g_stat_pass - g_ts_first); for (int i = 0; i < g_ts_n; i++) if (g_ts_idx[i] == idx) g_ts_on = idx + 1;
    g_ts_na = 0; if (!g_ts_on) return;
    for (NSUInteger i = 0; i < nc && i < 8; i++) { id<MTLTexture> t = pd.colorAttachments[i].texture; if (!t) continue;
        g_ts_att[g_ts_na] = t; g_ts_ser[g_ts_na] = R.rt.color[i] ? R.rt.color[i]->serial : 0; g_ts_lv[g_ts_na] = pd.colorAttachments[i].level; g_ts_na++; }
}
void ts_after(void) {
    if (!g_ts_on) return;
    // The copy goes into the replay stream (Metal 4 copy encoder, after the pass that just ended). A command buffer of the classic queue, committed here, ran before the
    // Metal 4 command buffer holding the pass was even committed, so every snapshot showed the attachments as they were before the pass (found on Tears of the Kingdom)
    for (int i = 0; i < g_ts_na; i++) {
        id<MTLTexture> t = g_ts_att[i]; if (t.textureType != MTLTextureType2D && t.textureType != MTLTextureType2DArray) continue;   // 2D arrays take slice 0
        MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:t.pixelFormat width:t.width height:t.height mipmapped:t.mipmapLevelCount > 1];
        d.usage = MTLTextureUsageShaderRead; d.storageMode = MTLStorageModePrivate; d.mipmapLevelCount = t.mipmapLevelCount;
        id<MTLTexture> c = [g_dev newTextureWithDescriptor:d]; res_add(c);
        NSUInteger lv = g_ts_lv[i], w = MAX((NSUInteger)1, t.width >> lv), h = MAX((NSUInteger)1, t.height >> lv);
        enc_b_copy_texture(blit(), t, 0, lv, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, 1), c, 0, lv, MTLOriginMake(0, 0, 0));
        [g_td_list addObject:@[c, @(g_ts_ser[i]), @(g_ts_lv[i]), @0, @(g_ts_on - 1)]];   // the end-of-frame fields (texture, serial, level, layer) plus the in-frame pass index: saved as <path with %d = 0>_s<index>_<serial>_<level>.png
    }
    g_ts_on = 0;
}
// Ring of actual presentation times: present sequence number -> presentedTime (seconds; -1 = dropped by the system, not presented)
#define PRING 1024
typedef struct { uint64_t n; double t; } pres_ent;
static pres_ent g_pres[PRING];
// Get the actual presentation time of the nth present (returns 0 if not ready, -1 if dropped)
double mtl_presented_time(uint64_t n) { pres_ent e = g_pres[n % PRING]; return e.n == n ? e.t : 0; }
// Ring of the display-link tick that took each present (written on the display-link callback thread, read 8 presents later for DM_NVN_TSV, as g_pres): its target display time
// (seconds, CACurrentMediaTime base), how long before it the callback ran, the callbacks since the previous present's (1 = no tick without a frame) and the longest interval between them
typedef struct { uint64_t n; double target, lead_ms, gap_ms; int ticks; } link_ent;
static link_ent g_link_ring[PRING];
int mtl_link_tick(uint64_t n, double *target, double *lead_ms, int *ticks, double *gap_ms) {
    link_ent e = g_link_ring[n % PRING]; if (e.n != n) return 0;
    *target = e.target; *lead_ms = e.lead_ms; *ticks = e.ticks; *gap_ms = e.gap_ms; return 1;
}
static _Atomic uint64_t g_drawable_ns;   // Accumulated wall clock waiting for nextDrawable in present (timing instrumentation)
uint64_t mtl_drawable_ns_take(void) { return atomic_exchange(&g_drawable_ns, 0); }
// Maximum refresh rate (Hz) of the screen when there is a window; returns 0 without a window. Mac uses CoreGraphics display modes (thread-safe C interface; the present configuration is read on the game thread).
// iOS: the app window scene's screen's maximumFramesPerSecond, which front_ios.m caches on the main thread (front_screen_max_fps; UIScreen.mainScreen, read here before, is deprecated)
int mtl_display_hz(void) {
    if (!front_metal_layer()) return 0;
#if TARGET_OS_OSX
    CGDisplayModeRef m = CGDisplayCopyDisplayMode(CGMainDisplayID());
    double hz = m ? CGDisplayModeGetRefreshRate(m) : 0; if (m) CGDisplayModeRelease(m);
    return (int)(hz + 0.5);
#else
    return front_screen_max_fps();
#endif
}
static _Atomic uint64_t g_present_stall_ns;   // For unit tests: an extra pause before each present on the present thread (simulating a drawable that stays unavailable)
static CAMetalLayer *g_present_layer_resident;
void mtl_present_test_stall(uint64_t ns) { g_present_stall_ns = ns; }
// The present's two pipelines, made together at the first present (and again for a new drawable format): fs, and fs_rcas for Sharpening. Both are made whole through the Metal 4
// compiler (host_rps) on the present thread, outside the pipeline archive, so a Sharpening picked in the in-game menu later finds its pipeline made and never compiles one inside a present
static void present_pipeline(MTLPixelFormat format) {
    if (!g_blit_pso || g_blit_fmt != format) {
        NSError *e = nil;
        id<MTLLibrary> lib = host_lib("present", &e);
        if (!lib) MDIE("present shader library did not load %s", e.localizedDescription.UTF8String);
        g_blit_pso = host_rps(lib, @"vs", @"fs", 1, &format, nil, 1, &e);
        if (!g_blit_pso) MDIE("present pipeline failed %s", e.localizedDescription.UTF8String);
        e = nil; g_rcas_pso = host_rps(lib, @"vs", @"fs_rcas", 1, &format, nil, 1, &e);   // an error when present.metal has no fs_rcas
        if (!g_rcas_pso) MLOG("[RED] present: no Sharpening pipeline (%s); the present draws without sharpening", e ? e.localizedDescription.UTF8String : "no error given");
        g_blit_fmt = format;
        MTLSamplerDescriptor *sd = [MTLSamplerDescriptor new]; sd.minFilter = sd.magFilter = MTLSamplerMinMagFilterLinear; sd.supportArgumentBuffers = YES;
        g_blit_samp = [g_dev newSamplerStateWithDescriptor:sd];
    }
}
// Present samples only the valid source rectangle declared by NVN; kept separate from the raw swapchain readback screenshot. Edges are clamped to the texel centers of the valid area, so bilinear does not read the black texels outside.
// Present samples the raw bytes stored in the swapchain texture (the Switch's scan-out sends the stored bytes as they are): an sRGB source is replaced by a non-sRGB view of the same storage,
// otherwise sampling decodes to linear first, the BGRA8Unorm layer does not encode again, and the whole picture comes out dark. Other formats are returned as they are (Mario's swapchain is RGBA8 and does not come here).
// View cache of 4 entries: swapchain textures live long and are few; a view holds its parent, so an equal parent pointer means the same object. A replaced view is released after the submissions that used it complete (Metal 4 does not retain resources)
static id<MTLTexture> present_raw_src(id<MTLTexture> src) {
    MTLPixelFormat pf = src.pixelFormat == MTLPixelFormatRGBA8Unorm_sRGB ? MTLPixelFormatRGBA8Unorm : src.pixelFormat == MTLPixelFormatBGRA8Unorm_sRGB ? MTLPixelFormatBGRA8Unorm : MTLPixelFormatInvalid;
    if (pf == MTLPixelFormatInvalid) return src;
    static __strong id<MTLTexture> views[4]; static int next; static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mu);
    id<MTLTexture> v = nil;
    for (int i = 0; i < 4 && !v; i++) if (views[i] && views[i].parentTexture == src) v = views[i];
    if (!v && (v = [src newTextureViewWithPixelFormat:pf])) { if (views[next]) defer_obj_unref(views[next]); views[next] = v; next = (next + 1) & 3; }
    pthread_mutex_unlock(&mu);
    if (!v) { RED_ONCE(69, "present: cannot create a non-sRGB view of the sRGB swapchain texture (format %lu); presenting the decoded values", (unsigned long)src.pixelFormat); return src; }
    return v;
}
// Picture Stretch (the iOS front end's DM_PICTURE_FIT=stretch, front_ios.m): the front end makes the canvas the whole screen and asks the present to draw the picture over all of it,
// its shape not kept. Set by the front end on every layout (off on a TV, in a portrait split and in Fit or Fill), read on the present thread
static _Atomic int g_present_stretch;
void mtl_present_stretch(int on) {
    on = on != 0;
    if (atomic_exchange_explicit(&g_present_stretch, on, memory_order_relaxed) != on)
        MLOG("present: picture %s", on ? "stretched over the whole canvas (Picture Stretch)" : "drawn in its own shape");
}
// The rectangle of the canvas (dw x dh) the picture (pw x ph) is drawn into: the picture's aspect ratio kept and centred, black bars in the rest (no stretching when the screen's ratio
// differs from the game's, e.g. iPhone about 19.5:9 against the game's 16:9); when the ratios differ by under 1 % (the remainder from a game width that is a multiple of 8 in the
// full-screen setup, e.g. 1952x900 against 2868x1320 differs by 0.17 %) the whole canvas, leaving no border of a few pixels. With Picture Stretch (mtl_present_stretch) the whole canvas always
static MTLViewport present_viewport(double pw, double ph, double dw, double dh) {
    if (atomic_load_explicit(&g_present_stretch, memory_order_relaxed)) return (MTLViewport){0, 0, dw, dh, 0, 1};
    double s = fmin(dw / pw, dh / ph), w = round(pw * s), h = round(ph * s);   // the size first: pw * s can land a hair over the canvas (1600 * 1710 / 1600 = 1710.0000000000002) and floor of half the negative rest put the picture at x = -1, its first column off the left edge (upstream NXNative 396441a92)
    MTLViewport vp = {floor((dw - w) / 2), floor((dh - h) / 2), w, h, 0, 1};
    if (fabs((dw / dh) / (pw / ph) - 1) < 0.01) vp = (MTLViewport){0, 0, dw, dh, 0, 1};
    return vp;
}
// The shape the picture is shown in, whatever part of the texture it comes from. The Switch's compositor stretches a buffer's crop to the layer, so a crop only picks texels: Super
// Mario Galaxy 2 draws its storybook cutscenes anamorphically into 1200x960 of a 1920x1080 swapchain (800x640 handheld). The layer fills the display, 16:9, unless the game sized it
// (vi::CreateLayer with a size, hle_vi.c). A screen taller than 16:9 (DM_SCREEN_ASPECT, loader.c) counts only for a texture of its shape: only builds with screen-shape stubs render it.
static _Atomic uint64_t g_layer_shape, g_screen_shape;   // w | h << 32, 0 = none
void mtl_present_layer(uint32_t w, uint32_t h) { atomic_store(&g_layer_shape, (uint64_t)w | (uint64_t)h << 32); }
void mtl_present_screen(uint32_t w, uint32_t h) { atomic_store(&g_screen_shape, (uint64_t)w | (uint64_t)h << 32); }
static void present_shape(id<MTLTexture> src, double *w, double *h) {
    uint64_t v = atomic_load(&g_screen_shape);
    if (v && fabs(((double)src.width / src.height) / ((double)(uint32_t)v / (double)(v >> 32)) - 1) < 0.01) { *w = src.width; *h = src.height; return; }
    v = atomic_load(&g_layer_shape);
    *w = v ? (double)(uint32_t)v : 1920; *h = v ? (double)(v >> 32) : 1080;
}
static MTLViewport present_fit(id<MTLTexture> src, double dw, double dh) { double w, h; present_shape(src, &w, &h); return present_viewport(w, h, dw, dh); }
// The pixel size of the picture in its shape (w x h, present_shape) with as many pixels as a source of sw x sh texels has across or down, whichever needs more: what a drawable
// needs to show every texel
static void present_render_size(double sw, double sh, double w, double h, int *pw, int *ph) {
    double s = fmax(sw / w, sh / h); *pw = (int)lround(w * s); *ph = (int)lround(h * s);
}
// The render size reported to the front end's drawable (front_picture_size), from the crop's pixels (cw x ch, present_render_size of the crop), not the window texture's: Fortune's
// Weave, Bananza, Star Fox, Mario Kart World and Ocarina of Time present a 1920x1080 crop of a 3840x2160 texture, and a drawable of the texture's size held twice the pixels the
// picture has. A dynamic resolution moves the crop every few frames, so the size held is the largest crop seen since the window texture's own size last changed (tw x th, the
// texture's pixels in the picture's shape: a mode change), and a new size counts once it has held for 30 presents (the first at once), so a crop that shrinks resizes nothing and one
// that grows resizes once it stops growing. A texture size that changes counts, the same way, once it has held for 30 presents: a game presenting textures of two sizes in turn keeps
// the larger of their crops. Returns 1 with *pw x *ph when the front end is to take a new size
typedef struct { int tw, th, ttw, tth, theld, mw, mh, rw, rh, cw, ch, held; } present_size_hold;
static present_size_hold g_present_size;   // the present thread's (present_now)
static int present_size_step(present_size_hold *z, int tw, int th, int cw, int ch, int *pw, int *ph) {
    if (tw != z->ttw || th != z->tth) { z->ttw = tw; z->tth = th; z->theld = 0; }
    if ((tw != z->tw || th != z->th) && (!z->tw || ++z->theld >= 30)) { z->tw = tw; z->th = th; z->mw = z->mh = 0; }   // a mode change: the largest crop starts again
    if (cw > z->mw) z->mw = cw;
    if (ch > z->mh) z->mh = ch;
    if (z->mw != z->cw || z->mh != z->ch) { z->cw = z->mw; z->ch = z->mh; z->held = 0; }
    if ((z->mw == z->rw && z->mh == z->rh) || (z->rw && ++z->held < 30)) return 0;
    z->rw = z->mw; z->rh = z->mh; *pw = z->rw; *ph = z->rh; return 1;
}
// The valid source rectangle of a present (x, y, width, height; the crop of nvnWindowSetCrop, zero = the whole texture); 0 when it lies outside the texture
static int present_crop_rect(id<MTLTexture> src, const int crop[4], NSUInteger r[4]) {
    r[0] = 0; r[1] = 0; r[2] = src.width; r[3] = src.height;
    if (!crop || !(crop[2] || crop[3])) return 1;
    if (crop[0] < 0 || crop[1] < 0 || crop[2] <= 0 || crop[3] <= 0 ||
        (uint64_t)crop[0] + crop[2] > src.width || (uint64_t)crop[1] + crop[3] > src.height) {
        MLOG("[RED] present crop out of bounds: %d,%d %dx%d / source texture %lux%lu", crop[0], crop[1], crop[2], crop[3], (unsigned long)src.width, (unsigned long)src.height); return 0;
    }
    r[0] = crop[0]; r[1] = crop[1]; r[2] = crop[2]; r[3] = crop[3]; return 1;
}
// ---------- Upscaling in the present (DM_PRESENT_UPSCALE) ----------
// Opt-in spatial scaling of the valid content to its letterboxed viewport. Copy the crop to an origin-aligned texture, scale in perceptual mode (present_raw_src supplies gamma
// bytes), then draw 1:1 with the usual origin and output format. Queue barriers serialize both the frame's rendering and reuse of the scaler's textures across presents.
// Replacing those textures waits for earlier presents; throttle replacement during resizing, and keep standard scaling for refused sizes. Offscreen captures own separate state.
// The scaler's input is the window texture's size, not the crop's, wherever the texture fits in the picture's rectangle (fx_input_size): a game whose dynamic resolution moves
// its crop inside the texture every few frames (Pokémon Scarlet calls nvnWindowSetCrop about once a frame; Super Mario Odyssey's crop moves) then keeps one scaler, which takes
// the crop's size as its content (inputContentWidth / Height) each frame. Keyed on the crop, each new size cost FX_REMAKE_PRESENTS bilinear frames and a drain of the presents
// in flight on the present thread. Measured on an M4 Max with MTL4FXSpatialScaler: content from 0.5 to 1.0 of 1920x1080 scaled to 2346x1320 matches a scaler made for the
// content's size within 45-58 dB PSNR, with no texel from outside the content in the output, in the same GPU time
#define FX_REMAKE_PRESENTS 30
#define FX_PAD 2   // texels of the crop's edge repeated past it in a texture-sized input (fx_encode)
// in: the scaler's input, made at the first present that copies the crop into it; with edge smoothing on (aa_encode) the scaler reads the smoothed texture instead and none is
// made. iw, ih, ipf: the input the scaler was made for
typedef struct { id<MTL4FXSpatialScaler> sc; id<MTLTexture> in, out; uint64_t made_at; int made; NSUInteger refused[6], iw, ih; MTLPixelFormat ipf; } fx_state;
static fx_state g_fx_present;   // only the present thread encodes or replaces the scaler
static _Atomic int g_fx_mode = -1;   // 1 = metalfx, 0 = off (nvn_upscale_pick.h UP_*); the live present sets it (fx_mode), a capture reads it
static _Atomic int g_fx_req = -1;    // the in-game menu's Upscaling (mtl_present_upscale_set, main thread) until the live present takes it at its next present; -1 none
// The front ends' (front.h): the iPhone's copies under its in-game menu's lock; the Mac's menus change no variable while the game runs, and the unit tests have no front end
__attribute__((weak)) int front_env_copy(const char *name, char *out, size_t cap) {
    const char *e = getenv(name);
    if (cap) strlcpy(out, e ? e : "", cap);
    return e != NULL;
}
// The in-game menu's Upscaling while the game runs (front_ios.m dm_setting_live): the live present takes the new mode at its next present (fx_mode, nvn_upscale_pick.h). A scaler
// made before is kept for FX_IDLE_PRESENTS presents, so switching back to MetalFX soon after makes none for the same sizes (FX_REMAKE_PRESENTS still spaces new ones), and released
// after that (present_fx_idle; DM_PRESENT_FX_KEEP=1 keeps it for good); a GPU without the scaler stays bilinear. Nothing the game sees changes
void mtl_present_upscale_set(const char *mode) {
    int v = up_parse(mode);
    if (v < 0) { MLOG("[RED] present upscaling: %s from the in-game menu is not metalfx or off; ignored", mode ? mode : "(none)"); return; }
    up_post(&g_fx_req, v);
}
// live: the live present's (0 for a capture, which never takes the menu's pick). The first present decides from DM_PRESENT_UPSCALE, as before; then the mode in force, until a pick
static int fx_mode(int live) {
    int want = -1, v = up_now(&g_fx_mode, &g_fx_req, live, &want);
    if (v >= 0) return v;   // every present but the first and the one after a pick
    int was = atomic_load_explicit(&g_fx_mode, memory_order_relaxed);
    if ((v = want) < 0) {   // a copy taken under the in-game menu's lock (front.h front_env_copy): the menu may set the variable on the main thread right now
        char e[256]; v = up_parse(front_env_copy("DM_PRESENT_UPSCALE", e, sizeof e) ? e : NULL);
        if (v < 0) { MLOG("[RED] DM_PRESENT_UPSCALE=%s: metalfx or off; keeping off", e); v = UP_OFF; }
    }
    if (v && ![MTLFXSpatialScalerDescriptor supportsMetal4FX:g_dev]) { MLOG("present upscaling: this GPU has no Metal 4 MetalFX spatial scaler; the present scales bilinearly"); v = UP_OFF; }
    if (v != was) MLOG("present upscaling (%s): %s", want >= 0 ? "in-game menu" : "DM_PRESENT_UPSCALE", v == UP_METALFX ? "metalfx, MetalFX's spatial scaler where the picture is shown larger than the game renders it" : "off, bilinear");
    up_set(&g_fx_mode, v);
    return v;
}
// MetalFX scales the content (cw x ch) to its rectangle on the canvas (vp) when the rectangle is at least as large in both directions and larger in one, and of the content's shape
// (within present_viewport's 1 %): a picture stretched to another shape (Picture Stretch) is scaled by the bilinear pass, MetalFX's spatial scaler being made for a uniform scale.
// fx_why says which (front.h DM_FX_UPSCALED, DM_FX_STRETCHED or DM_FX_NOT_LARGER), for the in-game menu's note (g_fx_why); fx_wanted only whether
static int fx_why(MTLViewport vp, NSUInteger cw, NSUInteger ch) {
    NSUInteger w = (NSUInteger)vp.width, h = (NSUInteger)vp.height;
    int stretch = atomic_load_explicit(&g_present_stretch, memory_order_relaxed);
    // Picture Stretch: a picture stretched to another shape (1 % or more) goes through the bilinear pass. Off, upstream's rule alone, so an anamorphic crop drawn in its layer's
    // shape (Super Mario Galaxy 2's 1200x960 shown at 16:9, present_fit) keeps MetalFX
    if (stretch && w && h && cw && ch && fabs(((double)w / h) / ((double)cw / ch) - 1) >= 0.01) return DM_FX_STRETCHED;
    if (cw && ch && w >= cw && h >= ch && (w > cw || h > ch)) return DM_FX_UPSCALED;
    // Not shown larger here, but stretched: the iPhone front end sizes a stretched drawable at the texture (front_ios.m dm_drawable_size, the picture's render size), so a crop
    // that fills its texture meets a rectangle of its own size and shape, and Core Animation stretches the layer over the screen. The reason the player sees is the stretch
    return stretch ? DM_FX_STRETCHED : DM_FX_NOT_LARGER;
}
static int fx_wanted(MTLViewport vp, NSUInteger cw, NSUInteger ch) { return fx_why(vp, cw, ch) == DM_FX_UPSCALED; }
// What the live present last did with each picture setting (front.h mtl_present_fx_why and the others): written by the present thread at each live present, never by a capture,
// and read by the iOS in-game menu on the main thread when it opens (front_ios.m dm_setting_why). Relaxed: a note one present late says the same
static _Atomic int g_fx_why, g_sharp_why, g_aa_why;
int mtl_present_fx_why(void) { return atomic_load_explicit(&g_fx_why, memory_order_relaxed); }
int mtl_present_sharp_why(void) { return atomic_load_explicit(&g_sharp_why, memory_order_relaxed); }
int mtl_present_aa_why(void) { return atomic_load_explicit(&g_aa_why, memory_order_relaxed); }
// DM_NVN_PRESENT_FX_EXACT=1: the scaler's input is the crop's size always, as before the texture-sized input (fx_input_size), for an A/B on a GPU whose MetalFX may treat a
// content well below the input size differently from the M4 Max's. Read once (-1 until then); the tests set it
static _Atomic int g_fx_exact = -1;
// The scaler's input size for content cw x ch of a tw x th texture scaled to ow x oh: the texture's when the texture is no larger than the output in either direction and smaller
// in one (fx_wanted's rule, for the texture), so the crop can move inside it without a new scaler. Otherwise the crop's: in a narrow layout (an iPad or a portrait split, about
// 1320 pixels across for a 1920x1080 texture whose crop is 960x540) a texture-sized input would be larger than the output, which MetalFX's spatial scaler does not scale down to
static void fx_input_size(NSUInteger tw, NSUInteger th, NSUInteger cw, NSUInteger ch, NSUInteger ow, NSUInteger oh, NSUInteger *iw, NSUInteger *ih) {
    int exact = atomic_load_explicit(&g_fx_exact, memory_order_relaxed);
    if (exact < 0) { const char *e = getenv("DM_NVN_PRESENT_FX_EXACT"); exact = e && atoi(e) != 0; atomic_store_explicit(&g_fx_exact, exact, memory_order_relaxed);
        if (exact) MLOG("present upscaling (DM_NVN_PRESENT_FX_EXACT=1): the MetalFX scaler's input is the crop's size, a new scaler for each new crop size"); }
    int fits = tw <= ow && th <= oh && (tw < ow || th < oh);
    *iw = fits && !exact ? tw : cw; *ih = fits && !exact ? th : ch;
}
// Encodes the upscale of the rectangle r of raw into cb (see above); returns the scaled picture, which the present pass draws 1:1 into vp, or nil (the bilinear pass).
// remake_wait: fx is the present thread's, whose textures presents still on the GPU may read: a new scaler waits for them and for FX_REMAKE_PRESENTS presents since the last.
// ready: raw is edge smoothing's output (aa_encode), the crop at its origin with its edge repeated FX_PAD texels past it: a scaler whose input is that texture's size reads it
// as it is, so the present makes one copy of the picture with both on, not two
static id<MTLTexture> fx_encode(fx_state *fx, id<MTL4CommandBuffer> cb, id<MTLTexture> raw, const NSUInteger r[4], MTLViewport vp, MTLPixelFormat out_pf, int remake_wait, int ready) {
    NSUInteger cw = r[2], ch = r[3], ow = (NSUInteger)vp.width, oh = (NSUInteger)vp.height, iw, ih;
    int live = fx == &g_fx_present, why = fx_mode(live) != UP_METALFX ? DM_FX_OFF : fx_why(vp, cw, ch);   // a capture (present_offscreen_m4, its own fx_state) takes no pick
    // The live present's outcome for the in-game menu: upscaled from here on, unless MetalFX makes no scaler for this size (below). The FX_REMAKE_PRESENTS wait for a new
    // scaler stays "upscaled": it lasts half a second, and the scaler comes after it
    if (live) atomic_store_explicit(&g_fx_why, why, memory_order_relaxed);
    if (why != DM_FX_UPSCALED) return nil;
    fx_input_size(raw.width, raw.height, cw, ch, ow, oh, &iw, &ih);
    if (!fx->sc || fx->iw != iw || fx->ih != ih || fx->ipf != raw.pixelFormat || fx->out.width != ow || fx->out.height != oh || fx->out.pixelFormat != out_pf) {
        NSUInteger key[6] = {iw, ih, raw.pixelFormat, ow, oh, out_pf};
        if (!memcmp(key, fx->refused, sizeof key)) { if (live) atomic_store_explicit(&g_fx_why, DM_FX_REFUSED, memory_order_relaxed); return nil; }
        if (remake_wait && fx->made && g_present_n < fx->made_at + FX_REMAKE_PRESENTS) return nil;
        if (remake_wait) { pthread_mutex_lock(&g_pq_mu); while (g_pq_inflight && !gpu_gone()) pthread_cond_wait(&g_pq_cv, &g_pq_mu); pthread_mutex_unlock(&g_pq_mu); }
        res_remove(fx->in); res_remove(fx->out); fx->sc = nil; fx->in = fx->out = nil;
        uint64_t t0 = now_ns(); id<MTL4Compiler> comp = mtl_comp4();   // the host's one compiler (g_comp4)
        MTLFXSpatialScalerDescriptor *d = [MTLFXSpatialScalerDescriptor new];
        d.colorTextureFormat = raw.pixelFormat; d.outputTextureFormat = out_pf; d.inputWidth = iw; d.inputHeight = ih; d.outputWidth = ow; d.outputHeight = oh;
        d.colorProcessingMode = MTLFXSpatialScalerColorProcessingModePerceptual;
        id<MTL4FXSpatialScaler> sc = comp ? [d newSpatialScalerWithDevice:g_dev compiler:comp] : nil;
        fx->made_at = g_present_n; fx->made++;
        if (!sc) { memcpy(fx->refused, key, sizeof key); if (live) atomic_store_explicit(&g_fx_why, DM_FX_REFUSED, memory_order_relaxed);
            MLOG("present upscaling: MetalFX makes no spatial scaler for %lux%lu format %lu → %lux%lu format %lu%s; this size is scaled bilinearly", (unsigned long)iw, (unsigned long)ih, (unsigned long)raw.pixelFormat,
                 (unsigned long)ow, (unsigned long)oh, (unsigned long)out_pf, comp ? "" : " (no Metal 4 compiler)"); return nil; }
        MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:out_pf width:ow height:oh mipmapped:NO];
        td.storageMode = MTLStorageModePrivate; td.usage = sc.outputTextureUsage | MTLTextureUsageShaderRead;
        id<MTLTexture> out = [g_dev newTextureWithDescriptor:td];
        if (!out) { memcpy(fx->refused, key, sizeof key); if (live) atomic_store_explicit(&g_fx_why, DM_FX_REFUSED, memory_order_relaxed); MLOG("[RED] present upscaling: cannot create the scaler's output texture (%lux%lu)", (unsigned long)ow, (unsigned long)oh); return nil; }
        out.label = @"present upscale output";
        res_add(out); res_commit();
        fx->sc = sc; fx->out = out; fx->iw = iw; fx->ih = ih; fx->ipf = raw.pixelFormat;
        MLOG("present upscaling: MetalFX spatial scaler %lux%lu → %lux%lu (format %lu → %lu, scaler #%d, made in %.1f ms), %s", (unsigned long)iw, (unsigned long)ih, (unsigned long)ow, (unsigned long)oh,
             (unsigned long)raw.pixelFormat, (unsigned long)out_pf, fx->made, (now_ns() - t0) / 1e6,
             iw == raw.width && ih == raw.height ? "the window texture's size: a crop moving inside it keeps this scaler" : "the crop's size: a new crop size makes a new scaler");
    }
    if (ready && raw.width == iw && raw.height == ih && (raw.usage & fx->sc.colorTextureUsage) == fx->sc.colorTextureUsage) {   // edge smoothing's encoder ends with a barrier before the queue's later stages
        fx->sc.colorTexture = raw; fx->sc.inputContentWidth = cw; fx->sc.inputContentHeight = ch; fx->sc.outputTexture = fx->out;
        [fx->sc encodeToCommandBuffer:cb];
        return fx->out;
    }
    if (!fx->in) {
        MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:raw.pixelFormat width:iw height:ih mipmapped:NO];
        td.storageMode = MTLStorageModePrivate; td.usage = fx->sc.colorTextureUsage | MTLTextureUsageShaderRead;
        if (!(fx->in = [g_dev newTextureWithDescriptor:td])) { if (live) atomic_store_explicit(&g_fx_why, DM_FX_REFUSED, memory_order_relaxed); RED_ONCE(164, "present upscaling: cannot create the scaler's input texture (%lux%lu); scaled bilinearly", (unsigned long)iw, (unsigned long)ih); return nil; }
        fx->in.label = @"present upscale input";
        res_add(fx->in); res_commit();
    }
    id<MTL4ComputeCommandEncoder> ce = [cb computeCommandEncoder];
    [ce barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageBlit visibilityOptions:resource_vis()];   // after the frame's work
    [ce copyFromTexture:raw sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(r[0], r[1], 0) sourceSize:MTLSizeMake(cw, ch, 1) toTexture:fx->in destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(0, 0, 0)];
    // MetalFX's filter reads past the content's last column and row (inputContentWidth / Height do not stop it), and in a texture-sized input those texels are an earlier, larger
    // crop's: on the M4 Max the last two output columns of a 48x48 content scaled to 96x96 took a third of the magenta left beyond it. The crop's edge texels are copied into
    // FX_PAD columns and rows past it (eight small copies), as an input of the content's own size clamps to them; with them the picture is byte-identical to that of a scaler
    // made for the crop's size (t_present_crop), one texel of padding still left two pixels off
    for (NSUInteger k = 0; k < FX_PAD; k++) {
        if (cw + k < iw) [ce copyFromTexture:raw sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(r[0] + cw - 1, r[1], 0) sourceSize:MTLSizeMake(1, ch, 1) toTexture:fx->in destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(cw + k, 0, 0)];
        if (ch + k < ih) [ce copyFromTexture:raw sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(r[0], r[1] + ch - 1, 0) sourceSize:MTLSizeMake(cw, 1, 1) toTexture:fx->in destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(0, ch + k, 0)];
        for (NSUInteger j = 0; j < FX_PAD; j++) if (cw + j < iw && ch + k < ih)
            [ce copyFromTexture:raw sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(r[0] + cw - 1, r[1] + ch - 1, 0) sourceSize:MTLSizeMake(1, 1, 1) toTexture:fx->in destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(cw + j, ch + k, 0)];
    }
    [ce barrierAfterStages:MTLStageBlit beforeQueueStages:MTLStageAll visibilityOptions:resource_vis()];   // the scaler's encoders come after the copy
    [ce endEncoding];
    fx->sc.colorTexture = fx->in; fx->sc.inputContentWidth = cw; fx->sc.inputContentHeight = ch; fx->sc.outputTexture = fx->out;
    [fx->sc encodeToCommandBuffer:cb];
    return fx->out;
}
// ---------- A game's own upscaler drawn by MetalFX (DM_UPSCALER) ----------
// Donkey Kong Bananza upscales its frame with agl's NDSR network: one compute dispatch (agl_ndsr.pck, 24 variants; Splatoon Raiders ships 20) reading the scene colour (texture slot 0, R11G11B10F; see up_mfx_color)
// and writing the output picture (image slot 1), between the render-resolution passes and the output-resolution ones, which draw the UI over it. Its push constants (c[24], S.push[1])
// give the two rectangles: input origin x, y and last texel relative to it (inclusive), then the same for the output. On an M1 the network takes 3.5-5 ms a frame in handheld mode
// (960x540 → 1920x1080), MetalFX's spatial scaler about 1 ms. With DM_UPSCALER=metalfx (the launcher's Game's upscaler: MetalFX), a dispatch of one of the game's upscaler shaders
// (DM_GAME_UPSCALER_KEYS: game.py takes the compute shaders the shader map found in an NDSR pack, whatever engine ships it) is replaced by the spatial scaler from the input rectangle to the output rectangle, in the colour mode of that shader. MetalFX takes whole textures: each side is the
// game's own texture where it can be (up_mfx_encode; the input in its own format), else a texture of the scaler's own (RGBA16F; RGBA8Unorm for the output of sRGB input), which the input rectangle is drawn
// into first or which is drawn into the output rectangle after (copy_t2t_draw, a render pass each). An output rectangle not larger than the input in both directions, an indirect dispatch, or anything
// the checks below refuse runs the game's shader. The look changes (Apple's scaler instead of the game's network), so it is the player's choice; DM_UPSCALER=game (the default)
// keeps the network. Found with the iPhone port's NDSR replacement (PR #1073), which decoded the rectangles. The network's own cost on the GPU is the translator's
// LDSM / MOVM shuffles, open in docs/reference/shaders.md (Ampere HMMA through simdgroup_matrix)
// key: input w, h, output w, h, sRGB input, colour format, output format. in, out: the scaler's own input and output, made on first use (up_mfx_scratch) by a side that cannot take the game's texture;
// read: what the game's image is drawn from (out, or its sRGB view)
typedef struct { id<MTL4FXSpatialScaler> sc; id<MTLTexture> in, out, read; NSUInteger key[7]; uint64_t used; int refused; } up_mfx_scaler;   // used: its last use (g_up_mfx_use), for LRU eviction
// Dynamic resolution moves the input, and a format MetalFX refuses keeps its slot (refused) beside the RGBA16F scaler that stands in. NX 18 keeps 4 slots (upstream: 8): each slot can hold
// an input and an output texture of its own, so 8 could keep twice the scratch memory 4 did; a slot whose sides are the game's textures holds none
// One scaler per output (DM_NVN_MFX_CONTENT, on by default): an input that goes through the scaler's own texture keys the scaler on the output rectangle alone, the scaler made
// for an input of the output's size, and each dispatch gives its rectangle's size as the content (inputContentWidth / Height), as the present's scaler does (fx_input_size).
// Ocarina of Time's dynamic resolution moves its upscaler's input over 8 sizes (854x480 to 1440x810, each its own texture, into 1920x1080): with a scaler per input size the 4 slots
// made about 60 scalers a run, each 1-20 ms on the encode thread, and kept up to 4 scratch inputs and outputs (about 100 MB at 1920x1080); now one scaler and one pair. MetalFX reads
// past the content's last column and row, so the copy into the scaler's input draws on to the input's edge (the game's texture clamped at its own edge) and FX_PAD columns and rows
// past the content are its edge again (up_mfx_pad) where the game's texture has more texels there: on the M4 Max the output is then byte for byte that of a scaler made for the
// content's size (t_upscaler_mfx). An input taken straight (the game's whole texture) keeps a scaler of its own size. =0 keys every scaler on its input size again
enum { UP_MFX_SCALERS = 4 };
static up_mfx_scaler g_up_mfx[UP_MFX_SCALERS]; static uint64_t g_up_mfx_use;
static uint64_t g_up_mfx_made;   // scalers made (the scaler line's count)
static int up_mfx_content_on(void) {
    static int m = -1;
    if (m < 0) { m = sw_mode("DM_NVN_MFX_CONTENT", 1); if (m != 1) MLOG("DM_NVN_MFX_CONTENT=%d: a MetalFX scaler for the game's upscaler per input size, as before%s", m, m ? " in the other A/B phases" : ""); }
    return sw_on(m);
}
static uint64_t g_up_mfx_n, g_up_mfx_kept, g_up_mfx_straight[2];   // dispatches drawn by MetalFX, dispatches of a named shader left to it, of the drawn: input and output that were the game's own textures
static _Atomic int g_up_mfx_drawn;   // MetalFX drew the game's upscaler at its last dispatch: the present thread's view (present_sharpen draws no sharpening over MetalFX's picture; a bilinear stretch takes it)
void mtl_up_mfx_stats(uint64_t *n, uint64_t *kept) { *n = g_up_mfx_n; *kept = g_up_mfx_kept; }
// DM_NVN_UP_BILINEAR (profile key upscaler_bilinear; =0 off, =1 on in any game): where MetalFX would draw the game's upscaler (DM_UPSCALER=metalfx, up_mfx_wanted), a plain bilinear stretch
// from the input rectangle to the output rectangle draws it instead (copy_t2t_draw, one render pass), a picture trade of the owner's Balanced and Battery Saver; the Quality preset sets =0.
// Donkey Kong Bananza: MetalFX's spatial scaler (1048x590-1280x720 R11G11B10F → 1920x1080) took 0.6-1.4 ms a frame of GPU time on the iPhone 18 Pro Max, then its RGBA16F output was
// drawn back into the game's R11G11B10F image (a render pass of its own); the stretch is that draw alone, reading the game's texture (NX18-X2.0 bananza-alldata-analysis.md, ranked fix 2).
// The picture is softer: no edge-adaptive upscale and no sharpening from MetalFX (the present's Sharpening row applies again). Only the linear and square-rooted colour shapes (the squaring
// copy, COPY_T2T_SQUARE); sRGB-encoded input keeps MetalFX, which decodes it. The stretch reaches the game's image, not the present: the game draws its UI at the output size after the
// upscaler. Read once a frame: a preset picked in the in-game menu (GameMenu.swift gameMenuPresetEnv) sets the switch while the game runs
static uint64_t g_up_bil_n, g_up_bil_kept;   // dispatches drawn by the stretch; by MetalFX after all because the stretch could not draw them
static int up_bil_on(void) {
    static uint64_t f = UINT64_MAX; static int v = -1; uint64_t now = atomic_load(&g_cur_frame);
    if (now == f) return v;
    f = now; const char *e = getenv("DM_NVN_UP_BILINEAR"); int nv = e && *e ? strcmp(e, "0") != 0 : DM_GAME_UP_BILINEAR;
    if (nv != v) { if (v >= 0 || nv) MLOG("upscaler (DM_NVN_UP_BILINEAR=%s): %s", e && *e ? e : "unset", nv ? "the game's upscaler, where MetalFX would draw it, is a bilinear stretch (profile upscaler_bilinear; =0 turns it off)" : "MetalFX draws the game's upscaler"); v = nv; }
    return v;
}
static int up_mfx_on(void) {
    static int v = -1;
    if (v >= 0) return v;
