        if (ch + k < kh) [ce copyFromTexture:t sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0, ch - 1, 0) sourceSize:MTLSizeMake(cw, 1, 1) toTexture:t destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(0, ch + k, 0)];
        for (NSUInteger j = 0; j < FX_PAD; j++) if (cw + j < kw && ch + k < kh)
