    int srgb = cs->up_color == UP_COLOR_SRGB, root = cs->up_color == UP_COLOR_ROOT;
    if (!srgb && up_bil_on()) {   // the bilinear stretch (DM_NVN_UP_BILINEAR): one draw from the input rectangle into the output rectangle, squared on the way for square-rooted input
        if ((out.usage & MTLTextureUsageRenderTarget) && copy_t2t_draw(in, out, 0, 0, 0, 0, &ir, &orr, 1, root ? COPY_T2T_SQUARE : 0)) {
            if (!g_up_bil_n++) MLOG("upscaler: first dispatch of %s drawn as a bilinear stretch, %dx%d at %d,%d of %lux%lu (format %lu) → %dx%d at %d,%d of %lux%lu (format %lu)%s", cs->key, ir.width, ir.height, ir.xoffset, ir.yoffset,
                                    (unsigned long)in.width, (unsigned long)in.height, (unsigned long)in.pixelFormat, orr.width, orr.height, orr.xoffset, orr.yoffset, (unsigned long)out.width, (unsigned long)out.height,
                                    (unsigned long)out.pixelFormat, root ? ", squared from its square roots" : "");
            atomic_store_explicit(&g_up_mfx_drawn, 0, memory_order_relaxed);
            return 1;
        }
        if (!g_up_bil_kept++) MLOG("[RED] upscaler %s: the bilinear stretch cannot draw into the image (format %lu, usage %#lx); MetalFX draws it", cs->key, (unsigned long)out.pixelFormat, (unsigned long)out.usage);
    }
    // Each side is the game's own texture when MetalFX can take it as it is: the rectangle is the whole texture (MetalFX reads and writes from the origin) and the format is not sRGB (as the
    // copies, which keep its decode). The input in any format MetalFX takes, unless it is square-rooted: only the copy squares it (COPY_T2T_SQUARE). The output, private, only in the
    // scaler's own: MetalFX's own writes of R11G11B10F come out about two steps of its mantissa low (2.0 as 1.94, 0.5 as 0.484), where its RGBA16F output drawn back gives 1.98 and 0.496
    // (t_upscaler_mfx), so a packed output stays drawn back. sRGB input's output is always the scaler's own, for its decode. Else the scaler's own texture, through a copy
    MTLPixelFormat c16 = MTLPixelFormatRGBA16Float, of = srgb ? MTLPixelFormatRGBA8Unorm : MTLPixelFormatRGBA16Float;
    int whole_in = !root && !ir.xoffset && !ir.yoffset && (NSUInteger)ir.width == in.width && (NSUInteger)ir.height == in.height && pf_srgb_linear(in.pixelFormat) == MTLPixelFormatInvalid && !mtl_fmt_block(in.pixelFormat);
    int whole_out = !srgb && !orr.xoffset && !orr.yoffset && (NSUInteger)orr.width == out.width && (NSUInteger)orr.height == out.height && out.storageMode == MTLStorageModePrivate && out.pixelFormat == of;
    MTLPixelFormat cf = whole_in && (in.pixelFormat == c16 || up_mfx_direct_on()) ? in.pixelFormat : c16;
    up_mfx_scaler *e = NULL; int sin = 0, sout = 0, content = up_mfx_content_on();
    NSUInteger kw = (NSUInteger)ir.width, kh = (NSUInteger)ir.height;   // the scaler's input size: the rectangle's, or the output's when the input is a copy (DM_NVN_MFX_CONTENT)
    for (int t = 0; t < 2 && !e; t++) {   // the game's format first; one MetalFX refuses (no scaler made, or a usage the game's texture lacks) falls back to the scaler's own
        if (t && cf == c16) break;
        MTLPixelFormat c = t ? c16 : cf;
        kw = (NSUInteger)ir.width; kh = (NSUInteger)ir.height;
        if (content && !(whole_in && c == in.pixelFormat)) {   // a copy into the scaler's own input: one scaler for every input size; one MetalFX refuses falls back to the input's size
            if ((e = up_mfx_scaler_for((NSUInteger)orr.width, (NSUInteger)orr.height, (NSUInteger)orr.width, (NSUInteger)orr.height, srgb, c, of))) { kw = (NSUInteger)orr.width; kh = (NSUInteger)orr.height; }
        }
        if (!e && !(e = up_mfx_scaler_for((NSUInteger)ir.width, (NSUInteger)ir.height, (NSUInteger)orr.width, (NSUInteger)orr.height, srgb, c, of))) continue;
        sin = whole_in && c == in.pixelFormat && kw == (NSUInteger)ir.width && kh == (NSUInteger)ir.height && (in.usage & e->sc.colorTextureUsage) == e->sc.colorTextureUsage;
        sout = whole_out && (out.usage & e->sc.outputTextureUsage) == e->sc.outputTextureUsage;
        if (c != c16 && !sin) {
            static int once; if (!once++) MLOG("upscaler: MetalFX's colour usage %#lx is not the game's texture's (%#lx): the input goes through RGBA16F", (unsigned long)e->sc.colorTextureUsage, (unsigned long)in.usage);
            e = NULL;
        }
    }
    if (!e || (!sout && !(out.usage & MTLTextureUsageRenderTarget))) { g_up_mfx_kept++; return 0; }
    id<MTL4FXSpatialScaler> sc = e->sc;
    id<MTLTexture> color = sin ? in : up_mfx_scratch(e, 0), drawn = sout ? out : up_mfx_scratch(e, 1), result = sout ? out : e->out;
    if (!color || !drawn) { g_up_mfx_kept++; return 0; }
    rp_end(); if (g_blit) { enc_b_end(g_blit); g_blit = nil; }
    ubd_land_compute();
    // To the origin of the scaler's input (a nearest draw: same size). An input larger than the rectangle (DM_NVN_MFX_CONTENT) is drawn whole from the rectangle's origin: the copy
    // keeps no old content (DontCare), and where the game's texture ends with the rectangle its clamp repeats the edge past the content, which MetalFX reads (up_mfx_pad otherwise)
    NVNcopyRegion at0 = {0, 0, 0, (int)kw, (int)kh, 1}, at0o = {0, 0, 0, orr.width, orr.height, 1}, irk = {ir.xoffset, ir.yoffset, 0, (int)kw, (int)kh, 1};
    if (!sin && !copy_t2t_draw(in, color, 0, 0, 0, 0, &irk, &at0, 0, root ? COPY_T2T_SQUARE : 0)) { g_up_mfx_kept++; return 0; }
    mfx_order();   // as dlss_eval: the scaler after the frame's work so far
    NSUInteger cw = (NSUInteger)ir.width, ch = (NSUInteger)ir.height;
    int pad = !sin && (cw < kw || ch < kh) && ((NSUInteger)ir.xoffset + cw < in.width || (NSUInteger)ir.yoffset + ch < in.height);   // texels of the game's beyond the content: its edge again
    rec_cb_block(g_cb, ^(id<MTL4CommandBuffer> cb) {   // the real command buffer, on the encoding thread when it runs (iOS's default)
        if (pad) up_mfx_pad(cb, color, cw, ch, kw, kh);
        sc.colorTexture = color; sc.outputTexture = result; sc.inputContentWidth = cw; sc.inputContentHeight = ch;
        [sc encodeToCommandBuffer:cb];
    });
    atomic_store_explicit(&g_last_end_relaxed, 0, memory_order_relaxed);   // the next pass waits for the scaler whole (enc_r_begin_pass)
    if (!sout && !copy_t2t_draw(drawn, out, 0, 0, 0, 0, &at0o, &orr, 0, 0)) {
        args_dirty_all_w(AW_HOST_DRAW); g_up_mfx_kept++; return 0;   // only the scratch image was scaled; the game's shader can still produce the output
    }
    args_dirty_all_w(AW_HOST_DRAW);
    g_up_mfx_straight[0] += sin; g_up_mfx_straight[1] += sout;
    g_up_mfx_n++; atomic_store_explicit(&g_up_mfx_drawn, 1, memory_order_relaxed);
    if (g_up_mfx_n == 1) MLOG("upscaler: first dispatch of %s drawn by MetalFX, %dx%d at %d,%d of %lux%lu (format %lu, %s) → %dx%d at %d,%d of %lux%lu (format %lu, %s)%s", cs->key, ir.width, ir.height, ir.xoffset, ir.yoffset,
                            (unsigned long)in.width, (unsigned long)in.height, (unsigned long)in.pixelFormat, sin ? "straight" : "copied", orr.width, orr.height, orr.xoffset, orr.yoffset, (unsigned long)out.width,
                            (unsigned long)out.height, (unsigned long)out.pixelFormat, sout ? "straight" : "drawn back", srgb ? ", decoded from sRGB" : root ? ", squared from its square roots" : "");
    return 1;
}
// ---------- Sharpening in the present (DM_PRESENT_SHARPEN) ----------
// The settings row Sharpening (Off, Low, Medium, High; the profile's present_sharpen is a game's default, Off without it) sharpens the picture inside the present's own draw:
// present.metal fs_rcas is fs with FSR1's RCAS fused in, its taps one source texel apart. The drawable stays the picture's render size on the iPhone (front_ios.m), so the
// sharpening happens before Core Animation scales the layer, in every API and picture mode (Stretch and Ultrawide included, where MetalFX runs only for a crop smaller than
// its texture, fx_wanted), for no memory and one more pipeline. Off draws fs as before, byte for byte. A crop smaller than the drawable (Breath of the Wild's 1280x720
// handheld picture in its 1920x1080 window textures, a dynamic resolution's moving crop) is RCAS of the bilinear scale, a variant measured separately
// (docs/reference/rendering.md, Sharpening in the present).
// Not drawn over MetalFX's picture, which its perceptual mode sharpens already: RCAS on top overshot HUD text by 15-26/255 in the synthetic test. That is the present's
// MetalFX (fx_encode) and the game's upscaler drawn by MetalFX inside the frame (DM_UPSCALER=metalfx, up_mfx_encode), where the present sees a plain 1:1 picture. Nor over a
// source that is not a UNORM format: RCAS's limiter assumes values in 0..1, and a float swapchain can hold more. The drawable is BGRA8Unorm always (front_ios.m).
// The in-game menu's pick reaches the live present as Upscaling's does (nvn_upscale_pick.h): the main thread posts it, the present thread takes it at its next present
static _Atomic int g_sharp_mode = -1;   // the level in force (nvn_upscale_pick.h sharp_parse); -1 before the first present
static _Atomic int g_sharp_req = -1;    // the in-game menu's Sharpening (mtl_present_sharpen_set, main thread) until the live present takes it at its next present; -1 none
static _Atomic uint64_t g_present_crop_moves;   // presents whose crop differs from the live present's before in the same texture size (present_crop_note), for present_gpu_note
// The in-game menu's Sharpening while the game runs (front_ios.m dm_setting_live): the live present takes the new level at its next present. Both pipelines are made at the
// first present (present_pipeline), so a pick compiles nothing. Nothing the game sees changes, nor does the drawable
void mtl_present_sharpen_set(const char *level) {
    int v = sharp_parse(level);
    if (v < 0) { MLOG("[RED] present sharpening: %s from the in-game menu is not 0 to 3; ignored", level ? level : "(none)"); return; }
    up_post(&g_sharp_req, v);
}
// live: the live present's (0 for a capture, which never takes the menu's pick). The first present decides from DM_PRESENT_SHARPEN, else the profile's present_sharpen; then
// the level in force, until a pick
static int sharp_mode(int live) {
    int want = -1, v = up_now(&g_sharp_mode, &g_sharp_req, live, &want);
    if (v >= 0) return v;
    int was = atomic_load_explicit(&g_sharp_mode, memory_order_relaxed);
    if ((v = want) < 0) {   // a copy taken under the in-game menu's lock (front.h front_env_copy), as fx_mode's
        char e[64]; int set = front_env_copy("DM_PRESENT_SHARPEN", e, sizeof e) && *e;
        v = set ? sharp_parse(e) : DM_GAME_PRESENT_SHARPEN;
        if (v < 0) { MLOG("[RED] DM_PRESENT_SHARPEN=%s: 0 (off) to 3 (high); keeping the profile's %d", e, (int)DM_GAME_PRESENT_SHARPEN); v = DM_GAME_PRESENT_SHARPEN; }
    }
    static const char *const names[] = {"off", "low (RCAS 2 stops)", "medium (RCAS 1 stop)", "high (RCAS 0.5 stops)"};
    if (v != was) MLOG("present sharpening (%s): %s", want >= 0 ? "in-game menu" : "DM_PRESENT_SHARPEN, else the profile's present_sharpen", names[v & 3]);
    up_set(&g_sharp_mode, v);
    return v;
}
// The formats RCAS's limiter holds for: unsigned normalized colour, 0..1. An sRGB swapchain arrives here as its UNORM view (present_raw_src)
static int present_unorm(MTLPixelFormat pf) {
    switch (pf) {
    case MTLPixelFormatRGBA8Unorm: case MTLPixelFormatBGRA8Unorm: case MTLPixelFormatRGBA8Unorm_sRGB: case MTLPixelFormatBGRA8Unorm_sRGB:
    case MTLPixelFormatRGB10A2Unorm: case MTLPixelFormatBGR10A2Unorm: case MTLPixelFormatRGBA16Unorm: return 1;
    default: return 0;
    }
}
// RCAS's linear strength for this present (exp2(-stops)), or 0 to draw fs: off, or one of the cases above, each said once in the log
// (front.h DM_SHARP_*: the live present keeps the reason for the in-game menu, g_sharp_why)
static float present_sharpen(int live, int metalfx, MTLPixelFormat pf) {
    int level = sharp_mode(live);
    static _Atomic int said;
    int why = !level ? 0 : metalfx ? DM_SHARP_METALFX : atomic_load_explicit(&g_up_mfx_drawn, memory_order_relaxed) ? DM_SHARP_GAME_UPSCALER : !present_unorm(pf) ? DM_SHARP_FORMAT : !g_rcas_pso ? DM_SHARP_PIPELINE : 0;
    if (live) atomic_store_explicit(&g_sharp_why, why, memory_order_relaxed);
    if (!level) return 0;
    if (!why) return exp2f(-sharp_stops(level));
    if (!(atomic_fetch_or_explicit(&said, why, memory_order_relaxed) & why))
        MLOG("present sharpening: not drawn on %s", why == DM_SHARP_METALFX ? "a picture MetalFX scaled (Upscaling MetalFX), which its perceptual mode sharpens already" :
             why == DM_SHARP_GAME_UPSCALER ? "the game's upscaler drawn by MetalFX (DM_UPSCALER=metalfx), which its perceptual mode sharpens already" :
             why == DM_SHARP_FORMAT ? "a swapchain that is not a UNORM format: RCAS's limiter assumes values in 0..1" : "this drawable: its pipeline was not made");
    return 0;
}
// ---------- Edge smoothing in the present (DM_POST_AA) ----------
// Intel's CMAA2 (dm/gfx/msl/cmaa2.metal) on the game's picture, for every game: no game has a hook before its HUD yet, so the HUD and text are smoothed with the scene (a 1-2 pixel
// stroke changed by 3.0/255 on average in the study's synthetic test, Extra Sharp about half that), which is why no profile turns it on. It runs at the game's resolution,
// before MetalFX or the bilinear scale and before Sharpening, on the present's own command buffer: the crop is copied to the origin of aa->tex, the five dispatches run in
// one encoder, and the present's draw (or MetalFX, which takes aa->tex as its input instead of making its own copy) reads the result. The drawable stays framebufferOnly.
// The present's command buffer runs on the game's queue after the frame's work, so its GPU time adds to a GPU-bound frame's (present_gpu_note gives it apart).
// - aa->tex is the window texture's size, so a dynamic resolution's crop moves inside it with no new allocation; the kernels take the crop's size from the constants (AA_UV).
// - An sRGB swapchain is smoothed in linear light: aa->tex is the _sRGB format, read decoded, and written through its UNORM view (aa->raw) with the encode in the shader.
//   An RGBA8 swapchain (Super Mario Odyssey's) is smoothed as stored. Other formats (10-bit, float) are shown without it, said once.
// - The working buffers are sized so no list can overflow on a real picture: shape candidates w*h/2 (a candidate needs two edges at a corner: a one-pixel checkerboard is the
//   worst case and reaches w*h), blend locations one per 2x2 quad (the most there can be). Every append is clamped all the same (cmaa2.metal), and a run that ran past one is said once (aa_note).
// - Deferred blend items (8 bytes each) start at a quarter of the pixels (aa_items_frac), not one per pixel: the bench's dense foliage at 1080p wants 237,056 of them, 11 % of
//   the pixels, and the typical picture 34,845, so a quarter holds them with room, and saves 11.9 MB at 1080p (15.8 MB for one per pixel). A run whose blend items ran past
//   the list (cmaa2.metal's overflow bit 2, aa_note) makes the list one per pixel from the next present on, for every size, and says so once (g_aa_items_full): until then that
//   run smooths fewer edges, as any clamp does. DM_PRESENT_AA_ITEMS=<fraction> (0 to 1) sets the start; =1 is one per pixel, as before
// The setting follows Sharpening's rule (nvn_upscale_pick.h): the first present reads DM_POST_AA, else the profile's post_aa; the in-game menu's pick is taken by the live present
// at its next present; a capture (present_offscreen_m4) has state of its own and reads the mode in force. DM_POST_AA=ab alternates off and edge with the DM_AB phases
#define AA_UV 12   // the present's constants buffer (uvb) from this float on: cmaa2.metal's Aa, 10 words
enum { AA_CTL_RAW_CAND = 13, AA_CTL_RAW_ITEM = 14, AA_CTL_RAW_LOC = 15, AA_CTL_OVERFLOW = 16, AA_CTL_RAW_INPLACE = 18, AA_CTL_ARGS1 = 20, AA_CTL_ARGS2 = 24, AA_CTL_WORDS = 32 };   // cmaa2.metal's CTL_*
// tex: the picture's copy, smoothed in place (the swapchain's format, _sRGB for an sRGB one); raw: its UNORM view (tex itself for a UNORM swapchain), what the present and MetalFX
// read; ctl: the control buffer (shared, so the host reads its counts); work: candidates, locations, items, list heads and edges at off[0..4]; cap: candidates, items, locations
typedef struct { id<MTLTexture> tex, raw; id<MTLBuffer> ctl, work; id<MTL4ArgumentTable> at; NSUInteger w, h, off[5], refused[3]; MTLPixelFormat pf; uint32_t cap[3]; int items_full; } aa_state;   // items_full: made with one blend item per pixel
static aa_state g_aa_present;   // the live present's: only the present thread encodes with it or replaces it
static _Atomic int g_aa_mode = -1;   // the mode in force (nvn_upscale_pick.h AA_*; AA_AB alternates); -1 before the first present
static _Atomic int g_aa_req = -1;    // the in-game menu's pick (mtl_present_aa_set, main thread) until the live present takes it at its next present; -1 none
static _Atomic int g_aa_ab;          // DM_POST_AA=ab's switch mode (sw_mode_of)
static uint32_t g_aa_test_cap[3];    // the tests: the candidates', blend items' and locations' capacities at most these (0 = as sized above), to run the overflow clamps
static uint32_t g_aa_test_slm;       // the tests: the threadgroup store of Z shapes' blend items at most this many (0 = cmaa2.metal's 768), to run its fallback
static uint32_t g_aa_test_stray;     // the tests: 1 fills that store with a stray item first, which shows if a slot nothing wrote is read (cmaa2.metal Aa.stray)
static _Atomic uint32_t g_aa_seen[5];   // the last completed run's candidates, blend items and locations before the clamps, the overflow bits, the Z shapes blended in place (aa_note; the tests)
static _Atomic double g_aa_items_frac = -1;    // the blend items' list as a share of the pixels (DM_PRESENT_AA_ITEMS, default AA_ITEMS_FRAC; the tests set it); -1 not read yet
static _Atomic int g_aa_items_full;    // a run's blend items ran past their list: one per pixel from then on (aa_note)
static _Atomic unsigned g_aa_items_reads;   // the times DM_PRESENT_AA_ITEMS was read (once in a run; the tests)
static void (*g_aa_items_hook)(void);   // the tests: called inside the read, before the share is stored, to hold a first reader while a second one asks
#define AA_ITEMS_FRAC 0.25
// The share is asked for by aa_make on the present thread and by aa_note in a present's completion handler on a Metal thread, so the switch is read once under dispatch_once and the
// share kept in an atomic: two first callers no longer both read it (and both said the [RED] line for a bad value), and a test's store of its own share is seen by both threads
static double aa_items_frac(void) {
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        atomic_fetch_add(&g_aa_items_reads, 1);
        const char *e = getenv("DM_PRESENT_AA_ITEMS"); double v = e && *e ? strtod(e, NULL) : AA_ITEMS_FRAC;
        if (!(v > 0 && v <= 1)) { MLOG("[RED] DM_PRESENT_AA_ITEMS=%s: a fraction of the pixels above 0 and at most 1; keeping %.2f", e, AA_ITEMS_FRAC); v = AA_ITEMS_FRAC; }
        if (g_aa_items_hook) g_aa_items_hook();
        double unread = -1; atomic_compare_exchange_strong(&g_aa_items_frac, &unread, v);   // a share a test stored first stays
    });
    return atomic_load_explicit(&g_aa_items_frac, memory_order_relaxed);
}
static id<MTLComputePipelineState> g_aa_ps[7];   // edges (Extra Sharp off, on), args, process (Extra Sharp off, on), apply (CONVERT off, on); written once, before g_aa_ps_state is 2
static _Atomic int g_aa_ps_state;   // the pipelines: 0 not asked for, 1 being made (aa_pipelines_start), 2 made, -1 cannot be made
static pthread_mutex_t g_aa_ps_mu = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t g_aa_ps_cv = PTHREAD_COND_INITIALIZER;   // a capture waiting for them (aa_pipelines)
// The seven pipelines, outside the pipeline archive like the present's own; said once either way. Runs on a background queue (aa_pipelines_start)
static void aa_pipelines_make(void) {
    static const struct { const char *fn; bool sharp, convert; NSUInteger threads; } P[7] = {
        {"cmaa2_edges", 0, 0, 256}, {"cmaa2_edges", 1, 0, 256}, {"cmaa2_args", 0, 0, 1}, {"cmaa2_process", 0, 0, 128}, {"cmaa2_process", 1, 0, 128},
        {"cmaa2_apply", 0, 0, 128}, {"cmaa2_apply", 0, 1, 128}};
    uint64_t t0 = now_ns(); NSError *e = nil; const char *why = NULL;
    id<MTLLibrary> lib = host_lib("cmaa2", &e);
    if (!lib) why = "no library";
    for (int i = 0; i < 7 && !why; i++) {
        MTLFunctionConstantValues *cv = [MTLFunctionConstantValues new]; bool c = P[i].convert, sh = P[i].sharp;
        [cv setConstantValue:&c type:MTLDataTypeBool atIndex:0]; [cv setConstantValue:&sh type:MTLDataTypeBool atIndex:1];
        g_aa_ps[i] = host_cps(lib, @(P[i].fn), cv, &e);   // the constants specialize it in the Metal 4 compiler (MTL4SpecializedFunctionDescriptor)
        if (!g_aa_ps[i]) why = P[i].fn;
        else if (g_aa_ps[i].maxTotalThreadsPerThreadgroup < P[i].threads) { why = P[i].fn; e = nil; }   // the threadgroup size the kernel's threadgroup memory is laid out for
    }
    if (why) MLOG("[RED] present edge smoothing: CMAA2's %s cannot be made (%s); the picture is shown without edge smoothing", why, e ? e.localizedDescription.UTF8String : "too few threads per threadgroup");
    else MLOG("present edge smoothing: CMAA2's 7 compute pipelines made in %.1f ms, in the background", (now_ns() - t0) / 1e6);
    pthread_mutex_lock(&g_aa_ps_mu);
    atomic_store_explicit(&g_aa_ps_state, why ? -1 : 2, memory_order_release);   // after g_aa_ps: whoever reads 2 sees the pipelines
    pthread_cond_broadcast(&g_aa_ps_cv); pthread_mutex_unlock(&g_aa_ps_mu);
}
// Starts making the pipelines on a background queue the first time anything asks for them: the in-game menu's pick, or a present that smooths. Compiling seven specialised
// kernels takes long enough to show as a hitch if the present thread did it while holding a drawable, which is what the live pick would do otherwise. Returns 1 if this call
// started it
static int aa_pipelines_start(void) {
    int none = 0;
    if (!atomic_compare_exchange_strong(&g_aa_ps_state, &none, 1)) return 0;
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{ @autoreleasepool { aa_pipelines_make(); } });
    return 1;
}
// Whether the pipelines are made. wait: a capture (screenshots and DM_NVN_SHOT_OUT, which wait for the GPU anyway) and the bench wait for them; the live present does not, and
// shows the picture without edge smoothing until they are made, a few presents after the first that asked
static int aa_pipelines(int wait) {
    if (aa_pipelines_start() && !wait) return 0;
    int st = atomic_load_explicit(&g_aa_ps_state, memory_order_acquire);
    if (st == 1 && wait) {
        pthread_mutex_lock(&g_aa_ps_mu);
        while ((st = atomic_load_explicit(&g_aa_ps_state, memory_order_acquire)) == 1) pthread_cond_wait(&g_aa_ps_cv, &g_aa_ps_mu);
        pthread_mutex_unlock(&g_aa_ps_mu);
    }
    return st == 2;
}
// The in-game menu's anti-aliasing while the game runs (front_ios.m dm_setting_live): taken by the live present at its next present. A pick that turns it on starts making the
// kernels in the background (aa_pipelines_start), and the present smooths once they are made; its buffers are made at the first present that smooths. The kernels are kept when it
// is turned off, so turning it on again compiles nothing; the buffers are released once it has been off for FX_IDLE_PRESENTS presents (present_fx_idle; DM_PRESENT_FX_KEEP=1 keeps
// them) and made again at the next present that smooths. Nothing the game sees changes, nor does the drawable
void mtl_present_aa_set(const char *mode) {
    int v = aa_parse(mode);
    if (v < 0 || v == AA_AB) { MLOG("[RED] present edge smoothing: %s from the in-game menu is not off, edge or edge-sharp; ignored", mode ? mode : "(none)"); return; }
    if (v != AA_OFF) aa_pipelines_start();
    up_post(&g_aa_req, v);
}
// The mode for this present: AA_OFF, AA_EDGE or AA_EDGE_SHARP (ab resolved for the phase this present runs in). live: as sharp_mode's
static int aa_mode(int live) {
    int want = -1, v = up_now(&g_aa_mode, &g_aa_req, live, &want);
    if (v < 0) {
        int was = atomic_load_explicit(&g_aa_mode, memory_order_relaxed);
        if ((v = want) < 0) {   // a copy taken under the in-game menu's lock (front.h front_env_copy), as fx_mode's
            char e[64]; int set = front_env_copy("DM_POST_AA", e, sizeof e) && *e;
            v = aa_parse(set ? e : DM_GAME_POST_AA);
            if (v < 0) { MLOG("[RED] DM_POST_AA=%s: off, edge, edge-sharp or ab; keeping the profile's %s", e, DM_GAME_POST_AA); v = aa_parse(DM_GAME_POST_AA); }
            if (v == AA_AB) { int m = sw_mode_of("DM_POST_AA", e, 0); atomic_store_explicit(&g_aa_ab, m, memory_order_relaxed); if (!m) v = AA_OFF; }
        }
        static const char *const names[] = {"off", "edge (CMAA2)", "edge-sharp (CMAA2, Extra Sharp)", "ab (off and edge in turn with the DM_AB phases)"};
        if (v != was) MLOG("present edge smoothing (%s): %s", want >= 0 ? "in-game menu" : "DM_POST_AA, else the profile's post_aa", names[v & 3]);
        up_set(&g_aa_mode, v);
    }
    return v == AA_AB ? (sw_on(atomic_load_explicit(&g_aa_ab, memory_order_relaxed)) ? AA_EDGE : AA_OFF) : v;
}
static void aa_free(aa_state *aa) {
    res_remove(aa->tex); res_remove(aa->work); res_remove(aa->ctl);
    aa->tex = aa->raw = nil; aa->ctl = aa->work = nil; aa->at = nil; aa->w = aa->h = 0;
}
// Makes aa's texture (tw x th, format tpf, its view upf) and working buffers. live: the present thread's, whose presents on the GPU may still use the old ones: it waits for them
// when there are old ones to replace (a new window texture size or format), and not the first time, when no present has used any
static int aa_make(aa_state *aa, NSUInteger tw, NSUInteger th, MTLPixelFormat tpf, MTLPixelFormat upf, int live) {
    NSUInteger key[3] = {tw, th, tpf};
    if (!memcmp(key, aa->refused, sizeof key)) return 0;
    if (live && aa->tex) { pthread_mutex_lock(&g_pq_mu); while (g_pq_inflight && !gpu_gone()) pthread_cond_wait(&g_pq_cv, &g_pq_mu); pthread_mutex_unlock(&g_pq_mu); }
    aa_free(aa);
    NSUInteger stride = (tw + 1) / 2, qh = (th + 1) / 2;
    int full = atomic_load(&g_aa_items_full) || aa_items_frac() >= 1; uint64_t items = full ? (uint64_t)tw * th : (uint64_t)((double)tw * th * aa_items_frac());
    uint64_t cap[3] = {(uint64_t)tw * th / 2, MAX(items, 1), (uint64_t)stride * qh};
    for (int i = 0; i < 3; i++) if (g_aa_test_cap[i] && cap[i] > g_aa_test_cap[i]) cap[i] = g_aa_test_cap[i];
    uint64_t size[5] = {cap[0] * 4, cap[2] * 4, cap[1] * 8, (uint64_t)stride * qh * 4, (uint64_t)stride * th}, total = 0;   // candidates, locations, items, list heads, edges
    for (int i = 0; i < 5; i++) { aa->off[i] = total; total += (size[i] + 255) & ~255ull; }
    MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:tpf width:tw height:th mipmapped:NO];
    td.storageMode = MTLStorageModePrivate; td.usage = MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite | MTLTextureUsagePixelFormatView;
    aa->tex = [g_dev newTextureWithDescriptor:td];
    aa->raw = tpf == upf ? aa->tex : [aa->tex newTextureViewWithPixelFormat:upf];
    aa->work = [g_dev newBufferWithLength:total options:MTLResourceStorageModePrivate];
    aa->ctl = [g_dev newBufferWithLength:AA_CTL_WORDS * 4 options:MTLResourceStorageModeShared];
    MTL4ArgumentTableDescriptor *ad = [MTL4ArgumentTableDescriptor new]; ad.maxBufferBindCount = 7; ad.maxTextureBindCount = 2; NSError *e = nil;
    aa->at = [g_dev newArgumentTableWithDescriptor:ad error:&e];
    if (!aa->tex || !aa->raw || !aa->work || !aa->ctl || !aa->at) {
        memcpy(aa->refused, key, sizeof key); aa_free(aa);
        MLOG("[RED] present edge smoothing: cannot make CMAA2's texture and buffers for %lux%lu (%.1f MB); this size is shown without it", (unsigned long)tw, (unsigned long)th, (total + tw * th * 4) / 1048576.0);
        return 0;
    }
    memset(aa->ctl.contents, 0, AA_CTL_WORDS * 4);   // the counters start at 0; cmaa2_args clears them after each run
    aa->tex.label = @"present edge smoothing"; aa->work.label = @"present edge smoothing: CMAA2 lists"; aa->ctl.label = @"present edge smoothing: CMAA2 control";
    res_add(aa->tex); res_add(aa->work); res_add(aa->ctl); res_commit();
    aa->w = tw; aa->h = th; aa->pf = tpf; aa->items_full = full; for (int i = 0; i < 3; i++) aa->cap[i] = (uint32_t)cap[i];
    if (live) MLOG("present edge smoothing: CMAA2 for window textures of %lux%lu, %.1f MB (%s; blend items for %.0f %% of the pixels)", (unsigned long)tw, (unsigned long)th, (total + aa->tex.allocatedSize) / 1048576.0,
                   tpf != upf ? "an sRGB swapchain: smoothed in linear light" : "smoothed as the swapchain stores it", 100.0 * cap[1] / ((double)tw * th));
    return 1;
}
static int aa_srgb(MTLPixelFormat pf) { return pf == MTLPixelFormatRGBA8Unorm_sRGB || pf == MTLPixelFormatBGRA8Unorm_sRGB; }
// The live present's edge smoothing outcome for the in-game menu (front.h DM_AA_*, g_aa_why); a capture's says nothing
static void aa_outcome(int live, int why) { if (live) atomic_store_explicit(&g_aa_why, why, memory_order_relaxed); }
// Encodes edge smoothing of the rectangle r of raw (present_raw_src's view of src) into cb; returns aa->raw, which holds the smoothed crop at its origin, or nil (none this
// present: off, an unsupported format, no pipelines or memory). uvb: the present's constants buffer, whose AA_UV floats take the kernels' constants
static id<MTLTexture> aa_encode(aa_state *aa, id<MTL4CommandBuffer> cb, id<MTLTexture> src, id<MTLTexture> raw, const NSUInteger r[4], id<MTLBuffer> uvb, int live) {
    int mode = aa_mode(live);
    if (!mode) { aa_outcome(live, DM_AA_OFF); return nil; }
    MTLPixelFormat upf = raw.pixelFormat;
    if (upf != MTLPixelFormatRGBA8Unorm && upf != MTLPixelFormatBGRA8Unorm) {
        aa_outcome(live, DM_AA_FORMAT);
        RED_ONCE(165, "present edge smoothing: the swapchain's format %lu is not 8-bit RGBA or BGRA (CMAA2 here handles those only); the picture is shown without it", (unsigned long)src.pixelFormat);
        return nil;
    }
    if (!aa_pipelines(!live)) {   // still being made (the live present does not wait for them) says nothing yet; kernels that failed, that it never runs here
        int st = atomic_load_explicit(&g_aa_ps_state, memory_order_relaxed);
        aa_outcome(live, st == 1 || st == 2 ? DM_AA_OFF : DM_AA_FAILED); return nil;
    }
    // An sRGB swapchain: the live present passes the swapchain texture, a capture its UNORM view (present_offscreen_m4), whose parent is the swapchain texture
    int srgb = aa_srgb(src.pixelFormat) || (src.parentTexture && aa_srgb(src.parentTexture.pixelFormat));
    MTLPixelFormat tpf = !srgb ? upf : upf == MTLPixelFormatRGBA8Unorm ? MTLPixelFormatRGBA8Unorm_sRGB : MTLPixelFormatBGRA8Unorm_sRGB;
    if ((!aa->tex || aa->w != raw.width || aa->h != raw.height || aa->pf != tpf || (!aa->items_full && atomic_load(&g_aa_items_full))) && !aa_make(aa, raw.width, raw.height, tpf, upf, live)) { aa_outcome(live, DM_AA_FAILED); return nil; }   // a blend items list that ran full: made again at one per pixel
    NSUInteger cx = r[0], cy = r[1], cw = r[2], ch = r[3], px = MIN((NSUInteger)FX_PAD, aa->w - cw), py = MIN((NSUInteger)FX_PAD, aa->h - ch);
    uint32_t *k = (uint32_t *)((float *)uvb.contents + AA_UV);   // cmaa2.metal Aa
    k[0] = (uint32_t)cw; k[1] = (uint32_t)ch; k[2] = (uint32_t)(cw + 1) / 2; k[3] = aa->cap[0]; k[4] = aa->cap[1]; k[5] = aa->cap[2]; k[6] = (uint32_t)px; k[7] = (uint32_t)py;
    k[8] = g_aa_test_slm ? g_aa_test_slm : 768; k[9] = g_aa_test_stray;   // cmaa2.metal takes at most its CMAA2_BLEND_ITEM_SLM_SIZE
    id<MTL4ComputeCommandEncoder> ce = [cb computeCommandEncoder];
    if (!ce) { aa_outcome(live, DM_AA_FAILED); RED_ONCE(166, "present edge smoothing: no compute encoder; the picture is shown without it"); return nil; }
    [ce barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageBlit visibilityOptions:resource_vis()];   // after the frame's work, and the presents before (aa's texture and lists)
    [ce copyFromTexture:raw sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(cx, cy, 0) sourceSize:MTLSizeMake(cw, ch, 1) toTexture:aa->raw destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(0, 0, 0)];
    // The crop's edge FX_PAD texels past it, for MetalFX (fx_encode's padding, here because the scaler reads this texture); cmaa2_apply writes a smoothed edge pixel there too
    for (NSUInteger j = 0; j < px; j++) [ce copyFromTexture:raw sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(cx + cw - 1, cy, 0) sourceSize:MTLSizeMake(1, ch, 1) toTexture:aa->raw destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(cw + j, 0, 0)];
    for (NSUInteger i = 0; i < py; i++) [ce copyFromTexture:raw sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(cx, cy + ch - 1, 0) sourceSize:MTLSizeMake(cw, 1, 1) toTexture:aa->raw destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(0, ch + i, 0)];
    if (px && py) [ce copyFromTexture:raw sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(cx + cw - 1, cy + ch - 1, 0) sourceSize:MTLSizeMake(1, 1, 1) toTexture:aa->raw destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(cw, ch, 0)];
    for (NSUInteger j = 0; j < px; j++) for (NSUInteger i = 0; i < py; i++) if (i || j)
        [ce copyFromTexture:raw sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(cx + cw - 1, cy + ch - 1, 0) sourceSize:MTLSizeMake(1, 1, 1) toTexture:aa->raw destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(cw + j, ch + i, 0)];
    [ce barrierAfterEncoderStages:MTLStageBlit beforeEncoderStages:MTLStageDispatch visibilityOptions:MTL4VisibilityOptionDevice];
    id<MTL4ArgumentTable> at = aa->at; uint64_t w = aa->work.gpuAddress, c = aa->ctl.gpuAddress;
    [ce setArgumentTable:at];
    [at setTexture:aa->tex.gpuResourceID atIndex:0]; [at setTexture:aa->raw.gpuResourceID atIndex:1];
    [at setAddress:uvb.gpuAddress + AA_UV * sizeof(float) atIndex:0]; [at setAddress:c atIndex:1];
    [at setAddress:w + aa->off[0] atIndex:2]; [at setAddress:w + aa->off[1] atIndex:3]; [at setAddress:w + aa->off[2] atIndex:4]; [at setAddress:w + aa->off[3] atIndex:5]; [at setAddress:w + aa->off[4] atIndex:6];
    int sharp = mode == AA_EDGE_SHARP;
    [ce setComputePipelineState:g_aa_ps[sharp]];   // each thread a 2x2 quad, 14x14 of each 16x16 threadgroup's quads its own
    [ce dispatchThreadgroups:MTLSizeMake((cw + 27) / 28, (ch + 27) / 28, 1) threadsPerThreadgroup:MTLSizeMake(16, 16, 1)];
    [ce barrierAfterEncoderStages:MTLStageDispatch beforeEncoderStages:MTLStageDispatch visibilityOptions:MTL4VisibilityOptionDevice];
    [ce setComputePipelineState:g_aa_ps[2]];
    [ce dispatchThreadgroups:MTLSizeMake(2, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    [ce barrierAfterEncoderStages:MTLStageDispatch beforeEncoderStages:MTLStageDispatch visibilityOptions:MTL4VisibilityOptionDevice];
    [ce setComputePipelineState:g_aa_ps[3 + sharp]];
    [ce dispatchThreadgroupsWithIndirectBuffer:c + AA_CTL_ARGS1 * 4 threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
    [ce barrierAfterEncoderStages:MTLStageDispatch beforeEncoderStages:MTLStageDispatch visibilityOptions:MTL4VisibilityOptionDevice];
    [ce setComputePipelineState:g_aa_ps[2]];
    [ce dispatchThreadgroups:MTLSizeMake(1, 2, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    [ce barrierAfterEncoderStages:MTLStageDispatch beforeEncoderStages:MTLStageDispatch visibilityOptions:MTL4VisibilityOptionDevice];
    [ce setComputePipelineState:g_aa_ps[5 + srgb]];
    [ce dispatchThreadgroupsWithIndirectBuffer:c + AA_CTL_ARGS2 * 4 threadsPerThreadgroup:MTLSizeMake(4, 32, 1)];
    [ce barrierAfterStages:MTLStageDispatch beforeQueueStages:MTLStageAll visibilityOptions:MTL4VisibilityOptionDevice];   // the present's draw or MetalFX reads aa->raw
    [ce endEncoding];
    aa_outcome(live, DM_AA_RAN);
    return aa->raw;
}
// A completed run's counts (ctl: the run's control buffer, from its present's completion): kept for the tests, and an overflow said once
static void aa_note(id<MTLBuffer> ctl) {
    const uint32_t *c = ctl.contents;
    for (int i = 0; i < 3; i++) atomic_store_explicit(&g_aa_seen[i], c[AA_CTL_RAW_CAND + i], memory_order_relaxed);
    atomic_store_explicit(&g_aa_seen[3], c[AA_CTL_OVERFLOW], memory_order_relaxed);
    atomic_store_explicit(&g_aa_seen[4], c[AA_CTL_RAW_INPLACE], memory_order_relaxed);
    if ((c[AA_CTL_OVERFLOW] & 2) && !atomic_exchange(&g_aa_items_full, 1) && aa_items_frac() < 1)
        MLOG("present edge smoothing: CMAA2's blend items ran past their list (%u wanted): one per pixel from the next present on", c[AA_CTL_RAW_ITEM]);
    if (c[AA_CTL_OVERFLOW])
        RED_ONCE(167, "present edge smoothing: CMAA2's lists ran full (bits %#x: 1 shape candidates, 2 blend items, 4 locations; this run %u candidates, %u items, %u locations): what did not fit was left unsmoothed",
                 c[AA_CTL_OVERFLOW], c[AA_CTL_RAW_CAND], c[AA_CTL_RAW_ITEM], c[AA_CTL_RAW_LOC]);
}
// A crop that moved since the live present before, in a texture of the same size: a game's dynamic resolution. Counted for present_gpu_note's line (present thread).
// Its size too, logging only (nvn_crop_area.h): every NVN_CROP_AREA_PRESENTS live presents, once a present this session has shown less than its whole window texture or the crop has
// moved, a line with the crop's mean, smallest and largest share of the window texture and their pixels, the thermal state and the time since launch, so a heat A/B shows how far a
// game's dynamic resolution went at each thermal state (Mario Kart World). The present thread only hands the interval over (g_crop_line, when the line before has gone out); the
// present's commit feedback handler writes the line (present_crop_line), so no log write, with its stderr lock, sits between waitForDrawable and the commit
int dm_thermal_now(void);   // hle_nvn.c's weak default (-1, the Mac), the iOS front end's NSProcessInfo thermal state
static nvn_crop_area g_crop_line; static uint64_t g_crop_line_moved, g_crop_line_total;
static _Atomic int g_crop_line_state;   // 0: g_crop_line free for the present thread; 1: an interval handed over; 2: the feedback handler is writing its line
static void present_crop_note(id<MTLTexture> src, const NSUInteger r[4]) {
    static NSUInteger last[6]; NSUInteger now[6] = {src.width, src.height, r[0], r[1], r[2], r[3]};
    if (last[0] && last[0] == now[0] && last[1] == now[1] && memcmp(last + 2, now + 2, sizeof now - 2 * sizeof *now)) atomic_fetch_add_explicit(&g_present_crop_moves, 1, memory_order_relaxed);
    memcpy(last, now, sizeof now);
    static nvn_crop_area area; static uint64_t moves_before;
    nvn_crop_area_add(&area, now[0], now[1], now[4], now[5]);
    if (area.n < NVN_CROP_AREA_PRESENTS) return;
    uint64_t moves = atomic_load_explicit(&g_present_crop_moves, memory_order_relaxed);
    if (!atomic_load_explicit(&g_crop_line_state, memory_order_acquire)) {   // else the line before has not gone out (no present completed in 300): this interval is dropped
        g_crop_line = area; g_crop_line_moved = moves - moves_before; g_crop_line_total = moves;
        atomic_store_explicit(&g_crop_line_state, 1, memory_order_release);
    }
    nvn_crop_area_next(&area); moves_before = moves;
}
static void present_crop_line(void) {   // the live present's commit feedback handler: the interval present_crop_note handed over, as its line
    int one = 1;
    if (!atomic_compare_exchange_strong_explicit(&g_crop_line_state, &one, 2, memory_order_acquire, memory_order_relaxed)) return;
    char line[448];
    if (nvn_crop_area_text(line, sizeof line, &g_crop_line, g_crop_line_moved, g_crop_line_total, dm_thermal_now(), (now_ns() - g_t0_ns) / 1e9)) {
        // The host's render scale now, once the heat ladder or the clock rescue has changed it (hle_nvn.c scale_set, mtl_render_scale_note): an A/B reads the crop against it,
        // and against the GPU time's stretch in the Mario Kart World family
        uint64_t vb = atomic_load_explicit(&g_scale_noted, memory_order_relaxed); double v = 0, k = gpu_stretch_k(); if (vb) memcpy(&v, &vb, sizeof v);
        size_t n = strlen(line);
        if (v > 0 && k > 0 && k != 1 && n < sizeof line) snprintf(line + n, sizeof line - n, "; render scale %.2f, the GPU time read ×%.2f", v, k);
        else if (v > 0 && n < sizeof line) snprintf(line + n, sizeof line - n, "; render scale %.2f", v);
        MLOG("%s", line);
    }
    atomic_store_explicit(&g_crop_line_state, 0, memory_order_release);
}
// ---------- The touch controls drawn into the frame (iOS; dm/host/touch_draw.h) ----------
// While the iPhone's or iPad's touch controls show, the front end keeps their layers hidden and the live present draws them over the picture, in its own render pass (touch_draw):
// with nothing visible over the game's CAMetalLayer iOS can show its drawables without compositing them, a refresh sooner (docs/reference/frame-rate.md, "Touch controls over
// the game's layer cost a refresh of latency"). The front end hands over a picture of every control (the atlas, mtl_present_touch_atlas, when the controls' look or place changes)
// and, at each touch, where each goes and which look it has (a touch_frame, mtl_present_touch); with a frame the front end also places the picture on a canvas larger than it (the
// whole screen with Fit's bars or a portrait split's controls), which present_viewport's centred fit would not. Only the live present draws them: screenshots and captures show the
// game's picture alone, as before. The Mac's front end hands over nothing, and nothing changes there
static touch_box g_touch_box;   // the front end's latest frame: the main thread writes it, the present thread reads it
uint32_t mtl_present_touch(const touch_frame *f) { return touch_publish(&g_touch_box, f); }
static pthread_mutex_t g_touch_mu = PTHREAD_MUTEX_INITIALIZER;
// Under g_touch_mu: the atlas the front end made last, until the present thread takes it (touch_adopt); g_touch_drop: the front end let the atlas go (mtl_present_touch_release)
static id<MTLTexture> g_touch_next; static uint32_t g_touch_next_gen; static int g_touch_drop;
static _Atomic uint32_t g_touch_ack;   // the frame sequence from which a drawn present is reported to the front end (mtl_present_touch_ack), 0: none wanted
static _Atomic uint64_t g_touch_live_ns;   // the last live present (touch_frame_now): mtl_present_touch_idle_ns
void mtl_present_touch_ack(uint32_t seq) { atomic_store_explicit(&g_touch_ack, seq, memory_order_release); }
void mtl_present_touch_release(void) { pthread_mutex_lock(&g_touch_mu); g_touch_next = nil; g_touch_drop = 1; pthread_mutex_unlock(&g_touch_mu); }
uint64_t mtl_present_touch_idle_ns(void) { uint64_t t = atomic_load_explicit(&g_touch_live_ns, memory_order_relaxed), n = now_ns(); return t ? (n > t ? n - t : 0) : UINT64_MAX; }
// The present thread's: the atlas in use and its generation, those it replaced until the GPU is done with them, the live presents encoded and the newest one completed (present_now's
// feedback: one present completing means every one before it has, as each present's pass waits for all the queue's earlier work), the last frame read, the pipeline and its table
static id<MTLTexture> g_touch_tex; static uint32_t g_touch_gen;
static struct { __strong id<MTLTexture> tex; uint64_t after; } g_touch_old[4];
static uint64_t g_touch_seq; static _Atomic uint64_t g_touch_done;
static touch_frame g_touch_last; static uint32_t g_touch_last_seq, g_touch_dead, g_touch_unfit;   // the last frame read and its sequence; touch_frame_places's and touch_unfit_step's
static uint32_t g_touch_drew;   // the frame sequence the live present being encoded drew the controls from (touch_draw), 0: none; present_now hands it to its completion
static id<MTLRenderPipelineState> g_touch_pso[2]; static MTLPixelFormat g_touch_fmt; static id<MTL4ArgumentTable> g_touch_args; static int g_touch_failed;   // [1]: a grey and alpha atlas (fs_touch_grey)
static _Atomic int g_touch_said;   // the first present that drew the controls says so
__attribute__((weak)) void front_touch_draw_failed(void) {}   // front_ios.m: the controls go back to their layers; the Mac and the graphics unit tests have none
__attribute__((weak)) void front_touch_drawn(uint32_t seq) { (void)seq; }   // DmGamepad.m: the layers can hide
__attribute__((weak)) void front_touch_unfit(void) {}   // DmGamepad.m: the layers show and the root lays out again
// A picture of the controls (premultiplied alpha, w x h pixels, row bytes a row: channels 4, BGRA; 2, grey and alpha, which the controls' whites and blacks fit in half the memory)
// for the frames of generation gen, made on the front end's thread (the main thread): the present thread takes it at its next live present. Returns 0 when Metal cannot make it
// (the front end then keeps the layers)
int mtl_present_touch_atlas(const void *px, int w, int h, size_t row, int channels, uint32_t gen) {
    if (!g_dev || !px || w <= 0 || h <= 0 || (channels != 2 && channels != 4)) return 0;
    MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:channels == 2 ? MTLPixelFormatRG8Unorm : MTLPixelFormatBGRA8Unorm width:(NSUInteger)w height:(NSUInteger)h mipmapped:NO];
    d.usage = MTLTextureUsageShaderRead; d.storageMode = MTLStorageModeShared;
    id<MTLTexture> t = [g_dev newTextureWithDescriptor:d];
    if (!t) { MLOG("[RED] present: no texture for the touch controls' %dx%d atlas; they stay on their layers", w, h); return 0; }
    t.label = @"touch controls";
    [t replaceRegion:MTLRegionMake2D(0, 0, (NSUInteger)w, (NSUInteger)h) mipmapLevel:0 withBytes:px bytesPerRow:row];
    pthread_mutex_lock(&g_touch_mu); g_touch_next = t; g_touch_next_gen = gen; g_touch_drop = 0; pthread_mutex_unlock(&g_touch_mu);
    return 1;
}
// Live present number seq: an atlas the front end made since becomes the one in use (resident from this present on), and those replaced leave the residency set once the GPU is
// done with every present that sampled them (the first present after the replacement, and so all before it, completed). An atlas the front end let go (mtl_present_touch_release:
// a controller in use, the Tap layout, a TV) is retired the same way, and none is in use until the front end makes one again
static void touch_adopt(uint64_t seq) {
    uint64_t done = atomic_load_explicit(&g_touch_done, memory_order_acquire); int freed = 0;
    for (int i = 0; i < 4; i++) if (g_touch_old[i].tex && done >= g_touch_old[i].after) { res_remove(g_touch_old[i].tex); g_touch_old[i].tex = nil; freed = 1; }
    pthread_mutex_lock(&g_touch_mu); id<MTLTexture> t = g_touch_next; uint32_t gen = g_touch_next_gen; int drop = g_touch_drop; g_touch_next = nil; g_touch_drop = 0; pthread_mutex_unlock(&g_touch_mu);
    if (!t && !(drop && g_touch_tex)) { if (freed) res_commit(); return; }
    if (g_touch_tex) {
        int k = 0; while (k < 4 && g_touch_old[k].tex) k++;
        if (k == 4) {   // four replaced atlases still in flight: this one (or the release) waits for the next present (unless a newer one came meanwhile)
            pthread_mutex_lock(&g_touch_mu); if (!g_touch_next && !g_touch_drop) { g_touch_next = t; g_touch_next_gen = gen; g_touch_drop = drop && !t; } pthread_mutex_unlock(&g_touch_mu);
            if (freed) res_commit(); return;
        }
        g_touch_old[k].tex = g_touch_tex; g_touch_old[k].after = seq;
    }
    g_touch_tex = t; g_touch_gen = t ? gen : 0;
    if (t) res_add(t);
    else MLOG("present: the touch controls are no longer drawn into the frame: their atlas is let go");
    res_commit();
}
static int touch_pipeline(MTLPixelFormat pf) {
    if (g_touch_pso[0] && g_touch_fmt == pf) return 1;
    if (g_touch_failed) return 0;
    NSError *e = nil; id<MTLLibrary> lib = host_lib("present", &e);
    g_touch_pso[0] = lib ? host_msl_rps_over(mtl_comp4(), lib, @"vs_touch", @"fs_touch", pf, &e) : nil;
    g_touch_pso[1] = g_touch_pso[0] ? host_msl_rps_over(mtl_comp4(), lib, @"vs_touch", @"fs_touch_grey", pf, &e) : nil;
    if (!g_touch_args) {
        MTL4ArgumentTableDescriptor *ad = [MTL4ArgumentTableDescriptor new]; ad.maxTextureBindCount = 1; ad.maxSamplerStateBindCount = 1; ad.maxBufferBindCount = 1;
        g_touch_args = [g_dev newArgumentTableWithDescriptor:ad error:&e];
    }
    if (!g_touch_pso[0] || !g_touch_pso[1] || !g_touch_args) {
        g_touch_pso[0] = g_touch_pso[1] = nil;
        g_touch_failed = 1;
        MLOG("[RED] present: no pipeline for the touch controls (%s); the front end draws them on their layers again", e ? e.localizedDescription.UTF8String : "no error given");
        front_touch_draw_failed(); return 0;
    }
    g_touch_fmt = pf; return 1;
}
// The live present's frame for a dw x dh drawable: the front end's latest (or the last one read, when the front end was writing one each time this looked), if it was laid out
// for a drawable of that size; else 0, and the present draws as before (a drawable made before or after a layout change, the Mac, a TV)
static int touch_frame_now(touch_frame *f, double dw, double dh) {
    touch_adopt(++g_touch_seq);
    atomic_store_explicit(&g_touch_live_ns, now_ns(), memory_order_relaxed);
    uint32_t s = touch_read(&g_touch_box, &g_touch_last); if (s) g_touch_last_seq = s;
    *f = g_touch_last;
    int fits = touch_frame_fits(f, dw, dh);
    if (touch_unfit_step(&g_touch_unfit, f, fits)) {   // the controls are drawn nowhere: the front end shows their layers and lays out again
        MLOG("present: the touch controls' frame is for a %ux%u drawable, the drawable is %.0fx%.0f for %d presents: the front end shows their layers and lays the view out again",
             f->canvas_w, f->canvas_h, dw, dh, TOUCH_UNFIT);
        front_touch_unfit();
    }
    return touch_frame_places(f, g_touch_last_seq, &g_touch_dead, fits);
}
// The controls over the picture, in the present's pass (en, a dw x dh drawable): one quad each, in their order, from the atlas in use; uvb's TOUCH_UV floats take the quads.
// Nothing when the frame's quads are for another atlas than the one in use (the next present has it)
static void touch_draw(id<MTL4RenderCommandEncoder> en, const touch_frame *f, id<MTLBuffer> uvb, MTLPixelFormat pf, double dw, double dh) {
    if (f->on != TOUCH_ON || !f->n || !g_touch_tex || f->atlas != g_touch_gen || !touch_pipeline(pf)) return;
    uint32_t n = MIN(f->n, (uint32_t)TOUCH_QUADS);
    memcpy((float *)uvb.contents + TOUCH_UV, f->q, n * sizeof(touch_quad));
    [en setViewport:(MTLViewport){0, 0, dw, dh, 0, 1}];
    [en setRenderPipelineState:g_touch_pso[g_touch_tex.pixelFormat == MTLPixelFormatRG8Unorm]];
    [en setArgumentTable:g_touch_args atStages:MTLRenderStageVertex | MTLRenderStageFragment];
    [g_touch_args setAddress:uvb.gpuAddress + TOUCH_UV * sizeof(float) atIndex:0];
    [g_touch_args setTexture:g_touch_tex.gpuResourceID atIndex:0];
    [g_touch_args setSamplerState:g_blit_samp.gpuResourceID atIndex:0];
    [en drawPrimitives:MTLPrimitiveTypeTriangleStrip vertexStart:0 vertexCount:4 instanceCount:n];
    g_touch_drew = g_touch_last_seq;
    if (!atomic_exchange_explicit(&g_touch_said, 1, memory_order_relaxed))
        MLOG("present: the touch controls are drawn into the frame (%u quads from a %lux%lu %s atlas, %.1f MB; drawable %.0fx%.0f)", n, (unsigned long)g_touch_tex.width,
             (unsigned long)g_touch_tex.height, g_touch_tex.pixelFormat == MTLPixelFormatRG8Unorm ? "grey and alpha" : "BGRA", g_touch_tex.allocatedSize / 1048576.0, dw, dh);
}
// The present pass: src's valid rectangle drawn into dst (the drawable, or a screenshot's texture), edge-smoothed first where aa_encode takes it (aa:
// its state, nil = none), then through MetalFX where fx_encode takes it (fx: the scaler state to use, nil = bilinear), with Sharpening where present_sharpen gives it. uvb: the
// pass's constants (one buffer per present allocator, written by the CPU)
static int present_encode_m4(id<MTL4CommandBuffer> cb, id<MTLTexture> src, id<MTLTexture> dst, const int crop[4], id<MTLBuffer> uvb, fx_state *fx, aa_state *aa) {
    NSUInteger r[4]; if (!present_crop_rect(src, crop, r)) return 0;
    present_pipeline(dst.pixelFormat);
    double dw = dst.width, dh = dst.height;
    MTLViewport vp = present_fit(src, dw, dh);
    int live = fx == &g_fx_present;
    if (live) g_touch_drew = 0;
    touch_frame tf; double pic[4]; int touch = live && touch_frame_now(&tf, dw, dh);   // the live present: the front end's canvas and the touch controls on it
    if (touch && touch_picture_px(&tf, dw, dh, pic)) vp = (MTLViewport){pic[0], pic[1], pic[2], pic[3], 0, 1};   // the picture where the front end laid it out on the canvas
    int full = vp.originX == 0 && vp.originY == 0 && vp.width == dw && vp.height == dh;
    if (live) present_crop_note(src, r);
    id<MTLTexture> tex = present_raw_src(src), smooth = aa ? aa_encode(aa, cb, src, tex, r, uvb, live) : nil;
    if (smooth) { tex = smooth; r[0] = r[1] = 0; }   // the smoothed crop, at the origin of a texture of the window texture's size
    id<MTLTexture> up = fx ? fx_encode(fx, cb, tex, r, vp, dst.pixelFormat, live, smooth != nil) : nil;
    if (up) { tex = up; r[0] = r[1] = 0; r[2] = up.width; r[3] = up.height; }   // the scaled picture, the viewport's size: drawn 1:1
    float sharp = present_sharpen(live, up != nil, tex.pixelFormat);
    MTL4RenderPassDescriptor *rp = [MTL4RenderPassDescriptor new];
    rp.colorAttachments[0].texture = dst;
    rp.colorAttachments[0].loadAction = full ? MTLLoadActionDontCare : MTLLoadActionClear;
    rp.colorAttachments[0].storeAction = MTLStoreActionStore;
    rp.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 1);
    id<MTL4RenderCommandEncoder> en = [cb renderCommandEncoderWithDescriptor:rp];
    if (!en) { MLOG("[RED] failed to create the M4 present render encoder"); return 0; }
    [en barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageAll visibilityOptions:resource_vis()];
    [en setArgumentTable:g_present_args atStages:MTLRenderStageFragment];
    [g_present_args setTexture:tex.gpuResourceID atIndex:0];
    [g_present_args setSamplerState:g_blit_samp.gpuResourceID atIndex:0];
    float *uv = uvb.contents; NSUInteger tw = tex.width, th = tex.height, cx = r[0], cy = r[1], cw = r[2], ch = r[3];
    uv[0] = (float)cx / tw; uv[1] = (float)cy / th; uv[2] = (float)cw / tw; uv[3] = (float)ch / th;
    uv[4] = (cx + 0.5f) / tw; uv[5] = (cy + 0.5f) / th; uv[6] = (cx + cw - 0.5f) / tw; uv[7] = (cy + ch - 0.5f) / th;
    uv[8] = sharp; uv[9] = 1.0f / tw; uv[10] = 1.0f / th; uv[11] = 0;   // fs_rcas: its strength and the step to its neighbours, one source texel (fs reads the first 8)
    if (atomic_load_explicit(&g_origin_ll, memory_order_relaxed)) { uv[1] += uv[3]; uv[3] = -uv[3]; }   // lower-left origin: the window image is stored bottom-up
    [g_present_args setAddress:uvb.gpuAddress atIndex:0];
    [en setViewport:vp]; [en setRenderPipelineState:sharp > 0 ? g_rcas_pso : g_blit_pso];
    [en drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];
    if (touch) touch_draw(en, &tf, uvb, dst.pixelFormat, dw, dh);
    m4_end_present(en);
    return (up ? PRESENT_METALFX : sharp > 0 ? PRESENT_SHARPENED : PRESENT_STANDARD) | (smooth ? PRESENT_AA : 0);
}
// The present's picture drawn into an offscreen texture (out: private, render target) the way present_now draws it into the drawable, MetalFX included, on the Metal 4 queue;
// returns whether it was submitted. Completion reports the encoding kind, or PRESENT_FAILED on a GPU error. Resources remain resident and retained until GPU completion.
static int present_offscreen_m4(id<MTLTexture> src, const int crop[4], id<MTLTexture> out, void (^done)(int)) {
    id<MTL4CommandAllocator> al = [g_dev newCommandAllocator]; id<MTL4CommandBuffer> cb = [g_dev newCommandBuffer];
    id<MTLBuffer> uvb = [g_dev newBufferWithLength:sizeof(float) * PRESENT_UV_FLOATS options:MTLResourceStorageModeShared];
    if (!al || !cb || !uvb) { MLOG("[RED] offscreen present: no command allocator or buffer"); return 0; }
    id<MTLTexture> raw = present_raw_src(src);
    fx_state fx = {0}; aa_state aa = {0};   // edge smoothing of its own, made for this capture, so screenshots and DM_NVN_SHOT_OUT captures show it as the screen does
    res_add(out); res_add(uvb); res_commit();
    [cb beginCommandBufferWithAllocator:al];
    int kind = present_encode_m4(cb, raw, out, crop, uvb, &fx, &aa);
    [cb endCommandBuffer];
    if (!kind) { res_remove(out); res_remove(uvb); res_remove(fx.in); res_remove(fx.out); aa_free(&aa); return 0; }
    MTL4CommitOptions *options = [MTL4CommitOptions new];
    id<MTLTexture> aa_tex = aa.tex, aa_raw = aa.raw; id<MTLBuffer> aa_work = aa.work, aa_ctl = aa.ctl; id<MTL4ArgumentTable> aa_at = aa.at;
    [options addFeedbackHandler:^(id<MTL4CommitFeedback> f) {
        fb_in("offscreen present");
        (void)al; (void)cb; (void)raw; (void)fx.sc; (void)aa_raw; (void)aa_at;   // keep the Metal 4 commands, source view, scaler and edge smoothing's state alive too
        res_remove(out); res_remove(uvb); res_remove(fx.in); res_remove(fx.out); res_remove(aa_tex); res_remove(aa_work); res_remove(aa_ctl);
        if (aa_ctl && !f.error) aa_note(aa_ctl);
        gpu_busy_note(f.GPUStartTime, f.GPUEndTime);
        if (f.error) { MLOG("[RED] offscreen present: %s", f.error.description.UTF8String); victim_note(f.error, "offscreen present", 0); gpu_lost_check(f.error, "offscreen present"); }
        done(f.error ? PRESENT_FAILED : kind);
        fb_out();
    }];
    if (gpu_gone()) { gpu_gone_skip(); return 0; }   // nothing more is sent to a GPU taken as lost (its feedback would never come: no wait for it)
    [g_q4 commit:&cb count:1 options:options];
    return 1;
}
// Diagnostic readback and tests wait for the same asynchronous capture used by whole-window screenshots. A timeout leaves cleanup with the GPU completion handler.
static int present_offscreen_wait(id<MTLTexture> src, const int crop[4], id<MTLTexture> out) {
    dispatch_semaphore_t sem = dispatch_semaphore_create(0); __block int kind = PRESENT_FAILED;
    if (!present_offscreen_m4(src, crop, out, ^(int k) { kind = k; dispatch_semaphore_signal(sem); })) return 0;
    if (dispatch_semaphore_wait(sem, dispatch_time(DISPATCH_TIME_NOW, 10 * NSEC_PER_SEC))) { MLOG("[RED] offscreen present: the GPU did not finish within 10 s"); return 0; }
    return kind;
}
// The present command buffer's GPU time (its commit feedback: from its first to its last command, edge smoothing, the MetalFX scaler and the present pass), every 600 presents as
// p50 / p95, apart for presents through the bilinear pass, through MetalFX and through the bilinear pass with Sharpening, each with and without edge smoothing (kind:
// present_encode_m4's; the [ab] lines leave the present's command buffer out, so DM_POST_AA=ab reads its cost here), with the times the game's crop moved so far
// (present_crop_note: a game whose dynamic resolution moves its crop, which a game's nvnWindowSetCrop call count alone does not show). Under g_pq_mu (the feedback handler)
static void present_gpu_note(double s, int kind) {
    static double v[6][600]; static int n[6];
    int b = (kind & ~PRESENT_AA) == PRESENT_METALFX ? 1 : (kind & ~PRESENT_AA) == PRESENT_SHARPENED ? 2 : 0;
    if (kind & PRESENT_AA) b += 3;
    if (!(s > 0 && s < 1)) return;
    v[b][n[b]++] = s * 1e3;
    if (n[b] < 600) return;
    double *a = v[b]; for (int i = 1; i < 600; i++) { double x = a[i]; int j = i - 1; while (j >= 0 && a[j] > x) { a[j + 1] = a[j]; j--; } a[j + 1] = x; }
    static const char *const how[] = {"through the bilinear pass", "through MetalFX", "through the bilinear pass with sharpening"};
    MLOG("present command buffer GPU time over 600 presents %s%s: p50 %.3f ms, p95 %.3f ms, max %.3f ms; crop moved %llu times so far", how[b % 3], b >= 3 ? " after edge smoothing" : "", a[299], a[569], a[599],
         (unsigned long long)atomic_load_explicit(&g_present_crop_moves, memory_order_relaxed));
    n[b] = 0;
}
// Edge smoothing (CMAA2) and the MetalFX scaler give their textures back once they are off. Kept, as they were, after the in-game menu, Picture Stretch or a TV turned them off, they held 32.7 MB of CMAA2 state at 1080p on an iPhone and the scaler's 14.4 MiB output (25.6 MiB on a Mac). The live present (present_now, the only thread that encodes with g_aa_present and g_fx_present) counts the presents each effect has not run in; after FX_IDLE_PRESENTS of them (2 s at 60 Hz, so a crop that moves in and out of MetalFX's rule does not make a scaler every few frames), and once the last present that ran it has completed on the GPU (its allocator's g_present_alloc_done reached that present's ticket, which waits for nothing: presents in flight since never read these textures), the effect's textures and buffers leave the residency set and are released. Turning it on again makes them again (about 1.5 ms for the scaler; CMAA2's kernels stay made). DM_PRESENT_FX_KEEP=1 keeps them, as before
enum { FX_IDLE_PRESENTS = 120 };
static int g_fx_idle_presents = FX_IDLE_PRESENTS;   // the tests lower it
static uint64_t g_aa_last_ticket, g_fx_last_ticket, g_aa_idle, g_fx_idle; static int g_aa_last_alloc, g_fx_last_alloc, g_aa_ran, g_fx_ran;   // present thread
static int present_fx_keep(void) { static int k = -1; if (k < 0) { const char *e = getenv("DM_PRESENT_FX_KEEP"); k = e && atoi(e); } return k; }
static int present_ticket_done(int alloc_i, uint64_t ticket) { pthread_mutex_lock(&g_pq_mu); int d = g_present_alloc_done[alloc_i] >= ticket; pthread_mutex_unlock(&g_pq_mu); return d; }
// g_fx_trim_req: a memory trim (mtl_trim_at) asks the present thread to release an effect that is off at its next present, without the FX_IDLE_PRESENTS wait; still only once the last
// present that ran it has completed, so a request that finds one still on the GPU stays for the next present
static _Atomic int g_fx_trim_req;
static int rep_effect_busy(int aa);   // the present repeat (nvn_present_repeat.inc): one whose present pass ran edge smoothing (aa) or the MetalFX scaler is still on the GPU
static int fg_effect_busy(int aa);   // frame generation (nvn_framegen.inc): a generated frame whose present pass ran edge smoothing (aa) or the MetalFX scaler is still on the GPU
static void present_fx_idle(int kind, uint64_t ticket, int alloc_i) {
    if (kind & PRESENT_AA) { g_aa_last_ticket = ticket; g_aa_last_alloc = alloc_i; g_aa_ran = 1; g_aa_idle = 0; } else g_aa_idle++;
    if ((kind & ~PRESENT_AA) == PRESENT_METALFX) { g_fx_last_ticket = ticket; g_fx_last_alloc = alloc_i; g_fx_ran = 1; g_fx_idle = 0; } else g_fx_idle++;
    if (present_fx_keep()) { atomic_store(&g_fx_trim_req, 0); return; }
    aa_state *aa = &g_aa_present; fx_state *fx = &g_fx_present;
    int req = atomic_exchange(&g_fx_trim_req, 0); uint64_t wait = req ? 1 : (uint64_t)g_fx_idle_presents;
    // A generated frame (DM_FRAMEGEN) presents through the same effects one tick before its real frame: one still on the GPU holds them as a real present's would
    int aa_gen = (aa->tex || aa->work) && (fg_effect_busy(1) || rep_effect_busy(1)), fx_gen = (fx->sc || fx->in || fx->out) && (fg_effect_busy(0) || rep_effect_busy(0));   // a repeat's too
    if (req && (((aa->tex || aa->work) && g_aa_idle >= 1 && ((g_aa_ran && !present_ticket_done(g_aa_last_alloc, g_aa_last_ticket)) || aa_gen)) ||
                ((fx->sc || fx->in || fx->out) && g_fx_idle >= 1 && ((g_fx_ran && !present_ticket_done(g_fx_last_alloc, g_fx_last_ticket)) || fx_gen)))) atomic_store(&g_fx_trim_req, 1);   // not yet: next present
    if ((aa->tex || aa->work) && g_aa_idle >= wait && (!g_aa_ran || present_ticket_done(g_aa_last_alloc, g_aa_last_ticket)) && !aa_gen) {
        uint64_t z = aa->tex.allocatedSize + aa->work.allocatedSize + aa->ctl.allocatedSize;
        aa_free(aa); res_commit(); g_aa_ran = 0;
        atomic_fetch_add(&g_present_fx_freed, 1); atomic_fetch_add(&g_present_fx_freed_bytes, z);
        MLOG("present edge smoothing: off for %llu presents, CMAA2's texture and lists released (%.1f MB)%s", (unsigned long long)g_aa_idle, z / 1048576.0, req ? ", for a memory trim" : "");
    }
    if ((fx->sc || fx->in || fx->out) && g_fx_idle >= wait && (!g_fx_ran || present_ticket_done(g_fx_last_alloc, g_fx_last_ticket)) && !fx_gen) {
        uint64_t z = fx->in.allocatedSize + fx->out.allocatedSize;
        res_remove(fx->in); res_remove(fx->out); fx->sc = nil; fx->in = fx->out = nil; res_commit(); g_fx_ran = 0;
        atomic_fetch_add(&g_present_fx_freed, 1); atomic_fetch_add(&g_present_fx_freed_bytes, z);
        MLOG("present upscaling: MetalFX not run for %llu presents, its scaler and textures released (%.1f MB)%s", (unsigned long long)g_fx_idle, z / 1048576.0, req ? ", for a memory trim" : "");
    }
}
// ---- Memory pressure and the trim ----
// Nothing listened for memory warnings: a jetsam could not be traced to memory, and nothing gave back what sits idle. The front ends (front_ios.m, front_mac.m) watch the system's
// memory pressure (DISPATCH_SOURCE_TYPE_MEMORYPRESSURE) and call dm_gfx_pressure (hle_nvn.c), which logs the footprint and the room left (mtl_pressure) and asks for a trim. The
// trim (mtl_trim_at) runs where nothing it releases can be in use: at the next submission's start (mtl_sub_begin, the submit thread), its objects waiting in the deferred-release
// queue for the fence of the submission that starts there, which no present or submission committed before it outlasts on the queue; or going to the background
// (dm_gfx_suspend: the graphics gate closed and every submission and present drained, so for the last fence, which has passed). It releases what is idle and large: at a pressure
// warning first the render targets drawn over and unused for 300 ms (tu_press_warning, DM_NVN_RT_DEAD_PRESSURE), then render-target heaps waiting for reuse (rh_trim_all), the upload slots' blocks above UP_SLOT_BLOCK and their overflow blocks (up_trim_idle) and the staging pool (up_pool_release), packaged-texture spares
// (pkg_spare_release), same-pass feedback snapshots (fb_trim), the render-target shadows of depth and compressed textures (bcrt_trim), per-frame arena blocks the GPU is done with above ARENA_KEEP_BLOCKS (arena_trim), the finalized-texture table's least recently
// used entries above the default's 512 that no submission in flight uses (ghost_trim; a profile's ghost_table sets more), what the deferred-release queue holds whose fence has passed (defer_drain), and it asks the present thread to
// release edge smoothing and MetalFX if they are off (g_fx_trim_req), and frame generation's memory while it is not generating (fg_trim, all of it going to the background).
// Going to the background (level 3) it also drops the kept vertex conversions (vk_trim_all), which a
// pressure warning leaves: they are still drawn, and would be made again in the next submission. Each was made again on its next use before, as after the idle trims. dm_gfx_pressure also sweeps the guest's
// files (hle_svc.c dm_guest_file_trim, DM_GUEST_FILE). One line gives the MB per class; the memory line counts the trims. DM_MEMORY_TRIM=0 logs the pressure and trims
// nothing; DM_BG_TRIM=0 keeps the trim going to the background off
static int mem_trim_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("DM_MEMORY_TRIM"); on = !e || atoi(e); } return on; }
int mtl_bg_trim_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("DM_BG_TRIM"); on = !e || atoi(e); } return on; }
static uint64_t mem_footprint(void) {
    task_vm_info_data_t vi; mach_msg_type_number_t n = TASK_VM_INFO_COUNT;
    return task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&vi, &n) == KERN_SUCCESS ? vi.phys_footprint : 0;
}
// Going to the background (dm_gfx_suspend, after the GPU has drained): the host's own private textures whose content it can make again are marked purgeable
// (MTLPurgeableStateVolatile), so they no longer count against the app's footprint and the system can take their memory instead of ending the app (ported from S2Arm 23b99c4a;
// S2Arm measured one game on an iPhone: 1,048 MB at the resume after 30 s in the background with it, 2,497 MB without). Only packaged textures (pkg_upload: their content is the
// game's memory) the GPU has not written since (bg_pkg_gpu_wrote) and made without render-target or shader-write use. Render targets and every texture the GPU wrote stay
// non-volatile: their content is only on the GPU (ported from S2Arm 41eec704: one S2Arm player had 853 and 909 textures emptied at two returns, only 3 of them packaged; one the
// game drew once, a glyph atlas or a block-compressed texture a copy filled, stayed broken or magenta). Not textures in a heap, views, textures over a buffer, sparse textures,
// nor any buffer (argument tables, conversions and the like are kept across frames). Coming back, before the gate opens, they are made non-volatile again; a packaged texture
// the system emptied goes into the dropped-upload record (g_up_lost) and is uploaded again whole at its next use, as after a dropped upload batch. The footprint is logged
// going and coming back. DM_NVN_BG_PURGE=0 turns it off (the footprint is still logged)
static NSMutableArray<id<MTLTexture>> *g_bg_purged; static NSMutableSet *g_bg_purged_pkg;   // only while suspended (the gate closed, the GPU drained)
static uint64_t g_bg_fp_in, g_bg_purge_n, g_bg_purge_lost;
int mtl_bg_purge_on(void) { static int on = -1; if (on < 0) { const char *e = getenv("DM_NVN_BG_PURGE"); on = !e || atoi(e); if (!on) MLOG("DM_NVN_BG_PURGE=0: the host's textures stay non-volatile in the background"); } return on; }
void mtl_bg_purge(int bg) { @autoreleasepool {
    if (!g_dev) return;
    sc_forget_all();   // a volatile texture's memory may be taken (sc_note)
    int on = mtl_bg_purge_on();
    if (bg) {
        uint64_t f0 = mem_footprint(), bytes = 0, kept_b = 0; unsigned pkg = 0, kept = 0;
        if (on) {
            res_mu_lock(); NSArray *all = g_res_objects ? g_res_objects.allObjects : @[]; res_mu_unlock();
            os_unfair_lock_lock(&g_bg_pkg_lk); NSSet *pkgs = g_bg_pkg ? [NSSet setWithArray:g_bg_pkg.allObjects] : [NSSet set]; os_unfair_lock_unlock(&g_bg_pkg_lk);
            if (!g_bg_purged) { g_bg_purged = [NSMutableArray array]; g_bg_purged_pkg = [NSMutableSet set]; }   // a second suspend before a resume keeps the first one's list
            for (id o in all) {
                if (![o conformsToProtocol:@protocol(MTLTexture)]) continue;
