            if (g_present_alloc_done[alloc_i] < g_present_alloc_fence[alloc_i] && wait_mark_due(&m)) {
                static _Atomic int n;
                wait_say(&n, "the present allocator's previous present on the GPU", "present_now (" LOCK_SITE ")", "allocator %d last used by ticket %llu, its feedback reported %llu; presents processed %llu, in flight %d; fences completed %llu, submitted %llu",
                         alloc_i, (unsigned long long)g_present_alloc_fence[alloc_i], (unsigned long long)g_present_alloc_done[alloc_i], (unsigned long long)g_pq_done,
                         g_pq_inflight, (unsigned long long)atomic_load(&g_done), (unsigned long long)atomic_load(&g_fence));
            }
        }
        if (noted) wn_out(WN_PALLOC);
        pthread_mutex_unlock(&g_pq_mu);
        if (aw0) g_lk_aw_ns = ws_t0() - aw0;
    }
    [g_present_alloc4[alloc_i] reset];
    [g_q4 waitForDrawable:dr];
    id<MTL4CommandBuffer> cb = g_present_cb[alloc_i];
    [cb beginCommandBufferWithAllocator:g_present_alloc4[alloc_i]];
    int kind = present_encode_m4(cb, src, dr.texture, crop, g_present_uv[alloc_i], &g_fx_present, &g_aa_present);
    if (!kind) { [cb endCommandBuffer]; [g_q4 signalDrawable:dr]; present_dropped(ticket); return 0; }
    [cb endCommandBuffer];
    MTL4CommitOptions *o = [MTL4CommitOptions new];
    id<MTLBuffer> aa_ctl = kind & PRESENT_AA ? g_aa_present.ctl : nil;   // its counts, read when this present completes (a later present may have run by then: a log line's figures only)
    uint64_t touch_seq = g_touch_seq;   // this live present's number (touch_frame_now): once it completes, the touch controls' atlases it replaced can go (touch_adopt)
    uint32_t touch_drew = g_touch_drew;   // the frame it drew the touch controls from: once it completes, the front end can hide their layers (mtl_present_touch_ack)
    [o addFeedbackHandler:^(id<MTL4CommitFeedback> f) {
        fb_in("present");
        if (touch_seq > atomic_load_explicit(&g_touch_done, memory_order_relaxed)) atomic_store_explicit(&g_touch_done, touch_seq, memory_order_release);   // the feedback queue is serial
        uint32_t want = touch_drew && !f.error ? atomic_load_explicit(&g_touch_ack, memory_order_acquire) : 0;
        if (want && touch_seq_since(touch_drew, want) && atomic_compare_exchange_strong(&g_touch_ack, &want, 0)) front_touch_drawn(touch_drew);   // once per request
        gpu_busy_note(f.GPUStartTime, f.GPUEndTime);
        if (f.error) { MLOG("[RED] display command buffer error: %s", f.error.description.UTF8String); victim_note(f.error, "display command buffer", 0); gpu_lost_check(f.error, "display"); }
        else { if (aa_ctl) aa_note(aa_ctl); uint64_t t = now_ns(); if (!atomic_exchange_explicit(&dm_present_done_ns, t, memory_order_relaxed)) dm_start_first_frame(t); }   // a present on screen: the freeze detector's clock (dm/host/stall.c); the first one, the start's first frame (hle_lifecycle.c)
        pthread_mutex_lock(&g_pq_mu); if (ticket > g_pq_done) g_pq_done = ticket; if (ticket > g_present_alloc_done[alloc_i]) g_present_alloc_done[alloc_i] = ticket; g_pq_inflight--; pthread_cond_broadcast(&g_pq_cv);
        present_gpu_note(f.GPUEndTime - f.GPUStartTime, kind); pthread_mutex_unlock(&g_pq_mu);
        if (fg_on()) fg_paced(target_ts, f.GPUEndTime, 0);   // frame generation's pacing of every picture (nvn_framegen.inc)
        present_crop_line();
        fb_out();
    }];
    id<MTL4CommandBuffer> buffers[] = {cb};
    pthread_mutex_lock(&g_pq_mu); g_pq_inflight++; pthread_mutex_unlock(&g_pq_mu);
    if (gpu_gone()) gpu_gone_skip(); else [g_q4 commit:buffers count:1 options:o];   // a GPU taken as lost since the check above: nothing more is sent (the waits on g_pq_inflight give way)
    double t_commit = target_ts > 0 ? CACurrentMediaTime() : 0;   // the display link's line: this commit against the callback's deadline
    present_fx_idle(kind, ticket, alloc_i);
    if (target_ts > 0) {
        // late: the commit's time past the callback's deadline (update.targetTimestamp; ms, <= 0 on time, NAN outside a callback that set one), cw / aw: the callback's blocking (ms)
        static double late[300], cw[300], aw[300];
        static uint64_t lk_n; late[lk_n % 300] = g_lk_deadline > 0 ? (t_commit - g_lk_deadline) * 1000.0 : NAN; cw[lk_n % 300] = g_lk_cw_ns / 1e6; aw[lk_n % 300] = g_lk_aw_ns / 1e6; lk_n++;
        g_lk_cw_ns = 0;
        static double leads[300], e2e[300];   // e2e: game enqueue -> system-scheduled present (including the time waiting in the queue for the display-link callback), the full span of input latency that our side can read
        static int depths[300];   // g_link_it_depth: a frame left waiting on every tick (a standing frame, the FIFO rule's) adds a tick to e2e without changing the lead
        static uint64_t lead_n;
        leads[lead_n % 300] = (target_ts - CACurrentMediaTime()) * 1000.0; e2e[lead_n % 300] = g_link_it_tin > 0 ? (target_ts - g_link_it_tin) * 1000.0 : 0; depths[lead_n % 300] = g_link_it_depth;
        lead_n++;
        if (lead_n % 300 == 0) {
            int dsum = 0, dmax = 0, dstand = 0; for (int i = 0; i < 300; i++) { dsum += depths[i]; if (depths[i] > dmax) dmax = depths[i]; dstand += depths[i] >= 2; }
            double a[300]; memcpy(a, leads, sizeof a);
            for (int i = 1; i < 300; i++) { double v = a[i]; int j = i - 1; while (j >= 0 && a[j] > v) { a[j + 1] = a[j]; j--; } a[j + 1] = v; }
            double b[300]; memcpy(b, e2e, sizeof b);
            for (int i = 1; i < 300; i++) { double v = b[i]; int j = i - 1; while (j >= 0 && b[j] > v) { b[j + 1] = b[j]; j--; } b[j + 1] = v; }
            MLOG("display link up to tick %llu: ticks 300, presents %llu, empty ticks %llu (held for the present interval %llu), old frames dropped by merging %llu; submission ahead of target display p50 %.3f ms / min %.3f ms; game enqueue to target display p50 %.3f ms / min %.3f / max %.3f ms; "
                 "frames queued at the callback mean %.2f / max %d, two or more on %d of 300, standing frames trimmed %llu%s",
                 (unsigned long long)g_link_tick_n, (unsigned long long)g_present_n, (unsigned long long)g_link_empty, (unsigned long long)g_link_held,
                 (unsigned long long)g_link_dropped, a[149], a[0], b[149], b[0], b[299], dsum / 300.0, dmax, dstand, (unsigned long long)g_link_trims, lk_line(late, cw, aw));
        }
    }
    [g_q4 signalDrawable:dr];
    g_present_alloc_fence[alloc_i] = ticket;
#if TARGET_OS_SIMULATOR   // The iOS simulator SDK has no presentation-time callback and no minimum display duration (used only for picture acceptance, display-link ticks are not counted)
    (void)period; [dr present];
#else
    uint64_t pn = ticket;   // Record the present time by the game's present sequence number (ticket number): hle's present statistics are taken by "the game's nth present"; in the display link path the actual present count != the game's present count (old frames get merged and dropped)
    [dr addPresentedHandler:^(id<MTLDrawable> d) {   // Actual presentation time (the time this frame is really put on screen, CACurrentMediaTime base)
        CFTimeInterval tt = d.presentedTime;
        g_pres[pn % PRING] = (pres_ent){pn, tt > 0 ? tt : -1};
        if (fg_on()) fg_shown(tt, 0);   // frame generation's on-screen intervals of every picture (nvn_framegen.inc)
    }];
    // Each frame is displayed for at least one present period: when the GPU completion time jitters around a 120 Hz refresh boundary, the paired "25 ms + 8.33 ms" stutter no longer appears
    if (target_ts > 0) [dr present];
    else if (period > 0) [dr presentAfterMinimumDuration:period]; else [dr present];
#endif
    (void)frame;
    return 1;
}
// ---------- Present thread ----------
// NVN semantics: QueuePresentTexture only queues the present and returns immediately (the game often calls it while holding a lock; iOS real device: synchronously waiting for nextDrawable inside it
// takes about 30 ms, the lock is held about 90% of the time, and the loading thread starves). Taking the drawable, blit and present are all done on this thread in enqueue order.
// Ticket number = which enqueue it is (starting from 1); g_pq_done = the ticket number that has been processed (blit committed to the GPU queue).
// Swapchain texture return: before AcquireTexture gets a texture it waits for the ticket of that texture's previous present to be processed (mtl_present_wait), after which the commands the game draws into it
// are necessarily ordered after that blit on the GPU queue.
#define PQ 8
typedef struct { tex_t t; double period; uint64_t frame; int crop[4]; double t_in; uint64_t snap_v, up_v, sub_v, fg_v; } pq_item;   // fg_v: frame generation's capture for this frame (0 = none, nvn_framegen.inc)
     // snap_v: the snapshot copy this present shows (snap_commit_wait); up_v: the upload batch present_enqueue flushed for it (pup_commit_wait); sub_v: the submissions a present of the game's own texture follows (sub_commit_wait)   // t_in: the time the game handed this frame into the present queue (CACurrentMediaTime)
static void snap_commit_wait(uint64_t v);
// With Metal encoding on its own thread an upload batch present_enqueue flushes is only recorded (rec_commit_upload): a RO_NOTE behind it sets g_pup_cmt to its g_pup_v, and the present
// thread waits for that before present_now commits the display command buffer straight to the queue, so the upload reaches the queue first
static _Atomic uint64_t g_pup_cmt; static uint64_t g_pup_v;   // g_pup_v: submit thread only
static void pup_commit_wait(uint64_t v) { if (v) rec_note_wait(&g_pup_cmt, v); }
static pq_item g_pq[PQ];
static uint64_t g_pq_in;
static int present_now(const tex_t *, double, uint64_t, uint64_t, const int[4], id<CAMetalDrawable>, double);
static double g_link_vperiod, g_link_vhalf;   // virtual ticks (link_range): seconds per counted tick (0 = every callback is a tick) and half a refresh of the screen

@interface NvMetalDisplayLinkDelegate : NSObject <CAMetalDisplayLinkDelegate>
@end

// Fallback for the display link going silent while in the foreground (two smoke-test hangs before merge: the display link stopped calling back while the app was in the foreground, nobody takes the queued frames, and the game waits forever for its previous present to be processed before "acquiring the next swapchain texture"):
// when mtl_present_wait has waited longer than STALL_NS and the display link has not called back for that long, drop the waiting frame and earlier queued frames as when entering the background (accounted as dropped frames) and let the game keep running; when the display link comes back things return to normal automatically.
// One stall logs one hint line, and one line on recovery (neither is a failure); only when the same stall lasts longer than STALL_RED_NS is it a failure. All under g_pq_mu
#define STALL_NS 100000000ull
#define STALL_RED_NS 2000000000ull
static uint64_t g_stall_t0, g_stall_drop, g_stall_n; static int g_stall_red, g_stall_logged;
// Under g_pq_mu: n frames dropped by the stall fallback (present_wait_at), the stall started at the link's last tick if it has not been (its line, RED and rescue count from there)
static void stall_note_locked(uint64_t n, uint64_t last, uint64_t now) {
    if (!g_stall_t0) { g_stall_t0 = last ? last : now; g_stall_drop = 0; g_stall_red = 0; g_stall_logged = 0; g_stall_n++; }
    g_stall_drop += n;
}
// When the display link stays silent for LINK_RESCUE_NS while the app is active, presents stop waiting for it: mode 0 (the present thread takes drawables itself), so the
// picture keeps moving instead of standing still on dropped frames (d2r-mobile afad65c, via MacNativeGames cf1e629: an iPhone's link stopped while active and the picture
// froze for 80 s; macOS also pauses the link of a window it takes for covered). The link is tried again after g_rescue_back_ns (link_sync), which doubles on each new
// stall up to 60 s. The requested g_dm_present_link stays unchanged; all rescue state changes take g_pq_mu, and link_sync handles the link object on the enqueue thread.
#define LINK_RESCUE_NS 500000000ull
static _Atomic int g_rescue_mode;   // Also read by link_on without g_pq_mu, to stop pacing on silent ticks immediately
static uint64_t g_rescue_back_at, g_rescue_back_ns = 3000000000ull, g_rescue_n;
// The display link watchdog only recognizes the "active" state: when the App loses active status (pulling down Control Center / notifications, incoming call, system popup) and in the background the system does not call back anyway, and the picture is covered too -- the frame-drop fallback stays as before,
// but it is not counted as stuck and no failure is reported; the stall is measured from the later of "the most recent callback / the most recent activation" (A16 logs: 8–17 seconds inactive and 17 seconds in the background were both reported as "stuck in foreground")
__attribute__((weak)) int dm_focus_now(void) { return 1; }   // The host's hle_oe.c provides the strong definition; when graphics unit tests do not link the host it is treated as always active
__attribute__((weak)) uint64_t dm_focus_in_since(void) { return 0; }
#include "nvn_framegen.inc"
// The present repeat (DM_PRESENT_REPEAT=1, nvn_present_repeat.inc, included after the present snapshots): a tick without a new frame shows the last one again
static int rep_on(void); static int rep_tick_locked(id<CAMetalDrawable> dr, double target_ts); static void rep_note(const pq_item *it, uint64_t ticket, int shown);
@implementation NvMetalDisplayLinkDelegate
- (void)metalDisplayLink:(CAMetalDisplayLink *)link needsUpdate:(CAMetalDisplayLinkUpdate *)update {
    (void)link;
    double cb = CACurrentMediaTime();
    g_lk_deadline = update.targetTimestamp; g_lk_cw_ns = 0;   // the display link line's deadline (present_now); read before anything else, as every path below may present
    pthread_mutex_lock(&g_pq_mu);
    // A callback that cannot take a present must not reset the watchdog or count a pacing tick: the next enqueue that hands off the layer may be waiting for a texture (upstream PR #3004)
    if (!g_dm_present_link || g_rescue_mode) { pthread_mutex_unlock(&g_pq_mu); return; }
    if (g_stall_t0) { uint64_t since = dm_focus_in_since(), t = now_ns();
        MLOG("display link recovered: stalled %.0f ms (%.0f ms of it active), fallback dropped %llu frames (stall #%llu)", (t - g_stall_t0) / 1e6, (t - (g_stall_t0 > since ? g_stall_t0 : since)) / 1e6, (unsigned long long)g_stall_drop, (unsigned long long)g_stall_n); g_stall_t0 = 0; }
    pthread_mutex_unlock(&g_pq_mu);
    double vp = g_link_vperiod, tick_time = update.targetPresentationTimestamp;
    if (vp > 0) {   // virtual ticks: only the refresh nearest each slot of a steady clock at the wanted rate counts (link_range)
        static double next, vp_was;
        if (vp != vp_was || tick_time > next + vp) { next = tick_time; vp_was = vp; }   // the first callback, a new rate, or after a stall: the clock starts again here
        if (tick_time < next - g_link_vhalf) return;
        tick_time = next;   // the hold follows counted slots even when their physical refreshes are unevenly spaced
        next += vp;
    }
    const double tick_period = vp > 0 ? vp : 1.0 / mtl_link_rate();   // the hold below counts whole ticks of this
    static double cb_prev, gap_max; static int nticks;   // for g_link_ring: callbacks counted as ticks since the previous present, and the longest interval between them
    if (cb_prev > 0 && cb - cb_prev > gap_max) gap_max = cb - cb_prev;
    cb_prev = cb; nticks++;
    pthread_mutex_lock(&g_link_mu);
    __atomic_store_n(&g_link_tick_ns, now_ns(), __ATOMIC_RELAXED);
    g_link_tick_n++;
    pthread_cond_broadcast(&g_link_cv);
    pthread_mutex_unlock(&g_link_mu);
    pthread_mutex_lock(&g_pq_mu);
    // Frame generation: the real frame whose generated frame the tick before showed comes first, before the hold and before a new frame (nvn_framegen.h fg_tick)
    if (g_fg_seq.has && fg_take_pending(update.drawable, update.targetPresentationTimestamp, cb)) return;   // (unlocks g_pq_mu)
    // Checked again: the queue lock was released to publish the tick, and rescue or a mode change can take the queue away from this callback in that interval
    if (!g_dm_present_link || g_rescue_mode || g_pq_read == g_pq_in) {
        int live = g_dm_present_link && !g_rescue_mode; if (live) g_link_empty++; g_link_standing = 0;
        if (live && rep_on()) { rep_tick_locked(update.drawable, update.targetPresentationTimestamp); return; }   // the last frame again (unlocks g_pq_mu)
        pthread_mutex_unlock(&g_pq_mu); return; }
    // The previous frame's period spans two or more ticks of the link: keep it on screen for those whole ticks before taking the next one, as the Switch flips only every N vertical syncs. This also holds while the link runs at 60 Hz (Mario 1.2.1 sets 2 for single frames, see nvn_game_fps in hle_nvn.c);
    //   before, every tick took the newest frame, so that frame, carrying the extra time step the game advanced for it, was shown for only 16.7 ms and the game looked like it jumped ahead.
    //   Counted in ticks (upstream PR #1045): a fixed 25 ms cutoff let a 60 fps frame on the 120 Hz link be replaced by a queued one on the next 8.33 ms tick
    if (g_link_hold_until > 0 && tick_time < g_link_hold_until - 0.002) { g_link_held++;
        if (rep_on()) { rep_tick_locked(update.drawable, update.targetPresentationTimestamp); return; }   // the frame on screen again, where the ring allows it with the next one waiting (unlocks g_pq_mu)
        pthread_mutex_unlock(&g_pq_mu); return; }
    uint64_t first = g_pq_read + 1, ticket = g_pq_in;
    // In order, one frame per tick and at most one behind the newest: two waiting, the older now and the newer on the next tick; three or more, the older ones are dropped. Taking the newest
    // dropped the one before whenever two frames landed in the same refresh, as frames of a 60 fps game that take 16-17.5 ms do, and the next frame then stayed up 33 ms
    // (Dark Souls Remastered, from PR #31: presents within 14.7-18.7 ms 98.2 -> 99.98 %, about 2 ms more from enqueue to display). DM_PRESENT_FIFO=0 takes the newest, as before
    static int fifo = -1; if (fifo < 0) { const char *e = getenv("DM_PRESENT_FIFO"); fifo = !(e && !strcmp(e, "0")); MLOG("display link: %s", fifo ? "frames in order, at most one behind" : "the newest frame each tick (DM_PRESENT_FIFO=0)"); }
    // DM_PRESENT_TRIM=<K> (the profile's present_trim by default; without the key 60 on iOS, off on the Mac: present_trim_k): the rule above keeps one frame waiting for good once two frames land in one refresh and no refresh comes without a frame, as a game at
    // a steady 60 does: every frame then waits one tick more (16.7 ms at 60 Hz) between the game's enqueue and the screen (an iPhone 18 Pro Max: enqueue to display p50 65.5 ms against
    // a callback lead of 33 ms). After K ticks in a row that found two or more frames waiting (the frame left behind stood through all of them), one tick takes the newest, dropping
    // the one before it (a standing frame trimmed, counted in the display link's log line), and the rule holds again. K must be larger than the runs of such ticks that frame-time
    // jitter alone makes, each ended by a refresh without a frame (PR #31's frames of 16-17.5 ms), or the trim drops the frames FIFO is there to keep: 60, a second at 60 Hz, lets
    // a standing frame last a second at most. Empty ticks end a run; ticks held for a long present interval neither end nor count in one. With DM_PRESENT_FIFO=0 there is nothing to trim
    if (g_link_trim < 0) g_link_trim = present_trim_k(getenv("DM_PRESENT_TRIM"), DM_GAME_PRESENT_TRIM, PRESENT_TRIM_PLATFORM, &g_link_trim_src);
    int trim = present_trim_ticks(g_link_trim, g_link_trim_src, mtl_link_rate());
    if (trim != g_link_trim_was) { g_link_trim_was = trim;   // the first tick with a trim, and the iOS default's K again when the link's rate changes it
        char why[64]; int rate = mtl_link_rate();
        if (g_link_trim_src == TRIM_ENV) snprintf(why, sizeof why, "DM_PRESENT_TRIM=%d", g_link_trim);
        else if (g_link_trim_src == TRIM_PROFILE) snprintf(why, sizeof why, "game profile present_trim %d", g_link_trim);
        else if (g_link_trim_src == TRIM_PLATFORM && trim != g_link_trim) snprintf(why, sizeof why, "iOS default %d, a second of the %d Hz link", trim, rate);
        else snprintf(why, sizeof why, "%s %d", g_link_trim_src == TRIM_PLATFORM ? "iOS default" : "set", trim);
        if (trim) MLOG("display link: a frame left waiting through %d ticks in a row is dropped once (%s)%s", trim, why, fifo ? "" : "; nothing to trim with DM_PRESENT_FIFO=0"); }
    g_link_it_depth = (int)MIN(g_pq_in - g_pq_read, (uint64_t)PQ);
    if (fifo && ticket > first) {
        if (trim && ++g_link_standing >= trim) { g_link_standing = 0; g_link_trims++; }   // the newest (ticket stays g_pq_in)
        else ticket = ticket - first >= 2 ? g_pq_in - 1 : first;
    } else g_link_standing = 0;
    pq_item it = g_pq[(ticket - 1) % PQ]; g_link_it_tin = it.t_in;
    g_pq_read = ticket;
    if (ticket > first) { g_link_dropped += ticket - first; for (uint64_t k = first; k < ticket; k++) { g_pres[k % PRING] = (pres_ent){k, -1}; mtl_tex_unpin(g_pq[(k-1)%PQ].t.serial); } }   // Old frames merged and dropped are recorded as "not presented", so the present statistics honestly count them as dropped frames
    if (ticket > 1 && g_pq_done < ticket - 1) g_pq_done = ticket - 1;
    g_link_ring[ticket % PRING] = (link_ent){ticket, update.targetPresentationTimestamp, (update.targetPresentationTimestamp - cb) * 1e3, gap_max * 1e3, nticks}; nticks = 0; gap_max = 0;
    pthread_cond_broadcast(&g_pq_cv);
    pthread_mutex_unlock(&g_pq_mu);
    int submitted;
    { uint64_t cw0 = ws_t0(); snap_commit_wait(it.snap_v); pup_commit_wait(it.up_v); sub_commit_wait(it.sub_v); g_lk_cw_ns = ws_t0() - cw0; }   // the display link line's blocking (present_now)
    int gen = 0;
    if (fg_on()) @autoreleasepool { gen = fg_present_gen(&it, ticket, update.drawable, update.targetPresentationTimestamp); }   // the generated frame on this tick, the real one on the next
    if (gen) { pthread_mutex_lock(&g_pq_mu); g_fg_pend_it = it; fg_pend(&g_fg_seq, ticket); pthread_cond_broadcast(&g_pq_cv); pthread_mutex_unlock(&g_pq_mu); submitted = 1; }   // the broadcast: a present thread that took over meanwhile (a rescue) waits for this frame
    else @autoreleasepool { submitted = present_now(&it.t, it.period, it.frame, ticket, it.crop, update.drawable, update.targetPresentationTimestamp); mtl_tex_unpin(it.t.serial); }
    if (rep_on()) rep_note(&it, ticket, submitted && !gen);
    // Hold the whole ticks of the frame's period. The acquire distributes fractional ticks (e.g. 75 fps on a 120 Hz link), and present_period truncates to whole nanoseconds
    const double hold_ticks = floor((it.period + 1e-9) / tick_period);
    g_link_hold_until = submitted && hold_ticks >= 2 ? tick_time + hold_ticks * tick_period : 0;
    if (!submitted) {
        pthread_mutex_lock(&g_pq_mu);
        if (ticket > g_pq_done) g_pq_done = ticket;
        pthread_cond_broadcast(&g_pq_cv);
        pthread_mutex_unlock(&g_pq_mu);
    }
}
@end

static CAMetalDisplayLink *g_link; static CFRunLoopRef g_link_rl; static int g_link_started;
static int g_link_owns_layer, g_pq_holding;   // Under g_pq_mu: nextDrawable throws while the layer has the display link object attached, so the present thread that takes its own drawable and the display link object are mutually exclusive
static int link_on(void) { return g_dm_present_link && !atomic_load(&g_rescue_mode) && g_link != nil; }
// Screens whose refresh rate is not a multiple of the link's (144 or 165 Hz against 60 or 30): asked for 60 Hz, the system fires the link on every third refresh of a 165 Hz screen,
// 55 Hz, and a game paced by the link runs at 55 fps (27.5 at 30). There the link runs at the screen's rate and only the refreshes nearest a steady clock of the wanted rate count as
// ticks (g_link_vperiod, NvMetalDisplayLinkDelegate): 60 a second on average, each frame shown on the refreshes nearest its 1/60 s slot. DM_LINK_VTICK=0 keeps the system's choice.
// In fullscreen the Mac front end switches such a screen to a rate that is a multiple where it has one (front_screen_match), and the range is set again for it (link_sync)
__attribute__((weak)) int front_screen_max_fps(void) { return 0; }   // front_mac.m, front_ios.m; graphics unit tests have none
__attribute__((weak)) void front_screen_match(int fps) { (void)fps; }   // front_mac.m; graphics unit tests and iOS have none
__attribute__((weak)) void front_picture_shape(int w, int h) { (void)w; (void)h; }   // front_mac.m, front_ios.m; graphics unit tests have none
__attribute__((weak)) void front_picture_size(int w, int h) { (void)w; (void)h; }   // front_ios.m; the Mac's drawable keeps the window's pixels, and graphics unit tests have none
static CAFrameRateRange link_range(int mode) {
    static int on = -1; if (on < 0) { const char *e = getenv("DM_LINK_VTICK"); on = !(e && !strcmp(e, "0")); }
    int rate = mode == 3 ? 30 : mode == 2 ? 120 : 60, hz = on ? front_screen_max_fps() : 0;
    if (hz > rate && hz % rate) {   // at 120 fps too: a game stepping by its target must not get 144 ticks a second
        if (g_link_vperiod != 1.0 / rate) MLOG("display link at the screen's %d Hz, counting a tick every 1/%d s (the screen's rate is not a multiple of it)", hz, rate);
        g_link_vhalf = 0.5 / hz; g_link_vperiod = 1.0 / rate;
        return CAFrameRateRangeMake(rate, hz, hz);
    }
    g_link_vperiod = 0;
    return mode == 3 ? CAFrameRateRangeMake(30, 30, 30) : mode == 2 ? CAFrameRateRangeMake(60, 120, 120) : CAFrameRateRangeMake(60, 60, 60);
}
// The display link's frame latency: 2 in variable-refresh fullscreen, 1 otherwise (DM_PRESENT_LATENCY overrides both). In a window the system calls back about 50 ms before the target display
// time; in fullscreen it shows the layer directly and, at latency 1, calls back only one 60 Hz period (16 ms) ahead. There, on ProMotion screens (M4 Pro, M5 Max), it shows some
// presents one 120 Hz refresh late and the link skips its next tick, though the callbacks run on time and no GPU work is in the way; the frame step read the late frames as load
// and stepped to 20 fps on frames costing 0.1-0.6 vsyncs, and the game presented 15 frames a second (issues #347, #348). Latency 2 gives 33 ms and removed most of the misses on
// both machines, for one more frame of input lag in variable-refresh fullscreen only. Fixed-rate screens do not need this workaround (#822). Why the system misses at 16 ms,
// and why a fixed-rate screen still has about 20 ms more presentation delay with the link at either latency, remain open (docs/reference/frame-rate.md)
__attribute__((weak)) int front_fullscreen(void) { return 0; }   // front_mac.m; graphics unit tests and iOS have none
__attribute__((weak)) int front_screen_variable_refresh(void) { return 0; }   // front_mac.m; graphics unit tests and iOS have none
// CAMetalDisplayLink accepts only 1 or 2. Compare its readback with the supported request, or an oversized override rewrites and logs every frame.
static int link_latency(void) { return g_present_latency > 0 ? MIN(g_present_latency, 2) : front_fullscreen() && front_screen_variable_refresh() ? 2 : 1; }
static const char *link_latency_why(void) { return g_present_latency > 0 ? "DM_PRESENT_LATENCY" : !front_fullscreen() ? "window" : front_screen_variable_refresh() ? "fullscreen, variable refresh" : "fullscreen, fixed refresh"; }
// The 30 Hz link at a 30 fps target, except in fullscreen on a fixed-rate screen. There the link skipped ticks: Ocarina of Time at a 30 fps cap on a MacBook Air M4 (60 Hz) got
// 16.5-25 callbacks a second over stretches of 300 frames, also on frames with under 1 ms of GPU, and each skipped tick kept a frame on screen 66.7 ms (a 180 s walk: 388 and 996
// frames over 50 ms; 3-4 in a window, where the same link held 30.0). Why is open (docs/reference/frame-rate.md). The 60 Hz link paces the 30 through the present interval, as it
// does interval-2 frames (two ticks per acquire, mtl_link_wait_tick; each frame held for its period, g_link_hold_until): 7 frames over 50 ms on the same walk
static int link_30hz(void) { return !front_fullscreen() || front_screen_variable_refresh(); }
// The 120 Hz link (mode 2, a frame every other tick) in place of the 60 Hz one in fullscreen on a variable-refresh screen whose rate is a multiple of 120 (a ProMotion
// screen), unless DM_PRESENT_LINK chose the mode. There, with the 60 Hz link at frame latency 2, the system showed every present one 120 Hz refresh after the link's
// target time (@pres_at_ms − @link_target_ms = 8.33 ms) and the link then skipped every other tick (@link_gap_ms 16.7, 33.3, 16.7, …): 40 callbacks a second, so a game
// paced by the link ran at 40 fps with its GPU at 10 ms of the 16.7 (Ocarina of Time on an M5 Pro, macOS 27.2; at latency 1 the frame step went to 4 vsyncs, 15 fps).
// The Mac front end first switches such a screen to a fixed-rate mode (front_screen_match: 60 Hz, 60.0 fps at latency 1 there), so this is the fallback for a screen with
// no such mode or with DM_SCREEN_MATCH=0: the 120 Hz link held 59.2 fps, about 2% of frames up 25 ms. A window keeps the 60 Hz link, where every present lands on its
// target (docs/reference/frame-rate.md)
static int link_vrr_120(void) { int hz = front_screen_max_fps(); return !g_present_link_env && front_fullscreen() && front_screen_variable_refresh() && hz >= 120 && hz % 120 == 0; }
static int g_link_mode = 1;   // Current mode of the display link object: 1 / 2 same as g_dm_present_link, 3 = power-saving mode 30 Hz
#include "nvn_link_sim.inc"   // DM_LINK_SIM=1 (diagnostic): a display link the host times itself, for a Mac whose screen is locked or asleep
static void *link_main(void *arg) {   // Display link thread: started when switching to display-link mode, exits when switching back to 0
    (void)arg;
    pthread_setname_np("nvn-present-link");
    pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);
    CAMetalLayer *layer = (__bridge CAMetalLayer *)front_metal_layer();
    pthread_mutex_lock(&g_pq_mu); g_link_owns_layer = 1; while (g_pq_holding) pthread_cond_wait(&g_pq_cv, &g_pq_mu); pthread_mutex_unlock(&g_pq_mu);   // Wait for the present thread to finish handing over the frame it holds
    NvMetalDisplayLinkDelegate *delegate = [NvMetalDisplayLinkDelegate new];
    if (link_sim()) { link_sim_run(layer, delegate); g_link_started = 0; return NULL; }   // DM_LINK_SIM=1 (diagnostic, nvn_link_sim.inc)
    CAMetalDisplayLink *link = [[CAMetalDisplayLink alloc] initWithMetalLayer:layer];
    link.preferredFrameRateRange = link_range(g_link_mode);
    link.preferredFrameLatency = link_latency(); MLOG("display link: frame latency %d (%s)", link_latency(), link_latency_why());
    link.delegate = delegate;
    [link addToRunLoop:[NSRunLoop currentRunLoop] forMode:NSDefaultRunLoopMode];
    g_link_rl = CFRunLoopGetCurrent(); g_link = link;
    CFRunLoopRun();   // When switching back to mode 0 the display link object is invalidated and this thread exits (nextDrawable cannot get a drawable while the layer still has the display link object attached, so pausing alone is not enough)
    g_link_started = 0;
    return NULL;
}
static void link_sync(void) {   // Called every frame by the game's present thread: aligns the display link object's state to g_dm_present_link and the power-saving mode (can change at run time)
    static int applied;
    pthread_mutex_lock(&g_pq_mu);
    int want = g_dm_present_link;
    if (want < 0 || want > 2) { g_dm_present_link = applied == 3 ? 1 : applied; pthread_mutex_unlock(&g_pq_mu); return; }
    if (g_rescue_mode && (want != g_rescue_mode || now_ns() >= g_rescue_back_at)) {
        g_rescue_mode = 0; g_stall_t0 = 0; __atomic_store_n(&g_link_tick_ns, now_ns(), __ATOMIC_RELAXED);
        MLOG("display link: rescue ended, trying pacing mode %d (frame %llu)", want, (unsigned long long)atomic_load(&g_cur_frame));
    }
    if (g_rescue_mode) want = 0;
    pthread_mutex_unlock(&g_pq_mu);
