    if (fg_on()) fg_keep = fps30 && link_30hz() && fg_keeps_60hz();   // frame generation (nvn_framegen.inc)
    if (fps30 && link_30hz() && !fg_keep) want = 3;   // Power-saving mode: display link at 30 Hz (frame generation keeps the 60 Hz link where it can generate: its generated frames take the ticks between; fg_keeps_60hz)
    if (want) front_screen_match(want == 3 ? 30 : want == 2 ? 120 : 60);   // the game's rate: a variable-refresh screen goes to a fixed-rate mode at a multiple where it has one
    static int vrr_was; int vrr = want == 1 && link_vrr_120(), fg_vrr = vrr;   // variable-refresh fullscreen that kept its mode: the 120 Hz link paces the 60 (link_vrr_120)
    // Frame generation's 60 Hz link would be the 120 Hz one there, where it generates nothing (a link other than 60 Hz): the 30 fps cap's 30 Hz link back. The 60 Hz match was
    // asked for first, so a screen with a fixed-rate 60 Hz mode switches to it, and the next frame keeps the 60 Hz link
    if (vrr && fg_keep) { vrr = 0; want = 3; static int said; if (!said++) MLOG("frame generation: fullscreen on a variable-refresh screen with no fixed-rate 60 Hz mode: the 30 fps cap keeps its 30 Hz link, and no depth or motion is copied (frame %llu)", (unsigned long long)atomic_load(&g_cur_frame)); }
    // Captures (fg_cap_wanted) only at the 30 fps cap and not in that fallback, where nothing is generated from them (two copies at the render size a frame); it comes there
    // only after a capture (fg_keeps_60hz), so the next frame on a fixed-rate 60 Hz mode or in a window generates again. Stored once, after the fallback is known
    if (fg_on()) atomic_store_explicit(&g_fg_fps30, fps30 && !fg_vrr, memory_order_relaxed);
    if (vrr != vrr_was) { vrr_was = vrr; MLOG("display link: %s (frame %llu)", vrr ? "120 Hz in fullscreen on a variable-refresh screen, a frame every other tick (DM_PRESENT_LINK=1 keeps 60 Hz)" : "60 Hz again (window, fixed-rate screen or another frame rate)", (unsigned long long)atomic_load(&g_cur_frame)); }
    if (vrr) want = 2;
