// The part of the presented texture a snapshot copies: the present's crop alone when it lies in the texture and is smaller (DM_PRESENT_SNAP_WHOLE=1: the whole texture, as before), at
// its own place in a slot of the texture's size, so every reader keeps the game's crop and a dynamic resolution's crop moves inside the slot with no new texture. Nothing reads a snapshot
// outside its crop: the present clamps its samples half a texel inside it (present_encode_m4), the scaler, edge smoothing, frame generation, the present repeat and the screenshots take
// the crop. A game whose crop is smaller than its window texture copied the whole texture every frame (MacNativeGames 78cf9896 (MIT): Ocarina of Time's 3840x2160 window images there
// with a 1920x1080 crop, the copy 0.446 -> 0.095 ms of GPU time a frame on an M4)
static uint64_t g_snap_copies, g_snap_cropped;   // snapshot copies, and those of the crop alone (unit tests, the slot line)
static int snap_whole(void) { static int v = -1; if (v < 0) { const char *e = getenv("DM_PRESENT_SNAP_WHOLE"); v = e && atoi(e) != 0; if (v) MLOG("DM_PRESENT_SNAP_WHOLE=1: present snapshots copy the whole window texture, as before"); } return v; }
static MTLRegion snap_region(id<MTLTexture> src, const int crop[4]) {
    MTLRegion all = MTLRegionMake2D(0, 0, src.width, src.height);
    if (!crop || snap_whole() || crop[0] < 0 || crop[1] < 0 || crop[2] <= 0 || crop[3] <= 0 || (uint64_t)crop[0] + crop[2] > src.width || (uint64_t)crop[1] + crop[3] > src.height) return all;
    if ((NSUInteger)crop[2] == src.width && (NSUInteger)crop[3] == src.height) return all;
    return MTLRegionMake2D((NSUInteger)crop[0], (NSUInteger)crop[1], (NSUInteger)crop[2], (NSUInteger)crop[3]);
}
// Copy the presented texture (its crop: snap_region) into the next ring slot; returns the slot's serial (0 = no snapshot: the game's texture is presented as before)
static uint64_t snap_take(const tex_t *t, const int crop[4]) {
