    // The texture this slot held before it was last replaced: every present that read it had been committed when the replacing copy was (the busy check then), and the queue
    // signals g_snap_ev only after all work committed before the signal, so those presents have run and it can leave the residency set
    if (g_snap[k].old) { [g_snap_res removeAllocation:g_snap[k].old]; [g_snap_res commit]; g_snap[k].old = nil; }
    id<MTLTexture> src = tex_mtl(t); if (!src) return 0;
    // The copy reads the source before present_now runs, so it needs the same commit as present_now: a window texture presented before any submission has used it was made just
    // now and is outside the committed residency set. DRAGON QUEST XI S presents three times before its first submission; on an A17 Pro the copy faulted silently (its command buffer
    // has no error handler) and every later command buffer of the process was ignored (GitHub issue #626). A commit with nothing new costs nothing
    res_commit();
    if (!g_snap_ev) {
        g_snap_ev = [g_dev newSharedEvent];
        MTLResidencySetDescriptor *rd = [MTLResidencySetDescriptor new]; rd.initialCapacity = SNAP_MAX; NSError *e = nil;
        g_snap_res = [g_dev newResidencySetWithDescriptor:rd error:&e]; if (!g_snap_res) MDIE("present snapshots: no residency set: %s", e.localizedDescription.UTF8String);
        [g_q4 addResidencySet:g_snap_res];
        for (int i = 0; i < g_snap_n; i++) {
            g_snap_alloc[i] = [g_dev newCommandAllocator]; g_snap_cb[i] = [g_dev newCommandBuffer];
            if (!g_snap_alloc[i] || !g_snap_cb[i]) MDIE("present snapshots: no command allocator / buffer");
        }
    }
    id<MTLTexture> dst = g_snap[k].tex;
    if (!dst || dst.width != src.width || dst.height != src.height || dst.pixelFormat != src.pixelFormat) {
        MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:src.pixelFormat width:src.width height:src.height mipmapped:NO];
        d.storageMode = MTLStorageModePrivate; d.usage = MTLTextureUsageShaderRead;
        // The old texture stays resident (and referenced) until the slot's next use: the busy check above means its last present was committed, not that the GPU has run it,
        // and a texture removed here was sampled outside the residency set by a display command buffer still queued
        g_snap[k].old = dst;
        dst = [g_dev newTextureWithDescriptor:d]; if (!dst) { RED_ONCE(112, "present snapshots: no texture"); return 0; }
        [g_snap_res addAllocation:dst]; [g_snap_res commit];
        if (!g_snap[k].serial) { static _Atomic uint64_t n; g_snap[k].serial = (1ull << 61) + atomic_fetch_add(&n, 1) + 1; }
        serial_put(g_snap[k].serial, dst); g_snap[k].tex = dst;
        MLOG("present snapshots: ring slot %d %lux%lu format %lu", k, (unsigned long)dst.width, (unsigned long)dst.height, (unsigned long)dst.pixelFormat);
    }
    [g_snap_alloc[k] reset];
    id<MTL4CommandBuffer> cb = g_snap_cb[k];
    [cb beginCommandBufferWithAllocator:g_snap_alloc[k]];
    id<MTL4ComputeCommandEncoder> ce = [cb computeCommandEncoder];
    [ce barrierAfterQueueStages:MTLStageAll beforeStages:MTLStageBlit visibilityOptions:resource_vis()];   // after the frame's work and the slot's last blit to the screen
    MTLRegion rg = snap_region(src, crop); g_snap_copies++; if (rg.size.width != src.width || rg.size.height != src.height) g_snap_cropped++;
    if (g_snap_cropped == 1 && rg.size.width != src.width) MLOG("present snapshots: the copy takes the present's crop alone, %lux%lu at %lu,%lu of the %lux%lu window texture (DM_PRESENT_SNAP_WHOLE=1: the whole texture)",
                                                               (unsigned long)rg.size.width, (unsigned long)rg.size.height, (unsigned long)rg.origin.x, (unsigned long)rg.origin.y, (unsigned long)src.width, (unsigned long)src.height);
    [ce copyFromTexture:src sourceSlice:0 sourceLevel:0 sourceOrigin:rg.origin sourceSize:rg.size toTexture:dst destinationSlice:0 destinationLevel:0 destinationOrigin:rg.origin];
    [ce barrierAfterStages:MTLStageBlit beforeQueueStages:MTLStageAll visibilityOptions:resource_vis()];   // the game's next writes to its texture come after the copy
    [ce endEncoding]; [cb endCommandBuffer];
    uint64_t v = ++g_snap_v;
    if (rec_on() && g_rb_started) {   // a block of the encode thread's queue, behind the frame's work (see above)
        if (on_sub_thread()) rec_publish();   // what the submitting thread recorded outside a submission goes first
        rec_blk *b = rec_own_begin();
        rec_t *r = rec_own_put(b, RO_COMMIT_REAL, 2); r->a[0] = 0; r->a[1] = rec_obj(cb); r->a[2] = res_seq_now();
        r = rec_own_put(b, RO_SIGNAL, 1); r->a[0] = rec_obj(g_snap_ev); r->a[1] = v;
        r = rec_own_put(b, RO_NOTE, 0); r->a[0] = (uint64_t)(uintptr_t)&g_snap_cmt; r->a[1] = v;
        rec_own_push(b);
    } else {
        res_commit_lock(); Q4_COMMIT_TIMED("snap_take (the present snapshot's copy)", [g_q4 commit:&cb count:1]); [g_q4 signalEvent:g_snap_ev value:v]; res_commit_unlock();
        atomic_store(&g_snap_cmt, v);
    }
    g_snap[k].ev = v;
    return g_snap[k].serial;
}
#include "nvn_present_repeat.inc"
// copy (may be NULL): the g_snap_ev value of the snapshot copy this present took, 0 when it took none (mtl_present_wait_texture)
static uint64_t present_enqueue(const tex_t *t, double period, const int crop[4], uint64_t *copy) {
    const tex_t *win = t;   // the window texture itself (t may become a snapshot below): its crop sets its passes' render area (nvn_win_area.h)
    atomic_store(&dm_present_ns, now_ns()); if (copy) *copy = 0;
    if (atomic_load(&g_present_discard)) return 0;   // Ticket number 0 = no pending present; the swapchain texture acquire does not wait
    // A texture whose content comes from its storage is uploaded when it is first resolved (and again when its pages change), in an upload batch only the submit thread may open.
    // Bastion fills both window textures with WriteTexels at boot (main+0x9374) and presents one before drawing into it: resolved on the present thread, the upload aborted the host.
    // Resolve it here, where the game queues the present, and commit the batch, so the display command buffer comes after the upload on the queue and the present thread finds it uploaded.
    // A texture first used by the present is resolved here too: its first use decides whether it is taken from its storage (tex_cpu_content), so tex_from_storage cannot tell before,
    // and resolved on the present thread a window texture holding the CPU's data in a pool the CPU can write was uploaded there and aborted the host (t_nvn, whose window textures
    // nothing draws into, since c06d1e79 stopped a sliver of another span from making them the GPU's)
    // The flush is unconditional: outside a submission every upload path (the fills of a window texture this first use makes, tex_init_fill / tex_zero_fill, too) flushes at once,
    // and inside one an open batch must still reach the queue before the snapshot copy and the display command buffer. up_flush returns at once with no batch open.
    // With encoding on its own thread a flush between submissions is only recorded and published (rec_commit_upload, rec_publish), and nothing drains the encode thread until the next
    // submission: when a batch began since the last submission's commit and the last note (g_up_seq), a RO_NOTE behind it is what the present thread waits for (pup_commit_wait) before its own commit;
    // the batches before that commit are ahead of the submission's own note (g_sub_cmt), which the present waits for too (sub_commit_wait), or of the snapshot copy it shows
    uint64_t up_v = 0;
    if (on_sub_thread()) {
        static unsigned seq_noted; tex_mtl(t); up_flush();
        if (rec_on() && g_rb_started) {
            // only a batch begun since the last submission's commit is covered by no note yet; one already noted is covered by its note
            if (g_up_seq != g_up_seq_drained && g_up_seq != seq_noted) { rec_t *r = rec_put(RO_NOTE, 0); r->a[0] = (uint64_t)(uintptr_t)&g_pup_cmt; r->a[1] = ++g_pup_v; rec_publish(); }
            up_v = g_pup_v;   // the newest note, not only this present's: the display link may drop the present that carried it and show this one (notes run in order)
        }
        seq_noted = g_up_seq;
    }
    static pthread_once_t once = PTHREAD_ONCE_INIT; pthread_once(&once, present_start);
    link_sync();
    {   // Test switch DM_TEST_LINK_STALL=start seconds,duration seconds: counting from the first present, pause the display link at that point (imitating the display link not calling back while in the foreground) and release it when the duration is up. For verifying the fallback; not set in the product
        static double t0, at = -1, dur; static int st; double now = CACurrentMediaTime();
        if (at < 0) { at = 0; const char *e = getenv("DM_TEST_LINK_STALL"); if (e && sscanf(e, "%lf,%lf", &at, &dur) == 2 && at > 0 && dur > 0) { t0 = now; st = 1; } else at = 0; }
        if (st == 1 && link_on() && now - t0 >= at) { st = 2; mtl_link_pause(1); MLOG("DM_TEST_LINK_STALL: pausing the display link for %.1f s (frame %llu)", dur, (unsigned long long)atomic_load(&g_cur_frame)); }
        else if (st == 2 && now - t0 >= at + dur) { st = 3; mtl_link_pause(0); MLOG("DM_TEST_LINK_STALL: resuming the display link (frame %llu)", (unsigned long long)atomic_load(&g_cur_frame)); }
    }
    if (ws_on()) { static uint64_t f0; uint64_t f = atomic_load(&g_cur_frame); if (!f0) f0 = f; else if (f >= f0 + 300) { ws_report(f, f - f0); f0 = f; } }
    tex_t snap; uint64_t ss = 0; int slot = 0;
    if (mtl_snap_on()) {
        slot = (int)(atomic_load(&g_snap_next) % (uint64_t)g_snap_n);
        if ((ss = snap_take(t, crop))) { memset(&snap, 0, sizeof snap); snap.magic = MAGIC('T', 'E', 'X', 0); snap.serial = ss; t = &snap; }
    }
    if (!ss && on_sub_thread()) rec_flush_held();   // the frame's held submissions go to the queue now, not when the GPU next runs out of work (a snapshot copy's commit sends them too)
    mtl_tex_pin(t->serial);
    pthread_mutex_lock(&g_pq_mu);
    while ((g_pq_in - g_pq_done >= PQ || g_rep_busy) && !gpu_gone()) pthread_cond_wait(&g_pq_cv, &g_pq_mu);   // Wait only when the queue is full; normally AcquireTexture blocks first. g_rep_busy: a present repeat reads a snapshot slot (always 0 while it is off)
    uint64_t fg_v = fg_on() ? fg_frame_capture() : 0;   // the newest capture since the last present: this frame's upscale (nvn_framegen.inc)
    pq_item *it = &g_pq[g_pq_in % PQ]; *it = (pq_item){*t, period, atomic_load(&g_cur_frame), {0}, CACurrentMediaTime(), ss ? g_snap[slot].ev : 0, up_v, !ss && on_sub_thread() ? g_fence : 0, fg_v};
    nvn_aspect_win_note(&g_aspect_wins, win->serial, win->d.width, crop ? crop[0] : 0, crop ? crop[2] : 0);   // Ultrawide's camera: a pass on it follows the final picture (aspect_canvas)
    if (wa_on() && wa_present(&g_wa, win->serial, win->d.width, win->d.height, crop)) {   // under g_pq_mu: one presenting thread at a time
        static int said; if (!said++) MLOG("window textures: passes on a %ux%u window texture limited to the presented crop's %ux%u (held %d presents; DM_NVN_WIN_AREA=0 turns it off)",
            win->d.width, win->d.height, wa_area(&g_wa, win->serial) >> 16, wa_area(&g_wa, win->serial) & 0xffff, WA_HOLD); }
    if (crop) memcpy(it->crop, crop, sizeof it->crop);   // The current frame's state is enqueued with the ticket number, rather than reading the mutable window late on the present thread
    uint64_t tk = ++g_pq_in;
    if (ss) { g_snap[slot].ticket = tk; atomic_fetch_add(&g_snap_next, 1); if (copy) *copy = g_snap[slot].ev; }
    pthread_cond_broadcast(&g_pq_cv);
    pthread_mutex_unlock(&g_pq_mu);
    // A snapshot present returns its ticket and, in *copy, its copy: the game's next acquire of this texture waits for the copy (mtl_present_wait_texture), not for the screen
    return tk;
}
// For the layer's frame history (hle_vi.c): the ticket of the last present queued, and the last one the present queue has handed on (to the GPU and the display, or dropped)
void mtl_present_progress(uint64_t *queued, uint64_t *done) { pthread_mutex_lock(&g_pq_mu); *queued = g_pq_in; *done = g_pq_done; pthread_mutex_unlock(&g_pq_mu); }
// Do not wait during discard: the frame enqueued only after the flag was set (the present thread had just passed the flag check) has nobody to take it, and waiting for it would stall again; it is left for the following mtl_drain to clear
// Do not wait indefinitely in display-link mode: see the note at STALL_NS. Only frames "not yet taken by the display link" are dropped; the one already on its way to the screen is waited for until handed to the GPU (same dropping as when entering the background)
// The game's next acquire of the texture a present showed (nvn_queue_present_wait), and nvnQueueFinish after a present (nvn_queue_finish); tk and ev are what mtl_present
// returned for that present. Without a snapshot (ev 0) the screen samples that texture: wait for the present (below).
// With one, the texture is the game's again once its copy has run on the GPU, and with it the frame that drew into it: the game never has more frames in flight than
// its swapchain holds, and still need not wait for the screen. Before, a snapshot present handed the texture back at once (ticket 0) and only the ring slot paced the
// acquire. The slot is counted when the queue worker replays the present, so a game that acquires its next texture before presenting the current frame, or before the
// worker has replayed that present, then ran a frame further ahead of the GPU per ring slot, and one that sizes its
// CPU-written per-frame buffers on the swapchain's depth rewrote data a queued frame's draws still read: Xenoblade Chronicles 3's scene came out one flat colour in a
// third to a half of the frames (2 slots 32/80, 4 slots 49/80, snapshots off 0/80; LNPANDY/NX2Apple#1117)
// The wait for the copy is a CPU wait for the GPU: the ledger counts it as "snapshot copy" (WS_SNAPCOPY), apart from the ring slot's (WS_SNAP)
void mtl_present_wait_texture(uint64_t tk, uint64_t ev) {
    if (!ev) { present_wait_at(tk, "mtl_present_wait_texture (a texture's next acquire, or a queue finish)"); return; }
    uint64_t w0 = ws_t0(); int blocked = !atomic_load(&g_present_discard) && !gpu_gone() && g_snap_ev.signaledValue < ev;
    if (blocked) nvn_acquire_block();   // the texture's next acquire waits for its copy: the acquiring guest thread gives its core away (hle_nvn.c)
    if (blocked && ![g_snap_ev waitUntilSignaledValue:ev timeoutMS:2000]) RED_ONCE(169, "present snapshots: a texture's copy did not finish within 2 s; the game draws into it again");
    if (ws_on()) ws_put(WS_SNAPCOPY, w0, blocked);
}
// A present wait at the 10 s mark (under g_pq_mu): the ticket, the present queue's counters and the display link's, the fences. The waits below no longer lean on the display
// link's stall drops alone: a present taken by the link or the present thread that never reaches the GPU, or one whose GPU work never completes, waited here without a line
static void present_wait_say(uint64_t tk, const char *site) {
    static _Atomic int n;
    uint64_t now = now_ns(), tick = __atomic_load_n(&g_link_tick_ns, __ATOMIC_RELAXED);
    wait_say(&n, "a present to be handed to the GPU", site, "ticket %llu; presents queued %llu, taken %llu, processed %llu, in flight %d; display link %s, its last tick %.1f s ago, stall %d; fences completed %llu, submitted %llu",
             (unsigned long long)tk, (unsigned long long)g_pq_in, (unsigned long long)g_pq_read, (unsigned long long)g_pq_done, g_pq_inflight, g_link_owns_layer ? "owns the layer" : "does not own the layer",
             tick && now > tick ? (now - tick) / 1e9 : -1.0, g_stall_t0 != 0, (unsigned long long)atomic_load(&g_done), (unsigned long long)atomic_load(&g_fence));
}
static void present_wait_at(uint64_t tk, const char *site) {
    pthread_mutex_lock(&g_pq_mu);
    if (g_pq_done < tk && !atomic_load(&g_present_discard)) { pthread_mutex_unlock(&g_pq_mu); nvn_acquire_block(); pthread_mutex_lock(&g_pq_mu); }   // it will block: inside an acquire, the acquiring guest thread gives its core away (hle_nvn.c; not under this lock)
    int noted = g_pq_done < tk && !atomic_load(&g_present_discard); if (noted) wn_in(WN_PTICKET, tk);
    wait_mark m = {0, 1}; if (noted) wait_mark_set(&m);   // the 10 s line, once; the untimed waits below wake at the mark once to say it, then wait as before
    while (g_pq_done < tk && !atomic_load(&g_present_discard)) {
        if (drain_over()) break;   // the suspend's limit (mtl_drain_by): present_flush_ok reads what is left
        if (wait_mark_due(&m)) present_wait_say(tk, site);
        if (!g_link_owns_layer) { wait_mark_sleep(&g_pq_cv, &g_pq_mu, &m); continue; }
        int fg_pending = g_fg_seq.has && g_fg_seq.ticket <= tk;   // a real frame waiting behind its generated one (frame generation): it is taken, but its tick may never come
        if (g_pq_read >= tk && !fg_pending) { wait_mark_sleep(&g_pq_cv, &g_pq_mu, &m); continue; }   // This one has already been taken by the display link and is being presented: wait for it to be handed to the GPU (the GPU completion callback will wake us)
        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts); ts.tv_nsec += (long)STALL_NS; if (ts.tv_nsec >= 1000000000L) { ts.tv_sec++; ts.tv_nsec -= 1000000000L; }
        // Already determined to be in a stall (when the display link comes back the callback first clears g_stall_t0, then records the display-link tick time): no longer wait 100 ms in vain every frame, drop directly, and the game proceeds by its own display-link wait timeout (about two ticks)
        if (!g_stall_t0 && (pthread_cond_timedwait(&g_pq_cv, &g_pq_mu, &ts) != ETIMEDOUT || g_pq_done >= tk)) continue;
        // The link's tick first, then now (as crash.c's watchdog reads): the display-link callback stamps g_link_tick_ns under g_link_mu, not g_pq_mu, so a tick between the two reads made last newer
        // than now, and now - last wrapped into a stall that dropped queued presents (MacNativeGames 0cedee77d7c, a watchdog that misread a raced clock). A tick newer than now is a running link
        uint64_t last = __atomic_load_n(&g_link_tick_ns, __ATOMIC_RELAXED), now = now_ns();
        if (fg_pending && g_pq_read >= tk) {   // the link went silent before the pending real frame's tick: drop it as a stall drops queued frames
            if (now >= last && now - last >= STALL_NS) { if (g_fg_seq.has && g_fg_seq.ticket <= tk && fg_drop_pending_locked()) {
                MLOG("display link silent: the real frame after a generated one is dropped");
                stall_note_locked(1, last, now); } }   // the stall's books as the queued branch keeps them, so 'fallback dropped' counts it when the next wait is the queued one
            else pthread_cond_timedwait(&g_pq_cv, &g_pq_mu, &ts);   // the link still runs: its next tick shows it (bounded, no busy spinning)
            continue;
        }
        if (g_pq_read >= tk) continue;
        if (now < last || now - last < STALL_NS) { pthread_cond_timedwait(&g_pq_cv, &g_pq_mu, &ts); continue; }   // The display link is still running, it is just not this one's turn yet: keep waiting (bounded, no busy spinning)
        uint64_t n = tk - g_pq_read;
        for (uint64_t k = g_pq_read + 1; k <= tk; k++) { g_pres[k % PRING] = (pres_ent){k, -1}; mtl_tex_unpin(g_pq[(k-1)%PQ].t.serial); }
        g_link_dropped += n; g_pq_read = tk;
        // A real frame pending behind its generated one (frame generation; it was taken before these): dropped with them, under the same lock, so its ticket is not counted done
        // while it still points at its slot or texture, which the game may then fill again, and the link's return does not show it after newer frames
        if (g_fg_seq.has && g_fg_seq.ticket <= tk && fg_drop_pending_locked()) { n++; MLOG("display link silent: the real frame after a generated one is dropped with the frames queued after it"); }   // counted with them (g_stall_drop)
        while (g_pq_inflight && !drain_over()) { wait_mark_sleep(&g_pq_cv, &g_pq_mu, &m); if (g_pq_inflight && wait_mark_due(&m)) present_wait_say(tk, site); }
        if (g_pq_inflight) break;   // the suspend's limit came first: no ticket is marked processed while a present is still on the GPU
        if (g_pq_done < tk) g_pq_done = tk;
        pthread_cond_broadcast(&g_pq_cv);
        stall_note_locked(n, last, now);
        int active = dm_focus_now() == 1; uint64_t since = dm_focus_in_since(), from = g_stall_t0 > since ? g_stall_t0 : since;
        uint64_t elapsed = now >= from ? now - from : 0;   // Focus can return after the earlier now sample, including while waiting for an in-flight present
        if (active && !g_stall_logged && elapsed >= STALL_NS) { g_stall_logged = 1;
            MLOG("display link silent for %.0f ms (active): dropping %llu queued frames not yet displayed, the game continues (stall #%llu; back to normal when the link returns)", (now - from) / 1e6, (unsigned long long)n, (unsigned long long)g_stall_n); }
        if (active && !g_rescue_mode && g_dm_present_link && elapsed >= LINK_RESCUE_NS) {
            g_rescue_mode = g_dm_present_link; g_rescue_n++; g_rescue_back_at = now + g_rescue_back_ns;
            MLOG("display link silent for %.0f ms while active: the present thread takes drawables itself (rescue #%llu), the link is tried again in %.0f s", (now - from) / 1e6, (unsigned long long)g_rescue_n, g_rescue_back_ns / 1e9);
            g_rescue_back_ns = g_rescue_back_ns < 30000000000ull ? g_rescue_back_ns * 2 : 60000000000ull;
        }
        if (active && !g_stall_red && elapsed >= STALL_RED_NS) { g_stall_red = 1; MLOG("[RED] display link silent for %.1f s while active; presenting relies entirely on fallback frame drops, the picture is frozen", elapsed / 1e9); }
    }
    if (noted) wn_out(WN_PTICKET);
    pthread_mutex_unlock(&g_pq_mu);
}
void mtl_present_wait(uint64_t tk) { present_wait_at(tk, "mtl_present_wait"); }
// Wait until all queued presents have been processed (used by mtl_finish = nvnQueueFinish etc.): goes through mtl_present_wait, so there is still a fallback when the display link stops (real device: the game called QueueFinish once while the display link was stopped,
// and this used to wait here without a timeout; nobody took the 3 queued frames and the game stalled; those two runs on Mac did not hit this call)
// present_flush_ok: the same wait, 0 when the suspend's limit (mtl_drain_by) ended it with the queue not processed
static int present_flush_ok(const char *site) {
    pthread_mutex_lock(&g_pq_mu); uint64_t h = g_pq_in; pthread_mutex_unlock(&g_pq_mu);
    present_wait_at(h, site);
    pthread_mutex_lock(&g_pq_mu); int ok = g_pq_done >= h || atomic_load(&g_present_discard); pthread_mutex_unlock(&g_pq_mu);
    return ok;
}
void mtl_present_flush(void) { present_flush_ok("mtl_present_flush (a queue finish, or the suspend)"); }
void mtl_stats(uint64_t *passes, uint64_t *draws) { *passes = g_stat_pass; *draws = g_stat_draw; cp_report(); }
void mtl_args_stats(uint64_t *enc, uint64_t *reuse, uint64_t *patch) { *enc = g_stat_args_enc; *reuse = g_stat_args_reuse; *patch = g_stat_args_patch; }
uint64_t mtl_args_xpass_stat(void) { return g_stat_args_xpass; }
uint64_t mtl_args_partial_stat(void) { return g_stat_args_partial; }   // of the patches, the partial ones (DM_NVN_ARGS_PARTIAL)   // of those reuses and patches, the ones only the cross-pass rule allowed (DM_NVN_ARGS_XPASS)
// DM_NVN_ARGS_STATS: the "[args-stats]" lines of a log window of nf frames (hle_nvn.c, after "argument blocks per frame"); nothing with the switch off. Per frame throughout
static const char *const g_ag_name[AG_N] = {"other bindings", "setup and lock", "textures and samplers", "pool and handle tables", "uniforms and sizes", "driver banks c0/c2", "push constants", "storage, images, raw memory", "arena, copy and bind", "texture lookups past the cached view (made, uploaded, checked)", "slot table checks (DM_NVN_BINDLESS, measuring)"};
static const char *const g_fx_name[FX_N] = {"tex_fit", "tex_float_fit", "fb_snapshot", "tbuf_as_2d", "tbuf_shadow", "border_twin", "dummy_tex", "dummy_samp"};
static void ast_put(char *b, size_t n, size_t *at, const char *fmt, ...) __attribute__((format(printf, 4, 5)));
static void ast_put(char *b, size_t n, size_t *at, const char *fmt, ...) {   // appends while there is room (a line stays under n bytes)
    if (*at >= n - 1) return;
    va_list ap; va_start(ap, fmt); int k = vsnprintf(b + *at, n - *at, fmt, ap); va_end(ap);
    if (k > 0) *at = *at + (size_t)k < n - 1 ? *at + (size_t)k : n - 1;
}
int mtl_args_stats_log(uint64_t frame, double nf) {
    if (!g_ast_on || nf <= 0) return 0;
    static uint64_t pfr[AW_N], ppa[2], ppx, psy[5], pfx[FX_N], pt[5], pn[5], ptg[AG_N], pdr, pdg, prb, pts, ppl, ppk[6], pps[2], ppt[PKC_N], ppn[PKC_N];
    uint64_t fr[AW_N], pa[2], px, sy[5], fxs[FX_N], t[5], n[5], tg[AG_N], dr, dg, rb, ts, pl, pk[6], ps[2], qt[PKC_N], qn[PKC_N];
    memcpy(pk, g_ast.part, sizeof pk); memcpy(ps, g_ast.pslot, sizeof ps); memcpy(qt, g_ast.pt, sizeof qt); memcpy(qn, g_ast.pn, sizeof qn);
    memcpy(fr, g_ast.fresh, sizeof fr); memcpy(pa, g_ast.patch, sizeof pa); px = g_ast.patch_x; memcpy(sy, g_ast.sync, sizeof sy); memcpy(fxs, g_ast.fx, sizeof fxs);
    memcpy(t, g_ast.t, sizeof t); memcpy(n, g_ast.n, sizeof n); memcpy(tg, g_ast.tg, sizeof tg); dr = g_ast.draws; dg = g_ast.draws_reg; rb = g_ast.regs_between;
    ts = atomic_load_explicit(&g_ast_reg_ts, memory_order_relaxed); pl = atomic_load_explicit(&g_ast_reg_pool, memory_order_relaxed);
    const double k = g_ast.ns_per_tick / 1e6 / nf;   // ticks → ms a frame
    char b[1600]; size_t at = 0; int lines = 0;
    // 1. full encodes by cause, most first
    double tot = 0, v[AW_N]; int ord[AW_N];
    for (int i = 0; i < AW_N; i++) { v[i] = (double)(fr[i] - pfr[i]) / nf; tot += v[i]; ord[i] = i; }
    for (int i = 1; i < AW_N; i++) for (int j = i; j > 0 && v[ord[j]] > v[ord[j - 1]]; j--) { int x = ord[j]; ord[j] = ord[j - 1]; ord[j - 1] = x; }
    ast_put(b, sizeof b, &at, "[args-stats] full encodes per frame up to frame %llu: %.1f; by cause (a binding change: the stage's last one before the encode):", (unsigned long long)frame, tot);
    for (int i = 0; i < AW_N && v[ord[i]] >= 0.05; i++) ast_put(b, sizeof b, &at, " %s %.1f", g_aw_name[ord[i]], v[ord[i]]);
    {   // ubo_unpatchable by the first binding kind that kept the shader off the uniform patch
        static const char *const rbn[] = {"none", "CBUF", "SAMP", "TEX", "IMG", "TBUF", "SBUFP", "SUPPORT", "C1", "DRV0", "DRV2", "SAMPT", "UBOP", "TEXU", "SAMPU", "SAMPI", "SBUFU", "TEXD", "SAMPD",
                                          "TEXA", "SAMPA", "GEOMETRY", "TEXP", "SAMPP", "TEXH", "SAMPH", "BORDER", "PUSH", "GMEM", "GMEML", "IMGU", "TBUFU", "CBSIZE", "SBUFQ"};
        _Static_assert(sizeof rbn / sizeof *rbn == NVN_RB_SBUFQ + 1, "binding kind names (nvn_refl.h NVN_RB_*)");
        static uint64_t puk[64]; int any = 0;
        for (int i = 0; i < 64; i++) { double x = (double)(g_ast.ubok[i] - puk[i]) / nf; if (x >= 0.05) { ast_put(b, sizeof b, &at, "%s %s %.1f", any ? "," : "; ubo_unpatchable by first kind off the patch list:", i < (int)(sizeof rbn / sizeof *rbn) ? rbn[i] : "?", x); any = 1; } puk[i] = g_ast.ubok[i]; }
    }
    MLOG("%s", b); lines++;
    // 2. patches, the binding syncs, registrations and draws
    double nd = (double)(dr - pdr), ndg = (double)(dg - pdg), nrb = (double)(rb - prb);
    at = 0;
    ast_put(b, sizeof b, &at, "[args-stats] per frame: patches %.1f (after a uniform binding %.1f, an inline update %.1f; across passes or programs %.1f); binding syncs %.1f (texture/sampler registration %.1f, memory pool %.1f, guest write %.1f, replaced texture %.1f: one sync may count under several); "
            "registrations: texture/sampler %.1f, memory pool %.1f; draws %.1f, with a texture/sampler registration since the previous draw %.1f (%.0f%%), registrations between draws %.2f a draw (%.2f a draw that had one)",
            (double)(pa[0] - ppa[0] + pa[1] - ppa[1]) / nf, (pa[0] - ppa[0]) / nf, (pa[1] - ppa[1]) / nf, (px - ppx) / nf, (sy[0] - psy[0]) / nf, (sy[1] - psy[1]) / nf, (sy[2] - psy[2]) / nf, (sy[3] - psy[3]) / nf, (sy[4] - psy[4]) / nf,
            (ts - pts) / nf, (pl - ppl) / nf, nd / nf, ndg / nf, nd > 0 ? 100.0 * ndg / nd : 0.0, nd > 0 ? nrb / nd : 0.0, ndg > 0 ? nrb / ndg : 0.0);
    MLOG("%s", b); lines++;
    // 3. encode_args_ time: by outcome, the full encodes by binding kind, their fix-ups
    double tf = (double)(t[0] - pt[0]), sg = 0;
    for (int i = 0; i < AG_N; i++) sg += (double)(tg[i] - ptg[i]);
    at = 0;
    ast_put(b, sizeof b, &at, "[args-stats] encode_args per frame (clock reads inside: absolute times run high, shares hold): full %.3f ms (%.0f calls, %.2f us each), patch %.3f ms (%.0f, %.2f us), reuse %.3f ms (%.0f, %.2f us), no bindings %.0f calls; full encodes by kind:",
            tf * k, (n[0] - pn[0]) / nf, n[0] > pn[0] ? tf * g_ast.ns_per_tick / 1e3 / (double)(n[0] - pn[0]) : 0.0,
            (t[1] - pt[1]) * k, (n[1] - pn[1]) / nf, n[1] > pn[1] ? (double)(t[1] - pt[1]) * g_ast.ns_per_tick / 1e3 / (double)(n[1] - pn[1]) : 0.0,
            (t[2] - pt[2]) * k, (n[2] - pn[2]) / nf, n[2] > pn[2] ? (double)(t[2] - pt[2]) * g_ast.ns_per_tick / 1e3 / (double)(n[2] - pn[2]) : 0.0, (n[3] - pn[3]) / nf);
    if (tf > 0) { ast_put(b, sizeof b, &at, " reuse checks %.3f ms %.0f%%", (tf - sg) * k, 100 * (tf - sg) / tf);
        for (int i = 0; i < AG_N; i++) { double x = (double)(tg[i] - ptg[i]); if (x > 0) ast_put(b, sizeof b, &at, ", %s %.3f ms %.0f%%", g_ag_name[i], x * k, 100 * x / tf); } }
    ast_put(b, sizeof b, &at, "; fix-ups:");
    for (int i = 0; i < FX_N; i++) ast_put(b, sizeof b, &at, " %s %.1f", g_fx_name[i], (fxs[i] - pfx[i]) / nf);
    MLOG("%s", b); lines++;
    // 3a. the texture lookups past the cached view (AG_TEXSLOW, tex_by_id_ptr): how many, by how they ended (TS_*), how new views were had, which binding kind asked; tex_fit's views
    {
        static const char *const tsn[TS_N] = {"current view (a caller without the fast test)", "packaged, its pages not written since (page check)", "registration epoch moved, texture kept",
                                              "packaged, pages written, texture kept", "packaged with no kept range, texture kept (serial lookup)", "texture replaced, view made again",
                                              "first lookup since its registration", "empty slot or no texture"};
        static const char *const tmn[TSM_N] = {"the texture as is", "from the view cache", "Metal views made"}, *const tfn[TF_N] = {"hits", "first", "for another view of the ID", "for another type", "second view hits"};
        static __typeof__(g_tsl) p; __typeof__(g_tsl) c = g_tsl, d;
        uint64_t *dp = (uint64_t *)(void *)&d; const uint64_t *cp = (const uint64_t *)(const void *)&c, *pp = (const uint64_t *)(const void *)&p;
        for (size_t i = 0; i < sizeof d / 8; i++) dp[i] = cp[i] - pp[i];
        p = c;
        static uint64_t ptsg[AG_N], pag; uint64_t tsg[AG_N]; memcpy(tsg, g_ast.tsg, sizeof tsg);
        double nn = 0, tt = 0, inf = 0; for (int i = 0; i < TS_N; i++) { nn += (double)d.n[i]; tt += (double)d.t[i]; }
        for (int i = 0; i < AG_N; i++) inf += (double)(tsg[i] - ptsg[i]);
        const double us = g_ast.ns_per_tick / 1e3;
        at = 0;
        ast_put(b, sizeof b, &at, "[args-stats] texture lookups past the cached view per frame: %.1f, %.3f ms (%.2f us each, two clock reads of %.0f ns each included); by outcome:", nn / nf, tt * k, nn > 0 ? tt * us / nn : 0.0, g_ast.timer_ns);
        for (int i = 0; i < TS_N; i++) if (d.n[i]) ast_put(b, sizeof b, &at, " %s %.1f (%.2f us each),", tsn[i], d.n[i] / nf, (double)d.t[i] * us / (double)d.n[i]);
        ast_put(b, sizeof b, &at, " new views:"); for (int i = 0; i < TSM_N; i++) ast_put(b, sizeof b, &at, " %s %.1f%s", tmn[i], d.mn[i] / nf, i < TSM_N - 1 ? "," : ";");
        ast_put(b, sizeof b, &at, " with a texture uploaded inside %.1f, %.3f ms; who asked: in full encodes %.3f ms (", d.up / nf, d.upt * k, inf * k);
        int any = 0; for (int i = 0; i < AG_N; i++) { double x = (double)(tsg[i] - ptsg[i]); if (x > 0) { ast_put(b, sizeof b, &at, "%s%s %.3f", any ? ", " : "", g_ag_name[i], x * k); any = 1; } }
        ast_put(b, sizeof b, &at, "), elsewhere (patches, pool walks, other threads) %.3f ms; tex_fit views per frame:", tt > inf ? (tt - inf) * k : 0.0);
        for (int i = 0; i < TF_N; i++) ast_put(b, sizeof b, &at, "%s %s %.1f", i ? "," : "", tfn[i], d.fn[i] / nf);
        double fm = (double)(d.fn[TF_NEW] + d.fn[TF_VIEW] + d.fn[TF_TYPE]), ftm = (double)(d.ft[TF_NEW] + d.ft[TF_VIEW] + d.ft[TF_TYPE]);
        ast_put(b, sizeof b, &at, "; made %.1f, %.3f ms (%.2f us each); type-view generation moves %.1f", fm / nf, ftm * k, fm > 0 ? ftm * us / fm : 0.0, (double)(g_alt_gen - pag) / nf);
        memcpy(ptsg, tsg, sizeof ptsg); pag = g_alt_gen;
        MLOG("%s", b); lines++;
    }
    // 3b. partial patches (DM_NVN_ARGS_PARTIAL): how many, by kind written, their time by class, and the texture / sampler bindings they wrote against those they kept
    if (g_args_partial > 0) {
        static const char *const kn[6] = {"texture", "sampler", "storage", "base instance", "uniform", "pool tables"};
        double np = (double)(n[4] - pn[4]), tp = (double)(t[4] - pt[4]);
        at = 0;
        ast_put(b, sizeof b, &at, "[args-stats] partial patches per frame: %.1f, %.3f ms (%.2f us each); with entries written again by kind:", np / nf, tp * k, np > 0 ? tp * g_ast.ns_per_tick / 1e3 / np : 0.0);
        for (int i = 0; i < 6; i++) ast_put(b, sizeof b, &at, " %s %.1f", kn[i], (pk[i] - ppk[i]) / nf);
        ast_put(b, sizeof b, &at, "; by class:");
        for (int i = 0; i < PKC_N; i++) { double c = (double)(qn[i] - ppn[i]), x = (double)(qt[i] - ppt[i]); ast_put(b, sizeof b, &at, " %s %.1f, %.3f ms (%.2f us each);", g_pkc_name[i], c / nf, x * k, c > 0 ? x * g_ast.ns_per_tick / 1e3 / c : 0.0); }
        ast_put(b, sizeof b, &at, " texture/sampler bindings written %.1f, kept %.1f", (ps[0] - pps[0]) / nf, (ps[1] - pps[1]) / nf);
        MLOG("%s", b); lines++;
    }
    // 3c. the encode levers: pool and handle table lookups by how they ended (DM_NVN_POOL_MEMO), and their time
    {
        static const char *const pwn[PW_N] = {"memo", "first check", "patch kept", "patched", "standing", "walk"}, *const htn[HT_N] = {"this pass", "read again, same", "same entries", "built"};
        static uint64_t ppw[PW_N], ppwt[PW_N], pht[HT_N], phtt[HT_N];
        at = 0; double npw = 0, tpw = 0, nht = 0, tht = 0;
        for (int i = 0; i < PW_N; i++) { npw += (double)(g_ast.pwn[i] - ppw[i]); tpw += (double)(g_ast.pwt[i] - ppwt[i]); }
        for (int i = 0; i < HT_N; i++) { nht += (double)(g_ast.htn[i] - pht[i]); tht += (double)(g_ast.htt[i] - phtt[i]); }
        ast_put(b, sizeof b, &at, "[args-stats] levers per frame: pool table lookups %.1f, %.3f ms (memo %s):", npw / nf, tpw * k, g_pool_memo > 0 ? "on" : "off");
        for (int i = 0; i < PW_N; i++) { double c = (double)(g_ast.pwn[i] - ppw[i]), x = (double)(g_ast.pwt[i] - ppwt[i]); ast_put(b, sizeof b, &at, " %s %.1f (%.2f us each)%s", pwn[i], c / nf, c > 0 ? x * g_ast.ns_per_tick / 1e3 / c : 0.0, i < PW_N - 1 ? "," : ";"); }
        ast_put(b, sizeof b, &at, " handle table lookups %.1f, %.3f ms:", nht / nf, tht * k);
        for (int i = 0; i < HT_N; i++) { double c = (double)(g_ast.htn[i] - pht[i]), x = (double)(g_ast.htt[i] - phtt[i]); ast_put(b, sizeof b, &at, " %s %.1f (%.2f us each)%s", htn[i], c / nf, c > 0 ? x * g_ast.ns_per_tick / 1e3 / c : 0.0, i < HT_N - 1 ? "," : ""); }
        {   // the patch path's split (g_ppw): where the 'pool and handle tables' time of the encode split goes, and the texture lookups it leaves to AG_TEXSLOW
            static uint64_t ppp[PP_N]; uint64_t d[PP_N]; for (int i = 0; i < PP_N; i++) { d[i] = g_ppw[i] - ppp[i]; ppp[i] = g_ppw[i]; }
            ast_put(b, sizeof b, &at, "; pool patch paths (entry order %s) %.1f (%.0f IDs each): collecting %.3f ms, resolving %.3f ms, texture lookups past the cached view %.3f ms, table copies %.3f ms; read-mark scans %.3f ms; whole builds %.3f ms",
                    g_pool_entry > 0 ? "on" : "off", d[PP_PATHS] / nf, d[PP_PATHS] ? (double)d[PP_IDS] / (double)d[PP_PATHS] : 0.0, d[PP_COLLECT] * k, d[PP_RESOLVE] * k, d[PP_TEXSLOW] * k, d[PP_TAKE] * k, d[PP_SCAN] * k, d[PP_BUILD] * k);
        }
        static uint64_t pdb[2][DB_N];   // driver banks (DM_NVN_ARGS_DRV): taken as they were, copied with words written again, made whole
        ast_put(b, sizeof b, &at, "; driver banks (shared %s):", g_args_drv > 0 ? "on" : "off");
        for (int c = 0; c < 2; c++) ast_put(b, sizeof b, &at, " c%d reused %.1f, patched %.1f, made %.1f%s", 2 * c, (g_stat_drv[c][DB_HIT] - pdb[c][DB_HIT]) / nf, (g_stat_drv[c][DB_DERIVED] - pdb[c][DB_DERIVED]) / nf, (g_stat_drv[c][DB_FULL] - pdb[c][DB_FULL]) / nf, c ? "" : ";");
        memcpy(pdb, g_stat_drv, sizeof pdb);
        static uint64_t prk[5];   // registration syncs (DM_NVN_ARGS_REGCHK): by ID, every block; blocks found current, stale, not checkable
        ast_put(b, sizeof b, &at, "; registration syncs (by ID %s): by ID %.1f, every block %.1f; blocks checked current %.1f, stale %.1f, kinds not checkable %.1f", g_args_regchk > 0 ? "on" : "off",
                (g_stat_rck[0] - prk[0]) / nf, (g_stat_rck[1] - prk[1]) / nf, (g_stat_rck[2] - prk[2]) / nf, (g_stat_rck[3] - prk[3]) / nf, (g_stat_rck[4] - prk[4]) / nf);
        memcpy(prk, g_stat_rck, sizeof prk);
        memcpy(ppw, g_ast.pwn, sizeof ppw); memcpy(ppwt, g_ast.pwt, sizeof ppwt); memcpy(pht, g_ast.htn, sizeof pht); memcpy(phtt, g_ast.htt, sizeof phtt);
        MLOG("%s", b); lines++;
    }
    // 3d. slot tables (DM_NVN_BINDLESS=1, stage 1): what the tables would replace of the texture / sampler work, and their own cost
    if (g_bl_on) {
        static __typeof__(g_bls) pb; __typeof__(g_bls) c = g_bls, d;
        uint64_t *dp = (uint64_t *)(void *)&d; const uint64_t *cp = (const uint64_t *)(const void *)&c, *pp = (const uint64_t *)(const void *)&pb;
        for (size_t i = 0; i < sizeof d / 8; i++) dp[i] = cp[i] - pp[i];
        pb = c;
        double ff = d.slot_full + d.other_full > 0 ? (double)((int64_t)d.slot_full - (int64_t)d.tab_full) / (double)(d.slot_full + d.other_full) : 0, xt = (double)(tg[AG_TEX] - ptg[AG_TEX]) * k;
        at = 0;
        ast_put(b, sizeof b, &at, "[args-stats] slot tables (DM_NVN_BINDLESS=1, stage 1: built and checked, not read) per frame: fragment encodes that resolved textures or samplers %.1f, the table version taken without a look in %.1f (%.0f%%); "
                "converted bindings the slot path resolved %.1f (in full encodes %.1f), table entries that needed resolving %.1f (%.1f): the tables would replace %.0f%% (in full encodes %.0f%%, of their texture and sampler bindings %.0f%%, about %.3f ms of %.3f ms); "
                "slot-bound texture/sampler bindings of the same encodes %.1f; feedback snapshots (a draw's own version) %.1f; versions built %.1f, %.1f KB; new epochs by what moved: registration %.2f, guest write %.2f, storage %.2f, view %.2f, submission %.2f; the checks' own time %.3f ms; mismatches %llu (in the run %llu, must be 0)",
                d.enc / nf, d.cur / nf, d.enc ? 100.0 * d.cur / d.enc : 0.0, d.slot / nf, d.slot_full / nf, d.tab / nf, d.tab_full / nf,
                d.slot ? 100.0 * ((double)d.slot - (double)d.tab) / d.slot : 0.0, d.slot_full ? 100.0 * ((double)d.slot_full - (double)d.tab_full) / d.slot_full : 0.0, 100 * ff, xt * ff, xt,
                d.other / nf, d.dspec / nf, d.builds / nf, d.bytes / nf / 1024, d.ep[BLE_REG] / nf, d.ep[BLE_DIRTY] / nf, d.ep[BLE_SER] / nf, d.ep[BLE_ALT] / nf, d.ep[BLE_SUB] / nf,
                (double)d.ticks * g_ast.ns_per_tick / 1e6 / nf, (unsigned long long)d.mism, (unsigned long long)c.mism);
        MLOG("%s", b); lines++;
    }
    // 4. the shaders with the most full encodes in the window (the table's half written since the last line; then cleared)
    int w = atomic_fetch_xor_explicit(&g_ast.kw, 1, memory_order_relaxed) & 1; ast_key_t *tab = g_ast.keys[w];
    if (tab) {
        int top[AK_TOP], nt = 0, used = 0;
        for (int i = 0; i < AK_N; i++) { if (!tab[i].sh || !tab[i].fresh) continue; used++;
            int j; if (nt < AK_TOP) j = nt++; else if (tab[i].fresh > tab[top[AK_TOP - 1]].fresh) j = AK_TOP - 1; else continue;
            top[j] = i; for (; j > 0 && tab[top[j]].fresh > tab[top[j - 1]].fresh; j--) { int x = top[j]; top[j] = top[j - 1]; top[j - 1] = x; } }
        for (int part = 0; part * 5 < nt; part++) {
            at = 0;
            ast_put(b, sizeof b, &at, "[args-stats] shaders by full encodes per frame, %d-%d of %d (%u had no room): key stage full/frame tables, top cause share, fix-ups /frame;", part * 5 + 1, nt < part * 5 + 5 ? nt : part * 5 + 5, used, g_ast.kmiss[w]);
            for (int r = part * 5; r < nt && r < part * 5 + 5; r++) { const ast_key_t *e = &tab[top[r]]; int c = 0;
                for (int i = 1; i < AW_N; i++) if (e->why[i] > e->why[c]) c = i;
                ast_put(b, sizeof b, &at, " %s st%d %.1f %s t%us%u%s, %s %.0f%%", e->key, e->stage, e->fresh / nf, e->pool ? "pool" : e->htab ? "htab" : "slots", e->ntex, e->nsamp, e->drv2 ? " c2" : "", g_aw_name[c], e->fresh ? 100.0 * e->why[c] / e->fresh : 0.0);
                for (int i = 0; i < FX_N; i++) if (e->fx[i]) ast_put(b, sizeof b, &at, " %s %.1f", g_fx_name[i], e->fx[i] / nf);
                ast_put(b, sizeof b, &at, ";"); }
            MLOG("%s", b); lines++;
        }
        memset(tab, 0, AK_N * sizeof *tab); g_ast.kmiss[w] = 0;
    }
    memcpy(pfr, fr, sizeof pfr); memcpy(ppa, pa, sizeof ppa); ppx = px; memcpy(psy, sy, sizeof psy); memcpy(pfx, fxs, sizeof pfx); memcpy(pt, t, sizeof pt); memcpy(pn, n, sizeof pn); memcpy(ptg, tg, sizeof ptg);
    memcpy(ppk, pk, sizeof ppk); memcpy(pps, ps, sizeof pps); memcpy(ppt, qt, sizeof ppt); memcpy(ppn, qn, sizeof ppn);
    pdr = dr; pdg = dg; prb = rb; pts = ts; ppl = pl;
    return lines;
}
void mtl_vbuf_stats(uint64_t *resolve, uint64_t *reuse, uint64_t *set, uint64_t *skip, uint64_t *copies, uint64_t *copy_bytes) {
    *resolve = g_vbuf_resolve; *reuse = g_vbuf_reuse; *set = g_vbuf_set; *skip = g_vbuf_skip; *copies = g_vbuf_copies; *copy_bytes = g_vbuf_copy_bytes;
}
void mtl_ft_stats(uint64_t *set, uint64_t *skip) { *set = g_ft_set; *skip = g_ft_skip; }
void mtl_use_stats(uint64_t *call, uint64_t *skip) { *call = 0; *skip = 0; }
void mtl_bw(uint64_t *load, uint64_t *store, uint64_t *full) { *load = g_bw_load; *store = g_bw_store; *full = g_pass_full_rw; }
uint64_t mtl_udc_saved_bytes(void) { return g_udc_saved_bytes; }
int mtl_has_window(void) { return front_metal_layer() != NULL; }
int mtl_link_active(void) { return link_on(); }
int mtl_link_stalled(void) { return __atomic_load_n(&g_stall_t0, __ATOMIC_RELAXED) != 0; }   // the display link has gone silent and mtl_present_wait drops frames (see STALL_NS) until it calls back
void mtl_link_pause(int on) { CAMetalDisplayLink *l = g_link; if (l) l.paused = on != 0; }   // For testing (DM_TEST_BG): imitates the system stopping the display-link callback in the background
int mtl_link_wait_tick(int vsyncs, uint64_t timeout_ns) {
    if (!mtl_link_active()) return 0;
    // Wait for the display link only when running faster than the display: if a display-link tick has already passed since the previous frame started work (this frame is already behind), start immediately instead of waiting in vain for the next display-link tick --
    // otherwise when the frame time is slightly more than one display-link period it would "miss the tick -> wait another whole tick", locking the frame rate straight to half (measured on Mac under windowed load: runs of dropped frames)
    // How many display-link ticks one frame takes: the game's present interval (vsyncs, 60 Hz) times 1 with a 60 Hz display link, times 2 with a 120 Hz one, halved and rounded up at 30 Hz.
    // A frame presented with interval N blocks the game for N vsyncs on the Switch, as the display callback holds it N ticks: games that scale their time step by the interval (BotW's VFR: interval / 2)
    // ran at double speed while they produced interval-2 frames every 60 Hz tick (iPhone log: Link sprinting with B, the interval flapping 1 ↔ 2)
    if (vsyncs < 1) vsyncs = 1;
    return mtl_link_wait_ticks(g_link_mode == 3 ? (vsyncs + 1) / 2 : vsyncs * (g_link_mode == 2 ? 2 : 1), timeout_ns);
}
// The display link's rate: 120 Hz (DM_PRESENT_LINK=2), 60, or 30 in power-saving mode
void mtl_link_mode_set(int mode) { pthread_mutex_lock(&g_pq_mu); g_dm_present_link = mode; pthread_mutex_unlock(&g_pq_mu); }   // 120 fps follows the screen: link_sync applies it
int mtl_link_rate(void) { return g_link_mode == 3 ? 30 : g_link_mode == 2 ? 120 : 60; }
// The same wait counted in the display link's own ticks: one per frame for a frame rate as high as the link's (present_interval display at DM_PRESENT_HZ=120 on a 120 Hz link)
int mtl_link_wait_ticks(int ticks, uint64_t timeout_ns) {
    if (!mtl_link_active()) return 0;
    static uint64_t started_tick;   // Display-link tick number when the previous frame started work (only the game's present thread calls this function)
    const uint64_t step = ticks < 1 ? 1 : (uint64_t)ticks;
    pthread_mutex_lock(&g_link_mu);
    if (g_link_tick_n >= started_tick + step) { started_tick = g_link_tick_n; pthread_mutex_unlock(&g_link_mu); return 1; }
    pthread_mutex_unlock(&g_link_mu); nvn_acquire_block(); pthread_mutex_lock(&g_link_mu);   // it blocks: the acquiring guest thread gives its core away (hle_nvn.c; not under this lock, which the link's callback takes)
    struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ns / 1000000000ull; ts.tv_nsec += timeout_ns % 1000000000ull;
    if (ts.tv_nsec >= 1000000000L) { ts.tv_sec++; ts.tv_nsec -= 1000000000L; }
    while (g_link_tick_n < started_tick + step) if (pthread_cond_timedwait(&g_link_cv, &g_link_mu, &ts) == ETIMEDOUT) { pthread_mutex_unlock(&g_link_mu); return 0; }
    started_tick = g_link_tick_n;
    pthread_mutex_unlock(&g_link_mu); return 1;
}

// The display's vsync for vi::GetDisplayVsyncEvent (hle_sdk16.c): returns 1 at the first display-link tick of the next 60 Hz vsync (120 Hz at 120 fps, nvn_vsync_hz) after *seen (the tick count it last returned, updated),
// 0 when the link does not run, runs at 30 Hz (power saving: the 60 Hz event cannot come from it) or gives no tick within the timeout; the caller then keeps its own clock
int nvn_vsync_hz(void);   // hle_nvn.c: 120 while 120 fps holds one tick of 1/120 s, else 60
int mtl_link_wait_vsync(uint64_t *seen, uint64_t timeout_ns) {
    if (!mtl_link_active() || g_link_mode == 3) return 0;
    const uint64_t step = g_link_mode == 2 && nvn_vsync_hz() != 120 ? 2 : 1;   // a 120 Hz link: every tick at 120 fps, every other one otherwise
    pthread_mutex_lock(&g_link_mu);
    if (*seen > g_link_tick_n || g_link_tick_n > *seen + 4 * step) *seen = g_link_tick_n;   // first call, or far behind (a stall): from the current tick on, no burst
    struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ns / 1000000000ull; ts.tv_nsec += timeout_ns % 1000000000ull;
    if (ts.tv_nsec >= 1000000000L) { ts.tv_sec++; ts.tv_nsec -= 1000000000L; }
    while (g_link_tick_n < *seen + step) if (pthread_cond_timedwait(&g_link_cv, &g_link_mu, &ts) == ETIMEDOUT) { pthread_mutex_unlock(&g_link_mu); return 0; }
    *seen += step;
    pthread_mutex_unlock(&g_link_mu); return 1;
}

static id<CAMetalDrawable> g_prefetched_drawable; // Used for compositing straight onto the drawable
id<CAMetalDrawable> mtl_present_take_prefetched(void) { return g_prefetched_drawable; }

// The upload slots' busy flags (back 0) or the batch each completed through (back 1), as "a b c" over g_up_nslots: atomics only (the dumps below take no lock)
static void up_slots_text(char *b, size_t n, int back) {
    size_t o = 0; b[0] = 0;
    for (unsigned i = 0; i < g_up_nslots && o < n; i++) o += (size_t)snprintf(b + o, n - o, "%s%u", i ? " " : "", back ? atomic_load(&g_up_slot_back[i]) : (unsigned)atomic_load(&g_up_alloc_busy[i]));
}
// Called by the watchdog (no progress): writes the state of all blocking wait points on the graphics side to the log -- who is waiting for whom is visible at a glance (after switching to the Metal 4 submit model there was once a case of "ran to 900 frames then stopped, no failure line")
void mtl_wait_state_dump(void) {
    char ub[64]; up_slots_text(ub, sizeof ub, 0);
    MLOG("wait points: main fence submitted %llu / completed %llu; main allocator fences [%llu %llu %llu]; uploads pending %d, allocators busy [%s], seq %u, unflushed batch %d; present queue in %llu / done %llu; main command buffer encoding %d, submit thread set %d",
         (unsigned long long)g_fence, (unsigned long long)g_done, (unsigned long long)g_alloc_fence[0], (unsigned long long)g_alloc_fence[1], (unsigned long long)g_alloc_fence[2],
         atomic_load(&g_up_pending), ub, g_up_seq, g_up_cb != nil,
         (unsigned long long)g_pq_in, (unsigned long long)g_pq_done, g_cb != nil, atomic_load(&g_sub_thread_set));
}
// The freeze detector's dump (dm/host/stall.c, DM_STALL_LOG; on by default, logging only), after its "[RED] stall: no present for N s" line: what each place that can hold presents
// back is doing (the notes at the top of this file). It runs on the detector's thread while the game may be frozen in any path it reads, so it takes no lock at all: atomics and the
// notes, and plain counters read as they stand (__atomic_load_n: a value a moment stale misleads one line, where a lock taken here could stop the dump in the freeze it describes).
// mtl_wait_state_dump's line, which reads the same way, ends it
static void stall_lock_text(char *out, size_t n, lock_note *ln, uint64_t now) {
    uint32_t th = atomic_load_explicit(&ln->th, memory_order_acquire); const char *site = atomic_load_explicit(&ln->site, memory_order_relaxed); uint64_t at = atomic_load_explicit(&ln->at, memory_order_relaxed);
    if (!th) snprintf(out, n, "free");
    else snprintf(out, n, "held by host thread %#x from %s for %.1f s", th, site ? site : "?", at && now >= at ? mach_s(now - at) : 0.0);
}
void mtl_stall_dump(void) {
    uint64_t now = mach_absolute_time();
    uint64_t sub = atomic_load(&g_fence), done = atomic_load(&g_done);
    const char *fw = atomic_load_explicit(&g_fbq_what, memory_order_acquire); uint64_t fin = atomic_load(&g_fbq_in), fout = atomic_load(&g_fbq_out);
    char fb[200];
    if (fw) snprintf(fb, sizeof fb, "running the %s handler for %.1f s", fw, fin && now >= fin ? mach_s(now - fin) : 0.0);
    else if (fout) snprintf(fb, sizeof fb, "idle, its last handler ended %.1f s ago", now >= fout ? mach_s(now - fout) : 0.0);
    else snprintf(fb, sizeof fb, "idle, no handler has run yet");
    MLOG("stall dump: fences submitted %llu / completed %llu (%llu behind); feedback queue %s, %llu handlers so far; main command buffers committed and not reported back %d",
         (unsigned long long)sub, (unsigned long long)done, (unsigned long long)(sub > done ? sub - done : 0), fb, (unsigned long long)atomic_load(&g_fbq_n), atomic_load(&g_seg_inflight));
    char lc[200], lr[200]; stall_lock_text(lc, sizeof lc, &g_res_commit_note, now); stall_lock_text(lr, sizeof lr, &g_res_note, now);
    MLOG("stall dump: residency commit lock (g_res_commit_mu) %s; residency lock (g_res_mu) %s", lc, lr);
    { char rk[300]; if (mtl_res_commit_stuck(0, rk, sizeof rk)) MLOG("stall dump: %s", rk); }   // the commit under way, when the lock's holder is one (res_kcommit_in)
    char rw[96]; rcw_text(rw, sizeof rw, now);   // a batch that retires staging is pending until the worker has committed its removal (res_commit_async)
    char ub[64], uk[128]; up_slots_text(ub, sizeof ub, 0); up_slots_text(uk, sizeof uk, 1);
    MLOG("stall dump: upload batches pending %d, last begun seq %u, a batch open %d; slots busy [%s], completed through seq [%s]; residency commit worker %s",
         atomic_load(&g_up_pending), __atomic_load_n(&g_up_seq, __ATOMIC_RELAXED), g_up_cb != nil,
         ub, uk, rw);
    if (__atomic_load_n(&g_rb_started, __ATOMIC_RELAXED)) {
        uint32_t st = atomic_load(&g_rx_state); uint64_t since = atomic_load(&g_rx_since);
        MLOG("stall dump: encode thread %s for %.1f s; blocks queued %d, one in hand %d, asleep %d; drains %llu (%llu blocked); uniform copies queued %llu / made %llu, waiters asleep %u, copy thread asleep %u",
             st < RX_N ? rx_name[st] : "?", since && now >= since ? mach_s(now - since) : 0.0, __atomic_load_n(&g_rb_head, __ATOMIC_RELAXED) != NULL,
             __atomic_load_n(&g_rb_busy, __ATOMIC_RELAXED), __atomic_load_n(&g_rb_sleeping, __ATOMIC_RELAXED), (unsigned long long)atomic_load(&g_drains), (unsigned long long)atomic_load(&g_drains_blocked),
             (unsigned long long)atomic_load(&g_ubc_head), (unsigned long long)atomic_load(&g_ubc_done), atomic_load(&g_ubc_waiting), atomic_load(&g_ubc_sleeping));
    } else MLOG("stall dump: no encode thread (Metal encoding on the submit thread)");
    uint64_t tick = __atomic_load_n(&g_link_tick_ns, __ATOMIC_RELAXED), tnow = now_ns(); char tk[64];
    if (tick && tnow >= tick) snprintf(tk, sizeof tk, "%.1f s ago", (tnow - tick) / 1e9); else snprintf(tk, sizeof tk, "none yet");
    MLOG("stall dump: present queue enqueued %llu / taken %llu / done %llu, on the GPU %d; allocators done [%llu %llu %llu] of [%llu %llu %llu]; presents %llu; display link %d, owns the layer %d, rescue %d, last tick %s",
         (unsigned long long)__atomic_load_n(&g_pq_in, __ATOMIC_RELAXED), (unsigned long long)__atomic_load_n(&g_pq_read, __ATOMIC_RELAXED), (unsigned long long)__atomic_load_n(&g_pq_done, __ATOMIC_RELAXED),
         __atomic_load_n(&g_pq_inflight, __ATOMIC_RELAXED),
         (unsigned long long)__atomic_load_n(&g_present_alloc_done[0], __ATOMIC_RELAXED), (unsigned long long)__atomic_load_n(&g_present_alloc_done[1], __ATOMIC_RELAXED), (unsigned long long)__atomic_load_n(&g_present_alloc_done[2], __ATOMIC_RELAXED),
         (unsigned long long)__atomic_load_n(&g_present_alloc_fence[0], __ATOMIC_RELAXED), (unsigned long long)__atomic_load_n(&g_present_alloc_fence[1], __ATOMIC_RELAXED), (unsigned long long)__atomic_load_n(&g_present_alloc_fence[2], __ATOMIC_RELAXED),
         (unsigned long long)__atomic_load_n(&g_present_n, __ATOMIC_RELAXED), g_dm_present_link, __atomic_load_n(&g_link_owns_layer, __ATOMIC_RELAXED), atomic_load(&g_rescue_mode),
         tk);
    char w[1024]; size_t o = 0;
    for (int k = 0; k < WN_N && o < sizeof w - 160; k++) { int n = atomic_load(&g_wn[k].n); if (n <= 0) continue; uint64_t at = atomic_load(&g_wn[k].at);
        o += (size_t)snprintf(w + o, sizeof w - o, " %s: %d thread%s, the latest for %llu, %.1f s;", wn_name[k], n, n == 1 ? "" : "s", (unsigned long long)atomic_load(&g_wn[k].what), at && now >= at ? mach_s(now - at) : 0.0); }
    MLOG("stall dump: blocked waits in progress:%s", o ? w : " none");
    mtl_wait_state_dump();
}
// ---------- The GPU hang watchdog (DM_GPU_LOST_S; the idea is d2r-metal's, PowerBeef/d2r-metal, MIT) ----------
// The iPhone freeze the owner sees: the picture stops, the app has to be closed from the app switcher, and the cloud save of what the game had saved goes with it (the send waits
// for the background, which a swipe in the app switcher kills). With work waiting and no GPU work finished for DM_GPU_LOST_S seconds (default 10, 0 = off), gpu_watch takes the
// GPU as lost (GL_HANG): nothing more is sent to it (Q4_COMMIT_TIMED and the present's own commits skip theirs), every CPU wait on its completion gives way (mtl_wait_at, once_wait,
// the waits that end at the suspend's limit through drain_over, the present waits, the snapshot copies, the indirect-count wait; gpu_gone_release raises the GPU events and wakes
// the condition waits), and the front end saves and quits (front_gpu_lost: the iPhone sends the cloud save, writes the pipeline archive and ends the process through the graceful
// exit, and its next launch tells the player). 2 s into such a stall (half the limit, under 4 s) the stall report says what the GPU was on: the fences, the first fence not back and
// which of its command buffers came back (their segment timestamps), the game shaders of the stuck command buffer, then the freeze detector's dump; the same again when the GPU is
// taken as lost.
// What counts as work waiting: a fence submitted and not complete, an upload batch pending, a present on the GPU, a main command buffer not reported back. What counts as GPU work
// finished: any commit feedback handler that ran to its end (g_fbq_n), so a feedback handler that never returns counts as a stall too. The time is counted in the timer's ticks
// (GPW_TICK_MS), not read from a clock: a process iOS suspended, or one stopped in a debugger, counts no time, and its first tick after it counts one. The timer is a dispatch
// source with a quarter of its interval as leeway (the system may coalesce its wakes); off with DM_GPU_LOST_S=0, when nothing is made
enum { GPW_TICK_MS = 500 };
static double gpw_seconds(void) {
    static double v = -1;
    if (v < 0) { const char *e = getenv("DM_GPU_LOST_S"); double d = e && *e ? strtod(e, NULL) : 10; v = d > 0 ? d : 0; }
    return v;
}
static int gpw_waiting(void) {
    return atomic_load(&g_done) < atomic_load(&g_fence) || atomic_load(&g_up_pending) > 0 || __atomic_load_n(&g_pq_inflight, __ATOMIC_RELAXED) > 0 || atomic_load(&g_seg_inflight) > 0;
}
// The command buffers of fence f that came back, from its segment clock (seg_ts: each cut's command buffer stamps its GPU end in its feedback). Only tried under g_post_mu: never
// waits on a lock a stuck thread may hold
static void gpw_segments(uint64_t f, char *out, size_t n) {
    snprintf(out, n, "its command buffers' timestamps not known");
    if (pthread_mutex_trylock(&g_post_mu)) return;
    post_rec *r = &g_postr[f % POST_RING];
    if (atomic_load(&r->fence) == f && r->sc) {
        const seg_clk *c = r->sc; uint32_t back = 0, last = UINT32_MAX;
        for (uint32_t i = 0; i < c->ncm; i++) if (atomic_load(&c->t[c->cm[i]][1])) { back++; last = c->cm[i]; }
        if (last == UINT32_MAX) snprintf(out, n, "none of its %u command buffers came back (the GPU is on its first)", c->ncm + 1);
        else snprintf(out, n, "%u of its %u command buffers came back, through segment %u (the GPU is on the next)", back, c->ncm + 1, last);
    } else if (atomic_load(&r->fence) == f) snprintf(out, n, "one command buffer, not back");
    pthread_mutex_unlock(&g_post_mu);
}
static void gpw_report(double s, const char *when) {
    uint64_t done = atomic_load(&g_done), sub = atomic_load(&g_fence);
    const char *fw = atomic_load_explicit(&g_fbq_what, memory_order_acquire);
    char seg[160] = "nothing in flight"; if (sub > done) gpw_segments(done + 1, seg, sizeof seg);
    MLOG("[RED] GPU stall (%s): no GPU work has finished for %.1f s with work waiting: fences completed %llu of %llu submitted; fence %llu: %s; upload batches pending %d, presents on the GPU %d, "
         "main command buffers not back %d; feedback handler %s%s", when, s, (unsigned long long)done, (unsigned long long)sub, (unsigned long long)(done + 1), seg, atomic_load(&g_up_pending),
         __atomic_load_n(&g_pq_inflight, __ATOMIC_RELAXED), atomic_load(&g_seg_inflight), fw ? "running: " : "none running", fw ? fw : "");
    cbs_fly_report(done + 1);
    mtl_stall_dump();
}
// Everything that waits for the GPU's completion is let go: the GPU events raised from the CPU (far past any fence, so a wait on a fence submitted after this passes too), and
// the condition waits woken under their locks after g_gpu_lost is set (their loops read gpu_gone)
static void gpu_gone_release(void) {
    os_unfair_lock_lock(&g_ev_lk);   // fence_ev_raise's: neither lowers g_ev under the other
    uint64_t far = atomic_load(&g_fence) + (1ull << 40);
    if (g_ev && g_ev.signaledValue < far) g_ev.signaledValue = far;
    if (g_snap_ev && g_snap_ev.signaledValue < g_snap_v + (1ull << 40)) g_snap_ev.signaledValue = g_snap_v + (1ull << 40);
    if (g_mdi_ev && g_mdi_ev.signaledValue < g_mdi_v + (1ull << 40)) g_mdi_ev.signaledValue = g_mdi_v + (1ull << 40);
    os_unfair_lock_unlock(&g_ev_lk);
    pthread_mutex_lock(&g_mu); pthread_cond_broadcast(&g_cv); pthread_mutex_unlock(&g_mu);
    pthread_mutex_lock(&g_pq_mu); pthread_cond_broadcast(&g_pq_cv); pthread_mutex_unlock(&g_pq_mu);
    up_wake();
    pthread_mutex_lock(&g_note_mu); pthread_cond_broadcast(&g_note_cv); pthread_mutex_unlock(&g_note_mu);
}
// Takes the GPU as lost (once a run; a revoked access first keeps its own path)
static void gpu_lost_take(int why, const char *what) {
    int none = GL_NONE;
    if (!atomic_compare_exchange_strong(&g_gpu_lost, &none, why)) return;
    MLOG("[RED] GPU lost: %s; nothing more is sent to the GPU, every wait on it returns, and the front end saves and quits (fences completed %llu of %llu)", what,
         (unsigned long long)atomic_load(&g_done), (unsigned long long)atomic_load(&g_fence));
    front_gpu_lost();   // first: it only hands the exit to another thread, and a lock below held by a stuck thread must not hold the exit back
    gpu_gone_release();
    if (why == GL_OOM) dispatch_async(res_commit_q(), ^{ res_drop_all(); });   // at once, on the residency commit worker (the caller may be the feedback queue)
}
static struct { uint64_t seen, ticks; int said; double s; uint32_t tick_ms; } g_gpw;   // on the watchdog's queue only
static dispatch_source_t g_gpw_timer;
static void gpw_tick(void) {
    if (atomic_load(&g_gpu_lost)) { dispatch_source_cancel(g_gpw_timer); return; }
    uint64_t n = atomic_load_explicit(&g_fbq_n, memory_order_relaxed);
    if (n != g_gpw.seen || !gpw_waiting()) { g_gpw.seen = n; g_gpw.ticks = 0; if (g_gpw.said == 1) { g_gpw.said = 0; MLOG("GPU stall: work finished again"); } return; }
    double s = (double)++g_gpw.ticks * g_gpw.tick_ms / 1e3, at = g_gpw.s / 2 < 2 ? g_gpw.s / 2 : 2;
    if (!g_gpw.said && s >= at) { g_gpw.said = 1; gpw_report(s, "the stall report"); }
    if (s >= g_gpw.s) {
        g_gpw.said = 2; gpw_report(s, "the GPU taken as lost");
        char what[96]; snprintf(what, sizeof what, "no GPU work finished for %.1f s with work waiting (DM_GPU_LOST_S=%g)", s, g_gpw.s);
        gpu_lost_take(GL_HANG, what);
    }
}
static void gpu_watch_start(void) {
    double v = gpw_seconds();
    if (!v) { MLOG("GPU hang watchdog off (DM_GPU_LOST_S=0)"); return; }
    g_gpw.s = v; g_gpw.tick_ms = GPW_TICK_MS; { double t = v * 1000 / 8; if (t < g_gpw.tick_ms) g_gpw.tick_ms = t < 10 ? 10 : (uint32_t)t; }   // at least 8 ticks to the limit (a test's short one)
    dispatch_queue_t q = dispatch_queue_create("dm.nvn.gpu-watch", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_UTILITY, 0));
    g_gpw_timer = dispatch_source_create(DISPATCH_SOURCE_TYPE_TIMER, 0, 0, q);
    uint64_t ns = (uint64_t)g_gpw.tick_ms * NSEC_PER_MSEC;
    dispatch_source_set_timer(g_gpw_timer, dispatch_time(DISPATCH_TIME_NOW, (int64_t)ns), ns, ns / 4);
    dispatch_source_set_event_handler(g_gpw_timer, ^{ gpw_tick(); });
    dispatch_resume(g_gpw_timer);
    if (getenv("DM_GPU_LOST_S")) MLOG("GPU hang watchdog: the GPU is taken as lost after %g s with work waiting and none finished (DM_GPU_LOST_S)", v);
}
// ---------- The run's first innocent-victim GPU error ----------
// A command buffer discarded as an innocent victim of another's GPU error and the recovery after it (kIOGPUCommandBufferCallbackErrorInnocentVictim) names neither the faulting
// work nor what ran beside it. Fire Emblem Fortune's Weave lost 7 command buffers so in the 2026-11-15 round, at about 1,665 s, as an AV1 movie stopped, about 20 s before the app
// left the screen (an older Fortune's Weave log has the same kind mid-play; Ocarina of Time had one about 1 s before it left the screen). At the run's first such error, from the
// feedback handler that saw it, a line says what the host had in flight: the queues (fences, the main command buffers not reported back, upload batches, the present queue, the
// residency commit worker and a commit in the kernel), the movies (the signal, the decoders and their GPU route, the native images' pools: dm_movie_state, nvn_native_state), the
// GPU probe's window without ending it, the thermal state and Low Power Mode, and the drawn-over render targets' last release (DM_NVN_RT_DEAD, the A/B to pair with). Every read is
// an atomic or a lock only tried (or the probe's leaf lock), as the stall dump's are. Logging only. Returns 1 when it wrote the line
__attribute__((weak)) void dm_movie_state(char *out, size_t n) { snprintf(out, n, "no movie layer in this build"); }   // hle_codec_video.c's
void nvn_native_state(char *out, size_t n);   // hle_nvn.c
static _Atomic int g_victim_said;
static int victim_note(NSError *e, const char *where, uint64_t fence) { @autoreleasepool {
    if (!e || ![e.description containsString:@"InnocentVictim"] || atomic_exchange(&g_victim_said, 1)) return 0;
    uint64_t now = mach_absolute_time(), sub = atomic_load(&g_fence), done = atomic_load(&g_done);
    char fs[48] = ""; if (fence) snprintf(fs, sizeof fs, ", fence %llu", (unsigned long long)fence);
    MLOG("[RED] GPU error: the run's first innocent-victim command buffer (%s%s), discarded in the recovery from another command buffer's error; what the host had in flight follows (logging only)", where, fs);
    char rw[96]; rcw_text(rw, sizeof rw, now); char rk[300] = ""; int stuck = mtl_res_commit_stuck(0, rk, sizeof rk) != 0;
    MLOG("  in flight: fences submitted %llu / completed %llu (%llu behind); main command buffers committed and not reported back %d; upload batches pending %d (one open %d); "
         "present queue enqueued %llu / taken %llu / done %llu, %d on the GPU; residency commit worker %s%s%s",
         (unsigned long long)sub, (unsigned long long)done, (unsigned long long)(sub > done ? sub - done : 0), atomic_load(&g_seg_inflight), atomic_load(&g_up_pending), g_up_cb != nil,
         (unsigned long long)__atomic_load_n(&g_pq_in, __ATOMIC_RELAXED), (unsigned long long)__atomic_load_n(&g_pq_read, __ATOMIC_RELAXED), (unsigned long long)__atomic_load_n(&g_pq_done, __ATOMIC_RELAXED),
         __atomic_load_n(&g_pq_inflight, __ATOMIC_RELAXED), rw, stuck ? "; " : "", stuck ? rk : "");
    char mv[1024], ni[128]; dm_movie_state(mv, sizeof mv); nvn_native_state(ni, sizeof ni);
    MLOG("  movies: %s; %s", mv, ni);
    char gp[200]; int pst = atomic_load_explicit(&g_probe_state, memory_order_acquire);
    if (pst == 2) {
        os_unfair_lock_lock(&g_probe_lk); __typeof__(g_probe) w = g_probe; os_unfair_lock_unlock(&g_probe_lk);   // the window as it stands: the power line still takes it whole
        if (w.n) snprintf(gp, sizeof gp, "this window's fastest %.1f us of %llu (mean %.1f), %.2fx the session's fastest %.1f us%s", w.min / 1e3, (unsigned long long)w.n, w.sum / 1e3 / (double)w.n,
                          w.best ? (double)w.min / (double)w.best : 0, w.best / 1e3, atomic_load(&g_probe_busy) ? "; one in flight" : "");
        else snprintf(gp, sizeof gp, "no probe in this window yet, the session's fastest %.1f us%s", w.best / 1e3, atomic_load(&g_probe_busy) ? "; one in flight" : "");
    } else snprintf(gp, sizeof gp, "%s", pst == -2 ? "off" : pst == -1 ? "refused" : "not made yet");
    int th = dm_thermal_now(); if (th < 0) th = (int)NSProcessInfo.processInfo.thermalState;   // the Mac's from the process info, as the front ends read it on iOS
    static const char *const thn[] = {"nominal", "fair", "serious", "critical"};
    uint64_t rn = atomic_load_explicit(&g_tu_rel_n, memory_order_relaxed), rt = atomic_load_explicit(&g_tu_rel_ns, memory_order_relaxed), tn = now_ns();
    char rel[120]; if (rt) snprintf(rel, sizeof rel, "%llu released in all, the last %.2f s before", (unsigned long long)rn, tn > rt ? (tn - rt) / 1e9 : 0.0); else snprintf(rel, sizeof rel, "none released");
    MLOG("  GPU probe: %s; thermal state %s, Low Power Mode %s; render targets drawn over (DM_NVN_RT_DEAD%s): %s; presents %llu", gp, th >= 0 && th <= 3 ? thn[th] : "unknown",
         NSProcessInfo.processInfo.isLowPowerModeEnabled ? "on" : "off", tu_mode() ? "" : "=0", rel, (unsigned long long)__atomic_load_n(&g_present_n, __ATOMIC_RELAXED));
    return 1;
} }
uint64_t mtl_alloc_shares(void) { return g_alloc_shares; }   // main submissions that began in the allocator of the one before them
void mtl_alloc_stats(uint64_t *waits, uint64_t *grown, int *n) { *waits = g_alloc_waits; *grown = g_alloc_grown; *n = g_alloc_n; }   // Main submit allocator pool: how many times it waited, how many times it grew, how many exist now
// Memory census for restop (diagnostic): residency-set textures by Metal format; which of them anything still names (serial tables, sharing table, descriptor views) and which only the
// deferred-release queue or nothing holds; and game textures at one storage address held as several Metal textures. Under no lock of the caller's
static char census_flags_key;
static id<MTLTexture> census_base(id in) { id o = [in isKindOfClass:[NvPkg class]] ? ((NvPkg *)in)->tex : in; if (![o conformsToProtocol:@protocol(MTLTexture)]) return nil; id<MTLTexture> t = o; return t.parentTexture ? t.parentTexture : t; }
void mem_census(const char *why) { @autoreleasepool {
    NSHashTable *named = [NSHashTable hashTableWithOptions:NSPointerFunctionsOpaqueMemory | NSPointerFunctionsOpaquePersonality];
    NSHashTable *named_ret = [NSHashTable hashTableWithOptions:NSPointerFunctionsOpaqueMemory | NSPointerFunctionsOpaquePersonality];   // named only through retired descriptors (until a live one names it)
    // The textures met, retained: the tables here hold bare pointers, and a texture they name can be freed while the census runs on its own thread (a load's census read the size
    // of one freed meanwhile and crashed in objc_msgSend, upstream NXNative 8b830abb1). Each is retained under the lock that names it, and kept until the census returns, so every
    // texture it reads stays valid
    NSMutableSet *keep = [NSMutableSet set];
    #define CN_ADD(o) do { id<MTLTexture> b_ = census_base(o); if (b_) { [named addObject:(__bridge id)(__bridge void *)b_]; [keep addObject:b_]; } } while (0)
    smu_lock();
    const nvn_hmap *maps[] = {&g_by_serial, &g_ghost, &g_alias};
    for (unsigned m = 0; m < sizeof maps / sizeof maps[0]; m++) for (uint32_t i = 0; i < maps[m]->cap; i++) if (maps[m]->vals[i]) { id o = (__bridge id)maps[m]->vals[i]; CN_ADD(o); if ([o isKindOfClass:[NvPkg class]] && ((NvPkg *)o)->spare) CN_ADD(((NvPkg *)o)->spare); }
    pthread_mutex_unlock(&g_smu);
    // registered descriptors: their views' bases, and per storage address the distinct bases
    NSMapTable *by_mem = [NSMapTable mapTableWithKeyOptions:NSPointerFunctionsOpaqueMemory | NSPointerFunctionsOpaquePersonality valueOptions:NSPointerFunctionsStrongMemory];
    NSMapTable *by_flags = [NSMapTable mapTableWithKeyOptions:NSPointerFunctionsOpaqueMemory | NSPointerFunctionsOpaquePersonality valueOptions:NSPointerFunctionsStrongMemory];   // texture flags | pool flags << 32
    rmu_lock();
    uint64_t nreg = 0, nretired = 0;
    for (int i = 1; i < g_ntreg; i++) { treg_t *r = &g_treg[i]; if (!r->ok) continue; nreg++; nretired += r->retired;
        void *vs[4] = {r->view, r->alt, r->im, r->alt2};
        for (int k = 0; k < 4; k++) if (vs[k]) { id<MTLTexture> b = census_base((__bridge id)vs[k]); if (!b) continue; [r->retired ? named_ret : named addObject:(__bridge id)(__bridge void *)b]; [keep addObject:b];
            if (k == 0 && r->t.mem) { const void *key = r->t.mem; NSHashTable *set = [by_mem objectForKey:(__bridge id)key];
                if (!set) { set = [NSHashTable hashTableWithOptions:NSPointerFunctionsOpaqueMemory | NSPointerFunctionsOpaquePersonality]; [by_mem setObject:set forKey:(__bridge id)key]; }
                [set addObject:(__bridge id)(__bridge void *)b];
                if (![by_flags objectForKey:(__bridge id)key]) [by_flags setObject:@(((uint64_t)(r->t.pool && r->t.pool->magic == MAGIC('P', 'O', 'O', 'L') ? r->t.pool->flags : 0) << 32) | r->t.d.flags) forKey:(__bridge id)key]; } } }
    os_unfair_lock_unlock(&g_rmu);
    NSHashTable *waiting = [NSHashTable hashTableWithOptions:NSPointerFunctionsOpaqueMemory | NSPointerFunctionsOpaquePersonality];
    pthread_mutex_lock(&g_deferred_mu); for (NvDeferredRelease *d in g_deferred) { id<MTLTexture> b = census_base(d->object); if (b) { [waiting addObject:(__bridge id)(__bridge void *)b]; [keep addObject:b]; } } pthread_mutex_unlock(&g_deferred_mu);
    uint64_t small_n[2][2] = {{0}}, small_b[2][2] = {{0}};   // [texture][shared storage]: residency objects of 64 KB or less
    uint64_t n_ret = 0, b_ret = 0, n_named = 0, b_named = 0, n_wait = 0, b_wait = 0, n_none = 0, b_none = 0, n_buf = 0, b_buf = 0;
    enum { NF = 24 }; struct { unsigned long pf; uint64_t n, b; } fm[NF] = {{0}}; int nfm = 0;
    res_mu_lock();
    for (id<MTLAllocation> o in g_res_objects.allObjects) { uint64_t z = o.allocatedSize;
        if (z <= 65536) { int tx = [(id)o conformsToProtocol:@protocol(MTLTexture)], sh = ((id<MTLResource>)o).storageMode == MTLStorageModeShared; small_n[tx][sh]++; small_b[tx][sh] += z; }
        if (![(id)o conformsToProtocol:@protocol(MTLTexture)]) { n_buf++; b_buf += z; continue; }
        id<MTLTexture> t = (id)o; if (t.parentTexture) continue;
        unsigned long pf = (unsigned long)t.pixelFormat; int i = 0; while (i < nfm && fm[i].pf != pf) i++; if (i == nfm && nfm < NF) fm[nfm++].pf = pf; if (i < NF) { fm[i].n++; fm[i].b += z; }
        if ([named containsObject:(__bridge id)(__bridge void *)t]) { n_named++; b_named += z; }
        else if ([named_ret containsObject:(__bridge id)(__bridge void *)t]) { n_ret++; b_ret += z; }
        else if ([waiting containsObject:(__bridge id)(__bridge void *)t]) { n_wait++; b_wait += z; }
        else { n_none++; b_none += z; } }
    res_mu_unlock();
    uint64_t dup_addr = 0, dup_tex = 0, dup_b = 0;
    for (id key in by_mem) { NSHashTable *set = [by_mem objectForKey:key]; if (set.count < 2) continue; dup_addr++;
        uint64_t biggest = 0, sum = 0; for (id b in set) { uint64_t z = ((id<MTLTexture>)b).allocatedSize; sum += z; if (z > biggest) biggest = z; } dup_tex += set.count - 1; dup_b += sum - biggest; }
    {   // the largest groups: each Metal texture over one storage address, so a reader can tell views made as copies from different images that reuse the memory
        NSMutableArray *groups = [NSMutableArray array];
        for (id key in by_mem) { NSHashTable *set = [by_mem objectForKey:key]; if (set.count >= 2) { [groups addObject:set]; objc_setAssociatedObject(set, &census_flags_key, [by_flags objectForKey:key], OBJC_ASSOCIATION_RETAIN_NONATOMIC); } }
        [groups sortUsingComparator:^NSComparisonResult(NSHashTable *x, NSHashTable *y) {
            uint64_t a_ = 0, b_ = 0; for (id t in x) a_ += ((id<MTLTexture>)t).allocatedSize; for (id t in y) b_ += ((id<MTLTexture>)t).allocatedSize;
            return a_ > b_ ? NSOrderedAscending : a_ < b_ ? NSOrderedDescending : NSOrderedSame; }];
        for (NSUInteger g = 0; g < groups.count && g < 8; g++) {
            char gl[700]; size_t go = 0;
            for (id<MTLTexture> t in groups[g]) if (go < sizeof gl) go += snprintf(gl + go, sizeof gl - go, "%s[fmt %lu %lux%lux%lu type %lu mips %lu slices %lu usage %#lx %lu KB]", go ? " " : "",
                (unsigned long)t.pixelFormat, (unsigned long)t.width, (unsigned long)t.height, (unsigned long)t.depth, (unsigned long)t.textureType, (unsigned long)t.mipmapLevelCount,
                (unsigned long)t.arrayLength, (unsigned long)t.usage, (unsigned long)(t.allocatedSize >> 10));
            uint64_t fl = [objc_getAssociatedObject(groups[g], &census_flags_key) unsignedLongLongValue];
            MLOG("%s census: shared storage group %lu (%lu textures, texture flags %#llx, pool flags %#llx): %s", why, (unsigned long)g, (unsigned long)((NSHashTable *)groups[g]).count, fl & 0xffffffffull, fl >> 32, gl);
        }
    }
    for (int i = 0; i < nfm; i++) for (int j = i + 1; j < nfm; j++) if (fm[j].b > fm[i].b) { __typeof__(fm[0]) x = fm[i]; fm[i] = fm[j]; fm[j] = x; }
    char line[900] = "none"; size_t o = 0; for (int i = 0; i < nfm && i < 12 && o < sizeof line; i++) o += snprintf(line + o, sizeof line - o, "%s%lu: %llu, %llu MB", i ? "; " : "", fm[i].pf, (unsigned long long)fm[i].n, (unsigned long long)(fm[i].b >> 20));   // none: no texture of the set has an allocation of its own
    MLOG("%s census: textures named by serials, sharing or live descriptors' views %llu, %llu MB; only by retired descriptors' views %llu, %llu MB; only in the deferred-release queue %llu, %llu MB; named by nothing %llu, %llu MB; buffers %llu, %llu MB; descriptors %llu (%llu retired); storage addresses with several Metal textures %llu (%llu extra textures, %llu MB)",
         why, (unsigned long long)n_named, (unsigned long long)(b_named >> 20), (unsigned long long)n_ret, (unsigned long long)(b_ret >> 20), (unsigned long long)n_wait, (unsigned long long)(b_wait >> 20), (unsigned long long)n_none, (unsigned long long)(b_none >> 20),
         (unsigned long long)n_buf, (unsigned long long)(b_buf >> 20), (unsigned long long)nreg, (unsigned long long)nretired, (unsigned long long)dup_addr, (unsigned long long)dup_tex, (unsigned long long)(dup_b >> 20));
    MLOG("%s census: textures by Metal format: %s", why, line);
    MLOG("%s census: residency objects of 64 KB or less: buffers shared %llu (%llu KB), private %llu (%llu KB); textures shared %llu (%llu KB), private %llu (%llu KB)", why,
         (unsigned long long)small_n[0][1], (unsigned long long)(small_b[0][1] >> 10), (unsigned long long)small_n[0][0], (unsigned long long)(small_b[0][0] >> 10),
         (unsigned long long)small_n[1][1], (unsigned long long)(small_b[1][1] >> 10), (unsigned long long)small_n[1][0], (unsigned long long)(small_b[1][0] >> 10));
    { char cls[600]; pool_res_classes(cls, sizeof cls); MLOG("%s census: %s", why, cls); }   // the resident pools by who read them (an upload's lookup is never cached, so the split is exact)
    #undef CN_ADD
} }
